INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10036, 'MIR 2025, P36c', 'Otros', 'Mujer de 67 años diagnosticada de cirrosis hepática, con antecedentes de descompensaciones ascíticas en tratamiento con espironolactona y furosemida. Su familia la trae a urgencias por alteración del nivel de conciencia. La paciente se encuentra ligeramente desorientada en tiempo y espacio y somnolienta. Tiene asterixis franca. ¿Cuál de las siguientes medidas NO se encuentra indicada a su ingreso?:', NULL, 2025, NULL, true, 'MEDIO', 'BORRADOR', 43, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:01:48.892431+00');
