INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9477, 'MIR 2017-18, P34', '2. Cuello', 'Pregunta vinculada a la imagen nº 34 De las siguientes estructuras óseas señale la apófisis odontoides:', 'imagenes/ANATOMIA_ordenadas_por_temas_(hasta_2025)/2._Cuello/MIR_2017-18,_P34_p13_1.png | imagenes/ANATOMIA_ordenadas_por_temas_(hasta_2025)/2._Cuello/MIR_2017-18,_P34_p13_2.png', 2018, NULL, false, 'FACIL', 'PUBLICADA', 48, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10240, 'MIR 2023-24, P180', '1: General', 'Mujer de 45 años con antecedentes de colitis ulcerosa, que consulta por fiebre diaria de hasta 40oC acompañada de escalofríos, astenia, anorexia y cefalea intensa. En la exploración está febril, normotensa, a 90 lpm y destaca hepatoesplenomegalia blanda. En la analítica destaca bicitopenia (leucocitos 2650 [73 N, 19 L, 3M], Hb 9,7, Hcto 28,6 %, VCM 95, CHCM 34), hipofibrinogenemia, ALT 88 UI/L (N hasta 37), AST 126 UI/L (N hasta 32), LDH 431 UI/L (N hasta 190), ferritina 936 μg/L (N 15 a 120), hipergammaglobulinemia (gamma: 27 %) y proteína C reactiva 78 mg/L (N hasta 8). Estudio serológico: IgM anti-ACV (antígeno de la cápside del virus de Epstein-Barr) positivo, IgG anti-ACV positivo. Médula ósea: disminución de la eritropoyesis y granulocitopoyesis con hiperplasia de histiocitos con intensa hemofagocitosis y cultivo negativo. ¿Cuál es la respuesta INCORRECTA sobre la enfermedad que sufre esta paciente?:', NULL, 2024, NULL, true, 'MEDIO', 'BORRADOR', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:01:48.892431+00');
