INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10692, 'MIR 2017-18, P178', '7. Cardiopatía isquémica', 'Se presenta en la consulta de valoración preanestésica un hombre portador de un stent fármaco activo implantado hace dos meses, en tratamiento con ácido acetilsalicílico (AAS) 300 mg/d y clopidogrel 75mg/d y que debe someterse a una cirugía programada y extracción dentaria múltiple. Señale la mejor recomendación para mantener el equilibrio entre el riesgo trombótico y el riesgo hemorrágico de la cirugía propuesta:', NULL, 2018, NULL, true, 'MEDIO', 'BORRADOR', 31, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:01:49.501461+00');
