INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13070, 'MIR 2011, P224', '21. Otros temas', 'Conociendo la función de las estructuras relacionadas con la percepción del dolor y asumiendo que la estimulación eléctrica puede bloquear la transmisión del dolor, ¿qué estructura no debería ser estimulada eléctricamente para el tratamiento del dolor?', NULL, 2011, NULL, false, 'MEDIO', 'PUBLICADA', 47, 2, '2026-05-06 09:01:52.652946+00', '2026-05-06 09:11:50.77389+00');
