INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12949, 'MIR 2022, P177', '11. Miopatías y enfermedades de la placa motora', 'Varón de 45 años, no fumador y no consume alcohol, que consulta por disnea progresiva de dos meses de evolución. Exploración física: afebril, frecuencia respiratoria 19 rpm, frecuencia cardiaca 120 lpm, SatO2 93 %. Lesiones cutáneas de aspecto ulceroso en palmas y dedos de las manos, estertores crepitantes en ambas bases pulmonares, fuerza muscular normal. Análisis: CK 300 UI/L (N: <150) y aldolasa 12 UI/L (N: <6). Radiografía de tórax: patrón intersticial bibasal. Una biopsia muscular evidenció necrosis de células musculares, atrofia perifascicular e infiltrados inflamatorios perivasculares. ¿Cuál de los siguientes es el diagnóstico más probable?:', NULL, 2022, NULL, false, 'MEDIO', 'PUBLICADA', 47, 2, '2026-05-06 09:01:52.652946+00', '2026-05-06 09:11:50.77389+00');
