INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9542, 'MIR 1995-96, P1003', '5. Miembro superior', 'F, P 99. El nervio mediano a nivel de la mano inerva a los músculos siguientes a EXCEPCION de:', NULL, 1996, NULL, false, 'FACIL', 'PUBLICADA', 48, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
