INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9551, 'MIR 2010-11, P220', '6. Miembro inferior', 'La torsión del pie en posición de supinación y estando sobre una superficie irregular es una de las lesiones deportivas más frecuentes, en esta torsión suele producirse un sobreestiramiento o ruptura de alguno de los ligamentos de la articulación del tobillo. De los ligamentos citados a continuación uno de ellos es el lesionado con más frecuencia ¿Cuál es?', NULL, 2011, NULL, false, 'MEDIO', 'PUBLICADA', 48, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
