INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9576, 'MIR 2004, P176', '2. Gestión clínica. Medicina basada en la evidencia (MBE)', 'Una determinada enfermedad es relativamente infrecuente y sólo se hace incurable varios años después de poder diagnosticarse por los medios clínicos habituales. Señale cuál de los siguientes tipos de recursos sanitarios serán los más útiles para su manejo adecuado:', NULL, 2004, NULL, false, 'DIFICIL', 'PUBLICADA', 43, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
