INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9915, 'MIR 2006, P72', '11. Diabetes', 'Con respecto la neuropatía diabética, una de estas afirmaciones es FALSA:', NULL, 2006, NULL, false, 'FACIL', 'PUBLICADA', 43, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9916, 'MIR 2006, P71', '11. Diabetes', '¿Cuál es la definición de intolerancia glucídica o tolerancia a la glucosa alterada?:', NULL, 2006, NULL, false, 'FACIL', 'PUBLICADA', 43, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
