INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (9918, 'MIR 2005, P73', '11. Diabetes', 'Varón de 70 años que acude al Hospital de Día de Endocrinología tras hallazgo en analítica de control de una glucemia de 456. El paciente refiere polidipsia y poliuria así como pérdida de 15 kg de peso en los últimos 3 meses. Presenta un IMC de 22 Kg/m 2. La actitud inicial que deberíamos tomar es:', NULL, 2005, NULL, false, 'MEDIO', 'PUBLICADA', 43, 2, '2026-05-06 09:01:48.266504+00', '2026-05-06 09:11:36.200908+00');
