INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10166, 'MIR 2011-12, P96', '1: General', 'La mutación del gen JAK-2 constituye uno de los criterios mayores de diagnóstico en una de estas patologías:', NULL, 2012, NULL, false, 'DIFICIL', 'PUBLICADA', 52, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
