INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10197, 'MIR 2006-07, P231', '1: General', 'Las micromatrices o “microarrays” de DNA son unas nuevas plataformas tecnológicas basadas en la información generada por la secuenciación masiva del genoma humano. Una de las siguientes afirmaciones es cierta en relación a la aplicación de esta tecnología en oncología:', NULL, 2007, NULL, false, 'MEDIO', 'PUBLICADA', 52, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
