INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10322, 'MIR 2016-17, P89', '1: General', 'Hombre de 60 años que sufrió un infarto de miocardio hace 1 año. Se lo remiten para valorar su tratamiento. Está tomando gemfibrozilo 900 mg, lisinopril 20 mg, aspirina 100 mg y carvedilol 25 mg. En sus análisis tiene cLDL 162 mg/dL, cHDL 46 mg/dL, triglicéridos 132 mg/dL, colesterol total 220 mg/dL. ¿Qué actitud terapéutica le parece más razonable?', NULL, 2017, NULL, false, 'MEDIO', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10323, 'MIR 2016-17, P92', '1: General', '¿Cuál de las siguientes se considera enfermedad por depósito lisosomal?', NULL, 2017, NULL, false, 'DIFICIL', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
