INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10399, 'MIR 2007-08, P248', '1: General', 'Los remanentes de quilomicrón son retirados de la circulación por el hígado mediante un proceso que requiere la siguiente apoproteína:', NULL, 2008, NULL, false, 'FACIL', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
