INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10402, 'MIR 2006-07, P71', '1: General', '¿Cuál es la definición de intolerancia glucídica o tolerancia a la glucosa alterada?:', NULL, 2007, NULL, false, 'FACIL', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10403, 'MIR 2006-07, P73', '1: General', 'Hombre de 50 años que consulta por presentar lesiones ampollosas y erosiones tras exposición solar. Señala que la orina, ocasionalmente, adquiere una tonalidad oscura. El laboratorio nos informa de la existencia de un discreto aumento de transaminasas, siendo la excreción urinaria de uroporfirina superior a 200 ug/l. Ante este cuadro el diagnóstico y tratamiento correcto es:', NULL, 2007, NULL, false, 'MEDIO', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10404, 'MIR 2006-07, P75', '1: General', 'Está indicado conseguir un objetivo de LDL colesterol < 100 mg/dl en todas la siguientes situaciones MENOS una:', NULL, 2007, NULL, false, 'MEDIO', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10405, 'MIR 2006-07, P76', '1: General', 'Actualmente el diagnóstico de hipercolesterolemia familiar se basa en las características clínicas del paciente. Son criterios de certeza:', NULL, 2007, NULL, false, 'MEDIO', 'PUBLICADA', 49, 2, '2026-05-06 09:01:48.892431+00', '2026-05-06 09:11:37.858978+00');
