INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10788, 'MIR 2012-13, P85b', '9. Semiología cardiaca', 'Si en un paciente con insuficiencia cardiaca crónica detectamos unas ondas v prominentes en el pulso venoso yugular y en la auscultación cardiaca se ausculta un soplo holosistólico en el área del apéndice xifoides que se acentúa con la inspiración profunda. ¿Cuál es la valvulopatía responsable de esta exploración física?', NULL, 2013, NULL, false, 'MEDIO', 'PUBLICADA', 31, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:11:39.655189+00');
