INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10791, 'MIR 2007-08, P23', '9. Semiología cardiaca', '¿En cuál de las siguientes situaciones clínicas, el pulso paradójico (disminución de la presión arterial de más de 10 mmHg durante la inspiración), no está presente en la exploración física?:', NULL, 2008, NULL, false, 'FACIL', 'PUBLICADA', 31, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:11:39.655189+00');
