INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10794, 'MIR 2004-05, P23', '9. Semiología cardiaca', 'La auscultación del corazón requiere un estetoscopio con campana y membrana. Señale la respuesta verdadera:', NULL, 2005, NULL, false, 'FACIL', 'PUBLICADA', 31, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:11:39.655189+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10796, 'MIR 2002-03, P99b', '9. Semiología cardiaca', 'El examen del pulso carotídeo revela dos impulsos o picos durante la sístole ventricular. ¿Cuál de los datos físicos siguientes se asociarían con más probabilidad a este hallazgo?', NULL, 2003, NULL, false, 'FACIL', 'PUBLICADA', 31, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:11:39.655189+00');
