INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (10860, 'MIR 2024-25, P51', 'Terapéutica quirúrgica', '¿Cuál de los siguientes escenarios podría suponer una contraindicación para el uso de un injerto de piel parcial como cobertura de un defecto cutáneo?:', NULL, 2025, NULL, false, 'MEDIO', 'PUBLICADA', 32, 2, '2026-05-06 09:01:49.501461+00', '2026-05-06 09:11:39.655189+00');
