INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11523, 'MIR 2007-08, P223', '11. Fármacos antidepresivos', '¿Cuál de los siguientes fármacos debe de utilizarse con precaución en un paciente tratado con un inhibidor selectivo de recaptación de serotonina por el riesgo de provocar un cuadro de hiperactividad serotoninérgica?', NULL, 2008, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
