INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11529, 'MIR 1999-2000, P1007', '11. Fármacos antidepresivos', 'F, P166. Si un paciente es tratado de un cuadro depresivo leve por su médico de Atención Primaria con inhibidores selectivos de la recaptación de serotonina (ISRS) a dosis terapéuticas (por ejemplo: 20 mg de fluoxetina) y a la semana de iniciar el tratamiento no obtiene la respuesta terapéutica deseada, ¿qué deberá hacer?:', NULL, 2000, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11530, 'MIR 1998-99, P238', '11. Fármacos antidepresivos', 'Paciente de 30 años con tratamiento por problemas psiquiátricos. Durante este período relata que aumenta de peso, está siempre sediento y orina con frecuencia. ¿Cuál de los siguientes fármacos hay que suponer es el responsable de estas reacciones adversas?:', NULL, 1999, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
