INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11716, 'MIR 2004-05, P71', '27. Farmacología del metabolismo glucídico', '¿Cuál de las siguientes asociaciones de fármacos antidiabéticos orales actúa fundamentalmente mejorando la sensibilidad a la insulina?:', NULL, 2005, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11717, 'MIR 2003-04, P41', '27. Farmacología del metabolismo glucídico', 'La Metformina es un fármaco muy útil en el tratamiento de la Diabetes Mellitus. Si Ud. lo utiliza debe conocer cuál de las siguientes afirmaciones NO es cierta:', NULL, 2004, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11718, 'MIR 2002-03, P125', '27. Farmacología del metabolismo glucídico', '¿Con qué objetivo prescribiría una Tiazolidinadiona (glitazona) a un paciente con diabetes mellitus?:', NULL, 2003, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
