INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11720, 'MIR 2020-21, P116', '28. Farmacología del metabolismo del calcio', 'Entre los siguientes fármacos para el tratamiento de la osteoporosis, ¿cuál de ellos NO causa osteonecrosis mandibular o fractura atípica de fémur como efecto adverso?:', NULL, 2021, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
