INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11722, 'MIR 2011-12, P165', '28. Farmacología del metabolismo del calcio', 'La necrosis de los maxilares está relacionada con la administración de:', NULL, 2012, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11723, 'MIR 2018-19, P213', '29. Fármacos antienoplásicos', 'Una paciente de 32 años acude a su consulta tras ser intervenida de un cáncer de mama derecho mediante cirugía conservadora. El informe de anatomía patológica informa de carcinoma ductal infiltrante moderadamente diferenciado de 2 cm con afectación de 8 de 12 ganglios aislados. Receptores de estrógenos y progesterona positivos. Her-2 negativo. El tratamiento adyuvante indicado incluiría todas las opciones EXCEPTO:', NULL, 2019, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11724, 'MIR 2018-19, P042', '29. Fármacos antienoplásicos', 'Las siguientes asociaciones de fármaco y reacción tipo A (consecuencia del efecto farmacológico) son ciertas EXCEPTO:', NULL, 2019, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11725, 'MIR 2012-13, P213', '30. Fármacos inmunosupresores', 'En el caso de un trasplante de órganos sólidos, si queremos inhibir la enzima calcineurina en las células del paciente trasplantado, ¿qué inmunodepresor deberíamos utilizar?', NULL, 2013, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11726, 'MIR 2000-01, P1014', '30. Fármacos inmunosupresores', 'F, P221: ¿Cuál de los siguientes fármacos inmunosupresores utilizados en el trasplante renal para prevenir el rechazo es nefrotóxico?:', NULL, 2001, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11727, 'MIR 2022-23, P164', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Varón de 80 años procedente de una residencia que presenta una sepsis de origen urinario que no ha respondido al tratamiento empírico con ceftriaxona. En los hemocultivos y urocultivos crece E. coli resistente a cefalosporinas. El laboratorio nos informa que es una cepa productora de betalactamasas de espectro extendido. ¿Qué antibiótico, entre los siguientes, debe utilizarse?:', NULL, 2023, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11728, 'MIR 2020-21, P153', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Paciente diagnosticado de diverticulitis aguda, tratado con amoxicilina/clavulánico. Al cabo de 5 días comienza con fiebre y diarrea. Se le diagnostica de colitis por Clostridium difficile, se suspende la amoxicilina/clavulánico y se pauta metronidazol. A los 4 días no ha respondido al metronidazol, pero se encuentra clínicamente estable. El siguiente paso del tratamiento es:', NULL, 2021, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11729, 'MIR 2018-19, P61', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Paciente oncológico portador de una sonda vesical con sospecha de una infección urinaria complicada que recibe tratamiento empírico con cefotaxima i.v. El laboratorio de microbiología informa del crecimiento en los hemocultivos de Pseudomonas aeruginosa, pendiente de antibiograma. Con esta información preliminar, ¿qué afirmación de las siguientes es CORRECTA?', NULL, 2019, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11730, 'MIR 2017-18, P117', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Hombre de 85 años portador de catéter venoso periférico que, una semana después de estar hospitalizado por un ictus, comienza con tiritona y fiebre. Se realizan hemocultivos y desde microbiología se informa que están creciendo cocos gram positivos en racimos. En espera del antibiograma, ¿cuál es el tratamiento antibiótico más adecuado?', NULL, 2018, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11731, 'MIR 2017-18, P44', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Los beta-lactámicos son el grupo más numeroso de antibióticos. Uno de los aspectos NEGATIVOS de este grupo de antibióticos es:', NULL, 2018, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11732, 'MIR 2016-17, P53', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Paciente de 80 años procedente de una residencia de ancianos. Presenta sepsis de origen urinario que no responde al tratamiento empírico con ceftriaxona. En los hemocultivos y urocultivos crece E. Coli resistente a cefalosporinas. El laboratorio nos informa que es una cepa productora de betalactamasas de espectro amplio. ¿Qué antibiótico entre los siguientes, debe utilizarse?', NULL, 2017, NULL, false, 'DIFICIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11733, 'MIR 2012-13, P225', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', '¿Cuál de las siguientes afirmaciones es FALSA respecto a los antibióticos betalactámicos?', NULL, 2013, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
