INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11737, 'MIR 2005-06, P223', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', '¿Cuál de los siguientes antibióticos antibacterianos no actúa inhibiendo la síntesis de la pared bacteriana celular?:', NULL, 2006, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11738, 'MIR 2004-05, P229', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', 'Paciente politraumatizado ingresado en UCI. En un absceso cutáneo y en tres muestras de hemocultivo se aísla una cepa de Staphylococcus Aureus resistente a meticilina. Señale el tratamiento antimicrobiano de elección:', NULL, 2005, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11739, 'MIR 2001-02, P231', '31. Antibióticos beta-lactámicos. Otros inhibidores de la síntesis de la pared bacteriana', '¿Cuál de los siguientes antimicrobianos utilizaría en primer lugar en monoterapia, para tratar una infección grave por Staphylococcus Aureus resistente a meticilina?:', NULL, 2002, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
