INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11747, 'MIR 2018-19, P41', '32. Antibióticos aminoglucósidos. Daptomicina', 'Hombre de 65 años con cardiopatía isquémica y estenosis aórtica reumática, por lo que recibe betabloqueantes, antiagregantes y estatinas, que comienza con un cuadro de fiebre y modificación de las cualidades del soplo aórtico, por lo que se sospecha endocarditis. Se extraen hemocultivos en los que crece Staphylococcus aureus meticilin resistente, por lo que recibe tratamiento antibiótico. En una analítica de control se constata importante elevación de CPK. ¿Cuál cree que es el antibiótico con el que se ha tratado?', NULL, 2019, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11748, 'MIR 2016-17, P57', '32. Antibióticos aminoglucósidos. Daptomicina', 'De la siguiente lista de antimicrobianos, ¿cuál NO elegiría como tratamiento secuencial en un paciente al que va a dar de alta a su domicilio?', NULL, 2017, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11749, 'MIR 2016-17, P106', '32. Antibióticos aminoglucósidos. Daptomicina', '¿Cuál es el antimicrobiano más activo en la endocarditis y bacteriemia por Staphylococcus aureus resistente a oxacilina?', NULL, 2017, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
