INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11788, 'MIR 2007-08, P127', '36. Antituberculosos', 'Entre los principios básicos del tratamiento de la tuberculosis NO se encuentra uno de los siguientes:', NULL, 2008, NULL, false, 'FACIL', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11789, 'MIR 1996-97, P15', '36. Antituberculosos', 'Un paciente de 31 años con infección por virus de la inmunodeficiencia humana (VIH) ha sido diagnosticado por cultivo de tuberculosis ganglionar. La respuesta inicial al tratamiento con Rifampicina, Isoniacida, Etambutol y Pirazinamida es satisfactoria, pero a los 19 días presenta fiebre alta, rash y síntomas pseudogripales. ¿Cuál es el responsable más probable de este cuadro?', NULL, 1997, NULL, false, 'MEDIO', 'PUBLICADA', 51, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
