INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (11851, 'MIR 2004-05, P78b', '3. Fisiología médica metabólica', '¿Qué consejo le parece MENOS adecuado para un hombre de 20 años con colesterol total de 320mg/dl y triglicéridos de 110 mg/dl?:', NULL, 2005, NULL, false, 'MEDIO', 'PUBLICADA', 50, 2, '2026-05-06 09:01:50.763184+00', '2026-05-06 09:11:43.741549+00');
