INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12466, 'MIR 2020, P35', 'Tema 6: Propiedades biológicas y funciones de las inmunoglobulinas.', 'Los receptores para los fragmentos Fc de las diferentes clases de inmunoglobulinas (Ig) se pueden expresar en distintos tipos de células que llevan a cabo funciones efectoras. Indique cuál de las siguientes afirmaciones es FALSA:', NULL, 2020, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
