INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12469, 'MIR 2016, P49', 'Tema 6: Propiedades biológicas y funciones de las inmunoglobulinas.', 'Las opsoninas son moléculas capaces de reconocer estructuras de la superficie de los microorganismos y de este modo facilitan:', NULL, 2016, NULL, false, 'DIFICIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
