INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12474, 'MIR 2005, P242', 'Tema 6: Propiedades biológicas y funciones de las inmunoglobulinas.', 'Los anticuerpos que desaparecen pocos meses después de la infección permiten detectar una enfermedad actual o muy reciente. Este tipo de anticuerpos pertenece a la clase:', NULL, 2005, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
