INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12485, 'MIR 2012, P213', 'Tema 14. Activación de las células T.', 'En el caso de un trasplante de órganos sólidos, si queremos inhibir la enzima calcineurina en las células del paciente trasplantado, ¿qué inmunosupresor deberíamos utilizar?:', NULL, 2012, NULL, false, 'DIFICIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
