INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12489, 'MIR 2009, P215', 'Tema 15. Activación de las células B.', 'El sistema inmune sirve para luchar contra elementos extraños al organismo, para lo cual, utiliza distintos mecanismos. Señale cuál de los siguientes es el usado para procesar y eliminar antígenos extraños:', NULL, 2009, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
