INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12492, 'MIR 2021, P34', 'Tema 16: Mecanismos de inmunosupresión. Generación de tolerancia periférica.', 'En la inmunoterapia antitumoral basada en el uso de anticuerpos monoclonales contra puntos de control inmunológico (checkpoints) destaca el uso de los anticuerpos monoclonales que bloquean la interacción entre PD-1 y sus ligandos. ¿Cuál de las siguientes afirmaciones es cierta?:', NULL, 2021, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12493, 'MIR 2021, P37', 'Tema 16: Mecanismos de inmunosupresión. Generación de tolerancia periférica.', 'Respecto a las células T reguladoras (Treg) es cierto que:', NULL, 2021, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12494, 'MIR 2025, P143', 'Temas 17 Y 18: El sistema del complemento. Cascada de activación. Regulación del complemento. Funciones.', 'Un paciente de 39 años que presenta emisión recidivante de orina rojiza, episodios repetidos de dolor abdominal de etiología no diagnosticada, acude a urgencias con un nuevo episodio de dolor abdominal intenso. En los estudios realizados en urgencias se objetiva una trombosis venosa mesentérica. ¿Cuál es el diagnóstico de sospecha que considera más probable?:', NULL, 2025, NULL, false, 'MEDIO', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
