INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12496, 'MIR 2019, P46b', 'Tema 19 y 20: La respuesta inflamatoria. Inflamación aguda y crónica. Mecanismos de extravasación. Mediadores de la Inflamación', 'En el tratamiento de la enfermedad inflamatoria intestinal pueden utilizarse anticuerpos monoclonales humanizados dirigidos frente al TNF-alfa (como el adalimumab) o frente a la integrina a4ß7 (como el vedolizumab). En relación con la integrina a4ß7 (también llamada LPAM1) es cierto que:', NULL, 2019, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
