INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12520, 'MIR 2025, P151', 'Tema 25: Autoinmunidad', 'Paciente con 23 años, quiere saber si es celíaco, porque su madre lo es. Pregunta sobre el estudio genético. Respecto al papel del estudio genético HLA-DQ2/DQ8 en enfermedad celíaca, señale la opción CORRECTA:', NULL, 2025, NULL, false, 'FACIL', 'PUBLICADA', 34, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
