INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12745, 'MIR 2013, P125', '10. Enfermedad renal crónica.', 'Respecto a la definición de la enfermedad renal crónica, una es INCORRECTA:', NULL, 2013, NULL, false, 'FACIL', 'PUBLICADA', 36, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12746, 'MIR 2012, P120', '10. Enfermedad renal crónica.', 'Un paciente con insuficiencia renal crónica estadio IV (filtrado glomerular renal 25 ml/min) presenta una hemoglobina de 8.6 g/dL. El estudio de anemia muestra un volumen corpuscular medio de 78 fl y los niveles de ferritina en sangre son de 48 ng/mL (valor normal 30-300 ng/mL). ¿Cuál de las siguientes opciones es más adecuada?:', NULL, 2012, NULL, false, 'MEDIO', 'PUBLICADA', 36, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (12747, 'MIR 2011, P103', '10. Enfermedad renal crónica.', 'Cuál de las siguientes alteraciones no es característica del hiperparatiroidismo secundario de los pacientes con insuficiencia renal:', NULL, 2011, NULL, false, 'FACIL', 'PUBLICADA', 36, 2, '2026-05-06 09:01:52.020007+00', '2026-05-06 09:11:48.21689+00');
