INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13358, 'MIR 2017-18, P126', '32. Patología de las glándulas salivares', 'Hombre de 47 años, con antecedente de un adenoma pleomorfo paro(cid:417)deo derecho, tratado con cirugía (paro(cid:415)dectomía extrafacial) hace 6 meses, que acude a nuestra consulta por presentar durante la mas(cid:415)cación dolor con sudoración y enrojecimiento de la piel de la región preauricular. ¿Qué tratamiento sería el de elección?', NULL, 2018, NULL, false, 'MEDIO', 'PUBLICADA', 28, 2, '2026-05-06 09:01:52.652946+00', '2026-05-06 09:11:50.77389+00');
