INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13361, 'MIR 2008-09, P154', '32. Patología de las glándulas salivares', 'Varón de 75 años que acude a la consulta por presentar parálisis facial derecha de lenta instauración. A la exploración se aprecia una tumoración preauricular derecha de 4 cm, de consistencia dura, que según refiere el paciente la (cid:415)ene desde hace aproximadamente un año. No se palpan adenopa(cid:417)as cervicales, ¿Cómo orientaría el cuadro clínico?:', NULL, 2009, NULL, false, 'MEDIO', 'PUBLICADA', 28, 2, '2026-05-06 09:01:52.652946+00', '2026-05-06 09:11:50.77389+00');
