INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13446, 'MIR 2016, P177', 'Tema 15. Malformaciones congénitas del aparato digestivo.', 'Un niño de 18 meses de vida es atendido en Urgencias por presentar deposición abundante de sangre oscura. En la exploración física el paciente presenta palidez, taquicardia y palpación abdominal normal. En el hemograma la cifra de hemoglobina es de 7 g/dL. ¿Qué prueba diagnóstica solicitaría?', NULL, 2016, NULL, false, 'MEDIO', 'PUBLICADA', 41, 2, '2026-05-06 09:01:52.652946+00', '2026-05-06 09:11:50.77389+00');
