INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13455, 'MIR 2008, P181', 'Tema 17. Crecimiento y desarrollo normal.', 'La valoración del desarrollo psicomotriz constituye una exploración importante para detectar trastornos del desarrollo durante la primera infancia. ¿A qué edad el 50% de los lactantes deben mantenerse sentados sin ayuda?:', NULL, 2008, NULL, false, 'FACIL', 'PUBLICADA', 41, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13457, 'MIR 2025, P21f', 'Tema 18. El lactante normal.', 'Un lactante de 8 meses presenta desde hace 2 semanas eritema de la zona del pañal (IMAGEN 21) que ha sido tratado durante los úl1mos días con emolientes y cremas barrera. ¿Cuál es el tratamiento más adecuado en este momento?:', NULL, 2025, NULL, false, 'MEDIO', 'PUBLICADA', 41, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
