INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13466, 'MIR 2020, P36c', 'Tema 20. Inmunizaciones en pediatría.', 'La vacuna neumocócica de polisacáridos PPSV23 genera una respuesta inmunitaria de tipo timo-independiente frente a 23 subtipos de neumococos. La inmunización con dosis repetidas de PPSV23:', NULL, 2020, NULL, false, 'FACIL', 'PUBLICADA', 41, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
