INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13468, 'MIR 2018, P127', 'Tema 20. Inmunizaciones en pediatría.', 'De acuerdo al calendario común de vacunación infantil del Consejo lnterterritorial de 2018, ¿qué vacuna se recomienda con una pauta a los 4 meses, 12 meses y 12 años?', NULL, 2018, NULL, false, 'FACIL', 'PUBLICADA', 41, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
