INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13754, 'MIR 2008, P163', '3. Esquizofrenia y otros trastornos psicóticos', 'En la exploración física del paciente con esquizofrenia es frecuente encontrar:', NULL, 2008, NULL, false, 'MEDIO', 'PUBLICADA', 45, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13755, 'MIR 2008, P164', '3. Esquizofrenia y otros trastornos psicóticos', 'Señale cuál de los siguientes síntomas NO pertenece a los clasificados como síntomas negativos en la esquizofrenia:', NULL, 2008, NULL, false, 'FACIL', 'PUBLICADA', 45, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (13756, 'MIR 2007, P157', '3. Esquizofrenia y otros trastornos psicóticos', 'Uno de los siguientes síntomas característicos del síndrome esquizofrénico no puede considerarse un síntoma negativo:', NULL, 2007, NULL, false, 'FACIL', 'PUBLICADA', 45, 2, '2026-05-06 09:01:53.281359+00', '2026-05-06 09:11:53.530746+00');
