INSERT INTO public.preguntas OVERRIDING SYSTEM VALUE VALUES (14628, 'MIR 2020-2021, P159', '1. La Isquemia Arterial Crónica', 'El tratamiento quirúrgico de elección de la compresión vascular del duodeno, conocida también como síndrome de la arteria mesentérica superior o síndrome de Wilkie, es:', NULL, 2021, NULL, false, 'FACIL', 'PUBLICADA', 35, 2, '2026-05-06 09:01:54.544406+00', '2026-05-06 09:11:59.195723+00');
