INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23028, 9491, '1. En la aurícula derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23029, 9491, '2. En la vena cava superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23030, 9491, '3. En la vena subclavia izquierda, en su confluencia con la vena yugular interna izquierda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23031, 9491, '4. En la vena yugular derecha.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23032, 9491, '5. En el tronco venoso braquiocefálico derecho.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23033, 9492, '1. Hiato de Bochdalek.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23034, 9492, '2. Hiato esofágico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23035, 9492, '3. Hiato de Winslow.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23036, 9492, '4. Hiato aórtico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23037, 9492, '5. Hiato de Mogagni.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23038, 9493, '1. La arteria interventricular posterior es rama de la arteria coronaria derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23039, 9493, '2. La arteria coronaria derecha irriga el tabique interventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23040, 9493, '3. La arteria circunfleja es rama de la arteria coronaria izquierda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23041, 9493, '4. El nodo aurículo-ventricular está irrigado por una rama de la coronaria izquierda en la mayoría de los casos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23042, 9493, '5. Las arterias coronarias son ramas de la aorta ascendente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23043, 9494, '1. Aorta torácica descendente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23044, 9494, '2. Vena ácigos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23045, 9494, '3. Nervios esplácnicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23046, 9494, '4. Vena cava superior.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23047, 9494, '5. Conducto torácico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23048, 9495, '1. El borde agudo del corazón está vascularizado por la arteria coronaria derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23049, 9495, '2. La arteria interventricular anterior o descendente anterior es rama de la arteria coronaria derecha.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23050, 9495, '3. Las arterias coronarias son ramas de la aorta torácica ascendente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23051, 9495, '4. El tabique interventricular o septo está irrigado por las arterias coronarias derecha e izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23052, 9495, '5. La arteria circunfleja auricular rama de la coronaria izquierda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23053, 9496, '1. La anatomía normal de los bronquios no influye en la localización de las lesiones por aspiración.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23054, 9496, '2. La división de los pulmones en segmentos no tiene ninguna aplicación en Radiología.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23055, 9496, '3. La división de los pulmones en segmentos no tiene ninguna aplicación en la práctica de la cirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23056, 9496, '4. El bronquio principal derecho es más estrecho, en la mayoría de los casos, que el izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23057, 9496, '5. Los bronquios principales acompañan a las arterias pulmonares en los hilios pulmonares.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23058, 9497, '1. Su punto más débil para fracturarse es el extremo próximo al esternón.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23059, 9497, '2. La primera costilla es, generalmente, la más delgada de todas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23060, 9497, '3. La presencia de costilllas cervicales puede producir síntomas neurológicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23061, 9497, '4. La presencia de costillas cervicales nunca produce síntomas vasculares.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23062, 9497, '5. La elasticidad de la caja torácica no depende de los cartílagos costales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23063, 9498, '1. El ápex del corazón se dirige hacia abajo, hacia delante y hacia la izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23064, 9498, '2. Las cavidades derechas ocupan una posición anterior y derecha, respecto las izquierdas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23065, 9498, '3. Las aurículas contribuyen con su contracción al 15-25% del llenado ventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23066, 9498, '4. El tabique interauricular es muscular, excepto en su posición basal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23067, 9498, '5. En algunos individuos, la fosa oval permanece abierta, aun tras el nacimiento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23068, 9499, '1. Arteria subclavia izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23069, 9499, '2. Tronco braquiocefálico venoso izquierdo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23070, 9499, '3. Vena yugular anterior derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23071, 9499, '4. Vena yugular externa izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23072, 9500, '1. La inervación de los músculos rectos abdominales procede de nervios que discurren entre el músculo transverso abdominal y el músculo oblicuo interno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23073, 9500, '2. Tras la disección y rotación de un colgajo TRAM (transversus rectus abdominis musculus) se produce una debilidad de la pared abdominal especialmente por encima de la línea arcuata.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23074, 9500, '3. La irrigación del músculo recto abdominal proviene principalmente de los vasos epigástricos inferiores y superiores profundos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23075, 9500, '4. El músculo recto abdominal puede utilizarse para reconstrucción de defectos mediastínicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23076, 9501, '1. Ligamento arqueado lateral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23077, 9501, '2. Hiato esofágico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23078, 9501, '3. Orificio de la vena cava inferior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23079, 9501, '4. Hiato aórtico.', false, 4);
