INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23119, 9510, '2. Arteria hepática izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23120, 9510, '3. Arteria hepática común.', false, 3);
