INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23122, 9510, '5. Arteria mesentérica superior.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23123, 9511, '1. La vena porta sigue un trayecto antero-medial con respecto a la arteria hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23124, 9511, '2. La arteria hepática derecha se divide en dos ramas que abrazan el conducto hepático derecho o el conducto cístico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23125, 9511, '3. La vía biliar principial es postero-lateral derecha con respecto a la vena porta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23126, 9511, '4. La arteria hepática izquierda nace de la arteria coronaria o de la arteria gastroduodenal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23127, 9511, '5. La vena coronaria confluye sobre la vena esplénica a unos 4 cm del tronco esplenomesentérico.', false, 5);
