INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23134, 9513, '2. Endodermo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23135, 9513, '3. Mesodermo.', false, 3);
