INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23137, 9513, '5. Mesotelio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23138, 9514, '1. La segunda porción duodenal tiene una dirección vertical o descendente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23139, 9514, '2. Una pequeña porción del duodeno se sitúa retroperitonealmente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23140, 9514, '3. El ligamento hepatoduodenal se inserta en la primera porción duodenal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23141, 9514, '4. La cara posterior de la segunda porción duodenal se relaciona con el hilio renal y el músculo psoas iliaco entre otros.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23142, 9514, '5. La arteria mesentérica superior está en relación con la tercera porción duodenal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23143, 9515, '1. Desciende por la pared posterior del abdomen apoyado en la cara anterior del músculo psoas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23144, 9515, '2. Cruza por delante de la arteria ilíaca primitiva o la porción inicial de la arteria ilíaca externa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23145, 9515, '3. Es cruzado anteriormente por los vasos colónicos izquierdos y por los vasos gonadales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23146, 9515, '4. Pasa por detrás del colon sigmoide.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23147, 9515, '5. Pasa por detrás del conducto deferente.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23148, 9516, '1. Supraduodenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23149, 9516, '2. Retroduodenal.', false, 2);
