INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23151, 9516, '4. Terminal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23152, 9516, '5. Ampular.', false, 5);
