INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23159, 9518, '2. Vena gastroepiploica inferior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23160, 9518, '3. Vena mesentérica inferior.', false, 3);
