INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23162, 9518, '5. Vena esplénica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23163, 9519, '1. Situada por detrás y algo por encima de la vena renal izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23164, 9519, '2. Situada por detrás y debajo del cuerpo del páncreas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23165, 9519, '3. Situada por detrás y debajo de vena esplénica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23166, 9519, '4. Se origina en la cara lateral izquierda de la aorta abdominal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23167, 9519, '5. Situada por detrás de la vena cava inferior.', true, 5);
