INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23169, 9520, '2. Hernia inguinal indirecta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23170, 9520, '3. Hernia pectínea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23171, 9520, '4. Hernia epigástrica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23172, 9520, '5. Hernia inguinal directa.', true, 5);
