INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23174, 9521, '2. Ligamento redondo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23175, 9521, '3. Ligamento triangulares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23176, 9521, '4. Ligamento falciforme.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23177, 9521, '5. Ligamento hepatoduodenal.', true, 5);
