INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23179, 9522, '2. Los rectos anteriores del abdomen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23180, 9522, '3. Los abductores de la cadera.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23181, 9522, '4. El sartorio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23182, 9522, '5. El oblicuo mayor del abdomen.', false, 5);
