INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23184, 9523, '2. Rotura de la porción corta del bíceps braquial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23185, 9523, '3. Rotura del tendón distal del bíceps braquial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23186, 9523, '4. Rotura del tendón del pectoral mayor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23187, 9524, '1. Epicondilopatía medial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23188, 9524, '2. Epicondilopatía lateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23189, 9524, '3. Síndrome compartimental crónico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23190, 9524, '4. Neuropatía cubital por atrapamiento en canal epitrócleo-olecraniano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23191, 9525, '1. Los músculos que forman el manguito de los rotadores son el subescapular, el supraespinoso, el infraespinoso y el redondo mayor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23192, 9525, '2. Los tendones de los músculos del manguito refuerzan la cápsula fibrosa de la articulación escápulo-humeral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23193, 9525, '3. El músculo infraespinoso rota el brazo en dirección interna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23194, 9525, '4. El músculo supraespinoso ayuda a la aducción (aproximación) del brazo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23195, 9526, '1. Espondiloartrosis cervical C5-C6.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23196, 9526, '2. Compresión cubital epitroclear.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23197, 9526, '3. Hernia discal cervical C6-C7.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23198, 9526, '4. Síndrome del túnel carpiano.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23199, 9527, '1. Está inervada por el nervio mediano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23200, 9527, '2. Tiene como función la supinación del antebrazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23201, 9527, '3. Participa en la estabilidad de la articulación radiocubital distal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23202, 9527, '4. Tiene su origen en el cuarto distal de la cara anterior del cúbito y su inserción en el cuarto distal de la cara anterior del radio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23203, 9528, '1. Una lesión del nervio radial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23204, 9528, '2. Una lesión del nervio axilar (circunflejo).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23205, 9528, '3. Una lesión del nervio musculocutáneo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23206, 9528, '4. Una rotura de los ligamentos escapulohumerales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23207, 9529, '1. Nervio musculocutáneo.', false, 1);
