INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23342, 9557, '1. Cuando no es necesaria la intervención de ningún facultativo para realizar la receta del medicamento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23885, 9692, '3. Diazepam.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23343, 9557, '2. Cuando el preparado contiene alguna sustancia homeopática y sigue un procedimiento de fabricación descrito en la farmacopea oficial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23344, 9557, '3. Cuando se prescribe para alguna enfermedad cuyo diagnóstico se debe realizar en un centro hospitalario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23345, 9557, '4. Cuando puede producir algún riesgo considerable de abuso, dependencia o ser desviado para usos ilegales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23346, 9558, '1. La asistencia sanitaria más elemental que no requiere de grandes estructuras organizativas ni de una gran inversión tecnollógica, puesta al servicio de la población para satisfacer sus necesidades de acuerdo con el plan de salud desarrollado e implementado por la Administración', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23347, 9558, '2. La asistencia sanitaria realizada por personal médico y de enfermería, con el apoyo de personal auxiliar y administrativo, dirigido a la población de un área sanitaria básica de un territorio concreto', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23348, 9558, '3. La atención que se da a la población de un área territorial', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23349, 9558, '4. La asistencia sanitaria esencial basada en métodos y tecnologías prácticos, científicamente fundados y socialmente aceptables, puesta al alcance de todos los individuos y familias de la comunidad a un coste soportable por esta', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23350, 9559, '1. La calidad en la atención del paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23351, 9559, '2. La calidad en la investigación clínica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23352, 9559, '3. La seguridad en la atención del paciente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23353, 9559, '4. La equidad en la gestión sanitaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23354, 9560, '1. Financiación pública, cobertura universal, asistencia sanitaria integral, equidad basada en la accesibilidad y descentralización territorial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23355, 9560, '2. Financiación pública, cobertura universal, asistencia sanitaria integral, eficacia y centralización territorial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23356, 9560, '3. Financiación mixta (pública y privada), gestión mixta (pública y privada) y centralización territorial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23357, 9560, '4. Financiación por cuotas de la seguridad social, gestión mixta (pública y privada) y descentralización territorial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23358, 9561, '1. Interrelación de promoción, prevención, tratamiento, rehabilitación e inserción social.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23359, 9561, '2. A lo largo de toda la vida de la persona (desde su nacimiento hasta su muerte).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23360, 9561, '3. Abordando las esferas física, psíquica y social.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23361, 9561, '4. Coordinando la atención en consulta y en domicilio, ya sean a demanda o programadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23362, 9562, '1. Ensayos clínicos postcomercialización.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23363, 9562, '2. Estudios de cohortes.', false, 2);
