INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23382, 9567, '1. Es una prueba diagnóstica confirmatoria cuando es positiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23383, 9567, '2. Un resultado negativo para HLA-DQ2 y HLA-DQ8 hace muy improbable el diagnóstico de enfermedad celíaca.', true, 2);
