INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23386, 9568, '1. Cuasi-incidente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23387, 9568, '2. Factor contribuyente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23388, 9568, '3. Infracción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23389, 9568, '4. Evento centinela.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23390, 9569, '1. Sesgo o falacia ecológica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23391, 9569, '2. Sesgo de atención o efecto Hawthorne.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23392, 9569, '3. Falacia de Neyman o sesgo de prevalencia de incidencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23393, 9569, '4. Sesgo de regresión a la media.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23394, 9570, '1. Los profesionales de salud deben responder a las demandas explícitas de los pacientes cuando estos acuden a consulta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23395, 9570, '2. Los equipos de atención primaria deben ser proactivos, abordando tanto las necesidades expresadas por los pacientes como aquellas que no han sido verbalizadas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23396, 9570, '3. Los pacientes son responsables de expresar todas sus necesidades para que el equipo de atención primaria pueda ofrecer la atención adecuada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23397, 9570, '4. La participación activa se refiere exclusivamente a la implicación de la comunidad en las decisiones sobre políticas de salud.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23398, 9571, '1. Los años vividos con discapacidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23399, 9571, '2. Los años de vida perdidos por muerte prematura.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23400, 9571, '3. La mortalidad general y por las principales enfermedades.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23401, 9571, '4. Los años de vida ajustados por discapacidad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23402, 9572, '1. Responsabilidad compartida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23403, 9572, '2. Atención a demanda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23404, 9572, '3. Atención integral y global.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23405, 9572, '4. Comunicación fluida entre médicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23406, 9573, '1. Los años perdidos por discapacidad atribuible a esa enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23407, 9573, '2. La mortalidad por esa enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23408, 9573, '3. Los años de vida ajustados por discapacidad atribuible a esa enfermedad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23409, 9573, '4. El coste económico de la enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23410, 9574, '1. La medicina basada en la evidencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23411, 9574, '2. Las búsquedas sistemáticas de información: Tripdatabase, Pubmed, Cochrane,...', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23412, 9574, '3. Los informes de evaluación de tecnologías sanitarias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23413, 9574, '4. La experiencia profesional individual.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23414, 9575, '1. La aplicación de los resultados de los ensayos clínicos a la práctica clínica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23415, 9575, '2. Que todas las decisiones médicas están fundamentadas en evidencias científicas de calidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23416, 9575, '3. La integración de la maestría clínica individual con las mejores evidencias científicas disponibles.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23417, 9575, '4. La búsqueda de las mejores respuestas para las preguntas que surgen en la práctica clínica diaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23418, 9576, '1. La existencia de servicios clínicos asistenciales adecuados y accesibles y de una buena educación ciudadana sobre su empleo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23419, 9576, '2. Que se tengan establecidas buenas medidas de prevención contra esa enfermedad, puesto que es mejor prevenir que curar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23420, 9576, '3. La existencia de buenas campañas de detección precoz, para poderla tratar antes de que dé síntomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23421, 9576, '4. Disponer de la tecnología adecuada que permita distinguir, desde el principio, los casos que se harán más graves, para centrar en ellos el esfuerzo terapéutico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23422, 9577, '1. Disminución de la eficacia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23423, 9577, '2. Listas de espera de pacientes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23424, 9577, '3. Disminución de la rentabilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23425, 9577, '4. Listas de programación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23426, 9578, '1. Exigir que los presupuestos sean controlados rigurosamente por los gestores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23427, 9578, '2. Conocer y controlar los costes de los recursos que usa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23428, 9578, '3. Primar los aspectos socio-económicos en la indicación diagnóstica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23429, 9578, '4. Primar los aspectos socio-económicos en el uso de medicamentos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23430, 9579, '1. La relación entre los resultados obtenidos y los costes generados por sus aplicaciones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23431, 9579, '2. El ahorro generado con la aplicación del programa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23432, 9579, '3. La relación entre los objetivos iniciales y los resultados finales obtenidos por el programa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23433, 9579, '4. La relación entre la cobertura poblacional alcanzada por el programa y la prevista inicialmente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23434, 9580, '1. Se produce con mayor frecuencia en familias desestructuradas y con pocos recursos económicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23435, 9580, '2. Los agresores presentan con frecuencia trastornos psiquiátricos graves que explican la conducta violenta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23436, 9580, '3. Las víctimas rara vez acuden a los servicios sanitarios por miedo a ser identificadas como víctimas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23437, 9580, '4. El embarazo es un periodo de riesgo para el inicio o agravamiento de la violencia de género.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23438, 9581, '1. Informaremos a su hija y que sea ella quien informe a la paciente, pues es quien mejor la conoce y sabe cómo reaccionará.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23439, 9581, '2. Debemos dar la información a la paciente, de acuerdo a la capacidad de comprensión.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23440, 9581, '3. Como médicos responsables de la paciente sabemos cuál es el mejor tratamiento. Dado que la paciente no es capaz de comprenderlo, la decisión es exclusivamente nuestra.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23441, 9581, '4. Ya hablamos con su hija ayer y decidimos ocultarle la sospecha diagnóstica para que no sufriera, así que no le daremos más información, independientemente de lo que ella nos pregunte.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23442, 9582, '1. La gratificación profesional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23443, 9582, '2. El avance científico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23444, 9582, '3. Servir a las necesidades del paciente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23445, 9582, '4. La exactitud diagnóstica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23446, 9583, '1. Entrevista semiológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23447, 9583, '2. Entrevista informativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23448, 9583, '3. Entrevista motivacional.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23449, 9583, '4. Entrevista operativa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23450, 9584, '1. Lleva la iniciativa con el fin de obtener respuestas concretas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23451, 9584, '2. Se mantiene distante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23452, 9584, '3. Comprende lo que el paciente le explica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23453, 9584, '4. Manifiesta que se hace cargo del problema como si el paciente se tratara de su hermano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23454, 9585, '1. Decirle que haga la solicitud de amistad y que la aceptará, pues está seguro de que en su página no hay elementos inapropiados para una chica de la edad de Sofía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23455, 9585, '2. Dado que considera a Sofía una paciente vulnerable y le preocupa que pueda interpretar mal un rechazo, aceptar que haga la solicitud pero solamente permitirle el acceso a determinados contenidos de su página.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23456, 9585, '3. Contestarle que es importante mantener unos ciertos límites profesionales entre pacientes y facultativos y que, desafortunadamente, si hace la petición, no podrá aceptarla, por lo que mejor que no la haga.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23457, 9585, '4. Decirle que haga la petición pero sin intención de aceptarla.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23458, 9586, '1. Preguntar al paciente si quiere que sus médicos le den la información sobre su enfermedad a ella o a sus hijos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23459, 9586, '2. Aceptar los deseos de los hijos y pedir a todo el personal involucrado en el tratamiento que no le digan al paciente que tiene cáncer.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23460, 9586, '3. Explicar a los hijos que los médicos están obligados a dar al paciente toda la información relevante sobre su problema médico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23461, 9586, '4. Pedir a sus hijos que estén presentes cuando le digan a su madre que tiene cáncer.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23462, 9587, '1. Comentarle al paciente que el tratamiento no parece haber sido efectivo y cambiar el antibiótico, evitando más comentarios que puedan comprometerle. Ofrecerle un nuevo control en pocos días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23463, 9587, '2. Comentarle al paciente que el tratamiento de la bronquitis puede ser fundamentalmente sintomático y que los antibióticos no necesariamente son efectivos por lo que, dada la evolución, lo más aconsejable es suspender la amoxicilina-clavulánico e iniciar tratamiento sintomático, con nuevo control en pocos días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23464, 9587, '3. Comentar que la presencia del exantema puede ser un efecto adverso de la medicación pues la amoxicilina-clavulánico, que no es lo mismo que la penicilina, puede en ocasiones tener reacciones cruzadas con la misma y que es mejor suspender toda medicación y ver evolución. Ofrecerle un nuevo control en pocos días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23746, 9657, '4. Se debe cambiar a un opioide mayor y mantener los AINES.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23465, 9587, '4. Comentar que la presencia del exantema puede ser un efecto adverso de la medicación pues la amoxicilina-clavulánico forma parte de la familia de las penicilinas y que usted, en la anterior visita no se percató de que el paciente era alérgico a la misma. Suspenderla en consecuencia, pedir excusas, proponer un tratamiento sintomático y ofrecerle un nuevo control en pocos días.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23466, 9588, '1. Escuchar activamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23467, 9588, '2. Evitar utilizar el lenguaje técnico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23468, 9588, '3. Reprimir la expresión de sentimientos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23469, 9588, '4. Graduar la información negativa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23470, 9589, '1. Leer el informe de Urgencias y solicitar las pruebas urgentes que estime conveniente y que deban realizarse en ayunas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23471, 9589, '2. Modificar el tratamiento según la impresión de la enfermera y los signos vitales disponibles en la gráfica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23472, 9589, '3. Realizar la historia clínica, anamnesis, exploración física, registrar todo ello en el sistema de documentación clínica del hospital, dejando constancia de la impresión diagnóstica y del plan.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23473, 9589, '4. Informar al paciente y a la persona que entiende de su caso de las perspectivas del ingreso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23474, 9590, '1. El facultativo tiene que mostrarse amigo antes que profesional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23475, 9590, '2. El médico debe evitar advertir al paciente del tiempo que dispone para atenderle.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23476, 9590, '3. El profesional debe verificar que el paciente ha comprendido la información.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23477, 9590, '4. El médico, durante la entrevista, debe permanecer de pie o situado tras la cabecera de la cama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23478, 9591, '1. Haga el favor de salir y vuelva usted a entrar en la consulta de manera educada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23479, 9591, '2. Tome asiento y veré qué puedo hacer por usted.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23480, 9591, '3. Esta medicación que le di es la mejor y más segura para la artrosis de rodilla.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23481, 9591, '4. Yo también estoy enfadado con usted por la forma en que me chilla, si me habla como persona seguro que nos entenderemos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23482, 9592, '"1. ""La causa de los síntomas que han motivado su ingreso es un quiste del hígado que se ha complicado y hay que valorar con otros especialistas cómo hacer un tratamiento definitivo"".', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23483, 9592, '2. ""A pesar de que Ud. no ha manifestado nunca estar interesado por conocer el diagnóstico de su enfermedad, antes de trasladarlo al Servicio de Oncología debo informarle que tiene un cáncer de pulmón con metástasis en el hígado y va a requerir quimioterapia cuyos resultados no se podrán valorar de aquí a un tiempo"".', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23484, 9592, '3. Informar sólo a los familiares ya que el paciente nunca preguntó sobre su proceso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23485, 9592, '4. ""Si le parece bien hablamos del estado de su enfermedad..."". ""Con los exámenes practicados sabemos que tiene varios nódulos en el hígado, como quistes. En el análisis de la punción realizada aparecen unas células que sugieren un tumor maligno de procedencia pulmonar"". ""Este tipo de tumores responden a los tratamientos actuales con quimioterapia y por lo tanto le proponemos que el Servicio de Oncología, con el que ya hemos contactado. inicie esta pauta de inmediato”."', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23486, 9593, '1. No pueden ser evaluadas con métodos objetivos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23487, 9593, '2. Mejoran la adherencia de los pacientes a los tratamientos prescritos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23488, 9593, '3. Se correlacionan con sus conocimientos científicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23489, 9593, '4. Se basan, exclusivamente, en la capacidad de comunicación oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23490, 9594, '1. Dirigiéndose al familiar con quien ha mantenido la información del proceso durante el ingreso y argumentando la mínima desfiguración del cadáver y la importante información que puede dar la autopsia para la familia y para los médicos que se encargaron de atenderlo en vida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23491, 9594, '2. A toda la familia presente en ese momento argumentando datos que la autopsia puede dar de cara a posibles enfermedades hereditarias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23492, 9594, '3. Dirigiéndose al familiar con quien ha mantenido la información del proceso durante el ingreso y argumentando la contribución al conocimiento científico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23493, 9594, '4. Aduciendo, como principal razón, el derecho que les asiste de conocer el diagnóstico preciso no detectado en vida del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23494, 9595, '1. Un método de toma de decisiones prudentes en condiciones de incertidumbre.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23495, 9595, '2. Un procedimiento de negociación para alcanzar un acuerdo entre partes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23496, 9595, '3. La autorreflexión individual previa a la acción clínica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23497, 9595, '4. La intervención de un mediador externo cuando existe conflicto de opiniones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23498, 9596, '1. El parte de lesiones solo debe emitirse si la víctima solicita expresamente que se comunique a la autoridad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23499, 9596, '2. Cuando el profesional sanitario atiende lesiones posiblemente derivadas de agresión, debe emitir parte y remitirlo al juzgado, incluso sin consentimiento de la víctima.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23500, 9596, '3. El parte de lesiones es obligatorio si existe ingreso hospitalario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23501, 9596, '4. Si el paciente niega la agresión y solicita confidencialidad, el médico debe mantener el secreto profesional y no emitir el parte.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23502, 9597, '1. Es necesario el consentimiento por representación para los menores de 18 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23503, 9597, '2. La prestación de ayuda para morir puede llevarse a cabo si está recogida por escrito en el Documento de Voluntades Anticipadas o instrucciones previas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23504, 9597, '3. El médico responsable es quien decide el lugar en que debe producirse el fallecimiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23505, 9597, '4. La ley no contempla el ejercicio de la objeción de conciencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23506, 9598, '1. En el CMD se hará constar que el cadáver pertenece al grupo I, por presentar enfermedad infecciosa que supone un riesgo relevante para la salud pública.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23507, 9598, '2. No se puede cumplimentar el CMD por tratarse de muerte sospechosa de criminalidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23508, 9598, '3. No se puede cumplimentar el CMD por que sólo se dispone de criterios de presunción y no de confirmación, aunque las circunstancias del fallecimiento y la patobiografía sean compatibles.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23509, 9598, '4. Se hará constar la infección por COVID-19 en el apartado de causa fundamental y no en el apartado de causa inmediata.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23565, 9612, '4. Se trata de un proceso de fin de vida en situación agónica a quien prioritariamente se debe realizar sedación para paliar su sufrimiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23510, 9599, '1. Si la persona tiene entre 16 y 18 años, la decisión corresponde a la persona menor si demuestra que es capaz de comprender el alcance del procedimiento. pero los padres o tutores deben ser consultados obligatoriamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23511, 9599, '2. Si la persona tiene entre 16 y 18 años, la decisión corresponde a los padres o tutores legales, pero la persona menor debe ser consultada si demuestra que es capaz de comprender el alcance del procedimiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23512, 9599, '3. En caso de conflicto entre el criterio del menor y el de sus padres o tutores legales, debe resolver un juez mediante la aplicación del principio del interés superior del menor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23513, 9599, '4. Los menores de 18 años no pueden ser donantes de órganos de vivo, según la Ley. No hay excepciones.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23514, 9600, '1. Rechazo al tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23515, 9600, '2. Eutanasia activa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23516, 9600, '3. Limitación de esfuerzo terapéutico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23517, 9600, '4. Obstinación terapéutica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23518, 9601, '1. Rechazo de tratamiento.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23519, 9601, '2. Limitación del esfuerzo terapéutico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23520, 9601, '3. Obstinación terapéutica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23521, 9601, '4. Eutanasia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23522, 9602, '1. Certificado ordinario de defunción.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23523, 9602, '2. Boletín estadístico de defunción con intervención judicial (muerte violenta).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23524, 9602, '3. Boletín estadístico de defunción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23525, 9602, '4. Parte de lesiones.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23526, 9603, '1. No es posible realizar una intervención quirúrgica urgente cuando sólo se obtiene un consentimiento verbal de un representante del paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23527, 9603, '2. Si no se pudiera contactar con ningún familiar o allegado del paciente no podría realizarse la intervención quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23528, 9603, '3. El médico responsable debe intentar contactar con los familiares del paciente y, tras explicar la situación, obtener de ellos el consentimiento para realizar la intervención.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23529, 9603, '4. Sin un documento de consentimiento informado firmado por los familiares del paciente no es posible realizar la intervención.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23530, 9604, '1. Autonomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23531, 9604, '2. Beneficencia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23532, 9604, '3. No maleficencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23533, 9604, '4. Justicia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23534, 9605, '1. Consultar el historial médico del paciente y darle la información que me pide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23535, 9605, '2. Decirle que yo no tengo nada que ver con el paciente y terminar la conversación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23536, 9605, '3. Transmitir al médico responsable del paciente la pregunta de mi colega y ponerles en contacto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23537, 9605, '4. Mandarle un informe escrito del paciente para evitar dar información por teléfono.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23538, 9606, '1. No maleficencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23539, 9606, '2. Confidencialidad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23540, 9606, '3. Justicia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23541, 9606, '4. Autonomía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23542, 9607, '1. Es un requisito legal que exime al médico de cualquier responsabilidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23543, 9607, '2. Supone una toma de decisión compartida después de informar al paciente del procedimiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23544, 9607, '3. Da libertad al médico para realizar nuevos procedimientos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23545, 9607, '4. Permite determinar si el paciente es capaz de tomar decisiones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23546, 9608, '1. Son las fuentes fundamentales a partir de las cuales justificamos las pautas para la acción, los deberes y las reglas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23547, 9608, '2. La capacidad de comprensión y la falta de coerción externa son fundamentales a la hora del ejercicio de la autonomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23548, 9608, '3. El principio de beneficencia y el de autonomía están relacionados y en ocasiones pueden entrar en conflicto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23549, 9608, '4. El principio de justicia se refiere a la compensación debida a los pacientes por las posibles malas prácticas médicas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23550, 9609, '1. Queda relevado de presentar un consentimiento informado a la paciente, y se considera suficiente su criterio como médico para que se realice la colonoscopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23551, 9609, '2. Solicita la comparecencia del Juez para que autorice la prueba, ante la incapacidad intelectual de la enferma para decidir convenientemente por sí misma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23552, 9609, '3. Por no tener capacidad para decidir, deben hacerlo por ella sus familiares, debiendo quedar constancia escrita de su aceptación en el impreso de consentimiento informado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23553, 9609, '4. Es jurídicamente aceptable un acuerdo entre el médico y los familiares de la enferma basado en un consentimiento informado verbal para que se practique la colonoscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23554, 9610, '1. Su médico está obligado a instaurar un tratamiento, aún en contra de la voluntad del paciente, si éste sufre una situación clínica amenazante para su vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23555, 9610, '2. Plantearemos la situación a sus familiares o representante legalmente designado y actuaremos de acuerdo con ellos, aunque su opinión no coincida con la del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23556, 9610, '3. Informaremos al paciente de los pros y de los contras de su decisión, y respetaremos la que adopte, aunque pueda conllevar un desenlace fatal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23557, 9610, '4. Está indicado no emprender otro tratamiento que no sea el de sedación por sufrir neoplasia terminal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23558, 9611, '1. Solicitar el consentimiento informado antes de practicarlo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23559, 9611, '2. Practicar directamente el drenaje ya que en las situaciones de urgencia puede prescindirse del consentimiento informado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23560, 9611, '3. Intentar localizar a un familiar para que decida por el paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23561, 9611, '4. No debe solicitarse dado que el drenaje no es necesario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23562, 9612, '1. Es crucial el diagnóstico preciso e inmediato mediante TAC de tórax y obtención de muestras microbiológicas, incluso de carácter invasivo, para ajustar el tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23563, 9612, '2. Es fundamental definir explícitamente los objetivos terapéuticos, simplificándolos y evitando tratamientos innecesarios, así como respetar los valores y preferencias del paciente y de su familia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23564, 9612, '3. Se trata de una neumonía adquirida en la comunidad (NAC) de alto riesgo que precisa de tratamiento intensivo con soporte ventilatorio, incluso mecánico, y antibioterapia de alto espectro por el riesgo de multirresistencia bacteriana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23567, 9613, '2. Trasladar el caso al comité de ética asistencial para que adopte la decisión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23568, 9613, '3. Respetar la preferencia manifestada y atenderle sin realizar la transfusión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23569, 9613, '4. Lo pondría en conocimiento del juez, y no administraría tratamiento alguno hasta que éste lo indicara.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23570, 9614, '1. Autonomía.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23571, 9614, '2. No maleficencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23572, 9614, '3. Equidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23573, 9614, '4. Beneficencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23574, 9615, '1. Ingreso en Psiquiatría para trabajar la negación y la rabia inherentes a su proceso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23575, 9615, '2. Solicitar la intervención de familiares que autoricen la intervención.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23576, 9615, '3. Alta hospitalaria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23577, 9615, '4. Informar al juez con el fin de que ordene tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23578, 9616, '1. Los familiares no la pueden solicitar. Lo tiene que hacer el propio paciente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23579, 9616, '2. El hospital tiene que facilitarla sin condiciones porque el propietario de la historia clínica es el paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23580, 9616, '3. Se facilitará el informe de todas las exploraciones complementarias y los comentarios generados por los médicos responsables cuando éstos lo consideren oportuno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23581, 9616, '4. Es necesario un requerimiento judicial para facilitar la información de una historia clínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23582, 9617, '1. Como norma general se realiza de forma oral y se prestará por escrito cuando se trate de procedimientos que supongan riesgos o inconvenientes de notoria y previsible repercusión negativa sobre la salud del paciente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23583, 9617, '2. El consentimiento informado por representación será necesario sólo en el caso de menores de 18 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23584, 9617, '3. Es la obtención de un documento firmado por el paciente para dar su consentimiento para cualquier tratamiento o intervención médica sobre su persona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23585, 9617, '4. El principio bioético fundamental que subyace bajo la obtención del consentimiento informado es el de beneficencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23586, 9618, '1. Obligar a la paciente a que ponga una denuncia en la comisaría más cercana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23587, 9618, '2. Hacer que la próxima visita la haga conjunta con su marido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23588, 9618, '3. Citar a su marido para el día siguiente y averiguar el motivo del maltrato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23589, 9618, '4. Tramitar el parte de lesiones por vía judicial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23590, 9619, '1. Que se respete la relación médico-paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23591, 9619, '2. Que acepte el riesgo que entraña la intervención.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23592, 9619, '3. Que colabore en el proceso terapéutico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23593, 9619, '4. Que entienda sus derechos legales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23594, 9620, '1. Colocar una gastrostomía para asegurar el aporte nutricional y explicarle a la hija que debe vigilar que su madre no se la retire.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23595, 9620, '2. Iniciar nutrición parenteral periférica y tranquilizar a la hija diciéndole que así su madre “seguirá recibiendo alimento, aunque no coma”.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23596, 9620, '3. Explicar a la hija que la falta de apetito y deglución son parte del proceso natural y ofrecer cuidados centrados en aliviar el malestar y proporcionar confort.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23597, 9620, '4. Intentar alimentación con espesantes y suplementos hipercalóricos durante unos días, animando a la hija a insistir en que su madre abra la boca y no tosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23598, 9621, '1. Aumentar la dosis de dexametasona y añadir midazolam.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23599, 9621, '2. Administrar haloperidol y valorar ajustar fármacos potencialmente implicados (como corticoides y morfina)', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23600, 9621, '3. Iniciar lactulosa y rifaximina para tratar una posible encefalopatía hepática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23601, 9621, '4. Sustituir la morfina por buprenorfina sublingual para reducir efectos neurotóxicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23602, 9622, '1. Aumentar la dosis de morfina un 25–50 % y asociar benzodiacepinas para controlar las mioclonías.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23603, 9622, '2. Reducir la dosis de morfina a la mitad y añadir un coadyuvante no opioide (AINE).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23604, 9622, '3. Rotar a fentanilo transdérmico calculando la dosis equianalgésica y reduciéndola un 30– 50 % por tolerancia cruzada incompleta.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23605, 9622, '4. Suspender el opioide oral y sustituirlo por buprenorfina sublingual a dosis bajas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23606, 9623, '1. La sedación paliativa tiene como finalidad provocar deliberadamente la muerte para evitar el sufrimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23607, 9623, '2. La eutanasia se realiza únicamente cuando el paciente está en situación de agonía inminente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23608, 9623, '3. La sedación paliativa busca aliviar síntomas refractarios, aunque pueda acortar secundariamente la supervivencia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23609, 9623, '4. En la eutanasia el alivio del sufrimiento es un efecto secundario no buscado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23610, 9624, '1. Clínica neurológica por metástasis cerebrales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23611, 9624, '2. Realizar TC cerebral y aumentar dosis de corticoides.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23612, 9624, '3. Psicosis inducida por corticoides. Retirar corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23613, 9624, '4. Síndrome confusional agudo hipoactivo. Iniciar tratamiento con neurolépticos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23614, 9624, '5. Neurotoxicidad por opioides. Reducir la dosis de morfina a la mitad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23615, 9625, '1. Es aceptable éticamente, aunque con ello sobrevenga la muerte del paciente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23616, 9625, '2. Se trata de una medida que depende fundamentalmente de la voluntad del médico responsable del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23617, 9625, '3. Es una práctica equivocada y obsoleta desde que existen medios sofisticados de soporte vital artificial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23618, 9625, '4. Según la ley española es eutanasia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23619, 9626, '1. Aceptar la petición del familiar y prescribir un analgésico no opioide para el control del dolor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23620, 9626, '2. Rechazar la solicitud del familiar y ordenar la administración de cloruro mórfico, a las dosis previamente prescritas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23621, 9626, '3. Plantear la rotación del tratamiento analgésico por otro opioide con menor riesgo sedante, como oxicodona/naloxona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23622, 9626, '4. Preguntar al paciente acerca de la intensidad de su dolor actual y de sus preferencias de analgesia en este momento.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23808, 9673, '2. Lograr el confort físico, emocional y espiritual del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23623, 9627, '1. En el caso de dolor por metástasis óseas está indicado el uso de antiinflamatorios como AINEs o corticoides como tratamiento coadyuvante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23624, 9627, '2. En el dolor neuropático están indicados como coadyuvantes fármacos anticonvulsivantes como la gabapentina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23625, 9627, '3. Dado que el paciente usa fentanilo como opioide de base, si decidimos pautar un opioide de rescate deberá ser también fentanilo dado que no deben mezclarse fármacos del tercer escalón analgésico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23626, 9627, '4. La radioterapia con finalidad analgésica es una opción en pacientes con metástasis óseas de neoplasias prostáticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23627, 9628, '1. La buscapina que se usa para disminuir las secreciones bronquiales al final de la vida se emplea también para evitar o disminuir el estreñimiento.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23628, 9628, '2. La morfina que se pauta para el dolor moderado- grave tiene un efecto positivo importante para reducir la sensación de disnea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23629, 9628, '3. La dexametasona que se emplea como antiinflamatorio se usa también para mejorar el apetito.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23630, 9628, '4. El haloperidol que se utiliza para paliar la agitación del delirium puede ser usado como antiemético, aunque en dosis menores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23631, 9629, '1. No está indicada por deprimir el centro respiratorio y no mejorar la disnea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23632, 9629, '2. Está indicada únicamente cuando la saturación de O2, sin oxigenoterapia, se mantiene por debajo del 90 %.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23633, 9629, '3. Está indicada porque existen síntomas y signos claros de empeoramiento grave y mal pronóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23634, 9629, '4. Estaría indicada únicamente cuando hay evidencia de insuficiencia respiratoria grave medida por gasometría arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23635, 9630, '1. Furosemida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23636, 9630, '2. Metamizol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23637, 9630, '3. Haloperidol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23638, 9630, '4. Metoclopramida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23639, 9631, '1. Rechazo de intervenciones con riesgo vital.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23640, 9631, '2. Donación de órganos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23641, 9631, '3. Rechazo de intervenciones sin riesgo vital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23642, 9631, '4. Instauración de intervenciones fútiles, sin indicación clínica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23643, 9632, '1. La dosis inicial de los inhibidores selectivos de la recaptación de serotonina debe ser la misma que la utilizada en adultos sin enfermedad terminal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23644, 9632, '2. Se recomienda evitar los antidepresivos tricíclicos, a menos que se utilicen como complementos en el tratamiento del dolor.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23645, 9632, '3. En pacientes en los que predominan síntomas como ansiedad o insomnio es preferible el uso de fluoxetina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23646, 9632, '4. La trazodona, incluso cuando se emplea a dosis bajas, está contraindicada por sus frecuentes efectos adversos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23647, 9633, '1. En presencia de tratamiento con opioides son recomendables los suplementos de fibra vegetal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23648, 9633, '2. Los elementos fundamentales del tratamiento son los laxantes estimulantes y osmóticos, reblandecedores de heces, líquidos y enemas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23649, 9633, '3. Para evitar el estreñimiento causado por los opioides se debe recurrir a la combinación de un laxante y un reblandecedor de heces.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23650, 9633, '4. Si no hay defecación tras varios días de tratamiento, se necesita el tacto rectal para extraer el material impactado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23651, 9634, '1. Múltiples.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23652, 9634, '2. Intensos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23653, 9634, '3. Estables.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23654, 9634, '4. Multifactoriales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23655, 9635, '1. Se inicia con dosis de 100 a 300 mg dos o tres veces al día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23656, 9635, '2. La combinación de gabapentina y nortriptilina no es más eficaz que la gabapentina sola.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23657, 9635, '3. La confusión y la somnolencia son efectos secundarios, en particular en pacientes mayores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23658, 9635, '4. Por lo común es eficaz una dosis de 900 a 3.600 mg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23659, 9636, '1. Eutanasia activa voluntaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23660, 9636, '2. Eutanasia activa involuntaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23661, 9636, '3. Eutanasia pasiva.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23662, 9636, '4. Suicidio asistido por un médico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23663, 9637, '1. El fentanilo transmucoso (oral o nasal) es el fármaco de elección en el tratamiento del dolor irruptivo oncológico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23664, 9637, '2. Los ensayos clínicos demuestran diferencias en la eficacia y tolerabilidad entre los diferentes opioides mayores.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23665, 9637, '3. La rotación de opioides o la analgesia raquídea son medidas de tratamiento del dolor refractario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23666, 9637, '4. La eficacia de la escalera analgésica de la Organización Mundial de la Salud (OMS) es del 80-90 %.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23667, 9638, '1. El fentanilo debe ajustarse en caso de insuficiencia renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23668, 9638, '2. La morfina presenta una vida media de 4 horas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23669, 9638, '3. La oxicodona presenta menor incidencia de náuseas que la morfina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23670, 9638, '4. La buprenorfina se puede administrar transdérmicamente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23671, 9639, '1. Acetato de megestrol (320 - 480 mg/día).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23672, 9639, '2. Paroxetina (10 - 20 mg/día).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23673, 9639, '3. Oxibutinina (2,5 – 10 mg/día).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23674, 9639, '4. Dexametasona (4 - 8 mg/día).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23675, 9640, '1. Cuidar el interior de la boca, aplicar lubricantes a los labios y uso de lágrimas artificiales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23676, 9640, '2. Pautar escopolamina para los ruidos respiratorios.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23677, 9640, '3. Tranquilizar a los cuidadores, explicando bien lo que está ocurriendo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23678, 9640, '4. Realizar cambios posturales para evitar las úlceras por presión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23679, 9641, '1. Solicitar analítica con hemograma, ionograma, función renal y hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23680, 9641, '2. Exploración física completa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23681, 9641, '3. Iniciar tratamiento con diazepam para control sintomático.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23682, 9641, '4. Evitar restricciones físicas de la paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23683, 9642, '1. La morfina es el fármaco más utilizado en sedación.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23684, 9642, '2. El delirium es el síntoma que con más frecuencia conduce al uso de la sedación paliativa en la mayoría de las series.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23883, 9692, '1. Clorazepato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23685, 9642, '3. Ante la presencia de un síntoma refractario en un paciente en situación de últimos días de vida, es necesario solicitar el consentimiento explícito, implícito o delegado antes de iniciar la sedación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23686, 9642, '4. La decisión multidisciplinar y consensuada en equipo puede redundar en un menor uso de la sedación como herramienta paliativa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23687, 9643, '1. El fármaco ideal para la sedación es el midazolam.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23688, 9643, '2. La morfina está contraindicada en el tratamiento de la disnea porque produce depresión respiratoria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23689, 9643, '3. El tratamiento estándar para los estertores premortem es la administración de anticolinérgicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23690, 9643, '4. En la agitación el tratamiento es el haloperidol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23691, 9644, '1. El representante puede cambiar la directriz anticipada de la paciente en su mejor interés.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23692, 9644, '2. El médico por ser una situación de urgencia no está obligado a seguir la directriz anticipada ni consultar con el representante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23693, 9644, '3. El representante no puede cambiar la directriz anticipada. Su finalidad es garantizar el respeto a los valores de la paciente y el cumplimiento de la instrucción.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23694, 9644, '4. Los familiares directos presentes, pueden hacer una decisión de sustitución en su mejor interés y no importa la opinión del representante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23695, 9645, '1. Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23696, 9645, '2. Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina u oxicodona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23697, 9645, '3. Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina u oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23698, 9645, '4. Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina u oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23699, 9646, '1. Opiáceos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23700, 9646, '2. Antidepresivos tricíclicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23701, 9646, '3. Agonistas dopaminérgicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23702, 9646, '4. Anticomiciales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23703, 9647, '1. Bajar dosis de opioides a la mitad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23704, 9647, '2. Pautar un laxante osmótico y comprobar mediante un tacto rectal que no exista impactación fecal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23705, 9647, '3. Pautar un procinético.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23706, 9647, '4. Realizar una TC urgente ante la sospecha de obstrucción intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23707, 9648, '1. La negativa a intervenciones para conservar la vida del paciente puede considerarse suicidio o incluso asesinato.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23708, 9648, '2. La administración de antibióticos o la infusión de suero debe evitarse en estas situaciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23709, 9648, '3. Deben suspenderse aquellas actividades que se demuestren que no son útiles para el paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23710, 9648, '4. Los médicos son los responsables de firmar la orden de no reanimación explicando los motivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23711, 9649, '1. Está indicada en pacientes que se encuentran cerca de su fallecimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23712, 9649, '2. Debe emplearse para aliviar síntomas refractarios a los tratamientos convencionales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23713, 9649, '3. No está indicada cuando lo solicita el paciente en situación terminal aduciendo motivos existenciales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23714, 9649, '4. Debe emplearse aún si se sospecha que va a ser la responsable de acortar la vida del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23715, 9650, '1. Demostrar buenos conocimientos y asertividad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23716, 9650, '2. Tenacidad y constancia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23717, 9650, '3. Empatía y compasión.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23718, 9650, '4. Seguridad y destreza.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23719, 9651, '1. Originan una respiración silenciosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23720, 9651, '2. Se tratan con morfina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23721, 9651, '3. Se tratan con procinéticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23722, 9651, '4. Se tratan con escopolamina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23723, 9652, '1. Retirar el tratamiento porque puede empeorar la insuficiencia respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23724, 9652, '2. Aumentar las dosis hasta 20 mg/4 horas según evolución.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23725, 9652, '3. Cambiar el tratamiento de morfina por escopolamina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23726, 9652, '4. Añadir al tratamiento risperidona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23727, 9653, '1. Pautar laxantes osmóticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23728, 9653, '2. Pautar laxantes estimulantes de la motilidad colónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23729, 9653, '3. Pautar fibra.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23730, 9653, '4. Pautar laxantes vía rectal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23731, 9654, '1. Administrar metoclopramida intravenosa para el control de vómitos y suspender laxantes y morfina hasta reevaluar evaluación clínica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23732, 9654, '2. Suspender fármacos por vía oral y administrar morfina, haloperidol, dexametasona y bromuro de hioscina por vía subcutánea para el control de síntomas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23733, 9654, '3. Suspender fármacos por vía oral y realizar tomografia axial computerizada para valorar cirugía urgente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23734, 9654, '4. Suspender fármacos por vía oral y administrar fentanilo transdérmico para control del dolor y metoclopramida y dexametasona por vía intravenosa para control de vómitos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23735, 9655, '1. Sonda nasogástrica, aspiración continua, sueroterapia intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23736, 9655, '2. Cirugía desobstrutiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23737, 9655, '3. Administración por vía subcutánea de morfina, buscapina, haloperidol y octeótrido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23738, 9655, '4. Dieta absoluta y sueros por vía intravenosa o subcutanea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23739, 9656, '1. Si precisamos sedación para control de la fase agónica podemos realizarla de forma exclusiva con morfina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23740, 9656, '2. Los antidepresivos tricíclicos no se consideran medicación coadyuvante para el alivio sintomático del dolor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23741, 9656, '3. Los neurolépticos a dosis bajas ayudan al control de las náuseas desencadenadas por el inicio de un tratamiento con opiáceos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23742, 9656, '4. El dolor de características viscerales es el que peor respuesta tiene al tratamiento con opiáceos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23743, 9657, '1. Se debe cambiar a opioides mayores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23744, 9657, '2. Se deben administrar las dosis extras de opioides que sean necesarias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23745, 9657, '3. Se deben añadir corticoides.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23747, 9658, '1. Colocar una sonda nasogástrica a medio plazo y dar el alta a una residencia con cuidados especializados hasta que se curen las escaras.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23748, 9658, '2. Dar el alta a una residencia con cuidados especializados hasta que curen las úlceras por presión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23749, 9658, '3. Poner una sonda por gastrostomía y dar el alta a domicilio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23750, 9658, '4. Dar el alta a domicilio con cuidados paliativos del área sanitaria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23751, 9659, '1. Se debe descartar la hipocalcemia por su manejo específico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23752, 9659, '2. La disminución de la actividad física contribuye a empeorar este síntoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23753, 9659, '3. La disminución de la ingesta de alimentos disminuye la masa fecal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23754, 9659, '4. Muchos de los fármacos que se utilizan en esta fase, como la amitriptilina, contribuyen al estreñimiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23755, 9660, '1. La dosis de morfina que recibe es la máxima aconsejada para evitar depresión respiratoria, por lo que se debería asociar otro tipo de analgésico para controlar el dolor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23756, 9660, '2. Haloperidol, clorpromacina y midazolam son fármacos útiles para controlar la agitación del paciente terminal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23757, 9660, '3. La hidratación intravenosa alivia el sufrimiento causado por la deshidratación terminal sin prolongar la agonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23758, 9660, '4. La confusión no es frecuente en pacientes oncológicos terminales, por lo que se debe realizar un CT craneal para descartar complicaciones de su enfermedad vascular cerebral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23759, 9661, '1. El estreñimiento es un efecto secundario casi constante por lo que se debería utilizar un laxante para evitar su aparición.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23760, 9661, '2. La depresión respiratoria es un efecto secundario frecuente dada la disfunción orgánica que presentan estos pacientes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23761, 9661, '3. La morfina no tiene techo terapéutico por lo que no existe una dosis máxima que no pueda sobrepasarse si lo requiere el paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23762, 9661, '4. Se deben pautar a intervalos regulares y no sólo si el paciente presenta dolor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23763, 9662, '1. Alternar AINES a dosis plenas con paracetamol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23764, 9662, '2. Utilizar un opioide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23765, 9662, '3. Utilizar un opioide y un AINE al mismo tiempo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23766, 9662, '4. Ingresar al paciente para tratamiento endovenoso con opioide mayor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23767, 9663, '1. Broncodilatadores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23768, 9663, '2. Morfina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23769, 9663, '3. Oxigenoterapia al 35% por mascarilla.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23770, 9663, '4. Antibióticos y fisioterapia respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23771, 9664, '1. Octreótido.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23772, 9664, '2. Metoclopramida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23773, 9664, '3. Domperidona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23774, 9664, '4. Enema de limpieza.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23775, 9665, '1. Cáncer de mama con metástasis óseas, ganglionares, hepáticas y pulmonares que sólo ha recibido hormonoterapia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23776, 9665, '2. Cáncer de pulmón intervenido hace un año con recaída local y metástasis hepáticas tratadas con radioterapia y dos líneas de quimioterapia sin respuesta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23777, 9665, '3. Paciente con demencia senil y neumonía aguda que produce insuficiencia respiratoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23778, 9665, '4. Enfermo con EPOC infección bronquial que condiciona insuficiencia respiratoria global e ingreso en cuidados intensivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23779, 9666, '1. El empleo de la fisioterapia respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23780, 9666, '2. El empleo de la aspiración nasofaríngea continuada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23781, 9666, '3. La administración de anticolinérgicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23782, 9666, '4. Evitar explicar a los familiares la etiología del síntoma por el impacto emocional de la situación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23783, 9667, '1. 5 mg cada 4 horas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23784, 9667, '2. 10 mg cada 8 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23785, 9667, '3. 15 mg cada 6 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23786, 9667, '4. 30 mg cada 4 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23787, 9668, '1. Ibuprofeno + Diclofenaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23788, 9668, '2. Buprenorfina + Celecoxib.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23789, 9668, '3. Paracetamol + Codeina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23790, 9668, '4. Ácido acetil salicílico + naproxeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23791, 9669, '1. Metadona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23792, 9669, '2. Meperidina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23793, 9669, '3. Fentanilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23794, 9669, '4. Tramadol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23795, 9670, '1. Sonda nasogástrica, aspiración contínua, sueroterapia intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23796, 9670, '2. Administración de Vitamina grupo B, laxantes y enema de limpieza.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23797, 9670, '3. Morfina, buscapina y haloperidol por vía subcutánea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23798, 9670, '4. Dieta absoluta y sueros por vía subcutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23799, 9671, '1. Paciente con carcinoma de pulmón que presenta disnea que no cede tras tratamiento con oxigenoterapia, cloruro mórfico y diazepam vía oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23800, 9671, '2. Paciente con carcinoma de cabeza y cuello que presenta una úlcera maligna en contacto con la arteria carótida. Durante la realización de una cura dicha arteria sufre rotura con hemorragia masiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23801, 9671, '3. Paciente con adenocarcinoma de páncreas y metástasis hepáticas que presenta obstrucción de la vía biliar extrahepática, con ictericia franca que comienza con disminución del nivel de conciencia por encefalopatía hepática.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23802, 9671, '4. Paciente con adenocarcinoma gástrico, metástasis óseas, hepáticas y pulmonares, que presenta agitación psicomotriz sin respuesta a los neurolépticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23803, 9672, '1. La vía de elección es la oral y en la mayoría de los casos es utilizable hasta los últimos días de vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23804, 9672, '2. El manejo de los analgésicos es similar al de la insulina en pacientes diabéticos, es decir, administración regular (pautada) para evitar que aparezca el dolor y dosis de rescate (a demanda) si aparece.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23805, 9672, '3. Utilizar ocasionalmente un placebo, ya que permite valorar el predominio del componente psicológico en la génesis del dolor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23806, 9672, '4. En general, son necesarios fármacos coadyuvantes o coanalgésicos (ansiolíticos, esteroides, antidepresivos, etc.) para optimizar el control del dolor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23807, 9673, '1. Acelerar la muerte para ahorrar sufrimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23884, 9692, '2. Lorazepam.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23809, 9673, '3. No abandonar y controlar todos los síntomas del enfermo y su familia, ayudando en el proceso de pérdidas continuas y del duelo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23810, 9673, '4. Intentar mantener la vida a costa de cualquier circunstancia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23811, 9674, '1. Reiniciar antiinflamatorio no esteroideo y ácido acetilsalicílico igual, con inhibidor de la bomba de protones 2 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23812, 9674, '2. Mantener inhibidor de la bomba de protones a dosis plenas, reevaluar la necesidad de antiinflamatorio no esteroideo y realizar endoscopia de control para confirmar cicatrización.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23813, 9674, '3. Cambiar inhibidor de la bomba de protones por antih2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23814, 9674, '4. Cambiar antiinflamatorio no esteroideo por paracetamol e inhibidor de la bomba de protones a demanda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23815, 9675, '1. La prescripción en cascada ocurre cuando se prescribe un fármaco para tratar síntomas originados por otro fármaco pensando que tiene una condición clínica nueva y no pensando en una reacción adversa o secundaria del fármaco inicial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23816, 9675, '2. El deterioro funcional y el aumento del riesgo de enfermedad podría considerarse algo normal con el paso de los años, pero la vejes es diversa y sus cambios están influidos por factores genéticos, ambientales o socioeconómicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23817, 9675, '3. Entre las pruebas para la detección de la fragilidad está la escala de Frail que evalúa cinco dominios: fatiga, resistencia, mide la incapacidad para bajar escaleras, la deambulación y el aumento de peso.', true, 3);
