INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23970, 9713, '4. El tratamiento de la incontinencia de urgencia con antimuscarínicos está recomendado en pacientes con deterioro cognitivo o demencia en fase grave.', true, 4);
