INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23975, 9715, '1. Se asocia a un buen número de consecuencias, como caídas, inmovilidad, discapacidad, mayor tasa de ingresos hospitalarios y de institucionalización, y mayor mortalidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23976, 9715, '2. Su detección precoz permitiría una intervención temprana para evitar sus consecuencias negativas', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23977, 9715, '3. Su prevalencia no tiene relación directa con la edad cronológica.', true, 3);
