INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23991, 9719, '1. Se produce una disminución en el número de nefronas relacionado con la edad biológica que condiciona pérdida fisiológica de función renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23992, 9719, '2. La esclerosis de los miocitos cardiacos favorece el desarrollo de insuficiencia cardiaca sistólica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23993, 9719, '3. La disminución de la masa magra y aumento de grasa favorece el acúmulo de las benzodiacepinas de larga duración.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23994, 9719, '4. El aumento de infecciones en la edad avanzada está favorecido por la inmunosenescencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23995, 9720, '1. La demencia y la depresión previas son factores precipitantes de delirium.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (23996, 9720, '2. Iniciar un tratamiento esteroideo es una causa potencial de delirium.', true, 2);
