INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24126, 9751, '"1. Incapacidad para realizar de manera independiente 4 de las siguientes actividades básicas de la vida diaria: bañarse, vestirse, asearse, trasladarse de la silla a la cama y viceversa, alimentarse y caminar.', true, 1);
