INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24146, 9756, '1. No precisa vigilancia hasta los 20 años de evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24147, 9756, '2. Debe realizarse colonoscopia con cromoendoscopia dirigida cada 3-5 años.', true, 2);
