INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24162, 9760, '1. Se considera un efecto indeseado de los cribados poblacionales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24163, 9760, '2. Se debe principalmente a la obtención de resultados falsos positivos en pruebas diagnósticas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24164, 9760, '3. Una de sus principales consecuencias es el sobretratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24165, 9760, '4. Su reducción es uno de los objetivos de la prevención cuaternaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24166, 9761, '1. La atención primaria es el entorno más favorable para detectar el consumo de tabaco, proporcionar consejo breve, facilitar la deshabituación tabáquica y promover estrategias de abandono.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24167, 9761, '2. La detección y el tratamiento de la dependencia del tabaco se considera una intervención con coste-efectividad favorable, sin repercusión en términos de coste por año de vida ganado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24168, 9761, '3. En la ayuda para dejar de fumar, la evidencia avala tanto las estrategias no farmacológicas (intervención breve o apoyo motivacional) como las estrategias farmacológicas, siendo la combinación de ambas lo más efectivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24169, 9761, '4. Los fumadores que no desean intentar el abandono del tabaco pueden carecer de la información adecuada sobre sus efectos nocivos, tener creencias erróneas o estar desmoralizados por haber tenido recaídas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24170, 9762, '1. A partir de los 40 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24171, 9762, '2. A partir de los 50 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24172, 9762, '3. A partir de los 60 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24173, 9762, '4. A partir de los 65 años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24174, 9763, '1. Parche cutáneo de nicotina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24175, 9763, '2. Bupropión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24176, 9763, '3. Vareniclina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24177, 9763, '4. Cigarrillo electrónico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24178, 9764, '1. Prevención primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24179, 9764, '2. Prevención secundaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24180, 9764, '3. Prevención terciaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24181, 9764, '4. Prevención cuaternaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24182, 9765, '1. Optimizar el tratamiento de la hipertensión arterial, ya que está mal controlado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24183, 9765, '2. Optimizar el tratamiento hipolipemiante, ya que está mal controlado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24184, 9765, '3. Añadir un fármaco para la diabetes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24185, 9765, '4. Abandonar el hábito tabáquico, caminar a diario y perder peso.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24186, 9766, '1. Suspender el tratamiento con acenocumarol y administrar 10 mg de vitamina K en infusión intravenosa lenta, que se repetirá cada 12 horas si fuera necesario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24187, 9766, '2. Suspender el acenocumarol y remitir al paciente a un centro hospitalario para vigilar la aparición de sangrado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24188, 9766, '3. Suspender temporalmente el acenocumarol y reanudar la anticoagulación cuando se haya alcanzado el intervalo terapéutico, calculando de nuevo la dosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24189, 9766, '4. Iniciar la administración de concentrado de complejo de protrombina o plasma fresco congelado según el peso', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24190, 9767, '1. Se recomienda tomar la presión arterial anualmente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24191, 9767, '2. Se recomienda tomar la presión arterial cada dos años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24192, 9767, '3. Se recomienda tomar la presión arterial cada tres años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24193, 9767, '4. Se recomienda tomar la presión arterial cada cuatro años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24194, 9768, '1. Averiguar: preguntar sobre los factores y las conductas de riesgo (preguntar a la paciente si fuma).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24195, 9768, '2. Aumentar: incrementar la percepción de riesgo para facilitar el cambio (explicar las consecuencias del tabaquismo).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24196, 9768, '3. Aconsejar: dar consejos claros, específicos y personalizados (aconsejar el abandono del tabaco).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24197, 9768, '4. Acordar: pactar colaborativamente los objetivos de cambio (valorar la disponibilidad para hacer un intento de dejar de fumar).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24198, 9769, '1. Precontemplación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24199, 9769, '2. Postcontemplación.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24200, 9769, '3. Acción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24201, 9769, '4. Mantenimiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24202, 9770, '1. Establecer un plan de protección y huida en mujeres víctimas de maltrato con hijos pequeños a su cargo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24203, 9770, '2. Actividades educativas con mujeres embarazadas y sus parejas sobre relaciones de igualdad y corresponsabilidad en la crianza.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24204, 9770, '3. Realizar un protocolo de cribado rutinario en las mujeres que acuden a los servicios de urgencia hospitalarios por crisis de ansiedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24205, 9770, '4. Notificación precoz a la autoridad judicial ante cualquier sospecha de maltrato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24206, 9771, '1. Retrasar la aparición de la enfermedad', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24207, 9771, '2. Disminuir la iatrogenia evitando las intervenciones médicas innecesarias', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24208, 9771, '3. Evitar la aparición de la enfermedad', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24209, 9771, '4. Disminuir el gasto del cuidado de las enfermedades', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24210, 9772, '1. El cribado del cáncer de colon dirigido al segmento poblacional de 50-69 años mediante el test de sangre oculta en heces.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24211, 9772, '2. El cribado del cáncer de próstata en hombres sanos mediante la prueba del PSA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24212, 9772, '3. Iniciar un estudio diagnóstico a las personas que acuden a la consulta por presentar microhematuria persistente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24213, 9772, '4. Iniciar un estudio diagnóstico a las personas que acuden a la consulta por presentar tos crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24214, 9773, '1. La principal causa de muerte relacionada con el tabaco son las neoplasias malignas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24215, 9773, '2. En promedio, uno de cada tres fumadores morirá de forma prematura como consecuencia del tabaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24216, 9773, '3. El tabaco aumenta el riesgo de cáncer de vejiga.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24217, 9773, '4. Los que suspenden el tabaquismo tienen una tasa de mortalidad por cáncer de pulmón casi del 50% menor a los 10 años que los sujetos que continúan el consumo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24218, 9774, '1. Cribado simple, no selectivo, precoz.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24219, 9774, '2. Cribado simple, selectivo, precoz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24220, 9774, '3. Cribado múltiple, no selectivo tardío.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24221, 9774, '4. Cribado múltiple, selectivo, precoz.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24222, 9774, '5. Cribado simple, selectivo, tardío.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24223, 9775, '1. El complejo QRS representa la repolarización de los ventrículos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24224, 9775, '2. La onda T indica la despolarización completa del músculo ventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24225, 9775, '3. La onda P corresponde a la despolarización de las aurículas antes de la contracción auricular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24226, 9775, '4. El electrodo ubicado cerca de la base del corazón registra una positividad durante la despolarización ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24227, 9776, '1. Edad, sexo, tabaco, presión arterial sistólica, colesterol total y colesterol LDL.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24228, 9776, '2. Edad, sexo, tabaco, presión arterial sistólica, colesterol total y lipoproteína A.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24229, 9776, '3. Edad, sexo, tabaco, presión arterial sistólica, colesterol total y colesterol HDL.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24230, 9776, '4. Edad, sexo, tabaco, presión arterial sistólica, colesterol total, lipoproteína A, triglicéridos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24231, 9777, '1. Hay que optimizar el tratamiento antihipertensivo porque los niveles de presión arterial están por encima de los niveles objetivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24232, 9777, '2. Hay que optimizar el tratamiento hipolipemiante porque los niveles de colesterol LDL están por encima de los niveles objetivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24233, 9777, '3. Tanto los niveles de presión arterial como los niveles de colesterol-LDL se encuentran dentro del rango objetivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24234, 9777, '4. Hay que optimizar el tratamiento de la presión arterial y el tratamiento hipolipemiante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24236, 9778, '2. Acenocumarol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24237, 9778, '3. Ácido acetilsalicílico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24238, 9778, '4. Enalapril.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24239, 9779, '1. Inhibidores del enzima dipeptidil peptidasa 4 (iDPP4).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24240, 9779, '2. Glitazonas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24241, 9779, '3. Sulfonilureas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24242, 9779, '4. Análogos del receptor Glucagon Like Peptid 1 (arGLP1).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24243, 9780, '1. Se debe intensificar el tratamiento hipolipemiante hasta el objetivo terapéutico (LDL < 55 mg/dl).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24244, 9780, '2. Su perfil lipídico es adecuado dado que tiene un colesterol total inferior a 200 mg/dl.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24245, 9780, '3. Su perfil lipídico es adecuado porque su HDL es elevado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24246, 9780, '4. Al dejar de fumar y ser mujer su riesgo es bajo y no hace falta insistir en optimizar su perfil lipídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24247, 9781, '1. Es un factor de riesgo independiente para la enfermedad vascular aterosclerótica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24248, 9781, '2. Las concentraciones plasmáticas elevadas habitualmente son de origen genético.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24249, 9781, '3. El tratamiento con dieta y ejercicio reduce las concentraciones plasmáticas de la lipoproteína en un 25 %.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24250, 9781, '4. Dado que es un factor heredable habitualmente sólo se necesita medir una vez en la vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24251, 9782, '1. El primer escalón es conseguir un control adecuado de su diabetes para corregir la hipertrigliceridemia y añadir una estatina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24252, 9782, '2. Aunque el control de la diabetes es necesario, no influye en la hipertrigliceridemia. El primer escalón es añadir ácidos grasos omega-3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24253, 9782, '3. La primera opción de tratamiento es combinar gemfibrozilo con una estatina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24254, 9782, '4. La primera opción es iniciar tratamiento con fibratos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24255, 9783, '1. Dislipemia secundaria a un síndrome nefrótico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24256, 9783, '2. Hipercolesterolemia familiar heterocigota.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24257, 9783, '3. Hipercolesterolemia familiar homocigota.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24258, 9783, '4. Hipercolesterolemia familiar recesiva por afectación del gen LDLRAP1.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24259, 9784, '1. Dos criterios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24260, 9784, '2. Tres criterios.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24261, 9784, '3. Cuatro criterios.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24262, 9784, '4. Cinco criterios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24263, 9785, '1. Disbetalipoproteinemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24264, 9785, '2. Hipercolesterolemia familiar heterocigota.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24265, 9785, '3. Hiperlipemia familiar combinada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24266, 9785, '4. Hipercolesterolemia poligénica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24267, 9786, '1. Se trata de una hipercolesterolemia secundaria a colestasis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24268, 9786, '2. Es imprescindible realizar un test genético para descartar una hipercolesterolemia familiar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24269, 9786, '3. Dados los niveles de colesterol total y de colesterol LDL se trata de una hipercolesterolemia familiar homocigota.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24270, 9786, '4. La eliminación del colesterol es fundamentalmente renal, por lo que hay que excluir una causa primaria de hipercolesterolemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24271, 9787, '1. El diagnóstico puede realizarse mediante un análisis genético.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24272, 9787, '2. En caso de confirmarse la entidad en el paciente, debemos realizar estudio genético a todos los familiares de primer grado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24273, 9787, '3. Podría beneficiarse de iniciar tratamiento con un fármaco inhibidor de PCSK9.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24274, 9787, '4. Es fundamental el control de todos los factores de riesgo cardiovascular debido a la asociación de esta patología con eventos cardiovasculares precoces.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24275, 9788, '1. Hipercolesterolemia familiar heterocigota.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24276, 9788, '2. Disbetalipoproteinemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24277, 9788, '3. Hiperlipemia familiar combinada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24278, 9788, '4. Síndrome metabólico con hiperlipemia mixta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24279, 9789, '1. Pioglitazona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24280, 9789, '2. Pentoxifilina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24281, 9789, '3. Ácido ursodesoxicólico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24282, 9789, '4. Fenofibrato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24283, 9790, '1. Insistir en cambios de estilo de vida y mantener el mismo tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24284, 9790, '2. Es prioritario aumentar el cHDL con ácido nicotínico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24285, 9790, '3. Hay que disminuir cLDL cambiando gemfibrozilo por atorvastatina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24286, 9790, '4. Retirar el betabloqueante por si altera los lípidos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24287, 9791, '1. En cuanto al colesterol LDL, el objetivo terapéutico depende del riesgo cardiovascular global.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24288, 9791, '2. Los pacientes diabéticos tipo 2 deben considerarse de alto riesgo cardiovascular y el objetivo en cuanto a colesterol LDL debe ser < 100 mg/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24289, 9791, '3. No hay evidencia suficiente de que niveles bajos de colesterol HDL supongan un factor de riesgo cardiovascular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24290, 9791, '4. Lo importante en el riesgo asociado a hipertensión arterial es que mejora cuando se reduce la presión arterial independientemente del tipo de fármaco utilizado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24291, 9792, '1. Triglicéridos > 150 mg/dL.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24292, 9792, '2. Aumento de colesterol ligado a lipoproteínas de baja densidad (LDL).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24293, 9792, '3. Hipertensión arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24294, 9792, '4. Metabolismo de la glucosa alterado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24295, 9793, '1. Tratar con estatinas hasta que se normalice el colesterol y recomendar hábito de vida saludable (dieta, ejercicio y no fumar).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24296, 9793, '2. Descartar hipotiroidismo u otra enfermedad sistémica, recomendar hábito de vida saludable y tratar con fibratos para normalizar el colesterol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24297, 9793, '3. Descartar dislipemia secundaria, tratar con resinas (resincolestiramina) y fibratos y recomendar hábito de vida saludable. Prohibir alcohol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24298, 9793, '4. Descartar dislipemia secundaria, solicitar estadio familiar y tratar con estatinas para mantener un buen perfil lipídico. Control de otros factores de riesgo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24299, 9794, '1. Se trata de una enfermedad hereditaria autosómica codominante, con una alta penetrancia, por lo que es frecuente que alguno de los progenitores y hermanos del individuo la padezcan también.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24365, 9810, '2. Bloqueador del receptor de la angiotensina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24300, 9794, '2. El trastorno genético afecta al gen que codifica el receptor del LDL colesterol y se han descrito más de 900 mutaciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24301, 9794, '3. El trastorno genético afecta también a la síntesis de los triglicéridos, provocando en las fases avanzadas de la enfermedad, un incremento de los mismos, que suele ser superior a los 500 mg/dl.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24302, 9794, '4. Los varones no tratados tienen una probabilidad cercana al 50% de sufrir un evento coronario antes de los 60 años de edad, y las mujeres con la enfermedad presentan una prevalencia de cardiopatía isquémica superior a la de la población general femenina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24303, 9795, '1. Aumento de la TSH.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24304, 9795, '2. Aumento de la CPK (Creatinfosfoquinasa).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24305, 9795, '3. Aumento de las transaminasas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24306, 9795, '4. Artralgias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24307, 9796, '1. Hipertrigliceridemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24308, 9796, '2. Hipertensión arterial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24309, 9796, '3. Hiperglucemia en ayunas', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24310, 9796, '4. Aumento de la concentración plasmática de colesterol-LDL.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24311, 9797, '1. Concentraciones de colesterol entre 175-250 mg/dl., a expensas de HDL, un hermano/a afecto/a de hipercolesterolemia, presencia de xantomas o el 25% de los familiares de primer grado hipercolesterolémicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24312, 9797, '2. Concentraciones de colesterol superiores a 300 mg/dl a expensas de LDL, un progenitor afecto, presencia de xantomas o el 50% de los familiares de primer grado hipercolesterolémicos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24313, 9797, '3. Colesterolemia superior a 300 mg/dl y antecedentes de accidentes vasculares encefálicos en un progenitor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24314, 9797, '4. Colesterolemia superior a 500 mg/dl en más de dos familiares de primer grado junto con xantomas de hipotiroidismo.', false, 4);
