INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24424, 9825, '1. La artrosis de articulaciones interfalángicas distales tiene una clara historia familiar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24425, 9825, '2. Las dos artropatías que afectan con más frecuencia las articulaciones interfalángicas distales son: la artrosis y la artritis psoriásica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24426, 9825, '3. La artritis reumatoide debe incluirse en el diagnóstico diferencial de este caso.', true, 3);
