INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24433, 9827, '2. Realizar una prueba invasiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24434, 9827, '3. Tranquilizarle porque se trata de un riesgo combinado de bajo riesgo en todo caso.', false, 3);
