INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24436, 9828, '1. El valor de la fracción libre de la gonadotropina coriónica se encuentra disminuido en la trisomía 21.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24437, 9828, '2. Se realiza mediante la combinación de datos analíticos y ecográficos.', true, 2);
