INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24439, 9828, '4. La transonolucencia nucal debe medirse entre las 11 y 14 semanas, mediante la realización de un corte sagital y con el embrión en posición de hiperflexión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24440, 9829, '1. La ausencia de hueso nasal.', false, 1);
