INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24444, 9830, '1. Debemos asumir que la edad gestacional real son 12 semanas, reasignar una nueva FUR (Fecha de última regla) o FPP (Fecha probable de parto) y planificar el resto de los controles del embarazo en base a esta edad gestacional.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24445, 9830, '2. Seguiremos considerando que la edad gestacional real son 10 semanas, ya que coincide con la FUR de la paciente. Planificaremos el resto de los controles en función de esta edad gestacional, aunque dejaremos constancia de esta discordancia en la historia clínica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24446, 9830, '3. Ante esta discordancia solicitaremos una analítica de sangre para cuantificar la hormona β-HCG y decidir en función de sus niveles cuál es la edad gestacional real para poder planificar el resto de los controles del embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24447, 9830, '4. Solicitaremos un nuevo control ecográfico en 2 semanas para ver la evolución y diagnosticar con más certeza la edad gestacional correcta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24448, 9831, '1. Recomendar que sus hijos se hagan la serología de T. cruzi por el riesgo de transmisión transplacentaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24449, 9831, '2. Informar a la paciente del riesgo de transmisión de T. cruzi y de la actitud que se va a tomar durante el embarazo, parto y postparto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24450, 9831, '3. Recomendar que su marido se haga la serología de T. cruzi por el riesgo de haberle transmitido la enfermedad por vía sexual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24451, 9831, '4. Recomendar que sus hermanos se hagan la serología de T. cruzi por el riesgo de transmisión vectorial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24452, 9832, '1. Entre 14 y 21 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24453, 9832, '2. Entre 21 y 28 días.', true, 2);
