INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24472, 9836, '4. Amniocentesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24473, 9837, '1. Anticonceptivos orales combinados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24474, 9837, '2. Parche anticonceptivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24475, 9837, '3. Anticonceptivo inyectable con estrógeno y progestágeno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24476, 9837, '4. Dispositivo intrauterino (DIU) con levonorgestrel.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24477, 9838, '1. Se ha de ofrecer consejo contraceptivo estructurado según los criterios de elegibilidad de la Organización Mundial de la Salud (OMS), e información tanto para la prevención de embarazos no planificados, como de enfermedades de transmisión sexual (ETS).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24478, 9838, '2. Como método anticonceptivo de urgencias, las opciones recomendadas son la toma de levonorgestrel, de acetato de ulipristal o la inserción de un DIU de cobre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24479, 9838, '3. Ante la indicación de anticonceptivos orales se recomienda el cribado rutinario de trombofilia y dislipemia y citologías de control anuales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24480, 9838, '4. El riesgo de tromboembolia venosa con el consumo de anticonceptivos orales es bajo, siendo el riesgo menor en los de segunda generación, frente al mayor riesgo en los de tercera y cuarta generación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24481, 9839, '1. Le explica que, si está en amenorrea, no requiere de otro método anticonceptivo puesto que la lactancia materna es suficiente como método anticonceptivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24482, 9839, '2. Le informa que el DIU de levonogestrel está contraindicado por haber tenido una cesárea hace menos de un año.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24483, 9839, '3. Le explica que podría usar un método hormonal de sólo gestágenos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24484, 9839, '4. Le ofrece anticoncepción hormonal combinada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24485, 9840, '1. Ninguno, la lactancia materna, a través de la liberación de oxitocina, impide la gestación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24486, 9840, '2. Dispositivo intrauterino con levonorgestrel.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24487, 9840, '3. Preparados hormonales combinados con 20 microgramos de etinilestradiol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24488, 9840, '4. Preparados hormonales combinados con gestágenos de tercera generación', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24489, 9841, '1. Anticoagulación con heparina intravenosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24490, 9841, '2. Fibrinolisis intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24491, 9841, '3. Antiagregación con ácido acetilsalicílico 300 mg.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24492, 9841, '4. Evacuación quirúrgica del hematoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24493, 9842, '1. La demostración de que no aparece cáncer cervical en los vacunados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24494, 9842, '2. La demostración de que se producen anticuerpos tras la vacunación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24495, 9842, '3. La demostración de protección frente a la aparición de lesiones preneoplásicas (CIN 2/3) asociadas a los virus incluidos en la vacuna.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24496, 9842, '4. Estudios clínicos no controlados.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24497, 9843, '1. Historia personal de tromboembolismo previo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24498, 9843, '2. Diabetes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24499, 9843, '3. Mujer de menos de 35 años y fumadora.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24500, 9843, '4. Infección urinaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24501, 9844, '1. Mujer de 26 años sin citologías previas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24502, 9844, '2. Mujer de 40 años con citología y virus del papiloma humano negativos hace 3 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24503, 9844, '3. Mujer de 67 años con incontinencia urinaria de esfuerzo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24504, 9844, '4. Mujer de 22 años vacunada para el virus del papiloma humano e inicio de relaciones sexuales hace 1 año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24505, 9845, '1. Solicitar detección del virus del papiloma humano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24506, 9845, '2. Conización cervical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24507, 9845, '3. No tratar y programar nueva revisión en 6-12 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24508, 9845, '4. Tratamiento con aciclovir durante 16 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24509, 9846, '1. Hacer colposcopia. Si es normal, programar una conización.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24510, 9846, '2. Confirmar la citología con una biopsia de cérvix bajo control colposcópico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24511, 9846, '3. Repetir citología para confirmar diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24512, 9846, '4. Hacer tipaje de virus HPV. Realizar conización si el test de HPV es positivo a virus de alto riesgo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24513, 9847, '1. Repetir la citología en 1 mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24514, 9847, '2. Colposcopia con eventual biopsia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24515, 9847, '3. Histerectomía con salpinguectomía bilateral y conservación de ovarios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24516, 9847, '4. Legrado uterino fraccionado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24517, 9848, '1. Sólo el 20% de las mujeres sexualmente activas se infectará por este virus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24518, 9848, '2. La mayoría de las mujeres infectadas desarrollarán displasia cervical o cáncer.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24519, 9848, '3. No se ha demostrado que otros cofactores como el tabaco o una respuesta inmunitaria alterada estén relacionados con el desarrollo de displasia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24520, 9848, '4. El virus es transitorio en la mayoría de las mujeres.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24521, 9849, '1. Genotipo 16.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24522, 9849, '2. Genotipo 11.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24523, 9849, '3. Genotipo 6.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24524, 9849, '4. Genotipo 55.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24525, 9850, '1. Tabaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24526, 9850, '2. Infección por ciertas cepas de virus del papiloma humano.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24527, 9850, '3. Multiparidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24528, 9850, '4. Antecedente de displasia vaginal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24529, 9851, '1. Cáncer de ovario no tributario de cirugía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24530, 9851, '2. Cáncer de vagina recidivado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24531, 9851, '3. Cáncer de cuello uterino localmente avanzado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24532, 9851, '4. Tras tratamiento quirúrgico por cáncer de endometrio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24533, 9852, '1. Histerectomia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24534, 9852, '2. Vacunación para el virus del papiloma humano (HPV).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24535, 9852, '3. Seguimiento citológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24536, 9852, '4. Conización cervical.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24537, 9853, '1. Tamaño tumoral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24538, 9853, '2. Afectación ganglionar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24539, 9853, '3. Permeabilidad vascular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24540, 9853, '4. Vaginitis de repetición.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24541, 9854, '1. Infección por virus del papiloma humano (HVP).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24542, 9854, '2. El consumo de tabaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24543, 9854, '3. Utilización de tratamiento hormonal sustitutivo en la menopausia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24544, 9854, '4. Infección por herpes virus tipo II.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24545, 9855, '1. Se presenta en mujeres jóvenes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24546, 9855, '2. Clínicamente se caracteriza por la presencia de hirsutismo, acné y amenorrea u oligomenorrea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24547, 9855, '3. Se asocia a obesidad y resistencia a la insulina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24548, 9855, '4. Aumenta el riesgo de cáncer de ovario.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24549, 9856, '1. Hiperandrogenismo clínico y/o analítico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24550, 9856, '2. Resistencia a la insulina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24551, 9856, '3. Oligo y/o anovulación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24552, 9856, '4. Ovarios poliquísticos definidos por ecografía (12 o más folículos por ovario).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24553, 9857, '1. Existe un mayor riesgo a largo plazo de desarrollar diabetes mellitus y carcinoma endometrial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24554, 9857, '2. Clínicamente, es típico en este síndrome la polimenorrea. obesidad e hirsutismo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24555, 9857, '3. Habitualmente la concentración sérica de FSH es mayor que la de LH.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24556, 9857, '4. No existe una imagen ecográfica ovárica característica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24557, 9858, '1. Fecundación in vitro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24558, 9858, '2. Inseminación artificial intraconyugal (IAC).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24559, 9858, '3. Metformina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24560, 9858, '4. Pérdida de peso.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24561, 9859, '1. Historia clínica familiar pormenorizada ya que lo más importante son los antecedentes familiares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24562, 9859, '2. Estudio ecográfico ginecológico con tecnología tridimensional y biopsia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24563, 9859, '3. Valoración clínica, estudio hormonal (andrógenos, FSH y LH) y ecografía ginecológica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24564, 9859, '4. Un escáner para estudiar de forma resolutiva los ovarios y estudio hormonal completo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24565, 9860, '1. En su caso está indicado el THM al menos hasta los 50 años si no aparecen contraindicaciones, porque el beneficio supera el riesgo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24566, 9860, '2. Puede obtener beneficio de la THM, pero la duración del tratamiento no debe superar los cinco años por el riesgo de cáncer de mama que tendría prolongarlo más.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24567, 9860, '3. La THM no tiene indicación en su caso al no presentar sintomatología vasomotora (sofocos) ni otros síntomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24644, 9879, '4. Cada 12 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24858, 9933, '2. Olanzapina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24568, 9860, '4. La THM no tiene indicación en su caso por no presentar sofocos, pero puede utilizar estrógenos locales para prevenir la sequedad vaginal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24569, 9861, '1. Benzodiacepinas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24570, 9861, '2. Estrógenos vaginales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24571, 9861, '3. Estrógenos y progestágenos orales en pauta continua.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24572, 9861, '4. Estrógenos transdérmicos en pauta continua.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24573, 9862, '1. Los estrógenos vaginales son un tratamiento farmacológico eficaz para los síntomas urogenitales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24574, 9862, '2. Las dosis de estrógenos administrados en la terapia hormonal deben alcanzar niveles plasmáticos similares o superiores a los alcanzados en un ciclo menstrual normal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24575, 9862, '3. La tibolona es un fármaco indicado en mujeres con antecedentes de cáncer de mama y clínica vasomotora intensa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24576, 9862, '4. En mujeres con útero, está indicada la terapia hormonal sistémica con sólo estrógenos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24577, 9863, '1. El nivel en sangre de testosterona libre es predictor del éxito terapéutico de la administración exógena de andrógenos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24578, 9863, '2. El uso de estrógenos orales combinados con gestágenos vaginales es el tratamiento más eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24579, 9863, '3. La terapia estrogénica local en la vagina con preparados de dosis baja no precisa de combinación con gestágenos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24580, 9863, '4. La terapia con lubricantes vaginales reduce la dispareunia y las infecciones urinarias secundarias a la atrofia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24581, 9864, '1. LH normal y Progesterona elevada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24582, 9864, '2. F.S.H. normal y Estradiol alto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24583, 9864, '3. F.S.H. elevado y Estradiol bajo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24584, 9864, '4. Delta 4 Androstendiona alta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24585, 9865, '1. El raloxifeno reduce la incidencia de cáncer de mama invasor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24586, 9865, '2. El raloxifeno ejerce una acción agonista estrogénica sobre el hueso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24587, 9865, '3. El raloxifeno incrementa el riesgo de cáncer de endometrio.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24588, 9865, '4. El raloxifeno no disminuye la aparición de sofocos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24589, 9866, '1. La metformina es el fármaco más usado, puede disminuir los niveles de vitamina B 12 y hay que vigilar el filtrado glomerular, si desciende por debajo de 30 ml/min hay que suspenderla.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24590, 9866, '2. Los iSGLT2 bajan peso y minimizan la progresión de la Enfermedad Renal Crónica y la Albuminuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24591, 9866, '3. Los iDPP4 pueden disminuir la glicada entre 0,6-0,9 %, tienen un efecto neutro sobre el peso pero son mal toleradas y se desaconsejan en los pacientes mayores.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24592, 9866, '4. La tirzepatida (agonista dual GIP + aGLP1) ha demostrado bajadas de peso importante y beneficio en la esteatosis hepática asociada a disfunción metabólica (MASH).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24593, 9867, '1. Insulina basal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24594, 9867, '2. Pioglitazona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24595, 9867, '3. Inhibidor de DPP-4 (sitagliptina).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24596, 9867, '4. Inhibidor de SGLT2 (empaglifozina).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24597, 9868, '1. 70-180 mg/dL.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24598, 9868, '2. 70-140 mg/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24599, 9868, '3. 63-140 mg/dL.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24600, 9868, '4. 60-130 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24601, 9869, '1. Pielonefritis crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24602, 9869, '2. Nefroesclerosis.', false, 2);
