INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24636, 9877, '4. < 220 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24637, 9878, '1. El control glucémico intensivo en el periodo perioperatorio por lo común se acompaña de mejoría en los resultados.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24638, 9878, '2. Las cifras de glucemia deseadas se situarán entre 100 y 180 mg/100mL en el periodo perioperatorio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24639, 9878, '3. Si el control glucémico es muy deficiente (HbA1c >9 %) debería intentarse su optimización antes de la cirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24640, 9878, '4. La optimización del control glucémico perioperatorio reduce las infecciones y, en pacientes quirúrgicos críticos, puede reducir la mortalidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24641, 9879, '1. Cada 3 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24642, 9879, '2. Cada 6 meses.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24645, 9880, '1. Practicar una curva de glucemia con 75 g de glucosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24646, 9880, '2. Reúne ya criterios diagnósticos de diabetes mellitus.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24647, 9880, '3. Solicitar una determinación de insulinemia basal o péptido C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24648, 9880, '4. Solicitar una determinación de hemoglobina glicosilada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24649, 9881, '1. Sulfonilurea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24650, 9881, '2. Insulina basal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24651, 9881, '3. Glitazona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24652, 9881, '4. Inhibidor de SGLT2.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24653, 9882, '1. Metformina (biguanida).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24654, 9882, '2. Pioglitazona (tiazolidindiona).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24655, 9882, '3. Canagliflozina (inhibidor del cotransportador 2 de sodio-glucosa- iSGLT2).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24656, 9882, '4. Liraglutida (agonista del receptor para GLP-1).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24657, 9883, '1. Por ser habitual en tumores abdominales de pequeño tamaño y crecimiento rápido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24658, 9883, '2. Porque los niveles plasmáticos de proinsulina, insulina y péptido C están suprimidos durante la hipoglucemia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24659, 9883, '3. Porque los niveles de IGFI están característicamente elevados y la ratio IGFII/IGFI es anormalmente baja.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24660, 9883, '4. Porque la hipoglucemia tumoral es una de las complicaciones más frecuentes en neoplasias hematológicas en ausencia de caquexia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24661, 9884, '1. La glucosa del alimento desde el intestino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24662, 9884, '2. La glucogenólisis hepática.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24663, 9884, '3. La gluconeogénesis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24664, 9884, '4. La glucogenólisis muscular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24665, 9885, '1. Suspendería antidiabéticos orales y pautaría insulinoterapia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24666, 9885, '2. Continuaría con metformina a dosis altas y añadiría insulina de acción lenta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24667, 9885, '3. Mantendría vildagliptina, pero suspendería metformina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24668, 9885, '4. Continuaría con igual tratamiento, ya que el paciente estaba bien controlado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24669, 9886, '1. Inhibidores DPP4.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24670, 9886, '2. Análogos GLP1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24671, 9886, '3. Insulina basal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24672, 9886, '4. lnhibidores SGLT2.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24673, 9887, '1. Pioglitazona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24674, 9887, '2. Pentoxifilina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24675, 9887, '3. Ácido ursodesoxicólico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24676, 9887, '4. Fenofibrato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24677, 9888, '1. Cursa con una osmolaridad plasmática eficaz >320 mOsm/Kg.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24678, 9888, '2. Implica siempre la necesidad de tratamiento con insulina tras su curación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24679, 9888, '3. Precisa un importante aporte de bicarbonato para su tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24680, 9888, '4. Es una forma habitual de presentación de la diabetes juvenil.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24681, 9889, '1. Suele asociarse a obesidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24682, 9889, '2. Puede asociarse a otras enfermedades endocrinas autoinmunes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24683, 9889, '3. Es más frecuente que la tipo 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24684, 9889, '4. Suele controlarse inicialmente con antidiabéticos orales, aunque puede necesitar insulina con el tiempo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24685, 9890, '1. Revisar la distribución de hidratos de carbono de su dieta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24686, 9890, '2. Suspender la metformina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24687, 9890, '3. Suspender la sulfonilurea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24688, 9890, '4. Sustituir la metformina por un inhibidor de la DPP4.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24689, 9891, '1. Ibuprofeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24690, 9891, '2. Oxicodona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24691, 9891, '3. Duloxetina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24692, 9891, '4. Paracetamol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24693, 9892, '1. Insulina glargina subcutánea 8 U al día.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24694, 9892, '2. Metformina oral a dosis de 850 mg cada 12 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24695, 9892, '3. Glibenclamida oral 10 mg al día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24696, 9892, '4. Pioglitazona 15 mg al día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24697, 9893, '1. Introducción de análogo de insulina de acción prolongada por mal control metabólico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24698, 9893, '2. Ingesta de alcohol superior a 50 g/día de forma habitual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24699, 9893, '3. Realización de TC con contraste intravenoso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24700, 9893, '4. Cuadro diarreico con elevación de Cr plasmática a 2,5 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24701, 9894, '1. Se realizarán todas aquellas pruebas que puedan aportar luz al proceso sospechado por el médico cubriendo el más amplio diagnóstico diferencial desde el comienzo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24702, 9894, '2. Es importante pensar en primer lugar en lo más corriente, para sólo después, una vez descartadas con certeza las entidades más frecuentes, considerar lo raro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24703, 9894, '3. Algunas pruebas complementarias pueden ser redundantes y no aportar valor al proceso diagnóstico, pero si al coste sanitario. Así, ante dos pruebas complementarias de rendimiento similar, se decidirá siempre por la más económica y de menor riesgo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24704, 9894, '4. Es imprescindible que el médico no añada nuevas incomodidades con la práctica de exploraciones complementarias que no sean estrictamente necesarias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24705, 9895, '1. Administración de metformina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24706, 9895, '2. Prescribir una sulfonilurea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24707, 9895, '3. Cambios conductuales: Dieta y ejercicio físico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24708, 9895, '4. Insulina antes de cada comida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24709, 9896, '1. Aumentar la ingesta de proteínas e hidratos de carbono de cadena larga en la dicta para mejorar la astenia y la perdida de peso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24710, 9896, '2. Asociar al tratamiento una dosis de insulina basal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24711, 9896, '3. Sustituir la sitagliptina por pioglitazona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24712, 9896, '4. Sustituir la metformina por glimepirida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24713, 9897, '1. Conseguir unos niveles óptimos de hemoglobina AlC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24714, 9897, '2. Conseguir un óptimo control de la presión arterial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24715, 9897, '3. Abandonar el tabaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24716, 9897, '4. Conseguir unos niveles óptimos de LDL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24717, 9898, '1. Conseguir un óptimo control de la presión arterial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24718, 9898, '2. Conseguir unos niveles óptimos de hemoglobina A1C.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24719, 9898, '3. Abandonar el tabaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24720, 9898, '4. Conseguir unos niveles de LDL inferiores a 100 mg/dl.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24721, 9899, '1. Infección urinaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24722, 9899, '2. Encamamiento por fractura.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24723, 9899, '3. Insuficiencia renal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24724, 9899, '4. Estrés psíquico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24725, 9900, '1. Suero fisiológico iv rápido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24726, 9900, '2. Suero glucosado 5 % iv cuando la glucemia sea menor de 250 mg/dl.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24727, 9900, '3. Cloruro potásico 100 mEq / día diluido en los sueros.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24728, 9900, '4. Bicarbonato sódico 1M 100 cc iv en 30 minutos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24729, 9901, '1. Coma hiperglucémico hiperosmolar no cetósico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24730, 9901, '2. Insuficiencia cardiaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24731, 9901, '3. Insuficiencia renal de causa obstrutiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24732, 9901, '4. Cetoacidosis diabética con coma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24733, 9902, '1. Ayuno prolongado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24734, 9902, '2. Hipoglucemia reactiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24735, 9902, '3. Insulinoma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24736, 9902, '4. Iatrogénica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24737, 9903, '1. Mantener la tensión arterial por debajo de 110/70 mmHg.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24738, 9903, '2. Abandono del hábito tabáquico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24739, 9903, '3. Mantener un índice de masa corporal (IMC) menor de 21.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24740, 9903, '4. Realizarse glucemia capilar basal a diario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24741, 9904, '1. Ecocardiograma transtorácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24742, 9904, '2. Determinación de microalbuminuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24743, 9904, '3. Índice tobillo-brazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24744, 9904, '4. Determinación de hemoglobina glicosilada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24745, 9905, '1. Es una cetoacidosis diabética. Hay que tratar con insulina endovenosa, sueroterapia. medidas generales y buscar causa precipitante.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24746, 9905, '2. Debut de diabetes tipo 1 con cetoacidosis. Tratar con bicarbonato y tras corregir la acidosis añadir insulina endovenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24747, 9905, '3. Parece una cetoacidosis diabética, pero podría ser alcohólica. Se debe determinar la alcoholemia antes de iniciar tratamiento con insulina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24748, 9905, '4. Tratar con insulina rápida subcutánea, sueroterapia y pedirle que beba líquidos en abundancia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24749, 9906, '1. Es determinante el aumento del umbral renal de glucosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24750, 9906, '2. Existe una reducción en la producción de acetoacetato hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24751, 9906, '3. Aumenta el aporte de ácidos grasos libres al hígado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24752, 9906, '4. Existe una reducción en los niveles de las hormonas de contra regulación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24753, 9907, '1. Suele presentar respiración de Kussmaul.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24754, 9907, '2. Implica la necesidad de posterior tratamiento con insulina al solucionarse el cuadro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24755, 9907, '3. Tiene un elevado riesgo de mortalidad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24756, 9907, '4. Para su diagnóstico es necesaria la existencia de una osmolaridad eficaz superior a 280.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24757, 9908, '1. Rosiglitazona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24758, 9908, '2. Sulfonilureas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24759, 9908, '3. Repaglinida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24760, 9908, '4. Metformina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24761, 9909, '1. Continuar con metformina, realizar controles de glucemia y añadir bolos de insulina rápida si la glucemia es elevada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24762, 9909, '2. Intentar controlar la glucemia combinando metformina y otros antidiabéticos orales para evitar a toda costa la utilización de insulina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24763, 9909, '3. Retirar la metformina. administrar una pauta de insulina y programar rescate según los controles de glucemia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24764, 9909, '4. Retirar todos los antidiabéticos orales y administrar bolos de insulina rápida cada seis horas según los controles de glucemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24765, 9910, '1. La macroangiopatía.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24766, 9910, '2. Las complicaciones renales glomerulares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24767, 9910, '3. Infecciones cutáneas purulentas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24768, 9910, '4. La cetoacidosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24769, 9911, '1. Metformina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24770, 9911, '2. Dieta estricta hipocalórica e inhibidores de la alfaglucosidasa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24771, 9911, '3. Insulinoterapia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24772, 9911, '4. Empleo de dos antidiabéticos orales, o un antidiabético oral cualquiera asociado a insulina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24773, 9912, '1. Comenzar tratamiento con metformina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24774, 9912, '2. Modificaciones intensivas de su estilo de vida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24775, 9912, '3. Repetir test de tolerancia a la glucosa al año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24776, 9912, '4. Comenzar tratamiento con sulfonilureas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24777, 9913, '1. Las tiazolidindionas bloquean la α-glucosidasa intestinal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24778, 9913, '2. La metformina reduce la producción hepática de glucosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24779, 9913, '3. No pueden asociarse a la administración de insulina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24780, 9913, '4. Con glibenclamida el riesgo de hipoglicemias es mínimo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24781, 9914, '1. Distal, bilateral, simétrica y motora.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24782, 9914, '2. Distal, unilateral y motora.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24783, 9914, '3. Distal, bilateral, simétrica y sensitiva.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24784, 9914, '4. Proximal, bilateral, simétrica y sensitiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24785, 9915, '"1. La mononeuropatía craneal más frecuente es la afectación del VII par.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24786, 9915, '2. En la afectación del III par craneal se suele conservar la motilidad pupilar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24787, 9915, '3. Una afectación frecuente es la presencia de ""síndrome del túnel carpiano""''.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24788, 9915, '4. El componente sensitivo es el más frecuente afectado en la polineuropatía diabética."', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24789, 9916, '1. Glucemia en ayunas entre 110 y 125 mg/dL.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24790, 9916, '2. Glucemia tras sobrecarga oral de glucosa mayor de 200 mg/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24791, 9916, '3. Glucemia tras sobrecarga oral de glucosa entre 140 y 199 mg/dL.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24792, 9916, '4. Glucemia en ayunas mayor de 125 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24793, 9917, '1. Es la forma de inicio de la retinopatía en pacientes diabéticos mal controlados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24794, 9917, '2. Es frecuente que provoque hemorragias de vitreo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24795, 9917, '3. Se caracteriza por la presencia de microaneurismas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24796, 9917, '4. Suele aparecer después de los 60 años de edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24797, 9918, '1. Repetir la glucemia en ayunas o realizar test tolerancia oral a la glucosa para confirmar el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24798, 9918, '2. Lo ideal es empezar un tratamiento combinado con acarbosa y metformina a dosis plenas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24799, 9918, '3. Inicialmente debemos pautar tratamiento dietético y ejercicio físico, valorando añadir algún fármaco según la evolución posterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24800, 9918, '4. En este momento lo más adecuado es iniciar insulinoterapia junto con tratamiento dietético y modificación en el estilo de vida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24801, 9919, '1. Los anticuerpos antidecarboxilasa del ácido glutámico son un marcador precoz de la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24802, 9919, '2. Los virus son capaces de iniciar el proceso de destrucción de la célula beta propio de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24803, 9919, '3. No existe alteración en la secreción de la insulina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24804, 9919, '4. Existe un aumento en la producción hepática de glucosa en ayunas y postingesta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24805, 9920, '1. El litio es altamente eficaz para reducir las tasas de suicidio.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24806, 9920, '2. El riesgo de malformaciones congénitas en recién nacidos es mayor cuando las madres reciben tratamiento con litio que cuando lo hacen con ácido valproico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24807, 9920, '3. El tratamiento con litio durante 10-20 años puede provocar una hepatopatía crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24808, 9920, '4. El litio es más eficaz que los fármacos anticonvulsivos para el tratamiento de los episodios mixtos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24809, 9921, '1. Trastorno de depresión mayor con características psicóticas congruentes con el estado de ánimo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24810, 9921, '2. Esquizofrenia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24811, 9921, '3. Trastorno esquizotípico de la personalidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24812, 9921, '4. Trastorno Bipolar I, episodio actual maniaco, con características psicóticas congruentes con el estado de ánimo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24813, 9922, '1. Hay una asociación sólida y dependiente de la dosis entre consumo de cannabis de alta potencia y el desarrollo posterior de esquizofrenia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24814, 9922, '2. Los pacientes con trastorno por consumo de alcohol presentan pocos trastornos psiquiátricos comórbidos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24815, 9922, '3. El tratamiento farmacológico principal de la abstinencia alcohólica son las benzodiacepinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24816, 9922, '4. El consumo de cocaína aumenta el riesgo de eventos adversos cardiovasculares.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24817, 9923, '1. Este tipo de psicosis es una urgencia psiquiátrica que requiere hospitalización.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24818, 9923, '2. Antes de realizar el diagnóstico psiquiátrico, es necesario descartar organicidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24819, 9923, '3. La aparición típica de los síntomas se produce a partir de la cuarta semana después del parto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24820, 9923, '4. Entre los tratamientos indicados se encuentran los antipsicóticos y el TEC.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24821, 9924, '1. Presentan un patrón de relaciones interpersonales estables.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24822, 9924, '2. Pueden experimentar cambios de humor repetidos y marcados a lo largo del día.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24823, 9924, '3. Es raro que se autolesionen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24824, 9924, '4. En su tratamiento tiene más peso la terapia farmacológica que la psicoterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24825, 9925, '1. Organizar un plan terapéutico ambulatorio, en el que se incluya la participación de psiquiatra y psicólogo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24826, 9925, '2. Ingresar a la paciente en una Unidad de Psiquiatría para mejorar su estado nutricional en primer lugar y posteriormente proceder al desarrollo de una psicoterapia especifica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24827, 9925, '3. Enviar cuanto antes a la paciente a consulta de un Nutricionista para realizar un plan dietético adecuado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24828, 9925, '4. Derivar a un Hospital de Día de Trastornos de la Conducta Alimentaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24829, 9926, '1. Paracetamol.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24830, 9926, '2. Diazepam.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24831, 9926, '3. Mirtazapina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24832, 9926, '4. Trazodona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24833, 9927, '1. Presencia de autolesiones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24834, 9927, '2. Aislamiento social.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24835, 9927, '3. Irritabilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24836, 9927, '4. Dificultades académicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24837, 9928, '1. Reacción aguda de estrés.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24838, 9928, '2. Reacción adaptativa depresiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24839, 9928, '3. Trastorno de estrés postraumático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24840, 9928, '4. Trastorno de ansiedad generalizada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24841, 9929, '1. Ácido valproico y terapia interpersonal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24842, 9929, '2. Lamotrigina y terapia cognitivo-conductual.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24843, 9929, '3. Litio y terapia cognitivo-conductual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24844, 9929, '4. Carbamazepina y terapia interpersonal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24845, 9930, '1. El carbonato de litio tiene un inicio de acción rápido y es efectivo en el tratamiento de la manía aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24846, 9930, '2. Los antipsicóticos atípicos como la olanzapina, quetiapina o aripiprazol son eficaces en el control de los síntomas maníacos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24847, 9930, '3. La combinación de estabilizadores del ánimo y antipsicóticos es a menudo necesaria para controlar la sintomatología grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24848, 9930, '4. Las benzodiacepinas como el lorazepam pueden utilizarse para el control de la agitación y el insomnio asociados a la manía aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24849, 9931, '1. Trastorno obsesivo-compulsivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24850, 9931, '2. Mutismo selectivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24851, 9931, '3. Fobia situacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24852, 9931, '4. Trastorno de pánico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24853, 9932, '1. Está indicada únicamente cuando han fracasado ambas formas de tratamiento por separado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24854, 9932, '2. El alivio rápido de los síntomas de ansiedad gracias a la medicación disminuye la motivación para la psicoterapia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24855, 9932, '3. Exige que un mismo profesional lleve a cabo las dos modalidades de tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24856, 9932, '4. Los resultados de la terapia combinada son superiores a los de cada una utilizada por separado.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24857, 9933, '1. Flufenazina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24859, 9933, '3. Litio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24860, 9933, '4. Carbamazepina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24861, 9934, '1. Litio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24862, 9934, '2. Valproato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24863, 9934, '3. Carbamazepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24864, 9934, '4. Clorazepato.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24865, 9935, '1. En un primer episodio en pacientes jóvenes con buena respuesta se puede suspender el tratamiento al cabo de un mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24866, 9935, '2. Se recomienda mantener el tratamiento durante un mínimo de tres meses tras la remisión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24867, 9935, '3. Se recomienda mantener el tratamiento durante un mínimo de seis meses tras la remisión.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24868, 9935, '4. Se recomienda mantener el tratamiento durante un mínimo de dos años para prevenir recaídas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24869, 9936, '1. Catalepsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24870, 9936, '2. Esquizofrenia de inicio tardío.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24871, 9936, '3. Enfermedad de Alzheimer.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24872, 9936, '4. Episodio depresivo grave con síntomas psicóticos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24873, 9937, '1. Incremento del apetito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24874, 9937, '2. Disminución de la secreción de cortisol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24875, 9937, '3. Dificultad para despertarse por la mañana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24876, 9937, '4. Empeoramiento matutino.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24877, 9938, '1. En la evolución es frecuente encontrar agorafobia y conductas de evitación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24878, 9938, '2. En el diagnóstico diferencial se deben considerar feocromocitoma, tirotoxicosis e hipoglucemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24879, 9938, '3. Es preciso descartar una taquicardia auricular paroxística.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24880, 9938, '4. El diagnóstico más probable es un trastorno por ansiedad generalizada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24881, 9939, '1. El diagnóstico es duelo (Z63.4, según la 10ª edición de la Clasificación Internacional de Enfermedades -CIE-10-).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24882, 9939, '2. Si las dificultades del sueño tienen consecuencias sobre la vigilia del día siguiente podría prescribirle temporalmente un fármaco hipnótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24883, 9939, '3. Dado el tiempo transcurrido se debería instaurar un antidepresivo a dosis bajas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24884, 9939, '4. Es conveniente darle una nueva cita al cabo de 1-2 meses para ver su evolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24885, 9940, '1. Abuso de sustancias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24886, 9940, '2. Evento estresante de larga duración.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24887, 9940, '3. Trastorno de pánico coexistente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24888, 9940, '4. Edad avanzada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24889, 9941, '1. El tratamiento habitual en las primeras 48 horas se basa en benzodiacepinas en monoterapia por vía parenteral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24890, 9941, '2. La clozapina es el fármaco de elección para el tratamiento agudo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24891, 9941, '3. La combinación de litio y antipsicóticos está contraindicada en las fases iniciales del tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24892, 9941, '4. En casos graves o resistentes puede utilizarse la terapia electroconvulsiva.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24893, 9942, '1. Es especialmente útil en trastornos psiquiátricos secundarios a la epilepsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24894, 9942, '2. Tiene una eficacia superior a la terapia electroconvulsiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24895, 9942, '3. Está indicada en la depresión resistente al tratamiento farmacológico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24896, 9942, '4. Por su seguridad, es el tratamiento de elección en la esquizofrenia de inicio tardío.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24897, 9943, '1. Benzodiacepinas de vida media larga y clometiazol.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24898, 9943, '2. Benzodiacepinas de vida media corta y betabloqueantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24899, 9943, '3. Benzodiacepinas de vida media larga y carbamacepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24900, 9943, '4. Benzodiacepinas de vida media corta y clozapina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24901, 9944, '1. La presencia de desorientación, apatía y pérdida de memoria orienta hacia el diagnóstico de demencia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24902, 9944, '2. La presencia de temblor de reposo, marcha sin balanceo y amimia facial orienta el diagnóstico hacia enfermedad de Parkinson.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24903, 9944, '3. La presencia de hipercolesterolemia, bradipsiquia, bradicardia y estreñimiento orienta hacia el diagnóstico de hipotiroidismo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24904, 9944, '4. El inicio reciente de tratamiento con betabloqueantes y antiinflamatorios no esteroideos puede justificar la aparición de un síndrome depresivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24905, 9945, '1. Trastorno obsesivo-compulsivo y trastornos relacionados.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24906, 9945, '2. Trastornos de ansiedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24907, 9945, '3. Trastornos psicosomáticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24908, 9945, '4. Trastornos del estado de ánimo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24909, 9946, '1. La hipomanía casi nunca es motivo de consulta y debe buscarse en la anamnesis de los episodios depresivos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24910, 9946, '2. El antecedente de hipomanía en un paciente con episodio depresivo mayor modifica el diagnóstico de trastorno depresivo e influye en la decisión terapéutica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24911, 9946, '3. Los pacientes con hipomanía pueden sentirse más activos y sociables, aunque generalmente su comportamiento resulta algo inapropiado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24912, 9946, '4. Estos pacientes presentar síntomas psicóticos, como ideas delirantes de grandiosidad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24913, 9947, '1. Inhibe la recaptación de noradrenalina y serotonina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24914, 9947, '2. Inhibe la recaptación de noradrenalina y dopamina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24915, 9947, '3. Es antagonista de la dopamina e inhibe la recaptación de serotonina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24916, 9947, '4. Es antagonista del glutamato e inhibe la recaptación de dopamina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24917, 9948, '1. Estreptococo viridans.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24918, 9948, '2. Estreptococo alfa-hemolítico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24919, 9948, '3. Estreptococo beta-hemolítico, grupo A.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24920, 9948, '4. Enterococo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24921, 9949, '1. Trastorno obsesivo-compulsivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24922, 9949, '2. Estrés postraumático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24923, 9949, '3. Trastorno antisocial de la personalidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24924, 9949, '4. Dependencia de alcohol.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24925, 9950, '1. Alprazolam cada 8 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24926, 9950, '2. Paroxetina a dosis bajas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24927, 9950, '3. Metilfenidato a dosis bajas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24928, 9950, '4. Amitriptilina a dosis bajas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24929, 9951, '1. Uno de los fármacos más eficaces es la clomipramina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24930, 9951, '2. La respuesta farmacológica a los inhibidores de la recaptación de serotonina es del 90%.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24931, 9951, '3. Las conductas compulsivas alivian la ansiedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24932, 9951, '4. La terapia psicológica de más utilidad para el control de síntomas es la de tipo conductual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24933, 9952, '1. Disociación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24934, 9952, '2. Reexperimentación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24935, 9952, '3. Conductas de evitación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24936, 9952, '4. Alteración del control de los impulsos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24937, 9953, '1. Trastorno psicótico breve.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24938, 9953, '2. Trastorno por ansiedad generalizada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24939, 9953, '3. Agorafobia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24940, 9953, '4. Fobia social.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24941, 9954, '1. Realizaría el diagnóstico de trastorno por déficit de atención e hiperactividad (TDAH) y le pondría tratamiento con metilfenidato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24942, 9954, '2. Analizaría la dinámica familiar para trabajar los problemas derivados de la enfermedad en la hermana y lo que esto había supuesto en el comportamiento del niño.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24943, 9954, '3. Intervendría con el colegio para que aporte información del posible acoso escolar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24944, 9954, '4. Tendría una entrevista con el niño y solicitaría información escolar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24945, 9955, '1. Trastorno por estrés anticipatorio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24946, 9955, '2. Fobia de impulsión evitativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24947, 9955, '3. Trastorno obsesivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24948, 9955, '4. Trastorno por angustia con agorafobia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24949, 9956, '1. Padece un trastorno conversivo y requiere psicoterapia analítica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24950, 9956, '2. Padece una agorafobia y requiere tratamiento con inhibidores de la monoaminooxidasa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24951, 9956, '3. Padece una fobia simple y requiere tratamiento cognitivo-conductual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24952, 9956, '4. Padece una fobia específica y no requiere tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24953, 9957, '1. Hidratación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24954, 9957, '2. Hemodiálisis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24955, 9957, '3. Lavado gástrico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24956, 9957, '4. Aminofilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24957, 9958, '1. Proceder a un ingreso hospitalario recurriendo a un internamiento involuntario si el paciente se niega a ingresar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24958, 9958, '2. Intentar tranquilizar al paciente verbalmente y con fármacos que disminuyan la agitación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24959, 9958, '3. Intentar convencer al paciente de que debe ingresar y si se niega dar el alta y recomendar acudir a su centro de salud mental.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24960, 9958, '4. Informar a la familia de la necesidad de una hospitalización para poder tratar al paciente, ya que se va a negar a tomar medicación voluntariamente por carecer de conciencia de enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24961, 9959, '1. Trastorno adaptativo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24962, 9959, '2. Trastorno por déficit de atención con hiperactividad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24963, 9959, '3. Trastorno bipolar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24964, 9959, '4. Abuso de alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24965, 9960, '1. Pueden manifestarse como estados persistentes de inquietud psicomotora y nerviosismo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24966, 9960, '2. La activación ansiosa puede alterar los niveles de cortisol y de otras hormonas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24967, 9960, '3. Pueden manifestarse como estados bruscos y rápidos de inquietud psicomotora y nerviosismo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (24968, 9960, '4. La presencia de síntomas depresivos excluye el diagnóstico de trastornos de ansiedad.', true, 4);
