INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25093, 9987, '1. La prevalencia de TOC en la población general es 2-3%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25094, 9987, '2. En adultos, la probabilidad de sufrir el TOC es igual en hombres que en mujeres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25095, 9987, '3. La alteración del sistema serotoninérgico está implicada en el TOC.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25096, 9987, '4. La terapia conductista es escasamente eficaz en el TOC.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25097, 9987, '5. Los fármacos de primera elección son los inhibidores selectivos de la recaptación de la serotonina (ISRS) o la clomipramina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25098, 9988, '1. El trastorno depresivo mayor tiene el doble de prevalencia en mujeres que en varones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25099, 9988, '2. El trastorno bipolar I tiene doble prevalencia en varones que en mujeres.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25100, 9988, '3. Los episodios maníacos son más frecuentes en los varones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25101, 9988, '4. El trastorno bipolar I es menos frecuente que el trastorno depresivo mayor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25102, 9988, '5. El trastorno bipolar I comienza más precoz- mente que el trastorno depresivo mayor.', false, 5);
