INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25104, 9989, '2. Trastornos de la personalidad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25105, 9989, '3. Esquizofrenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25106, 9989, '4. Estados confusionales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25107, 9989, '5. Trastorno obsesivo-compulsivo.', false, 5);
