INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25119, 9992, '2. Meticulosidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25120, 9992, '3. Ausencia de introspección.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25121, 9992, '4. Lentitud.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25122, 9992, '5. Compulsiones.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25123, 9993, '1. Los pacientes que sufren un trastorno obsesivo compulsivo tienen ideas obsesivas irracionales e intrusivas. Las más frecuentes son las obsesiones de limpieza', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25124, 9993, '2. Son los trastornos más comunes en la población general. Son más frecuentes en mujeres y su incidencia disminuye con la edad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25125, 9993, '3. El abuso de alcohol es una complicación grave y frecuente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25126, 9993, '4. El trastorno por estrés postraumático suele aparecer en los seis primeros meses tras el suceso traumático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25127, 9993, '5. El trastorno de ansiedad generalizada se caracteriza por la presencia de crisis de angustia, recurrentes e inesperadas y puede cursar con o sin agorafobia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25128, 9994, '1. Trastorno esquizoafectivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25129, 9994, '2. Distimia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25130, 9994, '3. Trastorno de ansiedad generalizada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25131, 9994, '4. Trastorno por estrés postraumático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25132, 9994, '5. Reacción normal frente al estrés.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25133, 9995, '1. A lo largo de la vida, aproximadamente un 15% de la población sufre un episodio depresivo mayor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25134, 9995, '2. Cerca de un 8% de los pacientes que atiende un médico de Atención Primaria podría recibir un diagnóstico de depresión mayor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25135, 9995, '3. Hasta un 15% de los casos de depresión mayor son secundarios a una enfermedad médica somática o al abuso de substancias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25136, 9995, '4. Cuando se sospecha que un paciente sufre un episodio depresivo mayor, debe evitarse hacer preguntas directas al paciente sobre ideas o proyectos suicidas, porque tal pregunta aumenta el riesgo de suicidio un 35%.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25137, 9995, '5. Cerca del 15% de los pacientes con depresión mayor que no reciben tratamiento se suicidan.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25138, 9996, '1. Esquizofrenias paranoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25139, 9996, '2. Hipocondríacos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25140, 9996, '3. Alucinosis alcohólica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25141, 9996, '4. Manías.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25142, 9996, '5. Depresiones ansiosas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25143, 9997, '1. Las benzodiacepinas son la base del tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25144, 9997, '2. El término crisis de angustia es sinónimo de trastorno de pánico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25145, 9997, '3. Entre las principales enfermedades con las que habría que realizar un diagnóstico diferencial estaría el hipertiroidismo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25146, 9997, '4. Una de sus variedades se caracteriza por presentarse en personas mayores de 45 años y acompañarse de pérdida de conocimiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25147, 9997, '5. Su presencia es un criterio diagnóstico de un episodio de depresión mayor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25148, 9998, '1. Ideas delirantes de contaminación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25149, 9998, '2. Fobia específica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25150, 9998, '3. Obsesiones de contaminación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25151, 9998, '4. Temores hipocondríacos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25152, 9998, '5. Ideas sobrevaloradas de contaminación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25153, 9999, '1. Un cuadro crónico de la hipocondria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25154, 9999, '2. La persistencia de una depresión mayor a lo largo de más de un año.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25155, 9999, '3. Un trastorno bipolar tipo II atípico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25156, 9999, '4. Un humor crónicamente deprimido (o irritable en niños y adolescentes).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25157, 9999, '5. Un síndrome de fatiga crónica, asociado a fibromialgia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25158, 10000, '1. Las benzodiacepinas son la base del tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25159, 10000, '2. El término crisis de angustia es sinónimo de trastorno de pánico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25160, 10000, '3. Entre las principales enfermedades con las que habría que realizar un diagnóstico diferencial estaría el hipertiroidismo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25161, 10000, '4. Una de sus variedades se caracteriza por presentarse en personas mayores de 45 años y acompañarse de pérdida de conocimiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25162, 10000, '5. Su presencia es un criterio diagnóstico de un episodio de depresión mayor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25163, 10001, '1. No ser creyente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25164, 10001, '2. Ser militar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25165, 10001, '3. Haber sido diagnosticado de depresión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25166, 10001, '4. Ser mujer.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25167, 10001, '5. Ser médico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25168, 10002, '1. Buspirona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25169, 10002, '2. Disulfiram.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25170, 10002, '3. Fluoxetina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25171, 10002, '4. Litio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25172, 10002, '5. Naltrexona.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25173, 10003, '1. Tras comprobar la ausencia de pulso, la reanimación cardiopulmonar básica debe realizarse siguiendo la pauta de 30 compresiones torácicas y 2 insuflaciones pulmonares.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25174, 10003, '2. En cuanto se disponga de los medios necesarios se debe realizar una cardioversión si el paciente aún no ha recuperado el pulso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25175, 10003, '3. En caso de asistolia deben administrarse 3 mg de atropina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25176, 10003, '4. La adrenalina, a dosis de 1 mg cada 3 min, no se administrará si el mecanismo de parada es una fibrilación ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25177, 10004, '1. Adrenalina porque es el fármaco inicial de elección en todas las paradas cardiacas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25178, 10004, '2. Atropina porque en los niños el ritmo electrocardiográfico más frecuente es la bradicardia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25179, 10004, '3. Bicarbonato para compensar la acidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25180, 10004, '4. Amiodarona porque lo más probable es que tenga una fibrilación ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25181, 10005, '1. Seguir con el masaje cardiaco y aislar la vía aérea mediante intubación orotraqueal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25182, 10005, '2. Conseguir un acceso venoso para administrar adrenalina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25183, 10005, '3. Cargar el desfibrilador y aplicar una descarga para continuar inmediatamente con el masaje cardiaco.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25184, 10005, '4. Avisar al centro coordinador de emergencias para que os envíen ayuda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25185, 10006, '1. Avisar a los servicios de emergencias (112) indicando localización y víctimas afectadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25186, 10006, '2. Proteger a los accidentados y a ti mismo, señalizando adecuadamente el lugar del accidente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25187, 10006, '3. Socorrer a los accidentados evitando movilizarlos bruscamente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25188, 10006, '4. Alejarte de la zona evitando que se formen aglomeraciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25189, 10007, '"1. Explorar detenidamente a cada uno de los pacientes asegurándome que están conscientes y no presentan heridas visibles.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25190, 10007, '2. Preguntar a cada paciente cómo se encuentra y considerar verdes a los que no refieran ningún dolor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25191, 10007, '3. Identificar a los que tengan una disminución del nivel de conciencia para así poder separar a los leves.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25192, 10007, '4. Gritar de forma clara: ""aquellos que puedan caminar que me sigan"" y alejarlos a una zona segura."', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25193, 10008, '1. Insertar una mascarilla laríngea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25194, 10008, '2. Canalizar una vía venosa periférica y administrar manitol intravenoso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25195, 10008, '3. Intubación endotraqueal con control de la columna cervical.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25196, 10008, '4. Oxigenoterapia con mascarilla tipo ventimask y traslado inmediato a un hospital con neurocirujano de guardia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25197, 10009, '1. En caso de continuar la FV después del 3º choque desfibrilatorio.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25198, 10009, '2. Debe aplicarse desde el inicio en RCP avanzada, cuando se detecte FV.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25199, 10009, '3. Tras el primer choque desfibrilatorio, en caso de persistencia de la FV.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25200, 10009, '4. No está indicada su administración en RCP avanzada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25201, 10010, '1. Aun en caso de asistolia debe intentarse desfibrilación como primera opción.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25202, 10010, '2. La adrenalina continúa siendo la catecolamina de elección para el tratamiento de la parada cardiaca en todos los ritmos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25203, 10010, '3. La dosis de adrenalina por vía intratraqueal es de 3 mg diluida en al menos 10 ml de agua estéril.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25204, 10010, '4. En caso de que la fibrilación ventricular/taquicardia ventricular persista tras 3 choques, debe administrarse un bolo de 300 mg de amiodarona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25205, 10011, '1. Iniciar la respiración boca a boca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25206, 10011, '2. Cateterizar una vía venosa periférica y administrar 1 mg de adrenalina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25207, 10011, '3. Asegurar que no existen cuerpos extraños en la boca, levantar la mandíbula e hiperextender la cabeza.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25208, 10011, '4. Hacer compresiones torácicas a razón de 80-100 por minuto tras colocar al paciente sobre plano duro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25209, 10012, '1. Shock distributivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25210, 10012, '2. Shock cardiogénico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25211, 10012, '3. Shock hipovolémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25212, 10012, '4. Shock obstructivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25213, 10013, '1. Recuento de leucocitos en sangre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25214, 10013, '2. Escala de coma de Glasgow.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25215, 10013, '3. Lactato en sangre.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25216, 10013, '4. pH en sangre.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25217, 10014, '1. Un punto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25218, 10014, '2. Dos puntos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25219, 10014, '3. Tres puntos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25220, 10014, '4. Cuatro puntos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25221, 10015, '1. Se debe determinar el lactato sérico como un marcador de hipoperfusión tisular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25222, 10015, '2. Se debe realizar una toma precoz (1ª hora) de muestra para cultivos e inicio de antibioterapia de amplio espectro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25223, 10015, '3. La reposición del volumen se debe realizar con cristaloides dentro de las 3 primeras horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25224, 10015, '4. Se recomienda la dopamina como el vasopresor de primera elección.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25225, 10016, '1. El control hemodinámico inmediato es fundamental para el pronóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25226, 10016, '2. Deben administrarse fluidos (cristaloides) a razón de 30 ml/kg en la primera hora de atención.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25227, 10016, '3. Debe administrarse hidrocortisona si tras el primer litro de cristaloides no se ha logrado el control hemodinámico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25228, 10016, '4. Debe iniciarse una perfusión con noradrenalina si tras la administración de fluidos no se logra control hemodinámico (tensión arterial media superior a 65 mmHg).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25229, 10017, '1. El control del foco solo se intentará una vez el paciente haya alcanzado la estabilidad hemodinámica y no dependa de vasopresores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25230, 10017, '2. El control del foco se realizará tras al menos la administración de dos dosis de antibiótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25231, 10017, '3. El control del foco se realizará tan pronto como sea posible.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25232, 10017, '4. Si la situación de shock séptico lleva más de 12 horas de evolución el control del foco ya no será beneficioso para el paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25233, 10018, '1. Adrenalina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25234, 10018, '2. Adrenalina y dexclorfeniramina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25235, 10018, '3. Adrenalina, dexclorfeniramina y metilprednisolona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25236, 10018, '4. Adrenalina, dexclorfeniramina y glucagón.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25237, 10019, '1. Requiere transfusión de sangre tipo-específica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25238, 10019, '2. Requiere transfusión de sangre de emergencia (O Rh negativo).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25239, 10019, '3. Debe prepararse una posible transfusión de sangre con pruebas cruzadas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25240, 10019, '4. Debe probarse la infusión de nuevo de otros 20 ml/kg de cristaloides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25241, 10020, '1. Perfusión intravenosa de dobutamina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25242, 10020, '2. Medición de lactato sérico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25243, 10020, '3. Extracción de hemocultivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25244, 10020, '4. Administración de fluidos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25245, 10021, '1. Dopamina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25246, 10021, '2. Noradrenalina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25247, 10021, '3. Dobutamina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25248, 10021, '4. Fenilefrina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25249, 10022, '1. Ha perdido entre un 15 y un 30 % de la volemia y precisa reposición de volumen.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25250, 10022, '2. Ha perdido más de un 30 % de la volemia y precisa reposición de volumen y de sangre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25251, 10022, '3. Ha perdido más de un 40 % de la volemia y precisará tratamiento quirúrgico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25252, 10022, '4. Ha perdido más de un 50% de la volemia y precisa reposición de volumen y de sangre.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25253, 10023, '1. Hipovolémico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25254, 10023, '2. Séptico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25255, 10023, '3. Anafiláctico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25256, 10023, '4. Neurogénico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25257, 10024, '1. Shock hipovolémico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25258, 10024, '2. Shock cardiogénico intrínseco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25259, 10024, '3. Shock neurogénico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25260, 10024, '4. Shock séptico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25261, 10025, '1. Naloxona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25262, 10025, '2. Flumazenilo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25263, 10025, '3. Atropina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25264, 10025, '4. Pralidoxima.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25265, 10026, '1. Oxigenoterapia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25266, 10026, '2. Nitroglicerina intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25267, 10026, '3. Morfina intravenosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25268, 10026, '4. Diuréticos intravenosos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25269, 10027, '1. Cohibir la hemorragia externa, exanguinante o masiva.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25270, 10027, '2. Asegurar la permeabilidad de la vía aérea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25271, 10027, '3. Asegurar una correcta ventilación/oxigenación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25272, 10027, '4. Identificar y tratar el shock.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25273, 10028, '1. La apertura de la vía aérea mediante tracción mandibular es la maniobra de elección.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25274, 10028, '2. Lo prioritario es colocar un collarín cervical rígido.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25275, 10028, '3. La apertura de la vía aérea es prioritaria en un paciente con un traumatismo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25276, 10028, '4. Una vez abierta la vía aérea, es recomendable usar un dispositivo orofaríngeo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25277, 10029, '1. Tras la sospecha clínica, el diagnóstico suele realizarse mediante ecografía doppler.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25278, 10029, '2. Los pacientes con factores de riesgo o trombosis venosas de repetición suelen precisar anticoagulación durante 12 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25279, 10029, '3. Por norma general, la anticoagulación se suele mantener durante 3 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25280, 10029, '4. La tasa de recidiva es del 60%.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25281, 10030, '1. Estamos ante una crisis de asma leve, agonistas Beta -2 de acción corta con cámara entre 2 y 4 inhalaciones cada 20 minutos en la primera hora hasta mejoría. Si mejoría alta con prednisonavia oral 5-7 días y glucocorticoide inhalado más LABA, un plan de acción por escrito y revisión en consulta.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25282, 10030, '2. Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Tras mejoría alta con glucocorticoide inhalado más LABA, prednisonavia oral 5-7 días, un plan de acción por escrito y revisión en consulta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25283, 10030, '3. Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Tras mejoría alta con amoxicilina 500 cada 12 horas pauta corta de 5 dias, glucocorticoide inhalado más LABA, prednisonavia oral 5-7 días, un plan de acción por escrito y revisión en consulta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25284, 10030, '4. Estamos ante una crisis de asma moderada, agonistas Beta-2 de acción corta con ipatropio nebulizado y oxígeno en gafa nasal. Y traslado al hospital con ambulancia para tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25285, 10031, '1. Realizaremos una analítica de sangre con determinación de troponinas para determinar si es un infarto y así activar un cateterismo urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25286, 10031, '2. Administraremos dosis de carga de aspirina lo antes posible.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25287, 10031, '3. El cateterismo ha de realizarse de forma urgente en menos de 2 horas siendo la vía femoral la primera opción por ser la más rápida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25288, 10031, '4. Sospecharemos una lesión coronaria trombótica oclusiva en la arteria circunfleja.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25289, 10032, '1. Existen algunos ensayos clínicos que avalan su uso en pacientes en hemodiálisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25290, 10032, '2. Tienen menos riesgo de hemorragia intracraneal que los antagonistas de la vitamina K.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25291, 10032, '3. Pueden administrarse en pacientes con valvulopatías y portadores de todo tipo de prótesis cardíacas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25292, 10032, '4. Son igual o más eficaces que los antagonistas de la vitamina K para prevenir ictus isquémicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25293, 10033, '1. Varón de 45 años con tres episodios de síncope precedido de cortejo vegetativo y recuperación lenta en el último año.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25294, 10033, '2. Varón de 75 años con fracción de eyección del ventrículo izquierdo del 40%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25295, 10033, '3. Varón de 75 años con ECG con bloqueo completo de rama izquierda del haz de His.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25296, 10033, '4. Mujer de 37 años con síncope en reposo precedido de palpitaciones', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25297, 10034, '1. Infarto agudo de miocardio con elevación del segmento ST inferior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25298, 10034, '2. Infarto agudo de miocardio con elevación del segmento ST inferior con rotura del músculo papilar posterior-medial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25299, 10034, '3. Infarto agudo de miocardio con elevación del segmento ST inferior y de ventrículo derecho.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25300, 10034, '4. Infarto con elevación del segmento ST inferior con rotura del septo interventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25301, 10035, '1. Hipotensión arterial refractaria a fluidoterapia intensiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25302, 10035, '2. Variación de velocidades de llenado mitral y tricúspide menor del 25% con la inspiración.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25303, 10035, '3. Colapso de aurícula derecha y ventrículo derecho en diástole.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25304, 10035, '4. Situación de parada cardiorrespiratoria con actividad eléctrica sin pulso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25305, 10036, '1. Paracentesis diagnóstica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25306, 10036, '2. Medición de los niveles plasmáticos de amoniaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25307, 10036, '3. Administración de lactulosa por vía oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25308, 10036, '4. Antibioterapia de amplio espectro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25309, 10037, '1. Ante la presencia de cuatro criterios de Centor, realizar test rápido de Estreptococo e iniciar tratamiento con Amoxicilina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25310, 10037, '2. Ante la presencia de tres criterios de Centor, realizar test rápido de Estreptococo y si es positivo iniciar tratamiento con Amoxicilina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25311, 10037, '3. Presenta un cuadro típico de faringitis, no es necesario test rápido de Estreptococo y se debería iniciar tratamiento con Amoxicilina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25312, 10037, '4. Ante la presencia de dos criterios de Centor realizar test rápido de Estreptococo y si es positivo iniciar tratamiento con Azitromicina 500 mg/24 h durante tres día', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25313, 10038, '1. Aumento del espacio muerto anatómico sin alteración del intercambio gaseoso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25314, 10038, '2. Hipoxemia con PaO₂/FiO₂ ≤ 300 asociada a shunt intrapulmonar y disminución de la distensibilidad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25315, 10038, '3. Hipercapnia leve con aumento de la compliance pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25316, 10038, '4. Aumento de la presión alveolar de CO₂ con distensibilidad normal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25317, 10039, '1. Sodio urinario < 20 mEq/L.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25318, 10039, '2. Excreción fraccional de sodio <1%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25319, 10039, '3. Cociente creatinina urinaria/creatinina plasmática mayor de 40.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25320, 10039, '4. Osmolalidad urinaria menor de 350 mOsmoles/Kg.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25321, 10040, '0. 8mg/dL. La osmolalidad plasmática es 257mOsm/kg y el sodio urinario 45 mEq/L. Hace un mes estuvo en la consulta de su médico de familia, quien le cambió el tratamiento antihipertensivo y le hizo una analítica general que fue normal. ¿Cuál es su diagnóstico?:', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25322, 10040, '1. Hiponatremia inducida por tiazidas.', false, 2);
