INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25331, 10042, '2. Fibrilación ventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25332, 10042, '3. Alucinaciones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25333, 10042, '4. Pupilas mióticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25334, 10043, '1. Hemograma y bioquímica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25335, 10043, '2. TC abdominal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25336, 10043, '3. e-FAST (Extended Focused Abdominal Sonography for Trauma).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25337, 10043, '4. Punción lavado peritoneal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25338, 10044, '1. Presencia de signos de insuficiencia cardiaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25339, 10044, '2. Antecedente de hemorragia craneal sin secuelas hace 10 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25340, 10044, '3. Antecedente de ictus isquémico hace 18 meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25341, 10044, '4. Cifras de tensión arterial ≥ 140/90 mmHg.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25342, 10045, '1. Cisatracurio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25343, 10045, '2. Dexmedetomidina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25344, 10045, '3. Midazolam.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25345, 10045, '4. Venlafaxina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25346, 10046, '1. Medidas generales de soporte y baño por inmersión para reducir la temperatura corporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25347, 10046, '2. Medidas de soporte, enfriamiento con esponjas húmedas (a 15-20 ºC) sobre la superficie corporal y asegurar una hidratación adecuada por vía intravenosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25348, 10046, '3. El uso de mantas de enfriamiento es la medida más eficaz para la rápida reducción de la temperatura corporal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25349, 10046, '4. Medidas de soporte, enfriamiento con esponjas empapadas en alcohol aplicadas sobre la superficie corporal y antipiréticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25350, 10047, '1. Incrementa la capacidad residual funcional de sistema respiratorio.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25351, 10047, '2. Es especialmente eficaz en el paciente con hipotensión y alteraciones del ritmo cardiaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25352, 10047, '3. Produce un aumento de la presión intratorácica que aumenta la precarga cardiaca.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25353, 10047, '4. Ocasiona un aumento de la presión transmural del ventrículo izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25354, 10048, '1. Los bloqueantes neuromusculares están indicados cuando el paciente presenta asincronías, independientemente del grado de analgesia y sedación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25355, 10048, '2. Se prefieren los sedantes no benzodiazepínicos debido a que las benzodiacepinas se relacionan con peor resultado clínico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25356, 10048, '3. La interrupción diaria de la sedación no acorta el tiempo de ventilación mecánica ni la estancia en UCI.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25357, 10048, '4. El paracetamol es el principal agente farmacológico para lograr una adecuada analgesia en los pacientes intubados y ventilados mecánicamente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25358, 10049, '1. La causa más frecuente es infecciosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25359, 10049, '2. Durante los primeros siete días de evolución se produce normalmente la fase proliferativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25360, 10049, '3. Se caracteriza por un aumento de la distensibilidad del pulmón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25361, 10049, '4. La relación entre la presión parcial de oxígeno y la fracción inspirada de oxígeno es superior a 300.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25362, 10050, '1. Presencia de reflejos medulares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25363, 10050, '2. Anisocoria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25364, 10050, '3. Ausencia de hipotensión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25365, 10050, '4. Ausencia de ventilación espontánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25366, 10051, '1. TC craneal sin contraste.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25367, 10051, '2. TC craneal con contraste.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25368, 10051, '3. Ninguna prueba de imagen.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25369, 10051, '4. Radiografía simple de cráneo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25370, 10052, '1. Instaurar ventilación mecánica no invasiva y solicitar transfusión sanguínea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25371, 10052, '2. Analgesia, oxigenoterapia, solicitar transfusión sanguínea e indicar una intervención quirúrgica urgente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25372, 10052, '3. Intubación orotraqueal, solicitar transfusión sanguínea y observación para, en caso de empeoramiento, indicar la intervención quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25373, 10052, '4. Intubación orotraqueal y realización de una TC urgente para valoración exacta de las lesiones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25374, 10053, '1. Adrenalina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25375, 10053, '2. Adrenalina y dexclorfeniramina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25376, 10053, '3. Adrenalina, dexclorfeniramina y metilprednisolona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25377, 10053, '4. Adrenalina, dexclorfeniramina y glucagón.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25378, 10054, '1. Dada la potencial gravedad de la enfermedad tromboembólica venosa y tratándose de una paciente joven hay que asegurarse que no tiene nada mediante la realización de un eco-doppler.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25379, 10054, '2. La paciente tiene una probabilidad previa baja en base a la historia y los hallazgos en la exploración, por lo que lo más adecuado es realizar una determinación de dímeros D, que, de ser negativos, descartarían la presencia de una trombosis venosa sin requerir pruebas adicionales.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25380, 10054, '3. Al no estar inmovilizada la probabilidad clínica de presentar una trombosis es muy baja, así que no requiere estudios adicionales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25381, 10054, '4. En todos los pacientes en los que se sospeche una trombosis venosa aguda hay que realizar de forma urgente una determinación de dímeros-D para el diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25382, 10055, '1. Tranquilizarla, explicarle que la exploración es normal, administrar un ansiolítico y recomendarle que si el cuadro no mejora acuda nuevamente al centro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25383, 10055, '2. Realizar una determinación de troponinas cardiacas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25384, 10055, '3. Realizar un electrocardiograma de 12 derivaciones.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25385, 10055, '4. Realizar una radiografía de tórax.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25386, 10056, '1. Apertura ocular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25387, 10056, '2. Respuesta verbal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25388, 10056, '3. Respuesta motora.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25389, 10056, '4. Reactividad pupilar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25390, 10057, '1. Pensar en síncope vasovagal y dar el alta.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25391, 10057, '2. Solicitar un TAC craneal e iniciar tratamiento antiepiléptico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25392, 10057, '3. Solicitar analítica y remitirla a consulta del neurólogo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25393, 10057, '4. Pensar en intoxicación etílica aguda, hacer TAC craneal y punción lumbar y administrar tiamina IV.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25394, 10058, '1. Vena subclavia derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25395, 10058, '2. Vena cava superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25396, 10058, '3. Vena basílica derecha.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25397, 10058, '4. Tronco braquiocefálico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25398, 10059, '1. Retirar todo el catéter y volverlo a introducir.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25399, 10059, '2. Extraer unos 10 cm el catéter e instaurar el tratamiento oportuno.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25400, 10059, '3. Canalizar otra vía venosa central por la yugular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25401, 10059, '4. Dejarlo como está porque se puede utilizar para monitorizar presión venosa central.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25402, 10060, '1. A un hombre de 64 años con una infección urinaria baja, que presenta glucemias capilares mantenidas entre 250 y 300 mg/dL y que está recibiendo ceftriaxona endovenosa, insulina rápida subcutánea cada 6 horas y 500 ce de suero fisiológico cada 4 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25403, 10060, '2. A una mujer de 44 años con sospecha de trombosis venosa profunda en la extremidad inferior derecha, que ha iniciado heparina de bajo peso molecular subcutánea a dosis anticoagulantes y que está pendiente de una ecografía-doppler.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25404, 10060, '3. A una mujer de 71 años con antecedentes de hipertensión arterial, con unas cifras de presión arterial sistólica y diastólica persistentemente mantenidas por encima de 210 y 110 mmHg. respectivamente, y en la que acaba de prescribir el inicio de una perfusión con nitroprusiato sódico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25405, 10060, '4. A una mujer de 32 años con una fibrilación auricular de inicio hace menos de 24 horas, en la que el intento de cardioversión farmacológica ha fracasado y que está esperando para una cardioversión eléctrica en urgencias las próximas horas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25406, 10061, '1. Este paciente debe ser atendido en el box de emergencia vital (cuarto de shock).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25407, 10061, '2. Avisaremos al cardiólogo de guardia para la valoración del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25408, 10061, '3. Desde la consulta de Triage se le remitirá a la unidad coronaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25409, 10061, '4. Haremos un ECG en menos de 10 minutos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25410, 10062, '1. Infarto agudo de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25411, 10062, '2. Diverticulitis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25412, 10062, '3. Aneurisma disecante de aorta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25413, 10062, '4. Embolia mesentérica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25414, 10063, '1. La etiología suicida de la intoxicación por CO es excepcional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25415, 10063, '2. La intoxicación por CO no está incluida en la lista de enfermedades profesionales, ya que cuando se presenta lo hace de forma accidental.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25416, 10063, '3. El CO es un gas incoloro pero dotado de un olor característico a almendras amargas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25417, 10063, '4. Una fuente habitual de producción de CO es la mala combustión de gases licuados (propano, butano, etc.).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25418, 10064, '1. Intoxicación por benzodiazepinas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25419, 10064, '2. Abstinencia de opiáceos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25420, 10064, '3. Intoxicación por cannabis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25421, 10064, '4. Abstinencia de alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25422, 10065, '1. Observación y repetición de niveles de paracetamol en 4 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25423, 10065, '2. Iniciar tratamiento con N-acetilcisteína y mantenerlo durante 12 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25424, 10065, '3. Observación y repetición de niveles de paracetamol, pruebas hepáticas y coagulación en 4 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25425, 10065, '4. Iniciar tratamiento con N-acetilcisteína y mantenerlo en función de la evolución de los niveles de paracetamol, pruebas hepáticas y renales.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25426, 10066, '1. Intoxicación por cloro. Nebulización bicarbonatada (4 ml de suero salino 0,9% + 6 mL de bicarbonato sódico 1M) en las primeras 3 horas tras la exposición.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25427, 10066, '2. Inhalación de vapores nitrosos. Tratamiento sintomático y de soporte.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25428, 10066, '3. Intoxicación por monóxido de carbono y cianuro. Medidas de soporte junto con oxigenoterapia al 100 % e hidroxicobalamina con una dosis de 5 g IV en 10 min.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25429, 10066, '4. Intoxicación por absorción cutánea de tóxicos. Medidas de soporte, oxigenoterapia, limpieza cutánea y atropina (1 mg IV) que se puede repetir cada 2-3 minutos hasta mejoría clínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25430, 10067, '1. Administrar naloxona, flumazenilo y tiamina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25431, 10067, '2. Administrar naloxona, flumazenilo y glucosa hipertónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25432, 10067, '3. Administrar naloxona y flumazenilo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25433, 10067, '4. Administrar tiamina y glucosa hipertónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25434, 10068, '1. No existe absorción a través de la piel.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25435, 10068, '2. Es común el fallecimiento al cabo de unos minutos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25436, 10068, '3. Se inicia con síntomas nicotínicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25437, 10068, '4. Su acción selectiva es anticolinesterásica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25438, 10069, '1. Taxus baccata (tejo).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25439, 10069, '2. Thevetia peruviana (adelfa amarilla).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25440, 10069, '3. Atropa belladona (escopolamina).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25441, 10069, '4. Aconitum napellus (acónito).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25442, 10070, '1. Administración de oxígeno mediante mascarilla tipo Venturi al 50%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25443, 10070, '2. Administración de hidroxicobalamina intravenosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25444, 10070, '3. Ventilación con cámara hiperbárica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25445, 10070, '4. Fluidoterapia con infusión de solución salina fisiológica a 21 ml/h.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25446, 10071, '1. Aplicar oxigeno con alto flujo+ bicarbonato IV.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25447, 10071, '2. Aplicar oxigeno con alto flujo + hidroxocobalamina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25448, 10071, '3. Aplicar oxigeno con alto flujo+ tiamina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25449, 10071, '4. Aplicar oxígeno con alto flujo + naloxona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25450, 10072, '1. El lugar de recolección es importante a la hora de valorar una intoxicación por setas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25451, 10072, '2. La cantidad de setas ingerida puede influir en el pronóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25452, 10072, '3. Dada la desaparición de los síntomas nuestro amigo no llevaba razón.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25453, 10072, '4. La aparición precoz de síntomas (menos de 6 horas) supone un mejor pronóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25454, 10073, '1. Hipotermia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25455, 10073, '2. Taquicardia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25456, 10073, '3. Midriasis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25457, 10073, '4. Diaforesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25458, 10073, '5. Dolor torácico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25459, 10074, '1. Suele ser un consumo individual lo cual indica un mejor pronóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25460, 10074, '2. El inicio del abuso en la adolescencia no ha demostrado un mayor riesgo de convertirse en adicto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25461, 10074, '3. Es independiente del riesgo de contagio por el VIH.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25462, 10074, '4. La droga más popular entre los adolescentes es el cannabis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25463, 10074, '5. Debe considerarse en adolescentes que llegan a la Urgencia con una crisis comicial.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25464, 10075, '1. Proceder a intubación endotraqueal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25465, 10075, '2. Realizar una radiografía de cráneo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25466, 10075, '3. Administrar flumazenilo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25467, 10075, '4. Administrar naloxona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25468, 10075, '5. Esperar a que despierte.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25469, 10076, '"1. Reducen el efecto del OH en el organismo, disminuyendo el posible efecto positivo de un nuevo consumo', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25470, 10076, '2. Incrementan el efecto tóxico del OH, desmotivando al paciente de cara a nuevos consumos', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25471, 10076, '3. Anulan el efecto del OH en el organismo, actuando como antagonistas', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25472, 10076, '4. Por su efecto estabilizador del ánimo posibilitan un mayor control del consumo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25473, 10076, '5. Ocupan los receptores GABA, reduciendo el ""craving"""', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25474, 10077, '1. Lo más probable es que se trate de una intoxicación aguda por éxtasis MDMA (Metilendietoximetanfetamina).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25475, 10077, '2. Precisa de tratamiento sintomático y observación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25476, 10077, '3. Si la ingestión de la última pastilla ha sido reciente (menos de 1-2 horas) se aconseja lavado gástrico y carbón activado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25477, 10077, '4. Se administrará el antídoto tan pronto como sea posible.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25478, 10077, '5. Se indicará sueroterapia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25479, 10078, '1. Alta a su domicilio aconsejando seguimiento en programa de deshabituación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25480, 10078, '2. Observación en urgencias con exámenes frecuentes del estado mental durante un mínimo de 4 a 6 horas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25481, 10078, '3. Iniciar infusión de naloxona intravenosa con 2/3 de la dosis inicial por hora.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25482, 10078, '4. Administrar 10 mg de metadona intramuscular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25483, 10078, '5. Sujeción mecánica en prevención de cuadro de agitación y agresión.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25484, 10079, '1. Administrar 0,4 mg de naloxona im o iv.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25485, 10079, '2. Obtener un hemograma y una bioquímica básica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25486, 10079, '3. Solicitar un examen toxicológico de orina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25487, 10079, '4. Realizar un ECG.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25488, 10079, '5. Solicitar una TC craneal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25489, 10080, '1. Asegurar la vía aérea, oxígeno y suero glucosado 10%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25490, 10080, '2. Asegurar la vía aérea, calentamiento corporal y observación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25491, 10080, '3. Asegurar la vía aérea, administrar naloxona intravenosa y observación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25492, 10080, '4. Asegurar la vía aérea, administrar naltrexona y observación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25493, 10081, '1. Síndrome de abstinencia complicado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25494, 10081, '2. Enfermedad de Korsakoff.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25495, 10081, '3. Encefalopatía de Wernicke.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25496, 10081, '4. Alucinosis alcohólica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25497, 10081, '5. Intoxicación etílica aguda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25498, 10082, '1. No iniciar ningún procedimiento diagnóstico ni terapéutico orgánico al tratarse de un problema psiquiátrico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25499, 10082, '2. Determinar los niveles de tóxicos, incluyendo cocaína, en orina y de etanol en sangre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25500, 10082, '3. Mantener al paciente en observación en un área médica, con constantes vitales monitorizadas, permitiendo la vigilancia policial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25501, 10082, '4. Monitorizar electrocardiográficamente al paciente, teniendo localizado al cardiólogo de guardia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25502, 10082, '5. Sedar al paciente, si es preciso, para posibilitar la exploración clínica, analítica y electrocardiográfica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25503, 10083, '1. Es un paciente categoría GOLD E de la guía Global Initiative for Chronic Obstructive Lung Disease y no necesita corticoi-des inhalados. Explicamos al paciente su enfermedad y el porqué de su tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25573, 10100, '3. Anomalías esqueléticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25574, 10100, '4. Estatura alta', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25504, 10083, '2. Es un paciente riesgo alto, no agudizador eosinofílico. Explicamos enfermedad y el porqué de su tratamiento y retiramos corticoide inhalado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25505, 10083, '3. Es un paciente riesgo alto, retiramos corticoide inhalado y ponemos doble broncodilatación. Explicamos al paciente su enfermedad y el porqué de su tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25506, 10083, '4. Es un paciente riesgo alto agudizador eosinofílico, debe mantener triple terapia, explicamos al paciente su enfermedad y el porqué de su tratamiento', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25507, 10084, '1. Artritis reumatoide seronegativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25508, 10084, '2. Polimialgia reumática.', true, 2);
