INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25510, 10084, '4. Artrosis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25511, 10085, '1. Dolor pulsátil bilateral con fotofobia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25512, 10085, '2. Dolor pulsátil unilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25513, 10085, '3. Dolor opresivo bilateral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25514, 10085, '4. Dolor que empeora con el ejercicio físico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25515, 10086, '1. Trombocitemia esencial. Estudio de médula ósea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25516, 10086, '2. Betatalasemia intermedia. Electroforesis de hemoglobinas y estudio genético.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25517, 10086, '3. Esferocitosis hereditaria. Prueba de unión con esosina-5’-maleimida (EMA).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25518, 10086, '4. Anemia ferropénica. Ferritina sérica y estudios digestivos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25519, 10087, '1. Colchicina y antiinflamatorios durante la crisis y luego suspender ambos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25520, 10087, '2. Colchicina y antiinflamatorios y cuando está asintomático suspender antiinflamatorios y añadir alopurinol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25521, 10087, '3. Alopurinol y antiinflamatorios durante la crisis y después suspender ambos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25522, 10087, '4. Colchicina y antiinflamatorios durante la crisis y después suspender antiinflamatorios y mantener colchicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25523, 10088, '1. Antihistamínicos orales de primera generación, como la difenhidramina, debido a su efecto rápido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25524, 10088, '2. Descongestionantes nasales típicos usados prolongadamente para un control sostenido de la congestión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25525, 10088, '3. Corticosteroides intranasales de alta potencia, para aliviar síntomas nasales y oculares con menos efectos sistémicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25526, 10088, '4. Cromoglicato sódico por vía oral como único tratamiento en síntomas moderados persistentes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25527, 10089, '1. Es más frecuente en verano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25528, 10089, '2. El tratamiento de elección es quirúrgico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25529, 10089, '3. En la mayoría de los casos, la evolución natural es hacia la curación espontánea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25530, 10089, '4. Los antihistamínicos son útiles para su resolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25531, 10090, '1. Realización de resonancia magnética urgente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25532, 10090, '2. Administración de dexametasona 10 mg.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25533, 10090, '3. Administración de AINEs y reevaluación en 48 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25534, 10090, '4. Realización de radiografía simple de columna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25535, 10091, '1. Estudio coproparasitario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25536, 10091, '2. Aclaramiento fecal de alfa-1-antitripsina.', false, 2);
