INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25539, 10092, '1. Se caracterizan por dolor intenso y eritema marcado, sin formación de ampollas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25540, 10092, '2. Afectan solo la epidermis y suelen sanar sin dejar cicatriz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25541, 10092, '3. Presentan destrucción de la epidermis y dermis reticular, con pérdida de sensibilidad y mayor riesgo de infección.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25542, 10092, '4. No requieren injerto cutáneo ya que cicatrizan espontáneamente en menos de una semana.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25543, 10093, '1. Dada la ausencia de patología tumoral en la ecografía es probable que presente vejiga hiperactiva por lo que se solicitar. Estudio urodinámico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25544, 10093, '2. Ha de realizarse cistoscopia y citologías ante riesgo de carcinoma in situ vesical.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25545, 10093, '3. Lo más probable es que presente una pequeña litiasis vesical que expulsará espontáneamente dada la longitud y anchura de la uretra femenina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25546, 10093, '4. La disuria descarta que la paciente presente patología tumoral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25547, 10094, '1. Síndrome del Osgood-Schlatter.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25548, 10094, '2. Síndrome de la Cintilla Ilio-Tibial.', true, 2);
