INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25559, 10097, '1. En pacientes con NAC grave, hospitalizados o que no responden al tratamiento empírico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25560, 10097, '2. En pacientes jóvenes sin comorbilidades para evitar el uso de antibióticos de amplio espectro.', false, 2);
