INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25631, 10115, '1. A positivo. El grupo sanguíneo permanece inalterable durante toda la vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25632, 10115, '2. AB positivo. Existe una mezcla de ambos grupos en los hematíes.', false, 2);
