INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25699, 10132, '1. El caso índice transmitirá la enfermedad a todos sus descendientes varones (herencia holándrica).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25700, 10132, '2. La enfermedad se transmitirá al 50% de los descendientes del caso índice con independencia de su sexo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25701, 10132, '3. La enfermedad se transmitirá a todos los descendientes de sexo femenino, pero a ningún varón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25702, 10132, '4. Ningún descendiente heredará la enfermedad', true, 4);
