INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25704, 10133, '2. Es útil en la evaluación de riesgo en familiares de individuos afectos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25705, 10133, '3. El gen HFE está en el locus del Complejo Mayor de Histocompatibilidad (HLA) en el cromosoma 6, en humanos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25706, 10133, '4. Las mutaciones C282Y y H63D en el gen HFE son muy prevalentes en la población caucásica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25707, 10134, '1. La presencia de una alteración en los mecanismos de reparación del ADN que afectan a las proteínas del sistema MMR (MissMatch Repair) da lugar a un exceso de mutaciones e inestabilidad de microsatélites. Esto ocurre en aproximadamente el 15% de los cánceres colorrectales esporádicos y en los asociados al síndrome de Lynch.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25708, 10134, '2. El cáncer colorrectal hereditario no polipósico se asocia a la presencia de mutaciones germinales en genes reparadores del ADN (MLH1, MLH2, MSH6, PMS2).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25709, 10134, '3. Las mutaciones germinales en el gen APC se asocian al cáncer colorrectal asociado a la poliposis hereditaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25710, 10134, '4. El cáncer colorrectal hereditario no polipósico se hereda con carácter autosómico recesivo', true, 4);
