INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25714, 10135, '4. Temblor/ataxia asociado a X frágil', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25715, 10136, '1. Una característica de las enfermedades con herencia autosómica dominante es la existencia de portadores asintomáticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25716, 10136, '2. Las enfermedades hereditarias ligadas al cromosoma Y son más frecuentes que las ligadas al cromosoma X.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25717, 10136, '3. No es posible la transmisión de una enfermedad con mutaciones del ADN mitocondrial desde un varón afectado a su descendencia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25718, 10136, '4. La herencia poligénica es una de las formas clásicas de herencia mendeliana', false, 4);
