INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25720, 10137, '2. La probabilidad de que el siguiente descendiente esté afecto es del 50%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25721, 10137, '3. Al haber tenido un hijo afecto, el siguiente descendiente también estará afecto.', false, 3);
