INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25722, 10137, '4. Al haber tenido un hijo homocigoto F508del, el siguiente descendiente será portador heterocigoto (67%) o de genotipo homocigoto sin la mutación (33%)', false, 4);
