INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25731, 10140, '1. Los oncogenes se comportan de forma dominante.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25732, 10140, '2. La mutación de genes supresores de tumores origina una activación de su función normal.', false, 2);
