INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25816, 10160, '1. La anomalía cromosómica más frecuente es el cariotipo 47XXY.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25817, 10160, '2. Se trata de un hipogonadismo hipogonadotrópico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25818, 10160, '3. El diagnóstico es infrecuente antes de la pubertad por su escasa sintomatología clínica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25819, 10160, '4. Es la causa más frecuente de esterilidad en varones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25820, 10160, '5. Durante la adolescencia tardía los pacientes presentan alteraciones del aprendizaje', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25821, 10161, '1. Al ser el caso índice varón, heredarán la ataxia todos los descendientes de sexo femenino, pero ningún hijo varón.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25822, 10161, '2. La mutación se transmitirá al 50% de los descendientes del caso índice, que desarrollarán la ataxia a partir de algún momento de su vida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25823, 10161, '3. La mutación se transmitirá al 25% de los descendientes del caso índice, que desarrollarán la ataxia a partir de algún momento de su vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25824, 10161, '4. La ataxia se transmitirá a lo largo de la vida del caso índice afectando a toda su descendencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25825, 10161, '5. Si la pareja del caso índice es portadora de otra mutación SCA (por ejemplo, en SCA36, gran heterogeneidad genética), la ataxia la padecerán el 25% de los descendientes a partir de algún momento de su vida. Si la pareja no es portadora, la ataxia no se transmitirá', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25826, 10162, '1. El caso índice transmitirá la enfermedad a todos sus descendientes varones (herencia holándrica).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25827, 10162, '2. La enfermedad se transmitirá al 50% de los descendientes del caso índice, independientemente de su sexo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25828, 10162, '3. La enfermedad se transmitirá a todos los descendientes del caso índice, por ser de herencia paterna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25829, 10162, '4. La enfermedad se transmitirá a los descendientes de sexo femenino, pero a ningún varón.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25830, 10162, '5. La enfermedad no se transmitirá a los descendientes del caso índice, por ser de herencia materna', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25831, 10163, '1. 0,01.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25832, 10163, '2. 0,1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25833, 10163, '3. 0,25.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25834, 10163, '4. 0,5.', false, 4);
