INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25836, 10164, '1. La madre es la que le ha transmitido la enfermedad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25837, 10164, '2. El padre es el que ha transmitido la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25838, 10164, '3. Ambos padres le han trasmitido la enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25839, 10164, '4. Si tienen una nueva hija puede presentar la enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25840, 10164, '5. Si tienen un nuevo hijo no puede heredar la enfermedad', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25841, 10165, '1. Gen de ARN transferente implicado en la aparición de tumores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25842, 10165, '2. Gen que controla el ciclo celular evitando el crecimiento celular. Cuando se produce una mutación en estos genes, sus proteínas no se expresan o dan lugar a proteínas no funcionantes, favoreciendo la aparición del proceso de carcinogénesis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25843, 10165, '3. Sustancia detectable en líquidos orgánicos, especialmente en sangre, producida por la célula neoplásica o sus metástasis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25844, 10165, '4. Es un gen anormal o activado que procede de la mutación de un alelo de un gen normal llamado proto-oncogén. Origina proteínas con expresión/función alterada que favorecen el crecimiento y/o la invasión tumoral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25845, 10165, '5. Gen de herencia autosómica dominante que condiciona la aparición de cáncer en la descendencia', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25846, 10166, '1. Policitemia Vera.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25847, 10166, '2. Leucemia Mieloide Aguda tipo M4 de la FAB.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25848, 10166, '3. Síndrome Mielodisplásico tipo Anemia Refractaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25849, 10166, '4. Leucemia Mieloide Crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25850, 10166, '5. Leucemia Mielomonocítica Crónica', false, 5);
