INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25852, 10167, '2. c-MYC.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25853, 10167, '3. Ciclina D1.', false, 3);
