INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25867, 10170, '2. RET.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25868, 10170, '3. EGFR.', false, 3);
