INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25870, 10170, '5. TP53', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26025, 10202, '1. LAM M1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25871, 10171, '1. Según la herencia autosómica dominante, la mitad de sus hijos heredarán la enfermedad y sin distinción de sexos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25872, 10171, '2. Sus hijas no heredarán la enfermedad, pero todos sus futuros hijos varones serán portadores y pueden transmitir la mutación al 50%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25873, 10171, '3. Sus hijos varones no heredarán la enfermedad, pero todas sus futuras hijas serán portadoras y pueden transmitir la mutación al 50%.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25874, 10171, '4. No hay riesgo: la herencia de la enfermedad es del tipo mitocondrial, nunca transmitida por los varones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25875, 10171, '5. Según la herencia autosómica recesiva, un 25% de sus hijos manifestarán la enfermedad en la infancia, sin distinción de sexos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25876, 10172, '1. Anemia ferropénica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25877, 10172, '2. α talasemia menor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25878, 10172, '3. β talasemia menor.', true, 3);
