INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25882, 10173, '2. t (8,21).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25883, 10173, '3. Monosomía 5, 7, cariotipo complejo.', true, 3);
