INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25885, 10173, '5. Trisomía 8', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25886, 10174, '1. Edad materna de 38 anos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25887, 10174, '2. Test combinado del primer trimestre positivo alto riesgo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25888, 10174, '3. Triple screening patológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25889, 10174, '4. Presencia de dos marcadores ecográficos secundarios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25890, 10174, '5. Anomalías en la ecografía de alta resolución/3D', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25891, 10175, '1. Un mayor riesgo de presentar cáncer de mama exclusivamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25892, 10175, '2. Un mayor riesgo de presentar cáncer de mama y de ovario.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25893, 10175, '3. Dado que es una mutación de trasmisión autonómico recesiva el riesgo de presentar cáncer de mama es menor del 10% a lo largo de la vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25894, 10175, '4. La mastectomía profiláctica de las pacientes portadoras de esta mutación solo debe realizarse (si se indica) por encima de los 45 años (postmenopausia), ya que por encima de esta edad existe la mayor incidencia de tumores de mama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25895, 10175, '5. Mejor pronostico si presentan un cáncer de mama, ya que la histopatología de los tumores que aparecen en las pacientes portadoras es más favorable (en términos de grado histológico de malignidad, presencia de receptores hormonales, etc.)', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25896, 10176, '1. Inactivación de la cadherina E.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25897, 10176, '2. Incremento de producción de metaloproteasas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25898, 10176, '3. Disminución en la activación de catepsinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25899, 10176, '4. Incremento en la expresión de Her2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25900, 10176, '5. Inactivación de p53', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25901, 10177, '1. Alfafetoproteina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25902, 10177, '2. Ca 125.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25903, 10177, '3. Cromogranina A.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25904, 10177, '4. Antigeno carcino embrionario (CEA).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25905, 10177, '5. Ca 15.3', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25906, 10178, '1. Ras.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25907, 10178, '2. APC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25908, 10178, '3. MSH2.', true, 3);
