INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25910, 10178, '5. c-MYC', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25911, 10179, '1. Los cromosomas de los humanos y los chimpancés son muy distintos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25912, 10179, '2. Las secuencias de ARN mensajero (ARNm) son decodificadas en conjuntos de 4 nucleótidos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25913, 10179, '3. Todas las células actuales usan el ARN como su material hereditario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25914, 10179, '4. Los genes que codifican para nuevas proteínas pueden ser creados mediante la recombinación de exones.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25915, 10179, '5. El número de genes existentes en un organismo es el mismo que el número de proteínas existentes en dicho organismo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25916, 10180, '1. Todos los tipos celulares de un organismo multicelular contienen el mismo ADN.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25917, 10180, '2. Las células de diferentes tipos sintetizan un conjunto de proteínas diferentes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25918, 10180, '3. Una célula puede cambiar la expresión de sus genes en respuesta a señales externas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25919, 10180, '4. La expresión génica puede ser regulada a varios niveles de la vía que conduce desde el ADN al ARN y a la proteína.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25920, 10180, '5. El control genético es muy estricto para evitar mutaciones lo que implica que cada gen mantiene el control sobre una única proteína', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25921, 10181, '1. Prueba de sobrecarga oral a la glucosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25922, 10181, '2. Estudio genético de la mutación C282Y.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25923, 10181, '3. Carga viral del virus de la hepatitis C.', false, 3);
