INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25946, 10186, '1. El riesgo de padecer cáncer de mama en mujeres portadoras de mutaciones en alguno de es-tos genes es del 60-85%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25947, 10186, '2. El riesgo de padecer además cáncer de ovario es mayor en las mujeres portadoras de mutación en el BRCA1 que en las portadoras de mutación en el BRCA2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26026, 10202, '2. LAM M3.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26027, 10202, '3. LAM M5.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25948, 10186, '3. Los cánceres de mama asociados a mutaciones en el BRCA1 son generalmente bien diferenciados en comparación con los cánceres de mama esporádicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25949, 10186, '4. Mutaciones en los genes BRCA1 y BRCA2 son muy poco frecuentes en cánceres de mama esporádicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (25950, 10186, '5. La prevalencia de mutaciones del BRCA1 es mayor que la del BRCA2', false, 5);
