INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26460, 10307, '1. La imagen mostrada se ha obtenido a través de ultrasonidos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26461, 10307, '2. Una de las posibles complicaciones de esta técnica es la punción de la arteria carótida común.', false, 2);
