INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26469, 10309, '2. El glucógeno se puede acumular de forma anormal en las neuronas, como en la enfermedad de Lafora.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26470, 10309, '3. Las glucogenosis que afectan al hígado se presentan normalmente con hepatomegalia e hiperglucemia como primera sintomatología clínica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26471, 10309, '4. La adrenalina regula el metabolismo del glucógeno', false, 4);
