INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26473, 10310, '2. Los cuerpos cetónicos procedentes del músculo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26474, 10310, '3. Los ácidos grasos procedentes del tejido adiposo.', false, 3);
