INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26477, 10311, '2. Tratar a la paciente con ácido ursodesoxicólico, ya que probablemente se trata de una colestasis intrahepática benigna del embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26478, 10311, '3. Interrumpir el embarazo ya que el diagnóstico más probable es el hígado graso agudo del embarazo.', false, 3);
