INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26500, 10317, '13. 540/uL, con 51% de neutrófilos y 36% de linfocitos, plaquetas 286.000/uL, bilirrubina 2,12 mg/dL, (directa 0,4 mg/dL) y lactato deshidrogenasa 318 U/L (v.n. < 190 U/L). Un estudio básico de la coagulación se encuentra dentro de los rangos normales. La radiografía de tórax es normal, así como un Eco-Doppler de extremidades inferiores. ¿Qué tipo de anemia sospecharía Ud. antes de iniciar los correspondientes estudios confirmatorios?', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26501, 10317, '1. Anemia por células falciformes.', false, 2);
