INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26511, 10319, '3. Hay que administrar digoxina para control de la frecuencia cardiaca.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26512, 10319, '4. Se deben evitar los vasoconstrictores periféricos para el tratamiento de la hipotensión', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26513, 10320, '1. Suele asociarse a obesidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26514, 10320, '2. Puede asociarse a otras enfermedades endocrinas autoinmunes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26515, 10320, '3. Es más frecuente que la tipo 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26516, 10320, '4. Suele controlarse inicialmente con antidiabéticos orales, aunque puede necesitar insulina con el tiempo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26517, 10321, '1. Cursa con una osmolaridad plasmática eficaz >320 mOsm/Kg.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26518, 10321, '2. Implica siempre la necesidad de tratamiento con insulina tras su curación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26519, 10321, '3. Precisa un importante aporte de bicarbonato para su tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26520, 10321, '4. Es una forma habitual de presentación de la diabetes juvenil', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26521, 10322, '1. Insistir en cambios de estilo de vida y mantener el mismo tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26522, 10322, '2. Es prioritario aumentar el cHDL con ácido nicotínico.', false, 2);
