INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26529, 10324, '1. Se trata de la resistencia del factor V a la acción de la proteína S.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26530, 10324, '2. Es un trastorno adquirido que se asocia a la presencia de anticuerpos anticardiolipina.', false, 2);
