INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26753, 10371, '5. Reticulocitosis', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26537, 10326, '1. La primera sospecha es una anemia hemolítica autoinmune y la prueba más importante para el diagnóstico será un Coombs directo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26538, 10326, '2. La primera sospecha es un cuadro de microangiopatía tipo púrpura trombótica trombocitopénica, y se debe realizar un frotis de sangre periférica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26539, 10326, '3. La primera sospecha es un cuadro de microangiopatía tipo purpura trombótica trombocitopénica, y se deben determinar unos niveles de ADAMTS 13 y hasta que no se tenga un resultado concluyente no se debería empezar tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26540, 10326, '4. La primera sospecha es una púrpura trombocitopénica autoinmune con sangrado cerebral y anemización secundaria. Se deben determinar anticuerpos antiplaquetarios para orientar el tratamiento', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26541, 10327, '1. Diclofenaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26542, 10327, '2. Alopurinol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26543, 10327, '3. Probenecid.', false, 3);
