INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26554, 10330, '2. Transportador de glucosa (GLUT).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26555, 10330, '3. Canal de calcio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26556, 10330, '4. Enzima limitante de la insulinosecreción', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26557, 10331, '1. Menos de 30 mg en 24 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26558, 10331, '2. Menos de 300 mg en 24 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26559, 10331, '3. Entre 30 y 300 mg/g de creatinina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26560, 10331, '4. Entre 300 y 1000 mg/g de creatinina', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26561, 10332, '1. Su principal fuente para el organismo es la ingesta de frutas y verduras.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26562, 10332, '2. Sus depósitos se localizan en el hígado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26563, 10332, '3. Se conjuga en el íleon con el factor intrínseco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26564, 10332, '4. Su déficit conduce a reducción de los niveles de homocisteína en plasma', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26565, 10333, '1. En reposo, el músculo solo tiene ATP suficiente para mantener la contracción durante unos segundos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26566, 10333, '2. La creatina fosfato es una molécula con un potencial de transferencia de fosforilos bajo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26567, 10333, '3. Durante un ejercicio intenso, la lactato deshidrogenasa oxida el piruvato en exceso a lactato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26568, 10333, '4. La alanina es utilizada para transportar nitrógeno y esqueletos carbonados desde el hígado al músculo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26569, 10334, '1. Revisar la distribución de hidratos de carbono de su dieta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26570, 10334, '2. Suspender la metformina.', false, 2);
