INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26578, 10336, '2. Deficiencia de Factor VII.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26579, 10336, '3. Deficiencia de Factor XII.', false, 3);
