INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26581, 10337, '1. La alteración poligénica y los factores ambientales conducen a la destrucción autoinmune de los islotes del páncreas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26582, 10337, '2. Precisa administración diaria de insulina exógena.', false, 2);
