INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26586, 10338, '2. Gastroenteritis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26587, 10338, '3. Alergia a las proteínas de la leche de vaca.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26588, 10338, '4. Alergia a los biberones', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26589, 10339, '1. Hepatitis por amoxicilina-clavulánico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26590, 10339, '2. Hepatitis por esteroides anabólicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26591, 10339, '3. Hepatitis aguda por virus B.', false, 3);
