INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26593, 10339, '5. Colestasis por fármacos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26594, 10340, '1. Iniciar tratamiento con diuréticos intravenosos, oxígeno con mascarilla a alto flujo al 50% y seguir con el resto de tratamiento ya prescrito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26595, 10340, '2. Iniciar tratamiento con aerosoles de salbutamol y esteroides, añadir al tratamiento antibiótico una cefalosporina, intensificar la oxigenoterapia con oxígeno en gafas nasales a 4 litros por minuto y mantener deflazacort.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26596, 10340, '3. Iniciar tratamiento de la acidosis con bicarbonato 1M, corregir la hiperglucemia, mantener tratamiento antibiótico y prescribir esteroides más diuréticos intravenosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26597, 10340, '4. Dada la situación de gravedad del paciente se procedería a la intubación orotraqueal previa preparación (preoxigenación y premedicación) y avisar a Medicina Intensiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26598, 10340, '5. Iniciar el tratamiento con ventilación mecánica no invasiva (modo presión positiva de dos niveles), prescribir aerosoles de salbutamol y esteroides intravenosos y mantener tratamiento antibiótico por vía intravenosa', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26599, 10341, '1. Es una anemia hemolítica congénita de herencia ligada al cromosoma X que es causa anemia severa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26600, 10341, '2. Se caracteriza por una disminución de la fragilidad osmótica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26601, 10341, '3. Se manifiesta como episodios de anemia aguda medicamentosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26602, 10341, '4. El tratamiento de elección cuando es sintomática es la esplenectomía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26603, 10341, '5. Raramente se asocia a colelitiasis', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26604, 10342, '1. Test de sangre oculta en heces.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26606, 10342, '3. Determinación de hierro, cobalamina y ácido fólico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26607, 10342, '4. Ecografía abdominal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26608, 10342, '5. Aspirado de médula ósea', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26609, 10343, '1. Anemia hemolítica autoinmune. Iniciar esteroides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26610, 10343, '2. Enfermedad de von Willebrand. Administración de desmopresina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26611, 10343, '3. Púrpura trombocitopénica. Iniciar esteroides y transfusión de plaquetas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26612, 10343, '4. Síndrome de Evans. Iniciar esteroides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26613, 10343, '5. Púrpura trombótica trombocitopénica. Tratamiento con plasmaféresis', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26614, 10344, '1. Hemofilia A y prueba de mezclas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26615, 10344, '2. Anticoagulante lúpico y estudio de ANAS.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26616, 10344, '3. Anemia sideroblástica y aspirado medular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26617, 10344, '4. Trombocitopatía congénita y estudio de agregación plaquetaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26618, 10344, '5. Enfermedad de von Willebrand y determinación de factor vW', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26619, 10345, '1. En cuanto al colesterol LDL, el objetivo terapéutico depende del riesgo cardiovascular global.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26620, 10345, '2. Los pacientes diabéticos tipo 2 deben considerarse de alto riesgo cardiovascular y el objetivo en cuanto a colesterol LDL debe ser <100 mg/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26621, 10345, '3. No hay evidencia suficiente de que niveles bajos de colesterol HDL supongan un factor de riesgo cardiovascular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26622, 10345, '4. Lo importante en el riesgo asociado a hipertensión arterial es que mejora cuando se reduce la presión arterial independientemente del tipo de fármaco utilizado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26623, 10345, '5. La existencia de enfermedad coronaria en la familia es un factor de riesgo para el paciente', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26624, 10346, '1. Polidipsia primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26625, 10346, '2. Diabetes insípida central.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26626, 10346, '3. Insuficiencia suprarrenal aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26627, 10346, '4. SIADH.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26628, 10346, '5. Diabetes insípida nefrogénica', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26629, 10347, '1. Enzimas hepáticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26630, 10347, '2. Anticuerpos antinucleares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26631, 10347, '3. Ferritina y sideremia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26632, 10347, '4. Función tiroidea y renal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26633, 10347, '5. Tirocalcitonina', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26634, 10348, '1. Las LDL representan la forma de transporte del colesterol del intestino al hígado. Por tanto, reflejan una mayor incorporación de colesterol desde la ingesta lipídica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26635, 10348, '2. Las LDL están implicadas en el transporte reverso del colesterol desde los tejidos periféricos hacia el hígado. Por tanto, unos niveles elevados son beneficiosos para disminuir los niveles plasmáticos de colesterol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26636, 10348, '3. Las LDL son ricas en triglicéridos y pobres en colesterol. Un aumento de LDL en plasma refleja un aumento de síntesis de novo y/o de ingesta de triglicéridos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26637, 10348, '4. Un aumento de los niveles de LDL en plasma es beneficioso porque protege a las arterias de la formación de placas ateroscleróticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26638, 10348, '5. Las LDL transportan colesterol desde el hígado a los tejidos periféricos, donde entran en las células mediante procesos de endocitosis', true, 5);
