INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26704, 10362, '1. Es necesario realizar tomografía axial computarizada abdominal para descartar pancreatitis crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26705, 10362, '2. Realizaría análisis del líquido sinovial de una articulación afecta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26706, 10362, '3. Trataría las crisis agudas con alopurinol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26707, 10362, '4. El diagnóstico más probable es una artritis reactiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26708, 10362, '5. Está indicado iniciar tratamiento con metotrexato', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26709, 10363, '1. Tumor cerebral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26710, 10363, '2. Acromegalia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26711, 10363, '3. Vasculitis aislada del sistema nervioso central.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26712, 10363, '4. Enfermedad de Paget.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26713, 10363, '5. Arteritis de células gigantes', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26714, 10364, '1. Tratar con estatinas hasta que se normalice el colesterol y recomendar hábito de vida saludable (dieta, ejercicio y no fumar).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26715, 10364, '2. Descartar hipotiroidismo u otra enfermedad sistémica, recomendar hábito de vida saludable y tratar con fibratos para normalizar el colesterol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26716, 10364, '3. No precisa descartar dislipemia secundaria por ser infrecuente. Se debe realizar perfil lipídico familiar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26717, 10364, '4. Descartar dislipemia secundaria, tratar con resinas (resincolestiramina) y fibratos y recomendar hábito de vida saludable. Prohibir alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26718, 10364, '5. Descartar dislipemia secundaria, solicitar estudio familiar y tratar con estatinas para mantener un buen perfil lipídico. Control de otros factores de riesgo', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26719, 10365, '1. Glucemia > 200 mg/dl.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26720, 10365, '2. Leucocitosis > 16.000/mm3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26721, 10365, '3. Edad < 55 años.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26722, 10365, '4. LDH sérica > 350 UI/L.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26723, 10365, '5. GOT sérica > 250 UI/L', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26724, 10366, '1. Suspender alopurinol e iniciar tratamiento con colchicina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26725, 10366, '2. Suspender alopurinol y comenzar con AINE.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26726, 10366, '3. Añadir un AINE hasta que la crisis remita.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26727, 10366, '4. Aumentar la dosis de alopurinol a 300 mg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26728, 10366, '5. Sustituir el alopurinol por un uricosúrico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26729, 10367, '1. Ayuno prolongado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26730, 10367, '2. Ejercicio físico excesivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26731, 10367, '3. Hipoglucemia reactiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26732, 10367, '4. Insulinoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26733, 10367, '5. Iatrogénica', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26734, 10368, '1. Mantener la tensión arterial por debajo de 110/70 mmHg.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26735, 10368, '2. Abandono del hábito tabáquico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26736, 10368, '3. Mantener un índice de masa corporal (IMC) menor de 21.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26737, 10368, '4. Realizarse glucemia capilar basal a diario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26738, 10368, '5. Evitar las grasas animales en la dieta', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26739, 10369, '1. Se trata de una enfermedad hereditaria autosómica codominante, con una alta penetrancia, por lo que es frecuente que alguno de los progenitores y hermanos del individuo la padezcan también.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26740, 10369, '2. El trastorno genético afecta al gen que codifica el receptor del LDL colesterol y se han descrito más de 900 mutaciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26741, 10369, '3. El trastorno genético afecta también a la síntesis de los triglicéridos, provocando en las fases avanzadas de la enfermedad, un incremento de los mismos, que suele ser superior a los 500 mg/dl.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26742, 10369, '4. Los varones no tratados tienen una probabilidad cercana al 50% de sufrir un evento coronario antes de los 60 años de edad, y las mujeres con la enfermedad presentan una prevalencia de cardiopatía isquémica superior a la de la población general femenina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26743, 10369, '5. Las estatinas son eficaces en el tratamiento de la forma heterocigota de la enfermedad, pero a menudo necesitan combinarse con inhibidores de la absorción de colesterol para alcanzar los objetivos terapéuticos y el control de la enfermedad', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26744, 10370, '1. Su empleo es de segunda elección, cuando han fracasado los uricosúricos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26745, 10370, '2. Su empleo por tiempo prolongado es prácticamente obligado porque existen tofos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26746, 10370, '3. Su introducción debe demorarse hasta que se haya resuelto al ataque actual con antiinflamatorios o con colchicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26747, 10370, '4. Su introducción debe ser gradual hasta una dosis que consiga una uricemia inferior a 6 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26748, 10370, '5. En los primeros meses de tratamiento se aconseja asociar dosis bajar de colchicina para prevenir nuevos ataques', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26749, 10371, '1. Adenopatías.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26750, 10371, '2. Esplonomegalia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26751, 10371, '3. Hiperbilirrubinemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26752, 10371, '4. Incremento LDH sérica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26754, 10372, '1. Rasgo talasémico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26755, 10372, '2. Anemia central, arregenerativa, por déficit de ácido fólico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26756, 10372, '3. Anemia periférica, regenerativa, hemolítica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26757, 10372, '4. Anemia periférica, regenerativa, por hemorragia activa aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26758, 10372, '5. Anemia central, arregenerativa, por déficit de hierro', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26759, 10373, '1. Dado que la gestación es un estado protrombótico, existiría alto riesgo de tromboembolia venosa por lo que se debe desaconsejar el embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26760, 10373, '2. Se debe realizar tratamiento con heparina de bajo peso molecular a dosis profilácticas en el puerperio inmediato siendo opcional realizar igual tratamiento durante el embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26761, 10373, '3. El Factor V Leiden en heterocigosis es una trombofilia de bajo riesgo y no hay necesidad de ningún tratamiento en el embarazo y puerperio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26762, 10373, '4. Se debe aconsejar aspirina a bajas dosis durante todo el embarazo y puerperio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26763, 10373, '5. Debe realizar tratamiento con fármacos anti-vitamina K (Acenocumarol) durante el embarazo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26764, 10374, '1. Enfermedad de Alzheimer.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26765, 10374, '2. Enfermedad de Parkison.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26766, 10374, '3. Corea de Huntington.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26767, 10374, '4. Enfermedad de CADASIL (arteriopatía cerebral autosómica dominante con infartos cerebrales y leucoencefalopatía).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26768, 10374, '5. Ataxia-teleangiectasia', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26769, 10375, '1. Debut de una diabetes mellitus tipo 2, con disnea probablemente por neumonía o tromboembolismo, ya que toma anovulatorios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26770, 10375, '2. Es una cetoacidosis diabética. Hay que tratar con insulina endovenosa, sueroterapia, medidas generales y buscar causa precipitante.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26771, 10375, '3. Debut de diabetes tipo 1 con cetoacidosis. Tratar con bicarbonato y tras corregir la acidosis, añadir insulina endovenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26772, 10375, '4. Parece una cetoacidosis diabética, pero podría ser alcohólica. Se debe determinar la alcoholemia antes de iniciar tratamiento con insulina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26773, 10375, '5. Tratar con insulina rápida subcutánea, sueroterapia y pedirle que beba líquidos en abundancia', false, 5);
