INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26799, 10381, '1. Suele presentar respiración de Kussmaul.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26800, 10381, '2. Implica la necesidad de posterior tratamiento con insulina al solucionarse el cuadro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26801, 10381, '3. Tiene un elevado riesgo de mortalidad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26802, 10381, '4. Para su diagnóstico es necesaria la existencia de una osmolaridad eficaz superior a 280.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26803, 10381, '5. Precisa un aporte elevado de bicarbonato para su tratamiento', false, 5);
