INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26844, 10390, '1. La impresión diagnóstica es que se trata de una insuficiencia suprarrenal primaria o enfermedad de Addison.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26845, 10390, '2. La causa más frecuente de enfermedad de Addison es la autoinmune, por ello habitualmente no se realizan pruebas de imagen de suprarrenales para el diagnóstico etiológico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26846, 10390, '3. Ante la sospecha de insuficiencia suprarrenal primaria, la determinación de cortisol y ACTH basal es lo más sensible para establecer el diagnóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26847, 10390, '4. La dosis sustitutiva en la insuficiencia suprarrenal primaria es habitualmente de 15-30 mg/día de hidrocortisona en dosis divididas y suele ser necesario también administrar 0’05-0’1 mg de fludrocortisona diarios por vía oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26848, 10390, '5. En la enfermedad de Addison autoinmune es importante investigar la presencia de otras enfermedades autoinmunes órgano-específicas', false, 5);
