INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26909, 10403, '1. Porfiria de Doss, debiendo indicar profilaxis con compuestos de plomo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26910, 10403, '2. Porfiria aguda intermitente, cuyas crisis se evitan con clorodiacepóxido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26911, 10403, '3. Porfiria cutánea tarda, siendo eficaz la cloroquina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26912, 10403, '4. Protoporfiria eritropoyética. Su tratamiento consiste en sangrías periódicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26913, 10403, '5. Porfiria congénita de Günther. En algunas ocasiones son eficaces las tetraciclinas al ser estos antibióticos excelentes protectores solares', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26914, 10404, '1. Diabetes Mellitus tipo 2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26915, 10404, '2. Varón de 45 años fumador con antecedentes de muerte súbita en su padre a los 60 años.', true, 2);
