INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26917, 10404, '4. Estenosis carotidea ateroscleriótica > 50%.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26918, 10404, '5. Arteriopatía periférica', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26919, 10405, '1. Concentraciones de colesterol entre 175-250 mg/dl, a expensas de HDL, un hermano/a afecto/a de hipercolesterolemia, presencia de xantomas o el 25% de los familiares de primer grado hipercolesterolémicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26920, 10405, '2. Concentraciones de colesterol superiores a 300 mg/dl a expensas de LDL, un progenitor afecto, presencia de xantomas o el 50% de los familiares de primer grado hipercolesterolémicos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26921, 10405, '3. Colesterolemia superior a 300 mg/dl y antecedentes de accidentes vasculares encefálicos en un progenitor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26922, 10405, '4. Colesterolemia superior a 300 mg/dl y criterios de cardiopatía isquémica en ambos progenitores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26923, 10405, '5. Colesterolemia superior a 500 mg/dl, en más de dos familiares de primer grado junto con xantomas de hipotiroidismo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26924, 10406, '1. Sideremia, Ac. Fólico y Vitamina B12.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26925, 10406, '2. Sideremia, Índice de saturación de la transferrina y ferritina sérica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26926, 10406, '3. La ferritina sola es suficiente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26927, 10406, '4. Si la sideremia está claramente bajo, no hacen falta otros datos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26928, 10406, '5. El hemograma contiene datos suficientes: Concentración de hemoglobina, número de hematíes por mm3 , valor hematocrito, VCM, CHCM, HCM y RDW', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26929, 10407, '1. El factor de crecimiento derivado de las plaquetas (PDGF) tiene un papel importante en la síntesis del colágeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26930, 10407, '2. El factor de crecimiento derivado de las plaquetas (PDGF) no es liberado por los macrófagos de la herida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26931, 10407, '3. El factor de crecimiento del endotelio vascular (VEGF) estimula la angiogénesis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26932, 10407, '4. El factor de crecimiento derivado de las plaquetas (PDGF) tiene un papel destacado en la migración y proliferación de los fibroblastos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26933, 10407, '5. La interleukina 1 (IL1) no está implicada en la angiogénesis', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26934, 10408, '1. Causan alta incidencia de reacciones adversas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26935, 10408, '2. Son el tratamiento de primera elección en el asma aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26936, 10408, '3. Tienen efecto antiagregante plaquetario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26937, 10408, '4. Son útiles como tratamiento complementario en el asma leve y moderada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26938, 10408, '5. Son de primera elección en bronquitis aguda', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26939, 10409, '1. Favorecen la gluconeogénesis en el hígado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26940, 10409, '2. Disminuyen la eliminación de nitrógeno.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26941, 10409, '3. Inhibe la respuesta inmunitaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26942, 10409, '4. Aumenta la eliminación renal de agua exenta de solutos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26943, 10409, '5. Protege contra el estrés', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26944, 10410, '1. Que no sigue correctamente la dieta.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26945, 10410, '2. Que no es una enfermedad celíaca lo que padece ese enfermo.', false, 2);
