INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26968, 10414, '5. Iniciar tratamiento gradual con betabloqueantes', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26969, 10415, '1. Solo se presenta en pacientes con diabetes tipo', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26970, 10415, '2. Es la forma de inicio de la retinopatía en pacientes diabéticos mal controlados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26971, 10415, '3. Es frecuente que provoque hemorragias de vitreo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26972, 10415, '4. Se caracteriza por la presencia de microaneurismas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26973, 10415, '5. Suele aparecer después de los 60 años de edad', false, 5);
