INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26975, 10416, '2. Los virus son capaces de iniciar el proceso de destrucción de la célula beta propio de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (26976, 10416, '3. No existe alteración en la secreción de la insulina.', false, 3);
