INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27039, 10429, '1. Pensar en que puede estar pasando un período de “luna de miel” y probablemente se puede retirar la insulina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27040, 10429, '2. Se debe sospechar que hace hipoglucemias en relación con la aparición de un insulinoma.', false, 2);
