INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30639, 11225, '5. Quinto grado.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27130, 10449, '1. Es más frecuente en varones jóvenes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27131, 10449, '2. Las arritmias auriculares son bien toleradas.', false, 2);
