INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27145, 10452, '4. Neumonitis alérgica extrínseca', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27146, 10453, '1. Debemos administrar oxigenoterapia, furosemida y nitroglicerina para el control de su disnea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27147, 10453, '2. Es esperable encontrar valores de NT-proBNP inferiores a 450 pg/ml dado que la paciente tiene obesidad grado I.', true, 2);
