INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27149, 10453, '4. No se puede descartar la presencia de síndrome de apnea del sueño como factor agravante de la disnea en esta paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27150, 10454, '1. Añadir ivabradina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27151, 10454, '2. Aumentar la dosis de enalapril.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27152, 10454, '3. Adicción de tratamiento inotrópico intermitente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27153, 10454, '4. Añadir espironolactona 25 mg diariamente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27154, 10455, '1. Inhibición del sistema arginina-vasopresina, que genera vasoconstricción y retención hidrosalina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27155, 10455, '2. Desarrollo de hipertrofia miocárdica, para normalizar la sobrecarga de la pared ventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27156, 10455, '3. Activación del sistema nervioso simpático, que aumenta la contractilidad ventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27157, 10455, '4. Alteraciones en la producción de energía en el miocardio y modificaciones en la matriz extracelular de los miocardiocitos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27158, 10456, '1. Ivabradina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27159, 10456, '2. Inhibidores de la enzima convertidora de angiotensina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27160, 10456, '3. Anti-aldosterónicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27161, 10456, '4. Beta-bloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27162, 10457, '1. Añadiría espironolactona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27163, 10457, '2. Suspendería tratamiento betabloqueante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27164, 10457, '3. Añadiría al tratamiento amiodarona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27165, 10457, '4. Añadiría al tratamiento verapamil.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27166, 10458, '1. Administrar furosemida por vía intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27167, 10458, '2. Aumentar dosis de enalapril según tolerancia y administrar furosemida por vía intravenosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27168, 10458, '3. Iniciar un beta-bloqueante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27169, 10458, '4. Añadir tratamiento con amlodipino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27170, 10459, '1. El tratamiento inicial debería dirigirse al proceso patológico subyacente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27171, 10459, '2. El tratamiento con diuréticos debe iniciarse a dosis altas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27172, 10459, '3. En caso de precisar tratamiento con nitratos debe iniciarse a dosis bajas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27173, 10459, '4. La disnea puede tratarse reduciendo la activación neurohormonal con inhibidores de la enzima convertidora de la angiotensina o antagonistas de los receptores de la angiotensina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27174, 10460, '1. Entre el 60 y el 70% de los pacientes fallecen en los primeros 5 años tras establecerse el diagnóstico de insuficiencia cardiaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27175, 10460, '2. La situación funcional del paciente con insuficiencia cardiaca es la que mejor se correlaciona con la expectativa de supervivencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27176, 10460, '3. La disfunción diastólica predomina en mujeres de edad avanzada con historia de hipertensión crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27177, 10460, '4. La insuficiencia cardiaca por disfunción sistólica suele objetivarse en pacientes varones afectos de cardiopatía isquémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27178, 10460, '5. La prevalencia de la insuficiencia cardiaca está reduciéndose en la última década gracias al mejor control de los factores de riesgo cardiovascular.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27179, 10461, '1. El paciente probablemente presente una neumonía y lo prioritario es realizar una Rx de tórax para confirmarlo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27180, 10461, '2. Probablemente se trate de una agudización de su EPOC debido a una sobreinfección respiratoria. Reforzar el tratamiento de base con un beta-2 inhalado, corticoides y antibióticos y vigilar evolución.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27181, 10461, '3. Es probable que tenga un componente de insuficiencia cardiaca izquierda asociada a una infección respiratoria febril. Sería prioritario el tratarlo con vasodilatadores y diuréticos además del tratamiento que corresponda a su infección respiratoria, broncodilatadores, etc.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27182, 10461, '4. El paciente no está clasificado de la gravedad de su EPOC por lo que indicaría una espirometría inmediata para ajustar el tratamiento a la gravedad de la obstrucción. Asociaría además un antibiótico dado el cuadro aparente de sobreinfección respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27183, 10461, '5. Un ecocardiograma sería la primera exploración a realizar para descartar un posible componente de insuficiencia cardiaca asociado al cuadro de EPOC agudizado que presenta el paciente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27184, 10462, '1. Los bloqueantes del receptor de la angiotensina (ARA II) han demostrado superioridad sobre los inhibidores de la enzima convertidora de angiotensina (IECA) y deberían ser la primera opción terapéutica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27185, 10462, '2. Los antagonistas de la aldosterona no han demostrado mejoría pronóstica, estando contraindicados en pacientes con disfunción sistólica avanzada y grado funcional IV.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27186, 10462, '3. Los betabloqueantes han demostrado disminuir la mortalidad en pacientes con fracción de eyección disminuida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27273, 10479, '5. Iniciar tratamiento gradual con betabloqueantes.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31679, 11455, '1. Dopamina', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27187, 10462, '4. La terapia mediante marcapasos de resincronización cardiaca está indicada en pacientes con disfunción sistólica siempre que el QRS sea estrecho (inferior a 120 msg).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27188, 10462, '5. El implante de desfibriladores automáticos está contraindicado en pacientes con disfunción ventricular, especialmente si es de causa isquémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27189, 10463, '1. Intoxicación digitálica por interacción farmacocinética por verapamilo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27190, 10463, '2. Hipopotasemia por la administración de tiazida y digoxina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27191, 10463, '3. Interacción farmacodinámica del betabloqueante, digoxina y verapamil.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27192, 10463, '4. Efecto hipotensor del diurético tiazídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27193, 10463, '5. Arritmia cardiaca por verapamil.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27194, 10464, '1. Le colocaría ventilación no invasiva pues mejora la oxigenación, la función cardiaca y reduce la necesidad de intubación orotraqueal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27195, 10464, '2. Le administraría morfina porque reduce la precarga y mejora la disnea y la ansiedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27196, 10464, '3. Le administraría nitroglicerina intravenosa por sus efectos venodilatadores y vasodilatadores coronarios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27197, 10464, '4. El nitroprusiato es el vasodilatador recomendado.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27198, 10464, '5. Al administrar furosemida se reducirá la precarga antes de iniciar su efecto diurético.', false, 5);
