INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27254, 10476, '1. Insuficiencia cardiaca inestable.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27255, 10476, '2. Enfermedad pulmonar crónica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27256, 10476, '3. Bloqueo A-V avanzado.', false, 3);
