INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27258, 10476, '5. Broncoespasmo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27259, 10477, '1. Realizar una dieta hiposódica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27260, 10477, '2. Pesarse a diario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27261, 10477, '3. Realizar ejercicio físico a diario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27262, 10477, '4. Tomar ibuprofeno si presenta dolor lumbar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27263, 10477, '5. Contactar con un médico si aparece hinchazón de piernas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27264, 10478, '1. Consumo máximo de oxígeno <10 mL/kg por minuto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27265, 10478, '2. Disfunción ventricular izquierda <25%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27266, 10478, '3. Hiponatremia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27267, 10478, '4. Valores de BNP (péptido natriurético tipo B) disminuidos (<100 pg/ml).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27268, 10478, '5. Extrasistolia ventriculares frecuentes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27269, 10479, '1. Iniciar tratamiento con antagonistas del calcio y nitritos orales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27270, 10479, '2. Sustituir la Aspirina por Clopidogrel.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27271, 10479, '3. Hacer una broncoaspiración y cultivo del material aspirado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27272, 10479, '4. Añadir Digoxina oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27274, 10480, '1. Disfunción ventricular sistólica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27275, 10480, '2. Enfermedad pulmonar obstructiva crónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27276, 10480, '3. Asma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27277, 10480, '4. Hipertensión pulmonar primaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27278, 10480, '5. Tromboembolismo pulmonar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27279, 10481, '1. Cambiar el captopril por lisinopril (20 mg/día).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27280, 10481, '2. Iniciar tratamiento con digoxina (0,25 mg/día).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27281, 10481, '3. Iniciar tratamiento con espironolactona (25 mg/día).', false, 3);
