INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27283, 10481, '5. Iniciar tratamiento con simvastatina (40 mg/día).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27284, 10482, '1. Betabloqueantes, calcioantagonistas e inhibidores de la enzima conversiva de la angiotensina (IECA).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27285, 10482, '2. IECA, diuréticos y calcioantagonistas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27286, 10482, '3. Diuréticos, betabloqueantes e IECA.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27287, 10482, '4. Betabloqueantes, antagonistas de los receptores de la angiotensina (ARA-II) e IECA.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27288, 10482, '5. ARA-II, IECA y calcioantagonistas.', false, 5);
