INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27290, 10483, '2. Péptidos Natriuréticos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27291, 10483, '3. Hormona Antidiurética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27292, 10483, '4. Actividad Adrenérgica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27293, 10483, '5. Aldosterona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27294, 10484, '1. Infiltración inflamatoria intersticial de carácter mixto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27295, 10484, '2. Necrosis fibrinoide de la pared vascular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27296, 10484, '3. Proliferación fibrosa endointimal arterial estenosante.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27297, 10484, '4. Angiogénesis difusa del injerto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27298, 10484, '5. Infecciones frecuentes y de repetición del injerto por gérmenes piógenos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27299, 10485, '1. Una espirometría demostrará casi con seguridad un patrón obstructivo, por lo que se debe comenzar tratamiento broncodilatador.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27300, 10485, '2. La fibrosis pulmonar idiopática requiere una biopsia pulmonar para su diagnóstico. Se le debe recomendar una broncoscopia o biopsia transbronquial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27301, 10485, '3. Una ergometría ambulante sería recomendable para descartar una isquemia silente, muy frecuente en diabéticos, pero no es preciso si el electrocardiograma basal no muestra ondas Q ni alteraciones de la repolarización.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27302, 10485, '4. Está indicado el ingreso y descartar lo antes posible una cardiopatía isquémica, iniciar tratamiento diurético parenteral y vasodilatador (inhibidores de la angiotensina convertasa), posiblemente añadir un betabloqueante y controlar los factores de riesgo cardiovascular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27303, 10485, '5. Si en un ecocardiograma la fracción de eyección es normal, se descartaría razonablemente la insuficiencia cardiaca y se deberían buscar otras causas de su problema (por ejemplo, enfermedad pulmonar obstructiva crónica agudizada).', false, 5);
