INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27329, 10491, '1. Suspender anticoagulantes orales', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27330, 10491, '2. Realizar monitorización de Holter.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27331, 10491, '3. Solicitar niveles de digoxina.', true, 3);
