INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27335, 10492, '2. Añadir resinas de intercambio iónico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27336, 10492, '3. Añadir Digitálicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27337, 10492, '4. Suspender los IECAS y la Espironolactona.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27338, 10492, '5. Suspender la Espironolactona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27339, 10493, '1. Fracción de eyección deprimida (<25%).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27340, 10493, '2. Concentraciones séricas bajas de Na y/o K.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27341, 10493, '3. Identificación de factores precipitantes reconocibles.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27342, 10493, '4. Incapacidad para caminar en llano 3 minutos tras la recuperación de la situación aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27343, 10493, '5. Disminución del consumo máximo de oxígeno.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27344, 10494, '1. Infarto agudo de miocardio con elevación del segmento ST, anterior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27345, 10494, '2. Bloqueo aurículo ventricular (AV) de primer grado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27346, 10494, '3. Bloqueo AV de segundo grado, tipo II.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27347, 10494, '4. Bloqueo AV de tercer grado.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27348, 10495, '1. Fibrilación auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27349, 10495, '2. Flutter auricular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27350, 10495, '3. Infarto agudo de miocardio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27351, 10495, '4. Taquicardia ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27352, 10496, '1. Asincronía ventricular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27353, 10496, '2. Miocardiopatía dilatada.', false, 2);
