INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27356, 10497, '1. Cirugía de reparación valvular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27357, 10497, '2. Cirugía de sustitución valvular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27358, 10497, '3. Terapia de resincronización cardíaca.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27359, 10497, '4. Mitra-Clip.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27360, 10498, '1. El tratamiento del síncope reflejo es fundamentalmente farmacológico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27361, 10498, '2. La estimulación con marcapasos en el síncope recurrente asociado a un mecanismo hipotensor ha demostrado ser eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27362, 10498, '3. Los fármacos betabloqueantes reducen la mortalidad de los síncopes reflejos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27363, 10498, '4. Las contracciones musculares isotónicas son útiles en pacientes jóvenes con síncope reflejo y pródromos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27364, 10499, '1. Lidocaína IV.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27365, 10499, '2. Amiodarona IV.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27366, 10499, '3. Procainamida IV.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27367, 10499, '4. Cardioversión eléctrica urgente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27368, 10500, '1. Síncope producido al rotar la cabeza o presionar el seno carotídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27369, 10500, '2. Síncope durante el esfuerzo o en decúbito supino.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27370, 10500, '3. Síncope después de una visión, sonido u olor desagradable.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27371, 10500, '4. Bloqueo aurículoventricular de segundo grado Mobitz I.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27372, 10501, '1. Flutter o aleteo auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27373, 10501, '2. Taquicardia ventricular polimórfica tipo torsade de pointes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27374, 10501, '3. Taquicardia aurículo-ventricular recíproca en el síndrome de Wolff-Parkinson-White.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27375, 10501, '4. Taquicardias asociadas a defectos del tabique interauricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27376, 10502, '1. Los betabloqueantes están contraindicados en el QT largo congénito.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27377, 10502, '2. Los antidepresivos tricíclicos pueden dar lugar a un QT largo adquirido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27378, 10502, '3. Predispone a la taquicardia ventricular polimórfica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27379, 10502, '4. Su fisiopatología se basa en una alteración de los canales iónicos responsables del potencial de acción transmembrana de la célula miocárdica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27380, 10503, '1. Marcapasos DDD (bicameral).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27381, 10503, '2. Marcapasos VVI (unicameral ventricular).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27382, 10503, '3. Marcapasos AAI (unicameral auricular).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27383, 10503, '4. Terapia de resincronización ventricular (TRC).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27384, 10504, '1. Verapamilo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27385, 10504, '2. Digoxina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27386, 10504, '3. Adenosina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27387, 10504, '4. Procainamida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27388, 10505, '1. Taquicardia sinusal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27389, 10505, '2. Flutter auricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27390, 10505, '3. Extrasístoles auriculares frecuentes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27391, 10505, '4. Fibrilación auricular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27392, 10506, '1. Ia (por ejemplo, procainamida).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27393, 10506, '2. Ib (por ejemplo, lidocaína).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27394, 10506, '3. II (por ejemplo, bisoprolol).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27395, 10506, '4. IV (por ejemplo, diltiazem).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27396, 10507, '1. Una valvulopatía reumática con estenosis mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27397, 10507, '2. Una embolia de pulmón con infarto pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27398, 10507, '3. Una enfermedad infiltrativa o inflamatoria sistémica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27399, 10507, '4. Una trombosis de vena cava inferior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27400, 10508, '1. Una taquicardia ventricular polimorfa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27401, 10508, '2. Un infarto agudo de miocardio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27402, 10508, '3. Un ictus cardioembólico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27403, 10508, '4. Un bloqueo aurículoventricular completo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27404, 10509, '1. Síndrome de QT largo adquirido y torsades de pointes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27405, 10509, '2. Infarto agudo de miocardio y taquicardia ventricular polimórfica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27406, 10509, '3. Fibrilación auricular y aberrancia de rama.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27407, 10509, '4. Taquicardia ventricular monomorfa sostenida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27408, 10510, '1. Seguir con el masaje cardiaco y aislar la vía aérea mediante intubación orotraqueal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27409, 10510, '2. Conseguir un acceso venoso para administrar adrenalina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27410, 10510, '3. Cargar el desfibrilador y aplicar una descarga para continuar inmediatamente con el masaje cardiaco.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27411, 10510, '4. Avisar al centro coordinador de emergencias para que os envíen ayuda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27412, 10511, '1. Verapamilo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27413, 10511, '2. Atenolol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27414, 10511, '3. Adenosina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27415, 10511, '4. Digoxina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27416, 10512, '1. Taquicardia auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27417, 10512, '2. Taquicardia supraventricular por reentrada intranodal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27418, 10512, '3. Taquicardia ventricular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27419, 10512, '4. Flutter auricular atípico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27420, 10513, '1. Compresiones torácicas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27421, 10513, '2. Golpe precordial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27422, 10513, '3. Ventilaciones de rescate.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27423, 10513, '4. Intubación oro-traqueal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27424, 10514, '1. Este paciente debe estar anticoagulado oralmente de por vida, salvo contraindicación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27425, 10514, '2. Si decidimos realizar una cardioversión a su llegada a Urgencias, sería necesario hacer previamente una ecocardiografía transesofágica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27426, 10514, '3. Al ser el primer episodio de fibrilación auricular es el candidato idóneo para realizar una ablación con catéter.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27427, 10514, '4. Para frenar la frecuencia cardiaca podríamos emplear betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27428, 10515, '1. Desfibrilación inmediata. Pedir ayuda. Maniobras de soporte vital. Cuidados postresucitación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27429, 10515, '2. Abrir la vía aérea. Pedir ayuda. Desfibrilación. Cuidados post-resucitación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27430, 10515, '3. Compresiones torácicas inmediatas. Desfibrilación y solicitud de ayuda. Cuidados postresucitación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27431, 10515, '4. Ventilación boca a boca. Compresiones torácicas intermitentes. Desfibrilación. Solicitar ayuda. Cuidados post-resucitación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27432, 10515, '5. Reconocimiento precoz y pedir ayuda. Resucitación cardiopulmonar precoz. Desfibrilación precoz. Cuidados post-resucitación.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27433, 10516, '1. El paciente tiene un bloqueo aurículoventricular de 3º grado y precisa la implantación de un marcapasos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27434, 10516, '2. La ausencia de periodos de asistolia >3 segundos excluye una causa cardiaca de los mareos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27435, 10516, '3. Estaría indicado un tratamiento farmacológico que incrementara la conducción en el nodo aurículo-ventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27436, 10516, '4. El paciente presenta una disfunción sinusal con bloqueo sinoauricular y requiere, por presentar síntomas, la implantación de marcapasos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27437, 10516, '5. Las alteraciones detectadas en el electrocardiograma ambulatorio son propias de pacientes de esta edad y no hay indicación de intervención terapéutica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27438, 10517, '1. Intoxicación digitálica por interacción farmacocinética por verapamilo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27439, 10517, '2. Hipopotasemia por la administración de tiazida y digoxina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27440, 10517, '3. Interacción farmacodinámica del betabloqueante, digoxina y verapamil.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27441, 10517, '4. Efecto hipotensor del diurético tiazídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27442, 10517, '5. Arritmia cardiaca por verapamil.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27443, 10518, '1. Taquicardia de reentrada aurículo ventricular mediada por una vía lenta intranodal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27444, 10518, '2. Síndrome de Brugada asociado a taquicardias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27445, 10518, '3. Síndrome de Wolff-Parkinson-White y fibrilación auricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27446, 10518, '4. Taquicardia ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27447, 10518, '5. Vía accesoria aurículo ventricular y taquicardia de reentrada ortodrómica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27448, 10519, '1. Tratamiento quirúrgico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27449, 10519, '2. Tratamiento con amiodarona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27450, 10519, '3. Ablación con catéter de la vía accesoria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27451, 10519, '4. Marcapasos antitaquicardia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27452, 10519, '5. Desfibrilador automático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27453, 10520, '1. El paciente ha de ser ingresado para implantarle un marcapasos definitivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27454, 10520, '2. Se trata de un síncope vasovagal y el bloqueo es de bajo grado por lo que puede ser dado de alta para seguimiento y control ambulatorio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27455, 10520, '3. Para el manejo de este paciente es indispensable la realización de una coronariografía con vistas a descartar sustrato coronario que justifique su clínica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27456, 10520, '4. Si la extrasistolia auricular es muy sintomática se puede pautar tratamiento con betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27457, 10520, '5. Necesitamos una TC craneal para descartar patología neurológica que justifique su clínica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27458, 10521, '1. Digoxina y ácido acetilsalicílico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27459, 10521, '2. Atenolol y ácido acetilsalicílico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27460, 10521, '3. Verapamilo y acenocumarol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27461, 10521, '4. Carvedilol y acenocumarol.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27462, 10521, '5. Carvedilol y clopidogrel.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27463, 10522, '1. Bloqueo aurículo-ventricular de tercer grado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27464, 10522, '2. Estenosis valvular aórtica degenerativa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27465, 10522, '3. Insuficiencia valvular mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27466, 10522, '4. Miocardiopatía hipertrófica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27467, 10522, '5. Miocardiopatía dilatada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27468, 10523, '1. Historia clínica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27469, 10523, '2. Electrocardiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27470, 10523, '3. Registro Holter.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27471, 10523, '4. Electroencefalograma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27472, 10523, '5. TC de cráneo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27473, 10524, '1. Aun en caso de asistolia debe intentarse desfibrilación como primera opción.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27474, 10524, '2. La energía inicial recomendada para desfibrilar con un desfibrilador bifásico es de 150200 J y de 360 J con uno monofásico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27475, 10524, '3. La adrenalina continúa siendo la catecolamina de elección para el tratamiento de la parada cardiaca en todos los ritmos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27476, 10524, '4. La dosis de adrenalina por vía intratraqueal es de 3 mg diluida en al menos 10 ml de agua estéril.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27477, 10524, '5. En caso de que la fibrilación ventricular/taquicardia ventricular persista tras 3 choques, debe administrarse un bolo de 300 mg de amiodarona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27478, 10525, '1. Insuficiencia respiratoria crónica agudizada por sobreinfección vírica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27479, 10525, '2. Insuficiencia cardíaca aguda por disfunción ventricular secundaria a infarto agudo de miocardio complicado con una taquicardia ventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27480, 10525, '3. Insuficiencia cardiaca aguda secundaria a fibrilación auricular persistente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27481, 10525, '4. Edema agudo de pulmón secundario a miocardiopatia hipertrófica obstructiva complicada con caída en fibrilación auricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27482, 10525, '5. Edema agudo de pulmón por probable descompensación de estenosis aórtica del anciano.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27483, 10526, '1. Diuréticos, oxigenoterapia, nitroglicerina endovenosa, cardioversión imnediata seguida de Lidocaína endovenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27484, 10526, '2. Intubación y ventilación mecánica, seguido de establilización con broncodilatadores, corticoides y antibióticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27485, 10526, '3. Antibióticos, oxigenoterapia, corticoides y broncodilatadores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27486, 10526, '4. Estabilización con furosemida endovenosa, digoxina endovenosa, oxigenoterapia, aspirina, nitroglicerina endovenosa. Cateterismo cardíaco urgente para proceder a la colocación de un stent intracoronario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27487, 10526, '5. Oxigenoterapia, furosemida endovenosa, digoxina endovenosa, vasodilatadores y heparinización.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27488, 10527, '1. Necesita tratamiento de la insuficiencia Cardíaca.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27489, 10527, '2. Puede presentar crisis de taquicardia paroxística supraventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27490, 10527, '3. La ecocardiografía 2D-Dopper descartará su asociación con la Enfermedad de Ebstein.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27491, 10527, '4. Es conveniente se la practique un E.C.G. de 24 horas (Holter) y una Ergometría.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27492, 10527, '5. En determinados pacientes la ablación de la vía accesoria con radiofrecuencia constituye la acción terapéutica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27493, 10528, '1. Digoxina 1 mg iv en bolo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27494, 10528, '2. Adenosina 6 mg iv en bolo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27495, 10528, '3. Amiodarona 5 mg/kg iv en 30 minutos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27496, 10528, '4. Flecainida 2 mg/kg iv en 20 minutos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27497, 10528, '5. Cardioversión eléctrica con choque DC sincronizado de 200 Julios.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27498, 10529, '1. El riesgo de accidente cerebro vascular embolígeno es similar en la FA paroxística y en la FA crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27499, 10529, '2. La anticoagulación crónica en la FA solitaria está indicada preferentemente en pacientes jóvenes (< 60 años) y sin factores de riesgo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27500, 10529, '3. La amiodarona es más efectiva en prevenir recaídas en FA y mantener el ritmo sinusal que los fármacos IA y IC.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27501, 10529, '4. En el tratamiento crónico la digoxina habitualmente es insuficiente para el control de la frecuencia durante el ejercicio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27502, 10530, '1. Pacientes asintomáticos cuando la frecuencia sinusal es inferior a 50 latidos por minuto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27503, 10530, '2. Presencia de bloqueo AV de primer grado asintomático cuando el pR es superior a los 200 msg.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27504, 10530, '3. El bloqueo alternante de ramas del haz de His.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27505, 10530, '4. Cualquier situación con bloqueo AV de segundo grado Mobitz I a nivel nodal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27506, 10530, '5. Síncope neurocardiogénico con respuesta cardioinhibidora negativa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27507, 10531, '1. De momento no iniciar tratamiento y profundizar en el diagnóstico realizando una coronariografía para excluir una estenosis coronaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27508, 10531, '2. Amiodarona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27509, 10531, '3. Propafenona o flecainida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27510, 10531, '4. Betabloqueantes o sotalol y aspirina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27511, 10531, '5. No precisa tratamiento farmacológico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27512, 10532, '1. En nuestro medio, la causa más frecuente de muerte súbita de origen cardiaco es la presencia de un infarto agudo de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27513, 10532, '2. Una vez recuperado el ritmo sinusal, el ECG puede mostrar alteraciones que sugieran la presencia de alteraciones genéticamente determinadas como un síndrome de Brugada, un síndrome del QT largo o una miocardiopatía hipertrófica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27514, 10532, '3. El síndrome de Brugada se ha asociado con la presencia de mutaciones en el canal de sodio cardiaco, presenta un ECG característico con bloqueo de rama derecha y elevación del segmento ST y la muerte súbita puede ser la primera manifestación de la enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27515, 10532, '4. El síndrome del QT largo se caracteriza por la presencia de un intervalo QT prolongado en el ECG, los pacientes pueden presentar episodios de síncope o muerte súbita debidos a taquicardias ventriculares polimórficas denominadas “torsade de pointes” y el tratamiento de elección es la administración de betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27516, 10532, '5. En la miocardiopatía hipertrófica, la muerte súbita aparece en reposo, sin relación con los esfuerzos y es debida a la presencia de una obstrucción a la salida de sangre del ventrículo izquierdo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27517, 10533, '1. Deben descartarse factores precipitantes como hipertiroidismo o embolismo pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27518, 10533, '2. La anticoagulación está indicada en todos los casos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27519, 10533, '3. En situaciones de inestabilidad hemodinámica es adecuado el tratamiento de cardioversión eléctrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27520, 10533, '4. Cuando el diámetro de la aurícula izquierda es mayor de 45 mm, puede ser difícil revertir a ritmo sinusal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27521, 10533, '5. Cuando el diámetro de la aurícula izquierda es mayor de 45 mm, puede ser difícil mantener el ritmo sinusal, si se consigue la reversión.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27522, 10534, '1. Extrasistoles ventriculares complejos sintomáticos en paciente sin cardiopatía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27523, 10534, '2. Taquicardia ventricular incesante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27524, 10534, '3. Fibrilación ventricular que ocurre en la primera hora tras un infarto agudo de miocardio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27525, 10534, '4. Parada cardiaca por fibrilación ventricular en paciente con infarto de miocardio crónico anterior extenso.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27526, 10534, '5. Síncopes de repetición en paciente con estudio cardiológico normal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27527, 10535, '1. Es una arritmia que se observa en menos del 30% de los varones adultos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27528, 10535, '2. Esta arritmia, tiene mayor importancia pronóstica que la fracción de eyección ventricular izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27529, 10535, '3. Cuando aparecen en un Holter, obligan a ser tratadas de inmediato con fármacos antiarrítmicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27530, 10535, '4. En pacientes con infarto previo y disfunción ventricular izquierda, si son frecuentes (> 10/hora) empeoran el pronóstico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27531, 10535, '5. En pacientes con infarto previo, si son sintomáticas, el fármaco de elección es la flecainida por vía oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27532, 10536, '1. Hombre de 55 años sin cardiopatía, con fibrilación auricular crónica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27533, 10536, '2. Mujer de 75 años con fibrilación auricular paroxística y antecedentes de hipertensión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27534, 10536, '3. Mujer de 45 años con estenosis mitral (área valvular por ecocardiograma de 1.8 cm2) con fibrilación auricular paroxística.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27535, 10536, '4. Hombre de 60 años con antecedentes de accidente cerebrovascular y fibrilación auricular paroxística controlada con fármacos antiarrítmicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27536, 10536, '5. Mujer de 60 años con fibrilación auricular crónica y prótesis valvular mecánica en posición aórtica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27537, 10537, '1. Fibrilación Ventricular en paciente con Infarto de Miocardio previo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27538, 10537, '2. Fibrilación Ventricular en paciente con Infarto Agudo de Miocardio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27539, 10537, '3. Fibrilación Ventricular en el seno de una Miocardiopatía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27540, 10537, '4. Paciente de alto riesgo arrítmico en una familia con canalopatía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27541, 10537, '5. Síncope de origen no filiado en paciente con arritmias ventriculares malignas inducibles en el Laboratorio de Electrofisiología.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27542, 10538, '1. Representa el mecanismo más frecuente de taquicardia supraventricular y afecta de manera predominante a mujeres.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27543, 10538, '2. Se presenta habitualmente como una taquicardia paroxística, regular, con complejo QRS estrecho.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27544, 10538, '3. Durante la taquicardia la onda P retrógrada aparece situada a unos 160 milisegundos después del inicio del complejo QRS.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27545, 10538, '4. Clínicamente la característica principal es la sensación de palpitaciones en el cuello debida a la aparición de un reflujo yugular por contracción simultánea de aurículas y ventrículos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27546, 10538, '5. En casos de taquicardias recurrentes el tratamiento de elección es la ablación con radiofrecuencia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27547, 10539, '1. La etiología principal de la taquicardia ventricular en España es la cardiopatía isquémica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27548, 10539, '2. Las manifestaciones clínicas de una taquicardia ventricular tienen relación con la duración y frecuencia de la arritmia y con el grado de afectación del miocardio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27549, 10539, '3. La aparición de una disociación aurículoventricular en el electrocardiograma durante una taquicardia con complejo QRS ancho es un signo patognómico del origen ventricular de la taquicardia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27550, 10539, '4. Son signos de mal pronóstico la aparición de paro cardíaco o síncope durante la arritmia clínica y la presencia de disfunción ventricular izquierda concomitante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27551, 10539, '5. El tratamiento del episodio agudo de taquicardia es la cardioversión eléctrica externa. En caso de taquicardia bien tolerada puede ensayarse un tratamiento farmacológico con amiodarona, procainamida o verapamilo intravenoso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27552, 10540, '1. Buen control de la hipertensión arterial que con frecuencia padecen estos enfermos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27553, 10540, '2. Digoxina asociada a un fármaco que disminuya la conducción en el nodo A-V (anticálcicos o beta-bloqueantes).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27554, 10540, '3. Ablación con catéter y radiofrecuencia del istmo cavotricuspídeo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27555, 10540, '4. Inserción de un marcapasos con capacidad antitaquicardia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27556, 10540, '5. Amiodarona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27557, 10541, '1. En el ECG complejos QRS están arrítmicos', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27558, 10541, '2. Fracción de eyección calculada en ecocardiograma, 57%', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27559, 10541, '3. En la placa de tórax se ven líneas B de Kerley', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27560, 10541, '4. En el ECG hay ondas P anchas y bifásicas', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27561, 10541, '5. En el ECG muestra un QRS con eje a +11º', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27562, 10542, '1. Debe ser siempre tratada con fármacos antiarrítmicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27563, 10542, '2. Se debe tratar con fármacos, únicamente cuando se detecten más de 10 extrasístoles ventriculares por hora.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27564, 10542, '3. No compromete el pronóstico, ni debe ser tratada con antiarrítmicos cuando asiente sobre corazón estructuralmente normal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27565, 10542, '4. Está demostrado que la superación de la extrasistolia ventricular con fármacos antiarrítmicos mejora la supervivencia, en cardiopatía isquémica crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27566, 10542, '5. La extrasistolia ventricular de alta densidad no es un predictor pronóstico en la cardiopatía isquémica crónica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27567, 10543, '1. Primer tono fuerte', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27568, 10543, '2. Segundo tono ampliamente desdoblado', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27569, 10543, '3. Soplo diastólico de llenado', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27570, 10543, '4. Chasquido de apertura', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27571, 10543, '5. Onda “a” en pulso venoso yugular', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27572, 10544, '1. Hacer ECG y establecer el diagnóstico diferencial del tipo y origen de la taquicardia, realizar maniobras vagales y si no cede, inyectar por vía i.v. adenosina, adenosin trifosfato (ATP) o verapamil.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27573, 10544, '2. Hacer ECG de 12 derivaciones y si el QRS es estrecho, inyectar cualquier fármaco antiarrítmico de tipo IA.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27574, 10544, '3. Tras hacer ECG y realizar maniobras vagales, administrar amiodarona por vía i.v.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27575, 10544, '4. Tras la monitorización ECG y una vez realizado el diagnóstico diferencial del origen y mecanismo de la arritmia, llevar a cabo la cardioversión eléctrica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27576, 10544, '5. Tras hacer ECG de 12 derivaciones, debe administrarse digital i.v. para comprobar el efecto sobre la frecuencia de la taquicardia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27577, 10545, '1. Estenosis mitral y fibrilación auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27578, 10545, '2. Fibrilación auricular y embolismo previo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27579, 10545, '3. Prótesis mitral mecánica en ritmo sinusal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27580, 10545, '4. Fibrilación auricular aislada en mujer de 55 años.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27581, 10545, '5. Miocardiopatía dilatada y fibrilación auricular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27582, 10546, '1. Se detecta bradicardia nocturna en ECG o monitorización ECG ambulatoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27583, 10546, '2. Sólo diagnosticaremos enfermedad del nódulo sinusal cuando el estudio electrofisiológico demuestre tiempos de recuperación del nódulo sinusal o tiempos de conducción sinoatrial prolongados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27584, 10546, '3. El diagnóstico de nódulo sinusal enfermo solo puede hacerse cuando se produzca bradicardia intensa con el masaje del seno carotideo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27585, 10546, '4. Cuando se detecte bradicardia diurna persistente, paros sinusales o bloqueo sinoatrial de segundo grado, a veces complicado con taquiarritmias auriculares paroxísticas en ECG normal o monitorización ECG ambulatoria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27586, 10546, '5. Cuando se detecte bloqueo AV de primero, segundo o tercer grado en ECG o monitorización ECG ambulatoria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27587, 10547, '1. Aspirina 100 mg al día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27588, 10547, '2. Dipiridamol 150 mg al día.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27589, 10547, '3. Acenocumarol.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27590, 10547, '4. Cardioversión eléctrica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27591, 10547, '5. Ecocardiograma transesofágico para demostrar un trombo auricular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27592, 10548, '1. Hacer exploración física, ECG y ecocardiografía, y si todo es normal, considerar que no tiene importancia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27593, 10548, '2. Después de comprobar con ECG y ecocardiograma que es normal, pedir un registro de Holter y dar amiodarona si se encuentran extrasístoles ventriculares frecuentes', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27594, 10548, '3. Practicar como primera prueba después de la exploración física y el ECG, un “tilt test”', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27595, 10548, '4. Tras exploración, ECG y ecocardiograma normales, debe practicarse un estudio arritmológico completo incluido un estudio electrofisiológico', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27596, 10548, '5. Practicar como primera prueba después de la exploración física y el ECG, un estudio de potenciales tardios', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27597, 10549, '1. Es una taquicardia de comienzo e interrupción bruscos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27598, 10549, '2. Se asocia a síndromes de preexcitación tipo Wolf-Parkinson-White.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27599, 10549, '3. En el ECG es una taquicardia de con QRS estrecho a 180-300 latidos/minuto', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27600, 10549, '4. El tratamiento de elección si el niño está estable, es la lidocaína intravenosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27601, 10549, '5. Si el niño está en insuficiencia cardíaca se recomienda choque eléctrico sincronizado.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27602, 10550, '1. Sin cardiopatía', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27603, 10550, '2. Sin síntomas hemodinámicos ni síncope', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27604, 10550, '3. Tardíamente después de un infarto', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27605, 10550, '4. En cardiopatías con buena fracción de eyección', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27606, 10550, '5. Precozmente, después de un infarto, con mala fracción de eyección', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27607, 10551, '1. Suspender anticoagulantes orales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27608, 10551, '2. Realizar monitorización Holter.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27609, 10551, '3. Solicitar niveles de digoxina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27610, 10551, '4. Asociar propoanolol', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27611, 10551, '5. Asociar procainamida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27612, 10552, '1. Taquicardia sinusal', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27613, 10552, '2. Fibrilación auricular', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27614, 10552, '3. Taquicardia ventricular', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27615, 10552, '4. Taquicardia por reentrada de nodo AV', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27616, 10552, '5. Taquicardia auricular con bloqueo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27617, 10553, '1. Propafenona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27618, 10553, '2. Amiodarona.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27619, 10553, '3. Digoxina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27620, 10553, '4. Diltiazem.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27621, 10553, '5. Captopril.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27622, 10554, '1. Sin cardiopatía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27623, 10554, '2. Sin síntomas hemodinómicos ni síncope.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27624, 10554, '3. Tardíamente después de un infarto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27625, 10554, '4. En cardiopatías con buena fracción de eyección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27626, 10554, '5. Precozmente, después de un infarto, con mala fracción de eyección.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27627, 10555, '1. Atelectasia pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27628, 10555, '2. Bloqueo aurículo-ventricular completo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27629, 10555, '3. Derrame pericárdico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27630, 10555, '4. Hemorragia grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27631, 10556, '1. Seguimiento por médico de atención primaria mientras esté asintomático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27632, 10556, '2. Implante de una prótesis valvular aórtica biológica transcatéter (TAVI).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27633, 10556, '3. Valvuloplastia aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27634, 10556, '4. Cirugía de sustitución valvular aórtica y raíz.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27635, 10557, '1. Estenosis valvular aórtica grave con indicación de recambio valvular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27636, 10557, '2. Estenosis valvular aórtica moderada con indicación de seguimiento clínico ambulatorio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27637, 10557, '3. Estenosis mitral grave con indicación de recambio valvular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27638, 10557, '4. Estenosis mitral moderada con indicación de seguimiento clínico ambulatorio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27639, 10558, '1. La degeneración mixomatosa valvular también puede afectar a las válvulas tricúspide y aórtica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27640, 10558, '2. Es más frecuente en hombres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27641, 10558, '3. Tiene un curso benigno y raramente origina insuficiencia valvular mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27642, 10558, '4. El soplo cardiaco que puede originar característicamente disminuye de intensidad con la maniobra de Valsalva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27643, 10559, '1. Suspender el tratamiento con acenocumarol y administrar 10 mg de vitamina K en infusión intravenosa lenta, que se repetirá cada 12 horas si fuera necesario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27644, 10559, '2. Suspender el acenocumarol y remitir al paciente a un centro hospitalario para vigilar la aparición de sangrado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27645, 10559, '3. Suspender temporalmente el acenocumarol y reanudar la anticoagulación cuando se haya alcanzado el intervalo terapéutico, calculando de nuevo la dosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27646, 10559, '4. Iniciar la administración de concentrado de complejo de protrombina o plasma fresco congelado según el peso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27647, 10560, '1. Tratamiento intervencionista con la implantación de stents coronarios en los 3 vasos e implantación simultanea de una bioprótesis aórtica transcatéter (TAVI).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27648, 10560, '2. Prótesis valvular aórtica mecánica quirúrgica, seguida de un tratamiento intervencionista percutáneo coronario en un segundo tiempo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27649, 10560, '3. Prótesis aórtica biológica transcatéter (TAVI) y luego, de manera ambulatoria, tratar percutáneamente las arterias coronarias con stents.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27650, 10560, '4. Tratamiento quirúrgico simultáneo con recambio valvular y revascularización quirúrgica coronaria con bypass.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27651, 10561, '1. Reemplazo quirúrgico de la válvula mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27652, 10561, '2. Implante percutáneo de la válvula aórtica (TAVI).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27653, 10561, '3. Reemplazo quirúrgico de la válvula aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27654, 10561, '4. Valvulotomía mitral percutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27655, 10562, '1. Añadir al tratamiento voriconazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27656, 10562, '2. Sustituir la vancomicina por daptomicina y administrar furosemida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27657, 10562, '3. Añadir gentamicina, rifampicina, furosemida y nitritos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27658, 10562, '4. Indicar cirugía de recambio valvular urgente y tratamiento deplectivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27659, 10563, '1. Insuficiencia mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27660, 10563, '2. Estenosis aórtica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27661, 10563, '3. Insuficiencia aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27662, 10563, '4. Miocardiopatía dilatada de origen isquémico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27663, 10564, '1. Válvula aórtica bicúspide estenótica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27664, 10564, '2. Comunicación interventricular perimembranosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27665, 10564, '3. Insuficiencia aórtica degenerativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27666, 10564, '4. Miocardiopatía restrictiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27667, 10565, '1. El cuadro clínico sugiere un tromboembolismo pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27668, 10565, '2. Los datos aportados indican miocardiopatía hipertrófica con obstrucción grave del tracto de salida de ventrículo izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27669, 10565, '3. Estos datos corresponden a estenosis aórtica grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27670, 10565, '4. Debe excluirse una disección de aorta mediante una tomografía computarizada con contraste.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27671, 10566, '1. Insuficiencia mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27672, 10566, '2. Insuficiencia pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27673, 10566, '3. Insuficiencia tricuspídea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27674, 10566, '4. Estenosis aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27675, 10567, '1. Las prótesis valvulares mecánicas precisan tratamiento anticoagulante permanente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27884, 10612, '1. Fiebre tifoidea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27676, 10567, '2. Las prótesis aórticas mecánicas se implantan principalmente en pacientes de más de 70 años en ritmo sinusal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27677, 10567, '3. La durabilidad de las prótesis valvulares biológicas es menor que la de las prótesis mecánicas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27678, 10567, '4. Las prótesis valvulares biológicas son menos trombogénicas que las prótesis valvulares mecánicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27679, 10568, '1. Insuficiencia aórtica grave.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27680, 10568, '2. Comunicación interventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27681, 10568, '3. Disfunción sistólica grave del ventrículo izquierdo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27682, 10568, '4. Miocarditis aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27683, 10569, '1. Endocarditis bacteriana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27684, 10569, '2. Estenosis mitral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27685, 10569, '3. Miocardiopatía hipertrófica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27686, 10569, '4. Insuficiencia aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27687, 10570, '1. El implante de una prótesis transcatéter en posición aórtica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27688, 10570, '2. Una valvuloplastia percutánea con balón de la válvula aórtica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27689, 10570, '3. Una cirugía sobre la válvula mitral, a ser posible reparadora.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27690, 10570, '4. Con tratamiento médico sería suficiente y no precisa ninguna intervención en ninguna válvula', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27691, 10571, '1. La reparación de la válvula mitral mantiene la función del ventrículo izquierdo en un grado mayor que la sustitución valvular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27692, 10571, '2. El tratamiento quirúrgico está indicado en pacientes asintomáticos cuando existe disfunción ventricular izquierda (fracción eyección ventrículo izquierdo < 60% y/o diámetro telesistólico ventricular izquierdo > 40 mm).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27693, 10571, '3. El tratamiento quirúrgico está indicado en pacientes sintomáticos, especialmente por encima de una fracción de eyección de ventrículo izquierdo de 30%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27694, 10571, '4. La reparación valvular mitral tiene un riesgo quirúrgico superior a la cirugía de sustitución valvular mitral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27695, 10572, '1. El tercer ruido coincide con la fase de llenado rápido de la diástole ventricular del ciclo cardiaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27696, 10572, '2. El diagnóstico más probable es el de insuficiencia cardiaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27697, 10572, '3. El soplo holosistólico puede corresponder a una insuficiencia mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27698, 10572, '4. El cuarto ruido suele aparecer cuando existe un cierto grado de estenosis valvular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27699, 10573, '1. Ductus persistente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27700, 10573, '2. Disfunción músculo papilar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27701, 10573, '3. Estenosis mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27702, 10573, '4. Insuficiencia aórtica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27703, 10574, '1. Las estenosis de las válvulas cardiacas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27704, 10574, '2. La coartación de la aorta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27705, 10574, '3. La angina de reposo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27706, 10574, '4. Las insuficiencias de las válvulas cardiacas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27707, 10574, '5. La fiebre reumática.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27708, 10575, '1. Reumática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27709, 10575, '2. Congénita.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27710, 10575, '3. Degenerativa o calcificada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27711, 10575, '4. Post endocarditis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27712, 10575, '5. Isquémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27713, 10576, '1. La anticoagulación permanente es necesaria en las prótesis mecánicas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27714, 10576, '2. En general las prótesis biológicas se indican en pacientes jóvenes, con esperanza de vida larga.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27715, 10576, '3. Las prótesis biológicas estarían indicadas en casos que presenten contraindicación formal para la anticoagulación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27716, 10576, '4. La velocidad de deterioro estructural de una prótesis biológica es inversamente proporcional a la edad del sujeto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27717, 10576, '5. Las prótesis biológicas no precisan anticoagulación permanente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27718, 10577, '1. Una prueba de esfuerzo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27719, 10577, '2. Una coronariografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27720, 10577, '3. Un ecocardiograma de ejercicio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27721, 10577, '4. Un TAC coronario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27722, 10577, '5. Un ecocardiograma- Doppler.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27723, 10578, '1. Insuficiencia mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27724, 10578, '2. Insuficiencia pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27725, 10578, '3. Insuficiencia tricúspide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27726, 10578, '4. Insuficiencia aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27727, 10578, '5. Estenosis aórtica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27728, 10579, '1. Una prueba de esfuerzo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27729, 10579, '2. Una coronariografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27730, 10579, '3. Un Ecocardiograma de ejercicio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27731, 10579, '4. Un TAC coronario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27732, 10579, '5. Un Ecocardiograma-Doppler.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27733, 10580, '1. Antes de plantear un tratamiento es importante practicar un cateterismo del lado izquierdo del corazón y de las arterias coronarias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27734, 10580, '2. El pronóstico de vida de este paciente sin ningún tratamiento es entre 2 y 3 años desde el momento del diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27735, 10580, '3. Se debe recomendar al paciente evitar el ejercicio físico excesivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27736, 10580, '4. En este paciente no es posible el tratamiento quirúrgico por el elevado riesgo de complicaciones y mortalidad al ser un paciente de edad avanzada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27737, 10580, '5. Antes de plantear un tratamiento es importante practicar un ecocardiograma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27738, 10581, '1. Soplo mesodiástólico en foco mitral, posible chasquido de apertura previo y tonos cardiacos rítmicos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27739, 10581, '2. Soplo mesosistólico y diastólico en borde esternal izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27740, 10581, '3. Soplo protodiastólico en foco mitral, tonos cardiacos irregulares y soplo sistólico aórtico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27741, 10581, '4. Soplo protodiastólico en foco mitral e hipertensión arterial sistólica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27742, 10581, '5. Soplo telesistólico mitral irradiado a axila.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27743, 10582, '1. Miocardiopatía hipertrófica no obstructiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27744, 10582, '2. Miocardiopatía no compactada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27745, 10582, '3. Comunicación interauricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27746, 10582, '4. Hipertiroidismo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27747, 10582, '5. Insuficiencia aórtica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27748, 10583, '1. Tratamiento conservador con controles anuales por un cardiólogo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27749, 10583, '2. En caso de aumentar la disnea de esfuerzo, debe practicarse una dilatación percutánea de la estenosis con catéter balón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27750, 10583, '3. Sustitución valvular aórtica con una prótesis mecánica o bioprótesis (si la anticoagulación permanente está contraindicada).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27751, 10583, '4. Reparación valvular aórtica mediante decalcificación valvular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27752, 10583, '5. Homoinjerto valvular aórtico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27753, 10584, '1. No está indicada la intervención por su avanzada edad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27754, 10584, '2. Estaría indicada la intervención, pero esperando al deterioro de la función ventricular izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27755, 10584, '3. Está indicada la intervención para plastia valvular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27756, 10584, '4. Está indicada la intervención quirúrgica para sustitución valvular aórtica por una prótesis mecánica y posterior anticoagulación oral de por vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27757, 10584, '5. Está indicada la intervención quirúrgica para sustitución valvular aórtica por una prótesis biológica y así evitar la anticoagulación oral.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27758, 10585, '1. Asociación de estenosis valvular tricúspide significativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27759, 10585, '2. Asociación de estenosis aórtica severa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27760, 10585, '3. Asociación de insuficiencia mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27761, 10585, '4. Hipertensión pulmonar grave.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27762, 10585, '5. Infarto inferior.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27763, 10586, '1. Suele requerir tratamiento quirúrgico en personas mayores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27764, 10586, '2. La edad no suele ser una contraindicación para el recambio valvular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27765, 10586, '3. La muerte súbita es una complicación poco común de los pacientes con estenosis aórtica sintomática.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27766, 10586, '4. Cuando la estenosis aórtica se hace sintomática está indicada la sustitución valvular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27767, 10586, '5. Los pacientes con estenosis aórtica que desarrollan angina tienen un elevado riesgo de mortalidad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27768, 10587, '1. Comisurotomía', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27769, 10587, '2. Dilatación con balón', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27770, 10587, '3. Sustitución de la válvula', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27771, 10587, '4. Cateterismo y endoprótesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27772, 10587, '5. Trasplante cardíaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27773, 10588, '1. Infarto de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27774, 10588, '2. Carcinoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27775, 10588, '3. Endocarditis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27776, 10588, '4. Prolapso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27777, 10588, '5. Congénita.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27778, 10589, '1. Recambio valvular aórtico aislado en ese momento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27779, 10589, '2. Tratamiento médico con calcioantagonistas hasta que aparezcan los síntomas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27780, 10589, '3. Tratamiento médico con betabloqueantes hasta que aparezcan los síntomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27781, 10589, '4. Control ecocardiográfico anual hasta que aparezcan los síntomas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27782, 10589, '5. Recambio de la válvula aórtica y la aorta ascendente con tubo valvulado (Operación de Bentall)', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27783, 10590, '1. La dilatación auricular izquierda atenúa la elevación de la presión intra auricular izquierda (y, por tanto, capilar pulmonar) en la insuficiencia mitral aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27784, 10590, '2. La dilatación ventricular izquierda atenúa la elevación de la presión telediastólica en la insuficiencia aórtica crónica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27785, 10590, '3. La dilatación auricular izquierda frena la progresión de la estenosis mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27786, 10590, '4. La disfunción sistólica severa ventricular izquierda producida por la estenosis aórtica contraindica su tratamiento quirúrgico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27787, 10590, '5. La acomodación de la caja torácica reduce los síntomas del prolapso mitral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27788, 10591, '1. Anticoagulación oral durante 3 meses para mantener INR entre 2,5-3,5 y posteriormente clopidogrel, 1 comprimido al día, suspendiendo la anticoagulación oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27789, 10591, '2. Anticoagulación oral para mantener INR entre 4-5 de forma indefinida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27790, 10591, '3. Anticoagulación oral para mantener INR entre 3-4 de forma indefinida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27791, 10591, '4. AAS 250 mg/24 h de forma indefinida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27792, 10591, '5. Anticoagulación oral para mantener INR entre 2-3 más AAS 125 mg/24 h de forma indefinida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27793, 10592, '1. El primer tono cardíaco se oye fuerte.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27794, 10592, '2. La intensidad del pulso carotideo, es variable.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27795, 10592, '3. Puede auscultarse un chasquido de apertura, inmediatamente antes del soplo mesodiastólico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27796, 10592, '4. El soplo diastólico finaliza en una acentuación presistólica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27797, 10592, '5. El segundo tono será fuerte si existe hipertensión pulmonar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27798, 10593, '1. Tratamiento médico hasta que se detecte que la fracción de eyección ventricular izquierda sea menor de 30%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27799, 10593, '2. Reparación de la válvula mitral mediante resección del segmento del velo posterior afectado por la rotura de las cuerdas y anuloplastia mitral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27800, 10593, '3. Reparación de las cuerdas rotas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27801, 10593, '4. Sustitución de la válvula mitral por bioprótesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27802, 10593, '5. Sustitución de la válvula mitral por prótesis mecánica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27803, 10594, '1. Un test de tabla basculante', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27804, 10594, '2. Un Holter de 24 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27805, 10594, '3. Un ecocardiograma- Doppler.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27806, 10594, '4. Un estudio electrofisiológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27807, 10594, '5. Una prueba de esfuerzo.', false, 5);
