INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27819, 10597, '2. Doble lesión aórtica con predominio de la insuficiencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27820, 10597, '3. Estenosis aórtica probablemente severa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27821, 10597, '4. Hipertensión arterial severa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27822, 10597, '5. Coartación de aorta.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27823, 10598, '1. Valvuloplastia mitral con balón porque la anatomía es favorable.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27824, 10598, '2. Recambio valvular por una prótesis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27825, 10598, '3. Comisurotomía mitral aislada bien sea cerrada o abierta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27826, 10598, '4. Esperar a que su clase funcional sea IV.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27827, 10598, '5. Esperar a que aparezca hipertensión pulmonar sistémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27828, 10599, '1. Aparición de insuficiencia renal aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27829, 10599, '2. Hallazgo por imagen de émbolos esplénicos o renales en el momento del diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27830, 10599, '3. Presencia de vegetaciones mayores de 8 mm en válvula tricúspide en la EI derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27831, 10599, '4. Hemocultivos positivos persistentes durante 7-10 días tras pauta antibiótica adecuada.', true, 4);
