INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27835, 10600, '4. Pacientes que han sufrido endocarditis infecciosa previa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27836, 10601, '1. Paciente de 82 años con EI por S. mitis sobre prótesis aórtica biológica, con buena evolución clínica, sin dehiscencia valvular, con un pseudoaneurisma de raíz aórtica a la 4º semana de tratamiento antibiótico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27837, 10601, '2. Paciente de 70 años con EI mitral por E. faecalis en el que se evidencia una insuficiencia valvular moderada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27838, 10601, '3. Paciente de 75 años con EI aórtica con regurgitación valvular moderada y sin compromiso hemódinámico, con aislamientos repetidos en hemocultivos de Candida albicans sensible a azoles.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27839, 10601, '4. Paciente de 68 años con EI aórtica por S. aureus con insuficiencia valvular aórtica moderada grave y episodio de fracaso ventricular izquierdo con insuficiencia cardiaca grado III de la NYHA durante la primera semana de tratamiento antibiótico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27840, 10602, '1. Presencia de fenómenos embólicos arteriales mayores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27841, 10602, '2. Un único hemocultivo positivo para Coxiella burnetii.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27842, 10602, '3. Al menos dos hemocultivos positivos extraídos con un intervalo > 12 horas de microorganismos compatibles con una endocarditis infecciosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27843, 10602, '4. Presencia de anemia hemolítica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27844, 10603, '1. Indicar cirugía de recambio valvular urgente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27845, 10603, '2. Añadir ceftarolina IV, diuréticos y control en cuidados intensivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27846, 10603, '3. Retirar daptomicina y pautar vancomicina a dosis altas y gentamicina, junto con diuréticos y control en cuidados intensivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27847, 10603, '4. Solicitar un nuevo ecocardiograma, administrar tratamiento diurético y control en cuidados intensivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27848, 10604, '1. Añadir al tratamiento voriconazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27849, 10604, '2. Sustituir la vancomicina por daptomicina y administrar furosemida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27850, 10604, '3. Añadir gentamicina, rifampicina, furosemida y nitritos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27851, 10604, '4. Indicar cirugía de recambio valvular urgente y tratamiento deplectivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27852, 10605, '1. Una esofagogastroduodenoscopia con toma de biopsia gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27853, 10605, '2. Un drenaje guiado por ecografía de absceso hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27854, 10605, '3. Una colonoscopia por sospecha de neoplasia de colon.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27855, 10605, '4. Un ecocardiograma para descartar endocarditis bacteriana.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27856, 10606, '1. Disección aórtica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27857, 10606, '2. Estenosis aórtica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27858, 10606, '3. Endocarditis aórtica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27859, 10606, '4. Mixoma valvular aórtico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27860, 10607, '1. Cirugía cardiaca de reemplazo valvular aórtico por prótesis mecánica con terapia antibiótica según antibiograma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27861, 10607, '2. Terapia antibiótica según antibiograma e implantación de balón de contrapulsación intraaórtico y marcapasos transitorio hasta 3 semanas, tras las cuales se implantará marcapasos definitivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27862, 10607, '3. Implantación de marcapasos transitorio, terapia antibiótica según antibiograma e implantación percutánea de prótesis valvular aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27863, 10607, '4. Implantación urgente de marcapasos definitivo con terapia antibiótica según antibiograma durante 6 semanas.', false, 4);
