INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27876, 10610, '3. Insuficiencia mitral moderada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27877, 10610, '4. Absceso periaórtico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27878, 10610, '5. Insuficiencia aórtica severa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27879, 10611, '1. La presencia de marcadores tumorales elevados, aún usados como método de screening, tiene gran sensibilidad y especificidad diagnóstica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27880, 10611, '2. La endocarditis marántica es una situación potencialmente embolígena, asociada a estados de hipercoagulabilidad en procesos neoplásicos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27881, 10611, '3. La elevación de la enzima fosfatasa alcalina, en este caso, refleja la presencia de metástasis ósea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27882, 10611, '4. La elevación de Bilirrubina directa apunta a estados hemolíticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27883, 10611, '5. El cuadro, en conjunto es diagnóstico de Hepatocarcinoma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31681, 11455, '3. Terbutalina', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27885, 10612, '2. Endocarditis bacteriana subaguda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27886, 10612, '3. Meningococcemia crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27887, 10612, '4. Fiebre botonosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27888, 10612, '5. Sífilis terciaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27889, 10613, '1. TAC torácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27890, 10613, '2. Resonancia magnética pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27891, 10613, '3. Espirometría.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27892, 10613, '4. Ecocardiografía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27893, 10613, '5. Gammagrafía pulmonar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27894, 10614, '1. Los criterios de Duke para el diagnóstico de endocarditis se basan en hallazgos clínicos, de laboratorio y ecocardiográficos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27895, 10614, '2. En ausencia de tratamiento antibiótico previo, es improbable que la endocarditis por Enterococo o Stafilococo aureus se presente con cultivo negativo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27896, 10614, '3. La ecografía transtorácica detecta vegetaciones en más del 90% de los pacientes con endocarditis infecciosa clínicamente confirmada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27897, 10614, '4. No se debe administrar tratamiento antibiótico empírico inicial a pacientes con endocarditis subaguda hemodinámicamente estable sobre todo a los que hubieran recibido tratamiento antibiótico en las dos semanas previas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27898, 10614, '5. La endocarditis por estafilococo aureus sensible a Meticilina, no complicada y limitada a la válvula tricúspide podría tratarse con tal sólo 2 semanas de Oxacilina y Gentamicina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27899, 10615, '1. Infarto de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27900, 10615, '2. Carcinoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27901, 10615, '3. Endocarditis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27902, 10615, '4. Prolapso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27903, 10615, '5. Congénito.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27904, 10616, '1. Considerar el resultado de los hemocultivos como probable contaminación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27905, 10616, '2. Pautar de inmediato tratamiento antibiótico con penicilina y gentamicina durante 10 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27906, 10616, '3. Comenzar tratamiento con cloxacilina y gentamicina y realizar estudio ecocardiográfico por la existencia probable de endocarditis aguda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27907, 10616, '4. Descartar la existencia de endocarditis por la ausencia de soplos en la auscultación cardiaca y buscar focos de posible osteomielitis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27908, 10616, '5. Realizar TAC abdominal urgente por probable absceso abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27909, 10617, '1. Neumonía neumocócica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27910, 10617, '2. Tuberculosis pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27911, 10617, '3. Neumonía por anaerobios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27912, 10617, '4. Neumonía hematógena.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27913, 10617, '5. Neumonía por H. Influenzae.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27914, 10618, '1. Ecocardiograma positivo de Endocarditis', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27915, 10618, '2. Nuevo soplo de regurgitación valvular', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27916, 10618, '3. Hemocultivos positivos', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27917, 10618, '4. Fiebre', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27918, 10618, '5. Abceso diagnosticado por ecocardiografía transesofágica', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27919, 10619, '1. Se debe realizar una prueba serológica con inmunofluorescencia para detectar IgG frente a T. cruzy.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27920, 10619, '2. La prueba de reacción en cadena de la polimerasa (PCR) tiene un valor diagnóstico limitado en esta fase de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27921, 10619, '3. Debe iniciar tratamiento con benznidazol para modificar la evolución de la enfermedad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27922, 10619, '4. Si se confirma el diagnóstico, debe estudiar a los familiares cercanos para identificar otros casos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27923, 10620, '1. Insuficiencia tricuspídea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27924, 10620, '2. Estenosis aórtica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27925, 10620, '3. Miocardiopatía hipertrófica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27926, 10620, '4. Insuficiencia mitral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27927, 10621, '1. Infarto agudo de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27928, 10621, '2. Gammagrafía cardiaca normal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27929, 10621, '3. Amiloidosis cardiaca mediada por transtiretina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27930, 10621, '4. Derrame pericárdico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27931, 10622, '1. La fracción de eyección del ventrículo izquierdo muy frecuentemente es inferior al 55%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27932, 10622, '2. Esta entidad es debida a una hipertrofia del tabique con obstrucción dinámica en el tracto de salida del ventrículo izquierdo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27933, 10622, '3. No se asocia a disfunción diastólica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27934, 10622, '4. El grosor de la pared del ventrículo izquierdo es normal o esta disminuido.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27935, 10623, '1. Disfunción microvascular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27936, 10623, '2. Mayor susceptibilidad de los receptores catecolaminérgicos en el miocardio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27937, 10623, '3. Espasmo coronario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27938, 10623, '4. Enfermedad coronaria obstructiva significativa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27939, 10624, '1. Lo más probable es que se trate de un infarto agudo de miocardio. Avisaría a Cardiología para realización de coronariografía urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27940, 10624, '2. Los fármacos más utilizados son los AINEs.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27941, 10624, '3. La colchicina está contraindicada en esta patología.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27942, 10624, '4. Lo más correcto sería iniciar tratamiento antibiótico empírico con una fluoroquinolona', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27943, 10625, '1. Amiloidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27944, 10625, '2. Endocarditis de Loeffler.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27945, 10625, '3. Alcoholismo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27946, 10625, '4. Hemocromatosis.', false, 4);
