INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27948, 10626, '2. Estenosis mitral', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27949, 10626, '3. Insuficiencia aortica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27950, 10626, '4. Comunicación interventricular', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27951, 10627, '1. Se trata de una enfermedad hereditaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27952, 10627, '2. Esta enfermedad se asocia a muerte súbita.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27953, 10627, '3. La fibrilación auricular tiene una mayor incidencia en las personas con esta enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27954, 10627, '4. La disnea no aparecerá hasta que la paciente desarrolle disfunción sistólica ventricular izquierda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27955, 10628, '1. Beta-bloqueantes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27956, 10628, '2. Digoxina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27957, 10628, '3. Calcio-antagonistas no dihidropirídinicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27958, 10628, '4. Desfibrilador automático implantable.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27959, 10628, '5. Miomectomíaseptal quirúrgica del Morrow.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27960, 10629, '1. El tratamiento con betabloqueantes ayuda a reducir los síntomas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27961, 10629, '2. Se debe de recomendar el abandono del deporte de competición.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27962, 10629, '3. La digoxina es útil para reducir el gradiente subaórtico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27963, 10629, '4. Los diuréticos se deben evitar o utilizar con gran cuidado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27964, 10629, '5. Dado el carácter hereditario de la patología se debe de realizar estudio de despistaje en el resto de los familiares directos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27965, 10630, '1. Soplo funcional', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27966, 10630, '2. Estenosis aórtica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27967, 10630, '3. Insuficiencia aórtica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27968, 10630, '4. Miocardiopatía hipertrófica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27969, 10630, '5. Comunicación interventricular', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27970, 10631, '1. Cardiopatía isquémica', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27971, 10631, '2. Estenosis valvular aórtica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27972, 10631, '3. Miocardiopatía hipertrófica', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27973, 10631, '4. Prolapso de la válvula mitral', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27974, 10631, '5. Miocardiopatía dilata con insuficiencia mitral', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27975, 10632, '1. Preclampsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27976, 10632, '2. Anemia en gestante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27977, 10632, '3. Miocardiopatía periparto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27978, 10632, '4. Embolia de líquido amniótico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27979, 10632, '5. Tromboembolismo pulmonar agudo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27980, 10633, '1. Vasoesapasmo coronario transitorio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27981, 10633, '2. Pericarditis aguda viral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27982, 10633, '3. Tromboembolismo pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27983, 10633, '4. Miocardiopatía de esfuerzo (enfermedad de Tako-Tsubo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27984, 10633, '5. Disección aórtica tipo B.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27985, 10634, '1. Radiografía de abdomen.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27986, 10634, '2. Doppler venoso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27987, 10634, '3. Niveles sanguíneos de magnesio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27988, 10634, '4. Ecocardiograma.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27989, 10634, '5. Electroforesis en sangre.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27990, 10635, '1. Alcoholismo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27991, 10635, '2. Tratamiento antineoplásico con adriamicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27992, 10635, '3. Amiloidosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27993, 10635, '4. Feocromocitoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27994, 10635, '5. Ataxia de Friedreich.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27995, 10636, '1. En nuestro medio, la causa más frecuente de muerte súbita de origen cardiaco es la presencia de un infarto agudo de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27996, 10636, '2. Una vez recuperado el ritmo sinusal, el ECG puede mostrar alteraciones que sugieran la presencia de alteraciones genéticamente determinadas como un síndrome de Brugada, un síndrome del QT largo o una miocardiopatía hipertrófica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27997, 10636, '3. El síndrome de Brugada se ha asociado con la presencia de mutaciones en el canal de sodio cardiaco, presenta un ECG característico con bloqueo de rama derecha y elevación del segmento ST y la muerte súbita puede ser la primera manifestación de la enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27998, 10636, '4. El síndrome del QT largo se caracteriza por la presencia de un intervalo QT prolongado en el ECG, los pacientes pueden presentar episodios de síncope o muerte súbita debidos a taquicardias ventriculares polimórficas denominadas “torsade de pointes” y el tratamiento de elección es la administración de betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (27999, 10636, '5. En la miocardiopatía hipertrófica, la muerte súbita aparece en reposo, sin relación con los esfuerzos y es debida a la presencia de una obstrucción a la salida de sangre del ventrículo izquierdo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28000, 10637, '1. Miocardiopatía restrictiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28001, 10637, '2. Pericarditis crónica constrictiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28002, 10637, '3. Miocardiopatía dilatada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28003, 10637, '4. Miocardiopatía hipertrófica obstructiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28004, 10637, '5. Cor pulmonale crónico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28005, 10638, '1. Rabdomioma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28006, 10638, '2. Lipoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28007, 10638, '3. Fibroma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28008, 10638, '4. Mixoma.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28009, 10638, '5. Hemangioma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28010, 10639, '1. Estenosis aortica congénita.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28011, 10639, '2. Infarto lateral alto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28012, 10639, '3. Miocardiopatía dilatada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28013, 10639, '4. Angina inestable.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28014, 10639, '5. Miocardiopatía hipertrófica obstructiva.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28015, 10640, '1. Miocardiopatía restrictiva secundaria a amiloidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28016, 10640, '2. Miocardiopatía restrictiva secundaria a hemocromatosis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28017, 10640, '3. Miocardiopatía hipertrófica familiar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28018, 10640, '4. Miocardiopatía hipertensiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28019, 10640, '5. Miocardiopatría restrictiva secundaria a sarcoidosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28020, 10641, '1. Los sujetos jóvenes con esta enfermedad y antecedentes familiares de muerte súbita son candidatos a la implantación de un desfibrilador automático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28021, 10641, '2. La fibrilación auricular es frecuente en esta enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28022, 10641, '3. El tratamiento de elección de los pacientes con miocardiopatía hipertrófica obstructiva en el ritmo sinusal e insuficiencia cardiaca es digoxina por vía oral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28023, 10641, '4. La fibrilación auricular en estos pacientes es un factor precipitante de insuficiencia cardíaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28024, 10641, '5. Los pacientes con angor y miocardiopatía hipertrófica obstructiva pueden ser tratados con beta-bloqueantes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28025, 10642, '1. Existe un aumento de las presiones telediastólicas del ventrículo izquierdo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28026, 10642, '2. En tres de cada cuatro casos se asocia a una obstrucción sistólica a nivel del tracto de saluda del ventrículo izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28027, 10642, '3. Se hereda de carácter autosómico recesivo con penetrancia variable.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28028, 10642, '4. La mayor parte de los pacientes presentan disnea de esfuerzo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28029, 10642, '5. Debe sospecharse al auscultar un soplo eyectivo que se superpone al primer ruido cardiaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28030, 10643, '1. Soplo diastólico después del chasquido de apertura.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28031, 10643, '2. Disminución de la presión sistólica durante la inspiración', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28032, 10643, '3. Soplo sistólico que aumenta durante las maniobras de Valsalva', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28033, 10643, '4. Tercer tono cardíaco de origen izquierdo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28034, 10643, '5. Desdoblamiento fijo del segundo ruido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28035, 10644, '1. Ondas Q en derivaciones anteriores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28036, 10644, '2. Ondas Q en derivaciones inferiores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28037, 10644, '3. Ondas T gigantes positivas en derivaciones anteriores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28038, 10644, '4. Ondas T gigantes negativas en derivaciones anteriores.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28039, 10644, '5. Ondas U diseminadas, amplias y profundas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28040, 10645, '1. La distribución de la hipertrofia es generalmente asimétrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28041, 10645, '2. La transmisión genética está ligada al cromosoma X.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28042, 10645, '3. Fisiopatologicamente se caracteriza por disfunción diastólica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28043, 10645, '4. Se puede detectar obstrucción al tracto de salida del ventrículo izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28044, 10645, '5. La muerte súbita es una forma clínica de presentación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28045, 10646, '1. Tiene una alta mortalidad a largo plazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28046, 10646, '2. Tiene una alta mortalidad en fase aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28047, 10646, '3. La mayoría de enfermos evoluciona a miocardiopatía restrictiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28048, 10646, '4. La mayoría de enfermos se cura sin secuelas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28049, 10646, '5. Es más frecuente en ancianos que en jóvenes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28050, 10647, '1. La disnea está en relación con la severidad del gradiente dinámico en el tracto de salida del ventrículo izquierdo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28051, 10647, '2. La disnea está en relación con la mayor rigidez de la pared del ventrículo izquierdo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28052, 10647, '3. La disnea está en relación con la disfunción sistólica del ventrículo izquierdo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28053, 10647, '4. La disnea está en relación con la regurgitación valvular mitral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28054, 10647, '5. La disnea es un síntoma muy infrecuente en estos pacientes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28055, 10648, '1. Neumotórax.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28056, 10648, '2. Taponamiento cardíaco con colapso de cavidades cardíacas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28057, 10648, '3. Disección de aorta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28058, 10648, '4. Derrame pericárdico crónico', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28059, 10649, '1. Las manifestaciones ecocardiográficas y los cambios hemodinámicos se producen con anterioridad a la aparición de las manifestaciones clínicas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28060, 10649, '2. Es típica la hipotensión, la taquicardia, la disminución de la presión venosa yugular y unos ruidos cardíacos atenuados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28061, 10649, '3. El volumen de líquido pericárdico necesario para producir taponamiento es similar en una pericarditis aguda que en una pericarditis crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28062, 10649, '4. El pulso paradójico es un dato de la exploración física característico que se define como un descenso de 5-10 mmHg en la tensión arterial sistólica durante la inspiración.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28063, 10650, '1. Lo más probable es que se trate de un infarto agudo de miocardio. Avisaría a Cardiología para realización de coronariografía urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28064, 10650, '2. Los fármacos más utilizados son los AINEs.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28065, 10650, '3. La colchicina está contraindicada en esta patología.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28066, 10650, '4. Lo más correcto sería iniciar tratamiento antibiótico empírico con una fluoroquinolona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28067, 10651, '1. Ingreso para monitorización estrecha de la aparición de signos de taponamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28068, 10651, '2. Administración de diuréticos que faciliten la desaparición del derrame.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28069, 10651, '3. Ingreso y consideración de pericardiocentesis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28070, 10651, '4. Administración de antiinflamatorios no esteroideos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28071, 10652, '1. Curso agudo (comienzo agudo del dolor torácico).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28072, 10652, '2. Antecedente de hipertensión arterial mal controlada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28073, 10652, '3. Fiebre superior a 38°C.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28074, 10652, '4. La presencia de derrame pericárdico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28075, 10653, '1. Presenta criterios electrocardiográficos de sobrecarga ventricular derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28076, 10653, '2. El ritmo que se observa es flutter (aleteo) auricular común con conducción 2:1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28077, 10653, '3. La prueba diagnóstica de imagen de elección es un ecocardiograma transtoracico urgente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28078, 10653, '4. Dada la sospecha clínica, se debe iniciar rápidamente la administración de diurético de asa intravenoso para reducir la congestión venosa sistémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28079, 10654, '1. TC de tórax.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28080, 10654, '2. Ecografía abdominal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28081, 10654, '3. Pruebas de funcionalismo respiratorio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28082, 10654, '4. Serología de hepatitis B y C.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28083, 10655, '1. Aviso urgente a cirugía para revaloración de la paciente por probable sangrado intraabdominal como complicación de la intervención quirúrgica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28084, 10655, '2. Oxígeno a alto débito, sueroterapia intensiva, iniciar noradrenalina endovenosa y antibioterapia por sospecha de sepsis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28085, 10655, '3. Pericardiocentesis eco guiada y en función del resultado, revisar posteriormente la causa del posible derrame pericárdico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28086, 10655, '4. Considerar fibrinolisis dada la alta probabilidad clínica de tromboembolismo pulmonar agudo grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28087, 10656, '1. Miocardiopatía dilatada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28088, 10656, '2. Derrame pericárdico con taponamiento cardiaco.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28089, 10656, '3. Pericarditis constrictiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28090, 10656, '4. Cardiopatía isquémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28091, 10657, '1. No existe una prueba específica para el diagnóstico de pericarditis aguda idiopática por lo que el diagnóstico es de exclusión.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28092, 10657, '2. Deben de evitarse los anticoagulantes porque su uso puede causar hemorragia en la cavidad pericárdica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28093, 10657, '3. No existe un tratamiento específico, pero puede indicarse el reposo en cama y ácido acetilsalicílico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28094, 10657, '4. Debe de informar a su paciente que la pericarditis recurre en más de un 75% de los pacientes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28095, 10658, '1. Colchina asociada a aspirina o antiinflamatorios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28096, 10658, '2. Prednisona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28097, 10658, '3. Tratamiento tuberculostático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28098, 10658, '4. Prednisona asociada a aspirina o antiinflamatorios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28099, 10659, '1. Infarto subagudo de miocardio anteroseptal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28100, 10659, '2. Síndrome de Tietze.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28101, 10659, '3. Dolor torácico osteomuscular con ECG de deportista.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28102, 10659, '4. Pericarditis aguda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28103, 10659, '5. Angina inestable.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28104, 10660, '1. Realización de cateterismo urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28105, 10660, '2. Angioplastia primaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28106, 10660, '3. Fibrinolisis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28107, 10660, '4. Prednisona 10 mg/12 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28108, 10660, '5. Antiinflamatorios en tratamiento prolongado.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28109, 10661, '1. Una estenosis aórtica grave.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28110, 10661, '2. Una miocardiopatía dilatada con disfunción ventricular izquierda significativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28111, 10661, '3. Una hipertensión pulmonar primaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28112, 10661, '4. Una miocardiopatía hipertrófica obstructiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28113, 10661, '5. Una pericarditis constrictiva.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28114, 10662, '1. La radiografía de tórax resulta muy útil para el diagnóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28115, 10662, '2. El registro venoso yugular permite objetivar un colapso x muy profundo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28116, 10662, '3. Es habitual la presencia de pulso arterial paradójico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28117, 10662, '4. El colapso auricular derecho es muy sensible para el diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28118, 10662, '5. El colapso ventricular derecho es muy específico para el diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28119, 10663, '1. Una estenosis aórtica grave.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28120, 10663, '2. Una miocardiopatía dilatada con disfunción ventricular izquierda significativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28121, 10663, '3. Una hipertensión pulmonar primaria.', false, 3);
