INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28148, 10668, '5. Insuficiencia aórtica aguda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28149, 10669, '1. La indicación más frecuente es la pericarditis constrictiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28150, 10669, '2. La vía de acceso es por esternotomía o toracotomía anterior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28151, 10669, '3. El cortocircuito (by pass) cardiopulmonar es necesario y no se asocia a riesgo hemorrágico mayor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28152, 10669, '4. La mortalidad quirúrgica está en relación con la clase funcional preoperatoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28153, 10669, '5. Debe extirparse el pericardio comprendido entre ambos nervios frénicos.', false, 5);
