INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28158, 10670, '5. Rx. de tórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28159, 10671, '1. Pericarditis aguda idiopática.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28160, 10671, '2. Pericarditis tuberculosa.', false, 2);
