INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28163, 10671, '5. Pericarditis de origen autoinmune.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28164, 10672, '1. Fibrosis miocárdica postradioterapia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28165, 10672, '2. Pericarditis constructiva postradioterapia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28166, 10672, '3. Miocardiopatía por adriamicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28167, 10672, '4. Taponamiento cardiaco por metástasis pericárdicos', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28168, 10672, '5. Miocardiopatía dilatada idiopática.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28169, 10673, '1. Fracturas costales con sincope vasovagal y gran ansiedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28170, 10673, '2. Posibilidad de que alguna costilla rota haya lesionado el pulmón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28171, 10673, '3. Su cuadro se debe a un shock hipovolémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28172, 10673, '4. Hay que descartar la presencia de un taponamiento cardiaco.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28173, 10673, '5. Hay que examinar el abdomen y descartar que la causa de todo sea una rotura del bazo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28174, 10674, '1. Ácido acetil salicílico 100 mg/día de forma indefinida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28175, 10674, '2. Ácido acetil salicílico 100 mg/día de forma indefinida y clopidogrel 75 mg/día durante 1 año.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28176, 10674, '3. Ácido acetil salicílico 100 mg/día de forma indefinida y ticagrelor 90 mg/día durante 1 año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28177, 10674, '4. Ácido acetil salicílico 100 mg/día de forma indefinida y prasugrel 5 mg/día durante 1 año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28178, 10675, '1. Ritmo auricular desorganizado con frecuencia ventricular irregular muy sugestiva de fibrilación auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28243, 10691, '1. Ejercicio físico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28179, 10675, '2. Alteración del sistema de conducción cardiaca con bloqueo bifascicular (bloqueo completo de rama derecha y hemibloqueo anterosuperior izquierdo del haz de His).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28180, 10675, '3. Alteración del sistema de conducción cardiaca con episodios de bloqueo aurículoventricular de alto grado o completo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28181, 10675, '4. Elevación significativa del segmento ST en derivaciones inferiores muy sugestiva de isquemia miocárdica aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28182, 10676, '1. Presencia de signos de insuficiencia cardiaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28183, 10676, '2. Antecedente de hemorragia craneal sin secuelas hace 10 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28184, 10676, '3. Antecedente de ictus isquémico hace 18 meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28185, 10676, '4. Cifras de tensión arterial ≥ 140/90 mmHg.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28186, 10677, '1. Se debe intensificar el tratamiento hipolipemiante hasta el objetivo terapéutico (LDL < 55 mg/dl).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28187, 10677, '2. Su perfil lipídico es adecuado dado que tiene un colesterol total inferior a 200 mg/dl.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28188, 10677, '3. Su perfil lipídico es adecuado porque su HDL es elevado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28189, 10677, '4. Al dejar de fumar y ser mujer su riesgo es bajo y no hace falta insistir en optimizar su perfil lipídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28190, 10678, '1. Es un factor de riesgo independiente para la enfermedad vascular aterosclerótica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28191, 10678, '2. Las concentraciones plasmáticas elevadas habitualmente son de origen genético.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28192, 10678, '3. El tratamiento con dieta y ejercicio reduce las concentraciones plasmáticas de la lipoproteína en un 25 %.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28193, 10678, '4. Dado que es un factor heredable habitualmente sólo se necesita medir una vez en la vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28194, 10679, '1. Riesgo bajo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28195, 10679, '2. Riesgo moderado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28196, 10679, '3. Riesgo alto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28197, 10679, '4. Riesgo muy alto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28198, 10680, '5. Durante una de las sesiones de diálisis refiere dolor centrotorácico y disnea de aparición súbita. Las constantes hemodinámicas son normales. Se pauta nitroglicerina intravenosa para la corrección del dolor torácico, que cede en unos quince minutos. Se muestran los electrocardiogramas realizados con y sin dolor torácico. No hubo elevación posterior de enzimas de necrosis miocárdica. ¿Cuál es el diagnóstico de sospecha y la actitud a seguir?:', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28199, 10680, '1. Síndrome coronario agudo sin elevación del segmento ST, de alto riesgo. Debe ingresar en una unidad con vigilancia electrocardiográfica continua con recomendación de coronariografía temprana (≤48 h).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28200, 10680, '2. Síndrome coronario agudo sin elevación del segmento ST, de riesgo moderado. Debe ingresar en una unidad con vigilancia electrocardiográfica continua, con recomendación inicial de coronariografía diferida (>48 h).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28201, 10680, '3. Síndrome coronario agudo sin elevación del segmento ST, de bajo riesgo. Debe ingresar en planta de hospitalización convencional con recomendación de prueba de inducción de isquemia antes del alta hospitalaria y coronariografía diferida según resultado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28202, 10680, '4. Los cambios electrocardiográficos no son diagnósticos de síndrome coronario agudo y se consideran secundarios a la hemodiálisis. No precisa ingreso hospitalario.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28203, 10681, '1. Optimizar el tratamiento de la hipertensión arterial, ya que está mal controlado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28204, 10681, '2. Optimizar el tratamiento hipolipemiante, ya que está mal controlado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28205, 10681, '3. Añadir un fármaco para la diabetes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28206, 10681, '4. Abandonar el hábito tabáquico, caminar a diario y perder peso.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28207, 10682, '1. Afectación de ventrículo derecho.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28208, 10682, '2. Rotura del septo interventricular basal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28209, 10682, '3. Rotura del músculo papilar posteromedial mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28210, 10682, '4. Pseudoaneurisma ventricular inferobasal.', false, 4);
