INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28212, 10683, '2. Glipizida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28213, 10683, '3. Acarbosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28214, 10683, '4. Sitagliptina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28215, 10684, '1. Abandono del tabaco.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28216, 10684, '2. Aumento de los niveles de lipoproteínas de alta densidad (colesterol HDL).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28217, 10684, '3. Control adecuado de la glucemia en pacientes diabéticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28218, 10684, '4. Aumento de la actividad física.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28219, 10685, '1. El infarto del ventrículo derecho puede producir signo de Kussmaul.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28220, 10685, '2. La elevación del segmento ST en V4 es la presentación más frecuente en el electrocardiograma.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28221, 10685, '3. El tratamiento incluye la expansión de volumen para conservar la precarga del ventrículo derecho.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28222, 10685, '4. Con la ecocardiografía podemos observar hipocinesia y dilatación del ventrículo derecho.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28223, 10686, '1. Tromboembolismo pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28224, 10686, '2. Miocardiopatía hipertrófica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28225, 10686, '3. Necrosis e isquemia subepicárdica anterior.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28226, 10686, '4. Miopericarditis aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28227, 10687, '1. Fibrilación auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28228, 10687, '2. Tromboembolismo pulmonar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28229, 10687, '3. Síndrome coronario sin elevación del segmento ST (SCASEST).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28230, 10687, '4. Infarto agudo de miocardio de cara diafragmática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28231, 10688, '1. Morfina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28232, 10688, '2. Dinitrato de isosorbida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28233, 10688, '3. Atenolol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28234, 10688, '4. Meperidina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28235, 10689, '1. Prescribir al paciente 180mg de ticagrelor como dosis de carga previa a la angioplastia primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28236, 10689, '2. Solicitar Troponina T de muy alta sensibilidad y esperar resultados para decidir la realización de angioplastia primaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28237, 10689, '3. Prescribir al paciente 300mg de ácido acetilsalicílico como dosis de carga previa a la angioplastia primaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28238, 10689, '4. Administrar oxígeno sólo a pacientes con hipoxemia (SaO2<90% o PaO2<60 mmHg).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28239, 10690, '1. Cardiogénico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28240, 10690, '2. Séptico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28241, 10690, '3. Hipovolémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28242, 10690, '4. Anafiláctico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28244, 10691, '2. Antagonistas del calcio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28245, 10691, '3. Ácido acetilsalicílico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28246, 10691, '4. Betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28247, 10692, '1. Retrasar la cirugía durante 3 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28248, 10692, '2. Mantener el tratamiento antiagregante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28249, 10692, '3. Suspender el AAS y mantener el clopidogrel.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28250, 10692, '4. Reducir la dosis de AAS a 100mg/día y suspender clopidogrel hasta el día siguiente de la cirugía', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28251, 10693, '1. Vena safena autóloga.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28252, 10693, '2. Vena cefálica autóloga.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28253, 10693, '3. Arteria torácica o mamaria interna.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28254, 10693, '4. Arteria radial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28255, 10694, '1. Rotura de una placa con trombo no oclusivo superpuesto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28256, 10694, '2. Espasmo de una arteria coronaria epicárdica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28257, 10694, '3. Isquemia miocárdica relacionada con aumento de la demanda miocárdica de oxígeno.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28258, 10694, '4. Disfunción del endotelio coronario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28259, 10695, '1. Infarto anteroseptal agudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28260, 10695, '2. Pericarditis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28261, 10695, '3. Infarto inferior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28262, 10695, '4. Infarto inferolateral agudo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28263, 10696, '1. Extrasistolia ventricular monomorfa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28264, 10696, '2. Antecedentes de hipertensión arterial y/o diabetes mellitus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28265, 10696, '3. Edad avanzada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28266, 10696, '4. Antecedentes de infarto de miocardio previo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28267, 10697, '1. Elevación de segmento ST en derivaciones II, III y avF.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28268, 10697, '2. Elevación de segmento ST en derivaciones V2, V3, V4 y V5.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28269, 10697, '3. Descenso de segmento ST en derivaciones V2, V3, V4 y V5.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28270, 10697, '4. Descenso de segmento ST en derivaciones II,III y avF, asociado a descenso en avL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28271, 10698, '1. Iniciar infusión de nitratos i.v.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28272, 10698, '2. Realizar fibrinolisis con tenecteplase (TNK).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28273, 10698, '3. Realizar angioplastia coronaria urgente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28274, 10698, '4. Administrar furosemida 40 mg i.v.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28275, 10699, '1. La mortalidad con tratamiento médico es del 20%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28276, 10699, '2. En caso de rotura de pared libre hay salta oximétrico en el ventrículo derecho en el cateterismo de Swan-Ganz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28277, 10699, '3. En caso de rotura de pared libre no hay frémito palpable.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28278, 10699, '4. Las complicaciones mecánicas suelen aparecer en el primer día postinfarto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28279, 10700, '1. Shock cardiogénico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28280, 10700, '2. Ruptura de pared libre de ventrículo izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28281, 10700, '3. Insuficiencia mitral aguda por rotura de músculo papilar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28282, 10700, '4. Taponamiento cardiaco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28283, 10700, '5. Trombosis de tronco común.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28284, 10701, '1. Realizar una determinación analítica de troponina y esperar su resultado para confirmar la presencia de un infarto agudo de miocardio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28285, 10701, '2. Tratar al paciente como si fuera un infarto con elevación del segmento ST, planteando una terapia de reperfusión lo más precoz posible.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28286, 10701, '3. Implantar un marcapasos transcutáneo ante la posibilidad de que desarrolle un bloqueo más avanzado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28287, 10701, '4. Realizar una TC urgente para descartar la presencia de una embolia pulmonar aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28288, 10701, '5. Como pudiera tratarse de una pericarditis aguda administraremos AINEs.', false, 5);
