INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28294, 10703, '"1. Médico con vasodilatadores y betabloqueantes para evitar la angina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28295, 10703, '2. Expectante con reposo riguroso ya que al disminuir la demanda miocárdica de oxígeno deberá disminuir la angina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28296, 10703, '3. Quirúrgico para revascularizar el miocardio isquémico mediante un puente (by-pass) de arteria mamaria izquierda distal a la lesión en la arteria coronaria enferma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28297, 10703, '4. Dilatación de la lesión en la arteria coronaria mediante un cateterismo terapéutico.', false, 4);
