INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28301, 10704, '3. Hombre de 55 años que tras una semana de tratamiento con doble antiagregación se le realiza una ergometría isotópica que muestra isquemia extensa en la cara anterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28302, 10704, '4. Mujer de 65 años con dolor en reposo y ergometría positiva clínica en el tercer estadio de Bruce.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28303, 10704, '5. Paciente de 55 años que ingresa por dolor torácico y disnea saturando al 80% a pesar de la administración de oxígeno y con un ECG con descenso del ST en la cara anterolateral que no revierte con la administración de nitroglicerina intravenosa.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28304, 10705, '1. Angina estable.', false, 1);
