INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28309, 10706, '1. El tronco de la coronaria izquierda es normal, sin placas de aterosclerosis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28310, 10706, '2. El catéter llega a la coronaria izquierda por vía arterial, pudiendo emplearse diversas vías de acceso (femoral, radial…).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28311, 10706, '3. La necesidad de revascularización coronaria, percutánea o quirúrgica, depende de la gravedad de las lesiones, de los síntomas y de la extensión de la isquemia miocárdica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28312, 10706, '4. Si se realiza tratamiento de la estenosis de la descendente anterior con angioplastia e implante de stent fármacoactivo, se debe mantener durante meses un tratamiento antiagregante plaquetario doble, con aspirina asociada a clopidogrel, prasugrel o ticagrelor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28313, 10706, '5. Las lesiones responsables de los síndromes coronarios agudos son placas aterosclerosas que sufren roturas o erosiones.', false, 5);
