INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28326, 10709, '3. Los pacientes con enfermedad de tres vasos y disfunción ventricular izquierda suelen recibir como primera opción de revascularización la cirugía coronaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28327, 10709, '4. En los pacientes diabéticos es preferible la revascularización percutánea a la cirugía de revascularización coronaria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28328, 10709, '5. La edad avanzada y la disfunción ventricular izquierda son factores que incrementan el riesgo operatorio en la cirugía coronaria.', false, 5);
