INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28379, 10720, '1. Es útil para disminuir el tamaño de la zona infartada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28380, 10720, '2. Es útil para disminuir las arritmias.', true, 2);
