INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28382, 10720, '4. Es útil para limitar la disfunción ventricular izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28383, 10720, '5. Sólo es útil en las primeras horas post-infarto.', false, 5);
