INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28444, 10733, '1. En el shock hipovolémico la presión venosa central y la presión de enclavamiento pulmonar están elevadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28445, 10733, '2. El shock secundario a insuficiencia suprarrenal no precisa de volumen ni vasopresores para su tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28446, 10733, '3. El tratamiento inicial del shock séptico debe ser la dobutamina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28447, 10733, '4. El shock se define por hipotensión, gasto cardiaco bajo y resistencias vasculares altas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28448, 10733, '5. El shock cardiogénico es un fallo primario de bomba que produce disminución del aporte de oxígeno a los tejidos y elevación de las presiones vasculares pulmonares.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28449, 10734, '1. Es una complicación infrecuente tras la angioplastia percutánea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28450, 10734, '2. La sospecha es una disección intimal de la arteria coronaria y la oclusión de la misma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28451, 10734, '3. Puede ser precisa la cirugía de forma urgente: cortocircuito –bypass- coronario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28452, 10734, '4. Está contraindicada la realización de una nueva coronariografía urgente para confirmar la sospecha clínica de oclusión arterial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28453, 10734, '5. El injerto vascular más frecuentemente utilizado es la arteria mamaria interna.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28454, 10735, '1. Los niveles disminuidos de colesterol HDL son factor de riesgo de ateroesclerosis dependiendo del nivel de colesterol total.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28455, 10735, '2. Se ha demostrado de forma definitiva que la terapia sustitutiva con estrógenos en la mujer postmenopáusica disminuye el riesgo cardiovascular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28456, 10735, '3. La hiperfibrinogenemia se considera factor de riesgo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28457, 10735, '4. La diabetes mellitus es factor de riesgo de ateroesclerosis por sus efectos en el árbol microvascular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28458, 10735, '5. Tras abandonar el hábito tabáquico el riesgo cardiovascular se reduce a largo plazo, en un periodo de años.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28459, 10736, '1. Oxigenoterapia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28460, 10736, '2. Noradrenalina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28461, 10736, '3. Reposición de la volemia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28462, 10736, '4. Diuréticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28463, 10736, '5. Estimulantes beta2-adrenérgicos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28464, 10737, '1. Infarto ventricular derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28465, 10737, '2. Tromboembolismo pulmonar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28466, 10737, '3. Rotura del músculo papilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28467, 10737, '4. Rotura de la pared libre ventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28468, 10737, '5. Hemorragia cerebral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28469, 10738, '1. Aumentar la presión arterial por vasoconstricción periférica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28470, 10738, '2. Aumentar la tensión de la pared del ventrículo izquierdo durante la sístole, lo que supone un efecto adverso por aumentar el consumo de oxígeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28471, 10738, '3. Mejoría de la perfusión miocárdica y la pulsatilidad que produce vasodilatación periférica, mejorando el flujo renal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28472, 10738, '4. Disminuye la presión diastólica coronaria, por efecto de la vasodilatación, empeorando el flujo en pacientes con patología coronaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28473, 10738, '5. Mejora el volumen minuto como consecuencia de un aumento de la precarga.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28474, 10739, '1. El alivio del dolor torácico con antiácidos indica patología gastro-esofágica en varones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28475, 10739, '2. El alivio del dolor torácico con antiácidos indica patología gastro-esofágica en mujeres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28476, 10739, '3. La ausencia de mejoría de dolor torácico con nitroglicerina excluye la isquemia miocárdica en hombres y mujeres.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28477, 10739, '4. La decisión diagnóstica no debe estar determinada por la respuesta a una maniobra terapéutica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28478, 10739, '5. La reproducción del dolor con la presión sobre el tórax indica patología osteomuscular y excluye el diagnóstico de angina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28479, 10740, '1. La reestenosis es muy frecuente y por eso se utiliza la implantación de conductos expansivos (stent), con lo que esta complicación es rara.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28480, 10740, '2. Si el paciente hubiera sido tratado diariamente con aspirina desde la ACTP inicial, este problema se hubiera reducido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28481, 10740, '3. Debería haberse administrado un hipolipemiante para prevenir el problema.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28482, 10740, '4. La administración de anticoagulantes orales durante 6 meses después de la ACTP previene esta complicación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28483, 10740, '5. Probablemente, la hiperplasia del músculo liso de las arterias coronarias contribuyó al problema actual.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28484, 10741, '1. Arteria mamaria interna izquierda', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28485, 10741, '2. Arteria epigástrica', false, 2);
