INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28494, 10743, '1. Solicitar una prueba de esfuerzo y si se confirma la existencia de isquemia coronaria, indicar un tratamiento médico adecuado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28495, 10743, '2. Se trata de un caso leve de isquemia coronaria, dado que se presenta después de un considerable esfuerzo y por ello indicaremos tratamiento médico con betabloqueantes y/o inhibidores del calcio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28496, 10743, '3. Por tratarse de un caso de angina estable no creemos que esté indicada la cirugía, por ello indicaremos tratamiento con aspirina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28497, 10743, '4. Contraindicaremos los esfuerzos excesivos, controlaremos el colesterol y haremos electrocardiogramas de control periódicamente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28498, 10743, '5. Solicitar prueba de esfuerzo y si se confirma la existencia de isquemia coronaria, indicaremos la realización de una coronariografía, tras lo cual se realizará, si fuera', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28499, 10744, '1. Tratamiento trombolítico con activador tisular del plasminógeno intracoronario únicamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28500, 10744, '2. Tratamiento trombolítico con activador tisular del plasminógeno intravenoso más aspirina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28501, 10744, '3. Tratamiento trombolítico con activador tisular del plasminógeno intravenoso más heparina.', false, 3);
