INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28527, 10749, '4. Apixaban', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28528, 10750, '1. El origen de la hipertensión en este caso es la secreción excesiva de aldosterona causada por una hiperfunción autónoma de la médula suprarrenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28529, 10750, '2. En la mayoría de los casos el sustrato anatómico es una hiperplasia bilateral de la corteza suprarrenal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28530, 10750, '3. La TC forma parte del estudio diagnóstico en caso de haber una confirmación bioquímica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28531, 10750, '4. La espironolactona está contraindicada en el manejo de esta patología', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28532, 10751, '1. Se recomienda tomar la presión arterial anualmente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28533, 10751, '2. Se recomienda tomar la presión arterial cada dos años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28534, 10751, '3. Se recomienda tomar la presión arterial cada tres años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28535, 10751, '4. Se recomienda tomar la presión arterial cada cuatro años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28536, 10752, '1. No es preciso realizar ningún estudio adicional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28537, 10752, '2. Está indicada la determinación de renina plasmática y aldosterona.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28538, 10752, '3. El hallazgo en dos analíticas sucesivas de cifras de potasio <3,5 mEq confirmaría el diagnóstico de sospecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28539, 10752, '4. La ausencia de hipopotasemia y alcalosis metabólica, descarta el diagnóstico de sospecha.', false, 4);
