INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28555, 10756, '4. Betabloqueantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28556, 10757, '1. El sistema nervioso simpático es el principal responsable del desarrollo de la enfermedad vascular y uno de los principales focos de atención terapéutica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28557, 10757, '2. Entre los cambios estructurales de la HTA se encuentran la hipertrofia de la capa media de las arterias de resistencia y la rigidez de las grandes arterias.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28558, 10757, '3. En hipertensos jóvenes o de mediana edad, la forma más frecuente de presentación es la HTA sistólica aislada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28559, 10757, '4. La disfunción endotelial por desequilibrio en la producción de sustancias vasodilatadoras y antiinflamatorias y sustancias vasoconstrictoras o proinflamatorias, no parece ser el desencadenante de la enfermedad según las últimas hipótesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28560, 10758, '1. Mantener su tratamiento actual sin cambios y repetir la MAPA en 6 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28561, 10758, '2. Asociar un antialdosterónico, suspender la hidroclorotiazida y revisar en consulta en 6 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28562, 10758, '3. Asociar olmesartán y repetir la MAPA en 6 meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28563, 10758, '4. Plantear estudio para descartar causas de hipertensión secundaria y asociar un cuarto fármaco.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28564, 10759, '1. Añadir un cuarto fármaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28565, 10759, '2. Incrementar la dosis de alguno de los que está tomando.', false, 2);
