INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28587, 10764, '1. Mantener el mismo tratamiento ya que está bien controlada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28588, 10764, '2. Reducir la dosis del comprimido ya que posiblemente necesite menos dosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28589, 10764, '3. Cambiar a un Antagonista de los Receptores de la Angiotensina II porque producen menos tos y edemas en miembros inferiores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28590, 10764, '4. Retirar la medicación hipotensora ya que la tensión está bien controlada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28591, 10764, '5. Cambiar a alfametildopa.', true, 5);
