INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28600, 10766, '4. No produce beneficio tratar la hipertensión arterial en mayores de 80 años de edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28601, 10766, '5. La cifra de presión sistólica es mejor predictor de cardiopatía isquémica que la de diastólica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28602, 10767, '1. Reduce la glucemia y la tensión arterial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28603, 10767, '2. Evita el riesgo de taquiarritmias, incluso después de un infarto de miocardio reciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28604, 10767, '3. Es aplicable en cualquier situación de prevención primaria como de prevención secundaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28605, 10767, '4. Aumenta mucho las concentraciones de colesterol HDL, aunque eleve un poco las concentraciones de colesterol LDL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28606, 10767, '5. Reduce el consumo muscular de oxígeno.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28607, 10768, '1. Mejora si se reduce el consumo de alcohol por debajo de 25-30 g diarios.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28608, 10768, '2. Supone un factor de riesgo sólo si supera 140/90.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28609, 10768, '3. Permanece inalterada durante el día si el sujeto está tranquilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28610, 10768, '4. Si está alta es un factor de riesgo mayor para el desarrollo de insuficiencia cardiaca o ictus, aunque el tabaco supone mucho mayor riesgo para estas 2 patologías.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28611, 10768, '5. Está regulada exclusivamente por los riñones.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28612, 10769, '1. La relación E (máxima velocidad de flujo en el llenado rápido) /A (máxima velocidad en la fase de contribución auricular) se eleva por encima de 1 cuando se deteriora la función diastólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28613, 10769, '2. No existe correlación entre el grado de hipertrofia ventricular y la gravedad de las arritmias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28614, 10769, '3. La fracción de eyección no se encuentra disminuida en la mayoría de los hipertensos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28615, 10769, '4. La mayoría de los fármacos antihipertensivos reducen las cifras tensionales, pero no la masa ventricular izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28616, 10769, '5. En caso de insuficiencia cardiaca con función sistólica deprimida están contraindicados los beta-bloqueantes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28617, 10770, '1. Cifras de Tensión Arterial Sistólica por encima de 180 mmHg.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28618, 10770, '2. Apnea Obstructiva del sueño.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28619, 10770, '3. Lesión orgánica irreversible o difícilmente reversible.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28620, 10770, '4. Cumplimiento deficiente del plan terapéutico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28621, 10770, '5. Causa secundaria no sospechada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28622, 10771, '1. Bloqueo aurículo-ventricular de 2º grado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28623, 10771, '2. Asma bronquial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28624, 10771, '3. Enfermedad del nódulo sinusal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28625, 10771, '4. Diabetes mellitus en tratamiento con hipoglucemiantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28626, 10771, '5. Insuficiencia cardiaca.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28627, 10772, '1. La disminución de la proteinuria con Inhibidores de la ECA y ácido acetil salicílico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28628, 10772, '2. El control de la volemia con restricción de sal y diuréticos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28629, 10772, '3. La disminución de la precarga con nitratos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28630, 10772, '4. La disminución de la precarga con inhibidores de la ECA.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28631, 10772, '5. La acción de vasodilatadores y potentes como la Hidralacina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28632, 10773, '1. Hipertrofia de la capa media de arterias y arteriolas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28633, 10773, '2. Necrosis fibrinoide.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28634, 10773, '3. Panarteritis exudativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28635, 10773, '4. Hialinosis de la media.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28636, 10773, '5. Fibrosis de la íntima.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28637, 10774, '1. Insuficiencia aórtica por válvula aórtica bicúspide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28638, 10774, '2. Estenosis valvular aórtica de grado moderado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28639, 10774, '3. Coartación de aorta.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28640, 10774, '4. Miocardiopatía hipertrófica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28641, 10774, '5. Disección aórtica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28642, 10775, '1. Diurético.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28643, 10775, '2. Betabloqueante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28644, 10775, '3. Calcioantagonista.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28645, 10775, '4. Inhibidor de la enzima conversora de la angiotensina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28646, 10775, '5. Antagonista del receptor de la angiotensina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28647, 10776, '1. Anciano con hipertensión sistólica aislada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28648, 10776, '2. Varón de edad media con antecedentes de infarto de miocardio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28649, 10776, '3. Diabético con nefropatía diabética.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28650, 10776, '4. Mujer joven con estenosis de arteria renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28651, 10776, '5. Mujer de 50 años, fumadora, obesa e hipercolesterolémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28652, 10777, '1. En pacientes obesos la reducción del peso por si sola no disminuye la tensión arterial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28653, 10777, '2. Los inhibidores de la enzima conversora de la angiotensina (IECA) deben añadirse al tratamiento previo con diuréticos sin interrupción de éstos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28654, 10777, '3. Los antagonistas de los receptores de la angiotensina II no producen hiperpotasemia como efecto secundario, a diferencia de los IECA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28655, 10777, '4. Los estudios a largo plazo han demostrado que los diuréticos en el tratamiento de la HTA disminuyen la morbimortalidad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28656, 10777, '5. La taquicardia refleja es un efecto secundario de los antagonistas del calcio no dihidropiridínicos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28657, 10778, '1. Control estricto de la tensión arterial con labetalol endovenoso.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28658, 10778, '2. Intervención quirúrgica emergente de sustitución de aorta descendente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28659, 10778, '3. Control estricto de la tensión arterial con hidralacina endovenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28660, 10778, '4. Intervención quirúrgica programada en breve plazo de reparación mediante parche de la zona de desgarro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28661, 10778, '5. Intervención quirúrgica programada en breve plazo de sustitución de aorta descendente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28662, 10779, '1. Administrar nifedipino sublingual y actuar en función de la respuesta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28883, 10827, '1. Tiroidectomía subtotal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28663, 10779, '2. Administrar una tiazida y programar para estudio de su hipertensión arterial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28664, 10779, '3. Programar al menos dos citas para realizar despistaje de hipertensión arterial.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28665, 10779, '4. Recomendar dieta hiposódica, ejercicio aeróbico 30 minutos al día, consumo limitado de alcohol, evitar situaciones estresantes y programar cita para estudiar su hipertensión arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28666, 10779, '5. Enviar al servicio de Nefrología para el estudio de su hipertensión arterial.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28667, 10780, '1. Observar a la enferma durante una hora en una habitación tranquila antes de dar medicación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28668, 10780, '2. Esperar los resultados de laboratorio antes de decidir el tratamiento específico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28669, 10780, '3. Administrar nitroprusiato sódico en infusión intravenosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28670, 10780, '4. Administrar diazóxido sódico en bolos i.v.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28671, 10780, '5. Administrar nicardipino intravenoso en dosis única.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28672, 10781, '1. Bloqueantes alfa adrenérgicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28673, 10781, '2. Nitratos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28674, 10781, '3. Inhibidores de la enzima convertidora de angiotensina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28675, 10781, '4. Bloqueantes beta adrenérgicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28676, 10781, '5. Antagonistas de los canales de calcio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28677, 10782, '1. Inspección del precordio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28678, 10782, '2. Palpación del área precordial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28679, 10782, '3. Percusión cardiaca.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28680, 10782, '4. Auscultación cardiaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28681, 10783, '1. En la estenosis aórtica grave se puede auscultar un desdoblamiento inverso o paradójico del segundo ruido, que es mayor durante la espiración', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28682, 10783, '2. En la insuficiencia aórtica grave se puede auscultar un soplo mesodiastólico de baja tonalidad en el foco mitral', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28683, 10783, '3. En el mixoma auricular se puede auscultar un ruido diastólico de tonalidad grave, que se aprecia de forma intermitente en algunas posturas', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28684, 10783, '4. En la pericarditis aguda se puede auscultar un roce en el borde esternal izquierdo, que se aprecia mejor con el paciente en decúbito, al final de la inspiración', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28685, 10784, '1. Pericarditis constrictiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28686, 10784, '2. Síndrome de vena cava superior.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28687, 10784, '3. Insuficiencia tricúspide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28688, 10784, '4. Insuficiencia cardiaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28689, 10785, '1. Ductus persistente', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28690, 10785, '2. Disfunción músculo papilar', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28691, 10785, '3. Estenosis mitral', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28692, 10785, '4. Insuficiencia aórtica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28693, 10786, '1. La radiografía de tórax resulta muy útil para el diagnóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28694, 10786, '2. El registro venoso yugular permite objetivar un colapso x muy profundo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28695, 10786, '3. Es habitual la presencia de pulso arterial paradójico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28696, 10786, '4. El colapso auricular derecho es muy sensible para el diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28697, 10786, '5. El colapso ventricular derecho es muy específico para el diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28698, 10787, '1. Es un sonido de baja frecuencia', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28699, 10787, '2. Se puede producir en procesos que incrementan la velocidad o el volumen de llenado ventricular', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28700, 10787, '3. Aparecen al final de la diástole', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28701, 10787, '4. Está presente en pacientes con insuficiencia mitral grave', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28702, 10787, '5. Puede aparecer en niños normales y en pacientes con gasto cardíaco elevado', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28703, 10788, '1. Insuficiencia mitral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28704, 10788, '2. Insuficiencia pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28705, 10788, '3. Insuficiencia tricúspide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28706, 10788, '4. Insuficiencia aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28707, 10788, '5. Estenosis aórtica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28708, 10789, '1. La presión en el ventrículo es máxima durante la fase de contracción isovolúmica o isovolumétrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28709, 10789, '2. El primer ruido cardiaco corresponde al cierre de las válvulas semilunares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28710, 10789, '3. El complejo QRS sucede durante la fase de eyección o expulsión ventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28711, 10789, '4. La presión arterial es máxima durante la fase de eyección o expulsión ventricular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28712, 10789, '5. La sístole auricular coincide exactamente con la onda P del electrocardiograma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28713, 10790, '1. El 2º ruido cardíaco corresponde con el cierre de las válvulas auriculoventriculares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28714, 10790, '2. Los soplos continuos pueden auscultarse tanto en estenosis como insuficiencias valvulares severas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28715, 10790, '3. En el pulso venoso yugular la onda “a” se debe a la distensión venosa producida por la contracción de la aurícula izquierda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28716, 10790, '4. El pulso alternante es típico de la miocardiopatía hipertrófica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28717, 10790, '5. El signo de Kussmaul es un aumento de la presión venosa central durante la inspiración.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28718, 10791, '1. Estenosis aórtica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28719, 10791, '2. Taponamiento cardiaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28720, 10791, '3. Pericarditis constrictiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28721, 10791, '4. Embolia pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28722, 10791, '5. Enfisema pulmonar (cor pulmonale).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28723, 10792, '1. En adultos jóvenes, fuertes, sanos', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28724, 10792, '2. En atletas', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28725, 10792, '3. En mujeres gestantes', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28726, 10792, '4. En pacientes mixedematosos', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28727, 10792, '5. En pacientes con enfermedades febriles', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28728, 10793, '1. Aumento del volumen cardíaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28729, 10793, '2. Aumento de la masa eritrocitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28730, 10793, '3. Aumento del valor hematocrito.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28731, 10793, '4. Aumento de la hemoglobina reducida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28732, 10793, '5. Aumento de la carboxihemoglobina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28733, 10794, '1. La campana es mejor para oír los sonidos graves como el soplo de la estenosis mitral.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28734, 10794, '2. La membrana identifica mejor sonidos graves como el soplo de la Insuficiencia aórtica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28884, 10827, '2. HemiKroidectomía derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28735, 10794, '3. El primer tono cardíaco sigue al pulso carotideo y el segundo tono lo precede', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28736, 10794, '4. El primer tono normal es más fuerte y agudo que el segundo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28737, 10794, '5. El segundo tono cardíaco se debe al cierre de las válvulas mitral y tricúspide.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28738, 10795, '1. Onda a del pulso yugular – Cuarto ruido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28739, 10795, '2. Clicks de apertura – Protosístole.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28740, 10795, '3. Arrastre presistólico – Ritmo sinusal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28741, 10795, '4. Llenado ventricular rápido – Tercer ruido.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28742, 10795, '5. Aumento de intensidad del soplo con inspiración – Origen izquierdo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28743, 10796, '1. Soplo diastólico después del chasquido de apertura.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28744, 10796, '2. Disminución de la presión sistólica durante la inspiración.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28745, 10796, '3. Soplo sistólico que aumenta durante las maniobras de Valsalva.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28746, 10796, '4. Tercer tono cardíaco de origen izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28747, 10796, '5. Desdoblamiento fijo del segundo ruido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28748, 10797, '1. Distinguir un soplo diastólico de uno sistólico', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28749, 10797, '2. Oír mejor el chasquido de apertura en pacientes con estenosis mitral', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28750, 10797, '3. Valorar la presencia de un tercer y/o cuarto tono', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28751, 10797, '4. Detectar el clic mesosistólico del prolapso mitral', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28752, 10797, '5. Auscultar a los niños pequeños y bebés, en los que la membrana no capta bien la tonalidad de los ruidos cardíacos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28753, 10798, '1. Bloqueo completo de rama izquierda', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28754, 10798, '2. Bloqueo completo de rama derecha', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28755, 10798, '3. Bloqueo AV de tercer grado', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28756, 10798, '4. Estenosis pulmonar congénita', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28757, 10798, '5. Estenosis mitral severa', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28758, 10799, '1. Doble sesión mitral en ritmo sinusal', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28759, 10799, '2. Estenosis mitral en fibrilación auricular, probablemente severa', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28760, 10799, '3. Mixoma de aurícula izquierda', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28761, 10799, '4. Insuficiencia aórtica en ritmo sinusal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28762, 10799, '5. Estenosis mitral en ritmo sinusal', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28763, 10800, '1. Pulso Parvus - Estenosis aórtica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28764, 10800, '2. Pulso Tardus - Insuficiencia aórtica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28765, 10800, '3. Chasquido de apertura - Estenosis mitral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28766, 10800, '4. Soplo Mesosistólico - Estenosis aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28767, 10800, '5. Soplo Pansistólico - Insuficiencia mitral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28768, 10801, '1. Hipertensión pulmonar severa y realizar un ecocardiograma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28769, 10801, '2. Fibrilación auricular y realizar un ECG.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28770, 10801, '3. Que es un hallazgo normal en gente joven y no hacer nada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28771, 10801, '4. Embolismo pulmonar y solicitar una gammagrafía pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28772, 10801, '5. Insuficiencia tricúspide probablemente severa en ritmo sinusal y solicitar un cateterismo cardíaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28773, 10802, '1. Miocardiopatía hipertrófica obstructiva', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28774, 10802, '2. Doble lesión aórtica con predominio de la insuficiencia', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28775, 10802, '3. Estenosis aórtica probablemente severa', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28776, 10802, '4. Hipertensión arterial severa', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28777, 10802, '5. Coartación de aorta', false, 5);
