INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28879, 10826, '2. Indicaría la realización de una angiograPa cerebral para descartar una aneurisma, ya que lo más probable es que estemos ante un caso de hemorragia subaracnoidea y la masa que se evidencia en la TC sea un aneurisma trombosado paraselar.', false, 2);
