INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28882, 10826, '5. Punción lumbar para descartar meningiKs bacteriana - previo inicio de anKbioterapia empírica. Una vez estabilizada la paciente, estudio de la masa selar.', false, 5);
