INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28971, 10847, '1. Una neoplasia endocrina múlKple Kpo 1 o Síndrome de Wermer.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28972, 10847, '2. Una neoplasia endocrina múlKple Kpo 2 A o Síndrome de Sipple.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28973, 10847, '3. Una neoplasia endocrina múlKple Kpo 2B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28974, 10847, '4. SomatostaKnoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28975, 10847, '5. Un tumor neuroendocrino productor de PTH.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28976, 10848, '1. Se asocia a MEN Kpo IIa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28977, 10848, '2. Es un tumor endocrino pancreáKco cuya resección quirúrgica supone la curación en la mayoría de casos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28978, 10848, '3. Suele ser un tumor mulKfocal y maligno en la mayoría de los casos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28979, 10848, '4. Suele ser un tumor de localización extrapancreáKca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28980, 10848, '5. El tratamiento de elección es la radiofrecuencia percutánea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28981, 10849, '1. Carcinoma medular de Kroides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28982, 10849, '2. Tumor endocrino del páncreas.', false, 2);
