INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28985, 10849, '5. Adenoma hipofisario.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28986, 10850, '1. El IMC es la mejor medida de correlación entre exceso de peso y gravedad de la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28987, 10850, '2. El IMC es una medida útil, pero que no se utiliza para la indicación de cirugía bariátrica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28988, 10850, '3. El punto de corte del IMC es de 55, inde pendientemente de las enfermedades asociadas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28989, 10850, '4. Paciente con IMC por debajo de 35 y enfermedades metabólicas poco controla das se pueden beneficiar de la cirugía bariátrica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28990, 10851, '1. El tratamiento farmacológico logra una pérdida de peso superior al tratamiento quirúrgico en pacientes con obesidad grave.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28991, 10851, '2. La cirugía bariátrica está indicada únicamente en pacientes con obesidad grado I sin comorbilidades.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28992, 10851, '3. El tratamiento farmacológico es más eficaz que la cirugía para mejorar la diabetes tipo 2 en pacientes con obesidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28993, 10851, '4. La cirugía bariátrica logra mayores reducciones de peso y mejoría de comorbilidades que el tratamiento farmacológico en obesidad grave.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28994, 10852, '1. Nutrición enteral por sonda nasogástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (28995, 10852, '2. Nutrición enteral por sonda nasoduodenal.', false, 2);
