INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29003, 10854, '2. Caquexia por empiema crónico en paciente inmunodeprimido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29004, 10854, '3. Íleo paralíKco prolongado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29005, 10854, '4. Enfermedad de Alzheimer avanzada con grave riesgo de broncoaspiración.', false, 4);
