INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29012, 10856, '2. Fístula yeyunal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29013, 10856, '3. Resección subtotal de intesKno delgado', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29014, 10856, '4. ExpectaKva de ayuno de menos de 5 días.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29015, 10856, '5. Postoperatorio de hemicolectomia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29016, 10857, '1. La mayor parte de las lesiones producidas por la corriente eléctrica en medio doméstico y laboral proceden de fuentes de alto voltaje.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29017, 10857, '2. Las lesiones dérmicas dependen del efecto de un aumento de la temperatura generado sobre la dermis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29018, 10857, '3. La corriente de bajo voltaje produce lesiones profundas, mientras que la de alto voltaje da lugar a lesiones superficiales adyacentes al punto de contacto con la corriente eléctrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29019, 10857, '4. La marca eléctrica es diagnóstica del lugar en el que se ha producido el contacto y, por tanto, el punto de entrada de la corriente en el cuerpo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29020, 10858, '1. Eritema no blanqueable.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29021, 10858, '2. Pérdida de espesor total de la piel con exposición del tejido celular subcutáneo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29022, 10858, '3. Pérdida de epidermis con exposición de la dermis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29023, 10858, '4. Aparición de tejido de granulación en el lecho del defecto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29024, 10859, '1. Un agregado de histiocitos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29025, 10859, '2. Un agregado de linfocitos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29026, 10859, '3. Un agregado de células plasmáticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29027, 10859, '4. Sinónimo de tejido de granulación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29028, 10860, '1. Cuando el defecto cutáneo abarca una gran superficie corporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29029, 10860, '2. En un paciente con comorbilidades médicas significativas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29030, 10860, '3. Cuando hay un tendón sin paratendón en la base de la herida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29031, 10860, '4. Cuando hay una infección activa en el lecho de la herida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29032, 10861, '1. Colgajo anterolateral fasciocutáneo de muslo, pediculado.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29033, 10861, '2. Colgajo libre de músculo dorsal ancho con isla cutánea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31682, 11455, '4. Efedrina', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29034, 10861, '3. Colgajo pediculado de trapecio (musculocutáneo).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29035, 10861, '4. Colgajo libre SCIP (derivado del sistema circunflejo ilíaco superficial).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29036, 10862, '1. Unos de los lechos considerados injertables por su rica vascularización es el tejido de granulación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29037, 10862, '2. Podemos clasificarlos en injertos de piel parcial (si presentan sólo la epidermis) o injertos de piel total (si presentan la epidermis y la dermis subyacente).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29038, 10862, '3. Suelen presentar un proceso de contracción, que aparece tanto a la hora de ser extraídos como después de haber sido injertados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29039, 10862, '4. Dentro de las comorbilidades médicas asociadas a la pérdida del injerto podemos destacar la diabetes, el tabaquismo y la vasculopatía periférica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29040, 10863, '1. Colgajo de músculo recto abdominal transverso basado en la arteria epigástrica inferior profunda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29041, 10863, '2. Colgajo de gastrocnemio medial, basado en la arteria sural media.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29042, 10863, '3. Colgajo anterolateral de muslo, basado en la rama descendente de la arteria circunfleja femoral lateral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29043, 10863, '4. Colgajo radial fasciocutáneo, basado en ramas perforantes de la arteria radial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29044, 10864, '1. Se trata de un colgajo de perforantes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29045, 10864, '2. Está irrigado por ramas de la arteria femoral circunfleja medial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29046, 10864, '3. Puede obtenerse realizando una disección tanto suprafascial como subfascial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29047, 10864, '4. Las perforantes musculocutáneas atraviesan el músculo vasto lateral antes de irrigar la piel del colgajo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29048, 10865, '1. Corticoides intravenosos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29049, 10865, '2. Adrenalina 1/1000 subcutánea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29050, 10865, '3. Icatibant o concentrado de C1 inhibidor intravenoso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29051, 10865, '4. Omalizumab.', false, 4);
