INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29053, 10866, '2. Por inmunocomplejos circulantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29054, 10866, '3. Activación no inmunológica de la vía efectora.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29055, 10866, '4. Un déficit de capsaicina.', true, 4);
