INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29059, 10867, '4. Impétigo neonatal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29060, 10868, '1. El paciente ha sufrido una quemadura química por un ácido por lo que se debe realizar cura con un álcali para parar la reacción química. Posteriormente cura de la quemadura con sulfadiazina argéntica y reevaluación de la misma en las siguientes horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29061, 10868, '2. El paciente ha sufrido una quemadura química por álcalis, por lo que se debe proceder al lavado exhaustivo con agua y jabón y después de comprobar el pH de la piel, cura local con sulfadiazina argéntica y reevaluación de la quemadura en las siguientes horas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29062, 10868, '3. Dado el tiempo transcurrido posiblemente sea una reacción alérgica. Se procederá a la aplicación de un corticoide tópico y a la toma de antihistamínicos orales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29063, 10868, '4. Dado el uso continuado de botas para la realización de su trabajo el paciente presenta una colonización por hongos y debe tratarse con antifúngicos tópicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29064, 10869, '1. Impétigo contagioso.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29065, 10869, '2. Molluscum contagioso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29066, 10869, '3. Infección por herpes virus.', false, 3);
