INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29069, 10870, '2. Dermatitis atópica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29070, 10870, '3. Dermatitis seborreica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29071, 10870, '4. Dermatitis dishidrótica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29072, 10871, '1. Ustekinumab.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29073, 10871, '2. Dupilumab.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29074, 10871, '3. Certolizumab.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29075, 10871, '4. Bimekizumab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29076, 10872, '1. Biopsia cutánea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29077, 10872, '2. Analítica sanguínea con determinación de IgE.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29078, 10872, '3. Intradermorreacción con suero autólogo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29079, 10872, '4. Ninguna, es suficiente con la anamnesis y exploración clínica.', true, 4);
