INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29084, 10874, '1. El fenómeno de Koebner indica que la psoriasis es una enfermedad asociada a comorbilidades metabólicas y articulares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29085, 10874, '2. El principal tratamiento sistémico de la psoriasis palmoplantar se basa en ciclos cortos de corticoides orales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29086, 10874, '3. La psoriasis es un trastorno crónico inmunomediado, con una herencia autosómica recesiva y factores desencadenantes ambientales, como traumatismos, infecciones, medicamentos o estrés psicológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29087, 10874, '4. Los hallazgos histológicos típicos incluyen acantosis con crestas elongadas, hipogranulosis, hiper y paraqueratosis, vasos dilatados y agregados de neutrófilos en la epidermis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29088, 10875, '1. Prednisona oral.', false, 1);
