INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29116, 10882, '1. En la biopsia cutánea realizada de una lesión de reciente aparición esperaría encontrar espongiosis epidérmica, vesículas espongióticas y un infiltrado eosinofílico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29117, 10882, '2. Las lesiones son compatibles con una pustulosis exantemática aguda generalizada por lo que iniciaría tratamiento con amoxicilina/clavulánico por vía oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29118, 10882, '3. Con la sospecha de una enfermedad ampollosa autoinmune se realiza una biopsia de las lesiones para inmunofluorescencia directa. Se cursa ingreso hospitalario y se inicia tratamiento con prednisona a dosis de 1 mg/kg/día.', true, 3);
