INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29219, 10907, '1. Solicitaría pruebas serológicas para la hepatitis B y C, parvovirus humano B19, virus de Epstein-Barr y prueba para el virus de la inmunodeficiencia humana, dado que la causa más probable son las enfermedades infecciosas, especialmente las infecciones víricas agudas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29220, 10907, '2. Aunque se trata de un diagnóstico de exclusión, solicitaría una ferritina sérica por la posibilidad de que se trate de una enfermedad de Still del adulto.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29221, 10907, '3. Solicitaría un estudio inmunológico que incluyera anticuerpos antinucleares, factor reumatoide, anticuerpos antipéptidos cíclicos citrulinados y ANCAs para confirmar la sospecha de una enfermedad reumática sistémica como la artritis reumatoide o lupus eritematoso sistémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29222, 10907, '4. Solicitaría un estudio genético dado que lo más probable es que se trate de una enfermedad autoinflamatoria tipo fiebre mediterránea familiar.', false, 4);
