INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29293, 10923, '3. Metformina o levodopa por igual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29294, 10923, '4. Levodopa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29295, 10924, '1. Sarampión', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29296, 10924, '2. Síndrome de DRESS', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29297, 10924, '3. Síndrome de Stevens Johnson', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29298, 10924, '4. Angioedema', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29299, 10925, '1. Urticaria aguda de causa farmacológica', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29300, 10925, '2. Eritema exudativo minor secundario a fármacos', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29301, 10925, '3. Síndrome de Stevens-Johnson farmacológico', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29302, 10925, '4. Necrolisis tóxica epidérmica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29303, 10926, '1. Toxina del Staphylococcus aureus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29304, 10926, '2. Coxsackie B4.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29305, 10926, '3. Minociclina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29306, 10926, '4. Virus difícil de filiar, posiblemente el mismo que el cuadro de la guardería.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29307, 10927, '1. Las formas minor se asocian a la infección por el virus herpes simple y se caracterizan por las denominadas lesiones en diana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29308, 10927, '2. Las formas major o síndrome de Stevens-Johnson, se caracterizan por la ausencia de afectación de las mucosas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29309, 10927, '3. La afectación de las mucosas en las formas minor se observa alrededor del 25% de los casos y se limita a la mucosa oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29310, 10927, '4. La necrolisis epidérmica tóxica, cuadro caracterizado por el despegamiento de amplias áreas de la piel, representa la forma más grave de eritema multiforme major y se relaciona con la ingesta de fármacos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29311, 10928, '1. Lupus eritematoso subagudo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29312, 10928, '2. Tiña corporis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29313, 10928, '3. Porfiria cutánea tarda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29314, 10928, '4. Eritema anular centrífugo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29315, 10929, '1. Síndrome de la piel escaldada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29316, 10929, '2. Síndrome de Stevens-Johnson.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29317, 10929, '3. Enfermedad mano-pie-boca atípica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29318, 10929, '4. Penfigoide ampolloso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29319, 10930, '1. Es una enfermedad de declaración obligatoria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29320, 10930, '2. El tratamiento de elección es la amoxicilina, un gramo cada 8 horas durante 7 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29321, 10930, '3. Debe derivarse a un centro hospitalario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29322, 10930, '4. En la mayoría de los casos, la fiebre precede al exantema y la escara.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29323, 10931, '1. El tratamiento de elección incluso en formas localizadas es la cloxacilina vía oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29324, 10931, '2. En caso de alergia a la penicilina, la opción más adecuada sería el ciprofloxacino oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29325, 10931, '3. Debe realizarse tratamiento oral en pacientes con valvulopatía reumática por el riesgo de endocarditis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29326, 10931, '4. Es una infección fundamentalmente estreptocócica por Streptococcus pyogenes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29327, 10932, '1. Impétigo contagioso.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29328, 10932, '2. Molluscum contagioso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29329, 10932, '3. Infección por herpes virus.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29330, 10932, '4. Candidiasis mucocutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29331, 10933, '1. Fascitis estreptocócica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29332, 10933, '2. Glomerulonefritis postestreptocócica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29333, 10933, '3. Shock tóxico estreptocócico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29334, 10933, '4. Escarlatina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29335, 10934, '1. Eritema exudativo multiforme.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29336, 10934, '2. Impétigo contagioso.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29337, 10934, '3. Acné infantil.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29338, 10934, '4. Psoriasis pustuloso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29339, 10935, '1. Se recomienda el análisis del líquido cefalorraquídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29340, 10935, '2. La azitromicina oral es un tratamiento alternativo eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29341, 10935, '3. Se recomienda una valoración clínica y serológica (RPR) a los 6 y 12 meses después del tratamiento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29342, 10935, '4. Si los títulos de RPR permanecen positivos después de 12 meses está indicado administrar el tratamiento de nuevo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29343, 10936, '1. Dientes de Hutchinson.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29344, 10936, '2. Nariz en silla de montar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29345, 10936, '3. Queratitis intersticial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29346, 10936, '4. Cardiopatía congénita.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29347, 10937, '1. Condiloma lata.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29348, 10937, '2. Molluscum contagiosum.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29349, 10937, '3. Condiloma acuminado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29350, 10937, '4. Liquen plano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29351, 10938, '1. Puede cursar con uveítis y producir ceguera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29352, 10938, '2. Las lesiones cutáneas involucionan espontáneamente entre 1 y 6 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29353, 10938, '3. Una cifra baja de linfocitos CD4+ (<350 cel/microL) es un riesgo para desarrollar afectación del sistema nervioso central y puede estar indicado practicar una punción lumbar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29354, 10938, '4. La azitromicina es una buena opción para el tratamiento de la enfermedad, ya que la resistencia a los macrólidos es escasa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29355, 10939, '1. Viruela del mono.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29356, 10939, '2. Herpes genital.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29357, 10939, '3. Sífilis primaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29358, 10939, '4. Lesiones por primoinfección por VIH.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29359, 10940, '1. Psoriasis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29360, 10940, '2. Liquen plano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29361, 10940, '3. Sífilis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29362, 10940, '4. Gonorrea.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29363, 10941, '1. No debe hacer nada, ya que el riesgo de transmisión del VIH es insignificante.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29364, 10941, '2. Debe recomendarse gammaglobulina IV en las primeras 72 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29365, 10941, '3. Debe hacer profilaxis postexposición frente al VIH durante 28 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29366, 10941, '4. Podría haber realizado profilaxis postexposición, pero ya es tarde para iniciarla.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29367, 10942, '1. Doxiciclina 100 mg cada 12 horas durante 21 días.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29368, 10942, '2. Cloxacilina 500 mg cada 6 horas durante 7 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29369, 10942, '3. Ceftriaxona 0,5 g IM (una única dosis) y azitromicina 1 g VO (una única dosis).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29370, 10942, '4. Moxifloxacino 400 mg una vez al día durante 7 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29371, 10943, '1. Pioderma gangrenoso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29372, 10943, '2. Pénfigo vulgar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29373, 10943, '3. Infección micótica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29374, 10943, '4. Infección por el virus del herpes simple.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29375, 10944, '1. Neisseria gonorrhoeae faringea', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29376, 10944, '2. Chlamydia trachomatis genital', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29377, 10944, '3. Molluscum contagiosum del área genital', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29378, 10944, '4. Trichomona vaginalis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29379, 10945, '1. Es una dermatosis producida por herpesvirus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29380, 10945, '2. El tratamiento de elección es imiquimod.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29381, 10945, '3. Se considera una zoonosis de frecuente transmisión al ser humano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29382, 10945, '4. Se incluye dentro de las enfermedades de transmisión sexual.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29383, 10946, '1. Hay que obtener una muestra del exudado uretral para realizar el diagnóstico etiológico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29384, 10946, '2. Se realizará tratamiento empírico con ceftriaxona intramuscular y azitromicina vía oral en dosis únicas, en espera de los resultados microbiológicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29385, 10946, '3. Hay que realizar antibiograma en los casos en que se aísle N. gonorrhoeae.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29386, 10946, '4. A las 2-3 semanas de la administración del tratamiento, hay que obtener nuevas muestras uretrales para confirmar la curación microbiológica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29387, 10947, '1. Administración única intramuscular de penicilina G benzatina 2,4 millones de unidades.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29388, 10947, '2. Penicilina G benzatina 2,4 millones de unidades, 1 inyección intramuscular semanal durante 3 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29389, 10947, '3. Penicilina acuosa, 24 millones de unidades al día (en 6 dosis intravenosas), durante 2 semanas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29390, 10947, '4. No puede tomarse una decisión terapéutica en este caso sin realizar antes una punción lumbar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29391, 10948, '1. Perihepatitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29392, 10948, '2. Uretritis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29393, 10948, '3. Chancroide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29394, 10948, '4. Linfogranuloma venéreo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29395, 10949, '1. Penicilina benzatina más doxiciclina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29396, 10949, '2. Cefixima + doxiciclina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29397, 10949, '3. Espectinomicina + clindamicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29398, 10949, '4. Ceftriaxona + metronidazol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29399, 10950, '1. En esta situación está indicado realizar citodiagnóstico de Tzanck y tratamiento con aciclovir 800 mg/12 horas durante 5 días de la paciente y de las parejas sexuales identificadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29400, 10950, '2. En esta situación está indicado realizar una serología (VDRL, FTA-ABS) y tratar con una monodosis intramuscular de 2,4 millones de UI de penicilina G benzatina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29401, 10950, '3. Sospechar una fiebre botonosa mediterránea y prescribir tratamiento con doxiciclina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29402, 10950, '4. Habrá que sospechar un lupus eritematoso sistémico con afectación cutánea e iniciar tratamiento con hidroxicloroquina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29403, 10951, '1. Infección por VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29404, 10951, '2. Sífilis secundaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29405, 10951, '3. Síndrome de Reiter.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29406, 10951, '4. Eritema multiforme.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29407, 10952, '1. Artritis reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29408, 10952, '2. Síndrome de Reiter.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29409, 10952, '3. Gota úrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29410, 10952, '4. Artritis gonocócica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29411, 10952, '5. Vasculitis de Cogan.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29412, 10953, '1. Candidiasis genital', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29413, 10953, '2. Chancroide', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29414, 10953, '3. Sífilis secundaria', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29415, 10953, '4. Balanitis por Tricomonas', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29416, 10953, '5. Infección fúngica por dermatofitos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29417, 10954, '1. En los casos sin manifestaciones sistémicas de la enfermedad es suficiente con tratamiento tópico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29418, 10954, '2. Para el diagnóstico es necesaria la práctica de una serología.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29419, 10954, '3. Si se precisa tratamiento antibiótico, se recomienda azitromicina 500 mg. en una dosis inicial y 250 mg cada 24 horas durante 4 días más.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29420, 10954, '4. La mayoría de los casos curan de forma espontánea en semanas o meses sin tratamiento de ningún tipo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29421, 10955, '1. El tratamiento de elección es permetrina tópica al 5 % desde la línea mandibular hasta los dedos de los pies, dejando actuar entre 8 y 14 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29422, 10955, '2. Es preciso lavar la ropa usada en las 48 horas previas y otras ropas del hogar al menos a 50 grados, lavado en seco o en su defecto poner la ropa en bolsas de plástico durante 15 días, para eliminar el parásito correctamente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29423, 10955, '3. La medida del efecto terapéutico del tratamiento es a través de la desaparición del picor en las primeras 48 horas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29424, 10955, '4. En caso de fracaso del tratamiento tópico o sarna nodular, el tratamiento de elección en nuestro entorno es la ivermectina oral en dosis única.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29425, 10956, '1. Es una infestación cutánea muy contagiosa causada por el Sarcoptes scabiei.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29426, 10956, '2. Se trata de una erupción polimorfa en la que confluyen lesiones producidas por el propio ácaro que se localizan en los pliegues interdigitales y las muñecas, y en menor medida en las axilas, en las mamas y en el pene.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29427, 10956, '3. En los casos muy persistentes del adulto las lesiones suelen generalizarse por el tronco y la cara.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29428, 10956, '4. El análisis mediante dermatoscopia del final del trayecto de un surco puede poner en evidencia el ácaro, que se ve en forma de ala delta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29429, 10957, '1. Isotretinoina oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29430, 10957, '2. Antimoniato de meglumina intralesional.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29431, 10957, '3. Corticoesteroides sistémicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29432, 10957, '4. Amoxicilina oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29433, 10958, '1. Ixodes ricinus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29434, 10958, '2. Rhipicephalus sanguineus.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29435, 10958, '3. Aedes aegypti.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29436, 10958, '4. Pediculosis corporis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29437, 10958, '5. Dermacentor variabilis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29438, 10959, '1. Sarampión.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29439, 10959, '2. Rubeola.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29440, 10959, '3. Varicela.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29441, 10959, '4. Escarlatina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29442, 10960, '1. Si presenta más de tres episodios anuales está indicado realizar profilaxis con un antiviral como valaciclovir 500 mg cada 12 horas o 1 g al día, durante seis meses.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29443, 10960, '2. Si es una única lesión y es un cuadro leve puede no realizarse ningún tratamiento o bien realizar tratamiento tópico con fomentos de sulfato de zinc o de cobre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29444, 10960, '3. Si existe riesgo de afectación oftálmica estaría indicado tratar con un antivírico como valaciclovir a razón de 1 g cada 8 horas durante 7 días vía oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29445, 10960, '4. Es necesario recomendarle una adecuada protección solar pues la exposición solar puede motivar recurrencias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29446, 10961, '1. Enfermedad de Kawasaki.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29447, 10961, '2. Escarlatina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29448, 10961, '3. Rubeola.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29449, 10961, '4. Sarampión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29450, 10962, '1. Deja de ser contagioso a las 24 horas de inicio del tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29451, 10962, '2. Deben tratarse los síntomas con analgésicos además del tratamiento del herpes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29452, 10962, '3. En casos con muy pocas lesiones, su efectividad es similar al tratamiento tópico con antivíricos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29453, 10962, '4. Sólo está indicado en pacientes inmunodeprimidos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29454, 10963, '1. Eritema infeccioso o quinta enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29455, 10963, '2. Sarampión o primera enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29456, 10963, '3. Roséola, exantema súbito o sexta enfermedad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29457, 10963, '4. Escarlatina o segunda enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29458, 10964, '1. Meningitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29459, 10964, '2. Genital.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29460, 10964, '3. Neumonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29461, 10964, '4. Gingivoestomatitis y faringitis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29462, 10965, '1. Enfermedad de Kawasaki.', true, 1);
