INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29466, 10966, '1. Presencia de vesículas en el conducto auditivo externo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29467, 10966, '2. Afectación multimetamérica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29468, 10966, '3. Afectación del ala nasal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29469, 10966, '4. Lesiones cutáneas en distintas fases evolutivas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29470, 10967, '1. Varicela.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29471, 10967, '2. Rubeola.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29472, 10967, '3. Eritema infeccioso o 5ª enfermedad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29473, 10967, '4. Exantema súbito o 6ª enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29474, 10968, '1. Infección diseminada por CMV.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29475, 10968, '2. Herpes zoster.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29476, 10968, '3. Síndrome de Sweet.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29477, 10968, '4. Toxicidad cutánea por bleomicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29478, 10969, '1. Arboviridae.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29479, 10969, '2. Virus del papiloma humano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29480, 10969, '3. Poxvirus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29481, 10969, '4. Coxsackie.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29482, 10970, '1. El tratamiento con amorolfina tópica al 5 % dos veces por semana por un periodo de 3 meses suele ser efectivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29483, 10970, '2. Si la lesión afectara la matriz ungueal el tratamiento debe prolongarse hasta los 6-9 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29484, 10970, '3. El tratamiento oral de elección en este caso es la griseofulvina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29485, 10970, '4. En casos de resistencia una opción es el tratamiento con itraconazol oral 200 mg cada 24 horas durante 12 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29486, 10971, '1. Dermatofitosis por Microsporum gypseum.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29487, 10971, '2. Infección cutánea por Staphylococcus aureus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29488, 10971, '3. Esporotricosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29489, 10971, '4. Infección cutánea por Mycobacterium marinum.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29490, 10972, '1. Candidiasis genital', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29491, 10972, '2. Chancroide', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29492, 10972, '3. Sífilis secundaria', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29493, 10972, '4. Balanitis por Tricomonas', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29494, 10972, '5. Infección fúngica por dermatofitos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29568, 10990, '3. La lesión sugiere una forma palmo-plantar de psoriasis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29495, 10973, '1. Tienen 3 fases evolutivas: una fase proliferativa en la que la lesión crece aceleradamente, un periodo de estabilidad y una fase involutiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29496, 10973, '2. Suponen la única lesión positiva para el marcador GLUT-1 (proteína transportadora de glucosa).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29497, 10973, '3. Es necesario realizar estudios de imagen (la ecografía sería la técnica de elección) por el riesgo aumentado de hemangiomas a nivel visceral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29498, 10973, '4. La mayoría de los hemangiomas infantiles tiene un curso clínico predecible por lo que, si no hay compromiso funcional ni estético, una opción válida es no tratar a estos pacientes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29499, 10974, '1. Dermatitis seborreica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29500, 10974, '2. Queratosis actínica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29501, 10974, '3. Liquen nitidus.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29502, 10974, '4. Psoriasis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29503, 10975, '1. Carcinoma basocelular ulcerado.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29504, 10975, '2. Blefaritis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29505, 10975, '3. Orzuelo externo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29506, 10975, '4. Dermatitis eccematosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29507, 10976, '1. Queratoacantoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29508, 10976, '2. Carcinoma basocelular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29509, 10976, '3. Queratosis actínica hipertrófica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29510, 10976, '4. Herpes simple crónico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29511, 10977, '1. Tumor de células de Merkel.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29512, 10977, '2. Carcinoma basocelular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29513, 10977, '3. Carcinoma escamoso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29514, 10977, '4. Melanoma maligno amelanótico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29515, 10977, '5. Linfoma cutáneo de células B.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29516, 10978, '1. Curación muy probable con moderada posibilidad de recidiva local y muy remota posibilidad de metástasis a distancia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29517, 10978, '2. Recidiva local con una probabilidad aproximada del 50%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29518, 10978, '3. Probabilidad de metástasis ganglionares superior al 50%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29519, 10978, '4. Probabilidad de metástasis a distancia superior al 30%.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29520, 10978, '5. En este caso no debe plantearse el tratamiento quirúrgico como única opción terapéutica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29521, 10979, '1. El tipo histológico más frecuente es el carcinoma basocelular y su tratamiento primario es habitualmente radioterápico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29522, 10979, '2. Se relaciona con factores etiopatogénicos como la irradiación solar y el virus del papiloma humano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29523, 10979, '3. Rara vez provoca metástasis por vía linfática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29524, 10979, '4. El tipo histológico más frecuente es el carcinoma epidermoide y su tratamiento quirúrgico asocia habitualmente disección ganglionar cervical.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29525, 10980, '1. Carcinoma de células escamosas cutáneo invasivo', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29526, 10980, '2. Carcinoma basocelular esclerodermiforme', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29527, 10980, '3. Sarcoma de Kaposi', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29528, 10980, '4. Lupus vulgar', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29529, 10981, '1. Botón de Oriente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29530, 10981, '2. Metástasis en tránsito de melanoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29531, 10981, '3. Queratoacantoma.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29532, 10981, '4. Carcinoma basocelular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29533, 10982, '1. Ingreso hospitalario y tratamiento antibiótico endovenoso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29534, 10982, '2. Biopsia de la zona mamelonada.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29535, 10982, '3. Realizar curas con pomadas enzimáticas desbridantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29536, 10982, '4. Cobertura de la úlcera con injerto de piel.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29537, 10983, '1. Azatioprina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29538, 10983, '2. Infliximab.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29539, 10983, '3. Vedolizumab.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29540, 10983, '4. Ustekinumab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29541, 10984, '1. PD-1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29542, 10984, '2. PD-L1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29543, 10984, '3. CTLA-4.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29544, 10984, '4. HER2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29545, 10985, '1. Biopsia mediante punción de la parte más pigmentada de la lesión para confirmar el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29546, 10985, '2. Biopsia mediante escisión completa con márgenes quirúrgicos de 2 mm y estudio histopatológico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29547, 10985, '3. Monitorización de la lesión con dermatoscopia digital y seguimiento en 3 meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29548, 10985, '4. Terapia fotodinámica para reducir el tamaño de la lesión antes de realizar una biopsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29549, 10986, '1. Realizar una cirugía con ampliación de márgenes de 1 cm.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29550, 10986, '2. Realizar una cirugía con ampliación de márgenes de 1 cm y biopsia de ganglio centinela.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29551, 10986, '3. Dado que es un segundo melanoma requiere tratamiento con la terapia dirigida dabrafenib + trametinib.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29552, 10986, '4. Dado que tiene múltiples tipos de cáncer cutáneo se podría beneficiar de un tratamiento con inmunoterapia, como nivolumab o pembrolizumab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29553, 10987, '1. Diámetro mayor de la lesión, en milímetros.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29554, 10987, '2. Máximo espesor de la lesión, en milímetros (índice de Breslow).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29555, 10987, '3. Presencia de ulceración en la lesión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29556, 10987, '4. Mitosis por milímetro cuadrado (índice mitótico).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29557, 10988, '1. Realizar un PET/TC para investigar si existen metástasis viscerales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29558, 10988, '2. Realizar ampliación de márgenes quirúrgicos a 1 cm y biopsia selectiva de ganglio centinela.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29559, 10988, '3. Realizar ampliación de márgenes quirúrgicos a 1 cm y linfadenectomía axilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29560, 10988, '4. Sólo es necesario realizar ampliación de márgenes quirúrgicos a 2 cm y después seguimiento periódico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29561, 10989, '1. Nivel sérico de LDH', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29562, 10989, '2. Espesor tumoral medido en el índice de Breslow.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29563, 10989, '3. La presencia de ulceración clínica o histológica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29564, 10989, '4. Número de metástasis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29565, 10989, '5. El índice mitótico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29566, 10990, '1. Buscaría factores de inmunodepresión, pues la lesión parece corresponder a una sarna noruega.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29567, 10990, '2. La lesión cutánea parece una callosidad en una zona de apoyo fisiológico, por lo que de momento, no la consideraría relacionada con la pérdida del estado general.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29705, 11023, '2. Esofagitis péptica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29569, 10990, '4. Parece una forma de queratosis seborreica difusa asociada a la edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29570, 10990, '5. Sugiere una queratodermia plantar paraneoplásica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29571, 10991, '1. Un aspirado de médula ósea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29572, 10991, '2. Un estudio inmunológico completo con ANA, ANCA y complemento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29573, 10991, '3. No haría más pruebas inmediatamente y seguiría la evolución clínica durante un mes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29574, 10991, '4. Una fibrogastroscopia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29575, 10991, '5. Una biopsia de la lesión plantar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29576, 10992, '1. Con frecuencia presentan crisis epilépticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29577, 10992, '2. Suelen presentar angiofibromas faciales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29578, 10992, '3. El tumor cerebral más frecuente es el astrocitoma gigantocelular subependimario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29579, 10992, '4. Con frecuencia presentan neurinomas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29580, 10993, '1. Linfoma de Hodgkin cutáneo', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29581, 10993, '2. Síndrome de Sezary', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29582, 10993, '3. Linfoma no Hodgkin cutáneo tipo T', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29583, 10993, '4. Psoriasis pustuloso', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29584, 10994, '1. Quiste renal / poliquistosis renal autosómica dominante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29585, 10994, '2. Carcinoma renal de células claras / enfermedad de Von Hippel Lindau.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29586, 10994, '3. Angiomiolipoma renal / esclerosis tuberosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29587, 10994, '4. Neurofibroma / neurofibromatosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29588, 10995, '1. Liquen plano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29589, 10995, '2. Xantoma tuberoso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29590, 10995, '3. Sarcoidosis cutánea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29591, 10995, '4. Granuloma anular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29592, 10996, '1. Mastocitoma, observación, ya que probablemente involucione', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29593, 10996, '2. Nevus sebáceo, extirpación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29594, 10996, '3. Angiofibroma, exploración de superficie corporal completa y estudio genético.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29595, 10996, '4. Nevus melanocítico congé-nito, seguimiento y control fotográfico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29596, 10997, '1. Enfermedad de Fabry.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29597, 10997, '2. Enfermedad de Pompe.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29598, 10997, '3. Polineuropatía amiloidótica hereditaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29599, 10997, '4. Enfermedad de Gaucher.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29600, 10998, '1. Enviar al hospital para vacunar de rabia y tétanos y mantener en observación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29601, 10998, '2. Limpiar la herida y administrar gammaglobulina inespecífica intramuscular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29602, 10998, '3. Dar 400 mg de moxifloxacino oral y enviar al hospital.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29603, 10998, '4. Dar clindamicina 600 mg oral cada 8 horas y observación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29604, 10999, '1. Síndrome de Sturge-Weber.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29605, 10999, '2. Neurofibromatosis tipo 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29606, 10999, '3. Neurofibromatosis tipo 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29607, 10999, '4. Esclerosis tuberosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29608, 11000, '1. Endoscopia digestiva: adenocarcinoma gástrico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29609, 11000, '2. TC abdominal: cáncer de páncreas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29610, 11000, '3. TC torácico: sarcoidosis ganglionar (síndrome de Löfgren).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29611, 11000, '4. Cultivo de los nódulos cutáneos: tuberculosis cutánea (lupus vulgar).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29612, 11001, '1. Todos los datos del paciente son compatibles con un exceso de glucocorticoides. Descartaría por interrogatorio el aporte externo (oral, en cremas) y, además de una analítica estándar que incluya estudio de lípidos y de glucemia, solicitaría varias determinaciones de cortisol libre en orina y una determinación de cortisol plasmático a primera hora de la mañana, tras administrar dexametasona oral la noche anterior.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29613, 11001, '2. Las estrías cutáneas se pueden justificar por un posible adelgazamiento previo. Lo más probable es que el paciente presente un síndrome metabólico (obesidad, hipertensión, sedentarismo…). Proseguiría investigando este aspecto (glicemia, lípidos, confirmación de la TA, etc.). La posible depresión podría ser reactiva al hecho de no encontrar trabajo y de momento me mantendría a la expectativa en este aspecto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29614, 11001, '3. Las estrías cutáneas son relativamente inespecíficas en un paciente obeso y la TA elevada en una única determinación no permite sacar ninguna conclusión. Aparte de solicitar una analítica general y proseguir el estudio de una eventual HTA, priorizaría los aspectos depresivos de la conducta del paciente y lo remitiría para una evaluación psiquiátrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29615, 11001, '4. Pensaría en la posibilidad de que el paciente tenga una hepatopatía crónica con hipertensión portal y ascitis. Aunque no admite una ingesta elevada de alcohol, hay otras causas (víricas, etc.) que deberán investigarse. La HTA en una primera visita podría no ser significativa y, de momento, el supuesto cuadro depresivo lo dejaría en segundo término. Pondría en marcha un estudio de hepatopatía crónica con estudios, en esta primera fase, bioquímicos y de imagen.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29616, 11002, '1. Anemia por células falciformes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29617, 11002, '2. Anemia hemolítica autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29618, 11002, '3. Anemia por enfermedad crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29619, 11002, '4. Anemia por déficit de hierro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29620, 11003, '1. Dada la extensión el tratamiento consistirá en curas diarias con sulfadiazina argéntica en su Centro de Salud y revisión por el especialista en Cirugía Plástica en 48 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29621, 11003, '2. El paciente debe ser trasladado urgentemente, en ambulancia medicalizada, a un Centro de grandes quemados, tras su estabilización previa en urgencias.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29622, 11003, '3. El paciente debe ser dejado en observación durante 8 horas y al cabo de las cuales si no empeora se procederá al alta con curas locales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29623, 11003, '4. Se procederá al desbridamiento del primer dedo del pie lesionado, apertura del túnel del carpo de mano derecha, cura con sulfadiazina argéntica e ingreso en planta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29624, 11004, '1. Dieta absoluta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29625, 11004, '2. Administración de ringer lactato según la fórmula de Parkland.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29626, 11004, '3. Administración profiláctica de antibióticos vía intravenosa.', true, 3);
