INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29636, 11006, '4. Esofagograma con bario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29637, 11007, '1. Es un divertículo por tracción y consta de todas las capas de la pared esofágica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29638, 11007, '2. Es menos frecuente que los divertículos del tercio medio del esófago en la actualidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29639, 11007, '3. No se trata con miotomía del cricofaríngeo si el tamaño es igual o menor a 2 cm.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29640, 11007, '4. Cuando se interviene mediante abordaje abierto para practicar una diverticulectomía o una divertículopexia, la incisión se realiza en el lado izquierdo del cuello.', true, 4);
