INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29651, 11010, '3. Espasmo esofágico difuso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29652, 11010, '4. Retención alimentaria por tumor submucoso (leiomioma) obstructivo en tercio distal esofágico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29653, 11011, '1. Espasmo esofágico distal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29654, 11011, '2. Esófago hipercontráctil.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29655, 11011, '3. Acalasia tipo I.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29656, 11011, '4. Peristalsis fragmentada.', false, 4);
