INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29658, 11012, '2. Ondas peristálticas en cuerpo esofágico y esfínter esofágico superior hipotenso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29659, 11012, '3. Aperistalsis de cuerpo esofágico y esfínter esofágico inferior hipertenso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29660, 11012, '4. Esfínter esofágico inferior hipotenso con relajaciones completas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29661, 11013, '1. Medidas higiénicas (comer despacio y dieta blanda) y en los episodios descritos la toma de anticolinérgicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29662, 11013, '2. Nitroglicerina sublingual antes de las comidas y a demanda en caso de dolor torácico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29663, 11013, '3. Miotomía laparoscópica del esfínter esofágico inferior.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29664, 11013, '4. Dilatación neumática endoscópica del esfínter esofágico inferior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29665, 11013, '5. Inyección endoscópica de toxina botulínica en el esfínter esofágico inferior.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29666, 11014, '1. Se trata de un divertículo por tracción.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29667, 11014, '2. Suele diagnosticarse en pacientes jóvenes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29668, 11014, '3. El tratamiento incluye la miotomía del músculo cricofaringeo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29669, 11014, '4. La pirosis es su síntoma principal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29670, 11014, '5. Se localiza siempre en la cara anterior de la hipofaringe.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29671, 11015, '1. Estenosis esofágica péptica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29672, 11015, '2. Hernia hiatal con reflujo gastroesofágico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29673, 11015, '3. Membrana esofágica asociada a ferropenia (síndrome de Plummer-Vinson).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29674, 11015, '4. Cáncer de esófago.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29675, 11015, '5. Acalasia esofágica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29676, 11016, '1. Huevo y trigo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29677, 11016, '2. Leche de vaca y pescado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29678, 11016, '3. Legumbres y leche de vaca.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29679, 11016, '4. Leche de vaca y trigo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29680, 11017, '1. El diagnóstico de certeza se realiza mediante endoscopia digestiva alta y biopsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29681, 11017, '2. El tratamiento inicial es recomendar dieta de eliminación de aquellos alimentos en los que se demuestran reacciones positivas in vivo o in vitro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29682, 11017, '3. La inflamación subyacente indica un mecanismo patogénico de hipersensibilidad Th1.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29683, 11017, '4. La inmunoterapia específica frente a los alérgenos respiratorios y alimentarios a los que se ha demostrado sensibilización es una práctica habitual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29684, 11018, '1. Esófago de Barrett.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29685, 11018, '2. Esofagitis eosinofílica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29686, 11018, '3. Enfermedad por reflujo gastro-esofágico no erosiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29687, 11018, '4. Esofagitis grado B de Los Ángeles.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29688, 11019, '1. Esofagitis por reflujo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29689, 11019, '2. Esófago de Barrett.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29690, 11019, '3. Esofagitis eosinofílica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29691, 11019, '4. Esofagitis por Candida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29692, 11020, '1. Aunque no existen datos de inmunosupresión, no puede descartarse la etiología herpética', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29693, 11020, '2. La etiología más probable es farmacológica, dado su tratamiento actual con simvastatina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29694, 11020, '3. La infección por citomegalovirus es la causa más frecuente de estas lesiones en personas inmunocompetentes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29695, 11020, '4. La presencia de células gigantes y de cuerpos de inclusión eosinofílicos en el estudio histopatológico de las biopsias, confirmarían la etiología candidiásica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29696, 11021, '1. La imagen corresponde a la tráquea, el endoscopista ha entrado a la vía respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29697, 11021, '2. La sospecha diagnóstica debería confirmarse con histología tomando biopsias de esófago distal y proximal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29698, 11021, '3. Si el paciente refiere dolor torácico la imagen es diagnóstica de espasmo esofágico difuso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29699, 11021, '4. La imagen corresponde a una acalasia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29700, 11022, '1. Epitelio plano papilomatoso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29701, 11022, '2. Epitelio columnar especializado con células caliciformes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29702, 11022, '3. Infiltrado inflamatorio mononuclear.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29703, 11022, '4. Acantosis glucogénica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29704, 11023, '1. Esófago de Barrett.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29706, 11023, '3. Esofagitis eosinofílica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29707, 11023, '4. Enfermedad de Mallory-Weiss.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29708, 11024, '1. Esófago de Barrett.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29709, 11024, '2. Anillo esofágico distal (Schaztki).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29710, 11024, '3. Esofagitis infecciosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29711, 11024, '4. Esofagitis eosinofílica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29712, 11025, '1. La intensidad y frecuencia de pirosis tiene poca relación con la presencia y gravedad de esofagitis endoscópica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29713, 11025, '2. La mayoría de los pacientes con enfermedad por reflujo gastroesofágico presentan esofagitis en la endoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29714, 11025, '3. El tratamiento con inhibidores de la bomba 8 de protones suele conseguir un buen control de los síntomas, pero no es superior a placebo en la curación endoscópica de la esofagitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29715, 11025, '4. El esófago de Barrett puede progresar a displasia epitelial de bajo grado, displasia epitelial de alto grado y finalmente a carcinoma escamoso de esófago.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29716, 11025, '5. Los programas endoscópicos de cribado y vigilancia han demostrado de forma inequívoca ser capaces de reducir la mortalidad en pacientes con esófago de Barrett.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29717, 11026, '1. Esofagitis herpética.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29718, 11026, '2. Esofagitis eosinofílica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29719, 11026, '3. Esofagitis candidiásica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29720, 11026, '4. Esofagitis por citomegalovirus.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29721, 11026, '5. Adenocarcinoma de esófago.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29722, 11027, '1. Neutralizan el ácido clorhídrico de la secreción gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29723, 11027, '2. Tiñen las heces de color negro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29724, 11027, '3. Bloquean el receptor histaminérgico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29725, 11027, '4. Bloquean el receptor de la gastrina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29726, 11027, '5. Requieren cubierta entérica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29727, 11028, '1. Esófago de Barret.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29728, 11028, '2. Pólipos adenomatosos de colon.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29729, 11028, '3. Hernia hiatal en pacientes con reflujo clínico sintomático.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29730, 11028, '4. Familiares de primer grado con cáncer de colon.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29731, 11028, '5. Pancolitis ulcerosa de más de 10 años de evolución.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29732, 11029, '1. Adenoma de colon.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29733, 11029, '2. Esofagitis cáustica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29734, 11029, '3. Ulcera gástrica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29735, 11029, '4. Anemia Perniciosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29736, 11029, '5. Esófago de Barrett.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29737, 11030, '1. Sinusitis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29738, 11030, '2. Erosión dental por reflujo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29739, 11030, '3. Asma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29740, 11030, '4. Laringitis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29741, 11030, '5. Tos crónica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29742, 11031, '1. Dado que la esofagitis es leve y la displasia de bajo grado se aconseja continuar tratamiento con alcalinos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29743, 11031, '2. Tratamiento indefinido con dosis altas de inhibidores de la bomba de protones ya que se ha demostrado que así se evita la progresión del esófago de Barrett a adenocarcinoma haciendo innecesaria la vigilancia endoscópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29744, 11031, '3. Endoscopias de vigilancia periódicas y tratamiento con inhibidores de la bomba de protones durante menos de 12 semanas ya que tratamientos más prolongados se asocian a un alto riesgo de desarrollo de gastrinomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29745, 11031, '4. Endoscopias de vigilancia periódicas y tratamiento indefinido con inhibidores de la bomba de protones.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29746, 11031, '5. Esofaguectomía.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29747, 11032, '1. Su origen es adquirido como consecuencia del reflujo gastroesofágico crónico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29748, 11032, '2. Se estima que el 0.5% de los pacientes con esófago de Barret desarrollan anualmente un adenocarcinoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29749, 11032, '3. Para su diagnóstico es imprescindible la toma de biopsias cada 1-2 cms y en cada uno de los cuadrantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29750, 11032, '4. En la actualidad el mejor marcador de potencial malignidad sigue siendo la detección de displasia en la biopsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29751, 11032, '5. La cirugía anti-reflujo logra controlar el reflujo gastroesofágico y hace desaparecer completamente la metaplasia columnar.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29752, 11033, '1. Paciente de 80 años con hernia hiatal de mediano tamaño y pirosis frecuente que responde bien a 20 mg/día de omeprazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29753, 11033, '2. Paciente de 56 años con molestias epigástricas tipo flatulencia y pirosis intermitente que responde sólo ligeramente al tratamiento con omeprazol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29754, 11033, '3. Paciente de 27 años con síndrome depresivo y molestias retroesternales que no alivian en absoluto con el tratamiento con inhibidores de la bomba de protones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29755, 11033, '4. Paciente de 58 años con pirosis diaria diurna y nocturna de más de 10 años de evolución y que permanece asintomático en los períodos que es tratado con dosis de omeprazol de 40 mg/día o superiores y cuyos síntomas recidivan inmediatamente al reducir esta dosis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29756, 11033, '5. Paciente de 66 años de edad con esofagitis erosiva y antecedentes de infarto de miocardio hace 1 año con insuficiencia cardiaca residual.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29757, 11034, '1. Misoprostol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29758, 11034, '2. Cimetidina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29759, 11034, '3. Pirenzepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29760, 11034, '4. Bismuto coloidal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29761, 11034, '5. Omeprazol.', true, 5);
