INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29764, 11035, '3. TC de abdomen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29765, 11035, '4. Estudio isotópico de vaciamiento gástrico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29766, 11036, '1. Pérdidas hemáticas en relación con el tratamiento esteroideo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29767, 11036, '2. Hipoplasia medular secundaria a colchicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29768, 11036, '3. Hemólisis secundaria a la toma de metimazol', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29769, 11036, '4. Gastritis tipo A', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29770, 11037, '1. Neoplasia endocrina múltiple tipo 1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29771, 11037, '2. Síndrome de McCune-Albright.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29772, 11037, '3. Complejo de Carney.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29773, 11037, '4. Síndrome poliglandular autoinmune tipo I.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29774, 11038, '1. Test de la ureasa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29775, 11038, '2. Determinación de pepsinógenos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29776, 11038, '3. Estimulación con pentagastrina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29777, 11038, '4. Prueba de la comida ficticia.', false, 4);
