INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29779, 11039, '2. Metaplasia intestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29780, 11039, '3. Hiperplasia de células endocrinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29781, 11039, '4. Atrofia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29782, 11040, '1. Es un término que debe reservarse para la definir la existencia de inflamación histológica en la mucosa gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29783, 11040, '2. Existe un espectro de manifestaciones clínicas claramente definidas en relación con la existencia de gastritis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29784, 11040, '3. El Helicobacter pylori es una causa frecuente de gastritis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29785, 11040, '4. Existe una escasa correlación entre los datos histológicos, los síntomas del paciente y los datos endoscópicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29786, 11041, '1. Realizar un hemograma y determinación de B12 ante la sospecha de una mielosis funicular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29787, 11041, '2. Realizar una RM buscando una atrofia de vermis y de folias cerebelosas ante la alta sospecha de degeneración cerebelosa alcohólica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29788, 11041, '3. Se debería administrar de inicio 100 mg de tiamina intravenosa por la sospecha de una encefalopatía de Wernicke-Korsakoff.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29789, 11041, '4. Lo primero a realizar sería una determinación de natremia para descartar una mielinolisis central pontina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29790, 11041, '5. Realizar un estudio electromiográfico ante la alta sospecha de una esclerosis lateral primaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29791, 11042, '1. Una neoplasia endocrina múltiple tipo 1 o Síndrome de Wermer.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29792, 11042, '2. Una neoplasia endocrina múltiple tipo 2 A o Síndrome de Sipple.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29793, 11042, '3. Una neoplasia endocrina múltiple tipo 2B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29794, 11042, '4. Somatostatinoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29795, 11042, '5. Un tumor neuroendocrino productor de PTH.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29796, 11043, '1. Predomina en el antro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29797, 11043, '2. Es más frecuente que la B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29798, 11043, '3. Está causada por H. pylori.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29799, 11043, '4. Cursa con aclorhidria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29800, 11043, '5. En el 50% hay antirreceptor anticélulas parietales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29801, 11044, '1. Valoración de Helicobacter Pylori.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29802, 11044, '2. Ecoendoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29803, 11044, '3. Determinación de la vitamina B12.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29804, 11044, '4. Estudio histológico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29805, 11044, '5. Estudios radiológicos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29806, 11045, '1. Estudio de vaciamiento gástrico de sólidos con isótopos radiactivos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29807, 11045, '2. Manometría gástrica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29808, 11045, '3. Gastroscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29809, 11045, '4. Electrogastrografía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29810, 11045, '5. Rx con contraste baritado (tránsito gastrointestinal).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29811, 11046, '1. Tumores hipofisarios, hiperparatiroidismo y síndrome de Zollinger-Ellison.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29812, 11046, '2. Hiperparatiroidismo, feocromocitoma y carcinoma medular de tiroides.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29813, 11046, '3. Hiperparatiroidismo, cáncer microcítico de pulmón y tumor carcinoide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29814, 11046, '4. Insulinoma, tumor de células claras renal y hepatocarcinoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29815, 11046, '5. Carcinoma medular de tiroides, insulinoma y glioblastoma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29816, 11047, '1. Carcinoma medular de tiroides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29817, 11047, '2. Tumor endocrino del páncreas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29818, 11047, '3. Hiperparatiroidismo Primario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29819, 11047, '4. Feocromocitoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29820, 11047, '5. Adenoma hipofisario.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29821, 11048, '1. Naproxeno.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29822, 11048, '2. Celecoxib.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29823, 11048, '3. Ketorolaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29824, 11048, '4. Ibuprofeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29825, 11049, '1. Gastrinoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29826, 11049, '2. Síndrome de antro retenido.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29827, 11049, '3. Síndrome de asa aferente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29828, 11049, '4. Carcinoma de muñón gástrico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29829, 11050, '1. Tratamiento erradicador del Helicobacter pylorii.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29830, 11050, '2. Tratamiento con inhibidores de la bomba de protones y una gastroscopia de control con biopsia a las 8 semanas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29831, 11050, '3. Suspender corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29832, 11050, '4. Tratamiento quirúrgico (Billrroth I).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29833, 11051, '1. En la endoscopia inicial está indicado aplicar una terapéutica endoscópica y posteriormente instaurar tratamiento endovenoso con dosis altas de un inhibidor de la bomba de protones. Esta estrategia ha demostrado reducir el riesgo de recidiva hemorrágica y la mortalidad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29834, 11051, '2. En la endoscopia inicial, dada la ausencia de sangrado activo, no está indicado aplicar una terapéutica endoscópica. Posteriormente, para reducir el riesgo de recidiva hemorrágica, se deberá instaurar tratamiento endovenoso con dosis altas de un inhibidor de la bomba de protones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29835, 11051, '3. En la endoscopia inicial está indicado aplicar una terapéutica endoscópica. No se ha podido demostrar que instaurar posteriormente tratamiento endovenoso con dosis altas de un inhibidor de la bomba de protones aporte beneficio adicional alguno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29836, 11051, '4. Dado que se trata de una úlcera complicada (hemorragia) la mejor opción terapéutica una vez resuelto el episodio hemorrágico, es una vagotomía y piloroplastia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29837, 11052, '1. Gastropatía por reflujo biliar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29838, 11052, '2. Adenocarcinoma gástrico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29839, 11052, '3. Síndrome de evacuación gástrica rápida (dumping).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29840, 11052, '4. Síndrome de asa aferente con sobrecrecimiento bacteriano.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29841, 11053, '1. Tan solo es preciso realizar trasfusión de concentrados de hematíes y vigilar la estabilidad hemodinámica del paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29842, 11053, '2. Los hallazgos endoscópicos sugieren una clasificación de Forrest III.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29843, 11053, '3. La colocación de bandas es el tratamiento endoscópico de elección ya que se trata de un paciente hepatópata.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29844, 11053, '4. Se necesita la realización de una endoscopia a las 12 h para vigilar la posibilidad de resangrado de manera sistemática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31769, 11474, '3. Ecotiofato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29845, 11053, '5. Es precisa la realización de tratamiento endoscópico con adrenalina 1:10000 asociada a la colocación de un endoclip.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29846, 11054, '1. No es preciso el tratamiento farmacológico ya que se ha identificado la lesión sangrante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29847, 11054, '2. El tratamiento ideal para este paciente es la perfusión de somatostatina ya que se trata de un paciente hepatópata.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29848, 11054, '3. La utilización de omeprazol a altas dosis reduce la recidiva de sangrado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29849, 11054, '4. La ranitidina es el fármaco de elección para evitar la toxicidad farmacológica al tratarse de un paciente con hepatopatía crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29850, 11054, '5. La erradicación del Helicobacter pylori es la primera medida a tomar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29851, 11055, '1. La lesión descrita tiene un riesgo bajo de recidiva hemorrágica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29852, 11055, '2. En caso de recidiva hemorrágica es imprescindible la intervención quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29853, 11055, '3. Por la localización de la lesión puede estar afectada la arteria gastroduodenal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29854, 11055, '4. La descripción y localización de la úlcera sugieren una lesión de Dieulafoy.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29855, 11055, '5. En caso de intervención quirúrgica es obligatoria la práctica de una vagotomía troncular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29856, 11056, '1. Aplicar tratamiento con un análogo de la somatostatina (octeótrido).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29857, 11056, '2. Seguir unas medidas dietéticas concretas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29858, 11056, '3. Realizar un tratamiento de prueba con una benzodiacepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29859, 11056, '4. Realizar la búsqueda de un probable tumor neuroendocrino (p.ej.: carcinoide).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29860, 11056, '5. Indicar tratamiento quirúrgico para efectuar una gastro-yeyunostomía antiperistáltica en Y de Roux.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29861, 11057, '1. Gran parte de las úlceras gastroduodenales se pueden atribuir a la infección por H. pylori o lesión mucosa por AINEs.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29862, 11057, '2. H. pylori no se relaciona con el desarrollo de linfoma gástrico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29863, 11057, '3. La transmisión de H. pylori se produce de persona a persona vía oral-oral o fecal-oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29864, 11057, '4. Un menor nivel educativo y un estatus socioeconómico bajo predisponen a mayores índices de colonización.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29865, 11057, '5. La incidencia a adenocarcinoma gástrico es mayor en pacientes portadores del H. pylori.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29866, 11058, '1. Se recomienda la erradicación de esta bacteria en personas con historia previa de enfermedad ulcerosa péptica, aunque se encuentren asintomáticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29867, 11058, '2. Es recomendable la realización de un amplio despistaje y tratamiento de esta infección en la población general para disminuir la incidencia de cáncer gástrico y de enfermedad ulcerosa péptica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29868, 11058, '3. Para comprobar la eliminación de la infección por H. pylori con la prueba del aliento con urea marcada tras el tratamiento se debe suprimir la toma de inhibidores de la bomba de protones al menos 2 semanas antes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29869, 11058, '4. Se recomienda la erradicación de esta bacteria en familiares de primer grado de pacientes con cáncer gástrico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29870, 11058, '5. En pacientes con úlcera gástrica se recomienda que la comprobación de la erradicación de esta bacteria se realice con endoscopia y toma de biopsias gástricas para asegurarse de la cicatrización ulcerosa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29871, 11059, '1. Adenoma de colon.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29872, 11059, '2. Esofagitis cáustica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29873, 11059, '3. Úlcera gástrica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29874, 11059, '4. Anemia Perniciosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29875, 11059, '5. Esófago de Barrett.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29876, 11060, '1. La transmisión es por vía oral-oral o fecal-oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29877, 11060, '2. Se asocia casi siempre a gastritis crónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29878, 11060, '3. Es un microorganismo microaerófilo gram-negativo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29879, 11060, '4. Está diseñado para vivir en el medio ácido del estómago.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29880, 11060, '5. El test de ureasa para el diagnóstico del H. pylori presenta una sensibilidad y especificidad inferior al 50%.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29881, 11061, '"1. Dado que el paciente es joven, sin enfermedades asociadas y la úlcera ha dejado de sangrar, puede ser dado de alta precozmente con tratamiento con un inhibidor de la bomba de protones y erradicación de H. pylori.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29882, 11061, '2. Retirar endoscopio, colocar sonda nasogástrica para aspiración continua e iniciar tratamiento con un inhibidor de la bomba de protones y con somatostatina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29883, 11061, '3. Tomar biopsia para la detección de H. pylori, retirar el endoscopio procurando no desprender el trombo plaquetar y continuar tratamiento farmacológico con administración intravenosa de inhibidor de la bomba de protones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29884, 11061, '4. Consulta al Servicio de Cirugía para considerar tratamiento quirúrgico urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29885, 11061, '5. Tratamiento endoscópico mediante inyección de adrenalina en la úlcera y colocación de ""clips"" (grapas metálicas), seguido de la administración intravenosa de inhibidor de la bomba de protones."', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29886, 11062, '1. En la endoscopia inicial está indicado aplicar una terapéutica endoscópica para disminuir el riesgo de recidiva hemorrágica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29887, 11062, '2. Dada la ausencia de malignidad en las biopsias iniciales y el aspecto endoscópico de la úlcera, se puede descartar de manera fiable el cáncer gástrico y es innecesario el seguimiento endoscópico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29888, 11062, '3. Sólo está indicado el tratamiento erradicador del Helicobacter pylori si se constata recidiva de la úlcera en ausencia de antiinflamatorios no esteroideos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29889, 11062, '4. Dado que se trata de una úlcera complicada (hemorragia) la mejor opción terapéutica es una vagotomía y piloroplastia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29890, 11062, '5. El paciente podría ser dado de alta hospitalaria de forma precoz.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29891, 11063, '1. Dieta rica en grasas animales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29892, 11063, '2. Rasgo genético con disminución de interleuquina 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29893, 11063, '3. Cepas de H. pylori cagA+.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29894, 11063, '4. Gastrectomía parcial de causa benigna reciente (menos de 5 años).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29895, 11063, '5. Hiperclorhidria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29896, 11064, '1. Tamaño de la úlcera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29897, 11064, '2. Base de la úlcera cubierta de fibrina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29898, 11064, '3. Base de la úlcera cubierta por un coágulo fijo, adherido que no se moviliza con el lavado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29899, 11064, '4. Localización de la úlcera en incisura angularis ó en cara posterior de bulbo duodenal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29900, 11064, '5. Sospecha endoscópica de malignidad de la úlcera.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29901, 11065, '1. Hipotensión y taquicardia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29902, 11065, '2. Disminución del hematocrito y hemoglobina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29903, 11065, '3. Pacientes que requieren transfusión para mantener la estabilidad hemodinámica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29904, 11065, '4. Lavado gástrico por sonda naso-gástrica con abundante sangre roja, que no se aclara tras lavados repetidos con abundante volumen.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29905, 11065, '5. Repetidos y frecuentes episodios de hematemesis con sangre roja y melenas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29906, 11066, '1. Tratamiento con inhibidores de la bomba de protones por vía oral y alta hospitalaria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29907, 11066, '2. Tratamiento erradicador de Helicobacter pylori de forma empírica y alta hospitalaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29908, 11066, '3. Tratamiento hemostático con sonda de calor de la erosión con hematina en su base y perfusión endovenosa de inhibidores de la bomba de protones durante tres días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29909, 11066, '4. Ayuno total y tratamiento con perfusión endovenosa de inhibidores de la bomba de protones durante 48 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29910, 11066, '5. Colocación endoscópica de un hemoclip en la lesión erosiva con signos de hemostasia reciente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29911, 11067, '1. Obstrucción gástrica por neoplasia antropilórica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29912, 11067, '2. Gastritis enfisematosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29913, 11067, '3. Gastroparesia diabética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29914, 11067, '4. Úlcera péptica con signos de perforación contenida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29915, 11068, '1. Los pólipos fibrovasculares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29916, 11068, '2. Los leiomiomas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29917, 11068, '3. Los papilomas escamosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29918, 11068, '4. Los hemangiomas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29919, 11069, '1. Esofaguectomía transhiatal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29920, 11069, '2. Esofaguectomía según la técnica de Ivor-Lewis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29921, 11069, '3. Quimioterapia más radioterapia preoperatoria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29922, 11069, '4. Quimioterapia neoadyuvante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29923, 11070, '1. Neurofibroma de la pared gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29924, 11070, '2. Tumor del estroma gastrointestinal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29925, 11070, '3. Leiomioma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29926, 11070, '4. Sarcoma granulocítico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29927, 11071, '1. La mayor parte de los casos cursan con hipo gastrinemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29928, 11071, '2. La metaplasia intestinal en el estómago es indicación de gastrectomía por la alta tasa de transformación a adenocarcinoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29929, 11071, '3. En el caso de indicar cirugía, la gastrectomía distal es la cirugía más indicada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29930, 11071, '4. Está indicado el tratamiento con análogos de la somatostatina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29931, 11072, '1. Quimioradioterapia neoadyuvante y posteriormente esofaguectomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29932, 11072, '2. Radioterapia como tratamiento definitivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29933, 11072, '3. Colocación de prótesis de tipo stent.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29934, 11072, '4. Esofaguectomía y plastia gástrica con anastomosis cervical.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29935, 11073, '1. Adenocarcinoma gástrico infiltrante y ulcerado a nivel de antro-píloro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29936, 11073, '2. Adenocarcinoma gástrico infiltrante subcardial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29937, 11073, '3. Tumor del estroma gastrointestinal a nivel de cuerpo gástrico-curvatura mayor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29938, 11073, '4. Linfoma MALT.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29939, 11073, '5. Esófago de Barrett con metaplasia intestinal y displasia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29940, 11074, '1. Se trata de tumores de origen epitelial, localizados sobre todo a nivel de la mucosa del tubo digestivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29941, 11074, '2. Es característico de estos tumores la mutación del gen c-kit, que codifica un receptor tirosina-cinasa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29942, 11074, '3. El tratamiento de los tumores localizados menores de 2 cms es fundamentalmente médico, con el empleo de Imatinib.', false, 3);
