INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29980, 11082, '1. El esófago tiene capa mucosa, capa muscular y capa serosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29981, 11082, '2. El esófago abdominal es más largo que el cervical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29982, 11082, '3. El diámetro máximo del esófago normal es de 5 cm.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29983, 11082, '4. El esófago torácico pasa por detrás del cayado aórtico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29984, 11082, '5. El epitelio esofágico normal es cilíndrico.', false, 5);
