INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29990, 11084, '1. Estadificación tumoral TNM.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29991, 11084, '2. Diagnóstico de coledocolitiasis.', false, 2);
