INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29993, 11084, '4. Punción y aspiración con aguja fina de masas y adenopatías en el mediastino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29994, 11084, '5. Diagnóstico de cáncer de recto.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29995, 11085, '1. Su etiología está relacionada con el consumo de alcohol y tabaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29996, 11085, '2. La incidencia del histotipo adenocarcinoma ha aumentado en estos últimos años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29997, 11085, '3. La disfagia progresiva es el síntoma más frecuente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29998, 11085, '4. Su pronóstico es muy malo, sólo un 5% de los pacientes con cáncer de esófago sobreviven los 5 años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (29999, 11085, '5. El carcinoma escamoso de esófago no se asocia a hipercalcemia.', true, 5);
