INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30004, 11087, '1. Realizar un tratamiento empírico con antibióticos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30005, 11087, '2. Solicitar una colonoscopia preferente.', false, 2);
