INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30009, 11088, '2. Enteropatía por AINEs.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30010, 11088, '3. Enteropatía asociada a olmesartán.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30011, 11088, '4. Síndrome de intestino irritable.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30012, 11089, '1. La presencia de sangre en heces y fiebre permiten establecer el diagnóstico de gastroenteritis bacteriana.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30013, 11089, '2. La diarrea osmótica suele autolimitarse después de un ayuno de 48 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30014, 11089, '3. La diarrea secretora se caracteriza por heces voluminosas y acuosas, con gradiente de la osmolaridad entre las heces y el plasma pequeño', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30015, 11089, '4. La diarrea motora por hiperperistaltismo suele interpretarse como una respuesta fisiológica del intestino frente a diversas agresiones (contenido extraño, comida en malas condiciones...).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30016, 11090, '1. Colitis ulcerosa cronificada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30017, 11090, '2. Colitis pseudomembranosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30018, 11090, '3. Colitis colágena.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30019, 11090, '4. Enfermedad de Crohn fibrosante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30020, 11091, '1. Cuando las heces penetran en la ampolla rectal se produce una relajación del esfínter anal interno de forma consciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30021, 11091, '2. Cuando las heces penetran en la ampolla rectal se produce una relajación del esfínter anal externo de forma inconsciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30022, 11091, '3. El esfínter anal externo lo controlan fibras nerviosas del nervio pudendo, parte del sistema nervioso somático, y por tanto bajo control consciente voluntario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30023, 11091, '4. Los movimientos propulsivos del colon en condiciones normales necesitan una hora para desplazar el quimo a través de todo el colon desde la válvula ileocal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30024, 11091, '5. Durante la defecación se produce la contracción del suelo de la pelvis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30025, 11092, '1. Pérdida de peso con o sin rectorragia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30026, 11092, '2. Persistencia de la diarrea durante la noche.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30027, 11092, '3. Inicio de los síntomas después de los 50 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30028, 11092, '4. Presencia durante la exploración de dermatitis y/o artritis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30029, 11092, '5. Expulsión de moco en más del 25% de las defecaciones.', true, 5);
