INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30054, 11098, '5. Productos de charcutería, embutidos, patés.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30055, 11099, '1. Linfoma intestinal: infiltración de la lámina propia y del epitelio superficial por una población celular linfoide monótona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31770, 11474, '4. Pralidoxima.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30056, 11099, '2. Enteropatía sensible al gluten (celiaquía): atrofia de vellosidades intestinales, aumento del infiltrado inflamatorio y linfocitosis intraepitelial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30057, 11099, '3. Linfangiectasias: dilatación de vasos linfáticos situados en la lámina propia de la mucosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30058, 11099, '4. Enfermedad de Whipple: acúmulos de macrófagos de citoplasma amplio y microvacuolado en la lámina propia de la mucosa.', false, 4);
