INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30076, 11103, '2. Colonoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30077, 11103, '3. Serología para virus de la hepatitis B y C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30078, 11103, '4. Biopsia intestinal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30079, 11103, '5. Ecografía abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30080, 11104, '1. La biopsia intestinal es la prueba diagnóstica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30081, 11104, '2. Presencia de anemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30082, 11104, '3. Déficit de vitaminas liposolubles.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30083, 11104, '4. Antecedentes de cirugía gastrointestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30084, 11104, '5. Presencia de diarrea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30085, 11105, '1. Diarrea postprandial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30086, 11105, '2. Deposiciones de olor ácido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30087, 11105, '3. Eritema perianal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30088, 11105, '4. Deposiciones explosivas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30089, 11105, '5. Heces abundantes, brillantes y adherentes (esteatorreicas).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30090, 11106, '1. Observación y seguimiento periódico con endoscopia digestiva alta debido a la localización del tumor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30091, 11106, '2. Quimioterapia neoadyuvante seguida de una nueva evaluación para posible resección quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30092, 11106, '3. Duodenopancreatectomía cefálica (procedimiento de Whipple) como tratamiento de elección.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30093, 11106, '4. Radioterapia dirigida al duodeno para controlar la enfermedad local antes de considerar la cirugía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30094, 11107, '1. TC toraco-abdomino-pélvico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30095, 11107, '2. Resonancia magnética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30096, 11107, '3. Gammagrafía con octreótido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30097, 11107, '4. Tomografía de emisión de positrones (PET).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30098, 11108, '1. Gran parte de las úlceras gastroduodenales se pueden atribuir a la infección por H. pylori o lesión mucosa por AINEs.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30099, 11108, '2. H. pylori no se relaciona con el desarrollo de linfoma gástrico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30100, 11108, '3. La transmisión de H. pylori se produce de persona a persona vía oral-oral o fecal-oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30101, 11108, '4. Un menor nivel educativo y un estatus socioeconómico bajo predisponen a mayores índices de colonización.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30102, 11108, '5. La incidencia a adenocarcinoma gástrico es mayor en pacientes portadores del H. pylori.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30103, 11109, '1. Se presentan frecuentemente con grandes masas adenopáticas diseminadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30104, 11109, '2. Algunos casos se curan con tratamiento antibiótico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30105, 11109, '3. La cirugía radical es el tratamiento de elección hoy día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30106, 11109, '4. Presentan un curso clínico agresivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30107, 11109, '5. Se caracterizan por el reordenamiento del gen bcl-1.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30108, 11110, '1. Adenocarcinoma gástrico tipo difuso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30109, 11110, '2. Adenocarcinoma gástrico de tipo intestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30110, 11110, '3. Linfoma MALT gástrico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30111, 11110, '4. Linfoma alto grado gástrico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30112, 11110, '5. Linfoma de Hodgkin gástrico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30113, 11111, '1. La CU afecta el colon y la EC puede afectar a todo el tracto digestivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30114, 11111, '2. En la EC las lesiones sueles ser focales, segmentarias y asimétricas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30115, 11111, '3. En la EC existen tres patrones de presentación clínica: Inflamatorio, fistulizante y obstructivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30116, 11111, '4. La colonoscopia y la biopsia definen la extensión, siendo posible realizar el diagnóstico diferencial entre ambas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30117, 11111, '5. El diagnóstico diferencial debe realizarse con el linfoma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30118, 11112, '1. El origen suele ser el linfocito T.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30119, 11112, '2. Se localizan más frecuentemente en duodeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30120, 11112, '3. Se relacionan con malabsorción crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30121, 11112, '4. Se relacionan con trasplantes de órganos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30122, 11112, '5. Se relacionan con el SIDA.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30123, 11113, '1. Azatioprina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30124, 11113, '2. Infliximab.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30125, 11113, '3. Vedolizumab.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30126, 11113, '4. Ustekinumab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30127, 11114, '1. Hemicolectomía derecha ampliada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30128, 11114, '2. Panproctocolectomía con reservorio en J.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30129, 11114, '3. Ileocequectomía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30130, 11114, '4. Colostomía terminal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30131, 11115, '1. Es una proteína secretada por los neutrófilos que se determina en sangre para valorar la actividad de la enfermedad inflamatoria intestinal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30132, 11115, '2. Sus niveles tienen muy buena correlación con la actividad objetivada por endoscopia, sobre todo en la colitis ulcerosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30133, 11115, '3. En los pacientes con síndrome de intestino irritable se detecta en niveles anormalmente elevados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30134, 11115, '4. No es de utilidad en el seguimiento de pacientes con enfermedad inflamatoria intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30135, 11116, '1. Enfermedad crónica inflamatoria intestinal tipo colitis ulcerosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30136, 11116, '2. Colitis infecciosa parasitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30137, 11116, '3. Poliposis intestinal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30138, 11116, '4. Linfoma intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30139, 11117, '1. Se une a ICAM-1 y es responsable del paso de linfocitos desde la sangre periférica a los ganglios linfáticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30140, 11117, '2. Es un receptor para TNF-a en los linfocitos T CD4+ del sistema linfoide asociado a mucosas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30141, 11117, '3. Se expresa en las células del epitelio gastrointestinal en pacientes con enfermedad inflamatoria intestinal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30142, 11117, '4. Se une a la adresina MadCAM-1 y favorece el paso de linfocitos desde la sangre periférica a la placa de Peyer y la lámina propia intestinal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30143, 11118, '1. La espondilitis anquilosante es más frecuente en pacientes con enfermedad de Crohn.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30144, 11118, '2. La actividad de la espondilitis anquilosante guarda relación con la actividad inflamatoria de la enfermedad inflamatoria intestinal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30145, 11118, '3. La actividad de la espondilitis anquilosante no remite con glucocorticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30146, 11118, '4. La evolución de la espondilitis anquilosante evolución es lenta y progresiva', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30147, 11119, '1. El tiempo de evolución', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30148, 11119, '2. La afectación extensa de la enfermedad', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30149, 11119, '3. La coexistencia de cirrosis biliar primaria', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30150, 11119, '4. Los antecedentes familiares de cáncer colorrectal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30151, 11120, '1. Invaginación ileo-cólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30152, 11120, '2. Ileítis isquémica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30153, 11120, '3. Enfermedad de Crohn.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30154, 11120, '4. Colitis rádica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30155, 11121, '1. La colitis ulcerosa solo se asocia a un incremento en el riesgo de cáncer colorrectal en fumadores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30156, 11121, '2. En su caso, dado que está en remisión de larga duración, se considera adecuado el cribado aconsejado a la población general.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30157, 11121, '3. En casos como el suyo se considera adecuado someterse a colonoscopias periódicas con toma de múltiples biopsias escalonadas a lo largo de todo el colon.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30158, 11121, '4. En casos como el suyo se considera adecuado el cribado mediante estudios periódicos de sangre oculta en heces pero con una frecuencia superior a la utilizada en el cribado de la población general.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30159, 11122, '1. Repetir la colonoscopia para confirmar el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30160, 11122, '2. Vigilancia intensiva con colonoscopia cada 3 a 6 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30161, 11122, '3. Repetir la exploración y realizar una cromoendoscopia para identificar la lesión y realizar una mucosectomía endoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30162, 11122, '4. Proctocolectomía total.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30163, 11122, '5. Tratamiento con mesalazina a dosis de 2-3 gramos al día y repetir la exploración a los 3 a 6 meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30164, 11123, '1. Colectomía subtotal de urgencia y en un segundo tiempo proctectomía y reservorio ileoanal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30165, 11123, '2. Asociar un inmunosupresor como azatioprina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30166, 11123, '3. Asociar mesalazina en dosis de 4 gramos al día oral y triamcinolona rectal 1 aplicación cada 12 horas', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30167, 11123, '4. Ciclosporina endovenosa 2 mg/Kg.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30168, 11123, '5. Debe valorarse el tratamiento con etanercept (un anticuerpo anti-TNFa).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30169, 11124, '1. Valoración del estadio inmunitario mediante contaje linfocitario.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30170, 11124, '2. Serología del virus de hepatitis B (VHB).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30171, 11124, '3. Prueba de la tuberculina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30172, 11124, '4. Radiografía de tórax.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30173, 11124, '5. Serología del virus de la inmunodeficiencia humana (VIH).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30174, 11125, '1. No se pueden emplear en diabéticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30175, 11125, '2. No se puede utilizar en combinación con Metotrexato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30176, 11125, '3. No se puede utilizar en combinación con corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30177, 11125, '4. Hay riesgo de reactivar una tuberculosis latente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30178, 11125, '5. La presencia de una enfermedad desmielinizante no contraindica su uso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30179, 11126, '1. Mesalazina 4.5 gramos diarios v.o.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30180, 11126, '2. Mesalazina 4.5 gramos diarios v.o. y mesalazina 1 gramo diario rectal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30181, 11126, '3. Metilprednisolona 1 mg/kg/día por vía oral si el paciente tolera esta vía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30182, 11126, '4. Azatioprina 2.5 mg/kg/d por vía oral, repartidos en 3 tomas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30183, 11126, '5. Infliximab 5 mg/kg, con dosis posteriores de mantenimiento cada 8 semanas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30184, 11127, '1. A la edad habitual del cribado en la población general, 50 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30185, 11127, '2. 10 años antes de la edad habitual recomendada para el cribado de la población general.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30186, 11127, '3. A los 20 años de evolución de la enfermedad', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30187, 11127, '4. Entre los 8 y 10 años de evolución de la enfermedad', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30188, 11127, '5. En el momento del diagnóstico de la colangitis esclerosante', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30189, 11128, '1. Recomendar reposo relativo y paños calientes en ambas piernas y añadir tratamiento antidepresivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30190, 11128, '2. Biopsiar zonas de piel alejados de las áreas lesionadas y pautar analgésicos opioides de entrada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30191, 11128, '3. Sospechar la existencia de una lesión tumoral maligna intestinal como desencadenante del proceso cutáneo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30192, 11128, '4. Sospechar isquemia bilateral de extremidades inferiores de origen medicamentoso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30193, 11128, '5. Ajuste del tratamiento de la enfermedad intestinal.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30194, 11129, '1. Una hemicolectomía izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30195, 11129, '2. Una colectomía total con anastomosis íleo-rectal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30196, 11129, '3. Una colectomía total con ileostomía terminal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30197, 11129, '4. Una proctocolectomía total y anastomosis íleoanal con reservorio ileal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30198, 11129, '5. Una ileostomía terminal manteniendo el colon en reposo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30275, 11146, '4. Disminuir el intervalo libre de enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30199, 11130, '6. La CU afecta el colon y la EC puede afectar a todo el tracto digestivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30200, 11130, '7. En la EC las lesiones sueles ser focales, segmentarias y asimétricas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30201, 11130, '8. En la EC existen tres patrones de presentación clínica: Inflamatorio, fistulizante y obstructivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30202, 11130, '9. La colonoscopia y la biopsia definen la extensión, siendo posible realizar el diagnóstico diferencial entre ambas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30203, 11130, '10. El diagnóstico diferencial debe realizarse con el linfoma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30204, 11131, '1. Muchos pacientes con enfermedad de Crohn van a requerir cirugía en algún momento de su evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30205, 11131, '2. Las indicaciones quirúrgicas de la Enfermedad de Crohn se limitan a las complicaciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30206, 11131, '3. La solución habitual del megacolon tóxico es quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30207, 11131, '4. En el tratamiento quirúrgico de la colitis ulcerosa la resección debe limitarse únicamente al segmento de colon afectado.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30208, 11131, '5. Las complicaciones extraintestinales de la EII suelen remitir tras la resección del intestino dañado, con excepción de la espondilitis anquilosante y las complicaciones hepáticas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30209, 11132, '1. Azatioprina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30210, 11132, '2. Mesalazina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30211, 11132, '3. Prednisona.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30212, 11132, '4. 6-Mercaptopurina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30213, 11132, '5. Metotrexato.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30214, 11133, '1. Aparición de reservoritis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30215, 11133, '2. Aparición de yeyunitis ulcerativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30216, 11133, '3. Aparición de gastroduodenitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30217, 11133, '4. Aparición de esofagitis por citomegalovirus.', false, 4);
