INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30220, 11134, '2. Presencia de pseudopólipos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30221, 11134, '3. Presencia de mucosa normal con áreas de inflamación (lesiones alternantes).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30222, 11134, '4. Ulceraciones aftosas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30223, 11134, '5. Estenosis del colon.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30224, 11135, '1. Plantear asociar tratamiento con metotrexato que potencie el efecto inmunosupresor obtenido ya previamente con la azatioprina, para disminuir el grado de displasia epitelial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30225, 11135, '2. Reforzar mediante la administración de enemas de mesalazina el efecto antiinflamatorio farmacológico, para así reducir el grado de displasia epitelial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30226, 11135, '3. Valoración quirúrgica para realización de panproctocolectomía precoz.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30227, 11135, '4. Valoración quirúrgica para realizar resección segmentaria colónica precoz de la zona donde se ha encontrado la displasia grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30228, 11135, '5. Repetir dentro de 4 años la exploración, tranquilizando a nuestro paciente y recomendando que mantenga el mismo tratamiento que venía realizando.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30229, 11136, '1. El proceso inflamatorio está limitado a la mucosa y a la submucosa superficial, y las capas más profundas permanecen respetadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30230, 11136, '2. Para establecer el diagnóstico de Enfermedad de Crohn se precisa la presencia de granulomas no caseificantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30231, 11136, '3. El diagnóstico de enfermedad de Crohn no debe considerarse en individuos mayores de 50 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30232, 11136, '4. El tabaco es un factor protector para la Enfermedad de Crohn.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30233, 11136, '5. No todos los pacientes con fístulas perianales presentan signos endoscópicos de inflamación en el colon.', true, 5);
