INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30257, 11142, '2. p53.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30258, 11142, '3. BRCA1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30259, 11142, '4. MLH1.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30260, 11143, '1. Tumor T1 con invasión de la submucosa sm3.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30261, 11143, '2. Distancia al borde de sección de 2,5 mm.', false, 2);
