INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30263, 11143, '4. Ausencia de invasión linfovascular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30264, 11144, '1. EGFR, NRAS, KRAS, proteínas reparadoras, HER2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30265, 11144, '2. NRAS, KRAS, BRAF, proteínas reparadoras.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30266, 11144, '3. EGFR, NRAS, KRAS, BRAF, proteínas reparadoras.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30267, 11144, '4. NRAS, KRAS, BRAF, proteínas reparadoras, PI3K.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30268, 11145, '1. Tacto rectal y programar colonoscopia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30269, 11145, '2. Espirometría y programar broncoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30270, 11145, '3. Medir haptoglobina y realizar test de Coombs.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30271, 11145, '4. Medir vitamina B12 y programar biopsia de médula ósea.', false, 4);
