INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30273, 11146, '2. Realizar una anastomosis más baja.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30274, 11146, '3. Disminuir el número de recurrencias locales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30276, 11147, '1. La presencia de anemia al diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30277, 11147, '2. La existencia de antecedentes familiares de cáncer colorrectal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30278, 11147, '3. El tamaño de la lesión primaria y la diferenciación histológica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30279, 11147, '4. La perforación o adhesión del tumor a órganos adyacentes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30280, 11148, '1. Determinar mutación de KRAS y NRAS para poder administrar un anti-EFGR en caso de no ser mutado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30281, 11148, '2. Asociar al tratamiento con quimioterapia bevacizumab en caso de ser mutado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30282, 11148, '3. Administrar una combinación de quimioterapia con fluorouracilo y oxaliplatino.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30283, 11148, '4. Realizar tratamiento con radioterapia al tener afectación ganglionar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30284, 11149, '1. Pseudoobstrucción intestinal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30285, 11149, '2. Oclusión intestinal por bridas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30286, 11149, '3. Isquemia intestinal.', false, 3);
