INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30362, 11166, '1. Poliposis adenomatosa familiar. Mutación de gen APC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30363, 11166, '2. Síndrome de Li-Fraumeni. Mutación en TP53.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30364, 11166, '3. Cáncer de colon no polipósico (síndrome de Lynch). Mutación de MSH2 y MLH-1.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30365, 11166, '4. Síndrome de Cowden. Mutación en PTEN.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30366, 11166, '5. Síndrome de Gardner. Mutación del gen APC.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30367, 11167, '1. Se observa un engrosamiento mural excéntrico a nivel del colon ascendente compatible con adenocarcinoma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30368, 11167, '2. Presencia de mínimo engrosamiento parietal del colon con hiperemia mucosa difusa compatible con cambios de colitis ulcerosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30369, 11167, '3. Se identifica una colección fluida en el área pericecal con nivel hidroaéreo compatible con diverticulitis perforada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30370, 11167, '4. Se observa un voluminoso fecaloma colónico con obstrucción proximal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30371, 11167, '5. Presencia de mínima distensión fisiológica de las asas intestinales compatible con la normalidad para la edad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30372, 11168, '1. Colocación de sonda nasogástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30373, 11168, '2. Drenaje percutáneo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30374, 11168, '3. Antibioterapia de amplio espectro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30375, 11168, '4. Colocación de sonda rectal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30376, 11168, '5. Pancolonoscopia con biopsia', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30377, 11169, '1. El paciente padece una poliposis adenomatosa familiar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30378, 11169, '2. El manejo más apropiado es sulindac, colonoscopias de vigilancia anuales y colectomía total a los 40 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30379, 11169, '3. De no someterse a tratamiento quirúrgico casi con toda seguridad el paciente desarrollará un cáncer colorrectal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30380, 11169, '4. Deben estudiarse los familiares de primer grado del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30381, 11169, '5. Los hijos del paciente tienen un 50% de riesgo de padecer la misma enfermedad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30382, 11170, '1. La quimioterapia es el tratamiento de elección.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30383, 11170, '2. Puesto que la biopsia es superficial debe repetirse antes de proceder al tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30384, 11170, '3. El pronóstico del tumor depende principalmente de su alto grado de anaplasia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30385, 11170, '4. Es poco probable que ese tumor se haya desarrollado sobre un adenoma previo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30386, 11170, '5. Deben estudiarse la inestabilidad de microsatélites y los genes de reparación de errores del DNA.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30387, 11171, '1. Resección anterior de recto con extirpación completa del mesorrecto y anastomosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30388, 11171, '2. Amputación abdominoperineal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30389, 11171, '3. Quimiorradioterapia preoperatoria y resección anterior de recto con extirpación completa de mesorrecto y anastomosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30390, 11171, '4. Quimiorradioterapia preoperatoria y resección local con microcirugía endoscópica transanal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30391, 11171, '5. Quimiorradioterapia preoperatoria y Amputación abdominoperineal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30392, 11172, '1. Es un anticuerpo monoclonal anti- EGFR (receptor del factor de crecimiento epidérmico).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30393, 11172, '2. Es un anticuerpo monoclonal humanizado anti- VEGF (factor de crecimiento endotelial vascular).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30394, 11172, '3. Es un anticuerpo monoclonal humanizado anti- CD20.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30395, 11172, '4. Es una pequeña molécula que inhibe la tirosina- quinasa de EGFR.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30396, 11172, '5. Es un anticuerpo monoclonal anti-HER2/neu.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30397, 11173, '1. Realizar una colonoscopia inicial a los 40 años y revisiones endoscópicas cada 3 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30398, 11173, '2. Realizar una colonoscopia inicial a los 40 años y revisiones endoscópicas cada 5 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30399, 11173, '3. Realizar una colonoscopia inicial a los 40 años y revisiones endoscópicas cada 10 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30400, 11173, '4. Realizar una colonoscopia inicial a los 50 años y revisiones endoscópicas cada 5 años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30401, 11173, '5. Realizar una colonoscopia inicial a los 50 años y revisiones endoscópicas cada 10 años.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30402, 11174, '1. Resección anterior baja de recto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30403, 11174, '2. Amputación de recto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30404, 11174, '3. Resección anterior baja de recto vía laparoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30405, 11174, '4. Escisión local transanal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30406, 11174, '5. Microcirugía transanal endoscópica (TEM).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30407, 11175, '1. Casi todas las enfermedades del colon y recto, susceptibles de tratamiento quirúrgico, se pueden abordar mediante laparoscopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30408, 11175, '2. En la cirugía del cáncer de colon y recto, la disección ganglionar que se puede realizar por laparoscopia es más limitada que la efectuada por laparotomía.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30409, 11175, '3. La cirugía laparoscópica adelanta el retorno a la normalidad de la función intestinal en el postoperatorio, en comparación con la resección por laparotomía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30410, 11175, '4. El abordaje laparoscópico favorece un alta hospitalaria postoperatoria más precoz que tras una resección de colon convencional.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30411, 11175, '5. En la cirugía del cáncer de colon y recto, las tasas de supervivencia a largo plazo de los pacientes intervenidos por laparoscopia o laparotomía son similares.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30412, 11176, '1. Ras.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30413, 11176, '2. APC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30414, 11176, '3. MSH2.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30415, 11176, '4. p53.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30416, 11176, '5. c-MYC.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30417, 11177, '1. Programar un nuevo control colonoscópico dentro de 1 año.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30418, 11177, '2. Programar un nuevo control colonoscópico dentro de 5 años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30486, 11192, '3. El cáncer de colon.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31771, 11474, '5. Edrofonio.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30419, 11177, '3. No hace falta programar una nueva colonoscopia porque el pólipo ya ha sido resecado y no tenía displasia de alto grado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30420, 11177, '4. Para determinar con mayor precisión el intervalo de tiempo en el cual hay que repetir una nueva colonoscopia es preciso realizar un análisis de inestabilidad de microsatélites en el pólipo resecado y eventualmente secuenciación de los genes reparadores del ADN.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30421, 11177, '5. Repetir un nuevo control colonoscópico a los tres meses con biopsias de la cicatriz de la base de resección del pólipo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30422, 11178, '1. Duodeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30423, 11178, '2. Yeyuno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30424, 11178, '3. Ciego.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30425, 11178, '4. Sigma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30426, 11178, '5. Recto.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30427, 11179, '1. Síndrome de Peutz-Jeghers.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30428, 11179, '2. Síndrome de Cowden.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30429, 11179, '3. Síndrome de Gardner.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30430, 11179, '4. Síndrome de Lynch.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30431, 11179, '5. Poliposis Juvenil.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30432, 11180, '1. Cáncer de colon y recto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30433, 11180, '2. Cáncer duodenal o periampular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30434, 11180, '3. Cáncer de tiroides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30435, 11180, '4. Cáncer de páncreas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30436, 11180, '5. Cáncer de pulmón.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30437, 11181, '1. Descartar mediante exploración clínica y de imagen la presencia de un síndrome de Peutz Jeghers.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30438, 11181, '2. Hacer un estadiaje tumoral inmediato sobre todo con el fin de descartar metástasis hepáticas precoces.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30439, 11181, '3. Realizar como tratamiento inmediato resección intestinal de la zona que incluya el lecho tumoral, precedida de quimioterapia neoadyuvante y radioterapia preoperatoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30440, 11181, '4. Realizar un estudio histológico exhaustivo de la pieza con el fin de descartar áreas de carcinoma intramucoso o infiltrante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30441, 11181, '5. Realizar un estudio clínico, radiológico y genético urgente con el fin de descartar poliposis múltiple familiar y cáncer colorectal hereditario.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30442, 11182, '1. Cáncer de colon izquierdo oclusivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30443, 11182, '2. Síndrome de Ogilvie.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30444, 11182, '3. Diverticulitis aguda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30445, 11182, '4. Megacolon tóxico o infeccioso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30446, 11183, '1. En presencia de tratamiento con opioides son recomendables los suplementos de fibra vegetal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30447, 11183, '2. Los elementos fundamentales del tratamiento son los laxantes estimulantes y osmóticos, reblandecedores de heces, líquidos y enemas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30448, 11183, '3. Para evitar el estreñimiento causado por los opioides se debe recurrir a la combinación de un laxante y un reblandecedor de heces.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30449, 11183, '4. Si no hay defecación tras varios días de tratamiento, se necesita el tacto rectal para extraer el material impactado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30450, 11184, '1. Sigmoidectomía laparoscópica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30451, 11184, '2. Tratamiento conservador con fibra dietética y rifaximina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30452, 11184, '3. Dilatación endoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30453, 11184, '4. Stent en zona de estenosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30454, 11185, '1. Realizar un ECG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30455, 11185, '2. Realizar un enema opaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30456, 11185, '3. Realizar un ecocardiograma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30457, 11185, '4. Preguntar por el país de procedencia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30458, 11186, '1. Edad de aparición de los síntomas por encima de los 50 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30459, 11186, '2. Pérdida de peso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30460, 11186, '3. Sangre oculta en heces positiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30461, 11186, '4. Urgencia defecatoria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30462, 11187, '1. Ingreso en planta con dieta absoluta y tratamiento antibiótico de amplio espectro.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30463, 11187, '2. Colostomía de descarga.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30464, 11187, '3. Drenaje mediante cirugía laparoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30465, 11187, '4. Cirugía urgente con sigmoidectomía y anastomosis colorrectal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30466, 11188, '1. Los estudios rutinarios de laboratorio (análisis) muestran anomalías específicas de este síndrome.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30467, 11188, '2. Dentro de los síntomas que nos hacen pensar en un colon irritable se encuentran: dolor abdominal nocturno, dolor progresivo y pérdida de peso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30468, 11188, '3. Cursa con diarrea o estreñimiento, si se manifiestan ambos, queda descartada esta entidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30469, 11188, '4. En pacientes con colon irritable con predominio de diarrea, el estudio diagnóstico debe incluir: cultivo de heces, cribado de enfermedad celiaca, colonoscopia con biopsias.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30470, 11189, '1. Múltiples estenosis y ulceraciones del intestino delgado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30471, 11189, '2. Hipertensión portal secundaria con estasis venoso intestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30472, 11189, '3. Propulsión ineficaz del contenido del intestino delgado con dolor y distensión abdominal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30473, 11189, '4. Relajación defectuosa del esfínter anal con evacuación dificultosa de heces.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30474, 11190, '1. La exploración complementaria más segura y de mejor rendimiento es el enema con contraste baritado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30475, 11190, '2. En caso de absceso pélvico contenido está indicada la colocación de un drenaje percutáneo guiado con TAC o ecografía.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30476, 11190, '3. En caso de precisar intervención quirúrgica tras solucionarse el episodio agudo, el abordaje laparoscópico está contraindicado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30477, 11190, '4. En caso de diverticulitis aguda no complicada está indicada la sigmoidectomía electiva tras la curación del primer episodio agudo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30478, 11190, '5. Si se produjera una peritonitis generalizada, la técnica quirúrgica más adecuada es la práctica de una colostomía derivativa sin resección del segmento sigmoideo afectado', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30479, 11191, '1. Pérdida de peso con o sin rectorragia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30480, 11191, '2. Persistencia de la diarrea durante la noche.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30481, 11191, '3. Inicio de los síntomas después de los 50 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30482, 11191, '4. Presencia durante la exploración de dermatitis y/o artritis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30483, 11191, '5. Expulsión de moco en más del 25% de las defecaciones.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30484, 11192, '1. La colitis ulcerosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30485, 11192, '2. La enfermedad de Crohn.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30487, 11192, '4. La diverticulitis de colon.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30488, 11192, '5. La cirugía abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30489, 11193, '1. Gammagrafía con tecnecio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30490, 11193, '2. Suspensión del ácido acetil salicílico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30491, 11193, '3. Hemicolectomía derecha de urgencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30492, 11193, '4. Coagulación de la lesión con tratamiento endoscópico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30493, 11193, '5. Cápsula endoscópica para descartar otros divertículos en tramos altos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30494, 11194, '1. Dolor en fosa ilíaca izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30495, 11194, '2. Escalofríos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30496, 11194, '3. Fiebre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30497, 11194, '4. Cambio en el ritmo intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30498, 11194, '5. Rectorragias.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30499, 11195, '1. Realización de colonoscopia urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30500, 11195, '2. Colocación urgente de un drenaje percutáneo, dirigido por TAC, en área inflamada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30501, 11195, '3. Intervención quirúrgica urgente para extirpar zona del colon inflamada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30502, 11195, '4. Alta domiciliaria, recomendando dieta rica en fibra y que acuda nuevamente a urgencias si empeora la situación del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30503, 11195, '5. Observación hospitalaria con dieta absoluta y administración de ciprofloxacino y metronidazol por vía i.v.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30504, 11196, '1. Tacto rectal y programar colonoscopia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30505, 11196, '2. Espirometría y programar broncoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30506, 11196, '3. Medir haptoglobina y realizar test de Coombs.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30507, 11196, '4. Medir vitamina B12 y programar biopsia de médula ósea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30508, 11197, '1. Interrogarle sobre sus antecedentes (AINEs, dosis, tipo, tiempo de consumo, historia ulcerosa previa, antecedente de hemorragia digestiva,…etc) y realizar tacto rectal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30509, 11197, '2. Colocar sonda nasogástrica con lavado previo a la realización de endoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30510, 11197, '3. Realizar inmediatamente una endoscopia digestiva para establecer el diagnóstico y aplicar el tratamiento hemostático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30511, 11197, '4. Canalizar al menos una vía periférica de grueso calibre para infusión de volumen y obtener determinaciones analíticas básicas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30512, 11198, '1. Intervención quirúrgica inmediata.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30513, 11198, '2. Cápsula endoscópica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30514, 11198, '3. Enteroscopia quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30515, 11198, '4. Continuar con tratamiento conservador y solicitar arteriografía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30516, 11199, '1. Aun si no se logra la estabilidad hemodinámica hay que insistir en la preparación del colon.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30517, 11199, '2. Si la colonoscopia es normal, una endoscopia digestiva alta puede dar el diagnóstico en el 10-15% de los casos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30518, 11199, '3. La colonoscopia es la exploración con la mejor relación coste/efectividad por su seguridad, sensibilidad y potencial terapéutico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30519, 11199, '4. La gammagrafía con Tc99m es de contrastada utilidad si se sospecha un divertículo de Meckel.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30520, 11200, '1. Biopsia de yeyuno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30521, 11200, '2. Arteriografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30522, 11200, '3. Cápsula endoscópica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30523, 11200, '4. Radioisótopos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30524, 11200, '5. RM pélvica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30525, 11201, '1. Asegurar una adecuada oxigenación del paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30526, 11201, '2. Canalizar dos vías periféricas de grueso calibre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30527, 11201, '3. Utilizar el hematocrito como índice de pérdida hemática.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30528, 11201, '4. Reponer la volemia con soluciones de cristaloides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30529, 11201, '5. Colocar una sonda nasogástrica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30530, 11202, '1. Administrar hierro oral y ver evolución de la anemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30531, 11202, '2. Tratar con inhibidores de la bomba de protones y evaluar a los tres meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30532, 11202, '3. Recomendar una colonoscopia completa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30533, 11202, '4. Realizar un estudio con cápsula endoscópica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30534, 11202, '5. Solicitar una evaluación ginecológica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30535, 11203, '1. Resonancia magnética intestinal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30536, 11203, '2. Tránsito esófago-gastroduodenal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30537, 11203, '3. Cápsula endoscópica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30538, 11203, '4. Ecoendoscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30539, 11203, '5. Arteriografía.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30540, 11204, '1. Tamaño de la úlcera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30541, 11204, '2. Base de la úlcera cubierta de fibrina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30542, 11204, '3. Base de la úlcera cubierta por un coágulo fijo, adherido que no se moviliza con el lavado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30543, 11204, '4. Localización de la úlcera en incisura angularis o en cara posterior de bulbo duodenal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30544, 11204, '5. Sospecha endoscópica de malignidad de la úlcera.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30545, 11205, '1. Gammagrafía con tecnecio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30546, 11205, '2. Suspensión del ácido acetil salicílico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30547, 11205, '3. Hemicolectomía derecha de urgencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30548, 11205, '4. Coagulación de la lesión con tratamiento endoscópico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30549, 11205, '5. Cápsula endoscópica para descartar otros divertículos en tramos altos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30550, 11206, '1. Hipotensión y taquicardia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30551, 11206, '2. Disminución del hematocrito y hemoglobina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30552, 11206, '3. Pacientes que requieren transfusión para mantener la estabilidad hemodinámica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30553, 11206, '4. Lavado gástrico por sonda naso-gástrica con abundante sangre roja, que no se aclara tras lavados repetidos con abundante volumen.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30554, 11206, '5. Repetidos y frecuentes episodios de hematemesis con sangre roja y melenas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30555, 11207, '1. Se observa gas en el sistema portal siendo indicativo de mal pronóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30556, 11207, '2. Se trata de una aerobilia y por tanto el diagnóstico más probable es el de colangitis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30557, 11207, '3. Se observa aerobilia y pneumatosis gástrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30558, 11207, '4. Se trata de un hallazgo no relevante en relación con una CPRE o cirugía previa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30559, 11208, '1. Ecografía urgente como test de cribado inicial, si es normal no son necesarios más estudios radiológicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30560, 11208, '2. Radiografía de abdomen en bipedestación o decúbito lateral izquierdo para valorar presencia de gas ectópico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30561, 11208, '3. TC abdominopélvico con contraste intravenoso con protocolo de angio-TC por sospecha de isquemia mesentérica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30562, 11208, '4. Arteriografía para descartar oclusión aguda de arteria mesentérica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30563, 11209, '1. Perforación de ulcus gástrico o duodenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30564, 11209, '2. Íleo biliar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30565, 11209, '3. Neoplasia obstructiva de sigma con perforación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30566, 11209, '4. Isquemia mesentérica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30567, 11210, '1. 1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30568, 11210, '2. 2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30569, 11210, '3. 3.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30570, 11210, '4. 4.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30571, 11211, '1. La arteria cólica media.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30572, 11211, '2. La arteria gastroduodenal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30573, 11211, '3. La arteria epigástrica inferior izquierda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30574, 11211, '4. La arteria esplénica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30575, 11211, '5. La arteria gastroepiploica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30576, 11212, '1. Dilatación de asas de intestino delgado y grueso, compatible con obstrucción en sigma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30577, 11212, '2. Asas de intestino delgado ligeramente dilatadas, con aire y presencia de heces y gas en marco cólico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30578, 11212, '3. Asas de intestino delgado dilatadas e imagen de colon cortado asociado a pancreatitis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30579, 11212, '4. Dilatación de asas de intestino delgado y grueso, por fecaloma en ampolla rectal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30580, 11212, '5. Asas de intestino delgado dilatadas con aire en la pared (“neumatosis intestinal”).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30581, 11213, '1. TAC abdominal sin contraste para disminuir el riesgo de daño renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30582, 11213, '2. Repetir radiografía simple de abdomen para descartar aire libre intraperitoneal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30583, 11213, '3. Hacer una ecografía abdominal para descartar patología biliar y/o renoureteral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30584, 11213, '4. Colonoscopia para valorar la integridad de la mucosa del colon.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30585, 11213, '5. Angiografía por medio de tomografía axial computarizada (Angio-TAC).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30586, 11214, '1. La causa más frecuente es un émbolo cardiógeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30587, 11214, '2. La embolia suele ser distal al origen de la arteria mesentérica superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30588, 11214, '3. La trombosis venosa es de difícil diagnóstico precoz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30589, 11214, '4. La isquemia no oclusiva tiene el mejor pronóstico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30590, 11214, '5. La cirugía precoz ofrece la mejor oportunidad de tratamiento eficaz.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30591, 11215, '1. Cáncer de colon.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30592, 11215, '2. Colitis ulcerosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30593, 11215, '3. Colitis pseudomembranosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30594, 11215, '4. Colitis actínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30595, 11215, '5. Colitis isquémica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30596, 11216, '1. Úlcera solitaria de recto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30597, 11216, '2. Proctalgia fugax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30598, 11216, '3. Proctalgia inespecífica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30599, 11216, '4. Síndrome del elevador del ano.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30600, 11217, '1. Fisura anal anterior crónica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30601, 11217, '2. Fisura anal aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30602, 11217, '3. Fístula ano-vaginal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30603, 11217, '4. Úlcera anal por enfermedad de Crohn.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30604, 11218, '1. Drenaje-desbridamiento quirúrgico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30605, 11218, '2. Antibiótico de amplio espectro y esperar evolución.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30606, 11218, '3. Ingreso hospitalario para estudio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30607, 11218, '4. Punción-drenaje guiado por radiología.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30608, 11219, '1. Consiste en un desgarro longitudinal de la piel que recubre la porción del canal anal distal a la línea dentada y origina un dolor intenso con la defecación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30609, 11219, '2. Tiene dos formas típicas: la primaria o idiopática aparece en individuos sanos y no se asocia a ningún tipo de enfermedad, la secundaria se detecta en pacientes que sufren otro proceso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30610, 11219, '3. La mayoría de las fisuras primarias se localizan en la comisura anterior, al ser ésta una zona del canal anal más susceptible al traumatismo y a la isquemia de la mucosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30611, 11219, '4. Las fisuras secundarias a otras enfermedades aparecen con frecuencia en posiciones más laterales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30612, 11220, '1. Antibióticos de amplio espectro y controlar evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30613, 11220, '2. Realizar ecoendoscopia y PAAF ecoguiada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30614, 11220, '3. Drenaje bajo anestesia regional.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30615, 11220, '4. Realizar una TC y así valorar la vía de abordaje para su correcto tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30616, 11221, '1. Fistulotomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30617, 11221, '2. Colocación de sedal no cortante en el trayecto de la fístula asociado a tratamiento con metronidazol, infliximab e inmunosupresores.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30618, 11221, '3. Realizar drenajes repetidos cada vez que presente un absceso, asociando tratamiento con infliximab e inmunosupresores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30619, 11221, '4. Esfinterotomía lateral interna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30620, 11222, '1. Tratamiento médico con normas higienodieteticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30621, 11222, '2. Biofeedback esfinteriano.', false, 2);
