INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30676, 11234, '1. Solicitar las transaminasas hepáticas en sangre y si no están alteradas darle el alta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30677, 11234, '2. Mantenerlo en observación hasta que hayan pasado 4 h desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de Nacetilcisteina intravenosa por si hubiera que administrarla.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30678, 11234, '3. Mantenerlo en observación hasta que hayan pasado 4 h desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de Protamina que es el antídoto necesario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30679, 11234, '4. Mantenerlo en observación hasta que hayan pasado 6 h desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de Atropina que es el antídoto necesario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30680, 11234, '5. Ponerse en contacto con el Coordinador de trasplantes por si fuera necesario el trasplante hepático.', false, 5);
