INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30687, 11236, '2. Tiempo de protrombina más de 4 segundos el límite normal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30688, 11236, '3. Encefalopatía hepática.', false, 3);
