INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30691, 11237, '1. Administrar una dosis de gammaglobulina frente a VHB y una dosis de vacuna.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30692, 11237, '2. Administrar una dosis de gammaglobulina frente a VHB y vacunación completa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30693, 11237, '3. Administrar una dosis de gammaglobulina frente a VHB y realizar antisepsia de la zona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30694, 11237, '4. Realizar antisepsia de la zona y vacunación completa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30695, 11238, '1. En el mundo, la vía de transmisión más frecuente del VHC es la vertical.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30696, 11238, '2. Si el VHC se adquiere en edad adulta, se cronifica en el 5-10% de los casos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30697, 11238, '3. La mayoría de los pacientes con infección crónica por el VHC presentan anticuerpos anti VHC positivos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30698, 11238, '4. La infección aguda por el VHC cursa con ictericia franca en más del 80% de los casos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30699, 11239, '1. Administrar una primera dosis de vacuna frente al VHB y simultáneamente coadministrar la inmunoglobulina antihepatitis B.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30700, 11239, '2. Administrar una primera dosis de vacuna frente al VHB y simultáneamente iniciar el tratamiento con el antiviral ribavirina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30701, 11239, '3. Administrar la inmunoglobulina antihepatitis B y simultáneamente iniciar el tratamiento con el antiviral ribavirina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30702, 11239, '4. Administrar únicamente la inmunoglobulina antihepatitis B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30703, 11240, '1. En contraste con el VHB y VHC, la transmisión por sangre del VHA es poco común, porque la viremia es breve y de bajo título.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30704, 11240, '2. El VHE es un virus defectivo que usa el antígeno de la superficie del VHB como su proteína de envoltura.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30705, 11240, '3. La polimerasa codificada por el VHB actúa como una transcriptasa inversa usando el RNAm vírico como molde para la síntesis de los genomas de DNA progenie.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30706, 11240, '4. La detección del HBsAg durante más de seis meses indica un estado del portador crónico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30707, 11241, '1. Infección aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30708, 11241, '2. Infección crónica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30709, 11241, '3. Paciente vacunado.', false, 3);
