INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30712, 11242, '2. Adefovir.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30713, 11242, '3. Tenofovir.', false, 3);
