INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30718, 11243, '4. Psoriasis pustulosa generalizada de von Zumbuch.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30719, 11244, '1. Intensidad de la ictericia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30720, 11244, '2. Frecuencia de la hepatitis A en el entorno.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30721, 11244, '3. Días de duración del cuadro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30722, 11244, '4. Experiencia del profesional sobre cuadros de ictericia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30723, 11244, '5. Enfermedades previas del paciente.', false, 5);
