INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30725, 11245, '2. Hepatitis crónica por VHC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30726, 11245, '3. Hepatitis crónica por VH delta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30727, 11245, '4. Hepatitis por tóxicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30728, 11245, '5. Hepatitis por alcohol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30729, 11246, '1. El virus de la hepatitis C.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30730, 11246, '2. El virus de la hepatitis B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30731, 11246, '3. El virus de la hepatitis A.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30732, 11246, '4. El virus de la hepatitis E.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30733, 11246, '5. El virus TTV.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30734, 11247, '1. Es un virus RNA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30735, 11247, '2. El genotipo más frecuente en España es el genotipo 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30736, 11247, '3. El genotipo 3 responde mejor al tratamiento que el genotipo 1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30737, 11247, '4. Puede ser causa de cirrosis hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30738, 11247, '5. El tratamiento consiste en administrar ribavirina en monoterapia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30739, 11248, '1. El virus de la inmunodeficiencia humana (VIH).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30740, 11248, '2. El virus del herpes simple (VHS).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30741, 11248, '3. El virus de Epstein-Barr (VEB).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30742, 11248, '4. Citomegalovirus (CMV).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30743, 11248, '5. El virus de la hepatitis C (VHC).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30744, 11249, '1. Reiniciar pauta vacunal (0-1-6 meses).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30745, 11249, '2. Reiniciar pauta vanal (0-1-2-12 meses).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30746, 11249, '3. No revacunar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30747, 11249, '4. Darle una dosis de recuerdo o booster.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30748, 11249, '5. Darle Immunoglobulina anti-hepatitis B y reiniciar pauta vacunal (0-1-2-12 meses).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30749, 11250, '1. Cirrosis en el contexto de una hepatitis C.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30750, 11250, '2. Necrosis hepática submasiva por tóxicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30751, 11250, '3. Hepatitis crónica B sin actividad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30752, 11250, '4. Hepatitis crónica activa C.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30753, 11250, '5. Hepatitis por VIH sin actividad en el momento actual.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30754, 11251, '1. La esperanza de vida de este paciente, dejado a su libre evolución, puede cifrarse en 23 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30755, 11251, '2. Sin tratamiento alguno, el riesgo de desarrollar un hepatocarcinoma a largo plazo es significativo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30756, 11251, '3. El riesgo de padecer hepatitis fulminante es, por lo menos, un 15 %, por lo que hay indicación para inclusión inmediata en programa de trasplante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30757, 11251, '4. El paciente padece un tipo de enfermedad limitada exclusivamente al hígado, por lo que no es de esperar patología extrahepática en el futuro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30758, 11251, '5. Los tratamientos actuales de esta enfermedad no permiten esperar mejorías duraderas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30759, 11252, '1. Administrar vacuna frente a hepatitis B nada más nacer. Lactancia artificial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30760, 11252, '2. Administrar vacuna e inmunoglobulinas al nacer. Lactancia materna a partir del mes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30761, 11252, '3. Inmunoglobulinas al nacer y lactancia artificial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30762, 11252, '4. Vacuna e inmunoglobulinas al nacer. Alimentación materna.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30763, 11252, '5. Alimentación artificial y aislamiento durante 4 semanas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30764, 11253, '1. Hepatitis crónica B.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30765, 11253, '2. Hepatitis aguda no viral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30766, 11253, '3. Hepatitis aguda B.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30767, 11253, '4. Sobreinfección por virus D (delta).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30768, 11253, '5. Hepatitis aguda A y B.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30769, 11254, '1. Las vacunas frente a la Hepatitis B son vacunas atenuadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30770, 11254, '2. Las vacunas frente a la Hepatitis B utilizan el antígeno del core (AgHBc) obtenido por ingeniería genética como inmunógeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30771, 11254, '3. Las vacunas frente a la Hepatitis B utilizan el antígeno de superficie (AgHBs) obtenido por ingeniería genética como inmunógeno.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30772, 11254, '4. La vacunación frente a la hepatitis B no está incluida en el calendario de vacunación del Consejo Interterritorial del Sistema Nacional de Salud.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30773, 11254, '1. Se debe vacunar frente a la hepatitis B en el caso de heridas sucias.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30774, 11255, '1. Anti VHA IgG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30775, 11255, '2. Anti Hepatitis D IgM.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30776, 11255, '3. Anti HBc IgG.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30777, 11255, '4. DNA del virus B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30778, 11255, '5. RNA del virus C', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30779, 11256, '1. ALT < 2 veces el límite alto de la normalidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30780, 11256, '2. Adquisición de la enfermedad en la infancia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30781, 11256, '3. Paciente inmunodeprimido.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30782, 11256, '4. Carga viral baja.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30783, 11256, '5. Ausencia de enfermedad infecciosa bacteriana reciente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30784, 11257, '1. Una respuesta viral mantenida (negativización del ARN) en la hepatitis crónica C se considera curación de la infección viral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30785, 11257, '2. Una respuesta viral mantenida (negativización del ADN) en la hepatitis crónica B se considera curación de la infección viral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30786, 11257, '3. La ausencia de respuesta viral temprana permite interrumpir el tratamiento en pacientes con hepatitis crónica C, evitando efectos secundarios y costes económicos innecesarios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30864, 11274, '4. Resonancia magnética hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30787, 11257, '4. La duración del tratamiento antiviral en la hepatitis crónica C depende del genotipo viral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30788, 11257, '5. El tratamiento antiviral indicado en la hepatitis crónica por virus C es la asociación de interferón alfa pegilado y ribavirina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30789, 11258, '1. La información disponible apoya el diagnóstico de cirrosis hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30790, 11258, '2. La presencia de anticuerpos antinucleares a títulos altos como en este caso es diagnóstica de hepatitis autoinmune asociada a la hepatitis C.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30791, 11258, '3. La elevada viremia detectada es un signo de mal pronóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30792, 11258, '4. Existe indicación de tratamiento antiviral con interferón pegilado y ribavirina durante 48 semanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30793, 11258, '5. La presencia de genotipo lb es un factor predictivo de buena respuesta al tratamiento.', false, 5);
