INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30797, 11259, '4. Hepatitis crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30798, 11260, '1. Tiene una esteatosis hepática sin riesgo de desarrollar cirrosis ni hepatocarcinoma, por lo que es suficiente el control metabólico periódico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30799, 11260, '2. Está indicado realizar una biopsia hepática por la sospecha de hepatitis autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30800, 11260, '3. Es útil realizar una elastografía de transición (FibroScan ®) para determinar la existencia o no de fibrosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30801, 11260, '4. Está indicado sustituir la metformina por pioglitazona que ha demostrado ser más eficaz para mejorar la esteatosis hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30802, 11261, '1. Es la prueba de elección en el cribado de la enfermedad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30803, 11261, '2. Es útil en la evaluación de riesgo en familiares de individuos afectos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30804, 11261, '3. El gen HFE está en el locus del Complejo Mayor de Histocompatibilidad (HLA) en el cromosoma 6, en humanos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30805, 11261, '4. Las mutaciones C282Y y H63D en el gen HFE son muy prevalentes en la población caucásica.', false, 4);
