INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30852, 11272, '2. Porfiria cutánea tarda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30853, 11272, '3. Reacción fototóxica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30854, 11272, '4. Dermatitis de contacto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30855, 11272, '5. Porfiria aguda intermitente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30856, 11273, '1. Debe repetirse la biopsia para saber si los cambios son difusos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30857, 11273, '2. El diagnóstico es de una glucogenosis hepática asociada a la diabetes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30858, 11273, '3. Los cambios histológicos son irreversibles y acabarán produciendo una cirrosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30859, 11273, '4. La lesión está causada claramente por el alcohol a pesar de la negativa del enfermo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30860, 11273, '5. Es importante disminuir peso y controlar adecuadamente la diabetes para evitar el posible desarrollo de una cirrosis.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30861, 11274, '1. Anticuerpos antimitocondriales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30862, 11274, '2. Estudio del metabolismo del hierro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30863, 11274, '3. Estudio del metabolismo del cobre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30865, 11274, '5. Serología de virus B y virus C.', false, 5);
