INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30870, 11275, '5. Resonancia magnética de las articulaciones de la muñeca.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30871, 11276, '1. Coledocolitiasis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30872, 11276, '2. Hepatitis autoinmune.', false, 2);
