INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30875, 11276, '5. Cirrosis biliar primaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30876, 11277, '1. Interferón.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30877, 11277, '2. Quelantes del Fe.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30878, 11277, '3. Lamivudina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30879, 11277, '4. Sangrías periódicas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30880, 11277, '5. D penicilamina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30881, 11278, '1. Porfiria de Doss, debiendo indicar profilaxis con compuestos de plomo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30882, 11278, '2. Porfiria aguda intermitente, cuyas crisis se evitan con clorodiacepóxido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30883, 11278, '3. Porfiria cutánea tarda, siendo eficaz la cloroquina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30884, 11278, '4. Protoporfiria eritropoyética. Su tratamiento consiste en sangrías periódicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30885, 11278, '5. Porfiria congénita de Günther. En algunas ocasiones son eficaces las tetraciclinas al ser estos antibióticos excelentes protectores solares.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30886, 11279, '1. Colocación de una derivación intrahepática percutánea (TIPS).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30887, 11279, '2. Anticoagulación oral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30888, 11279, '3. Trasplante hepático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30889, 11279, '4. Angioplastia percutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30890, 11280, '1. Estabilizar hemodinámicamente, hacer una endoscopia y colocar un TIPS si tiene hemorragia por varices.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30891, 11280, '2. Realizar una paracentesis, seguido de una endoscopia y ligadura de varices.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30892, 11280, '3. Estabilizar al paciente, iniciar un fármaco vasoactivo, realizar una endoscopia y practicar una ligadura si hay hemorragia por varices.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30893, 11280, '4. Esperar al resultado de la endoscopia para actuar en consecuencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30894, 11281, '1. Albúmina sérica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30895, 11281, '2. Índice internacional normalizado (INR).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30896, 11281, '3. Bilirrubina total sérica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30897, 11281, '4. Transaminasas (valor de ALT y AST).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30898, 11282, '1. Vancomicina 500 mg / día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30899, 11282, '2. Norfloxacino 400 mg / día.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30900, 11282, '3. Metronidazol 250 mg / día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30901, 11282, '4. Amoxicilina 1000 mg / día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30902, 11283, '1. Aunque esté estable y no tenga fiebre ni dolor, debe realizarse una paracentesis diagnóstica, al ser el primer episodio conocido de ascitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30903, 11283, '2. Está indicado realizar una nueva ecografía para descartar causas que puedan provocar una ascitis de novo (trombosis de vena porta, hepatocarcinoma, etc.).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30904, 11283, '3. Está indicado el inicio de tratamiento con betabloqueantes no cardioselectivos porque presenta varices grandes, aunque nunca haya sangrado, ya que prolongan la supervivencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30905, 11283, '4. La instauración del tratamiento diurético debemos iniciarla en un periodo corto de hospitalización para asegurarnos que no aparece fallo renal o hiponatremia grave asociada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30906, 11284, '1. Cirrosis hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30907, 11284, '2. Carcinomatosis peritoneal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30908, 11284, '3. Síndrome de Budd-Chiari', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30909, 11284, '4. Insuficiencia hepática aguda (hepatitis fulminante).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30910, 11285, '1. Triglicéridos 90 mg/dL.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30911, 11285, '2. Proteínas totales 3 g/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30912, 11285, '3. Leucocitos >500/mm3.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30913, 11285, '4. Gradiente de albúmina 0.9 g/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30914, 11286, '1. Ecoendoscopia digestiva alta diagnóstica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30915, 11286, '2. Esclerosis de varices esofágicas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30916, 11286, '3. Colonoscopia diagnóstica en paciente con dolicocolon.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30917, 11286, '4. Polipectomía de pólipo en colon descendente de morfología sesil.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30918, 11287, '1. Restricción de sal y líquidos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30919, 11287, '2. Tratamiento diurético con espironolactona oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30920, 11287, '3. Tratamiento con una cefalosporina de tercera generación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30921, 11287, '4. Paracentesis evacuadora.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30922, 11288, '1. Una tomografía computarizada craneal para descartar un accidente cerebro-vascular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30923, 11288, '2. Una ecografía abdominal para confirmar la presencia de ascitis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30924, 11288, '3. Una paracentesis exploradora para descartar una peritonitis bacteriana espontánea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30925, 11288, '4. Un electroencefalograma para confirmar la existencia de encefalopatía hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30926, 11288, '5. Una tomografía computarizada abdominal para descartar un carcinoma hepatocelular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30927, 11289, '1. Medir el volumen de orina de 24 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30928, 11289, '2. Medir el perímetro abdominal diariamente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30929, 11289, '3. Determinar cada semana el gradiente de albúmina entre el suero y la ascitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30930, 11289, '4. Registrar el peso cada día.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30931, 11289, '5. Evaluar la natriuresis cada 48 horas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30932, 11290, '1. Quinolonas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30933, 11290, '2. Bloqueantes beta-adrenérgicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30934, 11290, '3. Antiinflamatorios no esteroideos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30935, 11290, '4. Antidiabéticos orales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30936, 11290, '5. Analgésicos no antiinflamatorios.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30937, 11291, '1. Las lesiones son muy sugestivas de una púrpura de Schönlein-Henoch.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30938, 11291, '2. El diagnóstico diferencial deberá incluir las arañas vasculares propias de una cirrosis hepática alcohólica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30939, 11291, '3. El examen hematológico característicamente mostrará esquistocitos y plaquetopenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30940, 11291, '4. Lo más probable es que el paciente presente una anemia por pérdidas digestivas debidas a un pólipo degenerado en el colon.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30941, 11291, '5. Las lesiones mucosas son muy inespecíficas y difícilmente pueden relacionarse con la sintomatología que refiere el paciente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30942, 11292, '1. Endoscopia con escleroterapia mediante inyección de adrenalina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30943, 11292, '2. Taponamiento con sonda-balón de Sengstaken-Blakemore.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30944, 11292, '3. Endoscopia con ligadura mediante bandas elásticas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30945, 11292, '4. Embolización percutánea con coils de las varices esofágicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30946, 11292, '5. Derivación portosistémica intrahepática percutánea (por vía transyugular, conocida por sus siglas inglesas como TIPS)', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30947, 11293, '1. Lipoatrofia facial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30948, 11293, '2. Ginecomastia bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30949, 11293, '3. Arañas vasculares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30950, 11293, '4. Edema maleolar bilateral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30951, 11293, '5. Reflujo hepatoyugular.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30952, 11294, '1. Ligadura con bandas de varices esofágicas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30953, 11294, '2. Trasplante hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30954, 11294, '3. Shunt esplenorrenal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30955, 11294, '4. Shunt peritoneo-venoso de LeVeen.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30956, 11294, '5. Derivación portocava.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30957, 11295, '1. Proponer entrada preferente en un programa de trasplante hepático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30958, 11295, '2. Establecer un régimen de paracentesis evacuadoras periódicas con reposición coloidal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30959, 11295, '3. Insertar un TIPS.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30960, 11295, '4. Aumentar aún más las dosis de diuréticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30961, 11295, '5. Administrar una sobrecarga de suero salino hipertónico para forzar la diuresis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30962, 11296, '1. Trasplante hepático urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30963, 11296, '2. Realización de una cirugía resectiva: desconexión ácigo portal (técnica de Sugiura).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30964, 11296, '3. Realización de una portocava calibrada (shunt portosistémico quirúrgico).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30965, 11296, '4. Shunt transyugular portosistémico intrahepático.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30966, 11296, '5. La mejor cirugía derivativa de urgencia es la derivación selectiva espleno-renal distal de Warren.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30967, 11297, '1. Añadir diuréticos de asa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30968, 11297, '2. Realizar una paracentesis evacuadora.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30969, 11297, '3. Administrar antibióticos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30970, 11297, '4. Perfusión de Albúmina y Seguril intravenoso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30971, 11297, '5. Hacer una derivación portocava.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30972, 11298, '1. Colocación de una derivación intrahepática percutánea (TIPS).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30973, 11298, '2. Anticoagulación oral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30974, 11298, '3. Trasplante hepático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30975, 11298, '4. Angioplastia percutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30976, 11299, '1. Se observa gas en el sistema portal siendo indicativo de mal pronóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30977, 11299, '2. Se trata de una aerobilia y por tanto el diagnóstico más probable es el de colangitis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30978, 11299, '3. Se observa aerobilia y pneumatosis gástrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30979, 11299, '4. Se trata de un hallazgo no relevante en relación con una CPRE o cirugía previa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30980, 11300, '1. Trasplante hepático.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30981, 11300, '2. Oclusión de la comunicación portosistémica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30982, 11300, '3. Colocación de TIPS (protesis intrahepática percutánea transyugular).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30983, 11300, '4. Trasplante de microbiota fecal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30984, 11301, '1. Hemangioma complicado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30985, 11301, '2. Hepatocarcinoma calcificado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30986, 11301, '3. Quiste hidatídico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30987, 11301, '4. Metástasis hepática necrótica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30988, 11302, '1. Quimioembolización transarterial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30989, 11302, '2. Sorafenib.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30990, 11302, '3. Trasplante hepático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30991, 11302, '4. Ablación con radiofrecuencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30992, 11303, '1. Absceso hepático.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30993, 11303, '2. Hemangioma hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30994, 11303, '3. Hepatocarcinoma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30995, 11303, '4. Hiperplasia nodular focal con necrosis en su interior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30996, 11304, '1. Hepatocarcinoma sobre hígado normal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30997, 11304, '2. Hepatocarcinoma sobre hígado cirrótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30998, 11304, '3. Colangiocarcinoma sobre hígado normal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (30999, 11304, '4. Colangiocarcinoma sobre hígado cirrótico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31000, 11305, '1. Hemoglobina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31001, 11305, '2. INR.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31002, 11305, '3. Creatinina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31003, 11305, '4. Bilirrubina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31004, 11306, '1. Aplicar inyección de etanol percutánea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31005, 11306, '2. Resección hepática.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31006, 11306, '3. Trasplante hepático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31007, 11306, '4. Quimioembolización transarterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31008, 11307, '1. El estudio histológico es obligatorio en todos los casos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31009, 11307, '2. En pacientes cirróticos el diagnóstico se puede realizar mediante técnicas de imagen dinámicas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31010, 11307, '3. En pacientes cirróticos el diagnóstico se puede realizar ante la sospecha clínica y niveles de la alfa fetoproteína mayores de 100 ng/dL.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31011, 11307, '4. La arteriografía es la única técnica que demuestra de forma fiable la característica fundamental de este tumor que es la hipervascularización arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31012, 11308, '1. Trasplante hepático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31013, 11308, '2. Resección quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31014, 11308, '3. Quimioembolización transarterial con microesferas liberadoras de fármacos (TACEDEB).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31015, 11308, '4. Sorafenib.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31016, 11309, '1. Enfermedad de Crigler-Najjar de tipo I.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31017, 11309, '2. Hiperoxaluria primaria tipo I.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31018, 11309, '3. Atresia biliar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31019, 11309, '4. Enfermedad de Alagille.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31394, 11392, '2. CA 125.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31020, 11310, '1. La indicación de trasplante hepático más frecuente en la actualidad es la cirrosis por infección del virus B (VHB).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31021, 11310, '2. Las metástasis hepáticas por cáncer de colon constituyen una indicación aprobada para trasplante hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31022, 11310, '3. El sistema MELD es un modelo pronóstico que permite la priorización para el trasplante hepático de los enfermos en lista.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31023, 11310, '4. El trasplante hepático sería la mejor opción de tratamiento para un paciente de 45 años con un hepatocarcinoma difuso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31024, 11311, '1. Rechazo agudo mediado por anticuerpos con trombosis arterial asociada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31025, 11311, '2. Recidiva precoz del VHC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31026, 11311, '3. Estenosis de la anastomosis biliar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31027, 11311, '4. Lesión isquémica de las vías biliares intrahepáticas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31028, 11311, '5. Trombosis completa de las ramas portales intrahepáticas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31029, 11312, '1. Retrasplante hepático.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31030, 11312, '2. Tratamiento con Sofosbuvir y Daclatasvir', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31031, 11312, '3. Hepático-yeyunostomía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31032, 11312, '4. Administración de 3 bolus de metilprednilosona e incremento de la inmunosupresión basal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31033, 11312, '5. Anticoagulación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31034, 11313, '1. Pueden asociarse al síndrome de Kasabach-Merritt (trombocitopenia y coagulopatía de consumo), especialmente los hemangiomas gigantes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31035, 11313, '2. Se debe indicar la exéresis quirúrgica desde el momento que se diagnostique si su diámetro es mayor de 3 cm.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31036, 11313, '3. La opción terapéutica más recomendable para este tipo de tumor es la embolización percutánea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31037, 11313, '4. El mejor método para su confirmación diagnóstica es la biopsia percutánea de la lesión hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31038, 11313, '5. La RM hepática no suele ofrecer mucha ayuda para su caracterización diagnóstica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31039, 11314, '1. Se considera que su aparición está relacionada con el consumo de anticonceptivos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31040, 11314, '2. El riesgo de hemoperitoneo por rotura es similar al del adenoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31041, 11314, '3. Existe riesgo de degeneración tumoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31042, 11314, '4. Se comporta como una lesión focal hipovascular en la tomografía computerizada con administración de contraste.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31043, 11314, '5. En el estudio histológico de la lesión además de hepatocitos pueden observarse conductos biliares y otras células hepáticas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31044, 11315, '1. Iniciar sorafenib oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31045, 11315, '2. Practicar una resección quirúrgica del tumor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31046, 11315, '3. Realizar un tratamiento local mediante técnicas de ablación percutánea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31047, 11315, '4. Proponer un trasplante hepático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31048, 11315, '5. Tratar con quimioembolización arterial del tumor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31049, 11316, '1. Se observa una lesión focal hipervascular en fase arterial compatible con pseudoaneurisma de la arteria hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31050, 11316, '2. Se observa un nódulo hipervascular en fase arterial con lavado en fase venosa compatible con carcinoma hepatocelular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31051, 11316, '3. Se observa una lesión focal hipovascular compatible con colangiocarcinoma periférico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31052, 11316, '4. Se trata de una lesión quística. Probable quiste hidatídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31053, 11316, '5. Se observa una gran trombosis portal tumoral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31054, 11317, '1. Trasplante hepático.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31055, 11317, '2. Radioterapia externa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31056, 11317, '3. Ablación con radiofrecuencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31057, 11317, '4. Embolización arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31058, 11317, '5. Quimioterapia sistémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31059, 11318, '1. Tratamiento sintomático y de soporte, ya que presenta un hepatocarcinoma avanzado con invasión vascular y metástasis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31060, 11318, '2. Quimioembolización transarterial (TACE), ya que este tratamiento aumenta la supervivencia en los pacientes con hepatocarcinoma avanzado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31061, 11318, '3. Quimioterapia sistémica con doxorrubicina iv ya que presenta enfermedad diseminada pero mantiene buen estado general.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31062, 11318, '4. Tratamiento con sorafenib oral, ya que se trata de un enfermo con buen estado general, Child A y hepatocarcinoma en estadío avanzado BCLC-C.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31063, 11318, '5. El tratamiento adecuado es el trasplante hepático ya que es el único procedimiento que elimina completamente el tumor primario y evita las complicaciones futuras de la cirrosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31064, 11319, '1. Se prevé un aumento de su incidencia en los próximos años.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31065, 11319, '2. Suele diagnosticarse en pacientes entre 40 y 50 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31066, 11319, '3. En nuestro medio se relaciona habitualmente con la infección por el virus de la hepatitis B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31067, 11319, '4. En la TC se manifiesta como una lesión hipo-vascular en fase arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31068, 11319, '5. En la actualidad no se dispone de ningún fármaco capaz de mejorar la supervivencia de los pacientes con hepatocarcinoma avanzado.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31069, 11320, '1. Marcadores tumorales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31070, 11320, '2. TC de cuerpo entero.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31071, 11320, '3. PET-TC', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31072, 11320, '4. Gastroscopia + colonoscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31073, 11320, '5. Una PAAF.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31074, 11321, '1. T. mamarios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31075, 11321, '2. T. pulmonares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31076, 11321, '3. T. gastrointestinales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31077, 11321, '4. T. prostáticos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31078, 11321, '5. Melanomas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31079, 11322, '1. El diagnóstico diferencial entre masa sólida y quística se realizará mediante ecografía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31080, 11322, '2. Se debe establecer el diagnóstico diferencial entre hiperplasia nodular focal y el adenoma hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31081, 11322, '3. El hemangioma cavernoso se diagnostica por resonancia con contraste de gadolinio al ser muy intenso en T2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31082, 11322, '4. El tratamiento de elección de la hiperplasia nodular focal es quirúrgico por la posibilidad de malignidad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31083, 11322, '5. La biopsia hepática de la lesión será de utilidad para instaurar una terapia no quirúrgica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31084, 11323, '1. Litiasis intrahepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31533, 11423, '3. Sublingual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31085, 11323, '2. Parasitosis por Clonorchis Sinensis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31086, 11323, '3. Colangitis esclerosante primaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31087, 11323, '4. Hemocromatosis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31088, 11323, '5. Enfermedad de Caroli.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31089, 11324, '1. Hepatopatía alcohólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31090, 11324, '2. Hepatitis A.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31091, 11324, '3. Hepatitis B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31092, 11324, '4. Hemocromatosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31093, 11324, '5. Déficit de la alfa-1 antitripsina', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31094, 11325, '1. El patrón hipervascular es característico de angioma, por lo que no es precisa la realización de nuevas exploraciones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31095, 11325, '2. Los hallazgos son muy sugerentes de carcinoma hepatocelular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31096, 11325, '3. Dado que la presencia de varices y ascitis indican la presencia de hipertensión portal significativa, la resección de la lesión no es aconsejable.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31097, 11325, '4. El trasplante hepático es una opción terapéutica en este paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31098, 11325, '5. La ausencia de invasión vascular es un signo de buen pronóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31099, 11326, '1. Colecistitis aguda e indicación de colecistectomía urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31100, 11326, '2. Coledocolitiasis distal y solicitud de colangiorresonancia magnética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31101, 11326, '3. Toxicidad por fármacos y suspensión de la medicación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31102, 11326, '4. Tumoración maligna obstructiva de colédoco distal y solicitar TC abdominal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31103, 11327, '1. Microlitiasis por alto riesgo de pancreatitis aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31104, 11327, '2. Litiasis biliar de más de 2,5 cm de diámetro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31105, 11327, '3. Vesícula con paredes calcificadas en porcelana.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31106, 11327, '4. Presencia de cálculos de bilirrubina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31107, 11328, '1. A pesar de que nunca ha tenido síntomas de origen biliar está indicada la colecistectomía como prevención del cáncer de vesícula biliar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31108, 11328, '2. Dado que está asintomático y no tiene riesgo aumentado de cáncer de vesícula biliar no se recomienda la colecistectomía y no es preciso seguimiento por este motivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31109, 11328, '3. La imagen no es suficientemente concluyente como para tomar una decisión terapéutica. Sería necesario ampliar el estudio con RM y/o PET/TC.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31110, 11328, '4. No está indicada la colecistectomía por estar asintomático, pero sí el seguimiento periódico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31111, 11329, '1. Toxicidad por fármacos. Retirada del antibiótico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31112, 11329, '2. Colecistitis aguda. Colecistectomía urgente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31113, 11329, '3. Coledocolitiasis distal. Solicitar una colangiorresonancia magnética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31114, 11329, '4. Tumoración maligna obstructiva de colédoco distal. Solicitar una TC abdominal para estudio de extensión local y a distancia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31115, 11330, '1. Colecistitis aguda.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31116, 11330, '2. Enfermedad de Caroli.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31117, 11330, '3. Vesícula en porcelana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31118, 11330, '4. Cólico biliar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31119, 11331, '1. Colangiografía retrógrada endoscópica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31120, 11331, '2. Ecoendoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31121, 11331, '3. Colangiografía transparietohepática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31122, 11331, '4. Colangiorresonancia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31123, 11332, '1. Colecistitis enfisematosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31124, 11332, '2. Fitobezoar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31125, 11332, '3. Íleo biliar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31126, 11332, '4. Colitis isquémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31127, 11333, '1. Colecistectomía laparoscópica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31128, 11333, '2. Sonda nasogástrica descompresiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31129, 11333, '3. Enterolitotomía quirúrgica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31130, 11333, '4. Resección segmentaria de ileon terminal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31131, 11334, '1. Colecistitis aguda alitiásica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31132, 11334, '2. Coledocolitiasis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31133, 11334, '3. Colecistitis aguda litiásica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31134, 11334, '4. Colangitis ascendente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31135, 11335, '1. Hemolisis crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31136, 11335, '2. Anemia perniciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31137, 11335, '3. Infección crónica de vías biliares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31138, 11335, '4. Colangitis biliar primaria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31139, 11336, '1. Cirugía urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31140, 11336, '2. Colangiorresonancia magnética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31141, 11336, '3. TC abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31142, 11336, '4. Colangiopancreatografía endoscópica con esfinterotomía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31143, 11337, '1. Es una prueba sensible, económica, fiable y reproducible.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31144, 11337, '2. Se considera la prueba de elección de la evaluación inicial de ictericia o síntomas de enfermedad biliar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31145, 11337, '3. Facilita el diagnóstico de colecistitis aguda cuando hay engrosa miento de la pared vesicular y líquido pericolecístico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31146, 11337, '4. Permite distinguir los cálculos vesiculares (no dejan sombra posterior) de pólipos de vesícula (dejan una sombra evidente).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31147, 11338, '1. Síndrome de Mirizzi', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31148, 11338, '2. Neoplasia de páncreas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31149, 11338, '3. Coledocolitiasis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31150, 11338, '4. Estenosis postquirúrgica del colédoco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31151, 11339, '1. La ecografía muestra una vesícula biliar distendida, de paredes engrosadas y edematosas, con litiasis infundibular. Estos hallazgos sugieren el diagnóstico de colecistitis aguda litiásica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31152, 11339, '2. La ecografía muestra una vesícula biliar distendida, de paredes engrosadas y edematosas, sin evidencia de litiasis vesicular. Estos hallazgos sugieren el diagnóstico de colecistitis aguda alitiásica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31153, 11339, '3. La ecografía muestra una vesícula biliar poco distendida de paredes engrosadas (por su poca distensión) sin evidencia de litiasis. Estos hallazgos excluyen el diagnóstico de colecistitis aguda litiásica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31154, 11339, '4. En este contexto clínico, la primera prueba a realizarse debería ser siempre la TC abdominal pues muestra mayor sensibilidad en la detección de litiasis vesicular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31155, 11340, '1. Litiasis biliar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31156, 11340, '2. Alcoholismo crónico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31534, 11423, '4. Intramuscular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31157, 11340, '3. Vesícula en porcelana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31158, 11340, '4. Pólipo vesicular de 15 mm.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31159, 11341, '1. Mantener tratamiento antibiótico y medidas de soporte con colecistectomía reglada posterior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31160, 11341, '2. Colecistectomía laparoscópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31161, 11341, '3. Colocación de un drenaje biliar externo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31162, 11341, '4. Colecistectomía urgente con canulación del colédoco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31163, 11341, '5. Colangiopancreatografía retrógrada endoscópica con esfinterotomía.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31164, 11342, '1. Ecografía hepatobiliar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31165, 11342, '2. Colangiopancreatografia retrógrada endoscópica (CPRE).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31166, 11342, '3. Colangio Resonancia Magnética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31167, 11342, '4. Tomografía computerizada. TC abdominal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31168, 11342, '5. Colangiografía transhepática percutánea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31169, 11343, '1. Vesícula biliar distendida con litiasis en su interior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31170, 11343, '2. Engrosamiento de la pared de la vesícula biliar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31171, 11343, '3. Inflamación hipoecoica de la cabeza del páncreas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31172, 11343, '4. Litiasis y dilatación del colédoco.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31173, 11343, '5. Aumento de calibre de la vena cava.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31174, 11344, '1. Cirugía abierta urgente de la vía biliar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31175, 11344, '2. Antibioterapia y medidas sintomáticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31176, 11344, '3. Colangiografía retrógrada endoscópica con papilotomía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31177, 11344, '4. Plantear colecistectomía diferida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31178, 11344, '5. Solicitar una ecoendoscopia para valorar el páncreas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31179, 11345, '1. Tratamiento quirúrgico (colecistectomía) urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31180, 11345, '2. Drenaje biliar mediante colecistostomía percutánea.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31181, 11345, '3. Sustituir la piperacilina/tazobactam por metronidazol + cefotaxima.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31182, 11345, '4. Sustituir la piperacilina/tazobactam por amikacina + clindamicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31183, 11345, '5. Añadir al tratamiento un aminoglucósido como gentamicina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31184, 11346, '1. Oxígeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31185, 11346, '2. Argón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31186, 11346, '3. Óxido nítrico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31187, 11346, '4. Helio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31188, 11346, '5. Anhídrido carbónico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31189, 11347, '1. Carcinoma pancreático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31190, 11347, '2. Litiasis vesicular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31191, 11347, '3. Colecistitis crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31192, 11347, '4. Ampuloma.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31193, 11347, '5. Colangiocarcinoma intrahepático', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31194, 11348, '1. La presentación clásica se caracteriza por fiebre alta, ictericia y dolor abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31195, 11348, '2. Una causa frecuente de colangitis es la estenosis maligna del colédoco.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31196, 11348, '3. Es obligatoria la hospitalización, reposición hidroelectrolítica, soporte general y terapéutica antibiótica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31197, 11348, '4. La endoscopia precoz permite el diagnóstico por colangiografía y el drenaje de la vía biliar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31198, 11348, '5. La cirugía de drenaje de la vía biliar se realiza cuando no son posibles otras opciones.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31199, 11349, '1. La reducción de la estancia hospitalaria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31200, 11349, '2. Permite conservar la vesícula.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31201, 11349, '3. No se asocia a lesiones de la vía biliar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31202, 11349, '4. Es una técnica exenta de mortalidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31203, 11349, '5. Es siempre posible realizarla mediante el abordaje laparoscópico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31204, 11350, '1. Colelitiasis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31205, 11350, '2. Úlcera de boca anastomótica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31206, 11350, '3. Obstrucción intestinal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31207, 11350, '4. Hepatopatía por síndrome malabsortivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31208, 11350, '5. Úlcera duodenal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31209, 11351, '1. Coledocolitiasis residual.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31210, 11351, '2. Estenosis iatrogénica de la vía biliar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31211, 11351, '3. Hepatitis colestásica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31212, 11351, '4. Colangiocarcinoma hiliar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31213, 11351, '5. Colangitis esclerosante.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31214, 11352, '1. Ictericia indolora.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31215, 11352, '2. Prurito.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31216, 11352, '3. Acolia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31217, 11352, '4. Distensión vesicular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31218, 11352, '5. Hepatomegalia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31219, 11353, '1. Estafilococo aureus.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31220, 11353, '2. Escherichia coli.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31221, 11353, '3. Bacteroides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31222, 11353, '4. Enterococo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31223, 11353, '5. Klebsiella.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31224, 11354, '1. Tumoración en cola pancreática con calcificaciones e invasión tumoral de arteria esplénica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31225, 11354, '2. Calcificaciones pancreáticas difusas en cuerpo y cola pancreática, indicativas de pancreatitis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31226, 11354, '3. Tumoración en cabeza pancreática con calcificaciones e invasión tumoral de arteria esplénica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31227, 11354, '4. Calcificaciones pancreáticas difusas en cuerpo y cola pancreática, indicativas de pancreatitis crónica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31228, 11355, '1. Ensanchamiento del marco duodenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31229, 11355, '2. Áreas focales de necrosis pancreática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31230, 11355, '3. Aumento en el realce glandular en fase arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31231, 11355, '4. Dilatación de conducto pancreático.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31232, 11356, '1. El cuadro clínico sugiere una colangitis aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31233, 11356, '2. El paciente tiene probablemente una isquemia mesentérica aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31234, 11356, '3. No es necesario realizar prueba de imagen en urgencias o en todo caso una ecografía abdominal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31235, 11356, '4. Es preciso realizar una TC abdominal urgente', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31236, 11357, '1. Hamartoma pancreático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31237, 11357, '2. Pancreatitis autoinmune.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31238, 11357, '3. Malacoplaquia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31239, 11357, '4. Pancreatitis del surco', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31240, 11358, '1. El anticuerpo anticitoplasma de los neutrófilos (ANCA).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31241, 11358, '2. El anticuerpo antimitocondrial (AMA).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31242, 11358, '3. El anticuerpo antimicrosomal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31243, 11358, '4. El nivel de Ig G4.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31244, 11359, '1. La reanimación mediante fluidoterapia enérgica es básica en el tratamiento.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31245, 11359, '2. Debe administrarse desde el inicio antibioterapia con fines profilácticos para evitar la necrosis infectada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31246, 11359, '3. La nutrición parenteral total está indicada a partir de las 48-72 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31247, 11359, '4. El uso de inhibidores de la proteasa (aprotinina) ha demostrado un efecto beneficioso en estos casos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31248, 11360, '1. Pseudoquiste pancreático con ascitis pancreática.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31249, 11360, '2. Neoplasia quística pancreática con ascitis porcarcinomatosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31250, 11360, '3. Peritonitis secundaria por perforación del tubo digestivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31251, 11360, '4. Descompensación ascítica en paciente con hepatopatía crónica avanzada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31252, 11361, '1. Determinación serológica de IgG4.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31253, 11361, '2. PET-TAC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31254, 11361, '3. Gammagrafía con octreótido marcado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31255, 11361, '4. Radiografía de tórax.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31256, 11361, '5. Estudio serológico de Virus de la Inmunodeficiencia Humana (VIH).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31257, 11362, '1. Tomografia axial computarizada (TAC) del abdomen.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31258, 11362, '2. Creatinina en sangre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31259, 11362, '3. Niveles de amilasa y lipasa en sangre.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31260, 11362, '4. Hematocrito.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31261, 11362, '5. Nitrógeno ureico en sangre (BUN).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31262, 11363, '1. Punción aspiración con aguja fina de necrosis pancreática guiada por ecografía o TAC.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31263, 11363, '2. Aspirado broncoalveolar, cultivo de orina y hemocultivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31264, 11363, '3. Resonancia Magnética Nuclear abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31265, 11363, '4. Colecistectomía urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31266, 11363, '5. Ecoendoscopia con punción de la necrosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31267, 11364, '1. Glucemia > 200 mg/dl.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31268, 11364, '2. Leucocitosis > 16.000/mm3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31269, 11364, '3. Edad < 55 años.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31270, 11364, '4. LDH sérica > 350 UI/L.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31271, 11364, '5. GOT sérica > 250 UI/L.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31272, 11365, '1. Litiasis vesicular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31273, 11365, '2. Hipertrigliceridemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31274, 11365, '3. Alcohol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31275, 11365, '4. Hipercolesterolemia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31276, 11365, '5. Traumatismo abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31277, 11366, '1. Amilasemia > 3.000 UI/L.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31278, 11366, '2. Criterios de Ranson >3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31279, 11366, '3. Apache II >10.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31280, 11366, '4. PCR >150 mgl/L (a partir de las 48 h. del inicio de los síntomas).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31281, 11366, '5. Score de TAC abdominal >7 (a partir de las 72)', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31282, 11367, '1. Esperar evolución clínica de 4-6 semanas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31283, 11367, '2. Somatostatina (perfusion iv) u octreotido sc.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31284, 11367, '3. Drenaje quirúrgico interno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31285, 11367, '4. Drenaje endoscópico guiado por ecoendoscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31286, 11367, '5. Drenaje percutáneo guiado por ECO/TC abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31287, 11368, '1. El paciente explica pérdida de apetito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31288, 11368, '2. Se le detecta hiperglicemia en varias analíticas realizadas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31289, 11368, '3. El paciente refiere deposiciones amarillentas y brillantes con pérdida de peso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31290, 11368, '4. Su enfermedad ya lleva muchos años de evolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31291, 11368, '5. El paciente se queja de dolor incapacitante.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31292, 11369, '1. Iniciar tratamiento antibiótico y mantener actitud conservadora.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31293, 11369, '2. Cambiar la nutrición parenteral por enteral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31294, 11369, '3. Tratamiento quirúrgico: desbridamiento o necrosectomía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31295, 11369, '4. Iniciar tratamiento con un inhibidor de las proteasas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31296, 11369, '5. Aumentar el tratamiento analgésico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31297, 11370, '1. Hipocalcemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31298, 11370, '2. Hipomagnesemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31299, 11370, '3. Hipercolesterolemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31300, 11370, '4. Hipertrigliceridemia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31301, 11370, '5. Hipopotasemia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31302, 11371, '1. Punción drenaje del seudoquiste.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31303, 11371, '2. Resección quirúrgica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31304, 11371, '3. Antibioterapia de amplio espectro durante 10 días y volver a realizar una ecografía abdominal para plantear la posibilidad del drenaje del seudoquiste.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31305, 11371, '4. Actitud expectante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31306, 11371, '5. Solicitaría un TAC abdominal con contraste para descartar la existencia de comunicación con el conducto pancreático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31307, 11372, '1. Doble derivación bilio-digestiva.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31308, 11372, '2. Intervención de Whipple.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31309, 11372, '3. Intervención de Puestow.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31310, 11372, '4. Coledocoduodenostomía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31311, 11373, '1. Neoplasia mucinosa quística.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31312, 11373, '2. Neoplasia mucinosa papilar intraductal de rama secundaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31313, 11373, '3. Neoplasia sólida-pseudopapilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31314, 11373, '4. Neoplasia mucinosa papilar intraductal con componente invasivo de rama principal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31315, 11374, '1. Colangitis esclerosante primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31316, 11374, '2. Coledocolitiasis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31317, 11374, '3. Cáncer de páncreas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31318, 11374, '4. Hepatitis aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31319, 11375, '1. Adenocarcinoma ductal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31320, 11375, '2. Cistadenoma seroso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31321, 11375, '3. Neoplasia mucinosa quística.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31322, 11375, '4. Pancreatitis autoinmune asociada a enfermedad por IgG4.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31323, 11376, '1. Sigmoidectomía laparoscópica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31324, 11376, '2. Tratamiento conservador con fibra dietética y rifaximina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31325, 11376, '3. Dilatación endoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31326, 11376, '4. Stent en zona de estenosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31327, 11377, '1. Es una presentación clínica infrecuente (menor del 10 %).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31328, 11377, '2. Tiene una supervivencia mediana inferior a 3 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31329, 11377, '3. Es candidato a quimio-radioterapia neoadyuvante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31330, 11377, '4. Es mínimamente sintomático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31331, 11378, '1. Resección quirúrgica (pancreatectomía corporocaudal).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31332, 11378, '2. Punción guiada mediante ultrasonografía endoscópica y etanolización de la misma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31333, 11378, '3. Seguimiento de la lesión mediante RM.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31334, 11378, '4. Trasplante de riñón-páncreas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31335, 11379, '1. Los pacientes con diabetes de larga evolución tienen un riesgo superior al 50% de desarrollar cáncer de páncreas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31336, 11379, '2. La diabetes está presente en un tercio de los pacientes con cáncer de páncreas avanzado y en muchos de ellos es de instauración reciente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31337, 11379, '3. En la mayoría de pacientes con cáncer de páncreas, la diabetes se instaura cuando aparece ictericia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31338, 11379, '4. La diabetes desaparece después de la exéresis del tumor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31339, 11380, '1. PET-TC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31340, 11380, '2. Ecoendoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31341, 11380, '3. TC toraco-abdomino-pélvico con contraste.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31342, 11380, '4. Colangiopancreatografía retrógada endoscópica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31343, 11381, '1. La duodenopancreatectomía cefálica con linfadenectomía regional.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31344, 11381, '2. La pancreaticoyeyunostomía, que consiste en la derivación del dueto pancreático al intestino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31345, 11381, '3. La pancreatectomía corporocaudal por laparoscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31346, 11381, '4. La enucleación del tumor sin necesidad de linfadenectomía', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31347, 11382, '1. Los factores de riesgo implicados en esta neoplasia incluyen tabaquismo, obesidad y pancreatitis aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31348, 11382, '2. La prueba diagnóstica de imagen más adecuada es la TChelicoidal sin contraste y doble fase.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31349, 11382, '3. Es necesaria la confirmación diagnóstica anatomopatológica preoperatoria antes de realizar el tratamiento quirúrgico con finalidad curativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31350, 11382, '4. La alteración genética detectada con más frecuencia es la delección del gen p16.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31351, 11383, '1. Vena mesentérica superior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31352, 11383, '2. Vena coronaria estomáquica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31353, 11383, '3. Vena esplénica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31354, 11383, '4. Vena porta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31355, 11384, '1. La estadificación local puede realizarse con RM y TC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31356, 11384, '2. La invasión tumoral arterial es un criterio de irresecabilidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31357, 11384, '3. La infiltración focal de la vena mesentérica superior no es una contraindicación a la cirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31358, 11384, '4. La biopsia preoperatoria de los tumores pancreáticos es habitualmente necesaria para decidir el tratamiento quirúrgico. Solución', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31359, 11385, '1. Se consideran lesiones premalignas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31360, 11385, '2. Pueden afectar tanto al conducto pancreático principal como a las ramas secundarias y se caracterizan por presentar epitelio productor de mucina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31361, 11385, '3. La presencia de nódulos en la pared de la lesión no constituye un signo de alarma.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31362, 11385, '4. Cuando afecta a las ramas secundarias, la resección quirúrgica está indicada si es mayor de 3 cm.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31363, 11386, '1. Son tumores potencialmente malignos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31364, 11386, '2. Su frecuencia se ha incrementado notablemente en la última década.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31365, 11386, '3. Se distinguen tres subtipos: de conducto principal, de conducto secundario y mixto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31366, 11386, '4. Deben ser extirpados tan pronto como se diagnostiquen, excepto la variedad de conducto principal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31367, 11386, '5. Su primera manifestación clínica puede ser un cuadro de pancreatitis aguda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31368, 11387, '1. Se observa una masa tumoral en cabeza de páncreas que condiciona dilatación biliar y ductal compatible con adenocarcinoma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31369, 11387, '2. Presencia de engrosamiento difuso del páncreas con Wirsung arrosariado compatible con pancreatitis linfoplasmocitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31370, 11387, '3. Se identifica una masa tumoral en infundíbulo vesicular compatible con adenocarcinoma vesicular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31371, 11387, '4. Se observan voluminosas adenopatías tumorales en hilio hepático que producen dilatación de la vía biliar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31372, 11387, '5. Presencia de múltiples lesiones focales hepáticas sólidas compatibles con metástasis hepáticas difusas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31373, 11388, '1. Drenaje biliar por vía endoscópica retrógrada y quimioterapia sistémica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31374, 11388, '2. Duodenopancretectomía cefálica con resección vascular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31375, 11388, '3. Embolización hepática con esferas cargadas de quimioterapia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31376, 11388, '4. Drenaje biliar transparieto-hepático y quimioterapia sistémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31377, 11388, '5. Tratamiento con corticoides.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31378, 11389, '1. El tumor papilar mucinoso intraductal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31379, 11389, '2. El carcinoma neuroendocrino de páncreas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31380, 11389, '3. El cistoadenocarcinoma de páncreas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31381, 11389, '4. El insulinoma maligno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31382, 11389, '5. El adenocarcinoma ductal de páncreas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31383, 11390, '1. Diabetes, pérdida de peso y diarrea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31384, 11390, '2. Dolor epigástrico, ictericia y pérdida de peso.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31385, 11390, '3. Dolor en hipocondrio derecho, ictericia y fiebre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31386, 11390, '4. Anorexia, diarrea y pérdida de peso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31387, 11390, '5. Náuseas, dolor abdominal e ictericia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31388, 11391, '1. Estómago.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31389, 11391, '2. Vesícula.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31390, 11391, '3. Hígado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31391, 11391, '4. Páncreas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31392, 11391, '5. Colon.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31393, 11392, '1. CA 15.3.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31395, 11392, '3. Alfa-fetoproteína.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31396, 11392, '4. CA 19.9.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31397, 11392, '5. Gonadotropina.', false, 5);
