INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31399, 11393, '2. Apendicitis mesoceliaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31400, 11393, '3. Apendicitis retrocecal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31401, 11393, '4. Apendicitis medioinguinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31402, 11394, '1. Absceso en fondo de saco de Douglas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31403, 11394, '2. Infección de la herida quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31404, 11394, '3. Infección urinaria complicada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31405, 11394, '4. Absceso hepático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31406, 11395, '1. Apendicectomía urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31407, 11395, '2. Antibioterapia, drenaje percutáneo de la colección y programar apendicectomía en 12 semanas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31408, 11395, '3. Intervención urgente con hemicolectomía derecha y resección intestinal con drenaje de absceso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31409, 11395, '4. Aspiración nasogástrica, fluidoterapia iv, ertapenem iv y reevaluación en una semana.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31410, 11396, '1. Realización de una anamnesis completa y exploración física minuciosa', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31411, 11396, '2. Valoración del hemograma, especialmente el recuento y fórmula leucocitarios', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31412, 11396, '3. Valoración de los resultados obtenidos en la ecografía de abdomen', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31413, 11396, '4. Valoración de los resultados obtenidos en la TC abdominal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31414, 11397, '1. Dolor a la presión en epigastrio al aplicar una presión firme y persistente sobre el punto de McBurney', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31415, 11397, '2. Dolor agudo que aparece al comprimir el apéndice entre la pared abdominal y la cresta ilíaca', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31416, 11397, '3. Sensibilidad de rebote pasajera en la pared abdominal', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31417, 11397, '4. Pérdida de la sensibilidad abdominal al contraer los músculos de la pared abdominal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31418, 11397, '5. Dolor en el punto de McBurney al comprimir el cuadrante inferior izquierdo del abdomen', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31419, 11398, '1. Descompensación hidrópica secundaria a cirrosis hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31420, 11398, '2. Ascitis quilosa por linfoma no Hodgkin.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31421, 11398, '3. Tuberculosis peritoneal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31422, 11398, '4. Metástasis peritoneal de adenocarcinoma.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31423, 11398, '5. Ascitis secundaria a pericarditis constrictiva', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31424, 11399, '1. El dolor visceral se transmite por el sistema autónomo simpático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31425, 11399, '2. El dolor visceral es definido como profundo y difícil de localizar por el paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31426, 11399, '3. El dolor visceral suele referirse a la línea media del abdomen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31427, 11399, '4. El peritoneo visceral es sensible al estiramiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31428, 11399, '5. El peritoneo visceral es sensible a estímulos térmicos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31429, 11400, '1. La tomografía computarizada con contraste I.V', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31430, 11400, '2. La radiografía simple de abdomen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31431, 11400, '3. La ecografía abdominal', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31432, 11400, '4. La ecografía transvaginal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31433, 11400, '5. La tomografía computarizada sin contraste I.V', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31434, 11401, '1. La cirugía laparoscópica sólo está indicada para la colecistectomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31435, 11401, '2. La laparoscopia sólo sirve para el diagnóstico en casos de apendicitis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31436, 11401, '3. La apendicitis aguda sin peritonitis puede tratarse por laparoscopia y puede ofrecer algunas ventajas sobre la laparotomía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31437, 11401, '4. La apendicitis aguda es una contraindicación absoluta para el abordaje laparoscópico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31438, 11401, '5. La única indicación de cirugía laparoscópica es el plastrón inflamatorio palpable en fosa iliaca derecha.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31439, 11402, '1. Hernia inguinal directa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31440, 11402, '2. Hernia inguinal indirecta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31441, 11402, '3. Hernia obturatriz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31442, 11402, '4. Hernia crural.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31443, 11403, '1. La división del ligamento de Treitz.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31444, 11403, '2. La duodenoyeyunostomía.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31445, 11403, '3. El cambio de la posición del duodeno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31446, 11403, '4. El bypass de la arteria mesentérica superior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31447, 11404, '1. Detorsión endoscópica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31448, 11404, '2. Colectomía segmentaria y Hartmann.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31449, 11404, '3. Colectomía segmentaria y anastomosis colorrectal laparoscópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31450, 11404, '4. Detorsión quirúrgica y pexia de sigmoides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31451, 11405, '5. Múltiples estenosis y ulceraciones del intestino delgado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31452, 11405, '6. Hipertensión portal secundaria con estasis venoso intestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31453, 11405, '7. Propulsión ineficaz del contenido del intestino delgado con dolor y distensión abdominal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31454, 11405, '8. Relajación defectuosa del esfínter anal con evacuación dificultosa de heces.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31455, 11406, '1. Hemorragia de órganos sólidos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31456, 11406, '2. Íleo paralítico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31457, 11406, '3. Hernia en los orificios de acceso abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31458, 11406, '4. Neumomediastino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31459, 11407, '1. Realizar TC abdominal por sospecha de diverticulitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31460, 11407, '2. Realización urgente de arteriografía por sospecha de isquemia mesentérica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31461, 11407, '3. Desvolvulación por endoscopia digestiva baja.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31462, 11407, '4. Infusión de neostigmina bajo control hemodinámico por Síndrome de Ogilvie.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31463, 11408, '1. Vólvulo de sigma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31464, 11408, '2. Síndrome de Ogilvie.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31465, 11408, '3. Oclusión intestinal por bridas, en relación a la cirugía previa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31466, 11408, '4. Obstrucción intestinal por neoplasia de ciego.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31467, 11409, '1. Se trata de un cuadro de obstrucción intestinal por bridas que requiere laparotomía de urgencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31468, 11409, '2. Lo más probable es que nos encontremos ante un caso de obstrucción a nivel de intestino grueso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31535, 11423, '5. Subcutánea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31967, 11518, '3. Sertralina', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31469, 11409, '3. El hecho de que la paciente haya presentado una deposición diarreica nos permite excluir el diagnóstico de obstrucción intestinal. Son necesarios más estudios de imagen para asegurar un diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31470, 11409, '4. Deberíamos indicar la práctica de una colonoscopia descompresiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31471, 11409, '5. El manejo inicial debe ser conservador, con sueroterapia, aspiración nasogástrica y vigilancia clínica, analítica y radiográfica periódica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31472, 11410, '1. Estreñimiento secundario a tratamiento con hierro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31473, 11410, '2. Pancreatitis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31474, 11410, '3. Gastritis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31475, 11410, '4. Ileo paralítico secundario a alteraciones iónicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31476, 11410, '5. Obstrucción intestinal mecánica a nivel de íleon distal o ciego.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31477, 11411, '1. Dieta absoluta, sonda con aspiracion nasogástrica y sueroterapia con ClK. Solicitar TAC abdominal, urgente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31478, 11411, '2. Enemas de limpieza hasta resolución del cuadro. Repetir Rx de control.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31479, 11411, '3. Sueroterapia con Bicarbonato 1/6 M, ClNa y ClK intravenosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31480, 11411, '4. Dieta absoluta 8 h, probar tolerancia y alta a domicilio con lactulosa y domperidona vía oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31481, 11411, '5. Analgesia y omeprazol intravenoso. Si no mejora valorar gastroscopia urgente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31482, 11412, '1. Siguen siendo las hernias, suponiendo un 60% de las causas de íleo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31483, 11412, '2. Las tumoraciones malignas, que suponen un 60% de las causas de íleo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31484, 11412, '3. El síndrome adherencial postoperatorio, que supone el 60% de las causas de íleo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31485, 11412, '4. Los vólvulos e invaginaciones, que sumados en niños y adultos suponen un 60% de las causas de íleo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31486, 11412, '5. Los síndromes metabólicos tipo diabetes y otros, lo que sumado a la pluripatología y ancianidad de los pacientes quirúrgicos actuales suponen un 60% de las causas de íleo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31487, 11413, '1. Neoplasia de colon.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31488, 11413, '2. Eventración abdominal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31489, 11413, '3. Perforación de víscera hueca.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31490, 11413, '4. Isquemia mesentérica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31491, 11414, '1. Resección de la tumoración para análisis anatomopatológico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31492, 11414, '2. Colocación de una prótesis mediante un abordaje endovascular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31493, 11414, '3. Realización de una derivación o bypass a nivel de la lesión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31494, 11414, '4. Reparación del defecto herniario con una prótesis para evitar tensión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31495, 11415, '1. Hernia complicada de pared abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31496, 11415, '2. Seroma post-quirúrgico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31497, 11415, '3. Absceso en la vaina del recto anterior izquierdo del abdomen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31498, 11415, '4. Hematoma en la vaina del recto anterior izquierdo del abdomen.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31499, 11416, '1. Hernia umbilical.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31500, 11416, '2. Hernia inguinal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31501, 11416, '3. Hernia crural o femoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31502, 11416, '4. Hernia de Spiegel.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31503, 11417, '1. Debe realizarse una ecografía para confirmar el diagnóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31504, 11417, '2. La exploración física debe realizarse tanto en decúbito supino como en bipedestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31505, 11417, '3. Es altamente probable que se trate de una hernia inguinal indirecta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31506, 11417, '4. En caso de tratamiento quirúrgico la técnica de elección sería una reparación sin tensión con una malla protésica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31507, 11418, '1. Hernia inguinal directa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31508, 11418, '2. Hernia de Spiegel.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31509, 11418, '3. Hernia inguinal indirecta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31510, 11418, '4. Hernia femoral (crural).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31511, 11418, '5. Hernia obturatriz.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31512, 11419, '1. La hernia estrangulada se reduce con la manipulación y la incarcerada no.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31513, 11419, '2. La hernia incarcerada se caracteriza por cursar con interrupción del tránsito intestinal y la estrangulada no.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31514, 11419, '3. La hernia estrangulada cursa con alteración de la circulación sanguínea del contenido herniario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31515, 11419, '4. La estrangulación es más frecuente en las hernias inguinales directas y la incarceración en las indirectas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31516, 11419, '5. La hernia incarcerada se caracteriza por cursar con dolor intenso y permanente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31517, 11420, '1. Ante una hernia incarcerada está indicada la intervención quirúrgica urgente, ya que por definición presentan compromiso vascular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31518, 11420, '2. Actualmente las técnicas de reparación herniaria más generalizadas son aquellas que emplean material protésico, como la hernio- plastia tipo Liechtenstein.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31519, 11420, '3. Una hernia es de tipo indirecto si el saco herniario sale de la cavidad abdominal a través del orificio inguinal profundo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31520, 11420, '4. Las hernias crurales presentan mayor riesgo de incarceración que las inguinales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31521, 11420, '5. Las hernias de tipo directo se deben a la debilidad de la fascia transversalis, y aparecen mediales a los vasos epigástricos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31522, 11421, '1. Administración intravenosa de suero fisiológico con cloruro amónico para facilitar la eliminación renal del metotrexato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31523, 11421, '2. Administración intravenosa de solución de bicarbonato sódico para acelerar la diuresis del metotrexato.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31524, 11421, '3. Administración enteral de solución de bicarbonato sódico para reducir la absorción digestiva del metotrexato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31525, 11421, '4. Administración intravenosa de furosemida en suero con pH neutro para provocar una diuresis forzada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31526, 11422, '1. Un fármaco cabeza de serie de una clase terapéutica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31527, 11422, '2. Un fármaco que ha sido retirado del mercado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31528, 11422, '3. Un producto inactivo que se convierte enzimáticamente en un fármaco activo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31529, 11422, '4. Un compuesto de origen natural del que se obtienen uno o más fármacos por hemisíntesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31530, 11422, '5. Un fármaco que carece de actividad pero potencia la acción de otros.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31531, 11423, '1. Intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31532, 11423, '2. Rectal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31536, 11424, '1. La biodisponibilidad de un fármaco es diferente según la vía de administración utilizada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31537, 11424, '2. La forma farmacéutica puede modificar la velocidad de absorción de un fármaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31538, 11424, '3. Fármacos con importante metabolismo hepático de primer paso, tienen alta biodisponibilidad oral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31539, 11424, '4. La alcalinización de la orina aumenta el aclaramiento renal de fenobarbital (ácido débil)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31540, 11424, '5. La acidificación de la orina aumenta la eliminación renal de anfetamina (base débil).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31541, 11425, '1. Que el 25% del fármaco es metabolizado en el hígado', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31542, 11425, '2. Que el 25% del fármaco no es eliminado presistémicamente', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31543, 11425, '3. Que hemos administrado el 75% de la dosis', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31544, 11425, '4. Que el 75% del fármaco administrado accede a la circulación sistémica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31545, 11425, '5. Que hemos administrado un 75% más de la dosis recomendada', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31546, 11426, '1. Distintos fármacos pueden competir por un mismo mecanismo de absorción', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31547, 11426, '2. El orden cinético más frecuente es el 1', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31548, 11426, '3. La parte ionizada de un fármaco es la que se absorbe', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31549, 11426, '4. La velocidad de absorción de un fármaco se puede modificar alterando el pH del líquido en el que está disuelto', false, 4);
