INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31560, 11429, '1. Independiente del flujo sanguíneo en dicho tejido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31561, 11429, '2. Independiente de la solubilidad del fármaco en el tejido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31562, 11429, '3. Dependiente del desnivel de concentración de fármaco entre la sangre y el tejido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31563, 11429, '4. Acelerada para aquellos fármacos que se unen fuertemente a las proteínas plasmáticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31564, 11429, '5. Indiferente por lo que respecta a la vida media del fármaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31565, 11430, '1. La fracción de dosis que llega a la circulación general.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31566, 11430, '2. La concentración de fármaco que llega a la biofase.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31567, 11430, '3. La fracción de dosis indispensable para la consecución del efecto farmacológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31568, 11430, '4. La fracción de dosis que llega inalterada a la circulación general.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31569, 11430, '5. La fracción de dosis que no se metaboliza.', false, 5);
