INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31571, 11431, '2. La cantidad total de principio activo administrada en 24 horas', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31572, 11431, '3. La cantidad total de fármaco disponible para ser eliminado en 24 horas', false, 3);
