INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31574, 11431, '5. Las formas en que el fármaco está disponible (tabletas, inyectable, polvo, etc.)', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31575, 11432, '1. Requiere un periodo de latencia de días', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31576, 11432, '2. No es preciso que el inductor sea sustrato de enzima inducido', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31577, 11432, '3. Es un mecanismo de tolerancia a la acción farmacológica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31578, 11432, '4. Contaminantes ambientales también pueden inducir la biotransformación de fármacos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31579, 11432, '5. Se origina por un cambio en la velocidad de las enzimas biotransformantes', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31580, 11433, '1. Inyección intramuscular', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31581, 11433, '2. Inyección subcutánea', false, 2);
