INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31585, 11434, '1. 1.6.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31586, 11434, '2. 2.4.', false, 2);
