INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31590, 11435, '1. Para demostrar la eficacia y seguridad de un medicamento genérico se deben realizar ensayos clinicos de bioequivalencia en pacientes que padecen una de las patologias para las que esta indicado.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31591, 11435, '2. El nombre del medicamento genérico suele coincidir con la denominación común internacional o la denominación oficial española del principio activo seguido del nombre del laboratorio farmacéutico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31592, 11435, '3. El medicamento genérico tiene el mismo principio activo que el fármaco de referencia pero pueden cambiar los excipientes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31593, 11435, '4. El medicamento genérico tiene que cumplir los mismos requisitos de calidad que los exigidos para cualquier otro medicamento (normas de correcta fabricación de medicamentos)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31594, 11436, '1. Contienen el mismo principio activo aunque cambien los excipientes', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31595, 11436, '2. Su vida media biológica, semivida o t1/2, no difiere en más de un 5%', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31596, 11436, '3. Los procesos de biotransformación metabólica tiene lugar a través de las mismas isoformas enzimáticas', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31597, 11436, '4. Presentan una biodisponibilidad similar', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31598, 11437, '1. La evaluación de la equivalencia en ensayos clínicos de eficacia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31599, 11437, '2. La evaluación de la similitud en ensayos clínicos de tolerancia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31600, 11437, '3. La equivalencia en el proceso de distribución de un fármaco y, por tanto, a la comprobación de que se encuentra con las mismas concentraciones en el lugar de acción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31601, 11437, '4. La evaluación de la equivalencia farmacocinética.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31602, 11437, '5. La comprobación de un efecto similar de los factores que influyen en la biodisponibilidad de un fármaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31677, 11454, '3. Metilfenidato a dosis bajas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31678, 11454, '4. Amitriptilina a dosis bajas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31603, 11438, '1. Para que se autorice la comercialización de un medicamento genérico suele ser necesario realizar un estudio de bioequivalencia en voluntarios sanos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31604, 11438, '2. El objetivo de los estudios de bioequivalencia es demostrar que dos formulaciones del mismo principio activo tienen la misma eficacia clínica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31605, 11438, '3. Las dos formulaciones a comparar deben de tener la misma composición cualitativa y cuantitativa en cuanto a principio activo, para que el producto pueda comercializarse.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31606, 11438, '4. Se suele emplear un diseño cruzado, de manera que un grupo de sujetos recibe primero la formulación de referencia y luego la del producto genérico, y el otro grupo la secuencia inversa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31607, 11438, '5. La variable principal de evaluación se basa en la cuantificación plasmática (o urinaria) del principio activo, tras la administración de las dos formulaciones.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31608, 11439, '1. Tras 16 horas del comienzo de la administración.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31609, 11439, '2. Tras 24 horas del comienzo de la administración.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31610, 11439, '3. Tras 32 horas del comienzo de la administración.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31611, 11439, '4. Tras 40 horas del comienzo de la administración.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31612, 11440, '1. El rango de concentración plasmática que se alcanza con un medicamento una vez transcurridas cinco vidas medias.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31613, 11440, '2. El nivel plasmático máximo esperable con un medicamento en tratamiento crónico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31614, 11440, '3. El área bajo la curva producida por cualquier dosis en el curso de un tratamiento crónico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31615, 11440, '4. El equivalente molar a la semivida de eliminación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31616, 11441, '1. En 3 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31617, 11441, '2. Entre 3 y 9 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31618, 11441, '3. Entre 12 y 15 días.', true, 3);
