INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31622, 11442, '2. La semivida de eliminación del fármaco y la dosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31623, 11442, '3. La semivida de eliminación del fármaco y el intervalo posológico.', false, 3);
