INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31625, 11442, '5. La semivida de eliminación del fármaco, el intervalo posológico y el número de dosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31626, 11443, '1. Los que tienen un margen terapéutico estrecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (31627, 11443, '2. En los que existe una buena relación entre la concentración plasmática y el efecto.', false, 2);
