INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32000, 11525, '1. Precisa para su control de determinaciones de litemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32001, 11525, '2. Es eficaz en el tratamiento del episodio maníaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32002, 11525, '3. Eleva los niveles de uricemia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32003, 11525, '4. Es eficaz en la profilaxis del trastorno bipolar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32004, 11525, '5. Puede aparecer, a largo plazo, toxicidad tiroidea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32005, 11526, '1. El litio se utiliza en los cuadros bipolares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32006, 11526, '2. Los IMAOS están indicados en depresiones atípicas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32007, 11526, '3. Los inhibidores de la recaptación de la serotonina son mejor tolerados que los antidepresivos tricíclicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32008, 11526, '4. El tiempo medio de mantenimiento de la medicación antidepresiva es de 6 semanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32009, 11527, '1. Clorpromacina', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32010, 11527, '2. Fluoxetina', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32011, 11527, '3. Bupropión', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32012, 11527, '4. Flunitrazepam', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32013, 11527, '5. Venlafaxina', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32014, 11528, '1. El uso de fármacos antipsicóticos en las fases maníacas conlleva el riesgo de inducir un viraje a la fase depresiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32015, 11528, '2. El uso de fármacos antidepresivos en la fase depresiva conlleva el riesgo de inducir un viraje a la fase maníaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32016, 11528, '3. En el tratamiento de mantenimiento de los pacientes bipolares se recomienda el uso de uno o más fármacos eutimizantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32017, 11528, '4. Los fármacos antiepilépticos no deben utilizarse en estos pacientes por el riesgo de que desarrollen una discinesia tardía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32018, 11529, '1. Aumentar la dosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32019, 11529, '2. Cambiar de antidepresivo por otro del mismo grupo terapéutico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32020, 11529, '3. Cambiar de antidepresivo por otro del grupo de los tricíclicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32021, 11529, '4. Esperar, ya que la respuesta terapéutica tarda aproximadamente 2 semanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32022, 11529, '5. Derivarlo al especialista.', false, 5);
