INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32033, 11532, '2. Parkinson.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32034, 11532, '3. Insomnio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32035, 11532, '4. Pseudotumor cerebral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32036, 11532, '5. Hipertrofia benigna prostática.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32037, 11533, '1. Se elimina casi en su totalidad por la orina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32038, 11533, '2. Se recomienda, entre otras pruebas, hacer ECG y creatininemia antes de iniciar el tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32039, 11533, '3. Se consideran niveles terapéuticos óptimos de litemia los que oscilan entre 0,8 y 1,2 mEq/l.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32040, 11533, '4. Es más eficaz en las fases depresivas que en las maníacas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32041, 11533, '5. La disfunción tiroidea es uno de sus posibles efectos adversos.', false, 5);
