INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32048, 11535, '2. ECG.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32049, 11535, '3. TSH.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32050, 11535, '4. EEG.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32051, 11536, '1. Amitriptilina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32052, 11536, '2. Imipramina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32053, 11536, '3. Nortriptilina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32054, 11536, '4. Fluoxetina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32055, 11536, '5. Meperidina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32056, 11537, '1. El litio es igual o ligeramente más eficaz que el valproato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32057, 11537, '2. Los antipsicóticos son efectivos tanto en monoterapia como en asociación con eutimizantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32058, 11537, '3. El litio muestra una eficacia similar a los antipsicóticos, aunque con un inicio de acción más rápido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32266, 11584, '2. Losartán.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32059, 11537, '4. No existe un antipsicótico de elección en el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32060, 11538, '1. Flufenazina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32061, 11538, '2. Olanzapina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32062, 11538, '3. Litio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32063, 11538, '4. Carbamazepina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32064, 11539, '1. Litio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32065, 11539, '2. Valproato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32066, 11539, '3. Carbamazepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32067, 11539, '4. Clorazepato.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32068, 11540, '1. El tratamiento habitual en las primeras 48 horas se basa en benzodiacepinas en monoterapia por vía parenteral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32069, 11540, '2. La clozapina es el fármaco de elección para el tratamiento agudo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32070, 11540, '3. La combinación de litio y antipsicóticos está contraindicada en las fases iniciales del tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32071, 11540, '4. En casos graves o resistentes puede utilizarse la terapia electroconvulsiva.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32072, 11541, '1. El margen entre las dosis terapéuticas y tóxicas es estrecho.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32073, 11541, '2. Su uso es seguro durante el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32074, 11541, '3. Los nuevos antipsicóticos han hecho que su uso quede prácticamente obsoleto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32075, 11541, '4. Los diuréticos tiazídicos pueden disminuir su tasa sanguínea y por tanto su eficacia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32076, 11542, '1. Glomeruloesclerosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32077, 11542, '2. Diabetes insípida nefrógena', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32078, 11542, '3. Nefropatía túbulo-intersticial crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32079, 11542, '4. Nefritis intersticial aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32080, 11543, '1. Enzimas hepáticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32081, 11543, '2. Anticuerpos antinucleares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32082, 11543, '3. Ferritina y sideremia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32083, 11543, '4. Función tiroidea y renal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32084, 11543, '5. Tirocalcitonina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32085, 11544, '1. Bupropion', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32086, 11544, '2. Ácido valproico', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32087, 11544, '3. Carbonato de litio', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32088, 11544, '4. Risperidona', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32089, 11544, '5. Olanzapina', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32090, 11545, '1. Temblor postural fino', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32091, 11545, '2. Cefaleas de predominio frontal', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32092, 11545, '3. Atracones bulímicos , especialmente de hidratos de carbono', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32093, 11545, '4. Hiperlipemia (aumento de triglicéridos en sangre)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32094, 11545, '5. Puede inducir depresión con riesgo autolítico especialmente importante', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32095, 11546, '1. En la actualidad existen comercializados diferentes fármacos opioides para el tratamiento del dolor moderado o grave en personas que reciben cuidados paliativos, superando en perfil de efectos adversos y en efectividad a la morfina y relegándola a un papel testimonial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32096, 11546, '2. La adicción es un problema creciente en pacientes que precisan morfina en su fase final de vida y es más frecuente cuando se emplean fármacos con efecto de larga duración (metadona o morfina de liberación prolongada).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32097, 11546, '3. El fentanilo oral transmucoso tiene un perfil de acción que lo hace útil en el dolor crónico no irruptivo y de carácter crónico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32098, 11546, '4. La metadona es un fármaco analgésico con escasa excreción renal por lo que es útil en personas con aclaramiento renal disminuido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32099, 11547, '1. Aceptar la petición del familiar y prescribir un analgésico no opioide para el control del dolor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32100, 11547, '2. Rechazar la solicitud del familiar y ordenar la administración de cloruro mórfico, a las dosis previamente prescritas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32101, 11547, '3. Plantear la rotación del tratamiento analgésico por otro opioide con menor riesgo sedante, como oxicodona/naloxona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32102, 11547, '4. Preguntar al paciente acerca de la intensidad de su dolor actual y de sus preferencias de analgesia en este momento.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32103, 11548, '1. En el caso de dolor por metástasis óseas está indicado el uso de antiinflamatorios como AINEs o corticoides como tratamiento coadyuvante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32104, 11548, '2. En el dolor neuropático están indicados como coadyuvantes fármacos anticonvulsivantes como la gabapentina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32105, 11548, '3. Dado que el paciente usa fentanilo como opioide de base, si decidimos pautar un opioide de rescate deberá ser también fentanilo dado que no deben mezclarse fármacos del tercer escalón analgésico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32106, 11548, '4. La radioterapia con finalidad analgésica es una opción en pacientes con metástasis óseas de neoplasias prostáticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32107, 11549, '1. Quetiapina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32108, 11549, '2. Rocuronio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32109, 11549, '3. Etomidato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32110, 11549, '4. Fentanilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32111, 11550, '1. Naloxona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32112, 11550, '2. Flumazenilo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32113, 11550, '3. Ciproheptadina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32114, 11550, '4. Atropina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32115, 11551, '1. Su potencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32116, 11551, '2. Su actividad intrínseca.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32117, 11551, '3. Su índice terapéutico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32118, 11551, '4. Su afinidad por el lugar diana de acción.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32119, 11552, '1. Administrar naloxona, flumazenilo y tiamina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32120, 11552, '2. Administrar naloxona, flumazenilo y glucosa hipertónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32121, 11552, '3. Administrar naloxona y flumazenilo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32122, 11552, '4. Administrar tiamina y glucosa hipertónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32123, 11553, '1. Ha tomado zumo de pomelo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32124, 11553, '2. Es un metabolizador ultralento del CYP3A4.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32125, 11553, '3. Carece de alelos funcionales del locus CYP2D6.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32126, 11553, '4. Posee un fénotipo metabolizador ultrarapido del CYP2D6.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32127, 11554, '1. El fármaco ideal para la sedación es el midazolam.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32128, 11554, '2. La morfina está contraindicada en el tratamiento de la disnea porque produce depresión respiratoria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32129, 11554, '3. El tratamiento estandar para los estertores premortem, es la administración de anticolinérgicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32130, 11554, '4. En la agitación el tratamiento es el haloperidol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32131, 11555, '1. Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina y oxicodona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32132, 11555, '2. Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina y oxicodona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32133, 11555, '3. Suspender ibuprofeno y tramadol e iniciar un opioide mayor como morfina y oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32134, 11555, '4. Suspender tramadol, mantener ibuprofeno e iniciar un opioide mayor como morfina y oxicodona, y a la vez tratamiento para el dolor irruptivo con fentanilo sublingual.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32135, 11556, '1. Una reducción de la eficacia analgésica de codeína.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32136, 11556, '2. Ineficacia del tratamiento con acenocumarol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32137, 11556, '3. Potenciación del efecto sinérgico de codeína con paracetamol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32138, 11556, '4. Requerimiento de una dosis superior de amitriptilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32139, 11557, '1. Opiáceos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32140, 11557, '2. Antidepresivos tricíclicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32141, 11557, '3. Agonistas dopaminérgicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32142, 11557, '4. Anticomiciales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32143, 11558, '1. Si el paciente tiene dolor se emplearán siempre opiáceos potentes para el control sin tener en consideración la severidad y caracteristicas del dolor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32144, 11558, '2. Si precisamos sedación para control de la fase agónica podemos realizarla de forma exclusiva con morfina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32145, 11558, '3. Los antidepresivos tricíclicos no se consideran medicación coadyuvante para el alivio sintomático del dolor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32146, 11558, '4. Los neurolépticos a dosis bajas ayudan al control de las náuseas desencadenadas por el inicio de un tratamiento con opiáceos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32147, 11558, '5. El dolor de características viscerales es el que peor respuesta tiene al tratamiento con opiáceos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32148, 11559, '1. Los efectos secundarios de los opiáceos son frecuentes aunque no graves salvo la depresión respiratoria que se puede revertir con naloxona', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32149, 11559, '2. El primer signo de sobredosificación de opiáceos es la somnolencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32150, 11559, '3. La mayoria de los opiáceos actúan sobre los receptores mu.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32151, 11559, '4. La combinación de opiáceos e inhibidores de la cicoloxigenasa (AINE) no aporta valor en el tratamiento del dolor agudo postoperatorio.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32152, 11560, '1. Administrar 0,4 mg de naloxona i.m. o i.v.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32153, 11560, '2. Obtener un hemograma y una bioquímica básica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32154, 11560, '3. Solicitar un examen toxicológico de orina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32155, 11560, '4. Realizar un ECG.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32156, 11560, '5. Solicitar una TC craneal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32157, 11561, '1. Asegurar la vía aérea, oxígeno y suero glucosado 10%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32158, 11561, '2. Asegurar la vía aérea, calentamiento corporal y observación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32159, 11561, '3. Asegurar la vía aérea, administrar dopamina intravenosa y observación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32160, 11561, '4. Asegurar la vía aérea, administrar naloxona intravenosa y observación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32161, 11561, '5. Asegurar la vía aérea, administrar naltrexona y observación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32162, 11562, '1. El estreñimiento es un efecto secundario casi constante, por lo que se debería utilizar un laxante para evitar su aparición.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32163, 11562, '2. Su uso continuado requiere aumentar la dosis administrada para obtener el mismo efecto analgésico debido a fenómenos de tolerancia y sobre todo, a la progresión de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32164, 11562, '3. La depresión respiratoria es un efecto secundario frecuente dada la disrupción orgánica que presentan estos pacientes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32165, 11562, '4. La morfina no tiene techo terapéutico, por lo que no existe una dosis máxima que no pueda sobrepasarse si lo requiere el paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32166, 11562, '5. Se deben pautar a intervalos regulares y no sólo si el paciente presenta dolor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32167, 11563, '1. Broncodilatadores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32168, 11563, '2. Morfina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32169, 11563, '3. Oxigenoterapia al 35% por mascarilla.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32170, 11563, '4. Digital y diuréticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32171, 11563, '5. Antibióticos y fisioterapia respiratoria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32172, 11564, '1. Alternar AINES a dosis plenas con paracetamol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32173, 11564, '2. Cambiar de AINE.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32174, 11564, '3. Utilizar un opioide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32175, 11564, '4. Utilizar un opioide y un AINE al mismo tiempo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32176, 11564, '5. Ingresar al paciente para tratamiento endovenoso con opioide mayor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32177, 11565, '1. Midriasis, activación generalizada, convulsiones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32178, 11565, '2. Miosis, depresión respiratoria y coma.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32179, 11565, '3. Depresión respiratoria, hipertensión arterial y miosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32180, 11565, '4. Midriasis, hipotermia, hipotensión, bradicardias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32181, 11565, '5. Depresión respiratoria, hipertermia y taquiarritmias.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32182, 11566, '1. Consta de varios escalones dependiendo de los fármacos utilizados, con un máximo de seis escalones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32183, 11566, '2. Permite la utilización conjunta de opiáceos débiles (codeína) y potentes (morfina) en dolores de intensidad severa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32184, 11566, '3. Si se administra conjuntamente ibuprofeno, dexametasona y amitriptilina, se considera que se está utilizando el primer escalón de la escalera analgésica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32185, 11566, '4. No se permite la utilización de fármacos adyuvantes del dolor en el tercer escalón analgésico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32186, 11566, '5. El quinto escalón tiene como fármaco principal la morfina, bien de acción rápida o retardada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32187, 11567, '1. Es un fármaco sustitutivo de la heroína, utilizado en programas de mantenimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32188, 11567, '2. Es un agonista opiáceo, utilizado en la desintoxicación de heroína.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32189, 11567, '3. Es un sedante que se aplica como paliativo en el síndrome de abstinencia de opiáceos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32190, 11567, '4. Es un antagonista de los opiáceos de acción prolongada, que se utiliza después de la cura de desintoxicación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32191, 11567, '5. Es un antagonista de los opiáceos de acción rápida, que se utiliza en el tratamiento de las sobredosis de narcóticos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32192, 11568, '1. No deben utilizarse en atención primaria dados sus efectos adversos, siendo de uso hospitalario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32267, 11584, '3. Amlodipino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32193, 11568, '2. Debido a su rápida tolerancia y falta de efectividad no deben utilizarse en dolor por cáncer avanzado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32194, 11568, '3. La dosificación cada 12 horas de morfina de liberación lenta produce analgesia más continua y cómoda utilización en el dolor por cáncer.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32195, 11568, '4. No existen preparados comerciales de morfina por vía oral, siendo siempre de utilización parenteral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32196, 11568, '5. No deben asociarse derivados mórficos con antiinflamatorios no esteroideos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32197, 11569, '1. Diclofenaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32198, 11569, '2. Paracetamol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32199, 11569, '3. Ketorolaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32200, 11569, '4. Metamizol.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32201, 11570, '1. Naproxeno.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32202, 11570, '2. Celecoxib.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32203, 11570, '3. Ketorolaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32204, 11570, '4. Ibuprofeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32205, 11571, '1. Gabapentina oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32206, 11571, '2. Ibuprofeno oral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32207, 11571, '3. Capsaicina tópica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32208, 11571, '4. Lidocaína tópica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32209, 11572, '1. Porque es inhibidor selectivo de la COX-1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32210, 11572, '2. Porque es un inhibidor irreversible.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32211, 11572, '3. Porque da lugar a su metabolito, el ácido salicílico, que tiene una semivida en plasma muy prolongada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32212, 11572, '4. Porque inhibe la tromboxano sintetasa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32213, 11573, '1. Etoricoxib', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32214, 11573, '2. Ibuprofeno', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32215, 11573, '3. Ácido acetilsalicilico', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32216, 11573, '4. Ketorolaco', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32217, 11574, '5. Ibuprofeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32218, 11574, '6. Oxicodona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32219, 11574, '7. Duloxetina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32220, 11574, '8. Paracetamol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32221, 11575, '1. Solicitar las transaminasas hépaticas en sangre y si no están alteradas darle el alta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32222, 11575, '2. Mantenerlo en observación hasta que hayan pasado 4 horas desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de N-acetilcisteina intravenosa por si hubiera que administrarla.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32223, 11575, '3. Mantenerlo en observación hasta que hayan pasado 4 horas desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de protamina que es el antídoto necesario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32224, 11575, '4. Mantenerlo en observación hasta que hayan pasado 6 horas desde la ingesta, extraer sangre para determinar la concentración de paracetamol y comprobar que se dispone de atropina que es el antídoto necesario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32225, 11575, '5. Ponerse en contacto con el coordinador de trasplantes por si fuera necesario el trasplante hepático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32226, 11576, '1. Los AINE y el paracetamol están en el mismo escalón analgésico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32227, 11576, '2. Los opioides mayores y menores forman parte del mismo escalón analgésico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32228, 11576, '3. Cuando cambiamos de escalón analgésico se debe mantener el fármaco del escalón anterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32229, 11576, '4. El metamizol se corresponde con el tercer escalón.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32230, 11576, '5. Los opioides mayores se administran solamente por vía parenteral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32231, 11577, '1. Paracetamol, tramadol y dexametasona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32232, 11577, '2. Naproxeno, morfina de liberación retardada y gabapentína.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32233, 11577, '3. Ketorolaco, morfina y tramadol.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32234, 11577, '4. Ácido acetilsalicílico, ketorolaco y tramadol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32235, 11577, '5. Metadona, dexametasona y paracetamol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32236, 11578, '1. Pacientes de edad avanzada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32237, 11578, '2. Antecedentes previos de úlcera.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32238, 11578, '3. Antecedentes previos de sintomatología digestiva en relación con el consumo de antiinflamatorios no esteroideos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32239, 11578, '4. Tratamiento concomitante con corticoides o anticoagulantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32240, 11578, '5. Cualquier paciente hospitalizado, con independencia de su situación clínica.', true, 5);
