INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32244, 11579, '4. Diclofenaco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32245, 11580, '1. Su administración junto con corticoides no aumenta el riesgo de lesiones gastroduodenales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32246, 11580, '2. La edad no influye en el riesgo de desarrollar lesiones digestivas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32247, 11580, '3. Es preferible la administración rectal, ya que su efecto lesivo es fundamentalmente local.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32248, 11580, '4. El acúmulo de prostaglandinas en la mucosa gástrica o duodenal es el mecanismo patogénico más importante de las erosiones gastroduodenales inducidas por ellos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32249, 11580, '5. Hasta en el 15-30% de los pacientes que los toman de forma crónica se demuestran úlceras gástricas y/o duodenales en la endoscopia digestiva alta.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32250, 11581, '1. Ibuprofeno.', false, 1);
