INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32254, 11581, '5. Aciclovir.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32255, 11582, '1. El paciente padece probablemente amiloidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32256, 11582, '2. La IR es probablemente secundaria al efecto diurético de los AINE.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32257, 11582, '3. La IR es probablemente debida a la disminución del filtrado glomerular causada por los AINE.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32258, 11582, '4. Al aumentar la dosis de los AINE es probable que la IR mejore.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32259, 11582, '5. Se debe sustituir los AINE por corticosteroides por vía oral.', false, 5);
