INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32450, 11624, '2. Propranolol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32451, 11624, '3. Clortalidona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32452, 11624, '4. Doxazosina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32453, 11624, '5. Enalapril.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32454, 11625, '1. Digoxina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32455, 11625, '2. Diuréticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32456, 11625, '3. Inhibidores del enzima conversor de la angiotensina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32457, 11625, '4. Bloqueantes de los canales del calcio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32458, 11625, '5. Drogas simpaticomiméticas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32459, 11626, '1. Diuréticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32460, 11626, '2. Digitálicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32461, 11626, '3. Inhibidores de la ECA.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32462, 11626, '4. Calcioantagonistas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32463, 11626, '5. Aminas simpaticomiméticas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32464, 11627, '1. No está nunca indicado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32465, 11627, '2. Está indicado en principio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32466, 11627, '3. Sólo está indicado si fracasa la digital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32467, 11627, '4. Sólo está indicado si fracasa un tratamiento combinado con digital y diuréticos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32468, 11627, '5. Sólo está indicado cuando se asocia hipertensión arterial.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32469, 11628, '1. Se debe intensificar el tratamiento hipolipemiante hasta el objetivo terapéutico (LDL < 55 mg/dl).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32470, 11628, '2. Su perfil lipídico es adecuado dado que tiene un colesterol total inferior a 200 mg/dl.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32471, 11628, '3. Su perfil lipídico es adecuado porque su HDL es elevado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32472, 11628, '4. Al dejar de fumar y ser mujer su riesgo es bajo y no hace falta insistir en optimizar su perfil lipídico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32473, 11629, '1. Ácido nicotínico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32474, 11629, '2. Gemfibrozilo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32475, 11629, '3. Simvastatina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32476, 11629, '4. Colestiramina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32477, 11630, '1. Insistir en cambios de estilos de vida y mantener el mismo tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32478, 11630, '2. Es prioritario aumentar el cHDL con ácido nicotínico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32479, 11630, '3. Hay que disminuir cLDL cambiando gemfibrozilo por atorvastatina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32480, 11630, '4. Retirar el betabloqueante por si altera los lípidos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32481, 11631, '1. Las LDL representan la forma de transporte del colesterol del intestino al hígado, Por tanto, reflejan una mayor incorporación de colesterol desde la ingesta lipídica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32482, 11631, '2. Las LDL están implicadas en el transporte reverso del colesterol desde los tejidos periféricos hacia el hígado. Por tanto unos niveles elevados son beneficiosos para disminuir los niveles plasmáticos de colesterol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32483, 11631, '3. Las LDL son ricas en triglicéridos y pobres en colesterol. Un aumento de LDL en plasma refleja un aumento de síntesis de novo y/o de ingesta de triglicéridos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32484, 11631, '4. Un aumento de los niveles de LDL en plasma es beneficioso porque protege a las arterias de la formación de placas ateroscleróticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32485, 11631, '5. Las LDL transportan colesterol desde el hígado a los tejidos periféricos, donde entran en las células mediante procesos de endocitosis.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32486, 11632, '1. Tratar con estatinas hasta que se normalice el colesterol y recomendar hábito de vida saludable (dieta, ejercicio y no fumar).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32487, 11632, '2. Descartar hipotiroidismo u otra enfermedad sistémica, recomendar hábito de vida saludable y tratar con fibratos para normalizar el colesterol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32488, 11632, '3. No precisa descartar dislipemia secundaria por ser infrecuente. Se debe realizar perfil lipídico familiar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32489, 11632, '4. Descartar dislipemia secundaria, tratar con resinas (resincolestiramina) y fibratos y recomendar hábito de vida saludable. Prohibir el alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32490, 11632, '5. Descartar dislipemia secundaria, solicitar estudio familiar y tratar con estatinas para mantener un buen perfil lipídico. Control de otros factores de riesgo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32491, 11633, '1. Aumento de la TSH.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32492, 11633, '2. Aumento de la CPK (creatinfosfoquinasa).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32493, 11633, '3. Aumento de las transaminasas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32494, 11633, '4. Mialgias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32495, 11633, '5. Artralgias.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32496, 11634, '1. Anticoagulación con heparina intravenosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32497, 11634, '2. Fibrinolisis intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32498, 11634, '3. Antiagregación con ácido acetilsalicílico 300 mg.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32499, 11634, '4. Evacuación quirúrgica del hematoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32500, 11635, '1. Debe aconsejarse tratamiento profiláctico con heparina de bajo peso molecular durante el embarazo y hasta 6 semanas posparto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32501, 11635, '2. Debe aconsejarse tratamiento profiláctico con aspirina durante todo el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32502, 11635, '3. Debe aconsejarse realizar profilaxis con acenocumarol durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32503, 11635, '4. Dado que el estudio de trombofilia fue negativo solo se precisa realizar profilaxis de trombosis venosa con medidas compresivas para miembros inferiores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32504, 11636, '1. Hipopotasemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32505, 11636, '2. Alcalosis metabólica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32506, 11636, '3. Diarrea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32507, 11636, '4. Trombocitopenia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32508, 11637, '1. Deficiencia de antitrombina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32509, 11637, '2. Factor V Leiden.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32510, 11637, '3. Hiperhomocisteinemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32511, 11637, '4. Deficiencia de proteína C.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32512, 11638, '1. Insuficiencia renal aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32513, 11638, '2. Anemia hemolítica autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32514, 11638, '3. Trombosis venas suprahepáticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32515, 11638, '4. Síndrome leucoeritroblástico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32516, 11638, '5. Plaquetopenia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32517, 11639, '1. Heparina de bajo peso molecular solapada con dicumarínicos, al menos los 5 primeros días, hasta obtener INR entre 2 y 3. Después dicumarínicos solos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32518, 11639, '2. Sólo heparina de bajo peso molecular mientras dure el embarazo, pasando a dicumarínicos tras el parto si es preciso prolongar el tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32519, 11639, '3. Sólo dicumarínicos desde el principio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32520, 11639, '4. Fibrinólisis con activador tisular del plasminógeno (tPA)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32521, 11639, '5. Los anticoagulantes están contraindicados en el embarazo. Sólo medias de compresión fuerte.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32522, 11640, '1. Los cumarínicos tienen pocas interacciones farmacológicas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32523, 11640, '2. El tratamiento de la trombocitopenia inducida por heparina consiste en la disminución de la dosis de heparina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32524, 11640, '3. Los cumarínicos son seguros durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32525, 11640, '4. El test más utilizado para el control de la heparina no fraccionada es el TTPA (tiempo de tromboplastina parcial activada).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32526, 11640, '5. El fondaparinux es un nuevo anticoagulante de administración oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32527, 11641, '1. En pacientes con TVP confirmada objetivamente, recomendamos tratamiento agudo con heparina de bajo peso subcutánea o heparina no fraccionada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32528, 11641, '2. Para pacientes con elevada sospecha clínica de trombosis, se recomienda tratamiento anticoagulante mientras se espera el resultado de las pruebas diagnósticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32609, 11658, '3. Receptor P2Y12', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32529, 11641, '3. El tratamiento con heparina se dice debe controlarse realizando TPT (tiempo parcial de tromboplastina).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32530, 11641, '4. Se recomienda iniciar la administración de anticoagulantes orales junto con heparina en el primer día del tratamiento, e interrumpir la administración de heparina cuando el INR sea estable y superior a 2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32531, 11641, '5. En los pacientes tratados con heparina de bajo peso es necesario hacer mediciones sistemáticas de la actividad anti-Xa con el fin de ajustar la dosis.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32532, 11642, '1. Son compuestos obtenidos a partir de la heparina no fraccionada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32533, 11642, '2. Todas se eliminan por el riñón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32534, 11642, '3. Su biodisponibilidad es superior a la de la heparina no fraccionada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32535, 11642, '4. Es preciso monitorizar sus efectos en la mayoría de los pacientes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32536, 11642, '5. Producen trombocitopenia con menor frecuencia que la heparina no fraccionada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32537, 11643, '1. La heparina se une a la antitrombina III', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32538, 11643, '2. El acenocumarol compite con la vitamina K', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32539, 11643, '3. La heparina aumenta el AMPc plaquetario', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32540, 11643, '4. El efecto de la heparina es inmediato', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32541, 11643, '5. El acenocumarol precisa un tiempo de latencia antes de empezar a actuar', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32542, 11644, '1. Rivaroxaban.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32543, 11644, '2. Enoxaparina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32544, 11644, '3. Acenocumarol.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32545, 11644, '4. Fondaparinux.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32546, 11645, '1. Suspender el tratamiento con acenocumarol y administrar 10 mg de vitamina K en infusión intravenosa lenta, que se repetirá cada 12 horas si fuera necesario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32547, 11645, '2. Suspender el acenocumarol y remitir al paciente a un centro hospitalario para vigilar la aparición de sangrado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32548, 11645, '3. Suspender temporalmente el acenocumarol y reanudar la anticoagulación cuando se haya alcanzado el intervalo terapéutico, calculando de nuevo la dosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32549, 11645, '4. Iniciar la administración de concentrado de complejo de protrombina o plasma fresco congelado según el peso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32550, 11646, '1. Vitamina K.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32551, 11646, '2. Idarucizumab.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32552, 11646, '3. Plasma fresco congelado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32553, 11646, '4. Sulfato de protamina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32554, 11647, '1. Dabigatrán.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32555, 11647, '2. Apixaban.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32556, 11647, '3. Ribaroxaban.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32557, 11647, '4. Acenocumarol', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32558, 11647, '5. Clopidogrel.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32559, 11648, '1. Heparina- cofactor de la antitrombina III.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32560, 11648, '2. Acenocumarol- inhibe la vitamina K epóxido reductasa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32561, 11648, '3. Dabigatrán – inhibe la trombina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32562, 11648, '4. Rivaroxabán – inhibe el factor Xa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32563, 11648, '5. Warfarina - inhibe la absorción de la vitamina K.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32564, 11649, '1. Acenocumarol.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32565, 11649, '2. Gentamicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32566, 11649, '3. Digoxina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32567, 11649, '4. Fenitoína.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32568, 11649, '5. Litio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32569, 11650, '1. 1-2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32570, 11650, '2. 1,5-2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32571, 11650, '3. 2-3.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32572, 11650, '4. 3-4.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32573, 11650, '5. 4-5.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32574, 11651, '1. Fibrinógeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32575, 11651, '2. Tiempo de trombina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32576, 11651, '3. Tiempo de protrombina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32577, 11651, '4. Tiempo de tromboplastina parcial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32578, 11651, '5. Tiempo de sangría.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32579, 11652, '1. Mantener el cociente internacional normalizado (INR) entre 2 y 3.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32580, 11652, '2. Mantener el INR entre 3 y 4 y añadir 200 mg de aspirina al día.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32581, 11652, '3. Mantener el INR entre 4 y 5.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32582, 11652, '4. Mantener el INR entre 5 y 6.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32583, 11652, '5. Suprimir la anticoagulación y administrar 300 mg de aspirina oral al día.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32584, 11653, '1. Los derivados dicumarínicos pasan a través de la placenta aumentando el riesgo de defectos fetales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32585, 11653, '2. La heparina es más fácil de administrar que los derivados cumarínicos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32586, 11653, '3. El control del efecto anticoagulante de la heparina es más fácil y su neutralización muy rápida mediante sulfato de protamina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32587, 11653, '4. La heparina de bajo peso molecular es más económica que los dicumarínicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32588, 11653, '5. La dosificación de los derivados cumarínicos es difícil durante el embarazo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32589, 11654, '1. Porque es inhibidor selectivo de la COX-1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32590, 11654, '2. Porque es un inhibidor irreversible.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32591, 11654, '3. Porque da lugar a su metabolito, el ácido salicílico, que tiene una semivida en plasma muy prolongada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32592, 11654, '4. Porque inhibe la tromboxano sintetasa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32593, 11655, '1. Heparina sódica en perfusión intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32594, 11655, '2. Tromboendarectomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32595, 11655, '3. Fibrinólisis sistémica con rt-PA (alteplasa) 100 mg intravenoso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32596, 11655, '4. Filtro en vena cava inferior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32597, 11656, '1. Durante la primera semana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32598, 11656, '2. Durante las primeras 24 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32599, 11656, '3. No existe un tiempo límite para iniciar el tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32600, 11656, '4. Durante las primeras 12 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32601, 11656, '5. Durante las primeras 3 horas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32602, 11657, '1. Anticoagulación con heparina sódica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32603, 11657, '2. Anticoagulación con heparina de bajo peso molecular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32604, 11657, '3. Fibrinólisis con rt-PA.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32605, 11657, '4. Antiagregación con aspirina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32606, 11657, '5. Antiagregación con clopidogrel.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32607, 11658, '1. Receptor GP Ib.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32608, 11658, '2. Receptor GP IIb/IIIa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32610, 11658, '4. Receptor P2X1', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32611, 11658, '5. Receptor PAR-1', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32612, 11659, '1. Estimular el complejo protrombinasa y la formación de trombina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32613, 11659, '2. Estimular la conversión de plasminógeno en plasmina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32614, 11659, '3. Bloquear el receptor GP llb/llla de las plaquetas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32615, 11659, '4. Inhibir la formación de trombina y plasminógeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32616, 11659, '5. Estimular la producción de heparinoides.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32617, 11660, '1. Es útil para disminuir el tamaño de la zona infartada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32618, 11660, '2. Es útil para disminuir las arritmias.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32619, 11660, '3. Es útil para disminuir la mortalidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32620, 11660, '4. Es útil para limitar la disfunción ventricular izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32621, 11660, '5. Solo es útil en las primeras horas postinfarto.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32622, 11661, '1. Tratamiento trombolítico con activador tisular del plasminógeno intracoronario únicamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32623, 11661, '2. Tratamiento trombolítico con activador tisular del plasminógeno intravenoso más aspirina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32624, 11661, '3. Tratamiento trombolítico con activador tisular del plasminógeno intravenoso más heparina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32625, 11661, '4. Tratamiento trombolítico con activador tisular del plasminógeno intravenosos, heparina y aspirina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32626, 11661, '5. Heparina de bajo peso molecular en dosis terapéuticas y aspirina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32627, 11662, '1. Su principal fuente para el organismo es la ingesta de frutas y verduras.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32628, 11662, '2. Sus depósitos se localizan en el hígado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32629, 11662, '3. Se conjuga en el íleon con el factor intrínseco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32630, 11662, '4. Su déficit conduce a reducción de los niveles de homocisteína en plasma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32631, 11663, '1. Vitamina B12.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32632, 11663, '2. Calcio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32633, 11663, '3. Hierro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32634, 11663, '4. Magnesio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32635, 11663, '5. Ácido fólico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32636, 11664, '1. Procurar tomarlo en ayunas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32637, 11664, '2. Asociar vitamina C.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32638, 11664, '3. Asociar algún antiácido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32639, 11664, '4. La dosis de Fe elemental será 150-200 mg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32640, 11664, '5. Mantener el tratamiento ≥ 6 meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32641, 11665, '1. En presencia de tratamiento con opioides son recomendables los suplementos de fibra vegetal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32642, 11665, '2. Los elementos fundamentales del tratamiento son los laxantes estimulantes y osmóticos, reblandecedores de heces, líquidos y enemas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32643, 11665, '3. Para evitar el estreñimiento causado por los opioides se debe recurrir a la combinación de un laxante y un reblandecedor de heces.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32644, 11665, '4. Si no hay defecación tras varios días de tratamiento, se necesita el tacto rectal para extraer el material impactado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32645, 11666, '1. Es un potente antiácido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32646, 11666, '2. Bloquea reversiblemente la bomba de hidrogeniones en el estómago.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32647, 11666, '3. Es un profármaco.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32648, 11666, '4. Tras disolverse su cubierta entérica en el estómago se une directamente a la bomba de protones de la célula parietal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32649, 11667, '1. Lansoprazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32650, 11667, '2. Ondansetrón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32651, 11667, '3. Loperamida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32652, 11667, '4. Metoclopramida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32653, 11668, '1. Cleboprida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32654, 11668, '2. Domperidona.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32655, 11668, '3. Metoclopramida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32656, 11668, '4. Sulpirida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32657, 11669, '1. Bajar dosis de opioides a la mitad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32658, 11669, '2. Pautar un laxante osmótico y comprobar mediante un tacto rectal que no exista impactación fecal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32659, 11669, '3. Pautar un procinético.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32660, 11669, '4. Realizar una TC urgente ante la sospecha de obstrucción intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32661, 11670, '1. Es una situación bien tolerada por la familia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32662, 11670, '2. Originan una respiración silenciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32663, 11670, '3. Se tratan con morfina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32664, 11670, '4. Se tratan con procinéticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32665, 11670, '5. Se tratan con escopolamina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32666, 11671, '1. Neutralizan el ácido clorhídrico de la secreción gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32667, 11671, '2. Tiñen las heces de negro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32668, 11671, '3. Bloquean el receptor histamínico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32669, 11671, '4. Bloquean el receptor de la gastrina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32670, 11671, '5. Requieren cubierta entérica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32671, 11672, '1. Pautar laxantes osmóticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32672, 11672, '2. Pautar laxantes estimulantes de la motilidad colónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32673, 11672, '3. Pautar fibra.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32674, 11672, '4. Pautar laxantes reblandecedores de heces.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32675, 11672, '5. Pautar laxantes vía rectal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32676, 11673, '1. Inhibidores de la bomba de protones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32677, 11673, '2. Antagonistas de los receptores H2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32678, 11673, '3. Sucralfato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32679, 11673, '4. Tratamiento combinado con anti-H2 y sucralfato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32680, 11673, '5. Procinéticos y antiácidos pautados y a demanda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32681, 11674, '1. Se deben administrar de forma urgente agonistas beta2 nebulizados y, en caso de ausencia de respuesta temprana, añadir corticoides intravenosos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32682, 11674, '2. Antes de iniciarse el tratamiento debe realizase radiografía de tórax, gasometría arterial y analítica general para establecer el diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32683, 11674, '3. Los corticoides inhalados estarían contraindicados por aumentar el riesgo de neumonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32684, 11674, '4. Como primera elección se deben administrar anticolinérgicos nebulizados, debido a la ausencia de respuesta a los agonistas beta2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32685, 11675, '1. Uso de antihistamínicos de segunda generación por riesgo de sedación y efectos colinérgicos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32754, 11689, '4. Tratar con L-Tiroxina y determinar anticuerpos antitiroideos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32686, 11675, '2. Uso prolongado de benzodiacepinas de vida media larga por riesgo de sedación prolongada, confusión, trastorno del equilibrio y caídas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32687, 11675, '3. Antidepresivos tricíclicos en prostatismo por riesgo de retención urinaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32688, 11675, '4. Uso prolongado de neurolépticos en el parkinsonismo por empeoramiento de síntomas extrapiramidales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32689, 11676, '1. Corticoides inhalados a dosis bajas y agonistas beta2-adrenérgicos inhalados de acción corta', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32690, 11676, '2. Corticoides inhalados a dosis bajas y agonistas beta2-adrenérgicos inhalados de acción prolongada', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32691, 11676, '3. Corticoides inhalados a dosis altas y antagonistas de los leucotrienos', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32692, 11676, '4. Antagonistas de los leucotrienos y agonistas beta2-adrenérgicos inhalados de acción prolongada', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32693, 11676, '5. Antagonistas de los leucotrienos y teofilinas', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32694, 11677, '1. Aumentar la dosis de corticoides inhalados a 800 microgramos día', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32695, 11677, '2. Añadir tiotropio', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32696, 11677, '3. Mantener la misma pauta farmacológica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32697, 11677, '4. Cambiar a una terapia combinada con corticoides inhalados a dosis bajas y agonistas beta2-adrenérgicos inhalados de acción prolongada', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32698, 11677, '5. Añadir antileucotrienos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32699, 11678, '1. El salbutamol se indica como medicación de rescate', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32700, 11678, '2. Los glucocorticoides inhalados se metabolizan en el hígado', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32701, 11678, '3. Los agonistas adrenérgicos beta2 pueden emplearse en combinación con los glucocorticoides inhalados en el asma persistente leve-moderada', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32702, 11678, '4. El efecto del salmeterol dura 24 h', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32703, 11679, '1. Teofilina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32704, 11679, '2. Glucocorticoides inhalados.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32705, 11679, '3. Antagonistas de los receptores de los leucotrienos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32706, 11679, '4. N-acetilcisteína.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32707, 11680, '1. Salmeterol a demanda', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32708, 11680, '2. Salbutamol pautado más salbutamol a demanda', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32709, 11680, '3. Budesonida a demanda más salbutamol a demanda', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32710, 11680, '4. Budesonida pautada más salbutamol a demanda', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32711, 11680, '5. Budesonida pautada más salbutamol pautado', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32712, 11681, '1. Causan alta incidencia de reacciones adversas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32713, 11681, '2. Son el tratamiento de primera elección en el asma aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32714, 11681, '3. Tienen efecto antiagregante plaquetario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32715, 11681, '4. Son útiles como tratamiento complementario en el asma leve y moderada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32716, 11681, '5. Son de primera elección en bronquitis aguda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32717, 11682, '1. Una dosis baja-moderada de corticoides inhalados más un beta-agonista.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32718, 11682, '2. Deber evitar alergenos y utilizar un corticoide inhalado a demanda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32719, 11682, '3. Un beta agonista solo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32720, 11682, '4. Una combinación de teofilinas con corticoides inhalados y beta agonistas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32721, 11682, '5. Un ciclo inicial de corticoides orales combinado con beta agonistas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32722, 11683, '1. Prescribir broncodilatadores B2 estimulantes de corta acción cada cuatro horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32723, 11683, '2. Prescribir broncodilatadores de larga acción como formoterol asociado a corticoides inhalados.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32724, 11683, '3. Indicar antibióticos asociados a broncodilatadores anticolinérgicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32725, 11683, '4. Prescribir N-acetilcisteína, cada 6 horas asociado a amoxicilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32726, 11683, '5. Prescribir prednisona por vía oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32727, 11684, '1. Corticoides intravenosos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32728, 11684, '2. Teofilina intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32729, 11684, '3. Adrenalina subcutánea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32730, 11684, '4. Agonistas adrenérgicos beta2 en aerosol.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32731, 11684, '5. Anticolinérgicos en aerosol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32732, 11685, '1. Sulbutamol inhalado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32733, 11685, '2. Loratadina oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32734, 11685, '3. Budesonida inhalada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32735, 11685, '4. Ipatropio inhalado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32736, 11685, '5. Ibuprofeno oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32737, 11686, '1. La vía inhalatoria es la indicada de entrada en el asma estable, ya que así los efectos secundarios son menores.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32738, 11686, '2. Por vía parenteral, se deben emplear preferentemente los preparados de depósito.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32739, 11686, '3. Si se recurre persistentemente a la vía oral es conveniente suspender el resto de la medicación antiasmática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32740, 11686, '4. Los aerosoles de budesonida o de beclometasona sólo son eficaces cuando se combinan con corticosteroides por vía oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32741, 11686, '5. Los orales son la base del tratamiento en la mayoría de los casos de asma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32742, 11687, '1. Iniciar un tratamiento empírico con penicilina V oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32743, 11687, '2. Obtener una prueba rápida de detección de antígenos para el estreptococo del grupo A.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (32744, 11687, '3. Interrumpir el propranolol y obtener un cultivo de orofaringe.', false, 3);
