INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33028, 11751, '1. Algunos fármacos de esta familia presentan buena actividad frente a Mycobacterium tuberculosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33029, 11751, '2. La actividad bactericida depende de las concentraciones alcanzadas, por lo que pueden administrarse en dosis única diaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33030, 11751, '3. Todos los fármacos presentan buena actividad frente a bacilos Gram negativos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33031, 11751, '4. La toxicidad producida por los fármacos de este grupo se relaciona con el mantenimiento de una concentración mínima (concentración previa a una dosis) elevada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33032, 11751, '5. Cuando existe inflamación meníngea resultan muy útiles en el tratamiento de las infecciones bacterianas localizadas en el sistema nervioso central, especialmente las producidas por bacterias Gram negativas.', true, 5);
