INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33042, 11754, '1. Son bactericidas y actúan inhibiendo la síntesis proteica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33043, 11754, '2. Su captación por los ribosomas bacterianos es un proceso activo que requiere consumo energético.', false, 2);
