INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33050, 11755, '4. Pueden administrarse en una dosis única.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33051, 11755, '5. El bloqueo neuromuscular es una complicación potencialmente grave.', false, 5);
