INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33159, 11779, '1. Interfiere el metabolismo del folato en los microorganismos sensibles', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33160, 11779, '2. Es bactericida, siendo cada uno de sus componentes bacteriostáticos', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33161, 11779, '3. Su eliminación urinaria es pobre', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33162, 11779, '4. Produce alteraciones megaloblásticas en la médula ósea de forma excepcional excepto en pacientes con deficiencia previa', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33163, 11779, '5. Produce alteraciones hematológicas que se pueden prevenir con ácido fólico sin reducir la actividad antibacteriana', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33164, 11780, '1. La penicilina porque puede producir hidronefrosis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33165, 11780, '2. Las sulfamidas, porque pueden producir kernicterus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33166, 11780, '3. Las tetraciclinas porque pueden alterar el desarrollo del tejido óseo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33167, 11780, '4. Los aminoglucósidos porque pueden producir sordera en el recién nacido.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33168, 11781, '1. Isoniacida, durante nueve meses.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33169, 11781, '2. Rifampicina, durante cuatro meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33170, 11781, '3. Isoniacida y rifampicina, durante tres meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33171, 11781, '4. Isoniacida y rifapentina, durante tres meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33172, 11782, '1. Retirar toda la medicación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33173, 11782, '2. Continuar con el mismo tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33174, 11782, '3. Retirar la isoniacida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33175, 11782, '4. Retirar la pirazinamida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33176, 11783, '1. Isoniazida + rifampicina + pirazinamida (6 meses)', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33177, 11783, '2. Isoniazida + rifampicina + pirazinamida + etambutol (2 meses) seguido de isoniazida + rifampicina (4 meses)', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33178, 11783, '3. Isoniazida + rifampicina + etambutol (9 meses)', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33179, 11783, '4. Isoniazida + rifampicina + pirazinamida (2 meses) seguido de Isoniazida + rifampicina (4 meses)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33180, 11784, '1. Afectación del sistema nervioso central.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33181, 11784, '2. Alta prevalencia de resistencia primaria a isoniacida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33182, 11784, '3. Tuberculosis pulmonar cavitada y extensa con gran carga bacilar.', false, 3);
