INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33189, 11785, '5. Itraconazol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33190, 11786, '1. Los glicopéptidos son unos antibióticos de amplio espectro, con una más que aceptable actividad frente a bacterias Gram (+) y Gram (-).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33191, 11786, '2. Ciprofloxacino es un buen antibiótico para tratar todas las infecciones inducidas por bacterias Gram (+).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33192, 11786, '3. Los aminoglucósidos son unos antibióticos con una magnifica biodisponibilidad oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33193, 11786, '4. La Rifampicina es un medicamento que hay que administrar con otros antibióticos, para reducir el riesgo de una rápida selección de resistencias.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33194, 11786, '5. Las cefalosporinas son unos magníficos antibióticos con una buena actividad frente a Enterococcus faecalis.', false, 5);
