INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33196, 11787, '2. Ceftazidima.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33197, 11787, '3. Azitromicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33198, 11787, '4. Rifampicina.', true, 4);
