INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33689, 11897, '1. Anticonceptivos orales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33200, 11788, '1. La utilización de más de un fármaco al que el microorganismo sea resistente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33201, 11788, '2. La estrategia de inducción con un número elevado de fármacos durante dos meses, seguida de un tratamiento simplificado de duración prolongada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33202, 11788, '3. En la actualidad el tratamiento de inicio recomendado está compuesto por isoniacida, rifampicina, etambutol y pirazinamida', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33203, 11788, '4. En casos de fracaso terapéutico se recomienda monitorizar los niveles plasmáticos de los fármacos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33204, 11788, '5. La utilización de procedimientos de administración directamente observada es recomendable en determinados pacientes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33205, 11789, '1. Rifampicina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33206, 11789, '2. Pirazinamida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33207, 11789, '3. Isoniacida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33208, 11789, '4. Etambutol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33209, 11789, '5. Una infección independiente de la tuberculosis.', false, 5);
