INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33216, 11791, '2. Esfingolípidos', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33217, 11791, '3. Organofosforados', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33218, 11791, '4. Piridoxina', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33219, 11791, '5. Ninguna de las anteriores', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33220, 11792, '1. El tratamiento de elección es un comprimido vaginal de 500 mg de clotrimazol en dosis única.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33221, 11792, '2. Si estuviera embarazada, el tratamiento antifúngico debería ser oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33222, 11792, '3. Es preciso tratar a su pareja sexual, aunque esté asintomática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33223, 11792, '4. Es necesario realizar un cribado de otras enfermedades de transmisión sexual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33224, 11793, '1. Inhibición de la síntesis proteica por interacción con la subunidad 30S del ribosoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33225, 11793, '2. Alteración de la topoisomerasa II con afectación de la replicación del ADN.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33226, 11793, '3. Inhibición de la sintasa de 1,3-beta-glucano implicada en la síntesis de la pared celular fúngica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33227, 11793, '4. Inhibición de la polimerasa fúngica implicada en la síntesis del ADN del hongo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33228, 11794, '1. Fenitoína.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33229, 11794, '2. Cisaprida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33230, 11794, '3. Claritromicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33231, 11794, '4. Itraconazol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33232, 11794, '5. Omeprazol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33233, 11795, '1. Imipenem.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33234, 11795, '2. Clotrimazol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33235, 11795, '3. Metronidazol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33236, 11795, '4. Ampicilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33237, 11795, '5. Aciclovir.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33238, 11796, '1. No debe hacer nada, ya que el riesgo de transmisión del VIH es insignificante.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33239, 11796, '2. Debe recomendarse gammaglobulina IV en las primeras 72 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33240, 11796, '3. Debe hacer profilaxis postexposición frente al VIH durante 28 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33241, 11796, '4. Podría haber realizado profilaxis postexposición, pero ya es tarde para iniciarla.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33242, 11797, '1. La duración debe ser 28 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33243, 11797, '2. Debe hacerse una serología frente al VIH al inicio y al terminar la profilaxis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33244, 11797, '3. La evidencia de la utilidad de este tratamiento no está basada en ensayos clínicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33245, 11797, '4. El tratamiento es tenofovir y emtricitabina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33246, 11798, '1. El virus de la hepatitis C.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33247, 11798, '2. El virus de la hepatitis B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33248, 11798, '3. El virus de la hepatitis A.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33249, 11798, '4. El virus de la hepatitis E.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33250, 11798, '5. El virus TTV.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33251, 11799, '1. Es un virus RNA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33252, 11799, '2. El genotipo más frecuente en España es el genotipo 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33253, 11799, '3. El genotipo 3 responde mejor al tratamiento que el genotipo 1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33254, 11799, '4. Puede ser causa de cirrosis hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33255, 11799, '5. El tratamiento consiste en administrar ribavirina en monoterapia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33256, 11800, '1. El virus de la inmunodeficiencia humana (VIH).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33257, 11800, '2. El virus del herpes simple (VHS).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33258, 11800, '3. El virus de Epstein-Barr (VEB).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33259, 11800, '4. Citomegalovirus (CMV).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33260, 11800, '5. El virus de la hepatitis C (VHC).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33261, 11801, '1. No existe la transmisión madre-hijo del VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33262, 11801, '2. El tratamiento antirretroviral durante la gestación disminuye la transmisión del VIH al niño.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33263, 11801, '3. El VIH no se transmite a través de la leche materna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33264, 11801, '4. El tratamiento antirretroviral al niño tras el parto está contraindicado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33265, 11801, '5. Las mujeres gestantes con infección por el VIH no deben ser tratadas con antirretrovirales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33266, 11802, '1. El objetivo del tratamiento es la supresión máxima de la replicación viral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33267, 11802, '2. Las mujeres deben recibir tratamiento óptimo sin importar su estado de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33268, 11802, '3. Una vez que se alcanza la supresión virológica se puede suspender el tratamiento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33269, 11802, '4. El tratamiento antirretroviral se usa en profilaxis postexposición.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33270, 11802, '5. El tratamiento consiste en combinar tres fármacos activos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33271, 11803, '1. Pneumocystis carinii – Cotrimoxazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33272, 11803, '2. Citomegalovirus – Aciclovir.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33273, 11803, '3. Mycobacterium tuberculosis – Isoniacida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33274, 11803, '4. Toxoplasma gondii – Pirimetamina + Sulfadiacina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33275, 11803, '5. Mycobacterium avium – Rifabutina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33276, 11804, '1. La caída en la presión parcial de oxígeno promueve la ac?vación del factor inducible por hipoxia (HIF), que aumenta la expresión de hepcidina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33690, 11897, '2. Quistectomía ovárica por laparoscopia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33277, 11804, '2. El aumento de hierro sérico o la inflamación es?mulan la síntesis de hepcidina en el hígado, que regula nega?vamente la función de la ferropor?na.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33278, 11804, '3. La hepcidina disminuye la absorción intes?nal de hierro a través de la inac?vación del transportador de metales bivalentes 1 (DMT1).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33279, 11804, '4. En la hemocromatosis hereditaria de ?po 1, las mutaciones en la proteína de la hemocromatosis humana (HFE) causan un aumento de la producción de hepcidina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33280, 11805, '1. La distribución del líquido entre los compar?mentos intracelular y extracelular está determinada sobre todo por el efecto osmó?co de los iones más pequeños.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33281, 11805, '2. Alrededor del 80 % de la osmolaridad total del líquido inters?cial y del plasma se debe a los iones sodio y cloro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33282, 11805, '3. Alrededor del 50 % de la osmolaridad en el líquido intracelular se debe a los iones calcio.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33283, 11805, '4. Cambios rela?vamente pequeños en la concentración de solutos no difusibles en el líquido extracelular pueden causar grandes cambios en el volumen celular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33284, 11806, '1. La albúmina se sinte?za en el hígado y se metaboliza en numerosos tejidos, permi?éndoles a los mismos aprovechar los aminoácidos provenientes de su degradación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33285, 11806, '2. La albúmina es la proteína mayoritaria del plasma, por ello par?cipa en el mantenimiento de la presión oncó?ca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33286, 11806, '3. La albúmina interviene en el transporte de bilirrubina directa o conjugada, como así también de ácidos grasos, calcio, y algunas vitaminas, hormonas y fármacos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33287, 11806, '4. Al exis?r numerosas variantes gené?cas de la albúmina, es posible observar una doble banda de albúmina en un proteinograma, que se conoce como bisalbuminemia, pero que carece de significación clínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33288, 11807, '1. Es un derivado de los esfingolípidos que interviene en el recambio de las membranas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33289, 11807, '2. Es un tripép?do con acción an?oxidante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33290, 11807, '3. Es una proteína de pequeño tamaño que interviene en la degradación proteica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33291, 11807, '4. Es un coac?vador de la transcripción de diferentes genes', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33292, 11808, '1. Su ausencia determina la sobrecarga de hierro.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33293, 11808, '2. El exceso de la misma permite aumentar la absorción intes?nal de hierro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33294, 11808, '3. Se produce principalmente en el riñón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33295, 11808, '4. Su síntesis no está influida por el hierro ingerido.', false, 4);
