INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33461, 11845, '4. La absorción intes?nal del hierro contenido en el hemo de la carne roja es proporcionalmente mayor que la del hierro contenido en los vegetales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33462, 11845, '5. La absorción intes?nal de hierro de un hombre sano debe ser, por lo menos, 1 mg de hierro elemental al día.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33463, 11846, '1. Pensar en que puede estar pasando un período de “luna de miel” y probablemente se puede re?rar la insulina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33464, 11846, '2. Se debe sospechar que hace hipoglucemias en relación con la aparición de un insulinoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33465, 11846, '3. Es posible que haga hipoglucemias y puedan resolverse con un suplemento de dieta a mitad de la mañana.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33466, 11846, '4. A esta edad no hay que pretender normalizar las cifras de glucosa y sin duda habrá que bajar todas las dosis de insulina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33467, 11846, '5. Si se confirma que hace hipoglucemias se podría pasar a an?diabé?cos orales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33468, 11847, '1. Repe?r la glucemia en ayunas o realizar test tolerancia oral a la glucosa para confirmar el diagnós?co.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33469, 11847, '2. Iniciar tratamiento con sulfonilureas y revaluar en 6 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33470, 11847, '3. Lo ideal es empezar un tratamiento combinado con acarbosa y metormina a dosis plenas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33471, 11847, '4. Inicialmente debemos pautar tratamiento dieté?co y ejercicio fsico, valorando añadir algún fármaco según la evolución posterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33472, 11847, '5. En este momento lo más adecuado es iniciar insulinoterapia junto con tratamiento dieté?co y modificación en el es?lo de vida.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33473, 11848, '1. Ácido nicohnico.', true, 1);
