INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33478, 11849, '1. Dichas cifras reafirman la existencia de una diabetes y no se jus?fican más estudios diagnós?cos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33479, 11849, '2. Indicaría medidas dieté?cas: reducción de carbohidratos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33480, 11849, '3. Realizaría una prueba de tolerancia oral de glucosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33691, 11897, '3. Antiinflamatorios no esteroideos.', false, 3);
