INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33482, 11849, '5. Si la glucosuria fuera posi?va iniciaría un tratamiento con Insulina NPH.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33483, 11850, '1. Es un factor de riesgo cardiovascular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33484, 11850, '2. Se asocia frecuentemente a diabetes ?po 2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33485, 11850, '3. La obesidad periférica (acúmulo de grasa en extremidades y glúteos) es la que se asocia a un mayor riesgo cardiovascular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33486, 11850, '4. Se clasifica basándose en el índice de masa corporal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33487, 11850, '5. La medida del perímetro abdominal es una intervención de u?lidad para clasificar la obesidad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33488, 11851, '1. En el futuro su riesgo cardiovascular va a ser elevado y debe evitar por todos los medios el hábito tabáquico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33489, 11851, '2. Sus padres y hermanos deben estudiarse el perfil lipídico pues pueden tener alguna forma de hipercolesterolemia familiar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33490, 11851, '3. Su problema no es relevante por ahora, y no modificar sustancialmente sus hábitos, excepto el tabaco, si es que fuma, volviendo a revisiones anuales a par?r de los 35 años de edad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33491, 11851, '4. Debe procurar limitar el consumo de grasas de origen animal y mantener durante toda su vida un grado de ejercicio fsico moderado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33492, 11851, '5. Deberá tomar un fármaco hipolipemiante en el plazo de 6 meses si con las recomendaciones dieté?cas su colesterol LDL no baja por debajo de los límites recomendables para su situación de riesgo laboral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33493, 11852, '1. La hiperprolac?nemia es causa de casi el 20% de las amenorreas postpuberales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33494, 11852, '2. Causa amenorrea hipergonadotropa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33495, 11852, '3. El hipo?roidismo primario es causa de hiperprolac?nemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33496, 11852, '4. El tratamiento médico de elección es la cabergolina.', false, 4);
