INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33528, 11859, '4. Caquexia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33529, 11860, '1. Reduce la glucemia y la tensión arterial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33530, 11860, '2. Evita el riesgo de taquiarritmias, incluso después de un infarto de miocardio reciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33531, 11860, '3. Es aplicable en cualquier situación de prevención primaria como de prevención secundaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33532, 11860, '4. Aumenta mucho las concentraciones de colesterol HDL, aunque eleve un poco las concentraciones de colesterol LDL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33533, 11860, '5. Reduce el consumo muscular de oxígeno.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33534, 11861, '1. Desregulación en la señalización de nu- trientes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33535, 11861, '2. Acortamiento de los telómeros.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33536, 11861, '3. Disfunción mitocondrial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33537, 11861, '4. Agotamiento de células madre.', false, 4);
