INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33539, 11862, '2. Quiste de ovario complicado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33540, 11862, '3. Apendicitis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33541, 11862, '4. Enfermedad inflamatoria pélvica.', false, 4);
