INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33543, 11863, '2. Hiperplasia endometrial atípica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33544, 11863, '3. Pólipo endometrial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33545, 11863, '4. Coriocarcinoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33546, 11864, '105. 000 UI/L. Se aporta imagen de la ecografía transvaginal (imagen vinculada). ¿Qué indicaría en ese momento?', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33547, 11864, '1. Repetir seriadamente cada 2 días la ecografía y la beta-HCG.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33548, 11864, '2. Tranquilizar a la paciente, indicar reposo, antieméticos y repetir la ecografía en una semana.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33549, 11864, '3. Legrado uterino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33550, 11864, '4. Tratamiento con misoprostol por vía sistémica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33551, 11865, '1. Beta-HCG en sangre.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33552, 11865, '2. Histeroscopia diagnóstica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33553, 11865, '3. Legrado uterino diagnostico-terapéutico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33554, 11865, '4. Estudio hormonal ginecológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33555, 11866, '1. Tratamiento con metotrexate y ácido folínico semanales hasta normalizar las cifras de b-HCG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33556, 11866, '2. Determinación semanal de b-HCG hasta que tres consecutivas sean negativas, después determinación mensual hasta completar el año.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33557, 11866, '3. Realización de TC cerebral y torácico cada 3 meses durante 1 año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33558, 11866, '4. Realización de radiografía simple de tórax cada 3 meses durante 1 año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33559, 11867, '1. Le pautaría una profilaxis con atosibán por vía oral durante todo el embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33560, 11867, '2. Le ofrecería la maduración pulmonar con corticoides a partir de las 19-20 semanas de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33561, 11867, '3. Le recomendaría realizar un cerclaje cervical programado a partir de la semana 14 de gestación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33562, 11867, '4. Le aconsejaría no intentar más embarazos por el alto riesgo de recidiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33563, 11867, '5. Le recomendaría recurrir a las técnicas de reproducción asistida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33564, 11868, '1. Insuficiencia o fallo ovárico prematuro.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33565, 11868, '2. Adenoma hipofisario primario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33566, 11868, '3. Amenorrea hipotalámica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33567, 11868, '4. Sospecha de síndrome de Kallman o síndrome de Prader-Willi requiriéndose diagnósMco diferencial según otros datos clínicos de la paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33568, 11869, '1. Niveles séricos de estradiol en mitad de ciclo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33569, 11869, '2. Niveles séricos de hormona folículo esMmulante (FSH) en mitad de ciclo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33570, 11869, '3. Niveles séricos de hormona anMmulleriana (AMH) en cualquier momento del ciclo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33571, 11869, '4. Determinación conjunta de FSH y estradiol en día 8 del ciclo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33572, 11870, '1. En su caso está indicado el THM al menos hasta los 50 años si no aparecen contraindicaciones, porque el beneficio supera el riesgo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33573, 11870, '2. Puede obtener beneficio de la THM, pero la duración del tratamiento no debe superar los cinco años por el riesgo de cáncer de mama que tendría prolongarlo más.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33574, 11870, '3. La THM no Mene indicación en su caso al no presentar sintomatología vasomotora (sofocos) ni otros síntomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33575, 11870, '4. La THM no Mene indicación en su caso por no presentar sofocos, pero puede uMlizar estrógenos locales para prevenir la sequedad vaginal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33576, 11871, '1. La primera medida a realizar es una resonancia cerebral porque lo más probable es que sea un macroadenoma secretor de prolactina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33577, 11871, '2. Se debe interrogar sobre la toma de fármacos antagonistas del receptor de dopamina o un posible embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33578, 11871, '3. Las pruebas de laboratorio para su correcta caracterización consisten en la medición aislada de prolactina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33579, 11871, '4. Se debe descartar un hipertiroidismo primario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33580, 11872, '1. Fallo ovárico prematuro, por lo que le pauta terapia hormonal sustitutiva y control en 3 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33581, 11872, '2. Síndrome de Asherman, por lo que indica una histeroscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33582, 11872, '3. Amenorrea central hipofisaria (síndrome de Sheehan), por lo que solicita resonancia magnética cerebral para confirmar el diagnóstico y pautar tratamiento sustitutivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33583, 11872, '4. Amenorrea central hipotalámica funcional, por lo que solicita resonancia magnética para descartar otras patologías.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33584, 11873, '1. Le explica los hallazgos y descarta que el leiomioma, dada la localización, sea la causa de sus sangrados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33585, 11873, '2. Le explica que el leiomioma es probablemente la causa de los sangrados y la deriva a la consulta de histeroscopias.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33586, 11873, '3. Le explica que el leiomioma es probablemente la causa de los sangrados y la deriva a la consulta de ginecología para programar una miomectomía por laparoscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33587, 11873, '4. Dados los hallazgos ecográficos, solicita resonancia magnéoca preferente, pauta un análogo de la GnRH y revisión en consulta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33588, 11874, '1. Probablemente está menopáusica, pero hasta que no se cumplan los 12 meses de amenorrea no podrá iniciar ningún tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33589, 11874, '2. Insuficiencia ovárica prematura. Inicia estudio con cariotipo e indica terapia hormonal sustitutiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33590, 11874, '3. Insuficiencia ovárica prematura. Le explica que son esenciales los hábitos de vida saludables: no fumar, ejercicio y adecuada ingesta de vitamina D. La terapia hormonal la deja como tratamiento de segunda línea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33591, 11874, '4. Amenorrea hipotalámica. Precisa estudio con una RM craneal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33592, 11875, '1. Se presenta en mujeres jóvenes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33593, 11875, '2. Clínicamente se caracteriza por la presencia de hirsutismo, acné y amenorrea u oligomenorrea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33594, 11875, '3. Se asocia a obesidad y resistencia a la insulina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33595, 11875, '4. Aumenta el riesgo de cáncer de ovario.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33596, 11876, '1. Los estrógenos vaginales son un tratamiento farmacológico eficaz para los síntomas urogenitales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33597, 11876, '2. Las dosis de estrógenos administrados en la terapia hormonal deben alcanzar niveles plasmáticos similares o superiores a los alcanzados en un ciclo menstrual normal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33598, 11876, '3. La tibolona es un fármaco indicado en mujeres con antecedentes de cáncer de mama y clínica vasomotora intensa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33599, 11876, '4. En mujeres con útero está indicada la terapia hormonal sistémica con solo estrógenos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33600, 11877, '1. Inseminación artificial y FSH (hormona foliculoestimulante).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33601, 11877, '2. Aumentar la dosis de citrato de clomifeno a 200 mg/día 5 días, durante 6 meses más.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33602, 11877, '3. Fecundación in vitro (FIV).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33603, 11877, '4. Metformina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33604, 11878, '1. Todos sus hijos varones serán portadores y, por tanto, manifestarán la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33605, 11878, '2. Existe un fenómeno de anticipación genética, por lo que su descendencia presentará síntomas más graves y más precoces.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33606, 11878, '3. El diagnóstico genético preimplantacional para la selección de sexo de los embriones mediante hibridación in situ fluorescente (FISH) es la mejor opción para tener descendencia sana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33607, 11878, '4. El 50% de sus hijas serán portadoras, pero no presentarán manifestaciones clínicas de la enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33608, 11879, '1. El nivel en sangre de testosterona libre es predictor del éxito terapéutico de la administración exógena de andrógenos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33609, 11879, '2. El uso de estrógenos orales combinados con gestágenos vaginales es el tratamiento más eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33610, 11879, '3. La terapia estrogénica local en la vagina con preparados de dosis baja no precisa de combinación con gestágenos.', true, 3);
