INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33758, 11912, '1. Se ha de ofrecer consejo contraceptivo estructurado según los criterios de elegibilidad de la Organización Mundial de la Salud (OMS), e información tanto para la prevención de embarazos no planificados, como de enfermedades de transmisión sexual (ETS).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33759, 11912, '2. Como método anticonceptivo de urgencias, las opciones recomendadas son la toma de levonorgestrel, de acetato de ulipristal o la inserción de un DIU de cobre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33760, 11912, '3. Ante la indicación de anticonceptivos orales se recomienda el cribado rutinario de trombofilia y dislipemia y citologías de control anuales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33761, 11912, '4. El riesgo de tromboembolia venosa con el consumo de anticonceptivos orales es bajo, siendo el riesgo menor en los de segunda generación, frente al mayor riesgo en los de tercera y cuarta generación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33762, 11913, '1. Benzodiacepinas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33763, 11913, '2. Estrógenos vaginales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33764, 11913, '3. Estrógenos y progestágenos orales en pauta continua.', false, 3);
