INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33766, 11914, '1. Le explica que, si está en amenorrea, no requiere de otro método anticonceptivo puesto que la lactancia materna es suficiente como método anticonceptivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33767, 11914, '2. Le informa que el DIU de levonogestrel está contraindicado por haber tenido una cesárea hace menos de un año.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36080, 12420, '2. Salmonella.', false, 2);
