INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33787, 11919, '1. Tienen un efecto protector contra el Carcinoma de Mama.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33788, 11919, '2. Tienen un efecto protector contra el Carcinoma de Endometrio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33789, 11919, '3. Tienen un efecto protector contra el Carcinoma de Ovario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33790, 11919, '4. Incrementan el riesgo de Carcinoma de cervix en mujeres HPV positivas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33791, 11919, '5. No se ha encontrado asociación con el Carcinoma hepático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33792, 11920, '1. Hipertensión arterial bien controlada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33793, 11920, '2. Historia personal de tromboembolismo previo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33794, 11920, '3. Diabetes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33795, 11920, '4. Mujer de menos de 35 años y fumadora.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33796, 11920, '5. Infección urinaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33797, 11921, '1. La vaginosis bacteriana es habitualmente una infección monomicrobiana.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33798, 11921, '2. La vulvovaginitis candidiásica es la infección vulvovaginal más prevalente en Europa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33799, 11921, '3. Se define como vulvovaginitis candidiásica recidivante cuando aparecen 4 o más episodios en un año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33800, 11921, '4. La vaginosis bacteriana únicamente debe tratarse farmacológicamente cuando es sintomática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33801, 11922, '1. Iniciaríamos tratamiento antibiótico tan pronto como sospechemos el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33802, 11922, '2. Indicaríamos como prueba complementaria preferente una histerosalpingografía para valoración tubárica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33803, 11922, '3. El retraso en el diagnóstico y tratamiento aumenta la aparición de secuelas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33804, 11922, '4. La presencia de absceso sería criterio de hospitalización.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33805, 11923, '1. Sólo el 20% de las mujeres sexualmente activas se infectará por este virus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33806, 11923, '2. La mayoría de las mujeres infectadas desarrollarán displasia cervical o cáncer.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33807, 11923, '3. No se ha demostrado que otros cofactores como el tabaco o una respuesta inmunitaria alterada estén relacionados con el desarrollo de displasia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33808, 11923, '4. El virus es transitorio en la mayoría de las mujeres.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33809, 11924, '1. Genotipo 16.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33810, 11924, '2. Genotipo 11.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33811, 11924, '3. Genotipo 6.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33812, 11924, '4. Genotipo 23.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33813, 11924, '5. Genotipo 55.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33814, 11925, '1. El embarazo aumenta el riesgo de esta infección.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33815, 11925, '2. Puede presentarse en mujeres que nunca tuvieron relaciones sexuales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33816, 11925, '3. Es típica la secreción vaginal con placas o grumos blancos adheridos a las paredes de la vagina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33817, 11925, '4. Se puede diagnosticar en un frotis en fresco de la secreción vaginal sin necesidad de tinción.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33818, 11925, '5. Al añadir una gota de potasa a la secreción vaginal se desprende un fuerte olor a pescado.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33819, 11926, '1. Cáncer de cérvix.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33820, 11926, '2. Cáncer de endometrio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33821, 11926, '3. Cáncer de ovario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33822, 11926, '4. Cáncer de mama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33823, 11926, '5. Linfoma de Burkitt', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33824, 11927, '1. Clindamicina y gentamicina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33825, 11927, '2. Metronidazol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33826, 11927, '3. Azitromicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33827, 11927, '4. Amoxicilina-clavulánico y doxicilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33828, 11927, '5. Ceftriaxona y doxiciclina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33829, 11928, '1. La mayoría de las veces se origina por vía ascendente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33830, 11928, '2. Para el diagnóstico es imprescindible la toma de cultivo por laparoscopia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33831, 11928, '3. La promiscuidad sexual incrementa el riesgo de padecer la enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33832, 11928, '4. Puede tener como secuela la esterilidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33833, 11928, '5. Los gérmenes causantes de la enfermedad más frecuentes son la Neisseria gonorrhoeae y la Chlamydia trachomatis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33834, 11929, '1. Los serotipos 16 y 18 son los causantes del 70% de los cánceres de cervix uterino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33835, 11929, '2. La vacuna tetravalente ha demostrado disminución del riesgo de neoplasia de cervix en mujeres no infectadas previamente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33836, 11929, '3. La inmunidad que se adquiere ya se ha comprobado que es de por vida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33837, 11929, '4. La vacuna tetravalente también reduce el riesgo de lesiones vaginales asociadas al HPV en mujeres.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33838, 11929, '5. Se están llevando a cabo estudios para valorar el coste-efectividad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33839, 11930, '1. La demostración de que no aparece cáncer cervical en los vacunados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33840, 11930, '2. La demostración de que se producen anticuerpos tras la vacunación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33841, 11930, '3. La demostración de protección frente a la aparición de lesiones preneoplásicas (CIN 2/3) asociadas a los virus incluidos en la vacuna.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33842, 11930, '4. La demostración de la remisión del cáncer cervical en las mujeres vacunadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33843, 11930, '5. Estudios clínicos no controlados.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33844, 11931, '1. El endometrio está engrosado y ante la clínica de la paciente, toma una biopsia endometrial con cánula de Cornier.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33845, 11931, '2. El endometrio no está engrosado por lo que le pauta ácido tranexámico y seguimiento ambulatorio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33846, 11931, '3. Tiene indicación de histeroscopia diagnóstica sin necesidad de toma de biopsia endometrial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33847, 11931, '4. El endometrio no está engrosado, pero como tiene clínica de metrorragia está indicada la realización de una biopsia endometrial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33848, 11932, '1. Ecografía transvaginal y toma de endometrio.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33849, 11932, '2. Ecografía de abdomen completo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33850, 11932, '3. Histeroscopia bajo sedación y biopsia según hallazgos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33851, 11932, '4. Especuloscopia y citología cervical.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33852, 11933, '1. Ecografía transvaginal y medición del espesor endometrial. En función de éste tomar biopsia endometrial o no.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33853, 11933, '2. Biopsia endometrial por aspiración en consulta. Con ella puedo obtener el diagnóstico muy fiablemente y es económica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33854, 11933, '3. Histeroscopia con sedación y biopsia dirigida si se ve alguna lesión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33855, 11933, '4. Realizaría un microlegrado, ya que es la prueba que me proporcionaría el diagnóstico definitivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33856, 11934, '1. Histerectomía total conservando anejos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33857, 11934, '2. Anticonceptivos combinados orales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33858, 11934, '3. Ablación endometrial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33859, 11934, '4. DIU de levonorgestrel.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33860, 11935, '1. Repetir la ecografía al cabo de 6 meses.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33861, 11935, '2. Miomectomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33862, 11935, '3. Histerectomía conservando los ovarios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33863, 11935, '4. Tratamiento con análogos de Gn-RH durante 6 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33864, 11936, '1. Realizar aspirado endometrial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33865, 11936, '2. Solicitar una histeroscopia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33866, 11936, '3. Instaurar tratamiento con estrógeno-gestágenos orales y seguimiento clínico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33867, 11936, '4. Instaurar tratamiento con ácido tranexámico en las menstruaciones y seguimiento clínico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33868, 11937, '1. La cirugía ginecológica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33869, 11937, '2. El parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33870, 11937, '3. El cáncer de cuello de útero o vagina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33871, 11937, '4. La radioterapia de los cánceres ginecológicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33872, 11938, '1. Prescribir progesterona cíclica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33873, 11938, '2. Biopsia endometrial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33874, 11938, '3. Biopsias de cérvix al azar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33875, 11938, '4. Valoración hormonal con FSH, LH y estradiol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33876, 11939, '1. Realizar estudio de coagulación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33877, 11939, '2. Solicitar exploración pélvica con TC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33878, 11939, '3. Tratamiento de prueba con anovulatorios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33879, 11939, '4. Histerectomía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33880, 11939, '5. Biopsia endometrial.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33881, 11940, '1. Conización de cérvix.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33882, 11940, '2. Citología endometrial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33883, 11940, '3. Histeroscopia y biopsia de endometrio.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33884, 11940, '4. Resonancia nuclear magnética de pelvis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33885, 11940, '5. Exploración bajo anestesia de aparato genital y biopsia de cérvix y endometrio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33886, 11941, '1. Histerectomía total con salpingooforectomía bilateral.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33887, 11941, '2. Análogos GnRH.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33888, 11941, '3. Resección endometrial por histeroscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33889, 11941, '4. Dispositivo liberador de levonorgestrel.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33890, 11941, '5. Gestágenos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33891, 11942, '1. Corrección quirúrgica del cistocele.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33892, 11942, '2. Realización de diario miccional y reeducación vesical.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33893, 11942, '3. Indicación de flujometría y evaluación de la función uretral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33894, 11942, '4. Prescripción de tratamiento oral con fármacos colinérgicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33895, 11943, '1. En la incontinencia urinaria de esfuerzo, un factor precipitante es el ejercicio físico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33896, 11943, '2. En la incontinencia de urgencia la frecuencia miccional es normal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33897, 11943, '3. La prueba más fiable para establecer un diagnóstico exacto del tipo de incontinencia es el estudio urodinámico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33898, 11943, '4. En el tratamiento de la incontinencia de orina de urgencia se utilizan medicamentos anticolinérgicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33899, 11944, '1. Absceso pélvico secundario a apendicitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33900, 11944, '2. Litiasis ureteral derecha con formación de urinoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33901, 11944, '3. Tumor desmoide mesentérico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33902, 11944, '4. Teratoma ovárico maduro.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33903, 11945, '"1. Solicita una ecografía mamaria dada la edad de la paciente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33904, 11945, '2. Solicita una mamografía porque es la prueba diagnóstica “patrón oro"".', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33905, 11945, '3. Solicita una resonancia magnética dada la edad de la paciente y el antecedente familiar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33906, 11945, '4. Le explica que, al tener 30 años, probablemente sea un quiste y optará por un control clínico en 6-12 meses. Si persiste, entonces solicitará una prueba de imagen."', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33907, 11946, '1. Teratocarcinoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33908, 11946, '2. Teratoma inmaduro.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33909, 11946, '3. Teratoma quístico maduro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33910, 11946, '4. Disgerminoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33911, 11947, '1. Los pólipos endometriales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33912, 11947, '2. El embarazo tubárico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33913, 11947, '3. Los miomas submucosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33914, 11947, '4. Algunas malformaciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33915, 11947, '5. Las hemorragias por hipertrofia endometrial.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33916, 11948, '1. Disgerminoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33917, 11948, '2. Carcinoma embrionario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33918, 11948, '3. Teratoma maduro quístico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33919, 11948, '4. Teratoma inmaduro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33920, 11948, '5. Teratoma maduro sólido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33921, 11949, '1. Mujer de 26 años sin citologías previas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33922, 11949, '2. Mujer de 40 años con citología y virus del papiloma humano negativos hace 3 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33923, 11949, '3. Mujer de 67 años con incontinencia urinaria de esfuerzo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33924, 11949, '4. Mujer de 22 años vacunada para el virus del papiloma', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33925, 11950, '1. Solicitar detección del virus del papiloma humano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33926, 11950, '2. Conización cervical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33927, 11950, '3. No tratar y programar nueva revisión en 6-12 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33928, 11950, '4. Tratamiento con aciclovir durante 16 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33929, 11951, '1. Cáncer de endometrio y cáncer de ovario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33930, 11951, '2. Cáncer de mama y cáncer de ovario.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33931, 11951, '3. Cáncer de mama y cáncer de endometrio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33932, 11951, '4. Cáncer de cuello uterino y cáncer de mama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33933, 11952, '1. Hacer colposcopia. Si es normal, programar una conización.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33934, 11952, '2. Confirmar la citología con una biopsia de cérvix bajo control colposcópico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33935, 11952, '3. Repetir citología para confirmar diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33936, 11952, '4. Hacer tipaje de virus HPV. Realizar conización si el test de HPV es positivo a virus de alto riesgo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33937, 11953, '1. Repetir la citología en 1 mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33938, 11953, '2. Colposcopia con eventual biopsia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33939, 11953, '3. Histerectomía con salpinguectomía bilateral y conservación de ovarios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33940, 11953, '4. Legrado uterino fraccionado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33941, 11954, '1. Ninguna', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33942, 11954, '2. Citología endometrial', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33943, 11954, '3. Ecografía transvaginal', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33944, 11954, '4. Biopsia endometrial por aspiración', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33945, 11954, '5. Determinación en plasma del marcador tumoral CA 12.5', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33946, 11955, '1. Un mayor riesgo de presentar cáncer de mama exclusivamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33947, 11955, '2. Un mayor riesgo de presentar cáncer de mama y de ovario.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33948, 11955, '3. Dado que es una mutación de trasmisión autonómico recesiva el riesgo de presentar cáncer de mama es menor del 10% a lo largo de la vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33949, 11955, '4. La mastectomía profiláctica de las pacientes portadoras de esta mutación sólo debe realizarse (si se indica) por encima de los 45 años (postmenopausia), ya que por encima de esta edad existe la mayor incidencia de tumores de mama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33950, 11955, '5. Mejor pronóstico si presentan un cáncer de mama, ya que la histopatología de los tumores que aparecen en las pacientes portadoras es más favorable (en términos de grado histológico de malignidad, presencia de receptores hormonales, etc.).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33951, 11956, '1. Histerectomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33952, 11956, '2. Vacunación para el virus del papiloma humano (HPV).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33953, 11956, '3. Tratamiento antiinflamatorio local.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33954, 11956, '4. Seguimiento citológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33955, 11956, '5. Conización cervical.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33956, 11957, '1. Que el genoma vírico se halla integrado en el ADN celular del huésped y que el riesgo de desarrollo de un carcinoma invasivo es alto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (33957, 11957, '2. Que el genoma vírico no se halla integrado en el ADN celular del huésped y que el riesgo de desarrollo de un carcinoma invasivo es alto.', false, 2);
