INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34029, 11973, '1. Laparotomía exploradora, para diagnosticar y tratar un probable cáncer de ovario.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34030, 11973, '2. Puede tratarse de un quiste lúteo, convendría realizar un tratamiento de prueba con anovulatorios y reevaluar en tres meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34031, 11973, '3. Se trata de un cáncer diseminado, la paciente debe recibir quimioterapia sistémica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34032, 11973, '4. Vigilancia, repitiendo la exploración con escáner en tres meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34033, 11973, '5. Antibioterapia de amplio espectro, ante la posibilidad de una infección de origen ginecológico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34034, 11974, '1. Control evolutivo mediante seriación ecográfica y del nivel del marcador.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34035, 11974, '2. Completar el estudio mediante marcadores de estirpe germinal (alfafetoproteína/gonadotropina coriónica).', false, 2);
