INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34059, 11979, '1. Tranquilizarle, puesto que ya se ha hecho una prueba de imagen y se ha descartado malignidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34126, 11995, '3. La presencia de adenopatías axilares contraindica la cirugía de la mama.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34060, 11979, '2. Esa clasificación implica probablemente cirugía dado que la probabilidad de cáncer es mayor del 10 %. Se lo explica y le deriva de forma preferente a la Unidad de Mama.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34061, 11979, '3. Se trata de un hallazgo probablemente benigno, dado que hay menos de un 2 % de probabilidad de cáncer. Le explica que requiere de un seguimiento cada 6-12 meses hasta los 24 meses o una biopsia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34062, 11979, '4. Los hallazgos son de baja sospecha de cáncer (entre un 2 y un 10 %) pero es necesario hacer una biopsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34063, 11980, '1. Dado el carácter hemático de la secreción el diagnóstico más probable es el de carcinoma ductal infiltrante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34064, 11980, '2. Papiloma intraductal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34065, 11980, '3. Enfermedad de Paget del pezón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34066, 11980, '4. Hiperprolactinemia tumoral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34067, 11980, '5. La mamografía nos indicará el diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34068, 11981, '1. Presenta una incidencia por edad con un pico entre los 50 y 60 años que se reduce a partir de esta edad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34069, 11981, '2. El carcinoma ductal in situ se estadifica como estadio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34070, 11981, '3. El tipo histológico más frecuente es el carcinoma lobulillar infiltrante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34071, 11981, '4. La mayoría de los casos de cáncer de mama se desarrollan en mujeres con riesgo genético para padecerlo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34072, 11982, '1. Realizar la exéresis del nódulo mamario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34073, 11982, '2. Realizar pruebas de imagen cada 6 meses para comprobar si existe crecimiento y en ese caso ampliar el estudio con biopsia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34074, 11982, '3. Realizar biopsia percutánea con aguja gruesa del nódulo para estudio histopatológico, estimando una probabilidad de malignidad menor o igual al 10%.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34075, 11982, '4. No es aplicable en este caso la catalogación porque el sistema Birads se definió para clasificar las microcalcificaciones, no los nódulos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34076, 11983, '1. Realización de actividad física con elevación del miembro superior derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34077, 11983, '2. Terapia física con fisioterapia descongestiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34078, 11983, '3. Diuréticos para reducir edema.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34079, 11983, '4. Liposucción.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34080, 11984, '1. El cáncer de mama triple negativo es el subtipo más frecuente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34081, 11984, '2. El cáncer de mama HER2+ es el subtipo menos agresivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34082, 11984, '3. El cáncer de mama luminal A es el subtipo más raro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34083, 11984, '4. El cáncer de mama triple negativo es el subtipo más agresivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34084, 11985, '1. No está indicada en pacientes postmenopáusicas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34085, 11985, '2. Solo la pueden recibir pacientes diagnosticadas de carcinoma in situ.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34086, 11985, '3. Es de elección en pacientes con ganglios positivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34087, 11985, '4. No se debe emplear cuando hay más de un foco tumoral o lesiones multicéntricas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34088, 11986, '1. Debe incluir las regiones ganglionares locorregionales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34089, 11986, '2. Está contraindicada después de la mastectomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34090, 11986, '3. Está contraindicada después de la quimioterapia neoadyuvante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34091, 11986, '4. Su mejor alternativa estética es la irradiación parcial de la mama.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34092, 11987, '1. Incremento de la supervivencia global.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34093, 11987, '2. Transformar tumores no resecables en resecables para la cirugía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34094, 11987, '3. Aumentar la supervivencia libre de progresión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34095, 11987, '4. Mejorar el control de síntomas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34096, 11988, '1. Consumo moderado de alcohol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34097, 11988, '2. Obesidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34098, 11988, '3. Mastopatía fibroquística.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34099, 11988, '4. Menopausia tardía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34100, 11989, '1. Quimioterapia basada en antraciclinas y taxanos, radioterapia y trastuzumab.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34101, 11989, '2. Quimioterapia basada en antraciclinas y taxanos, radioterapia y tamoxifeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34102, 11989, '3. Quimioterapia basada en antraciclinas y taxanos, y radioterapia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34103, 11989, '4. Quimioterapia basada en antraciclinas y taxanos, radioterapia e inhibidores de la aromatasa, dado que es postmenopáusica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34104, 11990, '1. Hormonoterapia adyuvante que incluya inhibidores de aromatasa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34105, 11990, '2. Quimioterapia adyuvante, preferentemente con antraciclinas y taxanos, seguida de hormonoterapia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34106, 11990, '3. Quimioterapia adyuvante en asociación con el anticuerpo monoclonal trastuzumab, seguida de hormonoterapia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34107, 11990, '4. Quimioterapia adyuvante, preferiblemente con antraciclinas y taxanos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34108, 11991, '1. Biopsia selectiva de ganglio centinela.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34109, 11991, '2. Radioterapia + hormonoterapia con tamoxifeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34110, 11991, '3. Mastectomía + linfadenectomía axilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34111, 11991, '4. Quimioterapia + radioterapia + hormonoterapia con tamoxifeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34112, 11992, '1. Supone aproximadamente un 20% de todos los casos de cáncer de mama.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34113, 11992, '2. Se debe sospechar en aquellas familias con varios miembros afectados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34114, 11992, '3. Las alteraciones genéticas conocidas causantes del cáncer de mama hereditario suelen tener una herencia autosómica recesiva.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34115, 11992, '4. Puede estar indicado llevar a cabo una mastectomía profiláctica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34116, 11993, '1. Estudio fenotípico completo mediante citometría de flujo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34117, 11993, '2. Estudio de receptores hormonales y de HER2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34118, 11993, '3. Estudio de receptores hormonales, ecadherina y estudio de familiares de primer grado.', false, 3);
