INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34149, 12000, '1. Las células tumorales muestran infiltración epidérmica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34150, 12000, '2. Corresponde a formas de carcinoma in situ.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34151, 12000, '3. Tiene abundante infiltrado inflamatorio en el estroma del tumor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34152, 12000, '4. Tiene buen pronóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34153, 12000, '5. Muestra invasión de los linfáticos dérmicos por células tumorales.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34154, 12001, '1. En formol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34155, 12001, '2. En fresco.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34156, 12001, '3. En un envase lleno de suero fisiológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34157, 12001, '4. En alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34158, 12001, '5. Da igual en que medio fijador, lo importante es que se mande inmediatamente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34159, 12002, '1. Ecografía mamaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34160, 12002, '2. Mamografía.', false, 2);
