INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34164, 12003, '"1. Eccema de areola-pezón.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34165, 12003, '2. Microcalcificaciones en mamografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34166, 12003, '3. Inflamación generalizada de la mama.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34167, 12003, '4. Adenopatía axilar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34168, 12003, '5. Nódulo con imagen mamográfica de calcificación semilunar o en ""cáscara de huevo""."', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34169, 12004, '1. No se debe realizar en pacientes con ganglios palpables.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34170, 12004, '2. No evita la realización de una linfadenectomía axilar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34171, 12004, '3. Se realiza mediante marcado con arpón de un ganglio axilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34172, 12004, '4. Sirve para detectar los ganglios axilares sanos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34173, 12004, '5. Se realiza simultáneamente en ambas axilas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34174, 12005, '1. Ganglios paraesternales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34175, 12005, '2. Ganglios intercostales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34176, 12005, '3. Ganglios axilares.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34177, 12005, '4. Ganglios diafragmáticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34178, 12005, '5. Ganglios abdominales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34179, 12006, '1. El ganglio centinela es el primer ganglio que recibe el drenaje linfático del tumor primario.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34180, 12006, '2. El ganglio centinela es el primer ganglio metastatizado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34181, 12006, '3. Para su correcta localización es imprescindible la inyección de un colorante en la zona peritumoral (azul de isosulfan).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34182, 12006, '4. La existencia de una adenopatía axilar palpable en una paciente con un tumor de 3 cm de diámetro no se considera una contraindicación a la técnica de detección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34183, 12006, '5. Si durante la identificación del ganglio centinela solo capta la cadena mamaria interna se considerará como prueba fallida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34184, 12007, '1. pT N M . 3 1 0', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34185, 12007, '2. pT N M . 1a 0 0', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34186, 12007, '3. pT N M . 1b 0 0', true, 3);
