INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34189, 12008, '1. Sistemáticamente diferida al cabo de 5 años libre de enfermedad postmastectomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34190, 12008, '2. El momento (inmediato-diferido) vendrá indicado por el número de ganglios positivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34191, 12008, '3. La quimioterapia postoperatoria es una contraindicación para realizar la reconstrucción inmediata.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34192, 12008, '4. De forma inmediata, pues la reconstrucción de la mama no interfiere en la historia natural de la enfermedad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34193, 12008, '5. A partir de los 60 años es mejor el uso de prótesis externa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34194, 12009, '1. BCRA1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34195, 12009, '2. Her2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34196, 12009, '3. P53.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34197, 12009, '4. Receptor de estrógeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34198, 12009, '5. Receptor de progesterona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34199, 12010, '1. El riesgo de padecer cáncer de mama en mujeres portadoras de mutaciones en alguno de estos genes es del 60-85%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34200, 12010, '2. El riesgo de padecer además cáncer de ovario es mayor en las mujeres portadoras de mutación en el BRCA1 que en las portadoras de mutación en el BRCA2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34201, 12010, '3. Los cánceres de mama asociados a mutaciones en el BRCA1 son generalmente bien diferenciados en comparación con los cánceres de mama esporádicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34202, 12010, '4. Mutaciones en los genes BRCA1 y BRCA2 son muy poco frecuentes en cánceres de mama esporádicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34203, 12010, '5. La prevalencia de mutaciones del BRCA1 es mayor que la del BRCA2.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34204, 12011, '1. Hormonoterapia primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34205, 12011, '2. Quimioterapia neoadyuvante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34206, 12011, '3. Mastectomía y linfadenectomía axilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34207, 12011, '4. Tumorectomía y ganglio centinela.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34208, 12011, '5. Trastuzumab.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34209, 12012, '1. Quimioterapia primaria en combinación con trastuzumab.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34210, 12012, '2. Tumorectomía con exéresis del ganglio centinela con radioterapia posterior.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34211, 12012, '3. Hormonoterapia con Tamoxifeno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34212, 12012, '4. Mastectomía con linfadectomía axilar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34213, 12012, '5. Radioterapia externa como único tratamiento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34214, 12013, '1. Se sobreexpresa en un 20-25% de los cánceres de mama.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34215, 12013, '2. Las pacientes con cánceres que sobreexpresan el oncogén Her-2 se pueden beneficiar del tratamiento con Trastuzumab.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34216, 12013, '3. Los cánceres de mama que sobreexpresan el oncogén Her-2 tienen mejor pronóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34217, 12013, '4. La sobreexpresión de Her-2 se ha relacionado con la resistencia al tratamiento antihormonal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34218, 12013, '5. Existen datos que señalan que se benefician del tratamiento con antraciclinas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34219, 12014, '1. Se produce con mayor frecuencia en familias desestructuradas y con pocos recursos económicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34220, 12014, '2. Los agresores presentan con frecuencia trastornos psiquiátricos graves que explican la conducta violenta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34221, 12014, '3. Las vícMmas rara vez acuden a los servicios sanitarios por miedo a ser idenMficadas como vícMmas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34222, 12014, '4. El embarazo es un periodo de riesgo para el inicio o agravamiento de la violencia de género.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34223, 12015, '1. Trombocitemia esencial. Estudio de médula ósea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34224, 12015, '2. Betatalasemia intermedia. Electroforesis de hemoglobinas y estudio genético.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34225, 12015, '3. Esferocitosis hereditaria. Prueba de unión con esosina-5’-maleimida (EMA).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34226, 12015, '4. Anemia ferropénica. Ferritina sérica y estudios digestivos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34227, 12016, '1. Concentración de ferri^na en suero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34228, 12016, '2. Concentración de hemoglobina en re^culocitos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34229, 12016, '3. Volumen corpuscular medio de los hema‘es.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34230, 12016, '4. Concentración de transferrina en suero.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34231, 12017, '1. La esplenomegalia es un hallazgo frecuente en los cuadros de larga evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34232, 12017, '2. Puede producir episodios dolorosos por crisis oclusivas vasculares.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34233, 12017, '3. Es debida a un defecto congénito en las proteínas de la membrana eritrocitaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34234, 12017, '4. En el examen del fro^s sanguíneo se observa trombopenia y numerosos esquistocitos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34235, 12018, '1. Nivel sérico de vitamina B12.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34236, 12018, '2. Electroforesis de hemoglobinas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34237, 12018, '3. Test de Coombs directo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34238, 12018, '4. Nivel de ferritina en suero.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34239, 12019, '1. Exploración ginecológica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34240, 12019, '2. Estudio de sangre oculta en heces.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34241, 12019, '3. Estudio radiológico de aparato digestivo.', false, 3);
