INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34336, 12040, '4. El tratamiento de elección cuando es sintomática es la esplenectomía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34337, 12040, '5. Raramente se asocia a colelitiasis.', false, 5);
