INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34382, 12049, '5. β talasemia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34383, 12050, '1. Iniciar tratamiento con hierro oral y derivar a la consulta externa de Hematología para seguimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34384, 12050, '2. Transfundir dos concentrados de hematíes dado que el paciente presenta síndrome anémico franco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34385, 12050, '3. Realizar test de Coombs, recuento de reticulocitos y haptoglobina e iniciar tratamiento con esteroides.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34386, 12050, '4. Realizar aspirado de médula ósea lo antes posible para averiguar la etiología de la anemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34387, 12050, '5. Administrar Vitamina B12 y Ac. Fólico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34388, 12051, '1. Intoxicación por plomo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34389, 12051, '2. Alcoholismo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34390, 12051, '3. Síndrome mielodisplásico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34391, 12051, '4. Déficit de vitamina B12.', false, 4);
