INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34402, 12054, '2. Anemia inflamatoria (de proceso crónico).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34403, 12054, '3. Anemia ferropénica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34404, 12054, '4. Anemia por déficit de ácido fólico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34405, 12054, '5. Anemia hemolítica aguda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34406, 12055, '1. La síntesis de hepcidina está aumentada.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34407, 12055, '2. La anemia es característicamente macrocítica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34408, 12055, '3. Los niveles de ferritina están disminuidos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34409, 12055, '4. Los niveles de transferrina están elevados.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34410, 12055, '5. Debe tratarse con hierro intravenoso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34411, 12056, '1. La anemia aplásica suele estar ya presente en los primeros meses de vida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34412, 12056, '2. Son típicas las malformaciones esqueléticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34413, 12056, '3. El trasplante de progenitores hematopoyéticos es el tratamiento curativo, pero no hace desaparecer el riesgo de cáncer.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34414, 12056, '4. Los andrógenos suelen producir una respuesta favorable pero transitoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34415, 12057, '1. Secundaria a enfermedades autoinmunes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34416, 12057, '2. Primaria por leucemia aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34417, 12057, '3. Iatrogénica por administración de medicamentos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34418, 12057, '4. Debida al hiperesplenismo desarrollado en las infecciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34419, 12058, '1. Tratamiento con metilprednisolona a dosis de 1 g/Kg/día durante 5 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34420, 12058, '2. Estudio de hermanos y si alguno es HLA compatible, trasplante alogénico de progenitores hemopoyeticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34421, 12058, '3. Terapia inmunosupresora con ciclosporína e inmunoglobulina antitimocítica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34422, 12058, '4. Soporte hemoterápico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34423, 12058, '5. Quimioterapia y si respuesta trasplante autólogo de progenitores hemopoyeticos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34424, 12059, '1. Transfusiones periódicas y antibióticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34425, 12059, '2. Andrógenos y transfusiones de plaquetas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34426, 12059, '3. Trasplante de médula ósea alogénico si hermano HLA idéntico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34427, 12059, '4. Trasplante autólogo de médula ósea para evitar rechazo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34428, 12059, '5. Ciclosporina A y globulina antitimocítica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34429, 12060, '1. Toxicidad medular e inmunoterapia con timoglobulina y ciclosporina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34430, 12060, '2. Síndrome mielodísplásico y transfusiones periódicas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34431, 12060, '3. Anemia hemolítica autoinmune y corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34432, 12060, '4. Anemia perniciosa e inyecciones periódicas de vitamina B12.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34433, 12060, '5. Aplasia medular severa y trasplante de progenitores hematopoyéticos de un hermano histocompatible.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34434, 12061, '1. Cursa con pancitopenia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34435, 12061, '2. Se trata con trasplante de médula ósea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34436, 12061, '3. Puede responder al suero antitimocítico (ATG).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34437, 12061, '4. Cursa con eritroblastos en sangre periférica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34438, 12061, '5. Los reticulocitos están descendidos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34439, 12062, '1. Leucemia mieloide aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34440, 12062, '2. Síndrome mielodisplásico con exceso de blastos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34441, 12062, '3. Anemia megaloblás^ca.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34442, 12062, '4. Aplasia medular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34443, 12063, '1. El porcentaje de blastos en la médula ósea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34444, 12063, '2. El cariotipo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34445, 12063, '3. La dependencia transfusional de concentrados de hematíes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34446, 12063, '4. El recuento de plaquetas en la sangre periférica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34447, 12064, '1. Esta delección (5q-) es una alteración de buen pronóstico y tiene un tratamiento específico (la lenalidomida).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34448, 12064, '2. Lo recomendable en este paciente sería realizar tipajes HLA para organizar un trasplante alogénico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34449, 12064, '3. Se trata de un paciente con un Índice Internacional de Pronóstico (IPSS) alto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34450, 12064, '4. El tratamiento en este caso serían las transfusiones únicamente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34451, 12065, '1. Azacitidina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34452, 12065, '2. Imatinib.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34453, 12065, '3. Bortezomib.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34454, 12065, '4. Rituximab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34455, 12065, '5. Zoledronato.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34456, 12066, '1. Tiene mayor incidencia en mujeres jóvenes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34457, 12066, '2. La pancitopenia es un hallazgo poco frecuente (menos del 5%).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34458, 12066, '3. La presencia de citopenias o monocitosis sin anemia se da en más del 90% de los pacientes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34459, 12066, '4. La presencia de anemia con sideroblastos en anillo es de mal pronóstico y suele conllevar una supervivencia inferior a un año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34460, 12066, '5. La celularidad cuantitativa de la médula ósea está casi siempre aumentada o normal con patrón ferrocinético de eritropoyesis ineficaz.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34461, 12067, '1. Mieloma secretor de IgA leucemizado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34462, 12067, '2. Linfoma folicular leucemizado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34463, 12067, '3. Leucemia aguda mieloide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34464, 12067, '4. Leucemia aguda linfoide.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34465, 12068, '1. Si está se iniciará ácido trans retinoico (ATRA) y se recomendará controles en hospital de día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34466, 12068, '2. Se iniciará tratamiento con trióxido de arsénico, ATRA y terapia de soporte.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34467, 12068, '3. Es una leucemia mieloblástica tipo M3, por lo que se iniciara tratamiento quimioterápico y heparina para controlar la coagulación intravascular diseminada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34468, 12068, '4. Se debe iniciar tratamiento antibiótico. Cuando desaparezca la fiebre se iniciará el tratamiento de la leucemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34469, 12069, '1. Linfoma de Hodgkin.', false, 1);
