INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34598, 12097, '1. Es más exacta para la valoración de la médula ósea en el linfoma de Hodgkin (LH).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34599, 12097, '2. Realizada a mitad de tratamiento en el LH ayuda a decidir la duración del mismo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34600, 12097, '3. Es ú^l en los linfomas no Hodgkin de bajo grado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34601, 12097, '4. Al final del tratamiento puede diferenciar entre enfermedad residual y enfermedad ac^va.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34602, 12098, '1. Linfoma folicular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34603, 12098, '2. Linfoma de la zona marginal.', false, 2);
