INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34605, 12098, '4. Linfoma del manto.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34606, 12099, '1. Es el segundo linfoma más frecuente en Occidente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34607, 12099, '2. Las células neoplásicas derivan de un linfocito de la médula ósea.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34608, 12099, '3. Puede transformarse en un linfoma B difuso de célula grande.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34609, 12099, '4. Puede permanecer años sin necesitar tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34610, 12100, '1. El tratamiento de mantenimiento con rituximab prolonga la duración de las remisiones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34611, 12100, '2. En la era de la inmunoterapia, la actitud de observación sin tratamiento no es adecuada en este subtipo de linfoma.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34612, 12100, '3. La combinación de rituximab y CHOP consigue la remisión en un elevado porcentaje de pacientes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34613, 12100, '4. El trasplante de células madre hematopoyéticas puede ser útil tras las recaídas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34614, 12101, '220. 000/microL. MO: infiltrada por Linfoma folicular. Creatinina 1,5 mg/dL, LDH 235 U/L, Beta2 microglobulina 2,1 microg/mL. TAC: adenopatías menores de 3 cm en territorios cervical, axilar, retroperitoneo, ilíacos e inguinales, hígado y bazo normales. ¿Cuál de los siguientes tratamientos es el más apropiado?', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34615, 12101, '1. Rituximab-CHOP (Ciclofosfamida, Adriamicina, Vincristina, Prednisona).', false, 2);
