INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34617, 12101, '2. No tratar y vigilar (esperar y ver).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34618, 12101, '3. Rituximab-Bendamustina.', false, 5);
