INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34623, 12102, '5. Linfoma de Burkitt.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34624, 12103, '6. Cirugía citorreductora seguido de quimioterapia tipo Rituximab-CHOP hasta remisión completa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34625, 12103, '7. Rituximab-CHOP/21 x 6-8 ciclos seguido de Radioterapia del retroperitoneo.', false, 2);
