INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34627, 12103, '9. Quimioterapia intensiva que incluya Rituximab, dosis altas de Ciclofosfamida y profilaxis de SNC.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34628, 12103, '10. Retrasar tratamiento hasta obtener PET-TAC y luego tratar con Rituximab-CHOP /14 x 6-8 ciclos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34629, 12104, '5. Se presentan frecuentemente con grandes masas adenopáticas diseminadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34630, 12104, '6. Algunos casos se curan con tratamiento antibiótico.', true, 2);
