INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34702, 12119, '1. La forma de enfermedad de Hodgkin esclerosis nodular es especialmente frecuente en mujeres jóvenes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34703, 12119, '2. El linfoma de Burkitt se caracteriza por la t(14,28).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34704, 12119, '3. El linfoma folicular tiene habitualmente comportamiento clínico de alta malignidad, con difícil control duradero con las posibilidades terapéuticas actuales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34705, 12119, '4. La presentación inicial más frecuente de un linfoma MALT es una masa mediastínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34706, 12119, '5. La radioterapia nodal es el tratamiento de primera elección para un paciente con Enfermedad de Hodgkin en Estadío III-B en mujeres en edad fértil.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34707, 12120, '1. Depósito tubular de proteínas de Bence-Jones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34708, 12120, '2. Vasculitis necrotizante.', true, 2);
