INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34714, 12121, '4. Síndrome POEMS - Determinación de VEGF.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34715, 12122, '1. El tratamiento dependerá del resultado del estudio citogenético.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34716, 12122, '2. Tras la terapia inicial de inducción, la edad del paciente es adecuada para realizar posteriormente un trasplante autólogo de progenitores hematopoyéticos de sangre periférica como terapia de intensificación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34717, 12122, '3. El tratamiento más apropiado de inducción debe incluir un esquema de tres fármacos por ejemplo bortezomib junto con melfalán y prednisona.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34718, 12122, '4. El tratamiento de primera línea en este paciente ha de ser necesariamente lenalidomida oral debido a la edad y a la insuficiencia renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34719, 12123, '1. Son datos importantes para el pronóstico la citogenética y los niveles séricos de albúmina y beta2-microglobulina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34720, 12123, '2. El bortezomib, la talidomida, la lenalidomida y la poliquimioterapia son herramientas terapéuticas muy útiles.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34721, 12123, '3. El trasplante autogénico de progenitores hematopoyéticos proporciona una larga supervivencia libre de progresión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34722, 12123, '4. El trasplante alogénico se debe considerar un procedimiento experimental (de eficacia no probada).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34723, 12123, '5. La radioterapia no tiene ningún papel en el tratamiento de la enfermedad o sus complicaciones', true, 5);
