INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34749, 12129, '1. La mayoría de pacientes experimentan remisión completa con melfalan y prednisona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34750, 12129, '2. Se logran respuestas que alargan la supervivencia más allá de 15 años.', false, 2);
