INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34768, 12133, '1. La ligadura temprana de la arteria esplénica es crucial para reducir el riesgo de sangrado intraoperatorio y debe realizarse antes de movilizar el bazo en todos los casos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34769, 12133, '2. La preservación del polo inferior del bazo es recomendable en pacientes con PTI para mantener una función inmunológica parcial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34770, 12133, '3. El abordaje lateral izquierdo es la única opción en esplenectomías laparoscópicas y debe emplearse independientemente del tamaño del bazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34771, 12133, '4. La vacunación preoperatoria contra neumococo, meningococo y Haemophilus influenzae es esencial para reducir el riesgo de infección post- esplenectomía y debe completarse al menos dos semanas antes de la cirugía, siempre que sea posible.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34833, 12147, '2. La causa de muerte más frecuente, a menos de que se haga un tratamiento preventivo específico, es la hemorragia cerebral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34914, 12165, '3. Trombocitopenia neonatal aloinmunitaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34772, 12134, '12. 340 leucocitos (92 % PMN), plaquetas 14.600, urea 183 mg/dl, creatinina 2,3 mg/dl, bilirrubina total 2 mg/dl, transaminasas normales, LDH 2.125 UI, ferritina 1.582 ng/mL, haptoglobina < 30 mg/dl. Frotis de sangre periférica con anisocitosis y abundantes microesferocitos y esquistocitos (3-4 por campo) sin agregados plaquetarios. ¿Cuál de los siguentes tratamientos es MENOS apropiado?:', false, 1);
