INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34816, 12143, '5. Coagulación intravascular diseminada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34817, 12144, '1. La presencia de adenopatías o esplenomegalia en la exploración física sugiere un diagnóstico diferente de PTI.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34818, 12144, '2. El análisis de médula ósea muestra un número disminuido de megacariocitos, sin otras alteraciones.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34819, 12144, '3. El hemograma completo muestra trombocitopenia aislada con plaquetas a menudo grandes, sin anemia salvo que exista una hemorragia importante o hemólisis autoinmune asociada (síndrome de Evans).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34820, 12144, '4. El diagnóstico de PTI se establece por exclusión de otros procesos causantes de trombocitopenia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34821, 12144, '5. La determinación de anticuerpos antiplaquetarios no es precisa para establecer el diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34822, 12145, '1. Alergia al veneno de abeja.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34823, 12145, '2. Rechazo cardiaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34824, 12145, '3. Angioedema hereditario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34825, 12145, '4. Púrpura trombocitopénica idiopática.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34826, 12145, '5. Osteoartritis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34827, 12146, '1. Las lesiones son muy sugestivas de una púrpura de Shönlein-Henoch.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34828, 12146, '2. El diagnóstico diferencial deberá incluir las arañas vasculares propias de una cirrosis hepática alcohólica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34829, 12146, '3. El examen hematológico característicamente mostrará esquistocitos y plaquetopenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34830, 12146, '4. Lo más probable es que el paciente presente una anemia por pérdidas digestivas debidas a un pólipo degenerado en el colon.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34831, 12146, '5. Las lesiones mucosas son muy inespecíficas y difícilmente pueden relacionarse con la sintomatología que refiere el paciente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34832, 12147, '1. Se aconseja que todos los pacientes con esta sospecha diagnóstica se sometan a una prueba de imagen para descartar un aneurisma de aorta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34913, 12165, '2. Trombocitopenia neonatal autoinmunitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36160, 12438, '4. Cefazolina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34834, 12147, '3. El sustrato anatomopatológico es de vasculitis leucocitoclástica con necrosis fibrinoide en los pequeños vasos dérmicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34835, 12147, '4. Es relativamente frecuente que estos pacientes desarrollen una anemia ferropénica. En este caso, la causa más frecuente es la hemorragia digestiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34836, 12147, '5. A pesar de que en este caso había anemia, es posible que estos pacientes desarrollen poliglobulia hipoxémica por fístulas pulmonares.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34837, 12148, '1. 11.000 plaquetas/mm3, melenas, Hb 10 g/dL, VCM 85 fl, TA 85/60 mmHg, FC 115 lpm.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34838, 12148, '2. 7.000 plaquetas/mm3, púrpura en extremidades inferiores, Hb 13 g/dl, FC 90 lpm, TA 150/85 mmHg.', false, 2);
