INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34871, 12155, '2. Vitaminas an^oxidantes a dosis altas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34872, 12155, '3. Intentar la gestación mediante diagnós^co gené^co preimplantacional.', false, 3);
