INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34875, 12156, '2. Concentración elevada de an^trombina y pro- teína C.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34876, 12156, '3. Tiempo de protrombina y ^empo parcial de tromboplas^na ac^vada alargados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34877, 12156, '4. Presencia de productos de degradación de la fibrina (dímero D).', false, 4);
