INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34889, 12159, '4. Enfermedad de Von Willebrand.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34890, 12160, '1. Debe aconsejarse tratamiento profiláctico con heparina de bajo peso molecular durante el embarazo y hasta 6 sema- nas posparto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34891, 12160, '2. Debe aconsejarse tratamiento profiláctico con aspirina durante todo el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34892, 12160, '3. Debe aconsejarse realizar profilaxis con acenocumarol durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34893, 12160, '4. Dado que el estudio de trombofilia fue negativo solo se precisa realizar profilaxis de trombosis venosa con medias compresivas para miembros inferiores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34894, 12161, '1. Se trata de la resistencia del factor V a la acción de la proteína S.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34895, 12161, '2. Es un trastorno adquirido que se asocia a la presencia de anticuerpos anticardiolipina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34896, 12161, '3. Su presencia ocasiona una prolongación del tiempo de tromboplastina parcial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34897, 12161, '4. Junto con la mutación de la protrombina constituye la predisposición trombótica de base genética más frecuente en nuestro medio.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34898, 12162, '1. Deficiencia de Factor V.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34899, 12162, '2. Deficiencia de Factor VII.', true, 2);
