INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34918, 12166, '2. Enfermedad de Von Willebrand.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34919, 12166, '3. Enfermedad de Ehlers-Danlos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34920, 12166, '4. Hemofilia A.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34921, 12166, '5. Enfermedad de Bernard-Soulier.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34922, 12167, '1. Dado que la gestación es un estado protrombótico, existiría alto riesgo de tromboembolia venosa por lo que se debe desaconsejar el embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34923, 12167, '2. Se debe realizar tratamiento con heparina de bajo peso molecular a dosis profilácticas en el puerperio inmediato siendo opcional realizar igual tratamiento durante el embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34924, 12167, '3. El Factor V Leiden en heterocigosis es una trombofilia de bajo riesgo y no hay necesidad de ningún tratamiento en el embarazo y puerperio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34925, 12167, '4. Se debe aconsejar aspirina a bajas dosis durante todo el embarazo y puerperio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34926, 12167, '5. Debe realizar tratamiento con fármacos anti vitamina K (Acenocumarol) durante el embarazo.', false, 5);
