INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34942, 12171, '1. Suele manifestarse a edades más precoces.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34943, 12171, '2. Suele ser causa de enfermedad tromboembólica recidivante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34944, 12171, '3. Debe sospecharse en caso de antecedentes familiares positivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34945, 12171, '4. Es indicación de heparina no fraccionada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34946, 12171, '5. Puede requerir tratamientos más prolongados.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34947, 12172, '1. Existen algunos ensayos clínicos que avalan su uso en pacientes en hemodiálisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34948, 12172, '2. Tienen menos riesgo de hemorragia intracraneal que los antagonistas de la vitamina K.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34949, 12172, '3. Pueden administrarse en pacientes con valvulopatías y portadores de todo tipo de prótesis cardíacas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34950, 12172, '4. Son igual o más eficaces que los antagonistas de la vitamina K para prevenir ictus isquémicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34951, 12173, '1. Púrpura trombó^ca trombocitopénica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34952, 12173, '2. Coagulación intravascular diseminada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34953, 12173, '3. Trombopenia inducida por heparina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34954, 12173, '4. Síndrome hemolí^co urémico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34955, 12174, '1. Suspender el tratamiento con acenocumarol y administrar 10 mg de vitamina K en infusión intravenosa lenta, que se repe^rá cada 12 horas si fuera necesario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34956, 12174, '2. Suspender el acenocumarol y remi^r al paciente a un centro hospitalario para vigilar la aparición de sangrado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34957, 12174, '3. Suspender temporalmente el acenocumarol y reanudar la an^coagulación cuando se haya alcanzado el intervalo terapéu^co, calculando de nuevo la dosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34958, 12174, '4. Iniciar la administración de concentrado de complejo de protrombina o plasma fresco congelado según el peso.', false, 4);
