INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34987, 12182, '1. Realizar la cirugía ocular sin suspender el acenocumarol.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34988, 12182, '2. Suspender el acenocumarol 5 días antes de la cirugía y reiniciarlo el día posterior a la misma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35121, 12211, '4. Hiperviscosidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35122, 12211, '5. Adenopatías y esplenomegalia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34989, 12182, '3. Suspender el acenocumarol 5 días antes de la cirugía, iniciar heparina de bajo peso molecular 3 días antes de la cirugía y suspenderla 24 horas antes de la misma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34990, 12182, '4. Suspender el acenocumarol 1 día antes de la intervención y utilizar plasma fresco congelado durante la misma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34991, 12182, '5. Suspender el acenocumarol 1 día antes de la intervención y dar vitamina K justo antes de la misma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34992, 12183, '1. Dabigatran.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34993, 12183, '2. Apixaban.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (34994, 12183, '3. Ribaroxaban.', false, 3);
