INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35000, 12184, '4. Rivaroxabán - inhibe el factor Xa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35001, 12184, '5. Warfarina - inhibe la absorción de la vitamina K.', true, 5);
