INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35003, 12185, '2. Anemia hemolítica autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35004, 12185, '3. Trombosis venas suprahepáticas.', false, 3);
