INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35008, 12186, '2. Gentamicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35009, 12186, '3. Digoxina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35010, 12186, '4. Fenitoína.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35011, 12186, '5. Litio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35012, 12187, '1. Heparina de bajo peso molecular solapada con dicumarínicos al menos los 5 primeros días, hasta obtener INR entre 2 y 3. Después, dicumarínicos solos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35013, 12187, '2. Sólo heparina de bajo peso molecular mientras dure el embarazo, pasando a dicumarínicos tras el parto si es preciso prolongar el tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35014, 12187, '3. Sólo dicumarínicos desde el principio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35015, 12187, '4. Fibrinolisis con activador tisular del plasminógeno (tPA).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35016, 12187, '5. Los anticoagulantes están contraindicados en el embarazo. Sólo medias de compresión fuerte.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35017, 12188, '1. Los cumarínicos tienen pocas interacciones farmacológicas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35018, 12188, '2. El tratamiento de la trombocitopenia inducida por heparina consiste en la disminución de la dosis de heparina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35019, 12188, '3. Los cumarínicos son seguros durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35020, 12188, '4. El test más utilizado para el control de la heparina no fraccionada es el TTPA (tiempo de tromboplastina parcial activada).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35021, 12188, '5. El fondaparinux es un nuevo anticoagulante de administración oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35022, 12189, '1. En pacientes con TVP confirmada objetiva- mente, recomendamos tratamiento agudo con heparina de bajo peso subcutánea o heparina no fraccionada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35023, 12189, '2. 2. Para pacientes con elevada sospecha clínica de trombosis, se recomienda tratamiento anticoagulante mientras se espera el resultado de las pruebas diagnósticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35024, 12189, '3. 3. El tratamiento con heparina se dice debe controlarse realizando TPT (tiempo parcial de tromboplastina).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35025, 12189, '4. 4. Se recomienda iniciar la administración de anticoagulantes orales junto con heparina en el primer día del tratamiento, e interrumpir la administración de heparina cuando el INR sea estable y superior a 2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35026, 12189, '5. 5. En los pacientes tratados con heparina de bajo peso es necesario hacer mediciones sistemáticas de la actividad antiXa con el fin de ajustar la dosis.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35027, 12190, '1. Se considera una complicación tardía que suele presentarse a las 2-3 semanas de recibir el tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35028, 12190, '2. Se produce por un incremento suprafisiológico de algunas citosinas tales como la interleucina 6 (IL-6) e interleucina 1 (IL-1).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35029, 12190, '3. Las manifestaciones clínicas características incluyen fiebre e hipertensión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35030, 12190, '4. El tozilizumab se utiliza de forma excepcional para su tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35031, 12191, '1. El donante ^ene un síndrome de Klinefelter no diagnos^cado.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35032, 12191, '2. En la médula ósea coexisten células del donante y del receptor (quimerismo mixto).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35033, 12191, '3. Tras el trasplante ha exis^do un fenómeno de fusión celular entre las células del donante y receptor que ha originado el nuevo cario^po.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35034, 12191, '4. En el cario^po realizado precozmente tras un trasplante hematopoyé^co es habitual encontrar alteraciones cromosómicas transitorias de este ^po que carecen de significación clínica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35035, 12192, '1. Neumonía por Mycobacterium tuberculosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35036, 12192, '2. Neumonía por Aspergillus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35037, 12192, '3. Neumonía por Streptococcus pneumoniae.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35038, 12192, '4. Neumonía por PneumocysLs jirovecii.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35039, 12193, '1. A posi^vo. El grupo sanguíneo permanece inalterable durante toda la vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35040, 12193, '2. AB posi^vo. Existe una mezcla de ambos grupos en los hema‘es.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35041, 12193, '3. B posi^vo. Ha cambiado de grupo adquiriendo el del donante.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35042, 12193, '4. O posi^vo. Los an^cuerpos an^-transferasa del receptor inhiben la expresión de los grupos sanguíneos, siendo todos los pacientes trasplantados del grupo O.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35043, 12194, '1. Iniciar tratamiento con esteroides a dosis altas ante posibilidad de enfermedad aguda injerto contra huésped hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35044, 12194, '2. Ampliar cobertura antibiótica ante posibilidad de complicación infecciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35045, 12194, '3. Considerar síndrome de obstrucción sinusoidal y valorar iniciar tratamiento con defibrotide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35046, 12194, '4. Tratamiento sintomático y ver evolución', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35047, 12195, '1. Suspender lo antes posible el tratamiento inmunosupresor con tacrolimus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35048, 12195, '2. Iniciar tratamiento con esteroides a dosis altas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35049, 12195, '3. Iniciar infusión de linfocitos del donante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35050, 12195, '4. Iniciar tratamiento con fotoaféresis extracorpórea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35051, 12196, '1. En pacientes que carecen de un donante familiar o no emparentado HLA-idéntico se puede emplear la sangre de cordón umbilical como fuente alternativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35052, 12196, '2. En pacientes que carecen de un donante familiar o no emparentado HLA-idéntico se pueden emplear células progenitoras de un donante haploidéntico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35053, 12196, '3. En el trasplante autólogo las células se encuentran criopreservadas y han de descongelarse previo a su admi- nistración.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35054, 12196, '4. El efecto injerto contra leucemia es mayor en el trasplante autólogo que en el alogénico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35055, 12197, '1. El proceso fisiopatológico de la EICH tiene su origen en las células T del donante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35056, 12197, '2. La profilaxis de la EICH consiste en tratamiento inmunosupresor, frecuentemente ciclosporina asociada a metotrexate, y el tratamiento de la EICH establecida consiste en corticoterapia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35057, 12197, '3. La eliminación de los linfocitos del donante del injerto mejora el implante de los progenitores.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35058, 12197, '4. En la mayoría de los pacientes diagnosticados EICH crónica, ésta llega a desaparecer pudiendo interrumpir el tratamiento inmunosupresor sin que la enfermedad recidive.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35059, 12198, '1. Trasplante hepático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35060, 12198, '2. Trasplante autólogo de progenitores hematopoyéticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35061, 12198, '3. Trasplante singénico de progenitores hematopoyéticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35062, 12198, '4. Trasplante renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35063, 12198, '5. Trasplante alogénico de progenitores hematopoyéticos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35064, 12199, '1. Reduce la incidencia y severidad de la enfermedad del injerto contra el huésped.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35065, 12199, '2. Reduce el riesgo de recaída de la neoplasia de base.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35066, 12199, '3. Disminuye el riesgo de fallo primario del injerto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35067, 12199, '4. Mejora la probabilidad de supervivencia global del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35068, 12199, '5. Acelera la reconstitución inmune postrasplante.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35069, 12200, '1. Las reacciones hemolíticas tardías, ya que las pruebas de detección de anticuerpos previas a la transfusión son positivas y por tanto se transfundirá sangre carente del antígeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35070, 12200, '2. La hipocalcemia puede ser prevenida mediante la retirada del citrato que llevan los concentrados de hematíes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35071, 12200, '3. El lavado de los concentrados de hematíes previene la sobrecarga férrica en los pacientes politransfundidos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35072, 12200, '4. La irradiación de los componentes celulares (concentrados de hematíes y plaquetas) con 2500 cGy evita la aparición de la enfermedad injerto contra huésped asociada a la transfusion.', true, 4);
