INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35074, 12201, '2. Reacción febril secundaria a la transfusión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35075, 12201, '3. Reacción febril por el plasma que contamina', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35076, 12201, '4. los hematíes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35077, 12201, '5. Reacción transfusional hemolítica.', false, 5);
