INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35091, 12204, '5. Reacción transfusional hemolítica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35092, 12205, '1. Reacción hemolítica severa por la interacción de los anticuerpos anti-A del paciente y los hematíes A de la sangre transfundida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35093, 12205, '2. Reacción hemolítica severa por la disparidad de grupos Rh.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35094, 12205, '3. Sensibilización del receptor y posible hemólisis en futuras transfusiones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35095, 12205, '4. No se produce hemólisis si se administra gammaglobulina anti-D tras la transfusión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35096, 12205, '5. No se produce hemólisis si se premedica en corticoides.', false, 5);
