INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35102, 12207, '2. Síndrome de lisis tumoral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35103, 12207, '3. Hipocalcemia por citostá^cos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35104, 12207, '4. Alteración metabólica secundaria a la hiperémesis postquimioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35105, 12208, '1. El elemento de reconocimiento del receptor CAR está basado en fragmentos variables de an^cuerpos an^-CD19 (single-chain variable fragments, scFvs).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35106, 12208, '2. El receptor CAR posee un dominio intracelular responsable de la transmisión de señales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35107, 12208, '3. Entre los efectos secundarios graves de este tratamiento se encuentra el síndrome de liberación de citocinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35108, 12208, '4. El reconocimiento del an‘geno por el receptor CAR depende de las moléculas de histocompa^bilidad (HLA) clase I en la célula tumoral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35109, 12209, '1. Hipercalcemia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35110, 12209, '2. Hiperuricemia.', false, 2);
