INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35132, 12213, '5. Receptor PAR-1.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35133, 12214, '1. El control del foco solo se intentará una vez el paciente haya alcanzado la estabilidad hemodinámica y no dependa de vasopresores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35134, 12214, '2. El control del foco se realizará tras al menos la administración de dos dosis de antibiótico.', false, 2);
