INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35147, 12217, '3. Vancomicina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35148, 12217, '4. Linezolid.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35149, 12218, '1. Entre las medidas a tomar cuando se sospecha una sepsis, se encuentra la administración de antibioterapia en la 1ª hora de su llegada, aunque no se ha conseguido relacionar esta actitud con una disminución de la mortalidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35150, 12218, '2. La administración precoz de fluidos iv es esencial para mantener adecuada perfusión tisular, siendo la meta a conseguir mantener una presión arterial media > 65 mmHg.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35151, 12218, '3. Entre las pruebas complementarias que se reciben observamos un lactato > 5,6 mmol/L, hay que tenerlo en cuenta pero mientras mantenga estabilidad hemodinámica no debemos preocuparnos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35152, 12218, '4. En realidad no es correcto el diagnóstico de sepsis ya que la ausencia de fiebre la descarta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35153, 12218, '5. La paciente presenta hipotensión a pesar de administración intensiva de fluidoterapia endovenosa, es el momento de administrar drogas vasoactivas, siendo de elección el isoproterenol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35154, 12219, '1. Staphylococcus aureus.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35155, 12219, '2. Streptococcus pneumoniae.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35156, 12219, '3. Meningococo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35157, 12219, '4. Streptococcus viridans.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35158, 12219, '5. Streptococcus pyogenes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35159, 12220, '1. Hipotensión.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35160, 12220, '2. Oliguria (diuresis <0.5 ml/kg).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35161, 12220, '3. Niveles plasmáticos elevados de proteína C reactiva o procalcitonina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35162, 12220, '4. Hipoxemia con Pa 02/Fi 02 < 250.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35163, 12220, '5. Hiperlactoacidemia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35164, 12221, '1. Alrededor del 50% de los pacientes con sepsis grave o shock séptico desarrollan un síndrome de distress respiratorio del adulto (SDRA).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35165, 12221, '2. Por definición la sepsis se acompaña de bacteriemia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35166, 12221, '3. La hiperventilación es un signo precoz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35167, 12221, '4. La lesión del endotelio vascular es el mecanismo principal de la disfunción de órganos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35168, 12221, '5. El patrón hemodinámico del shock séptico incluye un gasto cardiaco normal o elevado y una disminución de las resistencias vasculares periféricas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35169, 12222, '1. Administrar precozmente corticoides y proteína C activada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35170, 12222, '2. Administrar precozmente bicarbonato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35171, 12222, '3. Ingreso en UCI para ventilación mecánica asistida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35172, 12222, '4. Administración de antibióticos y estabilización hemodinámica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35173, 12222, '5. Administración de tratamiento inotrópico con dobutamina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35174, 12223, '1. Enviar al hospital para vacunar de rabia y tétanos y mantener en observación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35175, 12223, '2. Limpiar la herida y administrar gammaglobulina inespecífica intramuscular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35176, 12223, '3. Dar 400 mg de moxifloxacino oral y enviar al hospital.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35177, 12223, '4. Dar clindamicina 600 mg oral cada 8 horas y observación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35178, 12224, '1. Fascitis necrotizante estreptocócica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35179, 12224, '2. Gangrena por Clostridium spp.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35180, 12224, '3. Celulitis por micobacterias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35181, 12224, '4. Erisipela.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35182, 12225, '1. Ciprofloxacino, pensando en que la flora oral está compuesta por flora mixta con predominio de flora anaerobia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35183, 12225, '2. Aztreonam, pensando en que la flora oral está compuesta por flora mixta con predominio de enterobacterias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35184, 12225, '3. Amoxicilina-clavulánico, pensando en que la flora oral está compuesta por flora mixta con predominio de flora gram positiva y anaerobia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35185, 12225, '4. Fluconazol, pensando en que la flora oral está compuesta por flora mixta con predominio de las levaduras como Candida albicans.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35186, 12225, '5. Metronidazol, pensando en que la flora oral está compuesta por flora mixta con predominio de flora anaerobia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35187, 12226, '1. Penicilina V o amoxicilina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35188, 12226, '2. Amoxicilina/Clavulánico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35189, 12226, '3. Doxiclina.', false, 3);
