INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35202, 12229, '"1. En la exploración clínica de la tos ferina es habitual la presencia de sibilancias en la auscultación pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35203, 12229, '2. La azitromicina es el antibiótico de elección para el tratamiento en todos los grupos de edad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35204, 12229, '3. El ""gallo"" (esfuerzo inspiratorio masivo) se produce fundamentalmente en los niños menores de 2 meses de edad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35205, 12229, '4. Los vómitos posteriores al episodio paroxístico de tos son extremadamente raros."', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35206, 12230, '1. Coxiella burnetii.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35207, 12230, '2. Rickettsia conorii.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35208, 12230, '3. Borrelia burgdorferi.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35209, 12230, '4. Yersinia pestis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35210, 12231, '1. La infección aguda es causa de neumonía y hepatitis aguda.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35211, 12231, '2. La endocarditis es frecuente en los niños aunque rara en adultos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35212, 12231, '3. El antecedente de mordedura por un animal doméstico debe hacer pensar en su etiología.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35213, 12231, '4. Los antibióticos beta-lactámicos son de elección en el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35214, 12232, '1. La forma de trasmisión de esta entidad es por garrapatas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35215, 12232, '2. Tanto la doxiciclina como la hidroxicloroquina son eficaces para tratar las formas agudas de esta enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35216, 12232, '3. En su forma aguda también presenta, generalmente, elevación de anticuerpos frente a antígenos en fase I.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35217, 12232, '4. La mortalidad en las formas agudas es casi inexistente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35218, 12233, '1. Ixodes ricinus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35219, 12233, '2. Rhipicephalus sanguineus.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35220, 12233, '3. Aedes aegypti.', false, 3);
