INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35224, 12234, '2. Doxiciclina 100 mg/12h oral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35225, 12234, '3. Paracetamol 500 mg/6h oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35226, 12234, '4. Cloranfenicol 500 mg/6h oral.', false, 4);
