INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35234, 12236, '2. Fiebre recurrente por Borrelia hispanica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35235, 12236, '3. Fiebre botonosa mediterránea.', false, 3);
