INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35239, 12237, '2. Borrelia burgdorferi.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35240, 12237, '3. Bartonella henselae.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35241, 12237, '4. Rickettsia conorii.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35242, 12237, '5. Coxiella burnetii.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35243, 12238, '1. Penicilina G sódica IV.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35244, 12238, '2. Doxiciclina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35245, 12238, '3. Cotrimoxazol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35246, 12238, '4. Gentamicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35247, 12238, '5. Ceftriaxona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35248, 12239, '1. Accidente cerebrovascular isquémico secundario a fibrilación auricular, iniciar anticoagulación y antipiréticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35249, 12239, '2. Meningitis bacteriana con complicación isquémica, realizar punción lumbar e iniciar antibiótico dirigido según antibiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35250, 12239, '3. Endocarditis infecciosa con embolia séptica, confirmar con ecocardiograma y tratar con antibiótico dirigido según el antibiograma.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35251, 12239, '4. Neoplasia cerebral con fiebre paraneoplásica, realizar resonancia magnética cerebral y evaluación oncológica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35252, 12240, '1. Añadir al tratamiento voriconazol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35253, 12240, '2. Sustituir la vancomicina por daptomicina y administrar furosemida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35254, 12240, '3. Añadir gentamicina, rifampicina, furosemida y nitritos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35255, 12240, '4. Indicar cirugía de recambio valvular urgente y tratamiento deplectivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35256, 12241, '1. Una esofagogastroduodenoscopia con toma de biopsia gástrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35257, 12241, '2. Un drenaje guiado por ecografía de absceso hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35258, 12241, '3. Una colonoscopia por sospecha de neoplasia de colon.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35259, 12241, '4. Un ecocardiograma para descartar endocarditis bacteriana.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35260, 12242, '1. Se trata de un microorganismo productor de betalactamasa por lo que se puede iniciar trata miento con cualquier antibiótico betalactámico menos penicilina/amoxicilina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35261, 12242, '2. A la hora de decidir el tratamiento habría que asumir la resistencia a todos los antibióticos betalactámicos y carbapenémicos con excepción de ceftarolina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35262, 12242, '3. El tratamiento con amoxicilina-ácido clavulánico intravenoso es la opción de trata miento más recomendable.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35263, 12242, '4. En este caso se puede iniciar trata miento con un antibiótico de amplio espectro como el meropenem.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35264, 12243, '1. Disección aórtica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35265, 12243, '2. Estenosis aórtica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35266, 12243, '3. Endocarditis aórtica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35267, 12243, '4. Mixoma valvular aórtico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35268, 12244, '1. Continuar con cefuroxima a la espera del resultado definitivo, pues el paciente ha llevado múltiples tratamientos y no deberíamos equivocarnos en su tratamiento actual.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35269, 12244, '2. Cambiar a ertapenem, pensando en la posibilidad de microorganismos multirresistentes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35270, 12244, '3. Cambiar a un tratamiento antimicrobiano de amplio espectro que cubra Enterococcus spp.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36161, 12438, '5. Sulfametoxazol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35271, 12244, '4. Cambiar a un tratamiento antimicrobiano de amplio espectro que contenga imipenem, pensando en la posibilidad de Staphylococcus aureus, ya que nuestro hospital tiene una elevada incidencia de S. aureus resistente a meticilina (SARM)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35272, 12245, '1. Imipenem.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35273, 12245, '2. Cefazolina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35274, 12245, '3. Vancomicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35275, 12245, '4. Daptomicina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35276, 12246, '1. Cirugía cardiaca de reemplazo valvular aórtico por prótesis mecánica con terapia antibiótica según antibiograma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35277, 12246, '2. Terapia antibiótica según antibiograma e implantación de balón de contrapulsación intra-aórtico y marcapasos transitorio hasta 3 semanas, tras las cuales se implantará marcapasos definitivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35278, 12246, '3. Implantación de marcapasos transitorio, terapia antibiótica según antibiograma e implantación percutánea de prótesis valvular aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35279, 12246, '4. Implantación urgente de marcapasos definitivo con terapia antibiótica según antibiograma durante 6 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35280, 12247, '1. Continuar con el mismo tratamiento hasta completar el tiempo recomendado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35281, 12247, '2. Continuar con el mismo tratamiento y realizar valoración de cirugía cardiovascular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35282, 12247, '3. Cambiar el tratamiento antimicrobiano a vancomicina y rifampicina, y realizar valoración de cirugía cardiovascular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35283, 12247, '4. Cambiar el tratamiento antimicrobiano a vancomicina y rifampicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35284, 12247, '5. Cambiar el tratamiento antimicrobiano a ceftriaxona.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35285, 12248, '1. Aspergilosis pulmonar angioinvasora.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35286, 12248, '2. Tuberculosis pulmonar bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35287, 12248, '3. Embolismo séptico pulmonar por Stafiloccocus aureus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35288, 12248, '4. Infección pulmonar por Nocardia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35289, 12248, '5. Neumonía bilateral por Pseudomonas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35290, 12249, '1. Alteración profunda de la inmunidad humoral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35291, 12249, '2. Endocarditis tricuspídea.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35292, 12249, '3. Hepatitis por virus C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35293, 12249, '4. Síndrome de inmunodeficiencia adquirida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35294, 12249, '5. Leucopenia grave.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35295, 12250, '1. Prueba de tolerancia a la glucosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35296, 12250, '2. Radiografía de tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35297, 12250, '3. Endoscopia digestiva alta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35298, 12250, '4. Colonoscopia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35299, 12250, '5. Ecografía abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35300, 12251, '1. Estreptomicina', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35301, 12251, '2. Cefuroxima', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35302, 12251, '3. Colistina', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35303, 12251, '4. Quinupristina-dalfopristina', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35304, 12251, '5. Ampicilina', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35305, 12252, '1. Derrame pericárdico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35306, 12252, '2. Prolapso de un festón de la válvula mitral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35307, 12252, '3. Insuficiencia mitral moderada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35308, 12252, '4. Absceso periaórtico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35309, 12252, '5. Insuficiencia aórtica severa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35310, 12253, '1. TAC torácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35311, 12253, '2. Resonancia magnética pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35312, 12253, '3. Espirometría.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35313, 12253, '4. Ecocardiografía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35314, 12253, '5. Gammagrafía pulmonar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35315, 12254, '1. Tratar con antibióticos a toda la familia, independientemente de la edad, estado de inmunización y sintomatología.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35316, 12254, '2. Tratar con antibióticos a todo el personal sanitario que ha atendido al niño independientemente de la edad, estado de inmunización y sintomatología.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35317, 12254, '3. Vacunar a los adultos convivientes, aunque hayan padecido la enfermedad ya que la inmunidad no dura toda la vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35318, 12254, '4. Aislar al paciente al menos 5 días después de iniciar el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35319, 12255, '1. Precauciones de transmisión por gotas.', false, 1);
