INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35323, 12256, '1. La puntuación de la escala de riesgo CURB-65 es 1. Es una persona joven, los gérmenes más probables son el neumococo y el mycoplasma. Puede tratarse ambulatoriamente con azitromicina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35324, 12256, '2. La puntuación de la escala de riesgo CURB-65 es 2. Debe ingresar en el hospital en una sala convencional y podría tratarse con una cefalosporina de tercera generación y azitromicina, puesto que hay que cubrir el neumococo resistente y la legionella.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35325, 12256, '3. La puntuación de la escala de riesgo CURB-65 es 3. Debe ingresar en el hospital en una sala convencional. Se tomarán muestras para cultivo con un catéter telescopado y un lavado broncoalveolar y se esperarán los resultados de los cultivos antes de iniciar cualquier tratamiento antibiótico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35326, 12256, '4. La puntuación de la escala de riesgo CURB-65 de 4. Debe cubrirse como germen más probable la Pseudomonas aeruginosa y tratarlo con cefalosporinas antipseudomona en una unidad de cuidados intensivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35327, 12257, '1. Es preciso analizar muestras de esputo inducido para descartar tuberculosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35328, 12257, '2. Se debe iniciar un tratamiento empírico con metronidazol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35329, 12257, '3. Si en el esputo no se aísla un patógeno específico se presupone la presencia de gérmenes anaerobios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35330, 12257, '4. Si sospecha compromiso inmunitario debe realizar de forma inmediata broncoscopia con biopsia o aspiración con aguja guiada por TC.', false, 4);
