INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35535, 12302, '1. La vacuna antigripal trivalente administrada a la población española en los últimos anos ha incluido sistemáticamente una cepa A, una cepa B y una cepa C del virus de la gripe humana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35536, 12302, '2. Una de las cepas de la vacuna antigripal estacional administrada a la población española en los últimos anos ha sido A (H1N1).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35537, 12302, '3. El virus A (H1N1) de la actual pandemia está formado por la recombinación de genes de la gripe A humana y porcina y no incluye genes de la gripe A aviar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35538, 12302, '4. Los virus de la gripe son virus con ADN monocatenario y diversas proteínas, de las cuales la hemaglutinina y la neuraminidasa no son estructurales y permiten su clasificación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35539, 12302, '5. La pandemia de gripe A (H1N1) de 1918 se llamó “gripe española” porque se inició en España y afecto a la población española de manera particularmente intensa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35540, 12303, '1. Encefalitis japonesa.', false, 1);
