INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35548, 12304, '4. En casi todos los casos se replica y disemina originando una sintomatología clínica muy característica (fiebre, hepato-esplenomegalia, linfadenopatías y trombocitopenia).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35549, 12304, '5. El riesgo de anomalías congénitas graves es muy bajo en los niños nacidos de madres que padecieron infección primaria durante el embarazo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35550, 12305, '1. Impedir mediante la inmunidad que generan que aparezca una pandemia.', false, 1);
