INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35571, 12309, '4. El hecho de presentar una prueba de Mantoux negativa descarta la tuberculosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35572, 12310, '1. Si no es posible asegurar una adecuada adherencia al tratamiento, lo mejor es que no lo reinicie por el riesgo de desarrollo de resistencias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35573, 12310, '2. Estaría indicado en este momento un estudio de resistencias para conocer las mutaciones presentes y guiar el reinicio del tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35574, 12310, '3. La biterapia con dolutegravir y lamivudina podría ser igual de eficaz en esta situación que la triple terapia, ya que podría reducir parte de los efectos adversos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35575, 12310, '4. La mejor opción en este paciente podría ser una combinación basada en inhibidores de proteasa potenciados.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35576, 12311, '1. Determinar niveles plasmáticos de los fármacos para asegurar que estos se encuentran dentro de los márgenes terapéuticos', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35577, 12311, '2. Repetir la carga viral en unas semanas para confirmar si se trata de un blip.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35578, 12311, '3. Hacer un estudio de resistencias genotípico, para verificar la existencia de mutaciones de resistencia a los fármacos usados', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35579, 12311, '4. Intensificar el tratamiento ante la eventualidad de un fracaso en un paciente con una infección VIH avanzada.', false, 4);
