INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35610, 12319, '1. Una serología VIH-1/VIH-2 negativa realizada por medio de la técnica de ELISA, descarta la posibilidad de que la paciente haya sido contagiada con el virus VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35611, 12319, '2. El proceso clínico que padece la paciente no concuerda con el de la infección aguda por VIH.', false, 2);
