INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35613, 12319, '4. La técnica de ELISA tiene una alta sensibilidad para el diagnóstico de infección por VIH, pero su especificidad es aún mayor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35614, 12319, '5. Si el test de ELISA para diagnosticar VIH en la paciente fuera negativo, podríamos determinar por la técnica de PCR la carga viral en sangre.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35615, 12320, '1. La cesárea programada no reduce la tasa de transmisión vertical del virus.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35616, 12320, '2. Se ofrecerá a la gestante la posibilidad de realizar tratamiento antirretroviral sea cual sea su estadio de la enfermedad, con la finalidad de prevenir la transmisión vertical del virus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35617, 12320, '3. La transmisión vertical del virus se asocia a la carga viral materna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35618, 12320, '4. Se tiene que ofrecer a toda gestante la serología VIH en la primera consulla, sea cual sea el momento del embarazo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35698, 12336, '4. El tratamiento de elección es el cotrimoxazol.', false, 4);
