INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35655, 12328, '1. El objetivo del tratamiento en la supresión máxima de la replicación viral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35656, 12328, '2. Las mujeres deben recibir tratamiento óptimo sin importar su estado de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35657, 12328, '3. Una vez que se alcanza la supresión virológica se puede suspender el tratamiento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35658, 12328, '4. El tratamiento antirretroviral se usa en profilaxis postexposición.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35659, 12328, '5. El tratamiento consiste en combinar tres fármacos activos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35660, 12329, '1. Tratamiento de infección tuberculosa latente, profilaxis primaria de Pneumocystis jiroveci y tratamiento antirretroviral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35661, 12329, '2. Tratamiento de infección tuberculosa latente y profilaxis primaria de P. jiroveci. No tiene criterios de inicio de tratamiento antirretroviral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35662, 12329, '3. Tratamiento de infección tuberculosa latente y tratamiento antirretroviral. No tiene criterios de inicio de profilaxis de P. jiroveci', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35663, 12329, '4. Tratamiento de infección tuberculosa latente. No tiene criterios de inicio de profilaxis de P. jiroveci ni de tratamiento antirretroviral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35664, 12329, '5. Seguimiento sin ninguna intervención específica en este momento.', false, 5);
