INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35674, 12331, '5. Cáncer digestivo en persona joven.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35675, 12332, '1. En África se ha mostrado eficaz en la prevención de la transmisión de la mujer al hombre.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35676, 12332, '2. Reduce la transmisión tras relaciones homosexuales entre hombres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35677, 12332, '3. Incrementa la transmisión del VIH del hombre a la mujer.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35678, 12332, '4. El balance coste-beneficio es desfavorable en países subdesarrollados.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35679, 12332, '5. Se recomienda generalizar el procedimiento para reducir las tasas de transmisión en todo el mundo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35680, 12333, '1. Asociada al HLA-B27-', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35681, 12333, '2. Descrita en pacientes VIH.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35682, 12333, '3. Muy frecuente en pacientes con lupus eritematoso sistémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35683, 12333, '4. Que ocurre en algunos pacientes con sífilis ocular tras la administración de penicilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35684, 12333, '5. Que ocurre en algunos pacientes con sarcoidosis tras abandonar el tratamiento con corticoides.', false, 5);
