INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35776, 12354, '1. Se recomienda el análisis del líquido cefalorraquídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35777, 12354, '2. La azitromicina oral es un tratamiento alternativo eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35778, 12354, '3. Se recomienda una valoración clínica y serológica (RPR) a los 6 y 12 meses después del tratamiento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35779, 12354, '4. Si los títulos de RPR permanecen positivos después de 12 meses está indicado administrar el tratamiento de nuevo.', false, 4);
