INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35796, 12359, '1. Una serología de lúes puesto que lo más probable es que se trate de una infección por Treponema pallidum.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35797, 12359, '2. Una exploración ginecológica a fin de descartar un cáncer de ovario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35798, 12359, '3. Por las características clínicas parece tratarse de unos ganglios normales y no deben hacerse exploraciones complementarias.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35799, 12359, '4. Debe realizarse una prueba de Paul-Bunell a fin de descartar una mononucleosis infecciosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35800, 12360, '1. En esta situación está indicado realizar citodiagnóstico de Tzanck y tratamiento con aciclovir 800 mg/12 horas durante 5 días de la paciente y de las parejas sexuales identificadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35801, 12360, '2. En esta situación está indicado realizar una serología (VDRL, FTA-ABS) y tratar con una monodosis intramuscular de 2,4 millones de UI de penicilina G benzatina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35802, 12360, '3. Sospechar una fiebre botonosa mediterránea y prescribir tratamiento con doxiciclina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35803, 12360, '4. Habrá que sospechar un lupus eritematoso sistémico con afectación cutánea e iniciar tratamiento con hidroxicloroquina.', false, 4);
