INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35819, 12364, '1. No hay ningún tratamiento efectivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35820, 12364, '2. La Penicilina es el tratamiento de elección en cualquier estadio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35821, 12364, '3. La Penicilina es el tratamiento de elección sólo en la Neurosífilis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35822, 12364, '4. La Penicilina es el tratamiento de elección sólo en la Sífilis no complicada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35823, 12364, '5. El tratamiento de elección son las Tetraciclinas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35824, 12365, '1. Retirar toda la medicación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35825, 12365, '2. Continuar con el mismo tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35826, 12365, '3. Retirar la isoniacida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35827, 12365, '4. Retirar la pirazinamida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35828, 12366, '1. Es un verdadero negativo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35829, 12366, '2. Es un falso negativo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35830, 12366, '3. Es un verdadero positivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35831, 12366, '4. Es un falso positivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35832, 12367, '1. El tratamiento de la enfermedad tuberculosa incluye varios fármacos con el fin de prevenir el desarrollo de cepas resistentes y el fracaso terapéutico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35833, 12367, '2. El tratamiento de la infección tuberculosa latente incluirá isoniacida durante 6 a 9 meses o rifampicina durante 4 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35834, 12367, '3. Bedaquilina es un fármaco nuevo, indicado en la tuberculosis multisensible.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35835, 12367, '4. Cicloserina, estreptomicina, PAS y levofloxacino son fármacos indicados en la tuberculosis multirresistente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35836, 12368, '1. Sarcoidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35837, 12368, '2. Toxoplasmosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35838, 12368, '3. Tuberculosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35839, 12368, '4. Linfoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35840, 12369, '1. Mycobacterium bovis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35841, 12369, '2. Mycobacterium kansasii.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35842, 12369, '3. Mycobacterium africanum.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35843, 12369, '4. Bacilo de Calmette-Guerin (BCG).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35844, 12370, '1. Isoniazida + rifampicina + pirazinamida (6 meses).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35845, 12370, '2. Isoniazida + rifampicina + pirazinamida + etambutol (2 meses) seguido de isoniazida + rifampicina (4 meses).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35846, 12370, '3. Isoniazida + rifabutina + etambutol (9 me- ses).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35847, 12370, '4. Isoniazida + rifampicina + pirazinamida (2 meses) seguido de isoniazida + rifampicina (4 meses).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35848, 12371, '1. Evita los falsos positivos de la vacunación previa con BCG.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35849, 12371, '2. Tiene mayor capacidad para predecir las tuberculosis de reactivación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35850, 12371, '3. Tiene mayor capacidad de predecir la eficacia de la profilaxis con isoniazida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35851, 12371, '4. Evita los falsos negativos por anergia en pacientes muy inmunosuprimidos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35852, 12372, '1. Linfadenitis dermatopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35853, 12372, '2. Linfadenitis tuberculosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35854, 12372, '3. Sarcoidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35855, 12372, '4. Linfadenitis sifilitica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35856, 12373, '1. Patrón en panal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35857, 12373, '2. Patrón destructivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35858, 12373, '3. Patrón miliar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35859, 12373, '4. Patrón microquístico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35861, 12374, '2. Medición del pH del líquido pleural.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35862, 12374, '3. Medición de la adenosina desaminasa del líquido pleural.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35863, 12374, '4. Prueba de la tuberculina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35864, 12375, '1. Afectación del sistema nervioso central.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35865, 12375, '2. Alta prevalencia de resistencia primaria a isoniacida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35866, 12375, '3. Tuberculosis pulmonar cavitada y extensa con gran carga bacilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35867, 12375, '4. Tuberculosis diseminad asociada a la infección por VIH.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35868, 12375, '5. Tuberculosis extrapulmonar en inmunodeprimidos de cualquier origen.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35869, 12376, '1. Mycobacterium bovis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35870, 12376, '2. Mycobacterium africanum.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35871, 12376, '3. Bacilo de Calmette-Guerin (BCG).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35872, 12376, '4. Mycobacterium microti.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35873, 12376, '5. Mycobacterium avium-intracellulare.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35874, 12377, '1. Isoniacida, etambutol, pirazinamida durante 12 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35875, 12377, '2. Isoniacida, etambutol, pirazinamida durante 12 meses y estreptomicina por dos meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35876, 12377, '3. Isoniacida, etambutol, pirazinamida durante 12 meses y una quinolona por dos meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35877, 12377, '4. Isoniacida, etambutol, pirazinamida y una quinolona durante 18 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35878, 12377, '5. Isoniacida, etambutol, pirazinamida durante 18 meses y estreptomicina y una quinolona durante dos meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35879, 12378, '1. Son más prolongadas que en los pacientes sin VIH.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35880, 12378, '2. Deben incluir más fármacos que en los pacientes sin VIH.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35881, 12378, '3. Son las mismas que en los pacientes sin VIH.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35882, 12378, '4. No presentan interacciones farmacológicas con los antirretrovirales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35883, 12378, '5. El tratamiento debe ser indefinido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35884, 12379, '1. Tranquilizarle, ya que no tiene ningún riesgo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35885, 12379, '2. Realizarle una radiografía de tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35886, 12379, '3. Iniciar quimioprofilaxis y repetir la prueba cutánea a los 3 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35887, 12379, '4. Repetir la prueba cutánea al mes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35888, 12379, '5. Habría que realizar estudio del esputo antes de iniciar quimioprofilaxis con Isoniacida durante 1 año.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35889, 12380, '1. Condensación pulmonar bilateral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35890, 12380, '2. Infiltrados pulmonares bilaterales e hiperclaridad lateral y basal izquierda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35891, 12380, '3. Patrón intersticial bilateral difuso e hiperclaridad pulmonar basal bilateral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35892, 12380, '4. Patrón reticulonodular bilateral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35893, 12380, '5. Patrón alveolar bilateral e hiperclaridad bilateral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35894, 12381, '1. Neumonía bilateral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35895, 12381, '2. Neumotórax espontáneo bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35896, 12381, '3. Neumotórax espontáneo izquierdo secundario a tuberculosis con afectación bilateral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35897, 12381, '4. Neumotórax espontáneo primario izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35898, 12381, '5. Neumotórax bilateral secundario a neumonía bilateral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35899, 12382, '1. Sólo separarlo de la madre hasta que ésta concluya su tratamiento (al menos 6 meses).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35900, 12382, '2. Realizar una TC de alta resolución pulmonar y, si es normal, repetir la PT a las 8-12 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35901, 12382, '3. Quimioprofilaxis con isoniacida (INH), hasta que la baciloscopia de la madre sea negativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35902, 12382, '4. Quimioprofilaxis con INH, 6-9 meses. Nueva PT y RX tórax al finalizarlo, para decidir si concluir, o no, el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35903, 12382, '5. Quimioprofilaxis con INH, 8-12 semanas. Repetir PT. Si negativa cesar el tratamiento. Si positiva, realizar RX tórax, para decidir si hay o no enfermedad.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35904, 12383, '1. Varón de 40 años con infección por el virus de la inmunodeficiencia humana con linfocitos CD4 del 1%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35905, 12383, '2. Mujer de 65 años con artritis reumatoide en tratamiento con fármacos antiTNF.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35906, 12383, '3. Mujer de 50 años con transplante renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35907, 12383, '4. Niño de 12 años con padre diagnosticado de tuberculosis bacilifera y que en el estudio de contactos presenta Mantoux positivo de 20 mm.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35908, 12383, '5. Varón de 45 años, no vacunado de BCG, que al comenzar un nuevo trabajo le detectan un Mantoux de 12 mm.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35909, 12384, '1. Tratamiento de infección tuberculosa latente, profilaxis primaria de Pneumocystis jiroveci y tratamiento antirretroviral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35910, 12384, '2. Tratamiento de infección tuberculosa latente y profilaxis primaria de P. jiroveci. No tiene criterios de inicio de tratamiento antirretroviral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35911, 12384, '3. Tratamiento de infección tuberculosa latente y tratamiento antirretroviral. No tiene criterios de inicio de profilaxis de P. jiroveci', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35912, 12384, '4. Tratamiento de infección tuberculosa latente. No tiene criterios de inicio de profilaxis de P. jiroveci ni de tratamiento antirretroviral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35913, 12384, '5. Seguimiento sin ninguna intervención específica en este momento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35914, 12385, '1. El paciente puede ser dado de alta con tratamiento antibiótico y realizar una radiografía de control en un mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35915, 12385, '2. Se debe realizar un estudio de tomografía computarizada (TC) torácica ante la sospecha de neoplasia pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35916, 12385, '3. El paciente puede ser bacilífero y se debe realizar un análisis del esputo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35917, 12385, '4. Se debe obtener un diagnóstico citológico mediante broncoscopia o punción percutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35918, 12385, '5. Se debe completar el estudio con una Resonancia Magnética con gadolinio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35919, 12386, '1. La utilización de más de un fármaco al que el microorganismo sea sensible.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35920, 12386, '2. La estrategia de inducción con un número elevado de fármacos durante dos meses, seguida de un tratamiento simplificado de duración prolongada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35921, 12386, '3. En la actualidad el tratamiento de inicio recomendado está compuesto por isoniacida, rifampicina, etambutol y pirazinamida', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35922, 12386, '4. En casos de fracaso terapéutico se recomienda monitorizar los niveles plasmáticos de los fármacos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35993, 12401, '4. Tuberculosis miliar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35923, 12386, '5. La utilización de procedimientos de administración directamente observada es recomendable en determinados pacientes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35924, 12387, '1. Recoger al menos 3 muestras de esputo matutino para baciloscopia y cultivo, solicitar Mantoux y análisis de sangre, incluyendo transaminasas, y serología de VIH, y aislarle en domicilio hasta tener los resultados.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35925, 12387, '2. Avisar a Epidemiología de la Comunidad Autónoma para que inicie el protocolo de estudio y tratamiento de los contactos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35926, 12387, '3. Remitirle a Urgencias del Hospital para estudio y tratamiento antituberculoso, durante 2-3 semanas, o hasta que la baciloscopia sea negativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35927, 12387, '4. Comenzar tratamiento antituberculoso mientras esperamos las baciloscopias de esputo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35928, 12387, '5. Dado que es una persona de alto riesgo, debe estar vacunado de la tuberculosis y por ello el Mantoux no es valorable.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35929, 12388, '1. Menores de 35 años con test de la tuberculina negativo y contacto con un paciente bacilífero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35930, 12388, '2. Menores de 35 años con test de la tuberculina positivo y contacto con un paciente bacilífero.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35931, 12388, '3. Pacientes inmunodeprimidos de cualquier edad con test de la tuberculina negativo y contacto con un paciente bacilífero.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35932, 12388, '4. Pacientes que van a recibir tratamiento con anticuerpos monoclonales anti TNF-α y con test de tuberculina negativo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35933, 12388, '5. Pacientes con infección por el virus de la inmunodeficiencia humana (VIH) y con test de la tuberculina positivo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35934, 12389, '1. Staphylococcus aureus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35935, 12389, '2. Pseudomonas aeruginosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35936, 12389, '3. Virus de la hepatitis C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35937, 12389, '4. Entamoeba histolytica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35938, 12389, '5. Mycobacterium tuberculosis.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35939, 12390, '80. 000/µL. En el frotis de sangre periférica no se observan anomalías morfológicas ni parásitos intra o extracelulares. Después de realizar una TC de tórax y abdomen, junto con distintos cultivos y serologías de VIH, VHB y VHC, todos con resultado negativo, se obtiene un aspirado de médula ósea (imagen). ¿A cuál de los siguientes corresponde la imagen?', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35940, 12390, '1. Gametocitos de Plasmodium falciparum', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35941, 12390, '2. Amastigotes de Leishmania infantum', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35942, 12390, '3. Tripomastigotes de Trypanosoma brucei', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35943, 12390, '4. Micro filarias de Loa Loa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35944, 12391, '1. Mefloquina por vía oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35945, 12391, '2. Artesunato intravenoso.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35946, 12391, '3. Doxiciclina por vía oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35947, 12391, '4. Sulfato de quinina por vía oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35948, 12392, '1. Recomendar que sus hijos se hagan la serología de T. cruzi por el riesgo de transmisión transplacentaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35949, 12392, '2. Informar a la paciente del riesgo de transmisión de T. cruzi y de la actitud que se va a tomar durante el embarazo, parto y postparto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35950, 12392, '3. Recomendar que su marido se haga la serología de T. cruzi por el riesgo de haberle transmitido la enfermedad por vía sexual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35951, 12392, '4. Recomendar que sus hermanos se hagan la serología de T. cruzi por el riesgo de transmisión vectorial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35952, 12393, '1. Borrelia burgdorferi.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35953, 12393, '2. Francisella tularensis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35954, 12393, '3. Rickettsia conorii.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35955, 12393, '4. Babesia spp.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35956, 12394, '1. Cyclospora spp.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35957, 12394, '2. Giardia lamblia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35958, 12394, '3. Acanthamoeba spp.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35959, 12394, '4. Ascaris lumbricoides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35960, 12395, '1. Infestación por Schistosoma haematobium.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35961, 12395, '2. Infestación por Ancylostoma duodenalis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35962, 12395, '3. Infestación por Strongyloides stercoralis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35963, 12395, '4. Infestación por Ascaris lumbricoides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35964, 12395, '5. Infestación por Necator americanus.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35965, 12396, '1. Realizaría una biopsia de médula ósea, ya que el diagnóstico más probable es una leishmaniasis visceral.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35966, 12396, '2. La pancitopenia se justifica por una cirrosis asociada al virus C y no realizaría más pruebas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35967, 12396, '3. Probablemente se trate de una toxicidad medular por prednisona que trataría con retirada del fármaco y filgastrim.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35968, 12396, '4. Solicitaría una determinación de ANAs para descartar lupus sistémico diseminado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35969, 12396, '5. Intensificaría el tratamiento antirretroviral, pues es probable que todas las manifestaciones que presenta se deban al VIH.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35970, 12397, '1. Resonancia magnética nuclear.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35971, 12397, '2. Determinación de alfa-fetoproteína y antígeno carcinoembrionario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35972, 12397, '3. Serología de Echinococcus granulosus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35973, 12397, '4. Serología de Entamoeba histolytica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35974, 12397, '5. Biopsia percutánea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35975, 12398, '1. Elevación marcada de los reactantes de fase aguda.', false, 1);
