INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (35995, 12402, '1. La infección del ser humano comienza con la picadura del mosquito Anopheles, que introduce esporozoitos con su saliva en el sistema circulatorio.', false, 1);
