INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36103, 12424, '5. Adenocarcinoma de colon', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36104, 12425, '1. El mecanismo de transmisión es por gotas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36105, 12425, '2. Se dispone de vacunas efectivas únicamente para la prevención de 4 subtipos de meningococo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36106, 12425, '3. La vacuna frente a meningococo tipo B está incluida en el calendario sistemático de inmunizaciones del Sistema Nacional de Salud.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36107, 12425, '4. Ante un contacto de riesgo con un paciente con meningitis meningocócica, la vacunación del contacto no debe ser la primera estrategia de profilaxis postexposición.', false, 4);
