INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36119, 12428, '4. Cefotaxima y tuberculostáticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36120, 12429, '1. Aciclovir.', true, 1);
