INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36122, 12429, '3. Aciclovir más metilprednisolona IV.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36123, 12429, '4. Vancomicina, ampicilina y ceftriaxona IV.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36124, 12430, '1. En nuestro medio más del 50 % de los S. pneumoniae causantes de meningitis son resistentes a penicilina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36125, 12430, '2. La mortalidad de la meningitis por S. pneumoniae que requiere ingreso en UCI supera el 30 %.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36126, 12430, '3. La precocidad en el inicio del tratamiento es básica para el buen pronóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36127, 12430, '4. El uso de dexametasona mejora el pronóstico funcional y vital.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36128, 12431, '1. Es un bacilo grampositivo, catalasa positiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36129, 12431, '2. Está ampliamente distribuida en el suelo, aguas residuales y vegetación en descomposición.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36130, 12431, '3. El hombre y los animales pueden ser portadores asintomáticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36131, 12431, '4. El tratamiento de elección de la meningitis por L. monocytogenes es una cefalosporina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36132, 12432, '1. Aplastamiento vertebral con tomografía computarizada (TC).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36133, 12432, '2. Metástasis óseas con gammagrafía ósea con tecnecio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36134, 12432, '3. Hiperostosis anquilosante vertebral con radiografía de columna dorsolumbar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36135, 12432, '4. Espondilodiscitis piógena con resonancia magnética (RM).', true, 4);
