INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36143, 12434, '4. Toxoplasmosis cerebral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36144, 12435, '1. Una meningitis bacteriana es la primera impresión diagnóstica y hay que iniciar cuanto antes tratamiento con cefalosporina de 3ª generación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36145, 12435, '2. Lo más probable es que el LCR de este paciente nos muestre una pleocitosis de predominio linfocitario con glucorraquia normal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36146, 12435, '3. Sospecharíamos una encefalitis límbica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36147, 12435, '4. Se trata de un absceso cerebral en fase inicial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36148, 12436, '1. Extraer hemocultivos, perfundir suero salino y administrar tratamiento con dexametasona, ceftriaxona, vancomicina y ampicilina intravenosos y después hacer TAC craneal y punción lumbar si no hay contraindicación y reevaluar el tratamiento tras el TAC.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36149, 12436, '2. Hacer TAC con la urgencia que se pueda, fondo de ojo, posterior cultivo del LCR y tratamiento antibiótico dirigido según los datos del GRAM del LCR.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36150, 12436, '3. Poner antitérmico iv, iniciar tratamiento con dopamina iv a dosis alfa y cuando esté estable hemodinámicamente, hacer TAC craneal, punción lumbar e iniciar tratamiento antibiótico guiado según los datos analíticos del LCR.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36151, 12436, '4. Iniciar tratamiento con ceftazidima + aciclovir + vancomicina intravenosos.', false, 4);
