INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36154, 12437, '3. Retraso mental.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36155, 12437, '4. Hidrocefalia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36156, 12437, '5. Defectos visuales.', false, 5);
