INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36158, 12438, '2. Vancomicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36162, 12439, '1. En una faringoamigdalitis aguda en un niño.', false, 1);
