INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36171, 12440, '5. Virus herpes', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36172, 12441, '1. Gammagrafía ósea con MDP-Tec99m y Galio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36173, 12441, '2. Tomografía por emisión de positrones (PET).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36174, 12441, '3. Densitometría ósea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36175, 12441, '4. Biopsia y examen patológico y microbiológico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36176, 12441, '5. Determinar marcadores tumorales de neoplasia de colon.', false, 5);
