INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36178, 12442, '2. Antibioterapia parenteral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36179, 12442, '3. Iniciar calcio más vitamina D y bifosfonatos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36180, 12442, '4. Radioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36181, 12442, '5. Reposo y AINEs y revalorar al paciente en un mes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36182, 12443, '1. Meningitis vírica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36183, 12443, '2. Meningitis bacteriana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36184, 12443, '3. Meningitis tuberculosa.', true, 3);
