INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36186, 12443, '5. Síndrome de Guillain Barré.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36187, 12444, '1. Neurosífilis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36188, 12444, '2. Meningitis fúngica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36189, 12444, '3. Meningitis tuberculosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36190, 12444, '4. Meningitis carcinomatosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36191, 12444, '5. Linfoma del sistema nervioso central.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36192, 12445, '1. El Tétanos aparece tras un período mínimo de incubación de 14 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36193, 12445, '2. La mortalidad del Tétanos es todavía en la actualidad, superior al 50%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36194, 12445, '3. En el diagnóstico del Tétanos, es fundamental haber efectuado cultivos previos al inicio del tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36195, 12445, '4. El Tétanos está caracterizado por una rigidez generalizada junto a crisis de espasmos musculares.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36196, 12445, '5. En el tratamiento del Tétanos es fundamental mantener el estado de alerta del enfermo, con el fin de evitar aspiraciones.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36197, 12446, '1. Neisseria meningitidis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36198, 12446, '2. Streptococcus pneumoniae.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36199, 12446, '3. Streptococcus agalactiae.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36200, 12446, '4. Mycobacterium tuberculosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36201, 12446, '5. Listeria monocytogenes.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36202, 12447, '1. En el momento actual hay varias vacunas autorizadas frente a la meningitis B eficaces.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36203, 12447, '2. La transmisión del meningococo no se produce de persona a persona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36204, 12447, '3. Existen vacunas conjugadas frente a la meningitis C de gran eficacia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36205, 12447, '4. Las vacunas más inmunogénicas son las polisacarídicas no conjugadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36206, 12447, '5. Las tasas de incidencia de enfermedad meningocócica son similares en las distintas partes del mundo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36207, 12448, '1. PCR de herpes virus humano 1 y 2 (HUH-1 y HUH-2).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36208, 12448, '2. Aglutinación látex de Cryptococcus neoformans.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36209, 12448, '3. Cultivo de enterovirus.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36210, 12448, '4. Gram y cultivo bacteriológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36211, 12448, '5. PCR de Neisseria meningitidis, Hemophilus influenzae y Streptococus pneumoniae.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36212, 12449, '1. Iniciar tratamiento empírico con antibióticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36213, 12449, '2. Iniciar tratamiento anticomicial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36214, 12449, '3. Realizar punción lumbar diagnóstica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36215, 12449, '4. Iniciar tratamiento con Dexametasona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36216, 12449, '5. Solicitar una TC (tomografía computerizada) de cráneo con contraste intravenoso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36217, 12450, '1. Claritromicina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36218, 12450, '2. Imipenem.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36219, 12450, '3. Ceftriaxona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36220, 12450, '4. Norfloxacino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36221, 12451, '1. Pacientes diagnosticados de VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36222, 12451, '2. Pacientes candidatos a trasplante hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36223, 12451, '3. Pacientes diagnosticados de asplenia anatómica o disfunción esplénica grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36224, 12451, '4. Pacientes diagnosticados de enfermedad hepática crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36225, 12452, '1. Por su perfil de seguridad para el feto, pueden administrarse durante cualquier periodo del embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36226, 12452, '2. Se recomienda retrasar su administración en niños que han recibido recientemente inmunoglobulinas inespecíficas a altas dosis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36227, 12452, '3. Dado que no se trata de virus salvajes, pueden administrarse en niños con inmunosupresión grave.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36228, 12452, '4. Ya no forman parte de los calendarios oficiales de vacunación pediátrica de nuestro país.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36229, 12453, '1. La producción de interferones tipo I tras el reconocimiento del ARN vírico por receptores de reconocimiento de patrón como los Toll-like receptors (TLR) o los RIG-like receptors (RLR).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36230, 12453, '2. La producción de interferón gamma por los linfocitos CD4+ Th1 tras el reconocimiento de péptidos víricos en las células presentadoras de antígeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36231, 12453, '3. La producción de anticuerpos neutralizantes tipo IgG producidos en respuesta a las proteínas víricas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36232, 12453, '4. La actividad citotóxica mediada por linfocitos T CD8+ tras el reconocimiento de péptidos víricos en las células infectadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36233, 12454, '1. Cada linfocito y su descendencia (clona) expresa un único tipo de ellos con una sola especificidad antigénica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36234, 12454, '2. Cada linfocito y su descendencia (clona) expresa un único tipo de ellos con varias especificidades antigénicas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36693, 12557, '2. Macrófagos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36235, 12454, '3. Varios linfocitos y sus descendencias (clonas) expresan varios tipos de ellos con varias especificidades antigénicas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36236, 12454, '4. Tras clonaje molecular y reordenamiento génico, los linfocitos adquieren especificidad antigénica clonal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36237, 12455, '1. El isotipo de una inmunoglobulina viene determinado por el tipo de cadena pesada y de cada ligera que la configuran.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36238, 12455, '2. Las inmunoglobulinas circulantes son sintetizadas por las células dendríticas en los órganos linfoides secundarios.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36239, 12455, '3. Los genes que codifican las regiones variables de las cadenas de las inmunoglobulinas sufren un reordenamiento somático V(D)J durante el desarrollo de los linfocitos B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36240, 12455, '4. La inmunoglobulina G (IgG) es la predominante en el suero y en el espacio extravascular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36241, 12455, '5. La IgG es la única inmunoglobulina que atraviesa la placenta.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36242, 12456, '1. Su especificidad inmunológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36243, 12456, '2. La inducción de memoria inmunitaria permanente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36244, 12456, '3. El reconocimiento de patrones moleculares vinculados a patógenos (PAMP) por proteínas de la familia Toll (TLR).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36245, 12456, '4. La no intervención de células presentadoras de antígeno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36246, 12456, '5. La participación de linfocitos B y linfocitos T.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36247, 12457, '"1. Los anticuerpos IgG con alta afinidad para antígenos peptidoglucanos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36248, 12457, '2. Los linfocitos TH2 de los ganglios linfáticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36249, 12457, '3. Los linfocitos T citotóxicos (CD3+CD8+).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36250, 12457, '4. Los receptores de tipo ""toll"" (TLR) de los fagocitos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36251, 12457, '5. Las células T de memoria circulantes."', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36252, 12458, '1. Reconoce estructuras microbianas altamente conservadas y compartidas por diferentes tipos de especies microbianas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36253, 12458, '2. Sus componentes celulares y humorales principales son los linfocitos (T y B) y los anticuerpos, respectivamente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36254, 12458, '3. Es llevada a cabo por receptores celulares y solubles altamente polimórficos con una distribución celular de tipo clonal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36255, 12458, '4. Guarda memoria de contactos previos con el mismo patógeno aumentando la intensidad de la respuesta con cada nueva exposición.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36256, 12458, '5. Tiene un tiempo de acción lento o diferido (días o semanas).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36257, 12459, '1. Su principal componente son las barreras epiteliales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36258, 12459, '2. Toll-Like proteínas son cruciales en el reconocimiento de patógenos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36259, 12459, '3. La eliminación de patógenos se produce mediante linfocitos específicos de antígeno.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36260, 12459, '4. La fagocitosis y el sistema del complemento son elementos esenciales de la misma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36261, 12459, '5. El reconocimiento de antígenos se realiza con un pequeño número de receptores (repertorio muy limitado).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36262, 12460, '1. Linfocitos B CD5+ (B 1a).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36263, 12460, '2. Linfocitos T colaboradores CD4+.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36264, 12460, '3. Linfocitos T citotóxicos CD8+.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36265, 12460, '4. Linfocitos T gamma/delta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36266, 12460, '5. Linfocitos NK (Natural Killer o asesinos naturales).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36267, 12461, '1. Los 3 principales tipos de tejido linfoide periférico son el bazo, los nódulos linfáticos y el tejido linfoide asociado a la mucosa (MALT).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36268, 12461, '2. Los neutrófilos, eosinófilos y basófilos son llamados en su conjunto linfocitos de respuesta inmune retardada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36269, 12461, '3. Los mastocitos están especializados en la respuesta inmune contra virus y secretan sustancias que alejan a los eosinófilos y basófilos en lugar de inflamación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36270, 12461, '4. Los linfocitos T maduran en la médula ósea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36271, 12461, '5. Los linfocitos y las líneas mieloides derivan de una célula madre mesenquimal pluripotente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36272, 12462, '1. El linfocito B reconoce fragmentos del Polisacárido y presenta fragmentos de éste a las células T.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36273, 12462, '2. El linfocito B reconoce fragmentos del toxoide tetánico y produce Anticuerpos frente al Polisacárido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36274, 12462, '3. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide a las células T y produce Anticuerpos frente al toxoide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36275, 12462, '4. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide de los linfocitos T y produce Anticuerpos frente al Polisacárido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36276, 12462, '5. El linfocito B reconoce fragmentos del toxoide, presenta fragmentos del toxoide a los linfocitos T y produce Anticuerpos frente al Polisacárido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36277, 12463, '1. El linfocito B reconoce fragmentos del Polisacárido y presenta fragmentos de éste a las células T.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36278, 12463, '2. El linfocito B reconoce fragmentos del toxoide tetánico y produce Anticuerpos frente al Polisacárido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36279, 12463, '3. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide a las células T y produce Anticuerpos frente al toxoide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36280, 12463, '4. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide de los linfocitos T y produce Anticuerpos frente al Polisacárido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36281, 12463, '5. El linfocito B reconoce fragmentos del toxoide, presenta fragmentos del toxoide a los linfocitos T y produce Anticuerpos frente al Polisacárido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36282, 12464, '1. La IgA activa la vía clásica del complemento contribuyendo a la eliminación de bacterias extracelulares.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36283, 12464, '2. La IgA pasa de la madre al recién nacido durante la lactancia contribuyendo a la protección de las mucosas del neonato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36284, 12464, '3. La IgA puede atravesar la barrera epitelial de las mucosas uniéndose al receptor poli-Ig (pIgR) siendo la inmunoglobulina más abundante en las mucosas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36285, 12464, '4. El déficit selectivo de IgA es la inmunodeficiencia más frecuente (aproximadamente 1:400) y la mayoría de los casos son asintomáticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36286, 12465, '1. La IgA se une al receptor poli-Ig (pIgR) para atravesar la placenta y participar en la defensa del neonato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36287, 12465, '2. La IgG se une al receptor III para Fc-gamma (Fc-gamma-RIII) de los fagocitos activando el proceso de opsonización.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36417, 12494, '1. Hemoglobinuria paroxística nocturna.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36288, 12465, '3. La IgM se une a C1q y activa la vía clásica del complemento contribuyendo a la eliminación de bacterias extracelulares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36289, 12465, '4. La IgE se une al receptor para Fc-épsilon (Fcépsilon-R) y activa a eosinófilos y mastocitos participando en la defensa frente a los helmintos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36290, 12466, '1. La IgG se une al receptor III para Fc-gamma (Fcgamma-RIII) en las células NK activando la citotoxicidad celular dependiente de anticuerpos (ADCC).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36291, 12466, '2. La IgA se une al receptor poli-Ig (pIgR) del epitelio intestinal para llegar a la luz intestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36292, 12466, '3. La IgM se une al receptor Fc neonatal (FcRn) en el sincitiotrofoblasto para atravesar la placenta.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36293, 12466, '4. La IgE se une al receptor para Fc-epsilon (Fcepsilon-R) en mastocitos e induce su desgranulación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36294, 12467, '5. Para que el sistema inmune de la madre produzca anticuerpos de isotipo IgM, específicos contra el patógeno, que permitan que tanto ella como el feto se encuentren inmunizados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36295, 12467, '6. Para que el sistema inmune de la madre produzca anticuerpos de isotipo IgG, específicos contra el patógeno, que permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma pasiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36296, 12467, '7. Para que el sistema inmune del feto produzca anticuerpos de isotipos IgM e IgG, específicos contra el patógeno, que permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma activa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36297, 12467, '8. Para que el sistema inmune de la madre produzca linfocitos T memoria, que atraviesen la placenta y permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma pasiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36298, 12468, '1. Es una reacción mediada por IgE.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36299, 12468, '2. Está mediada por anticuerpos de la clase IgG de la madre.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36300, 12468, '3. Está mediada por anticuerpos del recién nacido.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36301, 12468, '4. Es una reacción mediada por células T CD8+.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36302, 12469, '1. La lisis de dichos microorganismos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36303, 12469, '2. La fagocitosis de dichos microorganismos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36304, 12469, '3. Las reacciones de hipersensibilidad de tipo I frente a dichos microorganismos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36305, 12469, '4. La anergia de las células T específicas frente a dichos microorganismos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36306, 12470, '1. La defensa de las mucosas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36307, 12470, '2. La respuesta secundaria adquirida en trasplante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36308, 12470, '3. La actividad citotóxica dependiente de anticuerpos, mediante receptores para su fracción constante en el macrófago.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36309, 12470, '4. La respuesta celular T alogénica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36310, 12471, '1. IgM.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36311, 12471, '2. IgA.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36312, 12471, '3. IgE.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36313, 12471, '4. IgG.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36314, 12472, '1. El isotipo de una inmunoglobulina viene determinado por el tipo de cadena pesada y de cada ligera que la configuran.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36315, 12472, '2. Las inmunoglobulinas circulantes son sintetizadas por las células dendríticas en los órganos linfoides secundarios.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36316, 12472, '3. Los genes que codifican las regiones variables de las cadenas de las inmunoglobulinas sufren un reordenamiento somático V(D)J durante el desarrollo de los linfocitos B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36317, 12472, '4. La inmunoglobulina G (IgG) es la predominante en el suero y en el espacio extravascular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36318, 12472, '5. La IgG es la única inmunoglobulina que atraviesa la placenta.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36319, 12473, '1. Las inmunoglobulinas se sintetizan en los órganos linfoides pero son capaces de realizar su función efectora lejos de su lugar de síntesis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36320, 12473, '2. Todos los diferentes isotipos de inmunoglobulinas (IgG, IgA, IgM, IgE, IgD) pueden ser trasportados a través de diferentes compartimentos y fluidos incluyendo la placenta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36321, 12473, '3. En sus funciones efectoras, los anticuerpos utilizan tanto la región variable para la unión al antígeno como las regiones constantes de la molécula.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36322, 12473, '4. Los mecanismos de opsonización mediados por inmunoglobulinas implican la participación de células y receptores ajenos a las células B productoras de anticuerpos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36323, 12473, '5. Existen mecanismos de citotoxicidad celular mediados por IgE capaces de reconocer y eliminar helmintos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36324, 12474, '1. Ig G2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36325, 12474, '2. Ig E e Ig G3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36326, 12474, '3. Ig A e Ig M.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36327, 12474, '4. Ig D.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36328, 12474, '5. Ig G4 e Ig D.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36329, 12475, '1. Recombinación somática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36330, 12475, '2. Diversidad de unión por adición de nucleótidos N (no codificados).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36331, 12475, '3. Hipermutación somática.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36332, 12475, '4. Diversidad de unión por adición de nucleóticos P (palindrómicos).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36333, 12476, '1. Los pacientes presentan niveles elevados de IgM mientras que mantienen niveles normales de IgG e IgA en suero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36334, 12476, '2. Presentan un defecto de la diferenciación de los linfocitos B en la médula ósea con aumento de linfocitos B inmaduros que expresan la cadena mu intracitoplasmática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36335, 12476, '3. Existe un defecto en el proceso de colaboración entre linfocitos T y B necesario para el cambio de isotipo de las inmunoglobulinas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36336, 12476, '4. Existe un defecto en el proceso de reordenamiento de los genes V de las inmunoglobulinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36337, 12477, '6. Ig G2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36338, 12477, '7. Ig E e Ig G3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36339, 12477, '8. Ig A e Ig M.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36340, 12477, '9. Ig D.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36341, 12477, '10. Ig G4 e Ig D.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36342, 12478, '1. DQ8.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36343, 12478, '2. DQ2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36344, 12478, '3. B27.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36345, 12478, '4. B12.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36346, 12479, '1. Son proteínas nucleares muy polimórficas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36347, 12479, '2. Se dividen en moléculas de clase IgG. IgA e IgM.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36348, 12479, '3. Unen péptidos y los presentan en la superficie celular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36349, 12479, '4. Interaccionan con las citocinas para modular la respuesta inmune.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36350, 12479, '5. Son monomórficas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36418, 12494, '2. Síndrome antifosfolípido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36351, 12480, '1. Los linfocitos T reconocen determinantes antigénicos conformacionales o no lineales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36352, 12480, '2. Los linfocitos T reconocen antígenos solubles y en forma nativa (no desnaturalizada o no procesada) tal y como se presentan en la naturaleza.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36353, 12480, '3. Los linfocitos T CD8 + reconocen péptidos exógenos asociados a moléculas MHC de clase II.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36354, 12480, '4. Los linfocitos T CD4 + reconocen péptidos citosólicos (endógenos) asociados a moléculas MHC clase I.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36355, 12480, '5. Los linfocitos T reconocen antígenos peptídicos asociados a moléculas MHC (Major Histocompatibility Complex) propias.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36356, 12481, '1. A11.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36357, 12481, '2. B7.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36358, 12481, '3. Cw3.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36359, 12481, '4. DR2.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36360, 12481, '5. CD1.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36361, 12482, '1. Hemograma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36362, 12482, '2. Respuesta a mitógenos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36363, 12482, '3. Cuantificación de inmunoglobulinas por nefelometría.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36364, 12482, '4. Proteinograma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36365, 12482, '5. Citometría de flujo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36366, 12483, '1. Linfocitos B CD5+ (B 1a).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36367, 12483, '2. Linfocitos T colaboradores CD4+.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36368, 12483, '3. Linfocitos T citotóxicos CD8+.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36369, 12483, '4. Linfocitos T gamma/delta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36370, 12483, '5. Linfocitos NK (Natural Killer o asesinos naturales).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36371, 12484, '1. Autotolerancia a proteínas propias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36372, 12484, '2. Deleción clonal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36373, 12484, '3. Autoinmunidad frente a proteínas propias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36374, 12484, '4. Restricción por moléculas de histocompatibilidad propias.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36375, 12484, '5. Inmunización frente a patógenos intracelulares.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36376, 12485, '1. Ciclofosfamida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36377, 12485, '2. Sirolimus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36378, 12485, '3. Azatioprina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36379, 12485, '4. Micofenolato mofetilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36380, 12485, '5. Ciclosporina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36381, 12486, '1. El receptor de antígeno del linfocito T es el encargado de reconocer el péptido extraño en el contexto de moléculas del complejo mayor de histocompatibilidad tanto de clase I como de clase II.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36382, 12486, '2. Si el reconocimiento de antígeno se produce en ausencia de una señal coestimuladora se desencadena un fenómeno de tolerancia inmunológica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36383, 12486, '3. Puede conseguirse una tolerancia activa del linfocito T a través del bloqueo de la vía B7/CD28.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36384, 12486, '4. Durante la activación del linfocito T, la molécula CD45 es alejada del complejo del receptor de la célula T para permitir que ocurran los fenómenos de fosforilación que llevarán a la activación celular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36385, 12486, '5. Las células dendríticas de Langerhans son una subpoblación de células T activadas presentes en la piel.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36386, 12487, '1. Se unen a la porción lateral de la cadena alfa del receptor de la célula T y a la cadena beta de las moléculas del complejo mayor de histocompatibilidad de clase II.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36387, 12487, '2. Son moléculas de naturaleza proteica capaces de activar hasta un 20% de los linfocitos T de sangre periférica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36388, 12487, '3. Están implicados en el desencadenamiento del síndrome del aceite tóxico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36389, 12487, '4. En su mayor parte son agentes nutricionales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36390, 12487, '5. Para su acción utiliza la vía alternativa del complemento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36391, 12488, '5. Está indicada en niños menores de dos años en situación de riesgo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36392, 12488, '6. Induce una respuesta secundaria con altos niveles de IgG específica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36393, 12488, '7. Inducen maduración de la afinidad de los anticuerpos generados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36394, 12488, '8. No genera memoria inmunológica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36395, 12489, '1. Las células presentadoras de antígenos procesan los antígenos y los presentan a otros tipos celulares junto a proteínas del complemento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36396, 12489, '2. Los linfocitos T citotóxicos reconocen moléculas del complejo mayor de histocompatibilidad de clase II en la superficie de los macrófagos que están unidas a antígenos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36397, 12489, '3. Los linfocitos B y los macrófagos presentan antígenos a los linfocitos T cooperadores en conjunción a moléculas del complejo mayor de histocompatibilidad de clase II.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36398, 12489, '4. Los eosinófilos son una célula clave en la eliminación de virus.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36399, 12489, '5. Los virus no son procesados y desencadenan respuestas inflamatorias directas mediadas por linfocitos T cooperadores.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36400, 12490, '1. Está caracterizada por una respuesta temprana mediada por IgG (Inmunoglobulina tipo G).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36401, 12490, '2. Las inmunoglobulinas son secretadas por distintos tipos celulares, incluyéndose los macrófagos y los linfocitos T.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36402, 12490, '3. Las respuestas inflamatorias reactivas a infecciones por parásitos son mediadas por IgD (Inmunoglobulina tipo D).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36403, 12490, '4. Los linfocitos B presentan en su superficie inmunoglobulinas y moléculas del complejo mayor de histocompatibilidad siendo capaces de funcionar como células presentadoras de antígeno.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36404, 12490, '5. La maduración final de los linfocitos B se produce en el timo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36405, 12491, '1. PD-1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36406, 12491, '2. PD-L1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36407, 12491, '3. CTLA-4.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36408, 12491, '4. HER2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36409, 12492, '1. La molécula PD-1 es un receptor inhibidor de los linfocitos T que se expresa mayoritariamente en linfocitos T naive.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36410, 12492, '2. La interacción de PD-1 y sus ligandos inhibe la activación de los linfocitos T en los ganglios linfáticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36411, 12492, '3. El bloqueo de PD-1 o de sus ligandos potencia la capacidad antitumoral de los linfocitos T CD8+.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36412, 12492, '4. El uso de este tipo de inmunoterapia no se debe combinar con tratamientos de quimioterapia', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36413, 12493, '1. Colaboran en la eliminación de células tumorales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36414, 12493, '2. Expresan el correceptor inhibidor CTLA-4.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36415, 12493, '3. Coexpresan tanto CD4 como CD8.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36416, 12493, '4. Liberan citoquinas como IL-17 o IL-22.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36419, 12494, '3. Coproporfiria eritropoyética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36420, 12494, '4. Fiebre mediterránea familiar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36421, 12495, '1. Vía clásica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36422, 12495, '2. Vía alternativa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36423, 12495, '3. Vía de las lectinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36424, 12495, '4. Fase lítica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36425, 12495, '5. Vía dependiente de anticuerpos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36426, 12496, '1. Se une a ICAM-1 y es responsable del paso de linfocitos desde la sangre periférica a los ganglios linfáticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36427, 12496, '2. Es un receptor para TNF-a en los linfocitos T CD4+ del sistema linfoide asociado a mucosas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36428, 12496, '3. Se expresa en las células del epitelio gastrointestinal en pacientes con enfermedad inflamatoria intestinal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36429, 12496, '4. Se une a la adresina MadCAM-1 y favorece el paso de linfocitos desde la sangre periférica a la placa de Peyer y la lámina propia intestinal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36430, 12497, '1. Inhibe el crecimiento bacteriano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36431, 12497, '2. Incrementa la actividad bactericida de los fagocitos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36432, 12497, '3. Estimula la vía alternativa del complemento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36433, 12497, '4. Estimula la síntesis de proteínas de fase aguda y de inmunoglobulinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36434, 12497, '5. Produce secuestro de hierro sérico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36435, 12498, '1. Interleucina-1 alfa. Interleucina-1 beta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36436, 12498, '2. Tumor necrosis factor-alfa. Tumor necrosis factor-beta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36437, 12498, '3. Interleucina-17. Interleucina -22.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36438, 12498, '4. Interleucina -10. Trasforming growth factor-beta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36439, 12498, '5. Interleucina 2. Interferon-gamma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36440, 12499, '1. Endotelina - vasoconstricción.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36441, 12499, '2. Péptido intestinal vasoactivo -vasodilatación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36442, 12499, '3. Serotonina – vasoconstricción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36443, 12499, '4. Prostaciclina – vasodilatación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36444, 12499, '5. Oxido nítrico – vasoconstricción.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36445, 12500, '1. Inhiben la actividad citotóxica de los linfocitos T CD8+ contra las células infectadas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36446, 12500, '2. Son producidos por linfocitos CD4+ Th1 tras el reconocimiento de péptidos víricos mediante el receptor T para el antígeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36447, 12500, '3. Activan la expresión de genes que confieren a la célula huésped una resistencia mayor a la infección viral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36448, 12500, '4. Inhiben la expresión de los antígenos de histocompatibilidad (HLA) de clase I en las células infectadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36449, 12501, '1. Colaboran en la eliminación de células tumorales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36450, 12501, '2. Expresan el correceptor inhibidor CTLA-4.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36451, 12501, '3. Coexpresan tanto CD4 como CD8.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36452, 12501, '4. Liberan citoquinas como IL-17 o IL-22.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36453, 12502, '1. La producción de interferones tipo I tras el reconocimiento del ARN vírico por receptores de reconocimiento de patrón como los Toll-like receptors (TLR) o los RIG-like receptors (RLR).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36454, 12502, '2. La producción de interferón gamma por los linfocitos CD4+ Th1 tras el reconocimiento de péptidos víricos en las células presentadoras de antígeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36455, 12502, '3. La producción de anticuerpos neutralizantes tipo IgG producidos en respuesta a las proteínas víricas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36456, 12502, '4. La actividad citotóxica mediada por linfocitos T CD8+ tras el reconocimiento de péptidos víricos en las células infectadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36457, 12503, '1. Interferon gamma e interleucina 12.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36458, 12503, '2. Interleucina 4 e interleucina 5.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36459, 12503, '3. Interleucina 17 e interleucina 22.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36460, 12503, '4. Interleucina 10 y transforming growth factor beta (TGF-beta).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36461, 12504, '1. Interleucina-1 alfa. Interleucina-1 beta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36462, 12504, '2. Tumor necrosis factor-alfa. Tumor necrosis factor-beta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36463, 12504, '3. Interleucina-17. Interleucina -22.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36464, 12504, '4. Interleucina -10. Transforming growth factor-beta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36465, 12504, '5. Interleucina 2. Interferon-gamma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36466, 12505, '1. Interviene en la activación de la caspasa 1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36467, 12505, '2. Contiene receptores de tipo toll (TLR).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36468, 12505, '3. Interviene en la activación de interleucina-1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36469, 12505, '4. Es una estructura citoplasmática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36470, 12506, '1. Nod-like receptors (NLR).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36471, 12506, '2. Receptor del linfocito T alfa-beta (TcR alfabeta).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36472, 12506, '3. Toll-like receptors (TLR).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36473, 12506, '4. Receptor del linfocito T gamma-delta (TcR gamma-delta)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36474, 12507, '1. La lisis de dichos microorganismos.', false, 1);
