INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36486, 12510, '1. Los linfocitos B son los responsables de la coordinación de la respuesta inflamatoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36487, 12510, '2. En el asma bronquial hay un predominio de fenotipo linfocitario TH1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36488, 12510, '3. Las citocinas IL4 e IL13 son las favorecedoras de la síntesis de IgE.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36489, 12510, '4. La población de linfocitos T reguladores (CD4+ y CD25+) está aumentada.', false, 4);
