INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36491, 12511, '2. Educación del paciente en el uso de antihistamínicos bucodispersables, broncodilatadores en aerosol presurizado y corticoides orales.', false, 2);
