INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36511, 12516, '2. IgA.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36512, 12516, '3. IgE.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36513, 12516, '4. IgG.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36514, 12517, '1. Juegan un papel importante los eosinófilos y los mastocitos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36515, 12517, '2. No intervienen elementos celulares.', false, 2);
