INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36517, 12517, '4. No intervienen elementos del sistema inmune implicados en la atopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36518, 12517, '5. No interviene el receptor de la inmunoglobulina IgE.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36519, 12518, '1. Infecciosa por bacilos Gram negativos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36520, 12518, '2. Isquémica por obstrucción proximal de los vasos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36521, 12518, '3. Inmunológica por depósitos de inmunocomplejos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36522, 12518, '4. Metabólica con depósitos de proteínas glicosiladas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36523, 12518, '5. Reacción inflamatoria a cuerpo extraño.', false, 5);
