INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36525, 12519, '2. Asma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36526, 12519, '3. Miastenia gravis.', true, 3);
