INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36528, 12519, '5. Diabetes mellitus sensible a insulina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36529, 12520, '1. Es una prueba diagnóstica confirmatoria cuando es positiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36530, 12520, '2. Un resultado negativo para HLA-DQ2 y HLA-DQ8 hace muy improbable el diagnóstico de enfermedad celíaca.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36531, 12520, '3. Solo es útil en el cribado poblacional general.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36532, 12520, '4. Debe solicitarse de rutina en todos los pacientes con serología positiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36533, 12521, '1. Pénfigo vulgar – Anticuerpos antidesmogleina 3.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36534, 12521, '2. Bloqueo cardíaco congénito – Anticuerpos anti-Ro y anti-La.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36535, 12521, '3. Miastenia gravis – Anticuerpos anti receptor de la acetilcolina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36536, 12521, '4. Lupus eritematoso neonatal – Anticuerpos anti-Sm.', true, 4);
