INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36538, 12522, '2. Artritis reumatoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36539, 12522, '3. Miastenia gravis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36540, 12522, '4. Diabetes mellitus tipo 1.', false, 4);
