INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36542, 12523, '2. DQ2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36543, 12523, '3. B27.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36544, 12523, '4. B12.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36545, 12524, '1. Interleucina 7 (IL-7).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36546, 12524, '2. Interferón gamma (IFN-γ).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36547, 12524, '3. Factor de necrosis tumoral alfa (TNF-α).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36548, 12524, '4. Factor de crecimiento transformante beta (TGF-β).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36549, 12524, '5. Interleucina 4 (IL-4).', false, 5);
