INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36553, 12525, '4. Deficiencia de ADA.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36554, 12526, '1. Es una enfermedad autosómica recesiva', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36555, 12526, '2. El porcentaje de linfocitos que expresan CD19 o CD20 (linfocitos B) en sangre periférica está dentro de los límites normales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36556, 12526, '3. El nivel de IgG en suero disminuye paulatinamente desde el nacimiento hasta resultar indetectable.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36557, 12526, '4. La expresión de la proteína Btk en monocitos es normal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36558, 12527, '1. Los pacientes presentan niveles elevados de IgM mientras que mantienen niveles normales de IgG e IgA en suero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36559, 12527, '2. Presentan un defecto de la diferenciación de los linfocitos B en la médula ósea con aumento de linfocitos B inmaduros que expresan la cadena mu intracitoplasmática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36560, 12527, '3. Existe un defecto en el proceso de colaboración entre linfocitos T y B necesario para el cambio de isotipo de las inmunoglobulinas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36561, 12527, '4. Existe un defecto en el proceso de reordenamiento de los genes V de las inmunoglobulinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36562, 12528, '1. Está ligado al cromosoma X, por lo que el síndrome APS-1 también se conoce como IPEX (Inmunodesregulación, Poliendocrinopatía y Enteropatía ligada al cromosoma X).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36563, 12528, '2. Se expresa en los timocitos que no expresan CD4 ni CD8 (doble negativos) promoviendo su expansión y participando en el proceso de selección positiva en el timo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36564, 12528, '3. Se expresa en las células T reguladoras controlando su función y siendo responsable del proceso de tolerancia periférica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36691, 12556, '5. Interleukina-10.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36565, 12528, '4. Se expresa en células epiteliales de la médula tímica regulando la expresión antígenos específicos de otros tejidos y participando en el proceso de selección negativa en el timo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36566, 12529, '1. Agammaglobulinemia de Bruton.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36567, 12529, '2. Inmunodeficiencia común variable.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36568, 12529, '3. Deficiencia del receptor de interferon gamma (IFN-gamma RI, IFN-gamma RII).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36569, 12529, '4. Síndrome de Wiskott-Aldrich.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36570, 12530, '1. Deficiencia de adherencia leucocitaria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36571, 12530, '2. Inmunodeficiencia común variable.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36572, 12530, '3. Deficiencia de mieloperoxidasa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36573, 12530, '4. Enfermedad granulomatosa crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36574, 12531, '1. Se debe sospechar una agammaglobulinemia ligada al cromosoma X y se debe solicitar urgentemente la cuantificación de los linfocitos B circulantes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36575, 12531, '2. Se trata de una infección respiratoria típica de la época del año, que requiere tratamiento antibiótico sin necesidad de realizar pruebas adicionales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36576, 12531, '3. Se debe sospechar una inmunodeficiencia común variable y se debe solicitar la capacidad de producción de anticuerpos mediante ensayos funcionales in vitro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36577, 12531, '4. Se debe sospechar una inmunodeficiencia severa combinada y solicitar la cuantificación de las subpoblaciones linfocitarias T, B y NK.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36578, 12532, '1. Se hereda siguiendo un patrón de herencia autosómico recesivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36579, 12532, '2. Se debe a una deficiencia cuantitativa de la proteína C1-inhibidor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36580, 12532, '3. Se caracteriza por brotes repetitivos y autolimitados de angioedema, que pueden poner en riesgo la vida del paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36581, 12532, '4. Es el déficit hereditario de complemento más frecuente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36582, 12533, '1. Iniciar rápidamente tratamiento inmunosupresor y tipaje HLA para la búsqueda de donante (trasplante de progenitores hematopoyéticos).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36583, 12533, '2. Tratamiento biológico con Daclizumab (anti-CD25) como única terapia hasta obtener el diagnóstico molecular de la enfermedad', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36584, 12533, '3. Tratamiento sintomático y de soporte (transfusión de hematíes y plaquetas) y evitar cualquier fármaco inmunosupresor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36585, 12533, '4. Antibioterapia de amplio espectro vía iv para el tratamiento de un eventual microorganismo desencadenante del cuadro de hemofagocitosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36586, 12533, '5. Tratamiento con gammaglobulinas intravenosas, a mantener de por vida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36587, 12534, '1. Recuento de inmunoglobulinas séricas y test de capacidad de producción de anticuerpos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36588, 12534, '2. Test de fagocitosis y metabolismo oxidativo de los neutrófilos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36589, 12534, '3. Test de apoptosis (muerte celular programada) en los linfocitos circulantes del paciente', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36590, 12534, '4. Estudio del repertorio y clonalidad de los linfocitos T (alfa/beta).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36591, 12534, '5. En este paciente no procedería solicitar estudio inmunológico alguno.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36592, 12535, '1. Síndrome de inmunodeficiencia variable común.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36593, 12535, '2. Síndrome de inmunodeficiencia combinada severa por defecto en CD45.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36594, 12535, '3. Síndrome de inmunodeficiencia combinada severa por defecto en la enzima purina nucleósido fosforilasa (PNP).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36595, 12535, '4. Síndrome linfoproliferativo ligado a X / (síndrome de Duncan / Purtilo).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36596, 12535, '5. Síndrome de hiper-IgM ligado al sexo, por defecto en el ligando de CD40.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36597, 12536, '1. Un síndrome de Chediak-Higashi con expresión incompleta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36598, 12536, '2. Una deficiencia congénita de la molécula CD4 con presentación en la edad adulta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36599, 12536, '3. Una enfermedad granulomatosa crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36600, 12536, '4. Una deficiencia de moléculas de adhesión leucocitaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36601, 12536, '5. Un cuadro de inmunodeficiencia secundaria.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36602, 12537, '1. Terapia sustitutiva con inmunoglobulina intravenosa (IVIG).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36603, 12537, '2. IL-2 en perfusión intravenosa continua.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36604, 12537, '3. Administración de anti-TNF-alfa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36605, 12537, '4. Administración de IFN-beta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36606, 12537, '5. Trasplante de progenitores hematopoyéticos (TMO).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36607, 12538, '1. Agammaglobulinemia ligada al cromosoma X.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36608, 12538, '2. Enfermedad granulomatosa crónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36609, 12538, '3. Síndrome variable común de inmunodeficiencia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36610, 12538, '4. Infección por VIH.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36611, 12538, '5. Síndrome de Hiper-IgM.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36612, 12539, '1. La proteína CD4 de la superficie de las células T es el receptor para el virus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36613, 12539, '2. Los pacientes infectados por el virus producen anticuerpos frente a las glicoproteínas (gp 120 y gp 41) de la envuelta y el antígeno interno grupo específico (p24).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36614, 12539, '3. La prueba de Western blot es más específica que el ELISA para diagnosticar la infección por el virus.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36615, 12539, '4. Un problema importante para estudiar los anticuerpos frente al VIH es su reactividad cruzada con el virus linfotrópico I de células T humanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36616, 12539, '5. Existe una importante diversidad antigénica en las glicoproteínas de la envoltura del VIH.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36617, 12540, '1. Cultivo mixto de linfocitos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36618, 12540, '2. Nefelometría cinética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36619, 12540, '3. Respuesta a mitógenos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36620, 12540, '4. Microscopía electrónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36621, 12540, '5. Citofluorometría de flujo.', true, 5);
