INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36625, 12541, '4. Enfermedad renal diabética.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36626, 12542, '1. El rechazo agudo mediado por linfocitos T puede ser controlado mediante el uso de fármacos como la ciclosporina A o los corticoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36627, 12542, '2. La presencia en el receptor de anticuerpos específicos contra el donante (DSA) previa al trasplante es una contraindicación para el mismo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36692, 12557, '1. Neutrófilos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36628, 12542, '3. El rechazo crónico o lesión crónica del injerto se asocia al daño del endotelio mediado por anticuerpos anti-HLA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36629, 12542, '4. El rechazo hiperagudo es mediado por linfocitos T citotóxicos contra antígenos del donante presentes en el receptor.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36630, 12543, '1. Iniciar rápidamente tratamiento inmunosupresor y tipaje HLA para la búsqueda de donante (trasplante de progenitores hematopoyéticos).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36631, 12543, '2. Tratamiento biológico con Daclizumab (anti-CD25) como única terapia hasta obtener el diagnóstico molecular de la enfermedad', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36632, 12543, '3. Tratamiento sintomático y de soporte (transfusión de hematíes y plaquetas) y evitar cualquier fármaco inmunosupresor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36633, 12543, '4. Antibioterapia de amplio espectro via iv para el tratamiento de un eventual microorganismo desencadenante del cuadro de hemofagocitosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36634, 12543, '5. Tratamiento con gammaglobulinas intravenosas, a mantener de por vida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36635, 12544, '1. Prevención en el rechazo de injertos alogénicos o histoincompatibles.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36636, 12544, '2. Inducción de inmunidad específica frente a infecciones virales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36637, 12544, '3. Generación de células citotóxicas o asesinas naturales (NK, Natural Killer).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36638, 12544, '4. Inducción de inmunidad específica contra bacterias intracelulares.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36639, 12544, '5. Prevención de inmunodeficiencias adquiridas e innatas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36640, 12545, '1. Ciclofosfamida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36641, 12545, '2. Sirolimus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36642, 12545, '3. Azatioprina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36643, 12545, '4. Micofenolato mofetilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36644, 12545, '5. Ciclosporina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36645, 12546, '1. Histoplasma capsulatum.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36646, 12546, '2. Mycobacterium tuberculosis (Bacilo de Koch).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36647, 12546, '3. Virus de la varicela – zoster.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36648, 12546, '4. Streptococcus pneumoniae (neumococo).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36649, 12546, '5. Pneumocystis jiroveci.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36650, 12547, '1. Los linfocitos T-CD4 del receptor pueden reconocer las moléculas HLA-II alogénicas expresadas en las células presentadoras de antígeno del donante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36651, 12547, '2. Los linfocitos T-CD4 del receptor pueden reconocer fragmentos de moléculas HLA-II y HLA-I alogénicas expresadas en las células presentadoras de antígeno del receptor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36652, 12547, '3. El rechazo hiperagudo se debe a la presencia de anticuerpos en el receptor (formados previamente) que frecuentemente van dirigidos contra moléculas HLA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36653, 12547, '4. En el trasplante hepático el rechazo hiperagudo es infrecuente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36654, 12547, '5. A menor expresión de moléculas B7 sobre las células presentadoras de antígeno del donante, mayor es la tasa de rechazo agudo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36655, 12548, '1. Secuenciación masiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36656, 12548, '2. Inmunohistoquímica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36657, 12548, '3. Western blot.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36658, 12548, '4. Hibridación in situ (FISH).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36659, 12549, '1. Se considera una complicación tardía que suele presentarse a las 2-3 semanas de recibir el tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36660, 12549, '2. Se produce por un incremento suprafisiológico de algunas citosinas tales como la interleucina 6 (IL-6) e interleucina 1 (IL-1).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36661, 12549, '3. Las manifestaciones clínicas características incluyen fiebre e hipertensión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36662, 12549, '4. El tozilizumab se utiliza de forma excepcional para su tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36663, 12550, '1. PD-1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36664, 12550, '2. PD-L1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36665, 12550, '3. CTLA-4.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36666, 12550, '4. HER2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36667, 12551, '1. La inoculación intratumoral de células T reguladoras específicas frente a antígenos tumorales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36668, 12551, '2. La inoculación de células de la inmunidad innata con capacidad antitumoral como las células reguladoras de origen mieloide (myeloid-derived suppressor cells, MDSC).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36669, 12551, '3. El uso de citocinas como el TGF-beta o la IL-10 que frenan el crecimiento tumoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36670, 12551, '4. El uso de anticuerpos monoclonales inmunomoduladores frente a PD-1 o los ligandos de PD-1.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36671, 12552, '1. Se consideran marcadores de buen pronóstico en el desarrollo del tumor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36672, 12552, '2. Contribuyen a la defensa inmune antitumoral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36673, 12552, '3. Producen interferón gamma que contribuye a la activación de linfocitos citotóxicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36674, 12552, '4. Producen interleucina-10 que contribuye a un microambiente tumoral inmunosupresor.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36675, 12553, '1. El elemento de reconocimiento del receptor CAR está basado en fragmentos variables de anticuerpos anti-CD19 (single-chain variable fragments, scFvs).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36676, 12553, '2. El receptor CAR posee un dominio intracelular responsable de la transmisión de señales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36677, 12553, '3. Entre los efectos secundarios graves de este tratamiento se encuentra el síndrome de liberación de citocinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36678, 12553, '4. El reconocimiento del antígeno por el receptor CAR depende de las moléculas de histocompatibilidad (HLA) clase I en la célula tumoral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36679, 12554, '1. La molécula PD-1 es un receptor inhibidor de los linfocitos T que se expresa mayoritariamente en linfocitos T naive.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36680, 12554, '2. La interacción de PD-1 y sus ligandos inhibe la activación de los linfocitos T en los ganglios linfáticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36681, 12554, '3. El bloqueo de PD-1 o de sus ligandos potencia la capacidad antitumoral de los linfocitos T CD8+.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36682, 12554, '4. El uso de este tipo de inmunoterapia no se debe combinar con tratamientos de quimioterapia', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36683, 12555, '1. Está aprobada para el tratamiento de leucemia mieloblástica aguda refractaria o en recaída.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36684, 12555, '2. Un efecto secundario grave de esta terapia es el síndrome de liberación de citoquinas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36685, 12555, '3. El receptor CAR reconoce CD19 de forma restringida por el HLA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36686, 12555, '4. Se asocia a hipergammaglobulinemia permanente por activación crónica de linfocitos B CD19+.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36687, 12556, '1. Enzima tirosina kinasa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36688, 12556, '2. Factor de necrosis tumoral alfa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36689, 12556, '3. Interleukina-1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36690, 12556, '4. Proteína CTLA-4.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36694, 12557, '3. Eosinófilos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36695, 12557, '4. Mastocitos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36696, 12558, '1. Es una forma de inmunización activa cuyo resultado depende de la activación de linfocitos memoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36697, 12558, '2. Está indicado en pacientes inmunodeprimidos, como los pacientes con trasplante de órganos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36698, 12558, '3. Confiere protección durante un período de tiempo aproximado de dos años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36699, 12558, '4. Induce memoria inmunológica basada en la activación de linfocitos B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36700, 12559, '1. Tratamiento sustitutivo en inmunodeficiencias humorales (defecto en la formación de anticuerpos).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36701, 12559, '2. Prevención de la gammapatía monoclonal de significado incierto (MGUS).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36702, 12559, '3. Tratamiento del síndrome de Kawasaki.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36703, 12559, '4. Manejo de patologías neurológicas inflamatoria/autoinmune (Sd. Guillain-Barré. esclerosis múltiple).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36704, 12559, '5. Manejo terapéutico de la púrpura trombopénica inmune (PTI).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36705, 12560, '1. Sarcoidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36706, 12560, '2. Sepsis de origen pulmonar por bacterias grampositivas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36707, 12560, '3. Histiocitosis de células de Langerhans.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36708, 12560, '4. Tuberculosis pulmonar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36709, 12560, '5. Metástasis de timoma invasivo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36710, 12561, '1. Alergia al veneno de abeja.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36711, 12561, '2. Rechazo cardiaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36712, 12561, '3. Angioedema hereditario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36713, 12561, '4. Púrpura trombocitopénica idiopática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36714, 12561, '5. Osteoartritis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36715, 12562, '1. Las deficiencias de los componentes finales del sistema se manifiestan fundamentalmente por enfermedades de tipo autoinmune debido al depósito de inmunocomplejos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36716, 12562, '2. La deficiencia del componente C2 provoca fundamentalmente infecciones de repetición por bacterias del grupo Neisseria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36717, 12562, '3. El diagnóstico de edema angioneurótico hereditario se establece mediante la cuantificación de los niveles séricos circulantes y/o el estudio de la actividad funcional del C1-inhibidor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36718, 12562, '4. El estudio de la actividad hemolítica total del sistema de complemento no aporta datos de interés en el estudio de las deficiencias de dicho sistema.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36719, 12562, '5. Las infecciones recurrentes por estafilococos y estreptococos son habituales en el déficit del factor H.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36720, 12563, '"1. Los anticuerpos IgG con alta afinidad para antígenos peptidoglucanos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36721, 12563, '2. Los linfocitos TH2 de los ganglios linfáticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36722, 12563, '3. Los linfocitos T citotóxicos (CD3+CD8+).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36723, 12563, '4. Los receptores de tipo ""toll"" (TLR) de los fagocitos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36724, 12563, '5. Las células T de memoria circulantes."', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36725, 12564, '1. Miastenia gravis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36726, 12564, '2. Hipertiroidismo primario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36727, 12564, '3. Penfigo vulgar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36728, 12564, '4. Herpes gestacional.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36729, 12564, '5. Enfermedad celiaca.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36730, 12565, '1. Estudia los genes a nivel molecular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36731, 12565, '2. Está basada en la utilización de la transcriptasa reversa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36732, 12565, '3. Se apoya en el uso de la reacción en cadena de la polimerasa pero de una manera semicuantitativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36733, 12565, '4. Es el análisis de las proteínas y utiliza el espectrómetro de masas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36734, 12565, '5. Analiza la forma de transcripción del ADN al ARN.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36735, 12566, '1. Las únicas caracterizadas son las células madre hematopoyéticas. Se aíslan mediante su molécula de membrana CD34 y sirven para el tratamiento de los tumores hematológicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36736, 12566, '2. Su aislamiento sólo es posible a partir de tejido fetal o del cordón umbilical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36737, 12566, '3. Son células pluripotenciales, son capaces de diferenciarse en distintos tipos de tejido y/o estirpes celulares.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36738, 12566, '4. El proceso para obtenerlas es muy laborioso, dado que no son capaces de crecer en cultivos in vitro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36739, 12566, '5. Es muy difícil su conservación porque no se mantienen vivas en el nitrógeno líquido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36740, 12567, '5. Pacientes diagnosticados de VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36741, 12567, '6. Pacientes candidatos a trasplante hepático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36742, 12567, '7. Pacientes diagnosticados de asplenia anatómica o disfunción esplénica grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36743, 12567, '8. Pacientes diagnosticados de enfermedad hepática crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36744, 12568, '5. Por su perfil de seguridad para el feto, pueden administrarse durante cualquier periodo del embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36745, 12568, '6. Se recomienda retrasar su administración en niños que han recibido recientemente inmunoglobulinas inespecíficas a altas dosis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36746, 12568, '7. Dado que no se trata de virus salvajes, pueden administrarse en niños con inmunosupresión grave.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36747, 12568, '8. Ya no forman parte de los calendarios oficiales de vacunación pediátrica de nuestro país.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36748, 12569, '1. No generan memoria inmunológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36749, 12569, '2. Activan una respuesta inmunitaria T-dependiente (o timo-dependiente).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36750, 12569, '3. No activan el proceso de hipermutación somática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36751, 12569, '4. No inducen cambio de isotipo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36752, 12570, '1. La respuesta no requiere la colaboración de los linfocitos T, al ser un antígeno timoindependiente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36753, 12570, '2. Un elevado porcentaje de pacientes inmunodeprimidos, como aquellos con trasplante de órganos o con inmunodeficiencia, tienen un defecto en la respuesta a esta vacuna.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36754, 12570, '3. Es una forma de inmunización activa cuyo resultado se asocia al cambio de isotipo de los anticuerpos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36755, 12570, '4. Induce memoria inmunológica basada en la activación de linfocitos B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36756, 12571, '1. Está indicada en niños menores de dos años en situación de riesgo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36757, 12571, '2. Induce una respuesta secundaria con altos niveles de IgG específica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36758, 12571, '3. Inducen maduración de la afinidad de los anticuerpos generados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37706, 12785, '3. Propranolol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36759, 12571, '4. No genera memoria inmunológica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36760, 12572, '1. Para que el sistema inmune de la madre produzca anticuerpos de isotipo IgM, específicos contra el patógeno, que permitan que tanto ella como el feto se encuentren inmunizados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36761, 12572, '2. Para que el sistema inmune de la madre produzca anticuerpos de isotipo IgG, específicos contra el patógeno, que permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma pasiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36762, 12572, '3. Para que el sistema inmune del feto produzca anticuerpos de isotipos IgM e IgG, específicos contra el patógeno, que permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma activa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36763, 12572, '4. Para que el sistema inmune de la madre produzca linfocitos T memoria, que atraviesen la placenta y permitan que, tras el nacimiento, el bebé se encuentre inmunizado de forma pasiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36764, 12573, '1. El linfocito B reconoce fragmentos del Polisacárido y presenta fragmentos de éste a las células T.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36765, 12573, '2. El linfocito B reconoce fragmentos del toxoide tetánico y produce Anticuerpos frente al Polisacárido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36766, 12573, '3. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide a las células T y produce Anticuerpos frente al toxoide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36767, 12573, '4. El linfocito B reconoce fragmentos del Polisacárido, presenta fragmentos del toxoide de los linfocitos T y produce Anticuerpos frente al Polisacárido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36768, 12573, '5. El linfocito B reconoce fragmentos del toxoide, presenta fragmentos del toxoide a los linfocitos T y produce Anticuerpos frente al Polisacárido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36769, 12574, '1. Virus vivos y virus inactivados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36770, 12574, '2. Virus y bacterias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36771, 12574, '3. Un antígeno proteico y su adyuvante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36772, 12574, '4. Una proteína y un polisacárido unidos covalentemente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36773, 12574, '5. Un hapteno y su transportador o carrier.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36774, 12575, '1. En el momento actual en España no se recomienda ya la vacunación antipoliomielítica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36775, 12575, '2. En el momento actual en España solo se vacuna frente a la poliomielitis con vacuna atenuada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36776, 12575, '3. En el momento actual en España solo se vacuna frente a la poliomielitis con vacuna inactivada.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36777, 12575, '4. Desde el año 2002 en España no se vacuna frente a la poliomielitis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36778, 12575, '5. En el momento actual en España se vacuna frente a la poliomielitis con un procedimiento secuencial, primero con vacuna inactivada y luego con vacuna atenuada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36779, 12576, '1. En el aparato respiratorio, calcificación de los cartílagos traqueales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36780, 12576, '2. En el sistema nervioso, aumento del tamaño de los surcos interhemisféricos y de los ventrículos cerebrales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36781, 12576, '3. En el aparato cardiovascular, reducción en el número de células marcapaso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36782, 12576, '4. En el sistema nefrourológico, reducción del tejido mesangial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36783, 12577, '1. Los cambios de presión arterial se acompañan de cambios proporcionales en la filtración glomerular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36784, 12577, '2. Se produce vasoconstricción de las arteriolas eferentes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36785, 12577, '3. Aumenta la actividad de los núcleos hipotalámicos supraóptico y paraventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36786, 12577, '4. Aumenta la secreción renal de potasio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36787, 12578, '1. La distribución del líquido entre los compartimentos intracelular y extracelular está determinada sobre todo por el efecto osmótico de los iones más pequeños.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36788, 12578, '2. Alrededor del 80 % de la osmolaridad total del líquido intersticial y del plasma se debe a los iones sodio y cloro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36789, 12578, '3. Alrededor del 50 % de la osmolaridad en el líquido intracelular se debe a los iones calcio.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36790, 12578, '4. Cambios relativamente pequeños en la concentración de solutos no difusibles en el líquido extracelular pueden causar grandes cambios en el volumen celular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36791, 12579, '1. En el asa ascendente de Henle se reabsorbe sodio, sin reabsorber agua.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36792, 12579, '2. En el túbulo colector se reabsorbe un 20 % del sodio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36793, 12579, '3. La mayor reabsorción de sodio se produce en el túbulo distal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36794, 12579, '4. La reabsorción de sodio en el túbulo proximal está mediada por la aldosterona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36795, 12580, '1. Los valores de FG y FSR se mantienen relativamente constantes a pesar de cambios acentuados en la presión arterial sistémica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36796, 12580, '2. Se autorregulan en paralelo, pero en ciertas condiciones es más eficiente la autorregulación del FSR.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36797, 12580, '3. La reducción del cloruro de sodio en la mácula densa dilata las arteriolas aferentes y aumenta la liberación de renina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36798, 12580, '4. La angiotensina II ejerce una acción vasoconstrictora preferente sobre las arteriolas eferentes renales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36799, 12581, '1. Tomografía axial computarizada con contraste intravenoso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36800, 12581, '2. Urografía intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36801, 12581, '3. Resonancia magnética nuclear abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36802, 12581, '4. Ecografía urológica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36803, 12582, '1. Urografía intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36804, 12582, '2. Radiografía simple de abdomen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36805, 12582, '3. Ecografía renal y de vías urinarias.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36806, 12582, '4. Tomografía computarizada de abdomen.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36807, 12583, '1. Angiotensina II contrae preferentemente las arteriolas eferentes en la mayoría de los estados fisiológicos, elevando la presión hidrostática glomerular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36808, 12583, '2. Las arterias aferentes, son especialmente sensibles a la dilatación mediada por Angiotensina II en la mayoría de los estados fisiológicos asociados con la activación del sistema renina-angiotensina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36809, 12583, '3. Las concentraciones de Angiotensina II aumentadas disminuyen la presión hidrostática glomerular, aumentando el flujo sanguíneo renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36810, 12583, '4. Angiotensina II, con su acción de constricción arteriolar, contribuye a la disminución de la reabsorción de sodio y agua.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36811, 12584, '1. Existe riesgo de hemorragia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36812, 12584, '2. La paciente es obesa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36813, 12584, '3. La paciente tiene una HTA mal controlada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36814, 12584, '4. Tiene poca rentabilidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36815, 12585, '1. Los segmentos de asa de Henle reabsorben ClNa con un exceso de agua, un efecto esencial para la excreción de orina con osmolaridad diferente a la del plasma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36816, 12585, '2. La reabsorción del bicarbonato en la nefrona se realiza principalmente en el túbulo contorneado distal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36817, 12585, '3. La excreción urinaria de Na y agua es igual a la suma de la cantidad filtrada a través de los glomérulos y la cantidad reabsorbida por los túbulos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36818, 12585, '4. En condiciones normales el 80% de la glucosa filtrada se reabsorbe en el túbulo contorneado proximal y regresa a la circulación sistémica por los capilares peritubulares.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36819, 12586, '1. Edad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36820, 12586, '2. Talla.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36821, 12586, '3. Sexo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36822, 12586, '4. Raza.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36823, 12587, '1. Adrenalina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36824, 12587, '2. Noradrenalina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36825, 12587, '3. Endotelina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36826, 12587, '4. Angiotensina II.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36827, 12587, '5. Bradicinina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36828, 12588, '1. Aumenta la resistencia en la arteriola aferente glomerular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36829, 12588, '2. Disminuye la resistencia en la arteriola eferente glomerular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36830, 12588, '3. Aumenta la actividad de los nervios simpáticos renales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36831, 12588, '4. Se produce obstrucción de la vía urinaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36832, 12588, '5. Disminuye la concentración de las proteínas plasmáticas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36833, 12589, '1. Túbulo proximal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36834, 12589, '2. Rama descendente del asa de Henle.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36835, 12589, '3. Rama ascendente del asa de Henle.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36836, 12589, '4. Túbulo contorneado distal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36837, 12589, '5. Conducto colector.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36838, 12590, '1. Edad, peso (en Kg), género y creatinina plasmática.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36839, 12590, '2. Edad, etnia, género y creatinina plasmática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36840, 12590, '3. Edad, etnia, peso (en Kg) y creatinina plasmática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36841, 12590, '4. Edad, peso (en Kg), etnia y género.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36842, 12590, '5. Peso (en Kg), edad, superficie corporal y género.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36843, 12591, '1. Un aumento de la osmolaridad plasmática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36844, 12591, '2. Un aumento del volumen de plasma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36845, 12591, '3. Un incremento de la concentración de sodio en plasma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36846, 12591, '4. Un aumento de la presión arterial media.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36847, 12591, '5. Un incremento de la concentración de potasio en plasma.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36848, 12592, '1. La excreción urinaria de proteínas, superior a 3 g/24 horas supone en la práctica, que exista afectación glomerular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36849, 12592, '2. La rara presencia de Proteinuria selectiva (IgG/albumina L <0.1) implica un mal pronóstico en la nefritis de cambios mínimos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36850, 12592, '3. La presencia en la orina de proteínas de bajo peso molecular, de forma aislada, sugiere afectación tubular renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36851, 12592, '4. La microalbuminuria es factor pronóstico de la nefropatía diabética.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36852, 12592, '5. La proteína de Taum-Horsfall se compone de mucroproteínas secretadas por las células tubulares.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36853, 12593, '1. Hiponatremia con osmolalidad sérica baja y osmolalidad urinaria elevada.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36854, 12593, '2. Hiponatremia hipovolémica con concentración urinaria de sodio y osmolalidad en orina elevadas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36855, 12593, '3. Su tratamiento se basa en la restricción hídrica y la administración de fármacos agonistas del receptor de vasopresina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36856, 12593, '4. En la mayoría de los casos se asocia con la administración de fármacos, especialmente antibióticos e inmunosupresores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36857, 12594, '1. Acidosis láctica por metformina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36858, 12594, '2. Diarrea aguda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36859, 12594, '3. Cetoacidosis diabética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36860, 12594, '4. Intoxicación por metanol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36861, 12595, '1. Osmolalidad plasmática >270 mosm/Kg.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36862, 12595, '2. Hipovolemia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36863, 12595, '3. Osmolalidad urinaria >100 moms/Kg.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36864, 12595, '4. Excreción urinaria de sodio reducida con ingesta adecuada de sal y agua.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36865, 12596, '1. Insuficiencia suprarrenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36866, 12596, '2. Polidipsia primaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36867, 12596, '3. Diabetes insípida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36868, 12596, '4. Síndrome de secreción inadecuada de ADH.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36869, 12597, '1. Ninguna, el pH es normal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36870, 12597, '2. Acidosis respiratoria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36871, 12597, '3. Acidosis respiratoria y alcalosis metabólica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36872, 12597, '4. Alcalosis metabólica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36873, 12598, '1. Administración de resinas de intercambio catiónico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36874, 12598, '2. Colocación de un catéter para iniciar diálisis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36875, 12598, '3. Administración de gluconato cálcico endovenoso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36876, 12598, '4. Administración de furosemida oral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36877, 12599, '1. Favorecer el desplazamiento de potasio desde el espacio plasmático al espacio intracelular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36878, 12599, '2. Quelar el potasio circulante para favorecer su eliminación hepática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36879, 12599, '3. Quelar el potasio circulante para favorecer su eliminación renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36880, 12599, '4. Antagonizar la acción del potasio sobre la membrana de la célula miocárdica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36881, 12600, '1. Hiponatremia hipotónica en situación de euvolemia', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36882, 12600, '2. Hiponatremia hipotónica en situación de hipovolemia', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36883, 12600, '3. Hiponatremia isotónica asociada a hiperproteinemia', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36884, 12600, '4. Hiponatremia hipertónica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36885, 12601, '1. Está causada por mutaciones de acuaporina-2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36886, 12601, '2. Es debida a una reducción marcada de los niveles de acuaporina-2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36887, 12601, '3. Responde a dosis bajas de desmopresina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36888, 12601, '4. Los diuréticos tiazídicos y el amiloride están contraindicados en su tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37707, 12785, '4. Flunarizina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36889, 12602, '1. Insuficiencia renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36890, 12602, '2. Cetoacidosis diabética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36891, 12602, '3. Diarrea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36892, 12602, '4. Ayuno prolongado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36893, 12603, '1. El paciente tiene una alcalosis metabólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36894, 12603, '2. Los valores de pCO2 reflejan una acidosis respiratoria compensadora.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36895, 12603, '3. El anión gap es de 17 mmol/L.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36896, 12603, '4. La hipocloremia e hipokalemia se debe a las pérdidas gastrointestinales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36897, 12604, '1. Hiperventilación marcada y acidosis metabólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36898, 12604, '2. Alcalosis respiratoria crónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36899, 12604, '3. Alcalosis respiratoria y acidosis respiratoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36900, 12604, '4. Hiperventilación y alcalosis respiratoria aguda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36901, 12605, '1. Es probable que el tratamiento analgésico le haya adormilado y eso justificaría la acidosis respiratoria por hipoventilación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36902, 12605, '2. La paciente tiene una acidosis metabólica hiperclorémica que se puede explicar por el aporte de volumen.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36903, 12605, '3. Se trata de una acidosis metabólica compensada con una alcalosis respiratoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36904, 12605, '4. El cuadro es compatible con una acidosis metabólica con anión gap alto. Podría tratarse de una acidosis láctica secundaria a mala perfusión tisular por la hipotensión inicial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36905, 12606, '1. Administrar gluconato cálcico al 10% iv.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36906, 12606, '2. Corregir la acidosis metabólica con bicarbonato iv.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36907, 12606, '3. Retirada de fármacos y añadir resinas de intercambio iónico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36908, 12606, '4. Hemodiálisis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36909, 12607, '1. El paciente presenta una acidosis mixta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36910, 12607, '2. Debe descartarse la posibilidad de intoxicación por metanol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36911, 12607, '3. Se trata de una acidosis metabólica por pérdida de bicarbonato. Hay que descartar diarreas o pérdidas renales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36912, 12607, '4. Dada la disminución del bicarbonato, es ineludible su reposición inmediata con el objetivo de alcanzar. en la primera hora, sus valores plasmáticos normales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36913, 12608, '1. Hipoamilasemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36914, 12608, '2. Disminución del bicarbonato sérico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36915, 12608, '3. Hipocloremia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36916, 12608, '4. Hiperpotasemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36917, 12609, '1. Osmolalidad plasmática elevada, natremia alta, osmolalidad urinaria aumentada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36918, 12609, '2. Osmolalidad plasmática baja, natremia alta, osmolalidad urinaria aumentada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36919, 12609, '3. Osmolalidad plasmática elevada, natremia alta, osmolalidad urinaria disminuida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36920, 12609, '4. Osmolalidad plasmática baja, natremia baja, osmolalidad urinaria aumentada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36921, 12610, '1. El pH arterial se regula por la ecuación de Henderson-Hasselbach y es de 7.35-7.45.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36922, 12610, '2. La hipercapnia (aumento de la PaCO2) es consecuencia del aumento de producción de CO2.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36923, 12610, '3. La acidosis metabólica ocurre por aumento de producción endógena de ácidos, acumulación de ácidos y/o pérdida de bicarbonatos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36924, 12610, '4. En los pacientes con acidosis láctica es frecuente encontrar una brecha o diferencia aniónica superior a 12 mmol/L.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36925, 12610, '5. El uso de soluciones alcalinizantes debe reservarse para casos de acidemias graves con ph < 7.20.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36926, 12611, '1. Insulina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36927, 12611, '2. Potasio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36928, 12611, '3. Calcio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36929, 12611, '4. Fósforo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36930, 12611, '5. Magnesio.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36931, 12612, '1. pH 7.30, HCO3 18 mEq/L, Cl 116 mg/dL, porque es característica la acidosis metabólica con anión gaPnormal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36932, 12612, '2. pH 7.46, HCO3 18 mEq/L, Cl 116 mg/dL, porque es característica la alcalosis metabólica hiperclorémica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36933, 12612, '3. pH 7.456, HCO3 18 mEq/L, Cl 100 mg/dL, porque es característica la acidosis metabólica con anión gaPaumentado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36934, 12612, '4. pH 7.46, HCO3 30 mEq/L, Cl 90 mg/dL, porque es característica la alcalosis metabólica con anión gaPnormal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36935, 12612, '5. pH 7.45, HCO3 23 mEq/L, Cl 100 mg/dL, porque es característica la alcalosis metabólica con anión gaPnormal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36936, 12613, '1. Insuficiencia renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36937, 12613, '2. Hiponatremia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36938, 12613, '3. Déficit de aporte de potasio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36939, 12613, '4. Antihipertensivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36940, 12613, '5. Metformina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36941, 12614, '1. Hipercalcemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36942, 12614, '2. Hiperpotasemia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36943, 12614, '3. Hipomagnesemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36944, 12614, '4. Hipocalcemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36945, 12614, '5. Hipernatremia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36946, 12615, '1. El trastorno ácido-base que presenta es una acidosis respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36947, 12615, '2. La compensación para corregir la acidosis no es adecuada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36948, 12615, '3. Con esta exploración descartamos que esté deshidratada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36949, 12615, '4. En ningún caso debemos ponerle bicarbonato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36950, 12615, '5. Tiene una insuficiencia renal aguda de causa prerrenal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36951, 12616, '"1. Los pacientes con SIADH tienen una eliminación de sodio por orina inferior a 40 mEq/litro como consecuencia del reajuste a un nivel más bajo de osmolaridad (""reset osmotat"").', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36952, 12616, '2. El dolor postoperatorio y las enfermedades neuropsiquiátricas son etiologías conocidas del SIADH.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36953, 12616, '3. El SIADH constituye en nuestros días una de las causas más frecuentes de hiponatremia normovolémica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36954, 12616, '4. El SIADH se caracteriza por una hiponatremia hipoosmótica con una osmolaridad urinaria mayor de 100 mosm/kg.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36955, 12616, '5. La paroxetina y la sertralina deben ulizarse con precaución, por ser fármacos causantes de SIADH en algunos pacientes."', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36956, 12617, '1. Suero salino hipertónico (3%), 500 ml + 500ml de glucosado de 5%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36957, 12617, '2. Suero hiposalino (0.45%), 3000 ml.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36958, 12617, '3. Suero glucosado 5%, 1000 ml.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36959, 12617, '4. Hidratación oral con 1 litro de agua.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (36960, 12617, '5. Suero salino isotónico (0.9%), 2000 ml.', false, 5);
