INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37036, 12633, '4. Insuficiencia renal prerrenal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37037, 12634, '1. Es la apertura de la uretra en la cara dorsal del pene que causa un cúmulo de piel a nivel ventral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37038, 12634, '2. Se asocia a diástasis de pubis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37039, 12634, '3. Se asocia a un cúmulo de piel del prepucio a nivel dorsal y fibrosis en la placa uretral distal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37040, 12634, '4. Suele asociarse a otras malformaciones de los genitales externos (p.e. en la delección cromosoma 13q).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37041, 12635, '1. Insuficiencia cardiaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37042, 12635, '2. Síndrome nefrótico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37043, 12635, '3. Glomerulonefritis proliferativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37044, 12635, '4. Insuficiencia hepática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37045, 12635, '5. Insuficiencia renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37046, 12636, '1. Monoterapia con corticoides a 0,5 mg/kg/día con pauta descendente en 3 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37047, 12636, '2. Control de la presión arterial y la proteinuria (añadir un antagonista de los receptores de angiotensina II).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37048, 12636, '3. Rituximab como primera opción y, si no hay respuesta, administrar ciclofosfamida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37049, 12636, '4. Corticoides a altas dosis junto con ciclofosfamida como tratamiento de inducción.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37050, 12637, '1. Glomerulonefritis de cambios mínimos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37051, 12637, '2. Glomerulonefritis membranosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37052, 12637, '3. Glomerulonefritis membranoproliferativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37053, 12637, '4. Glomeroesclerosis focal y segmentaria.', false, 4);
