INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37064, 12640, '3. Glomerulonefritis membranoproliferativa o mesangiocapilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37065, 12640, '4. Glomerulonefritis aguda postinfecciosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37066, 12641, '1. Amiloidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37067, 12641, '2. Nefropatía IgA o enfermedad de Berger.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37068, 12641, '3. Síndrome de Alport.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37069, 12641, '4. Nefropatía con cambios mínimos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37070, 12642, '1. La mayoría de las nefropatías membranosas son de causa idiopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37071, 12642, '2. Lo que mejor predice el pronóstico es la presencia de afectación intersticial y no el daño glomerular (estadios I a IV).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37072, 12642, '3. Los anticuerpos frente al receptor de la fosfolipasa A2 (Anti-PLA2R) suelen ser positivos en las formas idiopáticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37073, 12642, '4. El 90% de los pacientes alcanzan la remisión con corticoides únicamente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37074, 12643, '1. Hematíes dismórficos y/o cilindros hemáticos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37075, 12643, '2. Proteinuria de 1 g/día, con resultado negativo en tira reactiva y con microalbuminuria mayor de 300 mg/24 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37076, 12643, '3. Coexistencia de hematuria con piuria sin bacteriuria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37077, 12643, '4. Coágulos en la orina a simple vista.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37078, 12644, '1. Glomerulonefritis membranosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37079, 12644, '2. Glomerulonefritis de cambios mínimos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37080, 12644, '3. Glomerulonefritis mesangial IgA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37081, 12644, '4. Glomerulonefritis membranoproliferativa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37082, 12645, '1. Enfermedad de cambios mínimos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37083, 12645, '2. Glomeruloesclerosis focal y segmentaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37084, 12645, '3. Nefropatía membranosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37085, 12645, '4. Nefropatía mesangial IgA', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37086, 12646, '1. Glomerulonefritis membranoproliferativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37087, 12646, '2. Nefropatía IgA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37088, 12646, '3. Síndrome de Alport ligado al X.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37089, 12646, '4. Glomerulonefritis aguda postinfecciosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37090, 12647, '1. Para poder diagnosticar la lesión se precisa tinción de rojo congo para excluir una amiloidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37091, 12647, '2. Es una glomerulonefritis segmentaria y focal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37092, 12647, '3. Es una glomeruloesclerosis diabética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37093, 12647, '4. Es una glomerulonefritis membranosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37094, 12648, '1. Sensibilidad a corticoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37095, 12648, '2. Presencia de edemas incapacitantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37096, 12648, '3. Presencia de síndrome nefrítico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37097, 12648, '4. Comienzo entre los 2 y 6 años de vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37098, 12649, '1. Enfermedad de cambios mínimos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37099, 12649, '2. Glomerulosclerosis focal y segmentaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37100, 12649, '3. Nefropatía membranosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37101, 12649, '4. Glomerulonefritis membranoproliferativa tipo I.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37102, 12649, '5. Glomerulonefritis proliferativa mesangial.', false, 5);
