INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37104, 12650, '2. Glomerulonefritis aguda postinfecciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37105, 12650, '3. Glomerulonefritis extracapilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37106, 12650, '4. Glomerulonefritis por cambios mínimos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37107, 12650, '5. Glomerulonefritis membranoproliferativa', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37108, 12651, '1. GNF mesangial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37109, 12651, '2. GNF necrotizante paucinmune.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37110, 12651, '3. GNF proliferativa focal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37111, 12651, '4. GNF proliferativa difusa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37112, 12651, '5. GNF membranosa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37113, 12652, '1. En el 20 al 50 % de los casos existe elevación de la concentración sérica de IgA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37114, 12652, '2. En la biopsia renal son característicos los depósitos mesangiales de IgA.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37115, 12652, '3. Es frecuente la existencia de proteinuria en rango nefrótico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37116, 12652, '4. Se considera una entidad benigna ya que menos de 1/3 de los pacientes evolucionan a insuficiencia renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37117, 12652, '5. La biopsia cutánea permite establecer el diagnóstico hasta en la mitad de los casos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37118, 12653, '1. Se trata de una Nefropatía Ig A con fracaso renal agudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37119, 12653, '2. Estaría indicada la realización de plasmaféresis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37120, 12653, '3. Se trata de una Glomerulonefritis membranosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37121, 12653, '4. El micofenolato mofetilo es el tratamiento inicial de elección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37122, 12653, '5. La afectación glomerular está causada por la presencia de inmunocomplejos circulantes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37123, 12654, '1. Nefropatía de cambios mínimos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37124, 12654, '2. Glomerulonefritis membranosa.', false, 2);
