INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37126, 12654, '4. Glomerulonefritis proliferativa difusa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37127, 12654, '5. Glomeruloesclerosis focal y segmentaria.', false, 5);
