INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37134, 12656, '2. Glomerulonefritis focal y segmentaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37135, 12656, '3. Nefropatía IgA.', false, 3);
