INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37137, 12656, '5. Nefropatía de cambios mínimos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37138, 12657, '1. Glomerulonefritis proliferativa difusa aguda postinfecciosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37139, 12657, '2. Glomerulonefritis rápidamente progresiva de tipo pauciinmune.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37140, 12657, '3. Glomerulonefritis membranoproliferativa tipo II.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37141, 12657, '4. Síndrome de Goodpasture.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37142, 12657, '5. Enfermedad de cambios mínimos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37143, 12658, '1. El tipo histológico más habitual es la hiperplasia mesangial difusa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37144, 12658, '2. El síndrome nefrótico idiopático por lesiones mínimas (síndrome nefrótico de cambios mínimos) es más frecuente en los niños mayores de 8 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37145, 12658, '3. La glomeruloesclerosis segmentaria y focal es la forma histológica que mejor responde al tratamiento con corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37146, 12658, '4. La biopsia renal es necesaria en todos los pacientes, para poder establecer una orientación pronóstica e instaurar el tratamiento adecuado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37147, 12658, '5. La dislipemia y la hipercoagulabilidad sanguínea son manifestaciones clínicas habituales en los pacientes con síndrome nefrótico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37148, 12659, '1. Depósito mesangial de IgA-IgG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37149, 12659, '2. Depósito intracapilar de crioglobulinas mixtas tipo II.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37150, 12659, '3. Depósito lineal de IgG.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37151, 12659, '4. Es negativa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37152, 12659, '5. Depósitos subepiteliales de inmunoglobulinas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37153, 12660, '1. Es un síndrome caracterizado por una pérdida progresiva y rápida de la función renal asociada a una glomerulonefritis mesangial y daño tubulo-intersticial', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37154, 12660, '2. Es un síndrome que cursa con pérdida progresiva y rápida de la función renal cuya principal característica es la presencia de semilunas en la biopsia renal', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37155, 12660, '3. Es un síndrome que afecta a las arterias renales con presencia de microtrombos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37156, 12660, '4. Es un síndrome cuya principal característica es la afectación glomerular con depósitos masivos de inmunocomplejos en arterias y glomérulos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37157, 12660, '5. Es un síndrome asociado a la presencia de anticuerpos antimembrana basal glomerular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37158, 12661, '1. Una estenosis de la arteria renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37159, 12661, '2. Una glomerulonefritis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37160, 12661, '3. Una glomerulonefritis membranosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37161, 12661, '4. Un riñón ópticamente normal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37162, 12661, '5. Una glomerulonefritis membranoproliferativa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37163, 12662, '1. Radiología de tórax.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37164, 12662, '2. Determinación de siderocitos en esputo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37165, 12662, '3. Determinación de ANCAS y anticuerpos antimembrana basal glomerular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37166, 12662, '4. Realización de biopsia renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37167, 12662, '5. Determinación de proteinuria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37168, 12663, '1. Glomerulonefritis membranosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37169, 12663, '2. Insuficiencia renal prerrenal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37170, 12663, '3. Glomerulonefritis extracapilar con vasculitis necrosante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37171, 12663, '4. Glomerulonefritis proliferativa difusa endocapilar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37172, 12663, '5. Hialinosis segmentaria y focal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37173, 12664, '1. Afectación difusa de penachos glomerulares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37174, 12664, '2. Infiltración glomerular por neutrófilos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37175, 12664, '3. Proliferación de células endoteliales y mesangiales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37176, 12664, '4. Depósitos mesangiales de IgA.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37177, 12664, '5. Depósitos subepiteliales de material electro- denso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37178, 12665, '1. Nefritis en el seno de infección meningocócica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37179, 12665, '2. Glomerulonefritis mesangiocapilar secundaria a crioglobulinemia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37180, 12665, '3. Glomerulonefritis mesangial con depósitos de IgA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37181, 12665, '4. Glomerulonefritis membranosa secundaria a VHC.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37182, 12665, '5. Granulomatosis de Wegener.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37183, 12666, '1. No hacer modificaciones en el tratamiento dada la estabilidad y buen control de su enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37184, 12666, '2. Añadir un antagonista del receptor de la angiotensina II para lograr un mejor control de la presión arterial y disminuir la albuminuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37185, 12666, '3. Indicar la realización de una biopsia renal para confirmar la existencia de una enfermedad renal diabética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37186, 12666, '4. Iniciar tratamiento con un inhibidor del cotransportador de sodio-glucosa tipo 2 que promueve la excreción urinaria de glucosa y tiene un efecto nefroprotector.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37187, 12667, '1. Glomerulonefritis pauciinmune.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37188, 12667, '2. Nefritis tubulointersticial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37189, 12667, '3. Síndrome de Goodpasture.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37190, 12667, '4. Nefropatía IgA.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37191, 12668, '1. Aumento lento de las cifras de creatinina sérica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37192, 12668, '2. Presencia de retinopatía diabética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37193, 12668, '3. Hematuria persistente (micro o macroscópica).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37194, 12668, '4. Cociente albúmina/creatinina en orina > 30 mg/g.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37195, 12669, '1. Nefropatía intersticial aguda por analgésicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37196, 12669, '2. Mieloma múltiple.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37197, 12669, '3. Pielonefritis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37198, 12669, '4. Progresión del aneurisma aórtico con afectación bilateral de las arterias renales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37274, 12686, '3. Test de Coombs, haptoglobina, ferrocinetica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37199, 12670, '1. Estudio de orina de 24 horas para determinación de proteínas y creatinina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37200, 12670, '2. Indicar una ecografía renal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37201, 12670, '3. Iniciar tratamiento con antagonistas del calcio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37202, 12670, '4. Iniciar tratamiento con IECAs.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37203, 12671, '1. Glomerulonefritis postinfecciosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37204, 12671, '2. Vasculitis pauciinmunitaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37205, 12671, '3. Nefropatía IgA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37206, 12671, '4. Síndrome de Goodpasture.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37207, 12672, '1. Filtrado glomerular 45-59 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37208, 12672, '2. Filtrado glomerular 30-44 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37209, 12672, '3. Filtrado glomerular 45-59 ml/min/1,73 m2 y albuminuria 30-300 mg/ml.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37210, 12672, '4. Filtrado glomerular 15-29 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37211, 12673, '1. Depósito tubular de proteínas de Bence-Jones', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37212, 12673, '2. Vasculitis necrotizante', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37213, 12673, '3. Hiperuricemia', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37214, 12673, '4. Acidosis tubular renal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37215, 12674, '1. Una amiloidosis y haría una biopsia de grasa subcutánea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37216, 12674, '2. Un mieloma múltiple y pediría un proteinograma y proteína de Bence Jones en orina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37217, 12674, '3. Una enfermedad glomerular y solicitaría una biopsia renal urgente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37218, 12674, '4. Una necrosis tubular aguda y solicitaría una ecografía renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37219, 12675, '1. Hipertensión arterial mal controlada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37220, 12675, '2. Proteinuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37221, 12675, '3. Hipocalcemia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37222, 12675, '4. Mal control glucémico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37223, 12676, '1. Menos de 30 mg en 24 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37224, 12676, '2. Menos de 300 mg en 24 horas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37225, 12676, '3. Entre 30 y 300 mg/g de creatinina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37226, 12676, '4. Entre 300 y 1000 mg/g de creatinina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37227, 12677, '1. Enfermedad por depósito de cadenas ligeras kappa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37228, 12677, '2. Síndrome nefrótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37229, 12677, '3. Amiloidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37230, 12677, '4. Mieloma IgA con preoteinuria Bence Jones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37231, 12677, '5. Mieloma de cadenas ligeras.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37232, 12678, '1. Iniciar corticoides por sospecha de enfermedad glomerular a cambios mínimos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37233, 12678, '2. Tratarle con ciclofosfamida por sospechar glomerulopatía membranosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37234, 12678, '3. Biopsia de grasa subcutánea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37235, 12678, '4. Iniciar diálisis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37236, 12678, '5. Realizar una prueba de sobrecarga con glucosa para descartar nefropatía diabética.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37237, 12679, '1. Proteinuria de Bence-Jones y tubulopatía con cilindros.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37238, 12679, '2. Amiloidosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37239, 12679, '3. Vasculitis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37240, 12679, '4. Depósitos de cadenas ligeras.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37241, 12679, '5. Hipercalcemia e hiperuricemia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37242, 12680, '1. Nefropatía IgA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37243, 12680, '2. Síndrome de Schoenlein Henoch.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37244, 12680, '3. Glomerulonefritis postinfecciosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37245, 12680, '4. Síndrome de Alport.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37246, 12680, '5. Glomerulonefritis membranosa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37247, 12681, '1. Iniciar tratamiento diurético y con antagonistas de los receptores de la enzima conversora de la angiotensina y mandarla al domicilio para revisarla en consulta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37248, 12681, '2. Realizar biopsia renal y esperar a los resultados para decidir el mejor tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37249, 12681, '3. Iniciar tratamiento con esteroides e inmunosupresores aunque no disponga de biopsia renal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37250, 12681, '4. Incluirla en protocolo de diálisis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37251, 12681, '5. Iniciar tratamiento antibiótico e hidratación intensa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37252, 12682, '1. Crioglobulinemia mixta esencial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37253, 12682, '2. Enfermedades de Waldeströn.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37254, 12682, '3. Sarcoidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37255, 12682, '4. Mieloma múltiple.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37256, 12682, '5. Glomerulonefritis extracapilar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37257, 12683, '1. Suele cursar con insuficiencia renal rápidamente progresiva y hematuria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37258, 12683, '2. La biopsia renal representa el método de elección para el diagnóstico de la nefritis por anticuerpos anti-MBG.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37259, 12683, '3. Los inmunosupresores constituyen el tratamiento de elección, encontrándose contraindicada la plasmaféresis por el riesgo de empeorar la hemorragia pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37260, 12683, '4. La asociación de nefritis por anticuerpos anti-MBG y hemorragia pulmonar constituyen el Síndrome de Goodpasture.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37261, 12683, '5. El trasplante renal se encuentra contraindicado en pacientes con enfermedad renal crónica terminal por enfermedad por anti-MBG, incluso aunque ya no se detecten los anticuerpos en suero.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37262, 12684, '1. La presencia de proteinuria, frecuentemente de rango nefrótico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37263, 12684, '2. La presencia de microhematuria con brotes frecuentes de hematuria macroscópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37264, 12684, '3. Presentarse en el 90% de los casos como Fracaso Renal Agudo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37265, 12684, '4. Desarrollar muy frecuentemente hipertensión arterial maligna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37266, 12684, '5. No evolucionar generalmente hacia la esclerosis renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37267, 12685, '1. La lesión glomerular, idéntica a la de la Nefropatía IgA (enfermedad de Berger), se caracteriza por depósitos de IgA en el mesangioglomerular.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37268, 12685, '2. Es una entidad exquisitamente sensible al tratamiento con corticoides.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37269, 12685, '3. Se detectan Ac anticitoplasma de neutrófilos en 80% de pacientes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37270, 12685, '4. Debe sospecharse en pacientes con hemoptisis e insuficiencia renal aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37271, 12685, '5. La presencia de proteinuria masiva es clave en el diagnóstico de esta enfermedad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37272, 12686, '1. Cuantificación de proteinuria en orina de 24 horas y aclaramiento de creatinina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37273, 12686, '2. Tomografía axial computarizada renal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37275, 12686, '4. C3, C4, ANA, AntiDNA.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37276, 12686, '5. Biopsia renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37277, 12687, '1. Restricción de proteínas en la dieta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37278, 12687, '2. Control glucémico estricto en los diabéticos tipo 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37279, 12687, '3. Control glucémico estricto en los diabéticos tipo 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37280, 12687, '4. Incremento de la presión de perfusión glomerular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37281, 12687, '5. Tratamiento con inhibidores de la enzima conversora de angiotensina, en pacientes con microalbuminuria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37282, 12688, '1. Granulomatosis de Wegener.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37283, 12688, '2. Síndrome de Goodpasture.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37284, 12688, '3. Púrpura de Schonlein Henoch.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37285, 12688, '4. Poliarteritis microscópica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37286, 12688, '5. Lupus eritematoso sistémico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37287, 12689, '1. Hipertensión arterial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37288, 12689, '2. Aumento del filtrado glomerular en fases iniciales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37289, 12689, '3. Hiperreninismo hiperaldosteronémico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37290, 12689, '4. Microalbuminuria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37291, 12689, '5. Necrosis papilar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37292, 12690, '1. Es necesario realizar una biopsia cutánea para establecer el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37293, 12690, '2. Hay que aumentar la dosis de antibiótico pues probablemente se trate de una nefropatía tubulointersticial aguda de etiología infecciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37294, 12690, '3. Se debe suspender el antibiótico y plantear tratamiento con esteroides si la función renal no mejora en 2-3 días.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37295, 12690, '4. Hay que iniciar tratamiento con bolus de esteroides a dosis altas y realizar una biopsia renal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37296, 12691, '1. Toxicidad renal directa del dexketoprofeno y/o omeprazol. Con la suspensión de los fármacos sería suficiente.', false, 1);
