INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37377, 12710, '2. Tiene una nefritis intersticial por enalapril.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37378, 12710, '3. Tiene una estenosis bilateral de las arterias renales y la administración de enalapril ha provocado una caída del FGe por la pérdida de vasoconstricción de la arteriola eferente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37379, 12710, '4. Tiene una insuficiencia renal aguda debida a la crisis hipertensiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37380, 12711, '12. 340 leucocitos (92 % PMN), plaquetas 14.600, urea 183 mg/dl, creatinina 2,3 mg/dl, bilirrubina total 2 mg/dl, transaminasas normales, LDH 2.125 UI, ferritina 1.582 ng/mL, haptoglobina <30 mg/dl. Frotis de sangre periférica con anisocitosis y abundantes microesferocitos y esquistocitos (3-4 por campo) sin agregados plaquetarios. ¿Cuál de los siguentes tratamientos es MENOS apropiado?:', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37381, 12711, '1. Iniciar plasmaféresis con plasma fresco congelado de forma precoz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37382, 12711, '2. Realizar transfusión de hematíes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37383, 12711, '3. Realizar transfusión de plaquetas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37384, 12711, '4. Iniciar tratamiento con corticoides.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37385, 12712, '1. Púrpura trombótica trombocitopénica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37386, 12712, '2. Síndrome hemolítico urémico atípico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37387, 12712, '3. Coagulación intravascular diseminada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37388, 12712, '4. Síndrome hemolítico urémico típico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37389, 12713, '1. Transfundir un concentrado de hematíes, indicarle dieta pobre en sal y en potasio, subir la dosis de valsartán y pedir una angioTC ambulatoriamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37390, 12713, '2. Hacer un electrocardiograma, indicarle dieta pobre en sodio y en potasio, suspender valsartán e hidroclotiazida, indicarle amlodipino y bicarbonato y pedirle un ecodoppler renal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37391, 12713, '3. Hacerle un electrocardiograma, indicarle dieta pobre en sodio y en potasio, subir valsartán y pedirle una TC abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37392, 12713, '4. Bajar urgentemente la presión arterial con captopril sublingual y furosemida, pedir TC urgente y dializar al paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37393, 12714, '1. Trombocitosis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37394, 12714, '2. Insuficiencia renal con microtrombos en capilares glomerulares en la biopsia renal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37395, 12714, '3. Hipertensión arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37396, 12714, '4. Hematuria y proteinuria no nefróticas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37397, 12715, '1. El cuadro se caracteriza por la triada de anemia hemolítica microangiopática no inmune, trombocitopenia y fracaso renal agudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37398, 12715, '2. En algunos casos, dicho síndrome es la consecuencia de una disregulación de la vía alternativa del sistema del complemento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37399, 12715, '3. Se acompaña de anemia hemolítica con test de Coombs positivo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37400, 12715, '4. Los niveles altos de lactato deshidrogenasa (LDH) e indetectables de haptoglobina junto con la presencia de esquistocitos, confirman la presencia de hemólisis intravascular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37401, 12716, '1. Hipertensión arterial maligna.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37402, 12716, '2. Necrosis tubular aguda por contraste.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37403, 12716, '3. Insuficiencia renal rápidamente progresiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37404, 12716, '4. Enfermedad ateroembólica renal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37405, 12716, '5. Estenosis de arteria renal bilateral.', false, 5);
