INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37413, 12718, '3. Estudio de microalbuminuria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37414, 12718, '4. Pruebas de imagen dirigidas al estudio de existencia de patología arterial renal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37415, 12718, '5. Determinación de aldosterona en plasma.', false, 5);
