INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37417, 12719, '2. Enfermedad de Goodpasture.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37418, 12719, '3. Crioglobulinemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37419, 12719, '4. Enfermedad de Wegener.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37420, 12719, '5. PAN microscópica del anciano.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37421, 12720, '1. Neumonía atípica con fracaso renal agudo secundario a necrosis tubular aguda y el tratamiento es la administración de antibióticos de amplio espectro y hemodiálisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37422, 12720, '2. Fracaso renal agudo parenquinatoso de probable origen glomerular con hemorragia alveolar asociada y el tratamiento es inmunosupresores y plasmaféresis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37423, 12720, '3. Síndrome urémico hemolítico atípico y hay que plantear plasmaféresis y administración de eculizumab.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37424, 12720, '4. Fracaso renal agudo funcional secundario a insuficiencia cardíaca y hay que iniciar tratamiento con diuréticos a altas dosis y diálisis si no responde.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37704, 12785, '1. Sumatriptan.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37425, 12721, '1. Analgesia iv y sueroterapia intensiva para forzar diuresis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37426, 12721, '2. Diuréticos intravenosos.', false, 2);
