INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37428, 12721, '4. Solicitar TC ante la sospecha de abdomen agudo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37429, 12722, '1. Nefritis intersticial inmunoalérgica', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37430, 12722, '2. Vasculitis', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37431, 12722, '3. Glomerulonefritis IgA', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37432, 12722, '4. Síndrome hemolítico-urémico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37433, 12723, '1. Transfundir un concentrado de hematíes, indicarle dieta pobre en sal y en potasio, subir la dosis de valsartán y pedir una angioTC ambulatoriamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37434, 12723, '2. Hacer un electrocardiograma, indicarle dieta pobre en sodio y en potasio, suspender valsartán e hidroclotiazida, indicarle amlodipino y bicarbonato y pedirle un ecodoppler renal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37435, 12723, '3. Hacerle un electrocardiograma, indicarle dieta pobre en sodio y en potasio, subir valsartán y pedirle una TC abdominal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37436, 12723, '4. Bajar urgentemente la presión arterial con captopril sublingual y furosemida, pedir TC urgente y dializar al paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37437, 12724, '1. En la necrosis tubular aguda lo característico es encontrar cilindros hialinos, fracción de excreción de Na inferior al 1% (FENa <1%), concentración de sodio en orina inferior a 10 mmol/L (UNa <10 mmol/L) y densidad de orina superior a 1.018.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37438, 12724, '2. En el fracaso renal secundario a exposición reciente a antibióticos o quimioterápicos nefrotóxicos lo característico es encontrar cilindros granulosos o tubulares de células epiteliales de color “pardo lodoso”, FENa >1%, UNa', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37439, 12724, '3. En la enfermedad renal aguda de origen isquémico por hemorragia o hipotensión grave recientes lo característico es encontrar cilindros granulosos o tubulares de células epiteliales de color “pardo lodoso”, FENa >1%, UNa >20 mmol/L, y densidad de orina inferior a 1015.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37440, 12724, '4. En las enfermedades de vasos finos y glomérulos (glomerulonefritis /vasculitis) lo característico es encontrar hematuria con cilindros eritrocíticos, eritrocitos dismórficos, cilindros granulosos y proteinuria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37441, 12725, '1. La nefrotoxicidad por aminoglucósidos se debe a su acción en el túbulo distal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37442, 12725, '2. Los inhibidores del sistema renina angiotensina, IECAs y ARA 2, afectan a los capilares preglomerulares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37443, 12725, '3. La toxicidad renal derivada de mecanismos de hipersensibilidad a fármacos como antibióticos, se manifiesta con afectación túbulointersticial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37444, 12725, '4. Los inhibidores de la calcineurina usados como terapia inmunosupresora del trasplante de órganos, tienen su mecanismo nefrotóxico principal en la vasconstricción.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37445, 12726, '1. Hipotensión, elevación de las cifras de urea y creatinina sérica, osmolaridad en orina inferior a 500 mOsm/kg y excreción fraccional de sodio superior a 1%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37446, 12726, '2. Intolerancia digestiva, elevación de las cifras de urea y creatinina séricas, osmolaridad e orina superior a 500 mOsm/kg y excreción fraccional de sodio inferior a 1%.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37447, 12726, '3. Administración intravenosa previa de contraste iodado, elevación de las cifras de urea y creatinina sérica, osmolaridad en orina inferior a 500 mOsm/kg y excreción fraccional de sodio superior a 1%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37448, 12726, '4. Administración previa de un antibiótico aminoglicósido, elevación de las cifras de urea y creatinina séricas e isostenuria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37449, 12727, '1. Amiloidosis renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37450, 12727, '2. Glomerulonefritis secundaria a la artritis reumatoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37451, 12727, '3. Insuficiencia renal por antiinflamatorios no esteroideos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37452, 12727, '4. Nefritis intersticial por metotrexate.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37453, 12728, '1. La osmolalidad urinaria es superior a 400 mOsm/Kgr.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37454, 12728, '2. El sodio urinario es inferior a 20 mEq/l.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37455, 12728, '3. El índice de fallo renal (IFR) es superior a 1.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37456, 12728, '4. El cociente entre la urea urinaria y la urea plasmática es superior a 10.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37457, 12728, '5. La excreción fraccional de Sodio (EFNa) es inferior al 1 %.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37458, 12729, '1. Niveles de anticomiciales en sangre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37459, 12729, '2. Nivel de creatinkinasa (CPK) en sangre.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37460, 12729, '3. Patrones de citolisis y colostasis hepática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37461, 12729, '4. Hemocultivos seriados y urocultivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37462, 12729, '5. Estudio radiológico vascular, tanto de riñones como de miembro inferior derecho.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37463, 12730, '1. Oliguria con orina concentrada y concentración de sodio alta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37464, 12730, '2. Oliguria con orina isotónica y sodio bajo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37465, 12730, '3. Diuresis conservada con osmolaridad alta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37466, 12730, '4. Oliguria con osmolaridad alta y sodio bajo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37467, 12730, '5. Diuresis conservada con sodio bajo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37468, 12731, '1. Se define como un volumen urinario inferior a 1000 ml/día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37469, 12731, '2. Es un hallazgo constante en la insuficiencia renal aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37470, 12731, '3. Se asocia a dolor lumbar bilateral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37471, 12731, '4. Hace más difícil el manejo conservador del fracaso renal agudo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37472, 12731, '5. Mejora el pronóstico del fracaso renal agudo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37473, 12732, '1. Creatinina plasmática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37474, 12732, '2. Urea plasmática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37475, 12732, '3. Sodio urinario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37476, 12732, '4. Eosinofilia en plasma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37477, 12732, '5. Nivel de C3 en suero.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37478, 12733, '1. Fracción de excreción de sodio menor de 1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37479, 12733, '2. Concentración de sodio urinario menor de 10.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37480, 12733, '3. Una relación entre el nitrógeno ureico urinario y el plasmático mayor de 8.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37481, 12733, '4. Una osmolaridad urinaria menor de 300.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37482, 12733, '5. Una relación entre nitrógeno ureico plasmático y la creatinina mayor de 20.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37483, 12734, '1. Riñones de pequeño tamaño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37484, 12734, '2. Antecedentes familiares de nefropatía.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37485, 12734, '3. niveles elevados de fósforo en sangre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37705, 12785, '2. Topiramato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37486, 12734, '4. Buena diferenciación ecográfica de corteza y médula renales', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37487, 12735, '1. Presenta una enfermedad renal crónica estadio 3 y debe iniciar quelantes de fósforo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37488, 12735, '2. Presenta una enfermedad renal crónica estadio 5 y debe considerarse tratamiento renal sustitutivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37489, 12735, '3. Un buen control glucémico puede revertir la insuficiencia renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37490, 12735, '4. Es poco probable que presente una proteinuria superior a 500mg/24h.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37491, 12736, '1. Filtrado glomerular 45-59 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37492, 12736, '2. Filtrado glomerular 30-44 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37493, 12736, '3. Filtrado glomerular 45-59 ml/min/1,73 m2 y albuminuria 30-300 mg/ml.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37494, 12736, '4. Filtrado glomerular 15-29 ml/min/1,73 m2 y albuminuria < 30 mg/ml.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37495, 12737, '1. Estadio G3b A2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37496, 12737, '2. Estadio G4 A3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37497, 12737, '3. Estadio G3b A3.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37498, 12737, '4. Estadio G4 A2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37499, 12738, '1. La osteopatía adinámica ha aumentado su prevalencia, en particular en ancianos y diabéticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37500, 12738, '2. La enfermedad ósea adinámica es secundaria a la intoxicación por aluminio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37501, 12738, '3. La osteítis fibrosa quística es la lesión clásica del hiperparatiroidismo secundario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37502, 12738, '4. Las concentraciones reducidas de calcitriol contribuyen al hiperparatiroidismo secundario.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37503, 12739, '1. Hiperpotasemia, hipofosforemia, hipercalcemia y acidosis metabólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37504, 12739, '2. Hipopotasemia, hipofosforemia, hipocalcemia y acidosis metabólica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37505, 12739, '3. Hiperpotasemia, hiperfosforemia, hipocalcemia y acidosis metabólica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37506, 12739, '4. Hiperpotasemia, hiperfosforemia, hipocalcemia y alcalosis metabólica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37507, 12740, '1. La hiperfiltración.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37508, 12740, '2. La malnutrición.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37509, 12740, '3. La hiperpotasemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37510, 12740, '4. La acidosis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37511, 12741, '1. Existe riesgo de hemorragia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37512, 12741, '2. La paciente es obesa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37513, 12741, '3. La paciente tiene una HTA mal controlada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37514, 12741, '4. Tiene poca rentabilidad', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37515, 12742, '1. Hipertensión arterial mal controlada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37516, 12742, '2. Proteinuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37517, 12742, '3. Hipocalcemia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37518, 12742, '4. Mal control glucémico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37519, 12743, '1. Paciente diabético con un filtrado glomerular de 46 mL/min y un cociente albumina/creatinina en orina de 25 mg/g.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37520, 12743, '2. Paciente diabético con filtrado glomerular de 89 mL/min y cociente albumina/creatinina en orina de 475 mg/g.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37521, 12743, '3. Paciente hipertenso con filtrado glomerular de 65 mL/min y cociente albumina/creatinina en orina de 150 mg/g.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37522, 12743, '4. Paciente hipertenso de 70 años con 1 quiste simple en cada riñón, filtrado glomerular de 35 mL/min y cociente albumina/creatinina en orina de 10 mg/g.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37523, 12743, '5. Paciente hipertenso de 87 años con filtrado glomerular de 30 mL/min y cociente albumina/creatinina en orina de 5 mg/g.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37524, 12744, '1. Ecocardiograma trastorácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37525, 12744, '2. Gammagrafía pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37526, 12744, '3. AngioTC pulmonar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37527, 12744, '4. Electrocardiograma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37528, 12744, '5. Radiografía de tórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37529, 12745, '1. Requiere presencia persistente de alteraciones estructurales o funcionales del riñón durante al menos 2 meses.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37530, 12745, '2. Incluye alteraciones en orina como proteinuria, independientemente de la tasa de filtración glomerular (TFG).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37531, 12745, '3. Incluye una TFG menor 60 ml/min/1,73m2 de superficie corporal independientemente de la presencia o no de otros marcadores de daño renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37532, 12745, '4. Se clasifica en 5 estadios según la TFG.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37533, 12745, '5. La preparación para la terapia renal sustitutiva se debe hacer en estadio 4.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37534, 12746, '1. Iniciar tratamiento sustitutivo con hemodiálisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37535, 12746, '2. Administrar darbepoetina alfa 0.70 microgramos vía subcutánea cada 2 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37536, 12746, '3. Indicar realización de un aspirado medular para completar el estudio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37537, 12746, '4. Reponer el déficit de hierro y si persiste la anemia iniciar tratamiento con un agente eritropoyético.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37538, 12746, '5. Realizar una endoscopia digestiva para descartar sangrado gastrointestinal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37539, 12747, '1. Hiperfosfaturia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37540, 12747, '2. Calcificaciones vasculares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37541, 12747, '3. Reabsorción subperióstica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37542, 12747, '4. Producto fosfo-cálcico elevado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37543, 12747, '5. Aumento de las fosfatasas alcalinas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37544, 12748, '1. Diabetes mellitus.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37545, 12748, '2. Hipertensión arterial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37546, 12748, '3. Glomerulonefritis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37547, 12748, '4. Riñón quístico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37548, 12748, '5. Infecciones urinarias de repetición.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37549, 12749, '1. La insuficiencia renal crónica no se considera un factor de riesgo de enfermedad cardiovascular isquémica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37550, 12749, '2. La hipertensión arterial sólo empeora la evolución de la nefropatía diabética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37551, 12749, '3. El uso de productos eritropoyéticos exógenos puede aumentar la presión arterial y la necesidad de fármacos antihipertensivos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37552, 12749, '4. La enfermedad cardiovascular no supone una causa frecuente de muerte en pacientes en diálisis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37553, 12749, '5. No se recomienda el tratamiento de la hiperlipemia que acompaña al síndrome nefrótico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37554, 12750, '1. El riñón aumenta la diuresis para mantener el filtrado glomerular normal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37555, 12750, '2. Se ha asociado una alteración en la secreción de ADH.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37556, 12750, '3. El mecanismo de concentración de la orina persiste intacto, aunque esté reducido el filtrado glomerular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37557, 12750, '4. La función renal se ha reducido a la mitad aproximadamente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37558, 12750, '5. Ha aumentado mucho la carga diaria de solutos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37559, 12751, '1. Hiperpotasemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37560, 12751, '2. Imposibilidad de diálisis por falta de acceso vascular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37561, 12751, '3. Sepsis de punto de partida en acceso vascular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37562, 12751, '4. Hemorragias relacionadas con el uso de heparina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37563, 12751, '5. Enfermedad cardiovascular.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37564, 12752, '1. Acidosis metabólica que no responde a tratamiento con bicarbonato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37565, 12752, '2. Sobrecarga de volumen con edema agudo de pulmón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37566, 12752, '3. Hiperpotasemia refractaria a tratamiento médico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37567, 12752, '4. Proteinuria de 1 gramo en la orina de 24 horas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37568, 12753, '1. Rechazo agudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37569, 12753, '2. Uropatía obstructiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37570, 12753, '3. Nefropatía por poliomavirus BK.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37571, 12753, '4. Toxicidad aguda por anticalcineurínicos', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37572, 12754, '1. Renograma isotópico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37573, 12754, '2. Ecografía-doppler.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37574, 12754, '3. Urografía intravenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37575, 12754, '4. Resonancia magnética.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37576, 12755, '1. Compatibilidad de grupo ABO y prueba cruzada negativa (suero del receptor no reacciona frente a linfocitos T del donante).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37577, 12755, '2. Identidad donante-receptor en el antígeno de histocompatibilidad DR.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37578, 12755, '3. Ausencia de anticuerpos citotóxicos en el receptor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37579, 12755, '4. El donante debe tener menos de 65 años de edad', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37580, 12756, '1. El tacrolimus se usa menos que la ciclosporina porque asocia mayor riesgo de diabetes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37581, 12756, '2. El micofenolato mofetil inhibe la síntesis de purinas y puede producir diarrea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37582, 12756, '3. Los esteroides son coadyuvantes de otros inmusupresores, bloquean transcripción de interleucinas y se suelen usar en el rechazo agudo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37583, 12756, '4. Sirolimus suele usarse en combinación con otros y puede causar hiperlipidemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37584, 12757, '1. Tacrolimus, ciclosporina y micofenolato mofetilo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37585, 12757, '2. Tacrolimus, micofenolato mofetilo y glucocorticoides.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37586, 12757, '3. Tacrolimus, sirolimus y micofenolato mofetilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37587, 12757, '4. Tacrolimus, azatioprina y micofenolato mofetilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37588, 12757, '5. Ciclosporina, azatioprina y micofenolato mofetilo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37589, 12758, '1. Infiltrado intersticial de linfocitos B.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37590, 12758, '2. Infiltrado preferentemente de linfocitos T en el intersticio renal y en los túbulos renales.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37591, 12758, '3. Fibrosis y atrofia tubular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37592, 12758, '4. Glomerulonefritis proliferativa sin afectar al intersticio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37593, 12758, '5. Presencia de anticuerpos circulantes antidonante e infartos renales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37594, 12759, '1. Ciclofosfamida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37595, 12759, '2. Sirolimus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37596, 12759, '3. Azatioprina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37597, 12759, '4. Micofenolato mofetilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37598, 12759, '5. Ciclosporina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37599, 12760, '1. Vigilancia estrecha y si aparecen síntomas iniciar tratamiento antibiótico empírico con amoxicilina 7-10 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37600, 12760, '2. Tratamiento empírico con fosfomicina a dosis única de 3 g y, si persiste la bacteriuria, urocultivo para valorar la sensibilidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37601, 12760, '3. Tomar muestra para urocultivo y comenzar de inmediato tratamiento empírico con betalactámicos durante 4-7 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37602, 12760, '4. Ecografía para descartar complicaciones, urocultivo e iniciar tratamiento empírico con nitrofurantoína 5-7 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37603, 12761, '1. Es de causa multifactorial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37604, 12761, '2. Se observa galope S1-S2 y edemas periféricos y pulmonares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37605, 12761, '3. Su presencia empeora notablemente el pronóstico y los síntomas de la insuficiencia cardiaca y dificulta su tratamiento.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37606, 12761, '4. La anemia asociada a la insuficiencia renal puede agravar los síntomas de la insuficiencia cardiaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37607, 12762, '1. Nefropatía cicatricial derecha postpielonefritis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37608, 12762, '2. Estenosis de la unión pieloureteral derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37609, 12762, '3. Pielonefritis aguda derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37610, 12762, '4. Displasia multiquística del riñón derecho.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37611, 12763, '1. Quiste renal / poliquistosis renal autosómica dominante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37612, 12763, '2. Carcinoma renal de células claras / enfermedad de Von Hippel Lindau.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37613, 12763, '3. Angiomiolipoma renal / esclerosis tuberosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37614, 12763, '4. Neurofibroma / neurofibromatosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37615, 12764, '1. Accidente cerebrovascular isquémico secundario a fibrilación auricular, iniciar anticoagulación y antipiréticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37616, 12764, '2. Meningitis bacteriana con complicación isquémica, realizar punción lumbar e iniciar antibiótico dirigido según antibiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37617, 12764, '3. Endocarditis infecciosa con embolia séptica, confirmar con ecocardiograma y tratar con antibiótico dirigido según el antibiograma.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37618, 12764, '4. Neoplasia cerebral con fiebre paraneoplásica, realizar resonancia magnética cerebral y evaluación oncológica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37619, 12765, '1. Es esperable encontrar diplococos grampositivos en el líquido cefalorraquídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37620, 12765, '2. La etiología más probable es el neumococo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37621, 12765, '3. Será necesario hacer quimioprofilaxis en las personas que hayan estado en contacto íntimo con el paciente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37622, 12765, '4. El tratamiento empírico inicial más apropiado es el aciclovir.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37623, 12766, '1. Ceftriaxona más vancomicina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37624, 12766, '2. Cefotaxima más ampicilina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37625, 12766, '3. Moxifloxacino más vancomicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37626, 12766, '4. Meropenem más ampicilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37627, 12767, '1. Hipoglucorraquia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37628, 12767, '2. Bandas oligoclonales positivas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37629, 12767, '3. Aumento del índice de IgG.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37630, 12767, '4. Proteína 14-3-3 positiva.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37631, 12768, '1. Reacción inflamatoria perineuronal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37632, 12768, '2. Cuerpos de inclusión en las neuronas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37633, 12768, '3. Acúmulos de depósitos fibrilares en el intersticio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37634, 12768, '4. Vacuolización del neuropilo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37635, 12769, '1. Esclerosis lateral amiotrófica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37636, 12769, '2. Síndrome de Guillain-Barré.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37637, 12769, '3. Encefalitis herpética.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37638, 12769, '4. Leucoencefalopatía mutifocal progresiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37639, 12769, '5. Enfermedad de Creutzfeld Jakob.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37640, 12770, '1. Está causada por el virus del herpes tipo II.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37641, 12770, '2. Afecta con preferencia los lóbulos occipitales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37642, 12770, '3. Causa un LCR purulento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37643, 12770, '4. El tratamiento de elección es aciclovir.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37644, 12770, '5. La resonancia magnética es diagnóstica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37645, 12771, '1. El cultivo del líquido cefalorraquídeo en una línea celular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37646, 12771, '2. La detección de antígeno de herpes simple 1 y en el LCR.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37647, 12771, '3. Detección de IgG frente al virus del herpes simple 1 y 2 en el LCR por prueba de ELISA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37648, 12771, '4. Detección de antígeno de los virus del herpes simple 1 y 2 en orina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37649, 12771, '5. Prueba de la reacción en cadena de la polimerasa con cebadores específicos para los virus del herpes simple 1 y 2 en una biopsia cerebral o alternativamente en el líquido cefalorraquídeo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37650, 12772, '1. Dolor pulsátil bilateral con fotofobia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37651, 12772, '2. Dolor pulsátil unilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37652, 12772, '3. Dolor opresivo bilateral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37653, 12772, '4. Dolor que empeora con el ejercicio físico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37654, 12773, '1. Albúmina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37655, 12773, '2. Prealbúmina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37656, 12773, '3. Beta 2 transferrina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37657, 12773, '4. Mielina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37658, 12774, '1. La vasculitis sistémica que se sospecha con mayor probabilidad es una vasculitis de gran vaso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37659, 12774, '2. En el análisis, la normalidad de la velocidad de sedimentación globular apoya el diagnóstico de esta vasculitis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37660, 12774, '3. Es frecuente observar afectación de la pared arterial de la aorta y sus ramas principales mediante pruebas de imagen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37661, 12774, '4. Una biopsia de la arteria temporal que muestre un infiltrado inflamatorio en la pared arterial confirmaría el diagnóstico de arteritis de células gigantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37662, 12775, '1. Tratamiento analgésico simple con paracetamol diario, los días que tenga dolor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37663, 12775, '2. Tratamiento con triptanes en el momento agudo de la cefalea los días que sea más intensa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37664, 12775, '3. Tratamiento preventivo de entrada con betabloqueantes tipo propranolol a dosis entre 40-160 mg/d entre 3-6 meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37665, 12775, '4. Tratamiento preventivo de entrada con amitriptilina a dosis bajas entre 25-50 mg/d y mantenerlo entre 3 y 6 meses.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37666, 12776, '1. El tratamiento más efectivo es la descompresión quirúrgica si existe contacto neurovascular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37667, 12776, '2. La carbamazepina sigue siendo el tratamiento de elección.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37668, 12776, '3. Tanto la radiocirugía como los procedimientos ablativos (p.ej. radiofrecuencia) tienen riesgo de recidiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37669, 12776, '4. Es frecuente la pérdida de sensibilidad asociada al dolor.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37670, 12777, '1. Prednisona oral con retirada en 2-3 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37671, 12777, '2. Prednisona oral con retirada en un mes, asociada a verapamilo oral a dosis de 80-180 mg cada 8 horas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37672, 12777, '3. Carbamazepina a dosis de 600-1200 mg al día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37673, 12777, '4. Indometacina a dosis de 50 mg cada 8 horas durante un mes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37674, 12778, '1. Meningitis neoplásica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37675, 12778, '2. Meningitis bacteriana aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37676, 12778, '3. Síndrome de Guillain-Barré.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37677, 12778, '4. Hemorragia subaracnoidea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37678, 12779, '1. Tiene una duración entre 30 y 180 minutos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37679, 12779, '2. Se acompaña de lagrimeo, rinorrea y signo de Horner homolaterales al dolor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37680, 12779, '3. Es más frecuente en mujeres.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37681, 12779, '4. El tratamiento sintomático puede hacerse con oxígeno al 100% por mascarilla.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37682, 12780, '1. Predominio matutino.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37683, 12780, '2. No cambia con esfuerzos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37684, 12780, '3. Fotofobia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37685, 12780, '4. Sonofobia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37686, 12781, '1. Persistencia de dolor en la frente en los periodos intercrisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37687, 12781, '2. Fotofobia que puede ser muy intensa y asociar náuseas y vómitos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37688, 12781, '3. Respuesta del dolor a tratamiento con indometacina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37689, 12781, '4. Mayor frecuencia del dolor en el periodo menstrual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37690, 12782, '1. La meningitis sigue siendo la causa fundamental de su cefalea, pues es el mismo tipo de cefalea que al inicio de los síntomas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37691, 12782, '2. Es una cefalea post-punción lumbar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37692, 12782, '3. Hay que buscar una causa diferente a esta cefalea, pues no es típica del síndrome postpunción lumbar ni de la meningitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37693, 12782, '4. Lo más probable es que no fuera una meningitis viral, sino una hemorragia subaracnoidea. Por este motivo, la cefalea inicial desaparece casi completamente al tumbarse', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37694, 12783, '1. Propranolol.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37695, 12783, '2. Flunaricina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37696, 12783, '3. Carbamacepina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37697, 12783, '4. Topiramato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37698, 12783, '5. Nadolol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37699, 12784, '1. Indometacina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37700, 12784, '2. Lamotrigina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37701, 12784, '3. Verapamilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37702, 12784, '4. Prednisona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37703, 12784, '5. Carbonato de litio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37708, 12785, '5. Ácido Valproico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37709, 12786, '1. La migraña.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37710, 12786, '2. Los trastornos vasculares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37711, 12786, '3. La arteritis de la arteria temporal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37712, 12786, '4. La tensional.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37713, 12786, '5. La oncológica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37714, 12787, '1. Aparición nocturna.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37715, 12787, '2. Presencia de síntomas vegetativos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37716, 12787, '3. Más frecuente en varones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37717, 12787, '4. Puede volverse crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37718, 12787, '5. Duración media del episodio 8 horas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37719, 12788, '1. Neuralgia del trigémino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37720, 12788, '2. Síndrome de Horner secundario a proceso expansivo retroocular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37721, 12788, '3. Migraña complicada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37722, 12788, '4. Arteritis de células gigantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37723, 12788, '5. Cefalea histamínica (en brotes).', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37724, 12789, '1. Esta paciente podría tener un problema urgente con más de un 40% de mortalidad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37725, 12789, '2. En este caso, una TAC craneal sería una radiación no justificada y una mala gestión de los recursos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37726, 12789, '3. Lo más adecuado sería instaurar tratamiento sintomático con analgesia y remitirla a consulta de Neurología.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37727, 12789, '4. Una punción lumbar no aportaría nada porque la paciente está afebril.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37728, 12789, '5. Sólo si tuviera un electrocardiograma normal sería adecuado iniciar tratamiento del dolor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37729, 12790, '1. Hemorragia subaracnoidea traumática occipital.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37730, 12790, '2. Hemorragia causada por una malformación arteriovenosa angiográficamente oculta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37731, 12790, '3. Hemorragia subaracnoidea perimesencefálica con un probable origen venoso o capilar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37732, 12790, '4. Hemorragia causada por una discrasia sanguínea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37733, 12791, '1. Fibrinolisis con alteplasa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37734, 12791, '2. Doble antiagregación y estatinas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37735, 12791, '3. Manejo conservador por los antecedentes del paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37736, 12791, '4. Trombectomía mecánica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37737, 12792, '1. Absceso cerebral secundario a otitis media aguda derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37738, 12792, '2. Trombosis venosa del seno sigmoide derecho.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37739, 12792, '3. Infarto isquémico agudo en territorio de arteria cerebral posterior derecha.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37740, 12792, '4. Neoplasia cerebral de origen', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37741, 12793, '1. Infarto cerebral secundario a consumo de drogas tipo cocaína.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37742, 12793, '2. Hemorragia intraparenquimatosa profunda asociada a hipertensión no diagnosticada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37743, 12793, '3. Hemorragia parietal lobar izquierda asociada a una posible angiopatia amiloide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37744, 12793, '4. Hemorragia intraparenquimatosa asociada a una hemorragia subaracnoidea, por un posible traumatismo craneoencefálico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37745, 12794, '1. Trombectomía mecánica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37746, 12794, '2. Fibrinolisis endovenosa con rTPA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37747, 12794, '3. Fibrinolisis endovenosa y, si no se consigue recanalización, trombectomía mecánica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37748, 12794, '4. Anticoagulación con heparina sódica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37749, 12795, '1. Afasia de Broca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37750, 12795, '2. Afasia de conducción.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37751, 12795, '3. Afasia transcortical sensitiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37752, 12795, '4. Afasia de Wernicke.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37753, 12796, '1. Se encuentra en el momento de la evolución en el que es más frecuente el vasoespasmo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37754, 12796, '2. Probablemente este deterioro progresivo sea secundario al resangrado del aneurisma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37755, 12796, '3. El deterioro subagudo que presenta con mayor probabilidad se debe a hidrocefalia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37756, 12796, '4. La técnica diagnóstica de elección es la angiografía cerebral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37757, 12797, '1. AngioTC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37758, 12797, '2. TC de difusión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37759, 12797, '3. TC de perfusión.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37760, 12797, '4. TC sin contraste.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37761, 12798, '1. Hipertensiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37762, 12798, '2. Angiopatía amiloide.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37763, 12798, '3. Lesión tumoral subyacente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37764, 12798, '4. Malformación arteriovenosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37765, 12799, '1. El vasoespasmo ocurre con mayor frecuencia entre los días 4 y 14 tras la hemorragia subaracnoidea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37766, 12799, '2. Cuanto mayor sea la cuantía del sangrado inicial mayor el riesgo de resangrado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37767, 12799, '3. Se aconseja la restricción hídrica en estos pacientes por el riesgo de hiponatremia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37768, 12799, '4. Es necesario hacer una TC craneal para poder descartar otras complicaciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37769, 12800, '1. Anticoagulación con heparina intravenosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37770, 12800, '2. Fibrinolisis intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37771, 12800, '3. Antiagregación con ácido acetilsalicílico 300 mg.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37772, 12800, '4. Evacuación quirúrgica del hematoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37773, 12801, '1. La imagen no permite determinar el tiempo de isquemia, podrían haber transcurrido sólo unos minutos desde la aparición del déficit.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37774, 12801, '2. No cumple criterios para la administración de tratamiento fibrinolítico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37775, 12801, '3. El ingreso en una unidad de ictus no está indicado en este paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37776, 12801, '4. Ante el tamaño del infarto se debe plantear una craniectomía descompresiva, antes de que aparezca edema cerebral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37777, 12802, '1. 1', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37778, 12802, '2. 2', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37779, 12802, '3. 3', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37780, 12802, '4. 4', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37781, 12803, '1. Un infarto lacunar capsular izquierdo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37782, 12803, '2. Un infarto Silviano cortico-subcortical fronto-temporal izquierdo', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37783, 12803, '3. Un infarto de tronco cerebral', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37784, 12803, '4. Una hemorragia lenticular izquierda', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37785, 12804, '1. 1', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37786, 12804, '2. 2', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37787, 12804, '3. 3', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37788, 12804, '4. 4', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37789, 12805, '1. Desviación de la mirada hacia la izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37790, 12805, '2. Hemiparesia derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37791, 12805, '3. Disartria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37792, 12805, '4. Pupilas arreactivas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37793, 12806, '1. Hematoma cerebeloso > 3 cm de diámetro y deterioro neurológico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37794, 12806, '2. Hemorragia intraventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37795, 12806, '3. Hematoma putaminal en paciente en coma profundo (Glasgow inferior o igual a 8).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37796, 12806, '4. Hematoma lobar y deterioro neurológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37797, 12807, '1. Realizar una videotoracoscopia diagnóstica y terapéutica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37798, 12807, '2. Realizar una toracocentesis diagnóstica.', true, 2);
