INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37826, 12813, '1. Hombre de 73 años de edad con antecedentes de hipertensión arterial, con clínica de hemiparesia derecha y afasia de 2,5 horas de evolución y TC craneal normal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37827, 12813, '2. Hombre de 91 años de edad con antecedentes de demencia tipo Alzheimer y dependiente para la mayoría de las actividades de la vida diaria, con clínica de hemiparesia derecha y afasia de 1 hora y 30 minutos de evolución. En el TC craneal se evidencia discreta atrofia cerebral global.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37828, 12813, '3. Hombre de 37 años de edad sin ningún antecedente de interés con clínica de cefalea, hemiparesia y hemihipoestesia izquierda de 30 minutos de evolución en el que no se puede realizar TC craneal por motivos técnicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37829, 12813, '4. Mujer de 53 años con antecedentes de diabetes mellitus tipo 2 y hemiparesia e hemihipoestesia derecha acompañada de disartria de instauración brusca y que a partir de 1 hora y 50 minutos de inicio de los síntomas inicia una mejoría espontánea del déficit neurológico hasta su total resolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37830, 12813, '5. Hombre de 73 años de edad con antecedentes de hipertensión arterial y con clínica de hemiparesia derecha y afasia de 2.5 horas de evolución y TC craneal con lesión ocupante de espacio que capta contraste en anillo, con edema perilesional y herniación subfacial incipiente.', false, 5);
