INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37836, 12815, '1. La causa más probable es la hipertensión arterial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (37837, 12815, '2. Se trata de una hemorragia lobar secundaria a angiopatía congófila por amiloidosis.', false, 2);
