INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38062, 12864, '1. Presenta un proceso benigno pero que casi siempre recurre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38063, 12864, '2. Debe remitirse a un Centro Hospitalario para realización de una prueba de neuroimagen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38064, 12864, '3. Si el foco causal de la fiebre es claro y banal y la recuperación clínica completa, puede manejarse con antitérmicos y observación domiciliaria sin realizar ninguna prueba complementaria', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38065, 12864, '4. Será necesaria la realización de un EEG más adelante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38066, 12864, '5. Presenta un riesgo de desarrollo posterior de alguna forma de epilepsia mayor que el resto de la población.', false, 5);
