INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38333, 12925, '1. Intoxicación por benzodiazepinas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38334, 12925, '2. Abstinencia de opiáceos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38335, 12925, '3. Intoxicación por cannabis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38336, 12925, '4. Abstinencia de alcohol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38337, 12926, '1. Dolor lancinante de muy corta duración.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38338, 12926, '2. El dolor tiene un punto gatillo, asociándose a la estimulación táctil de la zona afecta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38339, 12926, '3. El dolor puede desaparecer espontáneamente después de persistir semanas o meses.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38340, 12926, '4. Se asocia a hipoestesia de la cara.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38341, 12927, '1. Son comunes inmediatamente después del impacto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38342, 12927, '2. Las lesiones penetrantes y la gravedad de la lesión son factores favorecedores.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38343, 12927, '3. Está indicado el tratamiento anticomicial profiláctico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38344, 12927, '4. Tras un par de años de mayor riesgo los pacientes con lesiones graves tienen el mismo riesgo que la población general.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38345, 12928, '1. El cuadro corresponde a una hemicránea paroxística.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38346, 12928, '2. El tratamiento de elección es la fenitoína.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38556, 12976, '4. Ataxia y temblor cerebelosos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38348, 12928, '4. Puede tratarse con radiocirugía, pero con riesgo de recurrencia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38349, 12929, '1. El diagnóstico más probable es una placa desmielinizante en hemiprotuberancia contralateral, la exploración complementaria más necesaria sería una resonancia magnética craneal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38350, 12929, '2. Los corticoides vía oral son de elección en el tratamiento de la paciente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38351, 12929, '3. Debe ser considerada la fibrinolisis endovenosa si el tiempo de evolución es menor a 3 h.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38352, 12929, '4. Lo más probable es que el cuadro sea irreversible.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38353, 12930, '1. Presenta pupila contraída (en miosis) y conservado el reflejo de acomodación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38354, 12930, '2. Su pupila está contraída (en miosis) y abolido el reflejo de acomodación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38355, 12930, '3. Se encuentra dilatada su pupila (en midriasis) fija y conservado el reflejo de acomodación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38356, 12930, '4. Presenta pupila dilatada (en midriasis) fija y abolido el reflejo de acomodación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38357, 12930, '5. Su pupila no está fija (a veces dilatada y a veces contraída) y el reflejo de la acomodación es normal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38358, 12931, '1. Hipotensión ortostática sin respuesta cronotrópica adecuada.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38359, 12931, '2. Nistagmo horizontal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38360, 12931, '3. Edema de papila.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38361, 12931, '4. Debilidad muscular proximal sin alteraciones sensitivas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38362, 12932, '1. Indicar férula antiequino y fisioterapia por sospecha de compresión del nervio ciático poplíteo externo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38363, 12932, '2. Solicitar electromiograma urgente y dejarlo en reposo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38364, 12932, '3. Realizar punción lumbar por sospecha de complicación por Guillain-Barre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38365, 12932, '4. Solicitar resonancia magnética y pautar, si no está recibiendo, corticoides.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38366, 12933, '1. Espondiloartrosis cervical C5-C6.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38367, 12933, '2. Compresión cubital epitroclear.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38368, 12933, '3. Hernia discal cervical C6-C7.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38369, 12933, '4. Síndrome del túnel carpiano.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38370, 12934, '1. Radiculopatía S1 derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38371, 12934, '2. Mononeuropatía del ciático poplíteo externo derecho.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38372, 12934, '3. Radiculopatía L5 derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38373, 12934, '4. Amiotrofia diabética.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38374, 12935, '1. Síndrome de Guillain-Barré. Confirmar el diagnóstico con pruebas complementarias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38375, 12935, '2. Síndrome postCOVID. Rehabilitación respiratoria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38376, 12935, '3. Miopatía del enfermo crítico. Corticoides y pruebas complementarias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38377, 12935, '4. Miopatía del enfermo crítico. Rehabilitación respiratoria y motora intensivas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38378, 12936, '1. Hiperacusia izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38379, 12936, '2. Hipoestesia de la hemicara izquierda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38380, 12936, '3. Hipogeusia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38381, 12936, '4. Falta de lagrimeo en el ojo izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38382, 12937, '1. El cuadro es compatible con una polirradiculoneuropatía autoinmune.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38383, 12937, '2. En estos cuadros puede aparecer parálisis facial hasta en el 50 % de los casos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38384, 12937, '3. En casos graves estos cuadros pueden asociarse a neuropatía autonómica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38385, 12937, '4. El tratamiento de elección de estos cuadros es la administración de corticosteroides intravenosos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38386, 12938, '1. Ibuprofeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38387, 12938, '2. Oxicodona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38388, 12938, '3. Duloxetina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38389, 12938, '4. Paracetamol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38390, 12939, '1. Miastenia gravis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38391, 12939, '2. Primer brote de esclerosis múltiple.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38392, 12939, '3. Polirradiculopatía desmielinizante inflamatoria aguda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38393, 12939, '4. Dermatomiositis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38394, 12939, '5. Esclerosis lateral amiotrófica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38395, 12940, '1. Parálisis facial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38396, 12940, '2. Alteración de esfínteres.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38397, 12940, '3. Hipo o arreflexia tendinosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38398, 12940, '4. Debilidad muscular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38399, 12940, '5. Disautonomía.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38400, 12941, '1. No hay riesgo, porque el CMT2A es mayoritariamente de herencia recesiva y ambos padres han de ser portadores (la esposa no lo es) para poder transmitirla.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38401, 12941, '2. Al tratarse de un efecto sobre las mitocondrias, la enfermedad únicamente se transmitirá vía materna (herencia materna), por lo que no existe riesgo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38402, 12941, '3. Al tratarse de una enfermedad de herencia autosómico dominante, el riesgo de tener un hijo afecto es del 50%.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38403, 12941, '4. El gen MFN2 está en el cromosoma 1, por lo que todos los hijos varones están exentos de riesgo, en cambio todas sus hijas serán portadoras.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38404, 12941, '5. No hay riesgo, puesto que la enfermedad no ha aparecido en el padre (penetrancia incompleta).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38405, 12942, '1. Sospecharía un síndrome de Guillain-Barré.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38406, 12942, '2. Vigilaría la aparición de complicaciones por neuropatía autónoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38407, 12942, '3. Esperaría encontrar disociación albúmina-citológica a partir de los 10 días desde el inicio del cuadro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38408, 12942, '4. Indicaría tratamiento con Inmunoglobulinas intravenosas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38409, 12942, '5. Los hallazgos neurofisiológicos aparecen antes de que sea evidente la clínica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38410, 12943, '1. Su amplitud depende de la suma temporal de los potenciales de acción en la fibra muscular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38411, 12943, '2. Se origina principalmente por la apertura de receptores nicotínicos para acetilcolina que permiten el flujo de Na⁺ y, en menor cantidad, de K⁺.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38412, 12943, '3. Se genera cuando la acetilcolina activa conductos de Ca²⁺ dependientes de voltaje.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38413, 12943, '4. Se propaga a lo largo de toda la fibra muscular como un potencial de acción independiente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38414, 12944, '1. El nivel de anticuerpos es independiente de la gravedad de la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38415, 12944, '2. En ocasiones se asocia a otra enfermedad autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38416, 12944, '3. Es frecuente la agregación familiar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38417, 12944, '4. La respuesta a inmunosupresores es mayor en pacientes con anticuerpos antirreceptor de acetilcolina y anticuerpos antiMusk positivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38418, 12945, '1. Distrofia oculofaríngea.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38419, 12945, '2. Miopatía mitocondrial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38420, 12945, '3. Miastenia gravis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38421, 12945, '4. Miositis con cuerpos de inclusión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38422, 12946, '1. Dificultad para andar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38423, 12946, '2. Dificultad para subir escaleras.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38424, 12946, '3. Dificultad para abrocharse los botones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38425, 12946, '4. Dolor muscular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38426, 12947, '1. Debe ingresar con medidas de soporte y administración inmediata de antitoxina botulínica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38427, 12947, '2. El síndrome característico consiste inicialmente en la parálisis simétrica de los pares craneales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38428, 12947, '3. Se acompaña de parálisis espástica simétrica ascendente e hiperreflexia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38429, 12947, '4. El periodo de incubación suele ser de 8-36 h tras la ingesta, pero puede ser de hasta 10 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38430, 12948, '1. Miastenia gravis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38431, 12948, '2. Reflujo gastroesofágico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38432, 12948, '3. Tétanos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38433, 12948, '4. Dermatopolimiositis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38434, 12949, '1. Dermatomiositis asociada al autoanticuerpo anti-TIF1-gamma (transcription intermediary factor 1-gamma).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38435, 12949, '2. Miopatía inflamatoria idiopática asociada al autoanticuerpo anti-FHL-1 (Four and a half LIM domains 1).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38436, 12949, '3. Dermatomiositis asociada al autoanticuerpoanti-MDA-5 (melanoma differentiation associated gen 5).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38437, 12949, '4. Miopatía miofibrilar asociada al anticuerpo anti-desmina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38438, 12950, '1. Se transmite con carácter autosómico recesivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38439, 12950, '2. Afecta más frecuentemente a mujeres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38440, 12950, '3. Afecta al músculo pectoral mayor en estadios precoces.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38441, 12950, '4. Acorta significativamente la esperanza de vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38442, 12951, '1. Es una miopatía idiopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38443, 12951, '2. Afecta por igual a hombres y mujeres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38444, 12951, '3. Tiene actualmente un tratamiento curativo basado en administración de glucocorticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38445, 12951, '4. Es una enfermedad hereditaria recesiva ligada al cromosoma X.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38446, 12952, '1. En la Miastenia Gravis, el potencial de acción muscular compuesto inicial producido por la estimulación eléctrica está ligeramente reducido o es normal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38447, 12952, '2. En las polimiositis, distrofias musculares y otras miopatías, los potenciales de unidad motora son de elevada amplitud y de duración aumentada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38448, 12952, '3. En el Síndrome de Eaton Lambert, la estimulación repetitiva a alta frecuencia produce una disminución del potencial de la respuesta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38449, 12952, '4. El fenómeno de la miotonía se caracteriza por descargas repetitivas de baja frecuencia que tienen en general ondas positivas agudas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38450, 12953, '1. La expansión de un trinucleótido en el gen ZNF9.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38451, 12953, '2. La duplicación de regiones concretas del gen CNBP.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38452, 12953, '3. La presencia de mutaciones puntuales en el gen DMPK.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38453, 12953, '4. La expansión de un trinucleótido en el gen DMPK.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38454, 12954, '1. Anticuerpos frente a receptor de acetilcolina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38455, 12954, '2. Anticuerpos frente a canales del calcio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38456, 12954, '3. Anticuerpos antisintetasa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38457, 12954, '4. TSH y anticuerpos antitiroideos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38458, 12955, '1. La debilidad muscular en extremidades es de predominio distal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38459, 12955, '2. Es una enfermedad autosómica recesiva con penetrancia casi completa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38460, 12955, '3. En esta enfermedad son características las cataratas posteriores subcapsulares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38461, 12955, '4. Hay que vigilar la aparición frecuente de bloqueos de conducción cardiaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38462, 12956, '1. Polineuropatía paraneoplásica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38463, 12956, '2. Polimiositis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38464, 12956, '3. Miopatía asociada a alcoholismo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38465, 12956, '4. Síndrome de Eaton-Lambert.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38466, 12957, '1. Distrofia muscular de Duchenne.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38467, 12957, '2. Distrofia miotónica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38468, 12957, '3. Miotonía congénita.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38469, 12957, '4. Polimiositis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38470, 12957, '5. Esclerosis lateral amiotrófica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38471, 12958, '1. Estudio genético de expansión de tripletes de ADN.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38472, 12958, '2. Imagen por resonancia magnética de los diversos grupos musculares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38473, 12958, '3. Potenciales evocados somatosensoriales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38474, 12958, '4. Estudio bioquímico completo que incluya cretincinasas y aldolasas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38475, 12958, '5. Biopsia muscular con estudios inmunohistoquímicos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38476, 12959, '1. Tranquilizar a la enfermera y a la familia, pues el paciente en roncador habitual y está tranquilamente dormido. Se debe colocar en decúbito lateral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38477, 12959, '2. Avisar a cuidados intensivos por sospecha de insuficiencia respiratoria aguda, para valorar posible intubación orotraqueal y ventilación asistida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38478, 12959, '3. Hacer estudio polisomnográfico para descartar apnea del sueño.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38479, 12959, '4. Disminuir la dosis de esteroides, si tiene una miopatía esteroidea mejorará.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38480, 12959, '5. Pedir una TC torácica para descartar timoma compresivo sobre la tráquea asociado a la miastenia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38481, 12960, '1. Los datos confirman la existencia de una afectación postsináptica de la transmisión neuromuscular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38482, 12960, '2. Los datos establecen el diagnóstico de una Distrofia Miotónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38483, 12960, '3. Si en la biopsia muscular se encuentran datos de inflamación puede establecerse el diagnóstico de Polimiositis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38484, 12960, '4. Los datos del electromiograma muestran un patrón de afectación neurógeno crónico que excluye cualquier tipo de miopatía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38557, 12976, '5. Diplopia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38485, 12960, '5. Los datos confirman la existencia de una polineuropatía desmielinizante inflamatoria crónica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38486, 12961, '1. El sexo de la paciente hace improbable un diagnóstico de Miastenia Gravis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38487, 12961, '2. La presencia de lesiones desmielinizantes en la RMN cerebral confirmaría que se trata de Miastenia Gravis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38488, 12961, '3. En pacientes de Miastenia Gravis con afectación ocular limitada, se observa presencia de Ac antirreceptores de acetilcolina en sólo el 50%. Este dato positivo confirmaría el diagnóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38489, 12961, '4. Se trata de un síndrome de Horner y la Rx de tórax mostraría un tumor de Pancoast.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38490, 12961, '5. Los inmunosupresores no han demostrado eficacia en la Miastenia Gravis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38491, 12962, '1. Presencia de bandas oligoclonales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38492, 12962, '2. Pleocitosis leve linfocitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38493, 12962, '3. Hiperproteinorraquia>100 mg/dl.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38494, 12962, '4. Índice IgG elevado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38495, 12963, '1. En la mayoría de los casos, la presentación es entre los 20 y los 40 años y afecta con mayor frecuencia a los hombres que a las mujeres.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38496, 12963, '2. En su etiopatogenia los estudios indican que existe una susceptibilidad poligénica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38497, 12963, '3. El síntoma más frecuente es la alteración de la sensibilidad, en forma de parestesias o acorchamiento de uno o más miembros o del tronco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38498, 12963, '4. La lesión característica es la placa o lesión focal de desmielinización perivenosa, con inflamación y pérdida axonal variables.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38499, 12964, '1. En adolescentes predominan las manifestaciones psiquiátricas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38500, 12964, '2. En algunos casos puede ocurrir tras una infección por virus herpes simple 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38501, 12964, '3. No afecta a niños menores de 1 año de edad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38502, 12964, '4. El diagnóstico se establece al demostrar la presencia de anticuerpos anti-NMDAR en el LCR y el suero.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38503, 12965, '1. Tiene en torno al 85 % de probabilidades de presentar bandas oligoclonales en el líquido cefalorraquídeo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38504, 12965, '2. No necesita pruebas adicionales para establecer el diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38505, 12965, '3. Lo importante es tratar el cuadro y luego ya completaremos el estudio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38506, 12965, '4. Posiblemente se trata de una neuromielitis óptica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38507, 12966, '1. Iniciar tratamiento con inmunoglobulinas intravenosas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38508, 12966, '2. Iniciar tratamiento con corticoides intravenosos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38509, 12966, '3. Iniciar tratamiento con fingolimod.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38510, 12966, '4. Iniciar tratamiento con interferón beta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38511, 12967, '1. Mujer de 36 años que nota descargas eléctricas desde la región cervical a las nalgas al doblar el cuello, con hallazgo exploratorio de piramidalismo en ambas piernas y hemihipoestesia con nivel D1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38512, 12967, '2. Mujer de 22 años con crisis tónico-clónicas generalizadas de reciente comienzo, examen neurológico normal y esclerosis temporal mesial en RM craneal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38513, 12967, '3. Hombre de 42 años con parestesias subagudas ascendentes por ambas piernas y brazos, paraparesia simétrica y arreflexia universal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38514, 12967, '4. Hombre de 54 años con deterioro cognitivo de curso rápidamente progresivo en el que la RM craneal demostró lesiones hiperintensas periventriculares múltiples y lagunas subcorticales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38515, 12968, '1. Bandas oligoclonales en líquido cefalorraquídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38516, 12968, '2. Alteración de potenciales evocados visuales (aumento de latencia de onda P100 en ambos ojos).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38517, 12968, '3. Segundo ataque 3 meses después con afectación de cerebelo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38518, 12968, '4. RM inicial con múltiples (> 8) lesiones periventriculares bilaterales en secuencias T2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38519, 12969, '1. Diplopía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38520, 12969, '2. Alteraciones auditivas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38521, 12969, '3. Alteraciones urinarias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38522, 12969, '4. Depresión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38523, 12970, '1. Parálisis de Bell.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38524, 12970, '2. Síndrome de Ramsay-Hunt (parálisis facial herpética).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38525, 12970, '3. Sarcoidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38526, 12970, '4. Infarto silviano izquierdo con afectación del opérculo rolándico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38527, 12970, '5. Afectación protuberancial por un brote de esclerosis múltiple.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38528, 12971, '1. Múltiples brotes recurrentes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38529, 12971, '2. Mala respuesta a los corticoides en los brotes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38530, 12971, '3. Haber padecido un solo brote de la enfermedad con secuelas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38531, 12971, '4. Tener más de 50 años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38532, 12971, '5. Una forma clínica primaria progresiva.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38533, 12972, '1. Leve elevación de proteínas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38534, 12972, '2. Aumento de inmunologlulinas tipo IgM e IgG.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38535, 12972, '3. Bandas oligoclonales en el LCR y no en el suero.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38536, 12972, '4. Número de linfocitos hasta 100-200 por ml.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38537, 12972, '5. LCR bioquímicamente normal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38538, 12973, '1. Mielopatía vascular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38539, 12973, '2. Esclerosis múltiple primaria progresiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38540, 12973, '3. Mielopatía por déficit de vitamina B12.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38541, 12973, '4. Mielopatía en el contexto de una colagenosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38542, 12973, '5. Neuromielitis óptica (síndrome de Devic).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38543, 12974, '1. Inmunoglobulinas intravenosas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38544, 12974, '2. Vitamina B12 parenteral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38545, 12974, '3. Interferón beta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38546, 12974, '4. Tratamiento sintomático de la espasticidad y de la vejiga neurógena.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38547, 12974, '5. Corticoides intravenosos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38548, 12975, '1. Linfocito T CD4+.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38549, 12975, '2. Linfocito T CD8+.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38550, 12975, '3. Macrófagos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38551, 12975, '4. Linfocitos B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38552, 12975, '5. Basófilos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38553, 12976, '1. Síndrome piramidal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38554, 12976, '2. Hemianopsia homónima.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38555, 12976, '3. Neuritis óptica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38558, 12977, '1. Vasculitis en el marco de una colagenosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38559, 12977, '2. Esclerosis Múltiple.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38560, 12977, '3. Lupus eritematoso sistémico con afectación cerebral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38561, 12977, '4. Patología vascular protrombótica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38562, 12977, '5. Migraña con aura visual.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38563, 12978, '1. Interferón alfa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38564, 12978, '2. Acetato de glatiramer.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38565, 12978, '3. Interferón beta 1-a.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38566, 12978, '4. Mitoxandrona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38567, 12978, '5. Interferón beta 1-b.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38568, 12979, '1. Elevaciones del ácido úrico en plasma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38569, 12979, '2. Bandas oligoclonales en el líquido cefalorraquídeo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38570, 12979, '3. Más de 100 linfocitos por microlitro en el líquido cefalorraquídeo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38571, 12979, '4. Cifras elevadas de ácidos grasos de cadena muy larga en plasma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38572, 12979, '5. Más de 50 polimorfonucleares por microlitro en el líquido cefalorraquídeo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38573, 12980, '1. El cuadro de paraparesia puede ser asimétrico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38574, 12980, '2. La progresión de la enfermedad es lenta, pero puede acelerarse por movimientos de flexión o extensión cervical forzados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38575, 12980, '3. Se trata de una enfermedad primaria de motoneurona.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38576, 12980, '4. La incontinencia urinaria aparece con la progresión de la enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38577, 12981, '1. Debemos buscar una malformación de Chiari.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38578, 12981, '2. En algunos casos se asocia a hidrocefalia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38579, 12981, '3. Se caracteriza por una pérdida de la sensibilidad táctil y vibratoria con preservación de la sensación térmica y dolorosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38580, 12981, '4. Puede producirse tras traumatismos o infecciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38581, 12982, '1. Enfermedad de Alzheimer.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38582, 12982, '2. Demencia frontotemporal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38583, 12982, '3. Enfermedad de Parkinson.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38584, 12982, '4. Parálisis supranuclear progresiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38585, 12983, '1. TC cerebral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38586, 12983, '2. Estudio electromiográfico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38587, 12983, '3. RM cerebral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38588, 12983, '4. Potenciales evocados multimodales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38589, 12984, '1. Parálisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38590, 12984, '2. Amiotrofia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38591, 12984, '3. Fasciculaciones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38592, 12984, '4. Arreflexia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38593, 12984, '5. Hipoestesia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38594, 12985, '1. Mononeuropatía del N. Pero el común derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38595, 12985, '2. Afectación focal de primera motoneurona y probable de segunda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38596, 12985, '3. Afectación hemimedular derecho (Brown-Sequard).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38597, 12985, '4. Mononeuropatía múltiple con afectación de N. Pero el común y tibial posterior derecho.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38598, 12985, '5. Plexopatía lumbar derecha.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38599, 12986, '1. Solicitar un estudio electromiográfico con estimulación repetitiva por la alta sospecha de enfermedad de placa neuromuscular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38600, 12986, '2. Solicitar una bioquímica urgente ante la sospecha de una parálisis hipopotasémica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38601, 12986, '3. Solicitar una arteriografía de columna cervical ante la sospecha de una malformación arterio-venosa cervical.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38602, 12986, '4. Realizar un estudio electromiográfico con estudio de unidades motoras.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38603, 12986, '5. Determinación de anticuerpos antiGM1 ante la alta sospecha de una neuropatía motora multifocal con bloqueos de conducción.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38604, 12987, '1. La encefalitis anti NMDAR es la encefalitis autoinmune más frecuente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38605, 12987, '2. La RM con hiperseñal hipocampal es patognomónica de la enfermedad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38606, 12987, '3. Existe una fuerte asociación con patología tumoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38607, 12987, '4. El pronóstico habitualmente es favorable.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38608, 12988, '1. Radiculopatía cervical.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38609, 12988, '2. Hemiparesia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38610, 12988, '3. Neuropatía de pares craneales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38611, 12988, '4. Encefalopatía por hidrocefalia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38612, 12989, '1. Neurosífilis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38613, 12989, '2. Meningitis fúngica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38614, 12989, '3. Meningitis tuberculosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38615, 12989, '4. Meningitis carcinomatosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38616, 12989, '5. Linfoma del sistema nervioso central.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38617, 12990, '1. Es más frecuente en hombres ancianos con índice de masa corporal (IMC) bajo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38618, 12990, '2. Se caracteriza por aumento de la presión de apertura del LCR con composición anormal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38619, 12990, '3. Afecta preferentemente a mujeres jóvenes obesas y puede causar pérdida visual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38620, 12990, '4. El tratamiento inicial consiste en corticoides a dosis altas y restricción hídrica estricta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38621, 12991, '1. La pérdida de peso no es eficaz en esta situación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38622, 12991, '2. La acetazolamida y la furosemida son fármacos empleados habitualmente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38623, 12991, '3. Se debe realizar una punción lumbar antes de la prueba de imagen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38624, 12991, '4. Los corticoides orales se usan ampliamente en el manejo de esta entidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38625, 12992, '1. Elevar la cabeza del enfermo y mantener la cabeza centrada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38626, 12992, '2. El drenaje de LCR a través de un drenaje lumbar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38627, 12992, '3. La hiperventilación moderada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38628, 12992, '4. Los glucocorticoides en algunas circunstancias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38629, 12993, '1. Agudeza visual disminuida (0,1) en ambos ojos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38630, 12993, '2. Campimetría con aumento de mancha ciega y defectos nasales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38631, 12993, '3. Resonancia Magnética cerebral sin alteraciones significativas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38632, 12993, '4. Composición de líquido cefalorraquídeo dentro de los límites de la normalidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38633, 12994, '1. Ecografía de troncos supraaórticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38634, 12994, '2. Resonancia magnética de cráneo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38635, 12994, '3. Electroencefalograma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38636, 12994, '4. Punción lumbar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38637, 12994, '5. Potenciales evocados visuales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38638, 12995, '1. Mujeres delgadas de 30-40 años de edad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38639, 12995, '2. Hombres obesos de 50-60 años de edad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38640, 12995, '3. Mujeres obesas de 20-40 años de edad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38641, 12995, '4. Mujeres obesas de 60-70 años de edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38642, 12995, '5. Hombres delgados de 30-40 años de edad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38643, 12996, '1. Los 3 principales tipos de tejido linfoide periérico son el bazo, los nódulos linfáticos y el tejido linfoide asociado a la mucosa (MALT).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38644, 12996, '2. Los neutrófilos, eosinófilos y basófilos son llamados en su conjunto linfocitos de respuesta inmune retardada.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38645, 12996, '3. Los mastocitos están especializados en la respuesta inmune contra virus y secretan sustancias que alejan a los eosinófilos y basófilos en lugar de inflamación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38646, 12996, '4. Los linfocitos T maduran en la médula ósea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38647, 12996, '5. Los linfocitos y las líneas mieloides derivan de una célula madre mesenquimal pluripotente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38648, 12997, '1. A su llegada se encuentra en un coma de la escala de Glasgow de 7.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38649, 12997, '2. La presión de perfusión cerebral es la presión arterial media más la presión intracraneal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38650, 12997, '3. El edema cerebral vasogénico se produce por edema celular, rotura de la membrana y muerte celular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38651, 12997, '4. El flujo vascular cerebral aumenta con la hipercapnia y la acidosis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38652, 12998, '1. La lesión no es un hematoma subdural dado que, aunque aparece como un coágulo hiperdenso no presenta la morfología típica ni provoca un mayor desplaza miento horizontal (efecto de masa) del que se esperaría por su tamaño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38653, 12998, '2. La lesión se corresponde con un hematoma epidural agudo en el que la duramadre, firmemente adherida, se desprende de la superficie interna del cráneo, de modo que se forma una hemorragia característica de con tornos lenticulares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38654, 12998, '3. El hematoma subdural avanza por lo general con mayor rapidez y se acompaña con menos frecuencia de lesión cortical subyacente que los hematomas epidurales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38655, 12998, '4. Por lo general, los hematomas epidurales son causados por rotura de la arteria meníngea media después de una fractura del hueso temporal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38656, 12999, '1. Hematoma subdural agudo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38657, 12999, '2. Hematoma epidural.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38658, 12999, '3. Lesión cortical (contusión cerebral).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38659, 12999, '4. Hemorragia intraventricular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38660, 13000, '1. Hematoma subdural agudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38661, 13000, '2. Púrpura trombocitopénica.', false, 2);
