INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38670, 13002, '1. Afectan con más frecuencia la fosa anterior y el peñasco del hueso temporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38671, 13002, '2. La presencia de hematoma periocular o retroauricular debe hacer sospechar su existencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38672, 13002, '3. La ausencia de salida de líquido cefalorraquídeo por nariz u oído excluye la existencia de brecha dural acompañante y, por tanto, el riesgo de meningitis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38673, 13002, '4. El germen más frecuentemente implicado en las meningitis secundarias a brecha dural postraumática es el neumococo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38674, 13002, '5. Un paciente consciente, orientado y sin focalidad neurológica, pero con sospecha de fractura de base debe ser ingresado para observación durante, al menos, 24 horas.', false, 5);
