INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38683, 13005, '1. Las neoplasias secundarias son más infrecuentes que las neoplasias cerebrales primarias, representan sólo el 10% de los pacientes con diagnóstico de tumor cerebral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38684, 13005, '2. Son tumores que típicamente se desarrollan durante la primera y segunda década de la vida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38685, 13005, '3. Las neoplasias que con más frecuencia dan implantes cerebrales son aquellas originadas en el páncreas y en el hígado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38686, 13005, '4. Cuando existen metástasis cerebrales múltiples, el tratamiento quirúrgico para lograr la extirpación completa de todas las lesiones no suele ser una opción posible.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38687, 13006, '1. Son tumores bien definidos y de localización extraaxial, por lo que generalmente son extirpables quirúrgicamente de forma completa y esto puede ser curativo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38688, 13006, '2. Los pacientes diagnosticados de meningioma deben realizarse un estudio genético a la hora de tener descendencia ante la herencia autosómica dominante de estos tumores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38689, 13006, '3. Como son tumores de comportamiento benigno, no es necesario realizar un estudio anatomo-patológico completo puesto que el grado tumoral no influye en el tratamiento a realizar ni en el pronóstico posterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38690, 13006, '4. Las recidivas en estos tumores no dependen del grado tumoral y no son frecuentes.', false, 4);
