INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38906, 13055, '1. A nivel del área 4 de Brodmann de la corteza cerebral del lado derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38907, 13055, '2. En la cápsula interna, brazo posterior del lado derecho.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38908, 13055, '3. En el pedúnculo cerebral izquierdo.', false, 3);
