INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38912, 13056, '2. Afectación focal de primera motoneurona y probable de segunda.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38913, 13056, '3. Afectación hemimedular derecho (Brown-Sequard).', false, 3);
