INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38915, 13056, '5. Plexopatía lumbar derecha.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38916, 13057, '1. Fibras córtico putaminales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38917, 13057, '2. Fibras de las radiaciones talámicas anteriores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38918, 13057, '3. Fibras fronto pónticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38919, 13057, '4. Fibras córtico espinales.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38920, 13057, '5. Fibras córtico nucleares.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38921, 13058, '1. Un infarto de la corteza occipital produce una hemianopsia homónima ipsilateral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38922, 13058, '2. La duración más habitual de la amaurosis fugaz es de entre 45 y 60 minutos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38923, 13058, '3. En la neuritis óptica las pupilas son isocóricas y puede encontrarse un defecto pupilar aferente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38924, 13058, '4. La pérdida de agudeza visual en el edema de papila es muy grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38925, 13058, '5. En las lesiones compresivas del III par (motor ocular común) hay característicamente un respeto de la función pupilar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38926, 13059, '1. Naloxona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38927, 13059, '2. Flumazenilo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38928, 13059, '3. Atropina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38929, 13059, '4. Pralidoxima.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38930, 13060, '1. Aumento de la resistencia constante durante todo el movimiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38931, 13060, '2. Aumento de la resistencia dependiente de la velocidad del movimiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38932, 13060, '3. Disminución del tono con ausencia de resistencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38934, 13061, '1. Se asocia a deficiencia de hipocretina (orexina) en el líquido cefalorraquídeo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38935, 13061, '2. No cursa con cataplejía ni alteraciones del sueño REM.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38936, 13061, '3. Es más frecuente en mujeres y se asocia a exceso de serotonina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38937, 13061, '4. No se relaciona con ningún alelo HLA específico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38938, 13062, '1. Trastorno de la marcha, incontinencia urinaria y deterioro cognitivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38939, 13062, '2. Cefalea, vómitos y rigidez de nuca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38940, 13062, '3. Diplopía, papiledema y tinnitus pulsátil.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38941, 13062, '4. Vómitos, bradicardia y alteración del nivel de conciencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38942, 13063, '1. Enfermedad de Hungtinton.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38943, 13063, '2. Ataxia de Friedreich.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38944, 13063, '3. Síndrome del cromosoma X frágil.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38945, 13063, '4. Distrofia miotónica tipo 1.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38946, 13064, '1. Nistagmo horizontal, unidireccional, que aumenta de intensidad cuando se dirige al lado de la fase rápida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38947, 13064, '2. Nistagmo vertical, unidireccional, que no se suprime con la fijación de la mirada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38948, 13064, '3. Nistagmo horizontal, con componente rotatorio, que cambia de dirección cuando se dirige al lado de la fase lenta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38949, 13064, '4. Nistagmo horizontal, con componente rotatorio que no se suprime con la fijación de la mirada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38950, 13065, '1. RM cerebral con espectroscopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38951, 13065, '2. EEG de larga duración con vídeo-EEG.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38952, 13065, '3. Realizar un ciclo de tratamiento con metilprednisolona a dosis altas para valorar respuesta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38953, 13065, '4. Estudio en LCR y suero', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38954, 13066, '1. Con frecuencia presentan crisis epilépticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38955, 13066, '2. Suelen presentar angiofibromas faciales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38956, 13066, '3. El tumor cerebral más frecuente es el astrocitoma gigantocelular subependimario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38957, 13066, '4. Con frecuencia presentan neurinomas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38958, 13067, '1. Se debe instaurar tratamiento con análogos de prostaglandinas en colirio, porque presenta un glaucoma normotensional con afectación del campo visual.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38959, 13067, '2. Puede tratarse de una ceguera cortical y se debe de realizar un campo visual para valorar una posible hemianopsia homónima con respeto macular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38960, 13067, '3. Como no refiere problemas visuales, presenta una presión intraocular normal y una agudeza visual normal, se trata de despistes normales a su edad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38961, 13067, '4. Presenta un desprendimiento de retina periférico secundario a su miopía que no ha llegado a afectar al polo posterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38962, 13068, '1. Síndrome de leucoencefalopatía posterior reversible.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38963, 13068, '2. Meningitis carcinomatosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38964, 13068, '3. Leucoencefalopatía multifocal progresiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38965, 13068, '4. Toxicidad neurológica por 5-fluoruracilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38966, 13069, '1. La activación exclusiva de neuronas específicas de la nocicepción.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38967, 13069, '2. La convergencia de información cutánea y visceral en neuronas de gama dinámica ancha.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38968, 13069, '3. El bloqueo de substancia P desde las aferencias primarias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38969, 13069, '4. La interrupción de las fibras del tracto espinotalámico lateral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38970, 13069, '5. La separación de la información medular de acuerdo al principio de divergencia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38971, 13070, '1. Corteza sensorial primaria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38972, 13070, '2. Núcleos intralaminares del tálamo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38973, 13070, '3. Sustancia gris periacueductal/periventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38974, 13070, '4. Columnas dorsales de la médula espinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38975, 13070, '5. Estimulación eléctrica transcutánea de aferencias primarias de bajo umbral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38976, 13071, '1. Área motora primaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38977, 13071, '2. Área motora secundaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38978, 13071, '3. Área premotora.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38979, 13071, '4. Área motora suplementaria.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38980, 13071, '5. Área parietal de asociación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38981, 13072, '1. Hipoestesia en la zona malar derecha.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38982, 13072, '2. La duración del dolor es de unos pocos segundos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38983, 13072, '3. Los paroxismos dolorosos pueden desencadenarse al tocar suavemente una zona facial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38984, 13072, '4. El reflejo corneal es normal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38985, 13072, '5. Indicaría tratamiento con carbamazepina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38986, 13073, '1. La zona pelúcida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38987, 13073, '2. El trofoblasto.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38988, 13073, '3. El ectodermo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38989, 13073, '4. El mesodermo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38990, 13073, '5. La línea primitiva.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38991, 13074, '1. La capacitación del espermatozoide', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38992, 13074, '2. Corona radiata', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38993, 13074, '3. La reacción acrosómica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38994, 13074, '4. La reacción cortical y de zona', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38995, 13074, '5. La división celular', false, 5);
