INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38997, 13075, '2. Dexametasona.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38998, 13075, '3. Isotretinoína.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (38999, 13075, '4. Alfa-metildopa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39000, 13076, '1. El embarazo de la madre es una contraindicación para administrar la vacuna contra la varicela a su hijo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39001, 13076, '2. Las vacunas inactivadas suponen un riesgo para el feto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39002, 13076, '3. Están recomendadas las vacunas vivas atenuadas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39003, 13076, '4. Ante una exposición de riesgo, la embarazada puede recibir inmunoglobulinas inespecíficas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39004, 13077, '1. Debe de estimularse ya que es muy conveniente para la Salud Pública.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39005, 13077, '2. Es el procedimiento de elección para el control del síndrome de rubeola congénita.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39006, 13077, '3. No se considera ya como una indicación de aborto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39007, 13077, '4. Es permitida en el caso de las vacunas de la cepa RA 27/3, pero no en el caso de las vacunas de la cepa Cendehill.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44147, 14223, '3. Probenecid.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39008, 13077, '5. Se debe administrar conjuntamente con inmunoglobulina específica', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39009, 13078, '1. Le pautaría una profilaxis con atosibán por vía oral durante todo el embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39010, 13078, '2. Le ofrecería la maduración pulmonar con corticoides a partir de las 19-20 semanas de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39011, 13078, '3. Le recomendaría realizar un cerclaje cervical programado a partir de la semana 14 de gestación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39012, 13078, '4. Le aconsejaría no intentar más embarazos por el alto riesgo de recidiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39013, 13078, '5. Le recomendaría recurrir a las técnicas de reproducción asistida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39014, 13079, '1. Vacuna frente al tétanos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39015, 13079, '2. Vacuna frente al sarampión.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39016, 13079, '3. Vacuna frente a la tos ferina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39017, 13079, '4. Vacuna frente a la hepatitis B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39018, 13079, '5. Vacuna frente a la gripe.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39019, 13080, '1. Contraindicado de forma absoluta por claros riesgos para el feto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39020, 13080, '2. Puede utilizarse, pero limitando su utilización a periodos inferiores a 10 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39021, 13080, '3. Solo puede ser utilizado a partir de las 24 semanas de gestación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39022, 13080, '4. Solo se aconseja su utilización reduciendo la dosis a la mitad de lo habitual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39023, 13080, '5. Puede emplearse con seguridad durante toda la gestación.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39024, 13081, '1. La detección de anticuerpos IgG frente a rubeola es positiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39025, 13081, '2. La detección de anticuerpos IgG frente a rubeola es negativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39026, 13081, '3. La detección de anticuerpos IgG frente a toxoplasma es positiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39027, 13081, '4. La detección de anticuerpos IgG frente a toxoplasma es negativa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39028, 13081, '5. La detección de anticuerpos frente a antígenos no treponémicos es negativa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39029, 13082, '1. Los riesgos teratógenos son mayores en el primer trimestre de gestación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39030, 13082, '2. Los riesgos de parto prematuro son máximos en el tercer trimestre de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39031, 13082, '3. Los anestésicos generales pueden provocar hipoperfusión e hipoxemia fetal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39032, 13082, '4. La hemorragia quirúrgica no influye sobre el bienestar fetal ya que la circulación placentaria tiene autorregulación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39033, 13082, '5. El riesgo de aborto espontáneo asociado a la anestesia es menor durante el segundo trimestre de gestación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39034, 13083, '1. Mayor riesgo de desprendimiento de placenta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39035, 13083, '2. Riesgo de teratogénesis por la cocaína.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39036, 13083, '3. Mayor incidencia de parto postérmino.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39037, 13083, '4. Mayor incidencia de hipertensión materna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39038, 13083, '5. Mayor incidencia de retraso del crecimiento intrauterino y bajo peso al nacer.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39039, 13084, '1. Definir la causa de un sangrado vaginal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39040, 13084, '2. Confirmar la edad gestacional.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39041, 13084, '3. Valorar una sospecha de enfermedad trofoblástica gestacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39042, 13084, '4. Diagnosticar un embarazo en mujer con amenorrea.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39043, 13084, '5. Evaluar un dolor pélvico agudo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39044, 13085, '1. Estudio molecular en los padres.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39045, 13085, '2. Biopsia de corion en la 9a semana.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39046, 13085, '3. Determinación de alfa-fetoproteína en la madre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39047, 13085, '4. Amniocentesis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39048, 13085, '5. Estudio de subpoblaciones de linfocitos en la madre.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39049, 13086, '1. Herencia autosómica recesiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39050, 13086, '2. Mutación de novo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39051, 13086, '3. Penetrancia incompleta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39052, 13086, '4. Mosaicismo germinal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39053, 13087, '1. Valorar estudio genético teniendo en cuenta el riesgo de anomalía cromosómica en primer trimestre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39054, 13087, '2. Valorar si la gestación está correctamente datada según la longitud craneocaudal fetal de la ecografía del primer trimestre.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39055, 13087, '3. Repetir ecografía para nuevas biometrías en 2 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39056, 13087, '4. Estudio para descartar preeclampsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39057, 13088, '1. Necrosis y degeneración de los miomas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39058, 13088, '2. Malposición fetal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39059, 13088, '3. Progresión a leiomiosarcoma.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39060, 13088, '4. Parto pretérmino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39061, 13089, '1. Flufenazina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39062, 13089, '2. Olanzapina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39063, 13089, '3. Litio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39064, 13089, '4. Carbamazepina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39065, 13090, '1. Adelantar la ecografía de la semana 20.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39066, 13090, '2. Realizar una prueba invasiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39067, 13090, '3. Tranquilizarle porque se trata de un riesgo combinado de bajo riesgo en todo caso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39068, 13090, '4. Tranquilizarle porque se trata de un riesgo intermedio y está justificado por la edad materna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39069, 13091, '1. Longitud cráneo-caudal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39070, 13091, '2. Grosor placentario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39071, 13091, '3. Índice de pulsatilidad de las arterias uterinas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39072, 13091, '4. Índice de pulsatilidad de la arteria central de la retina materna.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39073, 13092, '1. El valor de la fracción libre de la gonadotropina coriónica se encuentra disminuido en la trisomía 21.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39074, 13092, '2. Se realiza mediante la combinación de datos analíticos y ecográficos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39075, 13092, '3. Está indicada en el primer trimestre en población gestante de riesgo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39076, 13092, '4. La translucencia nucal debe medirse entre las 11 y 14 semanas, mediante la realización de un corte sagital y con el embrión en posición de hiperflexión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39077, 13093, '1. La ausencia de hueso nasal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39078, 13093, '2. La alteración de la onda del ductus venoso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39079, 13093, '3. La presencia de quistes de plexos coroideos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39080, 13093, '4. La medida de la translucencia nucal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39260, 13133, '1. Trasfusión feto-fetal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39081, 13094, '1. Debemos asumir que la edad gestacional real son 12 semanas, reasignar una nueva FUR (Fecha de última regla) o FPP (Fecha probable de parto) y planificar el resto de los controles del embarazo en base a esta edad gestacional.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39082, 13094, '2. Seguiremos considerando que la edad gestacional real son 10 semanas, ya que coincide con la FUR de la paciente. Planificaremos el resto de los controles en función de esta edad gestacional, aunque dejaremos constancia de esta discordancia en la historia clínica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39083, 13094, '3. Ante esta discordancia, solicitaremos una analítica de sangre para cuantificar la hormona ß-HCG y decidir en función de sus niveles cuál es la edad gestacional real para poder planificar el resto de los controles del embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39084, 13094, '4. Solicitaremos un nuevo control ecográfico en 2 semanas para ver la evolución y diagnosticar con más certeza la edad gestacional correcta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39085, 13095, '1. Sonoluscencia nucal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39086, 13095, '2. Hueso nasal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39087, 13095, '3. Regurgitación tricúspidea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39088, 13095, '4. Quiste del plexo coroideo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39089, 13095, '5. Estudio del flujo en el ductus venoso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39090, 13096, '1. Edad materna de 38 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39091, 13096, '2. Test combinado del primer trimestre positivo alto riesgo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39092, 13096, '3. Triple screening patológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39093, 13096, '4. Presencia de dos marcadores ecográficos secundarios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39094, 13096, '5. Anomalías en la ecografía de alta resolución/3D.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39095, 13097, '1. La inclusión del Doppler de las arterias uterinas (valor del índice de pulsatilidad) en el cribado aumenta la tasa de detección.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39096, 13097, '2. El valor de sflt-1 incluido en el cribado indica mayor riesgo cuando está en concentraciones bajas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39097, 13097, '3. La detección de gestantes con alto riesgo permite prevenir la preeclampsia con ácido acetilsalicílico 150 mg/noche, comenzando el tratamiento a partir de la semana 16.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39098, 13097, '4. Únicamente debe realizarse en centros que dispongan de un ecógrafo de alta resolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39099, 13098, '1. Actitud expectante con antihipertensivos y sulfato de magnesio hasta la mejora de las plaquetas maternas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39100, 13098, '2. Actitud expectante con tratamiento antihipertensivo a domicilio y controles cada 48 h.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39101, 13098, '3. Finalización de la gestación cuando complete la maduración pulmonar fetal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39102, 13098, '4. Finalización inmediata de la gestación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39103, 13099, '1. Se trata de un feto pequeño para la edad gestacional, de origen placentario, que se acompaña de una preeclampsia no grave. La actitud recomendable es intentar prolongar la gestación al menos hasta la semana 37.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39104, 13099, '2. Se trata de un feto pequeño para la edad gestacional que se acompaña de un síndrome de HELLP. La actitud recomendable es intentar prolongar la gestación al menos hasta la semana 35.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39105, 13099, '3. Se trata de un feto con restricción del crecimiento intrauterino que se acompaña de una hipertensión gestacional del tercer trimestre. La actitud recomendable es intentar prolongar la gestación al menos hasta la semana 36.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39106, 13099, '4. Se trata de un feto con restricción del crecimiento intrauterino que se acompaña de un síndrome de HELLP. La actitud recomendable es la finalización del embarazo mediante inducción del parto.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39107, 13100, '1. Hipertensión arterial, proteinuria, edemas generalizados y aumento de peso por retención hídrica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39108, 13100, '2. Anemia hemolítica microangiopática, disfunción hepática y trombocitopenia que puede progresar a coagulación intravascular diseminada, en gestantes con hipertensión arterial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39109, 13100, '3. Anemia hemolítica, hipertensión arterial o elevación de la presión sistólica previa en 20 mm de Hg, proteinuria > 30 mg/dL en orina de 24 horas, elevación de transaminasas hepáticas y bajo nivel de conciencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39110, 13100, '4. Hipertensión arterial en gestantes de más de 20 semanas acompañada de anemia hemolítica, trombocitopenia, dolor epigástrico agudo y bajo nivel de conciencia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39111, 13101, '1. Preeclampsia moderada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39112, 13101, '2. Hipertensión inducida por el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39113, 13101, '3. Hipertensión crónica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39114, 13101, '4. Eclampsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39115, 13102, '1. Curva de glucemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39116, 13102, '2. Flujometría Doppler feto-placentaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39117, 13102, '3. Test de nitracina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39118, 13102, '4. Hematocrito.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39119, 13102, '5. Valoración cervical ecográfica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39120, 13103, '1. Tratamiento con sulfato de magnesio y después inducción del parto o cesárea si no reúne condiciones favorables para la inducción.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39121, 13103, '2. Inducción del parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39122, 13103, '3. Tratamiento con hidralazina y si se normaliza la tensión arterial continuar el embarazo hasta alcanzar las 36-37 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39123, 13103, '4. Cesárea inmediata.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39124, 13103, '5. Tratamiento con hidralazina, y con glucocorticoides para lograr la maduración pulmonar fetal y pasadas 24 horas inducir el parto.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39125, 13104, '1. Pautar tratamiento con alfametildopa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39126, 13104, '2. Recomendar dieta hipocalórica y reducir ingesta de sal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39127, 13104, '3. Diagnóstico de preeclampsia. Reposo y tratamiento antihipertensivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39128, 13104, '4. Dado que no existe patología, se debe continuar con los controles normales de la gestación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39129, 13104, '5. Solicitar analítica de orina.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39130, 13105, '1. Preeclampsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39131, 13105, '2. Preeclampsia grave.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39132, 13105, '3. Hipertensión inducida por el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39133, 13105, '4. Hipertensión crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39134, 13105, '5. Hipertensión crónica con preeclampsia sobreañadida.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39135, 13106, '1. Excepto en el contexto de la enfermedad trofoblástica gestacional, no aparece antes de las 20 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39136, 13106, '2. Debe sospecharse en la embarazada frente a tensiones arteriales diastólicas ≥ 90 mmHg o sistólicas ≥ 140 mmHg.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39137, 13106, '3. Para su diagnóstico debe evaluarse la proteinuria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39138, 13106, '4. En un elevado porcentaje de casos deriva en una eclampsia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39139, 13106, '5. La paciente con una preeclampsia requiere una cuidadosa valoración del crecimiento fetal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39140, 13107, '1. Hiperbilirrubinemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39141, 13107, '2. Trombocitopenia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39142, 13107, '3. Hipertensión arterial.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39143, 13107, '4. Anemia hemolítica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39144, 13107, '5. Disfunción hepática.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39145, 13108, '1. Realizar una biopsia hepática para establecer el diagnóstico de la enfermedad hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39146, 13108, '2. Tratar a la paciente con ácido ursodesoxicólico, ya que probablemente se trata de una colestasis intrahepática benigna del embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39147, 13108, '3. Interrumpir el embarazo ya que el diagnóstico más probable es el hígado graso agudo del embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39148, 13108, '4. Realizar una resonancia magnética para descartar una colangitis esclerosante primaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39149, 13109, '1. Dado que el asma mejora durante el embarazo en la mayoría de pacientes, lo mejor para la paciente y el feto es suspender el tratamiento antiasmático', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39150, 13109, '2. Suspender la budesonida por haberse relacionado con un riesgo aumentado de malformaciones fetales y reemplazarla por un antileucotrieno oral (montelukast).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39151, 13109, '3. Retirar el tratamiento actual y reemplazarlo por prednisona oral a la menor dosis posible.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39152, 13109, '4. Mantener el tratamiento actual y tranquilizar a la paciente acerca de sus efectos secundarios y de la necesidad de un adecuado control del asma durante la gestación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39153, 13109, '5. Reemplazar la budesonida por un anticuerpo monoclonal anti-IgE (omalizumab) por su mayor seguridad en el embarazo al no ser un fármaco.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39154, 13110, '1. Debe ser informada del riesgo de diabetes gestacional con riesgo fetal y remitida al servicio de urgencias hospitalarias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39155, 13110, '2. Se indicará una sobrecarga oral de glucosa de 100 g solamente si tiene factores de riesgo para alteraciones del metabolismo de la glucosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39156, 13110, '3. Al ser un valor superior a 165 mg/dL se confirma el diagnóstico de diabetes gestacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39157, 13110, '4. Debe solicitarse una confirmación diagnóstica de diabetes gestacional mediante la realización de una sobrecarga oral de glucosa de 100 g.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39158, 13111, '1. Entre las semanas 12 y 16 de gestación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39159, 13111, '2. Entre las semanas 16 y 20 de gestación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39160, 13111, '3. Entre las semanas 24 y 28 de gestación.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39161, 13111, '4. Entre las semanas 32 y 38 de gestación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39162, 13112, '1. Se debe separar a las mujeres infectadas de otras pacientes obstétricas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39163, 13112, '2. Todas las pacientes obstétricas expuestas, sin certeza de inmunidad previa, deben realizarse una determinación serológica de su estado de inmunización.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39164, 13112, '3. Se debe administrar inmunoglobulina específica a las pacientes obstétricas expuestas no inmunes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39165, 13112, '4. El plazo máximo para administrar la inmunoglobulina específica tras el contacto es de 96 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39166, 13112, '5. Las gestantes sin inmunidad al virus Varicela-Zóster pueden vacunarse durante la gestación para prevenir la primoinfección.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39167, 13113, '1. La cesárea programada no reduce la tasa de transmisión vertical del virus.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39168, 13113, '2. Se ofrecerá a la gestante la posibilidad de realizar tratamiento antirretroviral sea cual sea su estadio de la enfermedad, con la finalidad de prevenir la transmisión vertical del virus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39169, 13113, '3. La transmisión vertical del virus se asocia a la carga viral materna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39170, 13113, '4. Se tiene que ofrecer a toda gestante la serología VIH en la primera consulta, sea cual sea el momento del embarazo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39171, 13113, '5. Las mujeres infectadas por el VIH tienen un mayor riesgo de presentar abortos espontáneos, muerte fetal intraútero y retraso del crecimiento intrauterino.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39172, 13114, '1. En la embarazada con screening positivo en vagina o recto en las 5 semanas previas al parto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39173, 13114, '2. En la embarazada con el antecedente de un recién nacido con infección por el estreptococo del grupo B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39174, 13114, '3. En la embarazada con bacteriuria por estreptococo en el embarazo en curso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39175, 13114, '4. En la embarazada con cultivo desconocido o no realizado y parto pretérmino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39176, 13114, '5. En la cesárea programada en la gestante sin trabajo de parto y con membranas íntegras.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39177, 13115, '1. No existe la transmisión madre-hijo del VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39178, 13115, '2. El tratamiento antirretroviral durante la gestación disminuye la trasmisión del VIH al niño.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39179, 13115, '3. El VIH no se transmite a través de la leche materna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39180, 13115, '4. El tratamiento antirretroviral al niño tras el parto está contraindicado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39181, 13115, '5. Las mujeres gestantes con infección por el VIH no deben ser tratadas con antirretrovirales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39182, 13116, '1. Administrar vacuna frente a hepatitis B nada más nacer. Lactancia artificial', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39183, 13116, '2. Administrar vacuna e inmunoglobulinas al nacer. Lactancia materna a partir del mes', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39184, 13116, '3. Imnunoglobulinas al nacer y lactancia artificial', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39185, 13116, '4. Vacuna e inmunoglobulinas al nacer. Alimentación materna', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39186, 13116, '5. Alimentación artificial y aislamiento durante 4 semanas', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39187, 13117, '1. Hacer una cesárea.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39188, 13117, '2. Permitir el parto vaginal y tratar con acicloviral recién nacido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39189, 13117, '3. No es necesario una conducta especial ya que el herpes recidivante no tiene riesgo para el recién nacido.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39190, 13117, '4. Permitir el parto vaginal y aislar al recién nacido de la madre.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39191, 13117, '5. Tratar inmediatamente las lesiones con ácido tricloroacético para inactivar el virus y entonces permitir el parto vaginal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39192, 13118, '1. La del citomegalovirus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39193, 13118, '2. La del parvovirus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39194, 13118, '3. La de la hepatitis C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39195, 13118, '4. La del SIDA.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39196, 13118, '5. La de la listeriosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39329, 13148, '3. Controles ecográficos fetales periódicos de forma ambulatoria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39197, 13119, '1. Sin profilaxis la probabilidad de que una mujer Rh negativa con hijo Rh positivo se inmunice tras el primer parto es de 1 entre 1.000.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39198, 13119, '2. La dosis estándar de 250-300 microgramos de gammaglobulina anti-Rh es suficiente para todos los casos de riesgo de inmunización.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39199, 13119, '3. Hoy se preconiza administrar alrededor de las 28 semanas de edad gestacional una dosis de 250 microgramos de gammaglobulina anti-Rh a las embarazadas Rh negativas no inmunizadas, cuando el Rh del padre es positivo o desconocido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39200, 13119, '4. La profilaxis postparto se debe administrar antes de que transcurran 7 días de la fecha del parto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39201, 13119, '5. En caso de realizar una amniocentesis precoz a las mujeres Rh negativas no inmunizadas, antes de las 20 semanas de edad gestacional, no es necesario hacer profilaxis porque a esa edad todavía no se han manifestado los antígenos de los hematíes fetales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39202, 13120, '1. Existe un mayor riesgo de aparición por la administración de corticoides a la madre gestante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39203, 13120, '2. Aparece con menor frecuencia en niños nacidos por cesárea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39204, 13120, '3. Es más frecuente en embarazos únicos que en múltiples.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39205, 13120, '4. Existe una deficiencia de surfactante pulmonar por distintos mecanismos, muchos de ellos asociados a la prematuridad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39206, 13121, '1. Iniciar tratamiento tocolítico profiláctico y mantener actitud expectante con vigilancia maternofetal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39207, 13121, '2. Iniciar tratamiento tocolítico y la pauta de maduración pulmonar con corticoides y mantener actitud expectante con vigilancia maternofetal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39208, 13121, '3. Iniciar tratamiento antibiótico, la pauta de maduración pulmonar con corticoides y mantener actitud expectante con vigilancia maternofetal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39209, 13121, '4. Iniciar tratamiento antibiótico y pauta de maduración pulmonar con corticoides y emprender medidas para finalizar la gestación en 48-72 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39210, 13122, '1. Si la medida de la longitud cervical mediante ecografía vaginal es de 20 mm.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39211, 13122, '2. Si el test de fibronectina es negativo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39212, 13122, '3. Debe administrarse en todos los casos, dada la edad gestacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39213, 13122, '4. Debe administrarse en todos los casos si la mujer es primigesta, dada la edad gestacional.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39214, 13123, '1. Temperatura corporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39215, 13123, '2. Longitud cervical.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39216, 13123, '3. Hemograma y determinación de proteína C reactiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39217, 13123, '4. Registro cardiotocográfico externo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39218, 13124, '1. Repetir el registro a las 48 horas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39219, 13124, '2. Realizar una ecografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39220, 13124, '3. Realizar una amnioscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39221, 13124, '4. Interrumpir la gestación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39222, 13125, '1. Tocolíticos, corticoides y antibióticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39223, 13125, '2. Tocolíticos y antibióticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39224, 13125, '3. Tocolíticos y corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39225, 13125, '4. Oxitocina, corticoides y antibióticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39226, 13125, '5. Corticoides y antibióticos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39227, 13126, '1. Antibióticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39228, 13126, '2. Sulfato de Magnesio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39229, 13126, '3. Hidratación intravenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39230, 13126, '4. Corticoesteroides y tratamiento tocolítico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39231, 13126, '5. Ecografías seriadas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39232, 13127, '1. Tratamiento de útero inhibición. Administración a la madre de glucocorticoides para inducir la maduración pulmonar fetal y de antibióticos para prevenir la infección.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39233, 13127, '2. Tratamiento de útero inhibición y antibióticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39234, 13127, '3. Tratamiento de útero inhibición sólo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39235, 13127, '4. Dejar evolucionar el parto.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39236, 13127, '5. Cesárea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39237, 13128, '1. Se trata de una amenaza de parto pretérmino establecida que obliga a realizar tocolisis y maduración pulmonar fetal con betametasona.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39238, 13128, '2. El test de fibronectina negativo se asocia a un riesgo de parto pretérmino inferior al 1% en las 2 semanas siguientes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39239, 13128, '3. Una longitud cervical de 3 cm. supone un elevado valor predictivo negativo para el parto pretérmino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39240, 13128, '4. Se aconseja la administración de corticoides para maduración pulmonar por el antecedente de parto pretérmino.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39241, 13128, '5. Se trata de una amenaza de parto pretérmino incierta que requiere nueva evaluación clínica a los 60-120 minutos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39242, 13129, '1. Acidosis grave. Cesárea urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39243, 13129, '2. Valor prepatológico, repetir toma en 15-20 minutos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39244, 13129, '3. Acidosis moderada, repetir toma en 1-2 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39245, 13129, '4. Valor en límites normales, dejar evolución natural de parto.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39246, 13129, '5. Repetir en el momento, posible error en la obtención de la toma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39247, 13130, '1. Realización de una cesárea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39248, 13130, '2. Realización de un vacuum.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39249, 13130, '3. Realización de un fórceps.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39250, 13130, '4. Colocación de un pulsioxímetro para conocer la saturación de O2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39251, 13130, '5. Aplicación de O2 a la madre y repetición del PH en 10 minutos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39252, 13131, '1. Se trata de un feto pequeño para la edad gestacional: finalización a las 40 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39253, 13131, '2. Se trata de un feto CIR tipo 1: finalización a las 37 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39254, 13131, '3. Se trata de un feto CIR tipo 2: finalización a las 34 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39255, 13131, '4. Se trata de un feto CIR tipo 3: finalización a las 30 semanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39256, 13132, '1. Finalización de la gestación de forma inmediata mediante una cesárea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39257, 13132, '2. Controles semanales con monitorización fetal y ecografía obstétrica cada dos semanas hasta el inicio espontáneo del parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39258, 13132, '3. Controles semanales con monitorización fetal y ecografía obstétrica cada dos semanas hasta las 40 semanas de gestación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39259, 13132, '4. Inducción del parto a partir de las 37 semanas de gestación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39261, 13133, '2. Discordancia de crecimiento fetal con crecimiento fetal restringido selectivo del feto 2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39262, 13133, '3. Rotura prematura de membranas de feto 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39263, 13133, '4. Malformación renal feto 2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39264, 13134, '1. Cuando, tras 2 horas en completa, la presentación se queda en un II plano de Hodge con los pujos maternos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39265, 13134, '2. Cuando presencia un inicio de sangrado vaginal abundante con repercusión fetal y la presentación se encuentra sobre el estrecho superior de la pelvis materna.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39266, 13134, '3. Cuando la presentación se queda en un IV plano y el punto guía es el mentón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39267, 13134, '4. Cuando se produzca una bradicardia fetal que no se recupera tras el cese de la contracción y la fontanela menor se encuentra pasado el III plano de Hodge.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39268, 13135, '1. Ante la sospecha de desprendimiento prematuro de placenta normoinserta, indica cesárea urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39269, 13135, '2. Ante la sospecha de placenta previa oclusiva total, indica finalización de la gestación mediante cesárea.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39270, 13135, '3. Ante la sospecha de desprendimiento prematuro de placenta normoinserta, indica finalización mediante parto vaginal dado que el monitor es tranquilizador.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39271, 13135, '4. Ante la sospecha de una rotura uterina, indica cesárea urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39272, 13136, '1. Desprendimiento prematuro de placenta normoinserta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39273, 13136, '2. Rotura uterina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39274, 13136, '3. Rotura de vasos previos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39275, 13136, '4. Placenta previa', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39276, 13137, '1. Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y revisión del canal del parto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39277, 13137, '2. Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y ecografía transvaginal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39278, 13137, '3. Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y taponamiento uterino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39279, 13137, '4. Masaje uterino, colocación de sonda vesical, reposición de la volemia, administración de uterotónicos y ligadura de arterias uterinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39280, 13138, '1. Finalizar la gestación mediante una cesárea de urgencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39281, 13138, '2. Indicar una ecografía transvaginal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39282, 13138, '3. Finalizar la gestación mediante la inducción del parto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39283, 13138, '4. Realizar una rotura artificial de membranas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39284, 13139, '"1. Descompensación de su diabetes gestacional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39285, 13139, '2. Desprendimiento prematuro de la placenta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39286, 13139, '3. Preeclampsia grave.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39287, 13139, '4. Rotura de ""vasa previa"".', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39288, 13139, '5. Placenta previa"', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39289, 13140, '1. Rotura esplénica con hemoperitoneo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39290, 13140, '2. Desprendimiento prematuro de placenta normoinserta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39291, 13140, '3. Amenaza de parto prematuro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39292, 13140, '4. Rotura uterina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39293, 13140, '5. Rotura de vasa previa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39294, 13141, '1. Sospecha de abruptio placentae, realiza cesárea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39295, 13141, '2. Sospecha de placenta de inserción baja, esperará a la normalización de la frecuencia cardíaca fetal y permitirá seguir el curso del parto.', false, 2);
