INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39316, 13145, '3. Retirada de la lactancia con cabergolina y antibioticoterapia oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39317, 13145, '4. Antibióticos locales, junto con lavados de la mama con antisépticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39318, 13146, '1. Heparina de bajo peso molecular solapada con dicumarínicos al menos los 5 primeros días, hasta obtener INR entre 2 y 3. Después, dicumarínicos solos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39319, 13146, '2. Sólo heparina de bajo peso molecular mientras dure el embarazo, pasando a dicumarínicos tras el parto si es preciso prolongar el tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39320, 13146, '3. Sólo dicumarínicos desde el principio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39321, 13146, '4. Fibrinolisis con activador tisular del plasminógeno (tPA).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39322, 13146, '5. Los anticoagulantes están contraindicados en el embarazo. Sólo medias de compresión fuerte.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39323, 13147, '1. Tipo de presentación podálica (nalgas puras, completas o incompletas).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39324, 13147, '2. Medida del diámetro biparietal fetal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39325, 13147, '3. Peso fetal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39326, 13147, '4. Actitud de la cabeza fetal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39327, 13148, '1. Extracción fetal mediante cesárea programada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39328, 13148, '2. Extracción fetal tras inducción de parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39330, 13148, '4. Ingreso y control estricto materno-fetal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39331, 13149, '1. Ingreso hospitalario en planta de obstetricia y observación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39332, 13149, '2. Regreso a domicilio y profilaxis antibiótica con penicilina en periodo expulsivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39333, 13149, '3. Valoración en consultas externas de obstetricia para realización de ecografía obstétrica y Doppler fetal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39334, 13149, '4. Ingreso hospitalario en sala de dilatación y profilaxis antibiótica con penicilina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39335, 13150, '1. Retroflexión.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39336, 13150, '2. Flexión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39337, 13150, '3. Desprendimiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39338, 13150, '4. Rotación intrapélvica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39339, 13151, '1. La cirugía ginecológica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39340, 13151, '2. El parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39341, 13151, '3. El cáncer de cuello de útero o vagina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39342, 13151, '4. La radioterapia de los cánceres ginecológicos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39343, 13152, '1. Occipito iliaca transversa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39344, 13152, '2. Nalgas completas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39345, 13152, '3. Mento posterior.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39346, 13152, '4. Una cesárea anterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39347, 13153, '1. Aspirina y heparina de bajo peso molecular a dosis profilácticas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39348, 13153, '2. Vitaminas antioxidantes a dosis altas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39349, 13153, '3. Intentar la gestación mediante diagnóstico genético preimplantacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39350, 13153, '4. Tratamiento según cribado de preeclampsia de primer trimestre con aspirina a dosis bajas si alto riesgo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39351, 13154, '1. Tumor del lecho placentario.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39352, 13154, '2. Hiperplasia endometrial atípica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39353, 13154, '3. Pólipo endometrial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39354, 13154, '4. Coriocarcinoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39355, 13155, '1. Repetir seriadamente cada 2 días la ecografía y la ß-HCG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39356, 13155, '2. Tranquilizar a la paciente, indicar reposo, antieméticos y repetir la ecografía en una semana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39357, 13155, '3. Legrado uterino.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39358, 13155, '4. Tratamiento con misoprostol por vía sistémica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39359, 13156, '1. Beta-HC G en sangre.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39360, 13156, '2. Histeroscopia diagnóstica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39361, 13156, '3. Legrado uterino diagnóstico-terapéutico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39362, 13156, '4. Estudio hormonal ginecológico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39363, 13157, '1. Histerosalpingografía.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39364, 13157, '2. Cariotipo en sangre periférica de ambos miembros de la pareja.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39365, 13157, '3. Determinación de anticuerpos antifosfolípidos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39366, 13157, '4. Ecografía vaginal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39367, 13158, '1. Tratamiento con metotrexate y ácido folínico semanales hasta normalizar las cifras de ß- HCG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39368, 13158, '2. Determinación semanal de ß-HCG hasta que tres consecutivas sean negativas, después determinación mensual hasta completar el año.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39369, 13158, '3. Realización de TC cerebral y torácico cada 3 meses durante 1 año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39370, 13158, '4. Realización de radiografía simple de tórax cada 3 meses durante 1 año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39371, 13159, '1. El riesgo de una nueva gestación molar en un futuro embarazo es del 50%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39372, 13159, '2. No debe quedar embarazada hasta realizar controles periódicos y haber pasado un año con niveles de beta-HCG negativos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39373, 13159, '3. No es necesario realizar controles posteriores si la evacuación del tejido trofoblástico fue completa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39374, 13159, '4. Es necesario que se realice controles periódicos ya que en el 40 % de los casos desarrollará una neoplasia trofoblástica gestacional.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39375, 13160, '1. Realizar un examen ecográfico vaginal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39376, 13160, '2. Recomendar reposo domiciliario y repetir el test de embarazo en una semana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39377, 13160, '3. Evacuar el útero mediante legrado por aspiración.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39378, 13160, '4. Pautar progesterona natural micronizada por vía vaginal hasta la semana 14 de gestación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39379, 13160, '5. Evacuar el útero mediante la administración intravaginal de prostaglandinas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39380, 13161, '1. Entre 14 y 21 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39381, 13161, '2. Entre 21 y 28 días.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39382, 13161, '3. Entre 28 y 35 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39383, 13161, '4. Entre 35 y 42 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39384, 13161, '5. Entre 42 a 49 días.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39385, 13162, '1. Engloba una serie de neoplasias que tienen en común una producción aumentada de Beta-HCG.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39386, 13162, '2. El síntoma más frecuente de la mola total es la hemorragia genital.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39387, 13162, '3. En la etiología de la mola completa, el origen es paterno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39388, 13162, '4. En la mola parcial, el cariotipo embrionario es diploide en el 90% de los casos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39389, 13162, '5. En la mola total es frecuente la aparición de hiperemesis gravídica muy precoz y severa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39390, 13163, '1. Tratamiento con metotrexate y ácido folínico semanales, en cualquier caso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39391, 13163, '2. Determinación semanal de ß-HCG durante un mes tras la normalidad de la misma. Después determinación mensual durante 1 año.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39392, 13163, '3. Realización de tomografía axial computarizada cerebral y torácica cada 3 meses durante 1 año.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39393, 13163, '4. Realización de radiografía simple de tórax cada 3 meses durante 1 año.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39394, 13163, '5. Determinación trimestral de ß-HCG, tras la normalidad de la misma, durante 1 año.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39395, 13164, '1. Gestación mal datada. La LCC nos indica el tiempo de gestación en el primer trimestre. Corregiremos la fecha probable del parto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39396, 13164, '2. Diagnóstico de aborto diferido: legrado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39397, 13164, '3. Determinación de β-HCG plasmática cada 48 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39398, 13164, '4. Diagnóstico de feto acardio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39399, 13164, '5. Amenaza de aborto. Recomienda reposo y gestágenos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39400, 13165, '1. Amenaza de aborto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39401, 13165, '2. Aborto diferido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39402, 13165, '3. Mola hidatídica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39403, 13165, '4. Amenaza de aborto en un útero con miomas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39404, 13165, '5. Aborto incompleto.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39405, 13166, '1. Repetir la determinación de gonadotropina coriónica en plasma y la ecografía cada 2-3 días y si la hormona aumenta adecuadamente a lo esperado en un embarazo y sigue sin verse saco gestacional intrauterino, indicar una laparoscopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39406, 13166, '2. Laparoscopia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39407, 13166, '3. Legrado uterino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39408, 13166, '4. Laparotomía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39409, 13166, '5. Tratamiento con metotrexato.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39410, 13167, '1. Esterilización tubárica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39411, 13167, '2. Embarazo ectópico previo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39412, 13167, '3. Portador de DIU.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39413, 13167, '4. Primigesta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39414, 13167, '5. Uso de anticonceptivos de dosis baja y continuada de sólo estrógenos (minipills).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39415, 13168, '1. Quimioterapia con Metrotexate.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39416, 13168, '2. Legrado uterino con legra de Recamier y pinza Winter.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39417, 13168, '3. Legrado por aspiración.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39418, 13168, '4. Histerectomía simple (conservando ovarios).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39419, 13168, '5. Histerectomía radical.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39420, 13169, '1. El reflejo de la visión próxima se explora con una linterna que se enfoca sobre las pupilas de forma alternativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39421, 13169, '2. El signo pupilar de Marcus Gunn o defecto pupilar aferente relativo está presente en enfermedades del nervio óptico y enfermedades retinianas no extensas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39422, 13169, '3. El reflejo fotomotor consensuado está afectado cuando el daño implica la vía eferente vehiculada por el nervio motor ocular común.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39423, 13169, '4. La anisocoria que aumenta en condiciones de oscuridad mostrando una pupila más miótica se debe a que hay un trastorno en el sistema simpático', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39424, 13170, '1. Solicitar una analítica con glucemia, hemoglobina glicosilada y velocidad de sedimentación globular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39425, 13170, '2. Prescribir un colirio antihistamínico o corticoide de baja potencia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39426, 13170, '3. Realizar una OCT (tomografía de coherencia óptica) para descartar la existencia de un edema macular diabético.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39427, 13170, '4. Realizar una gonioscopia para descartar la presencia de neovasos en el ángulo camerular', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39428, 13171, '1. Maculopatía.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39429, 13171, '2. Neuritis óptica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39430, 13171, '3. Glaucoma agudo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39431, 13171, '4. Catarata intumescente', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39432, 13172, '1. Desprendimiento de retina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39433, 13172, '2. Catarata.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39434, 13172, '3. Neuritis óptica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39435, 13172, '4. Obstrucción de la vena central de retina', false, 4);
