INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39437, 13173, '2. Artritis Idiopática Juvenil.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39438, 13173, '3. Enfermedad de Behçet.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39439, 13173, '4. Enfermedad de Marfan.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39440, 13173, '5. Esclerosis múltiple', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39441, 13174, '1. Uveítis anterior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39442, 13174, '2. Úlcera corneal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39443, 13174, '3. Iritis traumática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39444, 13174, '4. Esclerouveítis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39445, 13174, '5. Coriorretinopatía central serosa', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39446, 13175, '1. Retinopatía diabética.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39447, 13175, '2. Glaucoma crónico simple.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39448, 13175, '3. Degeneración macular asociada a la edad.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39449, 13175, '4. Desprendimiento de retina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39450, 13175, '5. Cataratas', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39451, 13176, '1. Blefaritis crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39452, 13176, '2. Queratoconjuntivitis límbica superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39453, 13176, '3. Abuso en la utilización de lentes de contacto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39454, 13176, '4. Uveítis anterior aguda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39455, 13176, '5. Queratoconjuntivitis vernal', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39456, 13177, '1. RMN cerebral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39457, 13177, '2. Arteriografía carotídea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39458, 13177, '3. Medida de la presión arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39459, 13177, '4. Determinación de la VSG.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39460, 13177, '5. Curva de glucemia', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39461, 13178, '1. Causticación ocular por sosa cáustica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39462, 13178, '2. Fractura orbitaria por estallido.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39463, 13178, '3. Ataque de glaucoma agudo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39464, 13178, '4. Neuropatía óptica isquémica asociada a enfermedad de Horton.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39465, 13178, '5. Herida ocular penetrante', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39466, 13179, '1. La conjuntivitis bacteriana sin afectación corneal produce pérdidas de visión de forma permanente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39467, 13179, '2. El hecho de que un paciente mayor de 60 años presente una disminución de agudeza visual de forma repentina nos hace pensar que ha desarrollado una catarata madura.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39468, 13179, '3. Si un paciente está diagnosticado de glaucoma crónico simple avanzado, sin otra patología visual asociada, presentará alteraciones en su campo visual central conservando la visión en el campo periférico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39469, 13179, '4. Las queratitis severas de cualquier etiología no producen alteración de la agudeza visual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39470, 13179, '5. La disminución de agudeza visual central de forma aguda o subaguda con metamorfopsias en pacientes de más de 70 años nos obliga a pensar en una degeneración macular senil', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39471, 13180, '1. Porque la Artritis Idiopática Juvenil se asocia con mucha frecuencia a alteraciones congénitas retinianas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39472, 13180, '2. Porque la Artritis Idiopática Juvenil influye en el desarrollo de defectos refractivos miópicos severos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39473, 13180, '3. Porque la Artritis Idiopática Juvenil se asocia con frecuencia a uveítis anterior crónica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39474, 13180, '4. Porque los niños con Artritis Idiopática Juvenil deben ser revisados con la misma frecuencia que un niño con otro tipo de enfermedad infantil.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39475, 13180, '5. Porque la Artritis Idiopática Juvenil se asocia a subluxación del cristalino', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39476, 13181, '1. Aparición de Hipermetropía secundaria a aumento de los niveles de glucemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39477, 13181, '2. Desarrollo de un Edema Macular de reciente instauración, secundario a su diabetes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39478, 13181, '3. Aparición de una Queratitis Estromal secundaria a los niveles de glucemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39479, 13181, '4. Presencia de Exudados Algodonosos en parénquima periférico retiniano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39480, 13181, '5. Estrabismo Secundario', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39481, 13182, '1. Hacer una cuidadosa anamnesis para tratar de averiguar la naturaleza del agente cáustico y utilizar el neutralizante adecuado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39482, 13182, '2. Enviar a un acompañante al domicilio para que nos traiga el envase del producto y lavar con el neutralizante correspondiente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39483, 13182, '3. Pasar por alto la anamnesis y la exploración y proceder a lavar los ojos con suero fisiológico o agua durante 15 a 30 minutos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39484, 13182, '4. Realizar una tinción con Fluoresceína Sódica para valorar adecuadamente las lesiones del segmento anterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39485, 13182, '5. Enviar a un Centro con Oftalmólogo de guardia', false, 5);
