INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39592, 13206, '1. Inhibidores de la anhidrasa carbónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39593, 13206, '2. Beta-bloqueantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39594, 13206, '3. Agonistas alfa-2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39595, 13206, '4. Derivados de prostaglandinas', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39596, 13207, '1. El cuadro clínico expuesto suele ser más frecuente en personas con hipermetropía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39597, 13207, '2. En esta situación se espera que la presión intraocular de ese ojo esté elevada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39598, 13207, '3. Se trata de un cuadro más frecuente en pacientes sin cristalino, (afáquicos).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39599, 13207, '4. Probablemente este paciente tendrá una cámara anterior estrecha.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39600, 13207, '5. Es probable que este paciente refiera ver halos alrededor de las luces', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39601, 13208, '"1. Miosis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39602, 13208, '2. Cámara anterior estrecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39603, 13208, '3. Edema corneal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39604, 13208, '4. Enrojecimiento ""ciliar"".', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39605, 13208, '5. Presión intraocular gravemente aumentada."', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39606, 13209, '1. Alteraciones de la papila o cabeza del nervio óptico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39607, 13209, '2. Alteraciones del campo visual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39608, 13209, '3. Cifras elevadas de presión intraocular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39609, 13209, '4. Ausencia de fluctuación o variación diurna de la presión intraocular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39610, 13209, '5. Ausencia de sintomatología en los estadios iniciales', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39611, 13210, '1. Iniciar tratamiento con implante intravítreo de dexametasona.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39612, 13210, '2. Recomendar el uso de suplementos vitamínicos específicos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39613, 13210, '3. Indicar de forma preferente cirugía de catarata con implante de lente intraocular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39614, 13210, '4. Iniciar tratamiento con inyecciones intravítreas de anti-VEGF (factor de crecimiento endotelial vascular)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39615, 13211, '1. Los síntomas por los que generalmente consultan los pacientes son los fosfenos y las miodesopsias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39616, 13211, '2. El anillo de Weiss es un signo característico en la exploración oftalmoscópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39617, 13211, '3. El signo de Shaffer o polvo de tabaco es un signo de buen pronóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39618, 13211, '4. Se produce por la licuefacción del gel vítreo por la edad', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39619, 13212, '1. Enfermedad de Stargardt.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39620, 13212, '2. Distrofia macular viteliforme de Best.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39621, 13212, '3. Retinosis pigmentaria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39622, 13212, '4. Desprendimiento de retina', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39623, 13213, '1. Retinopatía hipertensiva aguda con estrella macular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39624, 13213, '2. Retinopatía diabética proliferativa con afectación de cuatro cuadrantes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39625, 13213, '3. Retinitis por citomegalovirus.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39626, 13213, '4. Trombosis de vena central de la retina', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39627, 13214, '1. Tiene una mejoría de los síntomas al despertarse, que empeoran según avanza el día.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39628, 13214, '2. Refiere una pérdida de visión, como una cortina, que le afecta a la zona superior del campo visual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39629, 13214, '3. Sería necesario realizar un tratamiento con láser YAG previo a la cirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39630, 13214, '4. Debe realizarse tratamiento quirúrgico mediante trabeculectomía ab-externo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39631, 13215, '1. Se debe realizar un campo visual para confirmar la presencia de un desprendimiento de vítreo posterior, ya que esta es la única forma de diferenciar un desprendimiento de vítreo posterior de un desprendimiento de retina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39632, 13215, '2. La presencia de fosfenos es un signo patognomónico del desprendimiento de vítreo posterior, que debe ser tratado con retinopexia neumática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39633, 13215, '3. La aparición de fosfenos seguida de una mancha oscura que se desplaza con la mirada es sugestiva de un desprendimiento de vítreo posterior, aunque se debe realizar una exploración de fondo de ojo para descartar una rotura retiniana o hemorragia vítrea.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39634, 13215, '4. Se debe instaurar un tratamiento hipotensor ocular, ya que ha sufrido un glaucoma agudo que le provocaron los destellos y hoy están apareciendo las alteraciones en el campo visual secundarias a la lesión del nervio', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39635, 13216, '1. Retinopatía diabética proliferativa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39721, 13235, '1. Sarcoidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39636, 13216, '2. Cristalino luxado a cámara vítrea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39637, 13216, '3. Obstrucción de arteria central de la retina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39638, 13216, '4. Coriorretinopatía serosa central', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39639, 13217, '1. Distrofia macular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39640, 13217, '2. Degeneración macular senil.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39641, 13217, '3. Pseudoagujero macular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39642, 13217, '4. Edema macular', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39643, 13218, '1. Infección fúngica por cándida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39644, 13218, '2. Infección viral por citomegalovirus.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39645, 13218, '3. Infección bacteriana por micobacterias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39646, 13218, '4. Infección bacteriana por pseudomonas', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39647, 13219, '1. Un recuento de linfocitos CD4 inferior a 100.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39648, 13219, '2. La patología observada es de origen medicamentoso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39649, 13219, '3. Este paciente requiere un tratamiento quirúrgico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39650, 13219, '4. Estamos ante un problema autoinmune', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39651, 13220, '1. Determinación de creatinina sérica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39652, 13220, '2. Medida de la presión arterial (PA).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39653, 13220, '3. Auscultación abdominal (periumbilical) en busca de un soplo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39654, 13220, '4. Medida de la presión intraocular (PIO)', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39655, 13221, '1. Endoftalmitis postquirúrgica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39656, 13221, '2. Desprendimiento de retina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39657, 13221, '3. Degeneración macular asociada a la edad, forma húmeda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39658, 13221, '4. Desprendimiento posterior de vítreo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39659, 13222, '1. Es una historia altamente sugestiva de maltrato infantil.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39660, 13222, '2. Es la evolución normal de un traumatismo intraocular no perforante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39661, 13222, '3. El diagnóstico más probable es un edema de Berlin.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39662, 13222, '4. Es el cuadro característico de la angiopatía retiniana traumática de Purstcher', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39663, 13223, '1. Desprendimiento posterior de vítreo agudo.', false, 1);
