INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39796, 13251, '4. La pérdida de agudeza visual en el edema de papila es muy grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39797, 13251, '5. En las lesiones compresivas del III par (motor ocular común) hay característicamente un respeto de la función pupilar', false, 5);
