INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39820, 13256, '5. Mucormicosis', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39821, 13257, '1. No hacer modificaciones en el tratamiento dada la estabilidad y buen control de su enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39822, 13257, '2. Añadir un antagonista del receptor de la angiotensina II para lograr un mejor control de la presión arterial y disminuir la albuminuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39823, 13257, '3. Indicar la realización de una biopsia renal para confirmar la existencia de una enfermedad renal diabética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39824, 13257, '4. Iniciar tratamiento con un inhibidor del cotransportador de sodio-glucosa tipo 2 que promueve la excreción urinaria de glucosa y tiene un efecto nefroprotector', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39825, 13258, '1. El tratamiento quirúrgico por vía endoscópica transnasal urgente podría mejorar el pronóstico visual y de afectación de pares.', false, 1);
