INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39841, 13262, '1. Debe administrarse rituximab, puesto que los glucocorticoides han quedado relegados a un tratamiento de segunda línea debido a sus efectos secundarios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39842, 13262, '2. El tocilizumab se ha mostrado eficaz en reducir las recidivas y la dosis acumulada de prednisona en más del 50% de los pacientes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39843, 13262, '3. En presencia de clínica isquémica, y para no empeorar el riesgo vascular del paciente, se debe evitar el uso de glucocorticoides a dosis superiores a 30 mg/día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39844, 13262, '4. Junto con bolos de glucocorticoides de 1 g/día, el infliximab debe utilizarse como fármaco de primera línea para la inducción a la remisión', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39845, 13263, '1. Urticaria aguda de causa farmacológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39846, 13263, '2. Eritema exudativo minor secundario a fármacos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39847, 13263, '3. Síndrome de Stevens-Johnson farmacológico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39848, 13263, '4. Necrolisis tóxica epidérmica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39849, 13264, '1. Enfermedad de Wilson. Solicitar hemocultivos, pautar tratamiento antibiótico empírico y dar de alta a domicilio tras resolución de la fiebre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39850, 13264, '2. Paraparesia espástica tropical. Administrar hidratación, asegurar la ingesta oral, solicitar VIH y dar de alta a domicilio tras resolución de la fiebre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39851, 13264, '3. Enfermedad metabólica congénita del ciclo de la urea. Suspender ingesta de proteínas, administrar glucosa, solicitar analítica con amonio y preparar benzoato sódico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39852, 13264, '4. Déficit de alfa-1 antitripsina. Realizar punción lumbar, administrar aciclovir y ácido valproico ante la sospecha de meningitis y estatus epiléptico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39853, 13265, '1. Predominio matutino.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39854, 13265, '2. No cambia con esfuerzos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39855, 13265, '3. Fotofobia', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39856, 13265, '4. Sonofobia', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39857, 13266, '1. Glioblastoma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39858, 13266, '2. Meduloblastoma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39859, 13266, '3. Tumor de células germinales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39860, 13266, '4. Meningioma', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39861, 13267, '1. Desviación de la mirada hacia la izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39862, 13267, '2. Hemiparesia derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39863, 13267, '3. Disartria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39864, 13267, '4. Pupilas arreactivas', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39865, 13268, '1. Agonistas dopaminérgicos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39866, 13268, '2. Cirugía transesfenoidal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39867, 13268, '3. Radioterapia externa o radiocirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39868, 13268, '4. Tratamiento del hipogonadismo hipogonadotropo con testosterona', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39869, 13269, '1. Diplopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39870, 13269, '2. Alteraciones auditivas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39871, 13269, '3. Alteraciones urinarias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39873, 13270, '1. La sospecha diagnóstica es una apoplejía hipofisaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39874, 13270, '2. Se debería iniciar tratamiento con corticoides a dosis altas y observar la evolución, puesto que este tratamiento podría reducir el volumen de la lesión y evitar la intervención.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39875, 13270, '3. Debe plantearse el tratamiento con glucocorticoides para evitar una insuficiencia adrenal secundaria que comprometa el pronóstico vital de la paciente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39876, 13270, '4. La presencia de oftalmoplejía y los defectos visuales constituyen indicaciones para intervenir sin demora mediante descompresión quirúrgica urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39877, 13270, '5. Tras la resolución del cuadro agudo, es frecuente el desarrollo de panhipopituitarismo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39878, 13271, '1. Indometacina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39879, 13271, '2. Lamotrigina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39880, 13271, '3. Verapamilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39881, 13271, '4. Prednisona.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39882, 13271, '5. Carbonato de litio', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39883, 13272, '1. Candidiasis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39884, 13272, '2. Leucoplasia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39885, 13272, '3. Liquen plano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39886, 13272, '4. Lupus eritematoso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39887, 13272, '5. Chancro sifilítico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39888, 13273, '1. A nivel del pedúnculo cerebral ipsilateral tras la decusación de las pirámides bulbares, por invasión tumoral o absceso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39889, 13273, '2. A algún nivel del tracto corticoespinal derecho, por metástasis pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39890, 13273, '3. A nivel de las raíces espinales cervicales inferiores al entrar en el plexo braquial izquierdo, por invasión de un tumor del vértice pulmonar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39891, 13273, '4. A nivel del nervio mediano izquierdo, por invasión de un tumor del vértice pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39892, 13273, '5. A nivel bulbar lateral izquierdo, por un infarto de la arteria cerebelosa postero-inferior', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39893, 13274, '1. Aumenta el número de verdaderos negativos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39894, 13274, '2. Disminuye el número de falsos negativos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39895, 13274, '3. Aumenta el número de verdaderos positivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39896, 13274, '4. Aumenta el número de falsos positivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39897, 13274, '5. Aumenta la sensibilidad y disminuye la especificidad', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39898, 13275, '1. Sospecharía meningitis química derivada de la rotura de un tumor epidermoide selar e iniciaría de inmediato tratamiento con corticosteroides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39899, 13275, '2. Indicaría la realización de una angiografía cerebral para descartar un aneurisma, ya que lo más probable es que estemos ante un caso de hemorragia subaracnoidea y la masa que se evidencia en la TC sea un aneurisma trombosado paraselar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39900, 13275, '3. Ingreso en UCI y tratamiento del shock que padece la paciente, y una vez estabilizada practicar resonancia cerebral para cirugía programada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39901, 13275, '4. Determinación de bioquímica y hemograma urgentes, inicio de terapia con corticosteroides a dosis elevadas y cirugía transesfenoidal urgente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39902, 13275, '5. Punción lumbar para descartar meningitis bacteriana-previo inicio de antibioterapia empírica. Una vez estabilizada la paciente estudio de la masa selar', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39903, 13276, '1. La disminución del crecimiento y desarrollo sexual, edad ósea retrasada, cefalea y alteración visual sugieren déficit hormonal y compromiso del quiasma óptico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39904, 13276, '2. Al ser una niña en edad puberal, lo más probable es que su disminución de crecimiento y retraso sexual sean debidos a un síndrome de Turner.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39905, 13276, '3. No debe tener un tumor hipotalámico por la ausencia de poliuria y polidipsia. Seguramente tenga retraso constitucional y su problema visual sea de refracción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39906, 13276, '4. Un déficit de hormona de crecimiento puede explicar el retraso del desarrollo y estradiol bajo. Valorar si precisa gafas, por sus cefaleas y alteraciones visuales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39907, 13276, '5. Podría tener un craneofaringioma, pero sería raro que no hubiera dado síntomas antes. Además, no justificaría las gonadotrofinas y estradiol bajos', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39908, 13277, '1. La positividad del antígeno HLA-B27 hará seguro el diagnóstico de espondilitis anquilosante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39909, 13277, '2. Los corticoides orales serán una parte importante del tratamiento en este paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39910, 13277, '3. Una radiografía anteroposterior de pelvis y de columna lumbar aportará poco en este caso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39911, 13277, '4. La sulfasalazina será una parte importante del tratamiento en este paciente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39912, 13277, '5. La uveítis posterior es relativamente frecuente en el curso evolutivo de estos pacientes', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39913, 13278, '1. Disartria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39914, 13278, '2. Incontinencia urinaria.', false, 2);
