INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39918, 13279, '1. Solicitar una tomografía axial computarizada cerebral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39919, 13279, '2. Comenzar con tratamiento con clopidogreal y controlarlo a los 3 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39920, 13279, '3. Administrar heparina de bajo peso molecular, mientras se llega a un diagnóstico definitivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39921, 13279, '4. Administrar prednisona, al menos 1 mg/kg de peso, hasta concluir el diagnóstico.', true, 4);
