INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39980, 13293, '1. El paciente precisará tratamiento antibiótico por vía endovenosa en al fase inicial y la duración estimada del tratamiento antibiótico total será de unas 8 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39981, 13293, '2. El microrganismo que con mayor frecuencia causa este cuadro clínico es Haemophilus influenzae.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39982, 13293, '3. La ceftazidima endovenso a dosis altas es un tratamiento empírico razonable en espera del resultado de los cultivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (39983, 13293, '4. Es importante tomar muestras del conducto auditivo externo para cultivo microbiológico y de ser positivos hay que realizar antibiograma', false, 4);
