INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40004, 13298, '1. Reactivación de una otitis media crónica simple que será tratada con ciprofloxacino en gotas óticas y remitir a Otorrinolaringología.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40005, 13298, '2. Otitis media aguda que precisa tratamiento con gentamicina en gotas óticas y revisión otoscópica pasada una semana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40006, 13298, '3. Otitis media crónica colesteatomatosa que será tratada con gentamicina en gotas óticas y remitir a Otorrinolaringología.', false, 3);
