INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40021, 13302, '1. Son síntomas frecuentes sensación de taponamiento, sordera y acúfeno en el oído afectado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40022, 13302, '2. El Weber audiométrico se desplaza al oído enfermo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40023, 13302, '3. El tratamiento de elección consiste en la colocación de un drenaje transtimpánico en el oído afectado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40024, 13302, '4. En ocasiones, la otitis media secretoria del adulto puede ser expresión de un cáncer de Cavum.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40025, 13302, '5. La impedanciometría es una prueba diagnóstica definitiva.', false, 5);
