INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40067, 13312, '1. Administraría sedantes vestibulares.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40068, 13312, '2. Control evolutivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40069, 13312, '3. Realizaría una resonancia magnética para descartar un neurinoma.', true, 3);
