INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40071, 13312, '5. Le indicaría cirugía otológica de otoesclerosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40072, 13313, '1. Hipoacusia súbita, se solicitará una tomografía computerizada craneal urgente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40073, 13313, '2. Hipoacusia de conducción por otitis media serosa, se tratará con lavados nasales y esteroides tópicos nasales.', false, 2);
