INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40090, 13317, '1. Nistagmo horizontal, unidireccional, que aumenta de intensidad cuando se dirige al lado de la fase rápida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40091, 13317, '2. Nistagmo vertical, unidireccional, que no se suprime con la fijación de la mirada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40092, 13317, '3. Nistagmo horizontal, con componente rotatorio, que cambia de dirección cuando se dirige al lado de la fase lenta.', false, 3);
