INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40094, 13318, '1. Con fijación visual y en posición primaria de la mirada cambia o alterna la dirección de manera espontánea y periódicamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40095, 13318, '2. Con fijación visual cambia de dirección al mirar a uno u otro lado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40096, 13318, '3. Con fijación visual y en posición primaria de la mirada es vertical hacia abajo puro, sin componente horizontal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40097, 13318, '4. Tanto con fijación visual como al anularla es unidireccional.', true, 4);
