INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40372, 13380, '1. La probabilidad de un tumor primario de vía aero-digestiva superior es muy alta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40373, 13380, '2. La TAC cervical nos informará en profundidad del grado de desarrollo de la enfermedad cervical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40374, 13380, '3. El carcinoma glótico es la ubicación más probable para el primario de esta masa cervical.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40375, 13380, '4. La biopsia abierta de la masa cervical no debe de preceder a la punción-aspiración en el estudio diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40376, 13380, '5. La tomografía por emisión de positrones pue de resultar útil en la localización del foco tumoral primario.', false, 5);
