INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40461, 13400, '1. El cáncer laríngeo más frecuente es el carcinoma epidermoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40462, 13400, '2. Los tumores subglóticos son los de localización más frecuente y sintomatología más precoz.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40463, 13400, '3. En los tumores supraglóticos el primer síntoma puede ser una adenopatía en la región laterocervical del cuello.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40464, 13400, '4. En los tumores glóticos el primer síntoma suele ser la disfonía persistente y progresiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40465, 13400, '5. En los tumores supraglóticos la disnea puede presentarse antes que la disfonía.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40466, 13401, '1. El paciente presenta estridor espiratorio y signos evidentes de edema pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40467, 13401, '2. El paciente está muy cianótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40468, 13401, '3. El paciente está taquicárdico y sudoroso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40469, 13401, '4. El paciente presenta estridor inspiratorio y tiraje.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40470, 13402, '1. Edema de glotis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40471, 13402, '2. Edema agudo de pulmón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40472, 13402, '3. Parálisis bilateral de las cuerdas vocales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40473, 13402, '4. Laringitis subglótica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40474, 13402, '5. Estenosis subglótica post intubación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40475, 13403, '1. La primera probabilidad diagnóstica es de carcinoma de suelo de boca con metástasis cervicales bilaterales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40476, 13403, '2. La prioridad terapéutica es garantizar la alimentación del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40477, 13403, '3. Nos encontramos casi con seguridad ante una mediastinitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40478, 13403, '4. Debemos considerar de forma prioritario el riesgo de obstrucción de la vía aérea.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40479, 13403, '5. Debemos realizar como primera medida diagnóstica una citología mediante punción aspiración con aguja fina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40480, 13404, '1. Laringitis catarral aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40481, 13404, '2. Amigdalitis bacteriana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40482, 13404, '3. Angina de Ludwick.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40483, 13404, '4. Edema de Reinke.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40484, 13404, '5. Epiglotitis bacteriana.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40485, 13405, '1. Acabalgamiento de sutura parieto-occipital.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40486, 13405, '2. Edema palpebral bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40487, 13405, '3. Eritema tóxico en tronco y extremidades.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40488, 13405, '4. Mancha mongólica en espalda y extremidades superiores.', false, 4);
