INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40490, 13406, '1. Infección en el embarazo por toxoplasmosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40491, 13406, '2. Meningitis bacteriana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40492, 13406, '3. Bajo peso al nacer (menos de 1500 grs.).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40493, 13406, '4. Hiperbilirrubinemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40494, 13406, '5. Administración de corticoides durante el embarazo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40495, 13407, '1. No se recomienda ningún suplemento vitamínico en niños sanos a término.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40496, 13407, '2. Vitamina D.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40497, 13407, '3. Vitamina C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40498, 13407, '4. Hierro oral desde los 2 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40499, 13408, '1. Es importante que la madre desinfecte bien su pezón antes de iniciar cada toma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40500, 13408, '2. La primera toma de lactancia materna no debe realizarse antes de las 6 horas de vida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40501, 13408, '3. La lactancia materna precisa de un horario fijo y estricto: una toma cada 4 horas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40502, 13408, '4. No debe darse lactancia materna después de los 12 meses de vida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40503, 13408, '5. La OMS recomienda la lactancia materna exclusiva hasta los 6 meses de edad.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40504, 13409, '1. La leche humana contiene anticuerpos bacterianos y víricos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40505, 13409, '2. La lactancia natural se asocia con mía menor incidencia de alergia o intolerancia a la leche de vaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40506, 13409, '3. Están bien reconocidas las ventajas psicológicas de la lactancia al pecho tanto para la madre como para el niño.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40507, 13409, '4. No se ha documentado la transmisión de infección por VIH por la leche materna.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40508, 13409, '5. La leche humana contiene lactoferrina. que tiene un efecto inhibitorio en el crecimiento de E. coli.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40509, 13410, '1. A partir de los 4 meses yema de huevo', true, 1);
