INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40528, 13414, '4. Lactancia materna no establecida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40529, 13414, '5. Falta de evacuación de meconio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40530, 13415, '1. Tienen 3 fases evolutivas: una fase proliferativa en la que la lesión crece aceleradamente, un periodo de estabilidad y una fase involutiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40531, 13415, '2. Suponen la única lesión positiva para el marcador GLUT-1 (proteína transportadora de glucosa).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40532, 13415, '3. Es necesario realizar estudios de imagen (la ecografía sería la técnica de elección) por el riesgo aumentado de hemangiomas a nivel visceral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40533, 13415, '4. La mayoría de los hemangiomas infantiles tiene un curso clínico predecible por lo que, si no hay compromiso funcional ni estético, una opción válida es no tratar a estos pacientes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40534, 13416, '1. Prematuridad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40535, 13416, '2. Aspiración de meconio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40536, 13416, '3. Metabolopatías.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40537, 13416, '4. Malformaciones cardiacas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40538, 13417, '1. La bilirrubina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40539, 13417, '2. La gentamicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40540, 13417, '3. Los corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40541, 13417, '4. El oxígeno.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40542, 13417, '5. El fentanilo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40543, 13418, '1. Coagulación intravascular diseminada secundaria a una sepsis neonatal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40544, 13418, '2. Trombocitopenia neonatal autoinmunitaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40545, 13418, '3. Trombocitopenia neonatal aloinmunitaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40546, 13418, '4. Enfermedad hemorrágica del recién nacido por déficit de vitamina K.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40547, 13418, '5. Hemorragia neonatal por disfunción plaquetaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40548, 13419, '1. El niño presenta una enfermedad de la membrana hialina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40549, 13419, '2. Debe instaurarse una terapia intravenosa con prostaglandina E1 para mantener permeable el conducto arterioso.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40550, 13419, '3. La ecocardiografía bidimensional no será diagnóstica en este caso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40551, 13419, '4. El tratamiento de elección inicial es la ventilación mecánica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44353, 14268, '3. Osteopenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40552, 13419, '5. El paciente reúne todos los criterios de insuficiencia cardiaca neonatal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40553, 13420, '1. Trasfusión feto-fetal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40554, 13420, '2. Discordancia de crecimiento fetal con crecimiento fetal restringido selectivo del feto 2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40555, 13420, '3. Rotura prematura de membranas de feto 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40556, 13420, '4. Malformación renal feto 2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40557, 13421, '1. Valorar estudio genético teniendo en cuenta el riesgo de anomalía cromosómica en primer trimestre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40558, 13421, '2. Valorar si la gestación está correctamente datada según la longitud craneocaudal fetal de la ecografía del primer trimestre.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40559, 13421, '3. Repetir ecografía para nuevas biometrías en 2 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40560, 13421, '4. Estudio para descartar preeclampsia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40561, 13422, '1. Ausencia de contracción del bíceps a esta edad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40562, 13422, '2. Una fractura de clavícula ipsilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40563, 13422, '3. Un síndrome de Horner ipsilateral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40564, 13422, '4. Una luxación congénita de la cadera ipsilateral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40565, 13423, '1. Se trata de un feto pequeño para la edad gestacional: finalización a las 40 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40566, 13423, '2. Se trata de un feto CIR tipo 1: finalización a las 37 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40567, 13423, '3. Se trata de un feto CIR tipo 2: finalización a las 34 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40568, 13423, '4. Se trata de un feto CIR tipo 3: finalización a las 30 semanas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40569, 13424, '1. Como no responde bien a las maniobras de reanimación, se debe cambiar el tubo endotraqueal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40570, 13424, '2. Continuar con la reanimación y administrar más dosis de adrenalina intravenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40571, 13424, '3. Iniciar tratamiento con hipotermia pasiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40572, 13424, '4. Interrumpir las maniobras de reanimación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40573, 13425, '1. Existe un mayor riesgo de aparición por la administración de corticoides a la madre gestante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40574, 13425, '2. Aparece con menor frecuencia en niños nacidos por cesárea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40575, 13425, '3. Es más frecuente en embarazos únicos que en múltiples.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40576, 13425, '4. Existe una deficiencia de surfactante pulmonar por distintos mecanismos, muchos de ellos asociados a la prematuridad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40577, 13426, '1. Retirar soporte respiratorio y aumento aporte de oxígeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40578, 13426, '2. Mantener VPPI y fracción inspirada de oxígeno al 21%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40579, 13426, '3. Pasar a modalidad presión positiva continua y aumento aporte de oxígeno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40580, 13426, '4. Pasar a modalidad presión positiva continua y fracción inspirada de oxígeno al 21%.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40581, 13427, '1. Aspiración de meconio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40582, 13427, '2. Neumonía intraútero.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40583, 13427, '3. Malformación pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40584, 13427, '4. Enfermedad de la membrana hialina.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40585, 13428, '1. Los corticoides antenatales reducen el riesgo de su aparición.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40586, 13428, '2. Sus manifestaciones clínicas aparecen a partir de las 24 horas de vida.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40587, 13428, '3. El riesgo de aparición disminuye ante una rotura prematura de membranas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40588, 13428, '4. Su causa principal es el déficit de surfactante pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40589, 13429, '1. El defecto de surfactante pulmonar por inmadurez.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40590, 13429, '2. Un neumotórax a tensión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40591, 13429, '3. Un síndrome de aspiración meconial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40592, 13429, '4. Una infección respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40593, 13429, '5. La escasa fuerza muscular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40594, 13430, '1. Puede existir transmisión vertical antes, durante o después del parto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40595, 13430, '2. El porcentaje más alto de niños infectados por VIH adquiere el virus durante el parto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40596, 13430, '3. La terapia prenatal, intraparto y postnatal con zidovudina ha disminuido la tasa de transmisión en el mundo desarrollado hasta menos del 8%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40597, 13430, '4. No se ha detectado virus VIH en la leche de madres infectadas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40598, 13430, '5. Un peso al nacer inferior a 2.500 gramos aumenta al doble la tasa de transmisión.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40599, 13431, '1. Dientes de Hutchinson.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40600, 13431, '2. Nariz en silla de montar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40601, 13431, '3. Queratitis intersticial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40602, 13431, '4. Cardiopatía congénita.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40603, 13432, '1. Administrar una dosis de la vacuna frente a varicela.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40604, 13432, '2. Forzar la terminación del embarazo para poder vacunarla.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40605, 13432, '3. Es tarde para plantear una estrategia de profilaxis post-exposición.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40606, 13432, '4. Administrar gammaglobulinas polivalentes o hiperinmunes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40607, 13433, '1. Infección perinatal por el Streptococcus agalactiae.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40608, 13433, '2. Infección intrauterina por el virus de la rubeola.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40609, 13433, '3. Infección congénita por citomegalovirus (CMV).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40610, 13433, '4. Infección congénita por el virus de la inmunodeficiencia humana (VIH).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40611, 13434, '1. Se debe separar a las mujeres infectadas de otras pacientes obstétricas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40612, 13434, '2. Todas las pacientes obstétricas expuestas, sin certeza de inmunidad previa, deben realizarse una determinación serológica de su estado de inmunización.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40613, 13434, '3. Se debe administrar inmunoglobulina específica a las pacientes obstétricas expuestas no inmunes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40614, 13434, '4. El plazo máximo para administrar la inmunoglobulina específica tras el contacto es de 96 horas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40615, 13434, '5. Las gestantes sin inmunidad al virus Varicela-Zóster pueden vacunarse durante la gestación para prevenir la primoinfección.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40616, 13435, '1. El estudio de la placenta puede resultar de utilidad en el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40617, 13435, '2. Debe realizar cuanto antes un estudio serológico al recién nacido.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40618, 13435, '3. El cuadro clínico neonatal puede ser indistinguible de otras infecciones congénitas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40619, 13435, '4. El recién nacido puede encontrarse asintomático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40620, 13435, '5. Los recién nacidos infectados pero no enfermos no precisan tratamiento.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40621, 13436, '1. Púrpura trombótica trombocitopénica (PTT) inmunomediada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40622, 13436, '2. Síndrome de Guillain-Barré.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40623, 13436, '3. Rechazo humoral agudo en trasplante renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40624, 13436, '4. Enfermedad hemolítica del recién nacido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40625, 13437, '1. Atresia de vías biliares.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40626, 13437, '2. Ictericia por lactancia materna.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40627, 13437, '3. Isoinmunización 0-A de aparición tardía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40628, 13437, '4. Enfermedad de Gilbert.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40629, 13437, '5. Esferocitosis hereditaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40630, 13438, '1. Pérdida de metilación en IC2 (KCNQ1OT1) paterna.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40631, 13438, '2. Ganancia de metilación en IC1 (H19/IGF2) materna.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40632, 13438, '3. Mutación pérdida de sentido paterna en CDKN1C.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40633, 13438, '4. Deleción de IGF2 en alelo paterno.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40634, 13439, '1. La herniación del hígado en el tórax.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40635, 13439, '2. La malrotación intestinal asociada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40636, 13439, '3. El saco herniario peritoneal intratorácico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40637, 13439, '4. La hipoplasia pulmonar y la hipertensión arterial pulmonar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40638, 13440, '1. El onfalocele se produce a nivel umbilical y la gastrosquisis a nivel epigástrico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40639, 13440, '2. El defecto, en el caso de la gastrosquisis, es de mayor tamaño que el onfalocele.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40640, 13440, '3. En el onfalocele, un saco peritoneal recubre el contenido abdominal y en la gastrosquisis no.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40641, 13440, '4. El onfalocele, a diferencia de la gastrosquisis, se asocia frecuentemente con la atresia intestinal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40642, 13440, '5. A diferencia del onfalocele, en la gastrosquisis el tratamiento quirúrgico se puede diferir.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40643, 13441, '1. Se debe intervenir cuanto antes para evitar el riesgo de estrangulación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40644, 13441, '2. A partir de los 3 ó 4 años de vida, al ser frecuente su cierre espontáneo antes de esa edad.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40645, 13441, '3. Con el fin de utilizar prótesis en la cirugía, se recomienda esperar a que el paciente sea mayor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40646, 13441, '4. Si el niño presentara vómitos durante los accesos febriles.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40647, 13441, '5. Ante la sospecha de que se trate de un onfa-locele.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40648, 13442, '1. Punto de sangrado de origen gástrico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40649, 13442, '2. Divertículo de Meckel revestido de mucosa gástrica ectópica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40650, 13442, '3. Punto de sangrado de origen genitourinario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40651, 13442, '4. Gammagrafía normal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40652, 13443, '1. En la zona afectada existe una concentración aumentada de acetilcolinesterasa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40653, 13443, '2. Está ausente el reflejo inhibitorio recto-anal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40654, 13443, '3. Las pruebas diagnósticas de referencia son las biopsias rectales por succión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40655, 13443, '4. Es frecuente la presencia de encopresis o incontinencia fecal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40656, 13444, '1. Tiene una base genética.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40657, 13444, '2. Puede relacionarse con la ingesta de ciertos fármacos durante el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40658, 13444, '3. Los pacientes afectos presentan con frecuencia otitis media aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40659, 13444, '4. El cierre quirúrgico de la fisura palatina se realiza en los primeros 3 meses para evitar problemas de alimentación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40660, 13445, '1. Neuroblastoma abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40661, 13445, '2. Tumor de Wilms.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40662, 13445, '3. Nefroma mesoblástico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40663, 13445, '4. Carcinoma medular de tiroides familiar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40664, 13446, '1. Endoscopia digestiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40665, 13446, '2. Tránsito gastrointestinal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40666, 13446, '3. Gammagrafía intestinal con pertecnectato Tc99m.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40667, 13446, '4. Enema opaco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40668, 13447, '1. Enfermedad de Crigler-Najjar de tipo I.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40669, 13447, '2. Hiperoxaluria primaria tipo I.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40670, 13447, '3. Atresia biliar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40671, 13447, '4. Enfermedad de Alagille.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40672, 13448, '1. La ecografía prenatal realizada en el tercer trimestre permite el diagnóstico en un 6080% de casos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40673, 13448, '2. Se asocia en un 50% de casos a microgastria y defectos del tubo neural.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40674, 13448, '3. La distancia entre los bolsones atrésicos proximal y distal es mayor que en los otros tipos de atresia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40675, 13448, '4. Debe realizarse una gastrostomía en las primeras 48 horas de vida para permitir la alimentación enteral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40676, 13448, '5. La presencia de aire en el estómago e intestino delgado en la radiografía de abdomen confirma la existencia de una fístula distal.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40677, 13449, '1. Por la imposibilidad de deglutir la saliva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40678, 13449, '2. Por las malformaciones cardiacas frecuentemente asociadas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40679, 13449, '3. Por el riesgo de neumonitis por aspiración.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40680, 13449, '4. Por la imposibilidad de alimentación enteral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40681, 13449, '5. Por la traqueomalacia asociada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40682, 13450, '1. Se realizará una punción percutánea para lavado peritoneal con objeto de comprobar que el quiste contiene bilis para dejar un drenaje que mejore el cuadro de dolor abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40683, 13450, '2. Se indicará una laparotomía exploradora y se procederá a una resección radical de toda la vía biliar para sustituirla por una asa de intestino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40684, 13450, '3. Se indicará una laparotomía exploradora para drenar el quiste y cuando remita la dilatación se retirará el drenaje.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40685, 13450, '4. Se realizará una colangio-resonancia para delimitar el quiste y se indicará una laparotomía para la resección de quiste y anastomosis de la vía biliar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40686, 13450, '5. Es necesario un estudio gammagráfico HIDA, para delimitar el quiste y poder realizar el drenaje percútaneo con seguridad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40687, 13451, '1. Lo más probable es que el paciente presente una Enfermedad de Hirschprung que requerirá colostomía urgente con extirpación del segmento agangliónico dilatado en el mismo acto.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44528, 14308, '3. Anti-Mi2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40688, 13451, '2. Seguramente se trate de una invaginación intestinal y la ecografía será muy útil en el diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40689, 13451, '3. En la medida de lo posible se recomienda un tratamiento conservador inicial con enema de suero y estimulaciones rectales hasta la realización de manometría, enema opaco y biopsia rectal que faciliten el diagnóstico y proporcionen datos sobre la extensión del intestino afecto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40690, 13451, '4. La toma de biopsias intestinales durante la realización de la ileostomía no debe realizarse pues convierte una cirugía limpia en contaminada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40691, 13451, '5. Si no existen antecedentes familiares de Enfermedad de Hirschprung, lo más probable es que tenga un válvulo intestinal y su tratamiento es conservador con sonda nasogástrica y antibioterapia intravenosa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40692, 13452, '1. No se trata de una erupción tardía. Estamos en los límites de la normalidad (media más desviación estándar).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40693, 13452, '2. La cronología dental guarda una estrecha relación con otros procesos de crecimiento y maduración.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40694, 13452, '3. Lo más frecuente es que no encontremos ninguna causa (origen idiopático).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40695, 13452, '4. La erupción dentaria comienza con los caninos, progresando hacia los incisivos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40696, 13453, '1. Entre los 3 y 4 meses de edad, la velocidad de ganancia ponderal aumenta hasta alrededor de 40 g al día.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40697, 13453, '2. A los 4 meses se duplica el peso al nacer.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40698, 13453, '3. El peso de un recién nacido puede disminuir un 10% del peso al nacer durante la primera semana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40699, 13453, '4. La percepción de permanencia de un objeto es un hito del desarrollo fundamental, que ocurre hacia los 9 meses de edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40700, 13453, '5. Al año de vida, es capaz de caminar de la mano, usa la pinza índice-pulgar para coger un objeto sin ayuda y entregarlo a otra persona bajo petición o gesto y emplea unas pocas palabras además de “papá” y “mamá”.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40701, 13454, '1. 12 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40702, 13454, '2. 15 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40703, 13454, '3. 18 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40704, 13454, '4. 21 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40705, 13454, '5. 24 meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40706, 13455, '1. A los 4−5 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40707, 13455, '2. A los 5−6 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40708, 13455, '3. A los 6−7 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40709, 13455, '4. A los 7−8 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40710, 13455, '5. A los 8−9 meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40711, 13456, '1. En el primer año de vida, el niño aproximadamente triplica su peso al crecimiento y duplica su longitud.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40712, 13456, '2. El peso del recién nacido suele disminuir más del 10% en la primera semana de vida, por pérdida de líquido extravascular, aunque se recupere posteriormente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40713, 13456, '3. Un niño debe ganar alrededor de 30 gramos/día durante el primer mes de vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40714, 13456, '4. Los reflejos precoces o arcaicos presentes al nacimiento desaparecen entre los 3 y 4 meses de edad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40715, 13456, '5. Hacia los 2 meses, suele haber hecho su aparición la sonrisa voluntaria o social.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40716, 13457, '1. Suspender las cremas actuales y aplicar cor/coide tópico de potencia media.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40717, 13457, '2. Mantener la higiene habitual, dejar el área del pañal seca y ven8lada, y aplicar an#fúngico tópico (nista#na o imidazólico).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40718, 13457, '3. Mantener la higiene, con secado riguroso de la zona, aplicar una pasta al agua y cambiar el pañal con más frecuencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40719, 13457, '4. Aplicar cor*coide tópico combinado con an*bió*co y an*fúngico de forma empírica durante 10-14 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40720, 13458, '1. Se ha de promover la posición de decúbito lateral en la cuna para evitar aspiraciones accidentales durante el sueño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40721, 13458, '2. En hermanos de niños fallecidos por este síndrome, se ha de retrasar la vacunación de los 2 a los 6 meses de edad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40722, 13458, '3. Se recomienda el sueño del lactante sobre una superficie blanda y con la cabecera incorporada 30º sobre plano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40723, 13458, '4. Se debe evitar el sobrecalentamiento de la habitación, así como la exposición al humo del tabaco.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40724, 13459, '1. La presencia de antecedentes de muertes similares en hermanos/familiares es criterio diagnóstico de este síndrome.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40725, 13459, '2. Ante un episodio de muerte súbita infantil se debe firmar el certificado ordinario de defunción por el facultativo del servicio de urgencias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40726, 13459, '3. La edad del niño superior a 1 año excluye el diagnóstico, independientemente de que se trate o no de lactantes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40727, 13459, '4. La existencia de una patología grave diagnosticada en la autopsia es criterio diagnóstico de este síndrome.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40728, 13460, '1. El tabaquismo materno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40729, 13460, '2. El sexo femenino.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40730, 13460, '3. Un intervalo QT prolongado en la primera semana de vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40731, 13460, '4. El antecedente de un hermano fallecido por este síndrome.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40732, 13460, '5. La postura en prono para dormir.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40733, 13461, '1. Por su perfil de seguridad para el feto, pueden administrarse durante cualquier periodo del embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40734, 13461, '2. Se recomienda retrasar su administración en niños que han recibido recientemente inmunoglobulinas inespecíficas a altas dosis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40735, 13461, '3. Dado que no se trata de virus salvajes, pueden administrarse en niños con inmunosupresión grave.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40736, 13461, '4. Ya no forman parte de los calendarios oficiales de vacunación pediátrica de nuestro país.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40737, 13462, '1. Las vacunas sistemáticas son aquellas que se administran de forma obligatoria a todos los niños según el calendario vacunal vigente en su comunidad autónoma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40738, 13462, '2. Las vacunas no sistemáticas son aquellas que no se administran de forma universal en todas las comunidades autónomas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40739, 13462, '3. El calendario vacunal se define como la secuencia cronológica de vacunas que se administra sistemáticamente en un país o área geográfica determinada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40740, 13462, '4. Los calendarios vacunales deben actualizarse de forma permanente según el desarrollo de nuevas vacunas o el cambio de incidencia de enfermedades en un área geográfica determinada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40741, 13463, '1. Vacuna antineumocócica conjugada 13-valente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44529, 14308, '4. Anti-PM/SCL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40742, 13463, '2. Vacuna antigripal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40743, 13463, '3. Vacuna frente al rotavirus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40744, 13463, '4. Vacuna antimeningocócica tipo B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40745, 13464, '1. Son vacunas de virus y bacterias combinadas para hacerlas menos inmunógenas y que provoquen menos efectos secundarios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40746, 13464, '2. Son vacunas de virus enteros conjugadas con un polisacárido para poder combinarlas y hacer la trivalente o tetravalente vírica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40747, 13464, '3. Son vacunas bacterianas conjugadas con un polisacárido para poder combinarlas y hacer vacunas penta o hexavalentes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40748, 13464, '4. Son vacunas polisacáridas conjugadas con una proteína para hacerla dependiente de linfocitos T y lograr memoria inmunológica a largo plazo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40749, 13465, '1. Lactante nacido antes de las 29 semanas de gestación en el primer año de vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40750, 13465, '2. Lactante nacido antes de las 32 semanas de gestación con enfermedad pulmonar crónica de la prematuridad en el primer año de vida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40751, 13465, '3. Lactante diagnosticado de fibrosis quística de páncreas en el cribado neonatal durante el primer año de vida.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40752, 13465, '4. Lactante de 12 meses afecto de inmunodeficiencia severa combinada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40753, 13466, '1. Está indicada en niños menores de dos años en situación de riesgo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40754, 13466, '2. Induce una respuesta secundaria con altos niveles de IgG específica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40755, 13466, '3. Inducen maduración de la afinidad de los anticuerpos generados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40756, 13466, '4. No genera memoria inmunológica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40757, 13467, '1. La pauta de inmunización primaria consta de 3 dosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40758, 13467, '2. La pauta de inmunización post-exposicion en no vacunados previamente consta de 5 dosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40759, 13467, '3. Contienen virus vivos atenuados.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40760, 13467, '4. El embarazo no contraindica su administración para la profilaxis post-exposición.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40761, 13468, '1. Hepatitis B.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40762, 13468, '2. Enfermedad neumocócica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40763, 13468, '3. Haemophilus influenzae B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40764, 13468, '4. Enfermedad meningocócica C.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40765, 13469, '1. Hepatitis B.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40766, 13469, '2. Triple vírica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40767, 13469, '3. Varicela.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40768, 13469, '4. Vacuna frente al neumococo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40769, 13470, '1. Recto anterior del abdomen.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40770, 13470, '2. Deltoides.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40771, 13470, '3. Cara anterolateral externa del muslo (músculo vasto externo).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40772, 13470, '4. Región dorso-glútea (cuadrante superior externo del glúteo mayor).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40773, 13471, '1. Varicela.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40774, 13471, '2. Hepatitis B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40775, 13471, '3. Gripe.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40776, 13471, '4. Neumocócica (polisacáridos).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40777, 13472, '1. La poliomielitis paralítica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40778, 13472, '2. La difteria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40779, 13472, '3. La viruela.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40780, 13472, '4. El sarampión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40781, 13473, '1. El embarazo de la madre es una contraindicación para administrar la vacuna contra la varicela a su hijo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40782, 13473, '2. Las vacunas inactivadas suponen un riesgo para el feto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40783, 13473, '3. Están recomendadas las vacunas vivas atenuadas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40784, 13473, '4. Ante una exposición de riesgo, la embarazada puede recibir inmunoglobulinas inespecíficas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40785, 13474, '1. Vacuna antigripal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40786, 13474, '2. Vacuna anti-hepatitis B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40787, 13474, '3. Vacuna antipoliomielítica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40788, 13474, '4. Vacuna anti-sarampión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40789, 13475, '1. Los prematuros deben ser vacunados de acuerdo a su edad corregida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40790, 13475, '2. Las vacunas vivas atenuadas están generalmente contraindicadas en los niños inmunodeprimidos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40791, 13475, '3. La vacuna triple vírica (sarampión, rubeola y parotiditis) está contraindicada en niños con alergia al huevo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40792, 13475, '4. Las inmunoglobulinas interfieren con las vacunas inactivadas (muertas).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40793, 13476, '1. Rubeola.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40794, 13476, '2. Tos ferina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40795, 13476, '3. Encefalitis japonesa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40796, 13476, '4. Hepatitis B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40797, 13477, '1. Debe de estimularse ya que es muy conveniente para la Salud Pública.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40798, 13477, '2. Es el procedimiento de elección para el control del síndrome de rubeola congénita.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40799, 13477, '3. No se considera ya como una indicación de aborto.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40800, 13477, '4. Es permitida en el caso de las vacunas de la cepa RA 27/3, pero no en el caso de las vacunas de la cepa Cendehill.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40801, 13477, '5. Se debe administrar conjuntamente con inmunoglobulina específica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40802, 13478, '1. Sí.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40803, 13478, '2. No.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40804, 13478, '3. Solo cuando se utilizan vacunas con adyuvantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40805, 13478, '4. Solo frente al virus polio tipo 3.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40806, 13478, '5. Solo si se administra con vacuna DTP.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40807, 13479, '1. En los lactantes vacunados antes de los 12 meses, no se debe contabilizar la dosis administrada, y han de recibir dos dosis adicionales: a los 12-15 meses y a los 4-6 años de edad, respectivamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40808, 13479, '2. La lectura del Mantoux no resulta interferida por la administración de la vacuna dos semanas antes de la prueba.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40809, 13479, '3. La vacuna puede prevenir o atenuar el curso de la enfermedad cuando se administra personas no vacunadas, en las 72 horas siguientes a la exposición a un caso de sarampión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40810, 13479, '4. La vacunación protege frente al desarrollo de panencefalitis esclerosante subaguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40811, 13479, '5. No está contraindicada en pacientes alérgicos al huevo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40812, 13480, '1. Reiniciar pauta vacunal (0-1-6 meses).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40813, 13480, '2. Reiniciar pauta vacunal (0-1-2-12 meses).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40814, 13480, '3. No revacunar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40815, 13480, '4. Darle una dosis de recuerdo o booster.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40816, 13480, '5. Darle Immunoglobulina anti-hepatitis B y reiniciar pauta vacunal (0-1-2-12 meses).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40817, 13481, '1. Triple vírica (sarampión/rubeola/parotiditis).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40818, 13481, '2. Hepatitis B.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40819, 13481, '3. DTPa (difteria/tetanos/pertussis acelular).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40820, 13481, '4. Gripe.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40821, 13481, '5. Antineumocócica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40822, 13482, '1. Vacunación a los niños con vacuna conjugada antineumocócica (PCV7).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40823, 13482, '2. Vacunación a los adultos con vacuna conjugada antineumocócica (PCV7).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40824, 13482, '3. Vacunación a los niños con vacuna polisacárida polivalente antineumocócica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40825, 13482, '4. Vacunación a los adultos con vacuna polisacárida polivalente antineumocócica (PPV23).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40826, 13482, '5. La mejora en las condiciones de vida y un mejor uso de antibióticos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40827, 13483, '1. La vacunación inadvertida de mujeres embarazadas con vacuna triple vírica produce malformaciones congénitas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40828, 13483, '2. La vacunación con vacuna triple vírica produce panencefalitis esclerosante subaguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40829, 13483, '3. El calendario de vacunación del Consejo Interterritorial del Sistema Nacional de Salud recomienda la administración de 5 dosis de esta vacuna a lo largo de la vida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40830, 13483, '4. La vacuna triple vírica es una vacuna combinada constituida por dos vacunas atenuadas y una inactivada (parotiditis).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40831, 13483, '5. La vacuna triple vírica es una vacuna combinada constituida por tres vacunas atenuadas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40832, 13484, '1. Encefalitis japonesa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40833, 13484, '2. Fiebre tifoidea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40834, 13484, '3. Fiebre amarilla.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40835, 13484, '4. Rabia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40836, 13484, '5. Dengue.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40837, 13485, '1. La vacuna antigripal trivalente administrada a la población española en los últimos años ha incluido sistemáticamente una cepa A, una cepa B y una cepa C del virus de la gripe humana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40838, 13485, '2. Una de las cepas de la vacuna antigripal estacional administrada a la población española en los últimos años ha sido A (H1N1).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40839, 13485, '3. El virus A (H1N1) de la actual pandemia está formado por la recombinación de genes de la gripe A humana y porcina y no incluye genes de la gripe A aviar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40840, 13485, '4. Los virus de la gripe son virus con ADN monocatenario y diversas proteínas, de las cuales la hemaglutinina y la neuraminidasa no son estructurales y permiten su clasificación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40841, 13485, '5. La pandemia de gripe A (H1N1) de 1918 se llamó “gripe española” porque se inició en España y afectó a la población española de manera particularmente intensa.', false, 5);
