INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40846, 13487, '1. Es una enfermedad autosómica recesiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40847, 13487, '2. El porcentaje de linfocitos que expresan CD19 o CD20 (linfocitos B) en sangre periférica está dentro de los límites normales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40848, 13487, '3. El nivel de IgG en suero disminuye paulatinamente desde el nacimiento hasta resultar indetectable.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40849, 13487, '4. La expresión de la proteína Btk en monocitos es normal.', false, 4);
