INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40851, 13488, '2. Vacuna antigripal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40852, 13488, '3. Vacuna frente al rotavirus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40853, 13488, '4. Vacuna antimeningocócica tipo B.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40854, 13489, '1. Los pacientes presentan niveles elevados de IgM mientras que mantienen niveles normales de IgG e IgA en suero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40855, 13489, '2. Presentan un defecto de la diferenciación de los linfocitos B en la médula ósea con aumento de linfocitos B inmaduros que expresan la cadena mu intracitoplasmática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40856, 13489, '3. Existe un defecto en el proceso de colaboración entre linfocitos T y B necesario para el cambio de isotipo de las inmunoglobulinas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40857, 13489, '4. Existe un defecto en el proceso de reordenamiento de los genes V de las inmunoglobulinas.', false, 4);
