INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40897, 13498, '4. Ante un contacto de riesgo con un paciente con meningitis meningocócica, la vacunación del contacto no debe ser la primera estrategia de profilaxis postexposición.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40898, 13499, '1. Es esperable encontrar diplococos grampositivos en el líquido cefalorraquídeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40899, 13499, '2. La etiología más probable es el neumococo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40900, 13499, '3. Será necesario hacer quimioprofilaxis en las personas que hayan estado en contacto íntimo con el paciente.', true, 3);
