INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40947, 13510, '1. El cuadro clínico es diagnóstico: fiebre elevada, malestar general, dolor de garganta y en ocasiones, adenopatías.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40948, 13510, '2. Los tests de diagnóstico rápido presentan una elevada sensibilidad, por lo que si el resultado es positivo podemos establecer un diagnóstico definitivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40949, 13510, '3. La pauta de tratamiento de elección es amoxicilina-clavulánico 875 mg cada 8 horas durante 10 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40950, 13510, '4. El tratamiento antibiótico ha demostrado reducir la posibilidad de fiebre reumática pero no de glomerulonefritis postestreptocócica.', true, 4);
