INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40978, 13517, '2. Fiebre y odinofagia de comienzo brusco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (40979, 13517, '3. Exantema de tipo escarlatiniforme.', false, 3);
