INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41161, 13559, '1. Rehidratación intravenosa, dieta absoluta 8 horas y comenzar alimentación con dieta astringente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41162, 13559, '2. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L) y continuar con su alimentación habitual.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41163, 13559, '3. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L), mantener alimentación habitual y amoxicilina oral 10 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41164, 13559, '4. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L) y comenzar alimentación con fórmula sin lactosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41165, 13559, '5. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L), mantener alimentación habitual y loperamida 7 días.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41166, 13560, '1. Se debe realizar una estimación de las pérdidas, recomendar un ayuno de 4 horas y rehidratar durante este tiempo con solución rehidratante oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41167, 13560, '2. Es aconsejable la introducción de cereales de arroz por su efecto astringente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41168, 13560, '3. Se debe realizar coprocultivo tan pronto como sea posible para excluir un origen bacteriano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41169, 13560, '4. Se debe recomendar el empleo de fórmula sin lactosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41170, 13560, '5. Se ha de aconsejar reponer las pérdidas tras cada deposición, con solución rehidratante oral, y continuar con su alimentación habitual.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41171, 13561, '1. Es necesaria la confirmación con biopsia intestinal para un diagnóstico definitivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41172, 13561, '2. La genética (DQ2/DQ8) tiene un elevado valor predictivo negativo.', true, 2);
