INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41178, 13562, '4. Se trata de una alergia a las proteínas de la leche de la vaca y le dejaría con lactancia materna exclusiva o fórmula hidrolizada.', true, 4);
