INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41188, 13565, '2. La causa más común de persistencia de títulos serológicos elevados es la ausencia de cumplimiento dietético o la ingesta inadvertida de gluten.', false, 2);
