INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41204, 13569, '1. El diagnóstico más probable es el de fisura anal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41205, 13569, '2. Puede encontrarse aumento de leucocitos en heces.', false, 2);
