INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41324, 13595, '2. La insuficiencia renal combinada con hemólisis puede provocar hiperpotasemia potencialmente grave.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41325, 13595, '3. Cuando está asociado a bacterias entéricas productoras de toxinas shiga o verotoxinas, es más frecuente en adolescentes que en menores de 5 años.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41326, 13595, '4. En los casos asociados a diarrea por E.coli O157:H7, el tratamiento antibiótico precoz con quinolonas mejora el pronóstico del paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41327, 13596, '1. Glomerulopatía membranosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41328, 13596, '2. Nefropatía por inmunoglobulina A (nefropatía de Berger).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41329, 13596, '3. Glomerulonefritis membranoproliferativa o mesangiocapilar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41330, 13596, '4. Glomerulonefritis aguda postinfecciosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41331, 13597, '1. Determinar creatinina y nitrógeno en sangre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41332, 13597, '2. Derivar a la niña para la realización de una citoscopia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41333, 13597, '3. Determinar anticuerpos antinucleares y complemento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41334, 13597, '4. Volver a repetir el sedimento de orina en 15 días.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41335, 13597, '5. Realizar una tomografía axial computarizada abdominal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41336, 13598, '1. Anemia hemolítica microangiopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41337, 13598, '2. Trombocitopenia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41338, 13598, '3. Alargamiento de los tiempos de coagulación (TPTA y protrombina).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41339, 13598, '4. Puede desencadenarlo una infección previa por Streptococcus pneumoniae.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41340, 13599, '1. Favorecer el desplazamiento de potasio desde el espacio plasmático al espacio intracelular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41341, 13599, '2. Quelar el potasio circulante para favorecer su eliminación hepática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41342, 13599, '3. Quelar el potasio circulante para favorecer su eliminación renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41343, 13599, '4. Antagonizar la acción del potasio sobre la membrana de la célula miocárdica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41344, 13600, '1. Mielomeningocele.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41345, 13600, '2. Infecciones urinarias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41346, 13600, '3. Estenosis de la unión pieloureteral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41347, 13600, '4. Válvulas uretrales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41348, 13601, '1. Es la apertura de la uretra en la cara dorsal del pene que causa un cúmulo de piel a nivel ventral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41349, 13601, '2. Se asocia a diástasis de pubis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41350, 13601, '3. Se asocia a un cúmulo de piel del prepucio a nivel dorsal y fibrosis en la placa uretral distal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41351, 13601, '4. Suele asociarse a otras malformaciones de los genitales externos (p.e. en la delección cromosoma 13q).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41352, 13602, '1. Hernia crural.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41353, 13602, '2. Torsión de hidátide de Morgagni.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41354, 13602, '3. Epididimitis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41355, 13602, '4. Torsión testicular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41356, 13603, '1. El diagnóstico más probable es el de testículo retráctil.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41357, 13603, '2. Se ha de esperar hasta los dos años de edad a que ocurra descenso espontáneo del mismo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41358, 13603, '3. La gonadotropina coriónica humana es el tratamiento de primera elección.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41359, 13603, '4. La indicación de orquidopexia no debe diferirse.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41360, 13604, '1. Realizar una ecografía abdómico-pélvica para determinar la localización exacta de la gónada no palpable.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41361, 13604, '2. Seguir al paciente clínicamente y ecográficamente hasta los dos años.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41362, 13604, '3. Indicar la realización de una laparoscopia exploradora para determinar la presencia o no del testículo derecho, realizando una orquidopexia en función de los hallazgos de la laparoscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41363, 13604, '4. Realizar un cariotipo para descartar la presencia de alteraciones cromosómicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41364, 13604, '5. El paciente presenta una anorquia unilateral y no precisa ningún estudio diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41365, 13605, '1. Hasta los dos años se puede tratar de un proceso fisiológico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41366, 13605, '2. Es un hallazgo poco frecuente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43169, 14006, '4. Mesotelioma', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41367, 13605, '3. Se realiza circuncisión solo en caso de existir motivos religiosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41368, 13605, '4. Las adherencias peneanas y la fimosis se trata de una misma patología.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41369, 13605, '5. En la actualidad el uso de pomadas de corticoides evita la circuncisión por motivos médicos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41370, 13606, '1. Iniciar perfusión continua con prostaglandinas E1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41371, 13606, '2. Administrar tratamiento con ibuprofeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41372, 13606, '3. Plantear cirugía de carácter emergente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41373, 13606, '4. Realizar cateterismo y atrioseptostomía de Rashking urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41374, 13607, '1. Dextro-transposición de grandes arterias.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41375, 13607, '2. Persistencia del ductus arterioso.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41376, 13607, '3. Tetralogía de Fallot.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41377, 13607, '4. Enfermedad de Ebstein.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41378, 13608, '1. En la prueba de hiperoxia con O2 al 100 % no se eleva significativamente la saturación de O2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41379, 13608, '2. Es típica la presencia de hiperaflujo sanguíneo pulmonar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41380, 13608, '3. Ante toda sospecha debe administrarse precozmente una perfusión de prostaglandina E1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41381, 13608, '4. La silueta cardiaca presenta la típica imagen de corazón en bota.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41382, 13609, '1. Exceptuando la válvula aórtica bicúspide, la CIV es la cardiopatía congénita más frecuente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41383, 13609, '2. Las CIV localizadas en la porción media y apical del tabique interventricular son de tipo muscular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41384, 13609, '3. La repercusión clínica y la necesidad de tratamiento dependen del tamaño de la comunicación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41385, 13609, '4. Las CIV membranosas son las más frecuentes y las que tienen más probabilidad de cierre espontáneo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41386, 13610, '1. Comunicación interauricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41387, 13610, '2. Comunicación interventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41388, 13610, '3. Defectos del tabique auriculo-ventricular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41389, 13610, '4. Coartación de la aorta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41390, 13610, '5. Conducto arterioso persistente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41391, 13611, '1. Sospecharía un soplo inocente y no le haría más pruebas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41392, 13611, '2. Dado que presenta un hemibloqueo anterior izquierdo podría tratarse de un canal auriculoventricular parcial (CIA ostium primun y cleft mitral) por lo que se le realizarían una Rx tórax y un ecocardiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41393, 13611, '3. Dado que presenta un eje derecho y un patrón rsR´ podría tratarse una comunicación interauricular tipo ostium secundum y se le realizaría una Rx tórax y un ecocardiograma para confirmarlo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41394, 13611, '4. Sería preciso plantear la implantación de un marcapaso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41395, 13611, '5. Como existen datos de hipertrofia ventrículo izquierdo le realizaría estudio familiar para descartar miocardiopatía hipertrófica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41396, 13612, '1. Tetralogía de Fallot.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41397, 13612, '2. Estenosis pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41398, 13612, '3. Comunicación interauricular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41399, 13612, '4. Persistencia de ductus arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41400, 13612, '5. Comunicación interventricular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41401, 13613, '1. Necesita tratamiento de la insuficiencia Cardíaca.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41402, 13613, '2. Puede presentar crisis de taquicardia paroxística supraventricular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41403, 13613, '3. La ecocardiografia 2D-Doppler descartará su asociación con la Enfermedad de Ebstein.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41404, 13613, '4. Es conveniente se la practique un E.C.G. De 24 horas (Holter) y una Ergometría.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41405, 13613, '5. En determinados pacientes la ablación de la vía accesoria con radiofrecuencia constituye la acción terapéutica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41406, 13614, '1. El tratamiento corrector es únicamente quirúrgico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41407, 13614, '2. Precisa profilaxis de la endocarditis bacteriana en las situaciones de riesgo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41408, 13614, '3. Para su diagnóstico es imprescindible la realización de un cateterismo cardíaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41409, 13614, '4. La sintomatología clínica tardía consiste en hipertensión pulmonar, arritmias auriculares e insuficiencia cardíaca.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41410, 13614, '5. Es más frecuente en el sexo masculino.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41411, 13615, '1. La Rx de Tórax puede presentar muescas costales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41412, 13615, '2. El diagnóstico se efectuará mediante, Ecocardiografía 2D-Doppler color y/o RM.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41413, 13615, '3. La paciente padece una Coartación de Aorta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41414, 13615, '4. El tratamiento de elección es médico (hipotensores).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41415, 13615, '5. Se asocia frecuentemente a S. de Turner.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41416, 13616, '1. El niño presenta una enfermedad de la membrana hialina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41417, 13616, '2. Debe instaurarse una terapia intravenosa con prostaglandina E1 para mantener permeable el conducto arterioso.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41418, 13616, '3. La ecocardiografía bidimensional no será diagnóstica en este caso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41419, 13616, '4. El tratamiento de elección inicial es la ventilación mecánica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41420, 13616, '5. El paciente reúne todos los criterios de insuficiencia cardiaca neonatal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41421, 13617, '1. Tratamiento médico de la hipertensión.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41422, 13617, '2. Angioplastia con balón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41423, 13617, '3. Reparación quirúrgica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41424, 13617, '4. Infusión de Prostaglandinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41425, 13617, '5. No requiere tratamiento', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41426, 13618, '1. Crisis hipoxícas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41427, 13618, '2. Postura de Acuclillamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41428, 13618, '3. Disnea de esfuerzo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41429, 13618, '4. Hipertensión Pulmonar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41430, 13618, '5. Corazón en zueco en la Rx de tórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41431, 13619, '1. Persistencia de fontanela anterior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41432, 13619, '2. Ensanchamiento de muñecas y rodillas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41433, 13619, '3. Hepatomegalia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41434, 13619, '4. Genu valgo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41435, 13620, '1. Calcio normal, fosfato normal, fosfatasas alcalinas (FA) normales, hormona pratiroidea (PTH) normal, 25 OH vitamina D baja.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41436, 13620, '2. Calcio normal, fosfato bajo, FA normales, PTH normal, 25 OH vitamina D baja.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41437, 13620, '3. Calcio bajo, fosfato alto, FA elevadas, PTH normal, 25 OH vitamina D baja.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41438, 13620, '4. Calcio normal, fosfato normal, FA elevadas, PTH elevada, 25 OH vitamina D baja.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41439, 13621, '1. Vitamina A.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41440, 13621, '2. Triptófano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41441, 13621, '3. Vitamina C.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41442, 13621, '4. Selenio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41443, 13621, '5. Vitamina K.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41444, 13622, '1. La prevalencia es mayor en quienes toman un desayuno escaso o lo omiten', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41445, 13622, '2. La medición de obesidad y sobrepeso se realiza mediante el cálculo del índice de masa corporal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41446, 13622, '3. El bajo nivel educativo de los padres y las condiciones económicas negativas, se consideran factores de riesgo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41447, 13622, '4. El empleo de los estándares de crecimiento de la Organización Mundial de la Salud facilita la comparación entre estudios realizados en distintos países.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41448, 13622, '5. El rápido aumento de la prevalencia experimentado en últimas décadas es atribuido a causas genéticas.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41449, 13623, '1. Acidosis metabólica sin compensar respiratoriamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41450, 13623, '2. Acidosis metabólica parcialmente compensada respiratoriamente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41451, 13623, '3. Acidosis respiratoria parcialmente compensada metabólicamente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41452, 13623, '4. Alcalosis respiratoria compensada metabólicamente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41453, 13624, '1. 30 ml/kg/día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41454, 13624, '2. 60 ml/kg/día.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41455, 13624, '3. 80 ml/kg/día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41456, 13624, '4. 100 ml/kg/día.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41457, 13625, '1. Hay que recomendar una dieta astringente pobre en fibra hasta su resolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41458, 13625, '2. Se recomienda reducir de entrada el aporte de lactosa los primeros días de la diarrea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41459, 13625, '3. Se debe proponer rehidratación oral durante 4-6 horas y realimentación posterior con dieta normal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41460, 13625, '4. La presencia de Salmonella en heces debe ser tratada con antibióticos para evitar su diseminación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41461, 13626, '1. Rehidratación intravenosa, dieta absoluta 8 horas y comenzar alimentación con dieta astringente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41462, 13626, '2. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L) y continuar con su alimentación habitual.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41463, 13626, '3. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L), mantener alimentación habitual y amoxicilina oral 10 días.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41464, 13626, '4. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L) y comenzar alimentación con fórmula sin lactosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41465, 13626, '5. Rehidratación con solución de rehidratación oral de baja osmolalidad (sodio 6075mEq/L), mantener alimentación habitual y loperamida 7 días.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41466, 13627, '1. Se debe realizar una estimación de las pérdidas, recomendar un ayuno de 4 horas y rehidratar durante este tiempo con solución rehidratante oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41467, 13627, '2. Es aconsejable la introducción de cereales de arroz por su efecto astringente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41468, 13627, '3. Se debe realizar coprocultivo tan pronto como sea posible para excluir un origen bacteriano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41469, 13627, '4. Se debe recomendar el empleo de fórmula sin lactosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41470, 13627, '5. Se ha de aconsejar reponer las pérdidas tras cada deposición, con solución rehidratante oral, y continuar con su alimentación habitual.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41471, 13628, '1. Acidosis respiratoria no compensada totalmente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41472, 13628, '2. Acidosis respiratoria totalmente compensada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41473, 13628, '3. Acidosis metabólica totalmente compensada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41474, 13628, '4. Acidosis metabólica no compensada totalmente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41475, 13628, '5. Alcalosis respiratoria compensada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41476, 13629, '1. Herencia autosómica recesiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41477, 13629, '2. Mutación de novo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41478, 13629, '3. Penetrancia incompleta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41479, 13629, '4. Mosaicismo germinal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41480, 13630, '1. Disminución de ácidos dicarboxílicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41481, 13630, '2. Aumento de la gluconeogénesis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41482, 13630, '3. Disminución de la ureagénesis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41483, 13630, '4. Aumento de carnitina libre.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41484, 13631, '1. La fenilalanina debe suprimirse en la dieta completamente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41485, 13631, '2. La discapacidad intelectual es constante y progresiva en caso de no realizar bien la dieta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41486, 13631, '3. Puede deberse a un déficit de tetrahidrobiopterina BH4.', false, 3);
