INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41501, 13635, '1. Tiene una base genética.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41502, 13635, '2. Puede relacionarse con la ingesta de ciertos fármacos durante el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41503, 13635, '3. Los pacientes afectos presentan con frecuencia otitis media aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41504, 13635, '4. El cierre quirúrgico de la fisura palatina se realiza en los primeros 3 meses para evitar problemas de alimentación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41505, 13636, '1. Es una gammagrafía ósea normal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41506, 13636, '2. No está indicada la gammagrafía ósea en el estudio de extensión, ya que el sarcoma de Ewing no desarrolla metástasis óseas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41507, 13636, '3. Existe afectación ósea metastásica diseminada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41508, 13636, '4. El único hallazgo anormal es el acúmulo patológico del radiotrazador en el tumor costal conocido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41509, 13637, '1. Antihistamínicos orales de primera generación, como la difenhidramina, debido a su efecto rápido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41510, 13637, '2. Descongestionantes nasales tópicos usados prolongadamente para un control sostenido de la congestión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41511, 13637, '3. Corticosteroides intranasales de alta potencia, para aliviar síntomas nasales y oculares con menos efectos sistémicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41512, 13637, '4. Cromoglicato sódico por vía oral como único tratamiento en síntomas moderados persistentes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41513, 13638, '1. Absceso subperióstico extracraneal.', false, 1);
