INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41548, 13646, '1. El virus respiratorio sincitial (VRS) es la segunda causa de bronquiolitis aguda y neumonía vírica en menores de 1 año.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41549, 13646, '2. Se recomienda la administración de palivizumab para proteger a niños con riesgo alto contra las complicaciones graves de la enfermedad por el VRS.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41550, 13646, '3. La bronquiolitis se produce por obstrucción y colapso de las vías respiratorias de mediano y gran calibre durante la espiración.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41551, 13646, '4. El tratamiento se basa en aerosoles de suero salino hipertónico, adrenalina y/o beta-2 agonistas según la gravedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41552, 13647, '1. Rivabirina oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41553, 13647, '2. Salbutamol nebulizado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41554, 13647, '3. Oxígeno suplementario.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41555, 13647, '4. Corticoides intravenosos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41556, 13648, '1. Solicitar gasometría venosa, recuento leucocitario y reactantes de fase aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41557, 13648, '2. Solicitar radiografía de tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41558, 13648, '3. Solicitar gasometría arterial y reactantes de fase aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41559, 13648, '4. No solicitar pruebas complementarias.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41560, 13649, '1. Ponerle semiincorporado en la cuna.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41561, 13649, '2. Lavados nasales con suero fisiológico con aspirado de secreciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41562, 13649, '3. Hidratación adecuada con tomas más pequeñas y frecuentes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41563, 13649, '4. Amoxicilina oral, 50 mg/kg/día cada 8 horas durante 5 días.', true, 4);
