INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41568, 13650, '5. Virus respiratorio sincitial.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41569, 13651, '1. Crisis asmática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41570, 13651, '2. Bronquiolitis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41571, 13651, '3. Neumonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41572, 13651, '4. Tosferina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41573, 13651, '5. Infección respiratoria de vías altas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41574, 13652, '1. Vacunar anualmente contra la gripe.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41575, 13652, '2. Tratar la rinitis y la sinusitis coincidentes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41576, 13652, '3. Enseñarle a medir el flujo espiratorio máximo en su domicilio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41577, 13652, '4. Evitar o reducir la exposición a los alergenos a los que esté sensibilizado y a otros irritantes de la vía respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41578, 13652, '5. Emplear como tratamiento de mantenimiento beta-agonistas de acción larga en monoterapia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41579, 13653, '1. Drenaje cerrado con un tubo de tórax con instilación de fibrinolíticos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41580, 13653, '2. Toracocentesis repetidas para extraer todo el derrame posible.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41581, 13653, '3. Decorticación quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41582, 13653, '4. Ampliación de la cobertura antibiótica.', false, 4);
