INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41588, 13655, '1. Anomalías pigmentarias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41589, 13655, '2. Anomalías renales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41590, 13655, '3. Anomalías esqueléticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41591, 13655, '4. Estatura alta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41592, 13656, '1. La anemia aplásica suele estar ya presente en los primeros meses de vida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41593, 13656, '2. Son típicas las malformaciones esqueléticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41594, 13656, '3. El trasplante de progenitores hematopoyéticos es el tratamiento curativo, pero no hace desaparecer el riesgo de cáncer.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41595, 13656, '4. Los andrógenos suelen producir una respuesta fa- vorable pero transitoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41596, 13657, '1. Déficit de factor VII.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41597, 13657, '2. Déficit de factor VIII.', false, 2);
