INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41601, 13658, '2. Emicizumab.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41602, 13658, '3. Ácido tranexámico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41603, 13658, '4. Factor VII activado recombinante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41604, 13659, '1. Puede ser una alternativa de tratamiento curativo en diversas situaciones en oncología.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41605, 13659, '2. Se emplea también para determinadas patologías benignas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41606, 13659, '3. Está contraindicada para el tratamiento de tumores pediátricos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41607, 13659, '4. Tiene una demostrada utilidad en el control del dolor por metástasis óseas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41608, 13660, '1. Debemos sospecharlo ante la aparición de un síndrome opsoclono-mioclono-ataxia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41609, 13660, '2. Existe casi siempre un aumento en la excreción urinaria de metabolitos de catecolaminas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41610, 13660, '3. La mayoría se diagnostica en menores de 6 años de edad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41611, 13660, '4. La gammagrafía con tecnecio es muy específica y está indicada para definir mejor su extensión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41612, 13661, '1. Osteosarcoma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41613, 13661, '2. Osteomielitis subaguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41614, 13661, '3. Osteocondritis disecante.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41615, 13661, '4. Tumor de células gigantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41616, 13662, '1. Lesión lítica con bordes bien definidos y sin reacción periostal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41617, 13662, '2. Lesión con patrón mixto lítico-esclerótico y reacción periostal tipo triangulo de Codman.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41618, 13662, '3. Lesión subcondral con colapso de la placa ósea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41619, 13662, '4. Lesión con calcificaciones puntiformes y sin masa de partes blandas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41620, 13663, '1. Observación, con recomendación específica de ejercicios y revisión posterior.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41621, 13663, '2. Corsé de Milwaukee a tiempo completo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41622, 13663, '3. Corsé de Boston a tiempo parcial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41623, 13663, '4. Derivación a cirugía para tratamiento quirúrgico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41624, 13664, '1. Realizar una arteriografía de la arteria humeral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41625, 13664, '2. Reducir y fijar la fractura en quirófano y observar la respuesta vascular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41626, 13664, '3. Proceder a la exploración quirúrgica de la arteria humeral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41627, 13664, '4. Hacer una ecografía Doppler de la arteria radial a nivel de la muñeca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41628, 13665, '1. Solicitar un escoliograma en bipedestación y en función de los grados de Cobb decidir tratamiento con corsé.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41629, 13665, '2. Proponer una revisión en 6 meses con un escoliograma en decúbito.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41630, 13665, '3. Derivar a fisioterapia para estiramientos y masajes del raquis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41631, 13665, '4. Recomendar natación para corregir y revisión en 6 meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41632, 13666, '1. Se aconseja la realización de una radiografía de caderas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41633, 13666, '2. En la sinovitis transitoria el comienzo suele ser agudo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41634, 13666, '3. En la enfermedad de Legg-Calvé-Perthes el pronóstico es peor cuanto menor es la edad de comienzo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41635, 13666, '4. La causa puede ser un estado de hipercoagulabilidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41636, 13666, '5. La opción terapéutica variará dependiendo del grado de afectación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41637, 13667, '1. Revisión en un año.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41638, 13667, '2. Plantillas correctoras del arco plantar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41639, 13667, '3. Plantillas de cuña pronadora de retropié.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41640, 13667, '4. Exploración neurológica y raquídea detallada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41641, 13667, '5. Cirugía de liberación de la fascia plantar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41642, 13668, '1. Fractura de cúbito y radio con luxación de cabeza radial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41643, 13668, '2. Fractura-luxación de la cabeza radial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41644, 13668, '3. Fractura del olécranon y luxación de cabeza radial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41645, 13668, '4. Fractura supracondílea del codo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41646, 13668, '5. Fractura-epifisiolisis de epitróclea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41647, 13669, '1. La edad de aparición es en mayores de 10 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41648, 13669, '2. Aparece especialmente en el sexo femenino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41649, 13669, '3. La cojera es el síntoma predominante con mayor o menor dolor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41650, 13669, '4. En la exploración del niño llama la atención la importante afectación del estado general.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41651, 13669, '5. La evolución de la enfermedad es rápida, siendo a evolución más frecuente de aproximadamente un mes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41652, 13670, '1. Radiografía de cadera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41653, 13670, '2. Ecografía de cadera.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41654, 13670, '3. RM de ambas caderas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41655, 13670, '4. Artrografía de cadera.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41656, 13671, '1. La elevación de la proteína C reactiva confirma el diagnóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41657, 13671, '2. La radiografía simple no es necesaria ya que en fases iniciales no muestra alteraciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41658, 13671, '3. La ecografía es poco sensible para detectar la presencia de líquido articular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41659, 13671, '4. La resonancia magnética es la prueba de elección para el despistaje de infección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41660, 13671, '5. La punción articular tiene valor diagnóstico y en algunos casos terapéutico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41661, 13672, '1. Cifosis congénita.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41662, 13672, '2. Tuberculosis vertebral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41663, 13672, '3. Tumor de Ewing.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41664, 13672, '4. Infección piógena.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41665, 13672, '5. Fractura antigua.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41666, 13673, '1. Pénfigo vulgar – Anticuerpos antidesmogleina 3.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41667, 13673, '2. Bloqueo cardíaco congénito – Anticuerpos anti Ro y anti-La.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41668, 13673, '3. Miastenia gravis – Anticuerpos anti receptor de la acetilcolina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41669, 13673, '4. Lupus eritematoso neonatal – Anticuerpos anti-Sm.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41670, 13674, '1. Con frecuencia presentan crisis epilépticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41671, 13674, '2. Suelen presentar angiofibromas faciales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41672, 13674, '3. El tumor cerebral más frecuente es el astrocitoma gigantocelular subependimario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41673, 13674, '4. Con frecuencia presentan neurinomas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41674, 13675, '1. Síndrome de Sturge-Weber.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41675, 13675, '2. Neurofibromatosis tipo 1.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41676, 13675, '3. Neurofibromatosis tipo 2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41677, 13675, '4. Esclerosis tuberosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41678, 13676, '1. Acabalgamiento de sutura parieto-occipital.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41679, 13676, '2. Edema palpebral bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41680, 13676, '3. Eritema tóxico en tronco y extremidades.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41681, 13676, '4. Mancha mongólica en espalda y extremidades superiores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41682, 13676, '5. Mechón de pelo en zona de columna lumbosacra.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41683, 13677, '1. Afecta por igual a ambos sexos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41684, 13677, '2. La presencia de comorbilidades en edad pediátrica es excepcional.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41685, 13677, '3. Los síntomas aparecen ya en las primeras fases del de desarrollo, pero pueden no manifestarse totalmente hasta que la demanda social supera las capacidades limitadas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41686, 13677, '4. No es posible su diagnós0co en menores de 36 meses, dadas las variabilidades fisiológicas del desarrollo psicomotor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41687, 13678, '1. Hipoacusia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41688, 13678, '2. Epilepsia residual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41689, 13678, '3. Retraso mental.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41690, 13678, '4. Hidrocefalia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41691, 13678, '5. Defectos visuales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41692, 13679, '1. Infección en el embarazo por toxoplasmosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41693, 13679, '2. Meningitis bacteriana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41694, 13679, '3. Bajo peso al nacer (menos de 1500 grs.).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41695, 13679, '4. Hiperbilirrubinemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41696, 13679, '5. Administración de corticoides durante el embarazo.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41697, 13680, '1. Debemos buscar una malformación de Chiari.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41698, 13680, '2. En algunos casos se asocia a hidrocefalia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41699, 13680, '3. Se caracteriza por una pérdida de la sensibilidad táctil y vibratoria con preservación de la sensación térmica y dolorosa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41700, 13680, '4. Puede producirse tras traumatismos o infecciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41701, 13681, '1. Inyectar un anticolinérgico intravenoso.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41702, 13681, '2. No tratar hasta no realizar en los días próximos un electroencefalograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41703, 13681, '3. No tratar hasta no saber en días próximos el resultado del cultivo del líquido cefalorraquídeo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41704, 13681, '4. Llamar al psiquiatra de urgencias', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41705, 13681, '5. Poner un antibiótico intravenoso tras obtener muestra de exudado faríngeo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41706, 13682, '1. Las pesadillas son más frecuentes en el primer tercio del sueño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41707, 13682, '2. En los niños con terrores nocturnos el umbral del despertar es bajo, por lo que es habitual que se despierten durante el episodio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41708, 13682, '3. La edad típica de presentación de los terrores nocturnos es la adolescencia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41709, 13682, '4. Los terrores nocturnos aparecen en el estadio de sueño de ondas lentas.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41710, 13682, '5. Es frecuente que los niños con terrores nocturnos recuerden, con angustia durante varios días, el episodio vivido.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41711, 13683, '1. Atrofia muscular espinal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41712, 13683, '2. Distrofia muscular de Duchenne.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41713, 13683, '3. Enfermedad de Parkinson.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41714, 13683, '4. Distrofia miotónica de Steinert.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41715, 13684, '1. Crisis primaria generalizada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41716, 13684, '2. Duración inferior a 15 minutos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41717, 13684, '3. Recurrencia en las primeras 24 horas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41718, 13684, '4. No hay focalidad neurológica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41719, 13685, '1. Presenta un proceso benigno pero que casi siempre recurre.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41720, 13685, '2. Debe remitirse a un Centro Hospitalario para realización de una prueba de neuroimagen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41721, 13685, '3. Si el foco causal de la fiebre es claro y banal y la recuperación clínica completa, puede manejarse con antitérmicos y observación domiciliaria sin realizar ninguna prueba complementaria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41722, 13685, '4. Será necesaria la realización de un EEG más adelante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41723, 13685, '5. Presenta un riesgo de desarrollo posterior de alguna forma de epilepsia mayor que el resto de la población.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41724, 13686, '1. Clonazepam.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41725, 13686, '2. Carbamazepina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41726, 13686, '3. Etosuximida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41727, 13686, '4. Ácido valproico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41728, 13687, '1. Automatismos motores leves en la cara durante la crisis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41729, 13687, '2. Confusión postcrítica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41730, 13687, '3. Descargas generalizadas punta-onda a 3 Hz en el electroencefalograma durante la crisis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41731, 13687, '4. Pérdida completa de la conciencia de segundos de duración.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41732, 13687, '5. Con maniobras de hiperventilación podemos provocar las crisis del niño.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41733, 13688, '"1. Le preguntará si fue el encargado de exprimir la lima de los mojitos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41734, 13688, '2. Le informará de la probable evolución favorable, aunque la hiperpigmentación residual podría ser muy persistente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41735, 13688, '3. La prevención consiste, en evitar el contacto con la sustancia en cues""ón y, cuando ello no sea posible, medidas fotoprotectoras.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41736, 13688, '4. El mecanismo fisiopatológico más probable en este caso sería una Hipersensibilidad -po IV mediada por linfocitos T."', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41737, 13689, '1. Se ha de ofrecer consejo contraceptivo estructurado según los criterios de elegibilidad de la Organización Mundial de la Salud (OMS), e información tanto para la prevención de embarazos no planificados, como de enfermedades de transmisión sexual (ETS).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41738, 13689, '2. Como método anticonceptivo de urgencias, las opciones recomendadas son la toma de levonorgestrel, de acetato de ulipristal o la inserción de un DIU de cobre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41739, 13689, '3. Ante la indicación de anticonceptivos orales se recomienda el cribado rutinario de trombofilia y dislipemia y citologías de control anuales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41740, 13689, '4. El riesgo de tromboembolia venosa con el consumo de anticonceptivos orales es bajo, siendo el riesgo menor en los de segunda generación, frente al mayor riesgo en los de tercera y cuarta generación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41741, 13690, '1. Presencia de autolesiones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41742, 13690, '2. Aislamiento social.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41743, 13690, '3. Irritabilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41744, 13690, '4. Dificultades académicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41745, 13691, '1. Suele ser un consumo individual lo cual indica un mejor pronóstico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41746, 13691, '2. El inicio del abuso en la adolescencia no ha demostrado un mayor riesgo de convertirse en adicto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41747, 13691, '3. Es independiente del riesgo de contagio por el VIH.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41748, 13691, '4. La droga más popular entre los adolescentes es el cannabis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41749, 13691, '5. Debe considerarse en adolescentes que llegan a la Urgencia con una crisis comicial.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41750, 13692, '1. Historia coherente con la lesión y el mecanismo lesional referido por su cuidador.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41751, 13692, '2. Hematomas u otras lesiones en diferentes estadios evolutivos, afectación de zonas no expuestas o protegidas, lesiones pares, simétricas o con forma de objeto.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41752, 13692, '3. Rasguños leves en zonas expuestas al juego.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41753, 13692, '4. Lesiones compatibles con molluscum contagiosum en tronco, axilas y miembros superiores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41754, 13693, '1. A los servicios sociales competentes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41755, 13693, '2. Al juzgado de guardia mediante parte de lesiones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41756, 13693, '3. A las Fuerzas y Cuerpos de Seguridad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41757, 13693, '4. Al Instituto de Medicina Legal y Ciencias Forenses de su demarcación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41758, 13694, '1. Maltrato físico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41759, 13694, '2. Politraumatismo por caída de la cuna.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41760, 13694, '3. Traumatismo torácico en lactante con alteración de la coagulación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41761, 13694, '4. Leucemia promielocítica aguda tras realizar aspirado de médula ósea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41762, 13695, '1. Es una historia altamente sugestiva de maltrato infantil.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41763, 13695, '2. Es la evolución normal de un traumatismo intraocular no perforante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41764, 13695, '3. El diagnóstico más probable es un edema de Berlín.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41765, 13695, '4. Es el cuadro característico de la angiopatía retiniana traumática de Purstcher.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41766, 13696, '1. Incisión y drenaje.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41767, 13696, '2. Mupirocina tópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41768, 13696, '3. Griseofulvina por vía oral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41769, 13696, '4. Cefazolina intravenosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41770, 13696, '5. Ketoconazol tópico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41771, 13697, '1. Sepsis fulminante con CID.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41772, 13697, '2. Niño maltratado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41773, 13697, '3. Déficit congénito de antitrombina 3.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41774, 13697, '4. Varicela hemorrágica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41775, 13697, '5. Enfermedad de Kawasaki.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41776, 13698, '1. Clínica neurológica por metástasis cerebrales. Realizar TC cerebral y aumentar dosis de corticoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41777, 13698, '2. Psicosis inducida por corticoides. Retirar corticoides.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41778, 13698, '3. Síndrome confusional agudo hipoactivo. Iniciar tratamiento con neurolépticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41779, 13698, '4. Neurotoxicidad por opioides. Reducir la dosis de morfina a la mitad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41780, 13699, '1. Probablemente se trata de un efecto secundario de la risperidona, por lo que se debe retirar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41781, 13699, '2. Se debe tratar el insomnio de madrugada añadiendo benzodiacepinas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41782, 13699, '3. Hay que esperar a que se resuelva totalmente la infección urinaria para cambiar la medicación actual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41783, 13699, '4. Ha empeorado la demencia y se debe añadir memantina al tratamiento de base con donepezilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41784, 13700, '1. Clorazepato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41785, 13700, '2. Lorazepam.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41786, 13700, '3. Diazepam.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41787, 13700, '4. Las benzodiacepinas están contraindicadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41788, 13701, '1. Cambios de humor, síntomas conductuales, déficit cognitivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41789, 13701, '2. Síntomas conductuales, síntomas motores, declive de la independencia funcional.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41790, 13701, '3. Cambios de humor, déficit cognitivo, declive de la independencia funcional.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41791, 13701, '4. Síntomas conductuales, cambios de humor, síntomas motores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41792, 13702, '1. Esquizofrenia de inicio tardío.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41793, 13702, '2. Episodio maniaco de inicio tardío.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41794, 13702, '3. Enfermedad de Alzheimer.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41795, 13702, '4. Demencia frontotemporal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41796, 13703, '1. La presencia de alucinaciones visuales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41797, 13703, '2. Los síntomas cognitivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41798, 13703, '3. La agitación psicomotriz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41799, 13703, '4. La fluctuación del nivel de alerta.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41800, 13704, '1. Enfermedad de Alzheimer atípica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41801, 13704, '2. Demencia por cuerpos de Lewy difusos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41802, 13704, '3. Degeneración lobular frontotemporal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41803, 13704, '4. Demencia por priones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41804, 13705, '1. Se trata del debut típico de una demencia en un paciente mayor con una infección grave.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41805, 13705, '2. Se trata de un cuadro de delirium en un paciente mayor con una infección grave.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41806, 13705, '3. Se trata del debut de un episodio psicótico agudo (esquizofrenia tardía del anciano).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41807, 13705, '4. Se trata de un episodio de depresión grave por la hospitalización con sintomatología psicótica asociada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41808, 13706, '1. La presencia de alucinaciones visuales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41809, 13706, '2. La fluctuación del nivel de alerta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41810, 13706, '3. Los síntomas cognitivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41811, 13706, '4. La agitación psicomotriz.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41812, 13707, '1. Solicitar analítica con hemograma, ionograma, función renal y hepática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41813, 13707, '2. Exploración física completa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41814, 13707, '3. Iniciar tratamiento con diazepam para control sintomático.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41815, 13707, '4. Evitar restricciones físicas de la paciente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41816, 13708, '1. La demencia y la depresión previas son factores precipitantes de delirium.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41817, 13708, '2. Iniciar un tratamiento esteroideo es una causa potencial de delirium.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41818, 13708, '3. Las benzodiacepinas son los fármacos más adecuados para el tratamiento de la inversión del ciclo sueño-vigilia característico del delirium.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41819, 13708, '4. La movilización precoz del paciente durante la hospitalización no previene la aparición del delirium.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41820, 13709, '1. Trastorno depresivo secundario a fármacos que pueda estar tomando el paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41821, 13709, '2. Trastorno depresivo secundario a enfermedades orgánicas diagnosticadas previamente o no.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (41822, 13709, '3. Pseudodemencia depresiva.', false, 3);
