INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42006, 13749, '2. El delirio es más comprensible en la paranoia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42007, 13749, '3. El Yo está más desestructurado en la esquizofrenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42008, 13749, '4. Ambas entidades aparecen clásicamente en las mismas edades.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42009, 13749, '5. Los síntomas disociativos son típicos de la esquizofrenia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42010, 13750, '1. La forma CATATÓNICA se presenta con sintomatología pobre, predominio de delirios y suele ser de inicio temprano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42011, 13750, '2. En la forma HEBEFRÉNICA existe predominio de alteraciones psicomotrices, negativismo y conductas estereotipadas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42012, 13750, '3. La presencia de estados de exaltación anímica, maniforme con estravagancias es propia de las formas SIMPLES.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42013, 13750, '4. La forma PARANOIDE presenta predominantemente trastornos del pensamiento y trastornos sensoperceptivos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42014, 13750, '5. Los síntomas obsesivos y compulsivos asociados a disgregación progresiva son habituales en la forma ESQUIZOTÍPICA.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42015, 13751, '1. Es un delirio estructurado y creíble, formado a base de creencias incorrectas acerca de la realidad externa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42016, 13751, '2. Trastornos del curso del pensamiento (bloqueo o disgregación del curso del pensamiento).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42017, 13751, '3. Síntomas negativos como abulia y aplanamiento afectivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42018, 13751, '4. Alucinaciones auditivas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42019, 13751, '5. Existe una conciencia clara de enfermedad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42020, 13752, '1. En Estados Unidos la prevalencia de esquizofrenia a lo largo de la vida es de alrededor del 1%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42021, 13752, '2. La esquizofrenia tiene igual prevalencia en varones que en mujeres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42022, 13752, '3. La evolución de la enfermedad es similar en hombres que en mujeres.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42023, 13752, '4. Según el DSM-IV-TR la incidencia anual de esquizofrenia varía de 0,5 a 5,0 por 100.000.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42024, 13752, '5. Las tasas de incidencia y prevalencia son aproximadamente iguales en todo el mundo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42025, 13753, '1. El síndrome catatónico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42026, 13753, '2. El síndrome melancólico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42027, 13753, '3. Las neoplasias frontales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42028, 13753, '4. Los estados confusionales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42029, 13753, '5. El estrés postraumático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42030, 13754, '1. Anomalías endocrinas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42031, 13754, '2. Signos neurológicos menores.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42032, 13754, '3. Alteraciones cardiológicas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42033, 13754, '4. Alteraciones inmunitarias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42034, 13754, '5. Dermopatías crónicas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42035, 13755, '1. Aplanamiento afectivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42036, 13755, '2. Alogia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42037, 13755, '3. Comportamiento desorganizado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42038, 13755, '4. Disminución de la atención.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42039, 13755, '5. Abulia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42040, 13756, '1. Anhedonia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42041, 13756, '2. Alogia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42042, 13756, '3. Frialdad emocional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42043, 13756, '4. Paralogia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42044, 13756, '5. Abulia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42045, 13757, '1. La existencia de trastornos de la percepción.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42046, 13757, '2. La incapacidad para distinguir entre la realidad interior y la exterior.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42047, 13757, '3. El marcado simbolismo que expresa su conducta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42048, 13757, '4. La hipersensibilidad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42049, 13757, '5. La incongruencia del pensamiento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42050, 13758, '1. Uso de la Terapia Electroconvulsiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42051, 13758, '2. Pasar el paciente a un antipsicótico atípico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42052, 13758, '3. Verificar que el paciente estuviera cumpliendo el tratamiento prescrito.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42053, 13758, '4. Ingresar al paciente en un hospital.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42054, 13758, '5. Añadir un tratamiento psicoterapéutico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42055, 13759, '1. El litio es altamente eficaz para reducir las tasas de suicidio.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42056, 13759, '2. El riesgo de malformaciones congénitas en recién nacidos es mayor cuando las madres reciben tratamiento con litio que cuando lo hacen con ácido valproico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42057, 13759, '3. El tratamiento con litio durante 10-20 años puede provocar una hepatopatía crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42058, 13759, '4. El litio es más eficaz que los fármacos anticonvulsivos para el tratamiento de los episodios mixtos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42059, 13760, '1. Presencia de autolesiones.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42060, 13760, '2. Aislamiento social.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42061, 13760, '3. Irritabilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42062, 13760, '4. Dificultades académicas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42063, 13761, '1. Ácido valproico y terapia interpersonal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42064, 13761, '2. Lamotrigina y terapia cognitivo-conductual.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42065, 13761, '3. Litio y terapia cognitivo-conductual.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42066, 13761, '4. Carbamazepina y terapia interpersonal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42067, 13762, '1. El carbonato de litio tiene un inicio de acción rápido y es efectivo en el tratamiento de la manía aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42068, 13762, '2. Los antipsicóticos atípicos como la olanzapina, quetiapina o aripiprazol son eficaces en el control de los síntomas maníacos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42069, 13762, '3. La combinación de estabilizadores del ánimo y antipsicóticos es a menudo necesaria para controlar la sintomatología grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42070, 13762, '4. Las benzodiacepinas como el lorazepam pueden utilizarse para el control de la agitación y el insomnio asociados a la manía aguda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42071, 13763, '1. Flufenazina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42072, 13763, '2. Olanzapina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42073, 13763, '3. Litio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42074, 13763, '4. Carbamazepina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42075, 13764, '1. Litio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42076, 13764, '2. Valproato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42077, 13764, '3. Carbamazepina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42078, 13764, '4. Clorazepato.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42079, 13765, '1. En un primer episodio en pacientes jóvenes con buena respuesta se puede suspender el tratamiento al cabo de un mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42080, 13765, '2. Se recomienda mantener el tratamiento durante un mínimo de tres meses tras la remisión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42081, 13765, '3. Se recomienda mantener el tratamiento durante un mínimo de seis meses tras la remisión.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42082, 13765, '4. Se recomienda mantener el tratamiento durante un mínimo de dos años para prevenir recaídas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42083, 13766, '1. Catalepsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42084, 13766, '2. Esquizofrenia de inicio tardío.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42085, 13766, '3. Enfermedad de Alzheimer.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42086, 13766, '4. Episodio depresivo grave con síntomas psicóticos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42087, 13767, '1. Incremento del apetito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42088, 13767, '2. Disminución de la secreción de cortisol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42089, 13767, '3. Dificultad para despertarse por la mañana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42090, 13767, '4. Empeoramiento matutino.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42091, 13768, '1. El diagnóstico es duelo (Z63.4, según la 10ª edición de la Clasificación Internacional de Enfermedades -CIE-10-).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42092, 13768, '2. Si las dificultades del sueño tienen consecuencias sobre la vigilia del día siguiente podría prescribirle temporalmente un fármaco hipnótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42093, 13768, '3. Dado el tiempo transcurrido se debería instaurar un antidepresivo a dosis bajas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42094, 13768, '4. Es conveniente darle una nueva cita al cabo de 1-2 meses para ver su evolución.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42095, 13769, '1. Abuso de sustancias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42096, 13769, '2. Evento estresante de larga duración.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42097, 13769, '3. Trastorno de pánico coexistente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42098, 13769, '4. Edad avanzada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42099, 13770, '1. El tratamiento habitual en las primeras 48 horas se basa en benzodiacepinas en monoterapia por vía parenteral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42100, 13770, '2. La clozapina es el fármaco de elección para el tratamiento agudo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42101, 13770, '3. La combinación de litio y antipsicóticos está contraindicada en las fases iniciales del tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42102, 13770, '4. En casos graves o resistentes puede utilizarse la terapia electroconvulsiva.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42103, 13771, '1. Es especialmente útil en trastornos psiquiátricos secundarios a la epilepsia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42104, 13771, '2. Tiene una eficacia superior a la terapia electroconvulsiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42105, 13771, '3. Está indicada en la depresión resistente al tratamiento farmacológico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42106, 13771, '4. Por su seguridad, es el tratamiento de elección en la esquizofrenia de inicio tardío.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42107, 13772, '1. La presencia de desorientación, apatía y pérdida de memoria orienta hacia el diagnóstico de demencia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42108, 13772, '2. La presencia de temblor de reposo, marcha sin balanceo y amimia facial orienta el diagnóstico hacia enfermedad de Parkinson.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42109, 13772, '3. La presencia de hipercolesterolemia, bradipsiquia, bradicardia y estreñimiento orienta hacia el diagnóstico de hipotiroidismo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42110, 13772, '4. El inicio reciente de tratamiento con betabloqueantes y antiinflamatorios no esteroideos puede justificar la aparición de un síndrome depresivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42111, 13773, '1. La hipomanía casi nunca es motivo de consulta y debe buscarse en la anamnesis de los episodios depresivos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42112, 13773, '2. El antecedente de hipomanía en un paciente con episodio depresivo mayor modifica el diagnóstico de trastorno depresivo e influye en la decisión terapéutica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42113, 13773, '3. Los pacientes con hipomanía pueden sentirse más activos y sociables, aunque generalmente su comportamiento resulta algo inapropiado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42114, 13773, '4. Estos pacientes presentar síntomas psicóticos, como ideas delirantes de grandiosidad.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42115, 13774, '1. Trastorno obsesivo-compulsivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42116, 13774, '2. Estrés postraumático.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42117, 13774, '3. Trastorno antisocial de la personalidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42118, 13774, '4. Dependencia de alcohol.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42119, 13775, '1. Hidratación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42120, 13775, '2. Hemodiálisis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42121, 13775, '3. Lavado gástrico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42122, 13775, '4. Aminofilina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42123, 13776, '1. Proceder a un ingreso hospitalario recurriendo a un internamiento involuntario si el paciente se niega a ingresar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42124, 13776, '2. Intentar tranquilizar al paciente verbalmente y con fármacos que disminuyan la agitación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42125, 13776, '3. Intentar convencer al paciente de que debe ingresar y si se niega dar el alta y recomendar acudir a su centro de salud mental.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42126, 13776, '4. Informar a la familia de la necesidad de una hospitalización para poder tratar al paciente, ya que se va a negar a tomar medicación voluntariamente por carecer de conciencia de enfermedad.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42127, 13777, '1. Trastorno adaptativo.', false, 1);
