INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42156, 13783, '2. Trastorno Bipolar II.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42157, 13783, '3. Trastorno de adaptación.', true, 3);
