INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42159, 13783, '5. Ciclotimia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42160, 13784, '1. El trastorno depresivo mayor tiene el doble de prevalencia en mujeres que en varones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42161, 13784, '2. El trastorno bipolar I tiene doble prevalencia en varones que en mujeres.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42162, 13784, '3. Los episodios maníacos son más frecuentes en los varones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42163, 13784, '4. El trastorno bipolar I es menos frecuente que el trastorno depresivo mayor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42164, 13784, '5. El trastorno bipolar I comienza más precoz- mente que el trastorno depresivo mayor.', false, 5);
