INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42178, 13787, '4. Trastorno somatomorfo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42179, 13787, '5. Depresión endógena.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42180, 13788, '1. A lo largo de la vida, aproximadamente un 15% de la población sufre un episodio depresivo mayor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42181, 13788, '2. Cerca de un 8% de los pacientes que atiende un médico de Atención Primaria podría recibir un diagnóstico de depresión mayor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42182, 13788, '3. Hasta un 15% de los casos de depresión mayor son secundarios a una enfermedad médica somática o al abuso de substancias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42183, 13788, '4. Cuando se sospecha que un paciente sufre un episodio depresivo mayor, debe evitarse hacer preguntas directas al paciente sobre ideas o proyectos suicidas, porque tal pregunta aumenta el riesgo de suicidio un 35%.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42184, 13788, '5. Cerca del 15% de los pacientes con depresión mayor que no reciben tratamiento se suicidan.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42185, 13789, '1. Esquizofrenias paranoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42186, 13789, '2. Hipocondríacos.', false, 2);
