INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42219, 13796, '3. Es preciso descartar una taquicardia auricular paroxística.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42220, 13796, '4. El diagnóstico más probable es un trastorno por ansiedad generalizada.', true, 4);
