INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42318, 13818, '4. La terapia conductista es escasamente eficaz en el TOC.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42319, 13818, '5. Los fármacos de primera elección son los inhibidores selectivos de la recaptación de la serotonina (ISRS) o la clomipramina.', false, 5);
