INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42776, 13920, '1. Se trata de un asma eosinofílica (T2) y una buena opción de tratamiento sería añadir omalizumab.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42777, 13920, '2. Se trata de un asma eosinofílica (T2) y una buena opción de tratamiento sería añadir mepolizumab.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42778, 13920, '3. Se trata de un asma no T2 y la mejor opción de tratamiento sería un antileucotrieno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42779, 13920, '4. Se trata de un asma no T2 y la mejor opción de tratamiento sería añadir benralizumab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42780, 13921, '1. Los linfocitos B son los responsables de la coordinación de la respuesta inflamatoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42781, 13921, '2. En el asma bronquial hay un predominio de fenotipo linfocitario TH1.', false, 2);
