INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42783, 13921, '4. La población de linfocitos T reguladores (CD4+y CD25+) está aumentada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42784, 13922, '1. Se deben administrar de forma urgente agonistas beta2 nebulizados y, en caso de ausencia de respuesta temprana, añadir corticoides intravenosos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42785, 13922, '2. Antes de iniciarse el tratamiento debe realizase radiografía de tórax, gasometría arterial y analítica general para establecer el diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42786, 13922, '3. Los corticoides inhalados estarían contraindicados por aumentar el riesgo de neumonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42787, 13922, '4. Como primera elección se deben administrar anticolinérgicos nebulizados, debido a la ausencia de respuesta a los agonistas beta2.', false, 4);
