INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42879, 13943, '1. Se trata de una alteración ventilatoria mixta de predominio restrictivo. Para el estudio de las causas se debe realizar estudio funcional completo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42880, 13943, '2. Se puede establecer el diagnóstico de enfermedad pulmonar obstructiva crónica. Se debe solicitar TC torácica para confirmar la existencia de enfisema.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42881, 13943, '3. Se trata de una alteración ventilatoria mixta con un componente obstructivo grave. Probable EPOC en la que, una vez confirmada la ausencia de reversibilidad, se puede iniciar tratamiento con corticoides inhalados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42882, 13943, '4. Presenta una alteración ventilatoria mixta con componente obstructivo grave que sugiere EPOC. Una vez confirmada la ausencia de reversibilidad, se puede iniciar tratamiento broncodilatador.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42883, 13944, '1. Iniciar oxigenoterapia crónica domiciliaria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42884, 13944, '2. Optimizar el tratamiento broncodilatador.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42885, 13944, '3. Optimizar el tratamiento broncodilatador e iniciar oxigenoterapia crónica domiciliaria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42886, 13944, '4. Iniciar oxigenoterapia crónica domiciliaria y ventilación mecánica no invasiva domiciliaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42887, 13945, '1. No está indicada por deprimir el centro respiratorio y no mejorar la disnea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42888, 13945, '2. Está indicada únicamente cuando la saturación de O2, sin oxigenoterapia, se mantiene por debajo del 90 %.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42889, 13945, '3. Está indicada porque existen síntomas y signos claros de empeoramiento grave y mal pronóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42890, 13945, '4. Estaría indicada únicamente cuando hay evidencia de insuficiencia respiratoria grave medida por gasometría arterial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42891, 13946, '1. Parche cutáneo de nicotina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42892, 13946, '2. Bupropión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42893, 13946, '3. Vareniclina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42894, 13946, '4. Cigarrillo electrónico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42895, 13947, '1. Tratamiento regular con broncodilatadores muscarínicos de acción prolongada (LAMA).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42896, 13947, '2. Tratamiento regular con broncodilatadores beta- adrenérgicos de acción prolongada (LABA).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42897, 13947, '3. Tratamiento con LABA más glucocorticoides inhalados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42898, 13947, '4. Tratamiento no farmacológico', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42899, 13948, '1. En este caso es preferible administrar prednisona vía intravenosa ya que es más efectiva que la administración oral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42900, 13948, '2. Una buena opción sería administrar prednisona 40 mg/día vía oral durante 5 días', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42901, 13948, '3. La dosis de prednisona debe ser cómo mínimo 1 mg/kg de peso al día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42902, 13948, '4. La prednisona debe pautarse de tal forma que la disminución de la dosis se realice de forma paulatina durante 10 días', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42903, 13949, '1. Iniciar ventilación mecánica no invasiva.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42904, 13949, '2. Proceder a la intubación orotraqueal e iniciar ventilación mecánica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42905, 13949, '3. Incrementar la oxigenoterapia hasta obtener una SatO2 de al menos 99 %.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42906, 13949, '4. Combinar benzodiacepinas con altos flujos de oxígeno para asegurar una disminución de la taquipnea y mejorar el patrón ventilatorio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42907, 13950, '1. Predominio de las lesiones enfisematosas en lóbulos superiores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42908, 13950, '2. FEV1<40%.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42909, 13950, '3. Lesiones enfisematosas heterogéneas de distribución difusa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42910, 13950, '4. Capacidad de esfuerzo reducida tras realizar programa de rehabilitación respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42911, 13951, '1. Valoración de la disnea (MRC).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42912, 13951, '2. Distancia recorrida (metros).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42913, 13951, '3. Índice de masa corporal (IMC).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42914, 13951, '4. Capacidad vital forzada (FVC).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42915, 13952, '1. FEV1 (flujo espiratorio en el primer segundo) menor del 80%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42916, 13952, '2. DLCO (capacidad de difusión) normal.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42917, 13952, '3. Relación FEV1/FVC menor del 70%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42918, 13952, '4. TLC (capacidad pulmonar total) aumentada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42919, 13953, '1. Oxigenoterapia en pacientes con hipoxemia crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42920, 13953, '2. Cirugía de reducción de volumen en pacientes seleccionados con enfisema.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42921, 13953, '3. Tratamiento con N-acetilcisteína.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42922, 13953, '4. Interrupción del tabaquismo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42923, 13954, '1. Ajuste del tratamiento inhalado con bronco-dilatadores de larga duración combinando anticolinérgicos y beta-2 adrenérgicos con glucocorticoides inhalados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42924, 13954, '2. Iniciar pauta de glucocorticoides orales durante 6 meses para el control de las exacerbaciones.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42925, 13954, '3. Comprobar que el paciente realiza correctamente la técnica inhalatoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42926, 13954, '4. Iniciar pauta de oxigenoterapia crónica domiciliaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42927, 13955, '1. Carcinoma pulmonar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42928, 13955, '2. Bronquiectasias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42929, 13955, '3. Fibrosis pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42930, 13955, '4. Cardiopatía cianótica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42931, 13956, '1. Disminución de la capacidad de difusión para el monóxido de carbono.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42932, 13956, '2. Disminución de los niveles de saturación de la oximetría durante las pruebas de esfuerzo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42933, 13956, '3. Patrón obstructivo grave en la espirometría (FEV1<50%).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42934, 13956, '4. Aumento del volumen residual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42935, 13957, '1. Asma bronquial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42936, 13957, '2. Fibrosis pulmonar idiopática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42937, 13957, '3. EPOC fenotipo enfisema.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42938, 13957, '4. Restricción torácica por cifoescoliosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42939, 13957, '5. Bronquiectasias.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42940, 13958, '1. La indicación de tratamiento quirúrgico será en aquellos pacientes que presenten al mismo tiempo una insuficiencia cardíaca congestiva moderada/grave.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42941, 13958, '2. La presencia de una presión sistólica de la arteria pulmonar inferior a 45 es una contraindicación absoluta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42942, 13958, '3. La EPOC con predominancia enfisematosa en lóbulos inferiores y medio asociada a patología pleural se asocia a mejores resultados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42943, 13958, '4. La presencia de enfisema de distribución difusa con un FEV1>20% y DLCO<20% son indicadores de buen pronóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42944, 13958, '5. La rehabilitación prequirúrgica junto con la distribución del enfisema en los lóbulos superiores y la capacidad de realizar ejercicio físico postoperatorio hace que los resultados de la cirugía sean beneficiosos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42945, 13959, '1. El empleo de bromuro de ipratropio se ha asociado a una disminución de la mortalidad.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42946, 13959, '2. En un paciente con saturación arterial de oxígeno inferior al 90% y signos de hipertensión pulmonar debe plantearse el uso de oxígeno complementario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42947, 13959, '3. El uso regular de corticoides inhalados no influye sobre el ritmo de deterioro de la función pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42948, 13959, '4. Los agonistas betaadrenérgicos de larga duración proporcionan beneficios asintomáticos similares a los del bromuro de ipratropio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42949, 13959, '5. En los pacientes hospitalizados por exacerbación se ha demostrado que la corticoterapia acorta el tiempo de hospitalización.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42950, 13960, '1. Iniciar el tratamiento con diuréticos intravenosos, oxígeno con mascarilla a alto flujo al 50% y seguir con el resto del tratamiento ya prescrito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42951, 13960, '2. Iniciar el tratamiento con aerosoles de salbutamol y esteroides, añadir al tratamiento antibiótico una cefalosporina, intensificar la oxigenoterapia con oxígeno en gafas nasales a 4 litros por minuto y mantener deflazacort.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42952, 13960, '3. Iniciar el tratamiento de la acidosis con bicarbonato 1M, corregir la hiperglucemia, mantener tratamiento antibiótico y prescribir esteroides más diuréticos intravenosos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42953, 13960, '4. Dada la situación de gravedad del paciente se procedería a la intubación orotraqueal previa preparación (preoxigenación y premedicación) y avisar a Medicina Intensiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42954, 13960, '5. Iniciar el tratamiento con ventilación mecánica no invasiva (modo presión positiva de dos niveles) y esteroides intravenosos y mantener tratamiento antibiótico por vía intravenosa.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42955, 13961, '1. El hábito tabáquico es el factor más importante para desarrollar EPOC.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42956, 13961, '2. Contrariamente al asma, no hay componente Inflamatorio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42957, 13961, '3. El factor genético para desarrollar EPOC mejor documentado es el déficit de alfa1antitripsina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42958, 13961, '4. Las acropaquias no son características de la EPOC y su presencia debe sugerir bronquiectasias asociadas o carcinoma broncopulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42959, 13961, '5. Espirométricamente, se detecta obstrucción por un cociente FEV1/FVC inferior a 0,70.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42960, 13962, '1. Poligrafía respiratoria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42961, 13962, '2. Ecocardiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42962, 13962, '3. Tomografía computarizada torácica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42963, 13962, '4. Gammagrafía pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42964, 13962, '5. Punción de médula ósea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42965, 13963, '1. FEV1 menor del 80%.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42966, 13963, '2. DLCO disminuida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42967, 13963, '3. Cociente FEV1/FVC inferior al 0.7.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42968, 13963, '4. Volúmenes pulmonares disminuidos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42969, 13963, '5. Prueba broncodilatadora negativa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42970, 13964, '1. Corticoide inhalado diario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42971, 13964, '2. Oxigenoterapia domiciliaria con fuente portátil de oxígeno para deambulación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42972, 13964, '3. Antagonista de leucotrienos por vía oral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42973, 13964, '4. Corticoide oral durante tres meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42974, 13964, '5. Tiotropio inhalado.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42975, 13965, '1. Grado de disnea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42976, 13965, '2. Índice de masa corporal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42977, 13965, '3. Volumen espiratorio forzado en el primer segundo (FEV1).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42978, 13965, '4. Distancia recorrida en la prueba de la marcha de 6 minutos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42979, 13965, '5. Puntuación obtenida en los cuestionarios de calidad de vida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42980, 13966, '1. Síndrome de apnea del sueño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42981, 13966, '2. Hipotiroidismo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42982, 13966, '3. Osteoporosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42983, 13966, '4. Anemia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42984, 13966, '5. Ansiedad/depresión.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42985, 13967, '1. Iniciar tratamiento con broncodilatadores inhalados.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42986, 13967, '2. Realizar radiografía de tórax y espirometría con prueba broncodilatadora.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42987, 13967, '3. Pautar corticoides orales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42988, 13967, '4. Realizar TC torácica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42989, 13967, '5. Realizar gasometría arterial basal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42990, 13968, '1. Mejora la calidad de vida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42991, 13968, '2. Mejora la disnea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42992, 13968, '3. Mejora la capacidad del ejercicio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42993, 13968, '4. Disminuye la frecuencia de hospitalización.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42994, 13968, '5. Disminuye la mortalidad.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42995, 13969, '1. Aumentaría el flujo del oxígeno porque tiene acidosis respiratoria aguda e hipoxemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42996, 13969, '2. Iniciaría ventilación mecánica no invasiva porque tiene una insuficiencia respiratoria hipercápnica aguda con acidosis respiratoria moderada.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42997, 13969, '3. Añadiría bicarbonato sódico para corregir la acidosis metabólica aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42998, 13969, '4. El paciente no tiene insuficiencia respiratoria por lo que continuaría con la misma pauta farmacológica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (42999, 13969, '5. Añadiría aminofilina intravenosa como estimulante respiratorio, ya que aprecio hipoxemia e hipercapnia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43000, 13970, '1. Muy leve.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43001, 13970, '2. Leve.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43002, 13970, '3. Moderada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43003, 13970, '4. Grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43004, 13970, '5. Muy grave.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43005, 13971, '1. Cáncer de pulmón.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43006, 13971, '2. Fibrosis pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43007, 13971, '3. Bronquiectasias.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43008, 13971, '4. Absceso pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43009, 13971, '5. Empiema.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43010, 13972, '1. Teofilina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43011, 13972, '2. Glucocorticoides inhalados.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43012, 13972, '3. Antagonistas de los receptores de los leucotrienos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43013, 13972, '4. N-acetilcisteína.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43014, 13972, '5. Cromoglicato.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43015, 13973, '1. Una obstrucción al flujo aéreo leve.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43016, 13973, '2. Una obstrucción al flujo aéreo moderada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43017, 13973, '3. Una obstrucción al flujo aéreo grave.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43018, 13973, '4. Una obstrucción al flujo aéreo muy grave.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43019, 13973, '5. Una obstrucción al flujo aéreo grave asociada a restricción al menos moderada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43020, 13974, '1. Retirar oxígeno y administrar bicarbonato sódico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43021, 13974, '2. Reducir el flujo de oxígeno a 1 L/min y administrar bicarbonato sódico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43022, 13974, '3. Mantener flujo de oxígeno y administrar acetazolamida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43023, 13974, '4. Intubación y ventilación mecánica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43024, 13974, '5. Administrar epinefrina iv. y bicarbonato sódico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43025, 13975, '1. Por alteraciones en la relación “ventilación/perfusión”.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43026, 13975, '2. Por vaciado incompleto de unidades alveolares a causa del aumento de la frecuencia respiratoria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43027, 13975, '3. Por vaciado incompleto de unidades alveolares a causa de una disminución en la “orden respiratoria”.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43028, 13975, '4. Por los problemas mecánicos asociados a una alcalosis metabólica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43029, 13975, '5. Por los problemas mecánicos asociados a una alcalosis respiratoria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43030, 13976, '1. Realizar una espirometría con prueba broncodilatadora para demostrar la existencia de obstrucción crónica al flujo aéreo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43031, 13976, '2. Iniciar inmediatamente tratamiento con altas dosis de broncodilatadores, corticoides inhalados y teofilina para mejorar su situación clínica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43032, 13976, '3. Cuestionar el diagnóstico de EPOC y valorar otras patologías que cursen con insuficiencia cardiaca derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43033, 13976, '4. Ampliar el estudio del paciente con radiografía de tórax y ecocardiograma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43034, 13976, '5. Valorar la existencia de patología vascular pulmonar si se descarta alteración parenquimatosa pulmonar y enfermedad cardiológica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43035, 13977, '1. Espiración alargada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43036, 13977, '2. Cianosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43037, 13977, '3. Acropaquias.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43038, 13977, '4. Disminución del murmullo vesicular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43039, 13977, '5. Edemas periféricos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43040, 13978, '1. Formoterol y salmeterol/fluticasona, pautados de forma continua, y salbutamol a demanda, porque el paciente presenta una buena respuesta broncodilatadora.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43041, 13978, '2. Bromuro de tiotropio y budesonida/formoterol, pautados de forma continua, y salbutamol con o sin bromuro de ipratropio, de rescate, y rehabilitación respiratoria, dada la gravedad clínico-funcional y el antecedente de exacerbaciones repetidas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43042, 13978, '3. Xinafoato de salmeterol y formoterol/budesonida, pautados de forma continua, y salbutamol de rescate, con oxigenoterapia continua porque el paciente muy posiblemente presente hipoxemia arterial al esfuerzo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43043, 13978, '4. Bromuro de tiotropio, salmeterol/fluticasona, pautados de forma continua, y terbutalina de rescate, al margen de su hiperreactividad bronquial, con sesiones de ventilación mecánica no invasiva ambulatoria (2 horas 3 veces por semana).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43044, 13978, '5. Bromuro de tiotropio y budesonida/formoterol, pautados de forma continua, salbutamol de rescate, n-acetil cisteina y antibioterapia intermitente con levofloxacino.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43045, 13979, '1. Grado 0.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43046, 13979, '2. Grado I.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43047, 13979, '3. Grado II.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43048, 13979, '4. Grado III.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43049, 13979, '5. Grado IV.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43050, 13980, '1. AngioTC helicoidal con contraste.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43051, 13980, '2. Gammagrafía pulmonar de perfusión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43052, 13980, '3. Radiografía de tórax.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43053, 13980, '4. Ecocardiografía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43054, 13981, '1. Heparina de bajo peso molecular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43055, 13981, '2. Rivaroxaban.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43056, 13981, '3. Acenocumarol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43057, 13981, '4. Filtro de vena cava inferior.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43058, 13982, '1. 630 ng/ml (normal <500). Se muestra la radiografía de tórax póstero-anterior. ¿Cuál es el diagnóstico de sospecha y la actitud a seguir?:', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43059, 13982, '1. Solicitar angioTC de arterias pulmonares por sospecha de tromboembolismo pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43060, 13982, '2. Iniciar tratamiento antibiótico por sospecha de neumonía sin signos de complicación y control radiológico en 4-6 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43061, 13982, '3. Derivarle a consulta especializada por sospecha radiológica de carcinoma de pulmón.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43062, 13982, '4. Solicitar radiografía en decúbito lateral derecho por sospecha de derrame pleural encapsulado previo a toracocentesis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43063, 13983, '1. Fibrilación auricular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43064, 13983, '2. Tromboembolismo pulmonar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43065, 13983, '3. Síndrome coronario sin elevación del segmento ST (SCASEST).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43066, 13983, '4. Infarto agudo de miocardio de cara diafragmática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43067, 13984, '1. Heparina sódica en perfusión intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43068, 13984, '2. Tromboendarectomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43069, 13984, '3. Fibrinolisis sistémica con rt-PA (alteplase) 100 mg intravenoso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43070, 13984, '4. Filtro en vena cava inferior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43071, 13985, '1. Confirmar el diagnóstico con una angioTC tórax.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43072, 13985, '2. Anticoagular con heparina y monitorización estrecha de constantes vitales.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43073, 13985, '3. Administrar diuréticos de asa endovenosos, nitritos y antiagregantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43074, 13985, '4. Administrar fibrinolíticos ante la gravedad del cuadro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43075, 13986, '1. Iloprost.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43076, 13986, '2. Riociguat.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43077, 13986, '3. Treprostinil.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43078, 13986, '4. Epoprostenol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43079, 13987, '1. Hipertensión arterial pulmonar idiopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43080, 13987, '2. Hipertensión arterial pulmonar asociada a conectivopatía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43081, 13987, '3. Hipertensión pulmonar secundaria a cardiopatía izquierda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43082, 13987, '4. Hipertensión pulmonar tromboembólica crónica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43083, 13988, '1. Trastorno de la caja torácica o neuromuscular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43084, 13988, '2. Enfisema.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43085, 13988, '3. Enfermedad pulmonar vascular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43086, 13988, '4. Asma.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43087, 13989, '1. Neumonía bacteriana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43088, 13989, '2. Empiema.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43089, 13989, '3. Infarto sublingual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43090, 13989, '4. Tuberculosis pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43091, 13990, '1. El antecedente de cáncer de mama.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43092, 13990, '2. La historia de osteoporosis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43093, 13990, '3. El antecedente de haber estado más de 3 días en reposo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43094, 13990, '4. La presencia de edema unilateral de la pantorrilla derecha.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43095, 13991, '1. Tromboembolismo pulmonar', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43096, 13991, '2. Accidente cerebrovascular agudo de territorio posterior', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43097, 13991, '3. Síndrome coronario agudo', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43098, 13991, '4. Shock hipovolémico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43099, 13991, '5. Edema agudo de pulmón secundario a flutter auricular', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43100, 13992, '1. Ecocardiograma trastorácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43101, 13992, '2. Gammagrafía pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43102, 13992, '3. AngioTC pulmonar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43103, 13992, '4. Electrocardiograma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43104, 13992, '5. Radiografía de tórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43105, 13993, '1. Pautar morfina, furosemida y dopamina y vigilar evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43106, 13993, '2. Se debe solicitar determinación de dímero D para confirmar o descartar el diagnóstico de embolia de pulmón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43107, 13993, '3. Hay alta sospecha de embolia de pulmón y se debe iniciar tratamiento con heparina de bajo peso molecular sin realizar más estudios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43108, 13993, '4. Existe alta sospecha de embolia de pulmón masiva y se debe realizar angioTAC para confirmarla y valorar tratamiento fibrinolítico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43109, 13993, '5. Se debe solicitar determinación de NTproBNPy Troponinas y conocer el resultado antes de realizar un nuevo procedimiento diagnóstico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43110, 13994, '1. Heparina no fraccionada, 10000 U iv ante la sospecha clínica. Fibrinolisis con activador tisular del plasminógeno (tPA), 100 mg iv, una vez confirmado el diagnóstico.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43111, 13994, '2. Enoxaparina: 80 mg sc cada 12 horas, comenzando ante la sospecha diagnóstica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43112, 13994, '3. Enoxaparina: 80 mg sc cada 12 horas, comenzando tras la confirmación diagnóstica', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43113, 13994, '4. Fondaparinux, 7.5 mg sc diarios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43114, 13994, '5. Tromboendarterectomía pulmonar de urgencia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43115, 13995, '1. Iniciar ventilación mecánica no invasiva y broncodilatadores', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43116, 13995, '2. Cefotaxima iv 2 g/8 horas más azitromicina iv 500mg/día y tubo de drenaje pleural.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43117, 13995, '3. Morfina iv 5 mg en dos minutos e iniciar infusión de dopamina 2-5 μg/ kg/ min.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43118, 13995, '4. Activador tisular del plasminógeno 100 mg iv en dos horas seguida de anticoagulación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43119, 13995, '5. Aspirina 325 mg por vía oral y nitroglicerina sublingual.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43120, 13996, '1. Shock séptico', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43121, 13996, '2. Disfunción progresiva del ventrículo derecho', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43122, 13996, '3. Hemoptisis masiva', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43123, 13996, '4. Infarto agudo de miocardio', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43124, 13996, '5. Hemorragia cerebral', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43125, 13997, '1. Colocación de sonda nasogástrica y determinación de hematocrito.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43126, 13997, '2. Electrocardiograma y determinación de Dímeros-D, troponina y BNP.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43127, 13997, '3. Gammagrafía de ventilación/perfusión.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43128, 13997, '4. TAC craneal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43129, 13997, '5. AngioTAC torácico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43130, 13998, '1. Ecocardiograma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43131, 13998, '2. Angiografía coronaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43132, 13998, '3. AngioTAC pulmonar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43133, 13998, '4. Repetir determinaciones de troponina y mioglobina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43134, 13998, '5. Hemocultivos y cultivos de esputos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43135, 13999, '1. Se debe realizar un estudio complejo para llegar a un diagnóstico inicial, pudiendo descartarse de entrada la existencia de embolia de pulmón dado que se realizó tratamiento profiláctico con heparina tras la cirugía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43136, 13999, '2. Aunque la probabilidad clínica de embolia de pulmón es baja debe realizarse una TAC de arterias pulmonares para descartarla, antes de iniciarse ningún tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43137, 13999, '3. Debe realizarse la determinación dímero D y si es positiva iniciarse tratamiento con heparina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43138, 13999, '4. La probabilidad clínica de embolia de pulmón es alta debiendo iniciarse tratamiento con heparina y después realizar con una TAC de arterias pulmonares para confirmar el diagnóstico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43139, 13999, '5. El paciente probablemente padece una embolia de pulmón y debe iniciar tratamiento fibrinolítico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43140, 14000, '1. No es necesario realizar más pruebas y debe iniciarse anticoagulación, ya que tiene un D-Dímero elevado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43141, 14000, '2. La neumonía justifica todos los hallazgos, por lo que la opción terapéutica es el levofloxacino', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43142, 14000, '3. La probabilidad de embolia de pulmón es baja, aunque estaría indicada la heparina de bajo peso molecular en dosis profilácticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43143, 14000, '4. No se puede descartar que tenga una embolia de pulmón, por lo que habría que realizar una gammagrafía de perfusión', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43144, 14000, '5. Debería realizarse una TAC helicoidal tras iniciar heparina Sc', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43145, 14001, '1. Infección respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43146, 14001, '2. Infarto de miocardio con Síndrome de Dressler.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43147, 14001, '3. Taponamiento cardíaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43148, 14001, '4. Tromboembolismo pulmonar masivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43149, 14001, '5. Dehiscencia de sutura con distress respiratorio.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43150, 14002, '1. Es imprescindible la realización de una biopsia por cirugía torácica ante la elevada posibilidad de malignidad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43151, 14002, '2. Al tratarse de un NPS de pequeño tamaño (< 1 cm) la actitud más adecuada es la de seguimiento radiológico estrecho con TC al mes y a los 3, 6 y 12 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43152, 14002, '3. Ante la alta probabilidad de malignidad se recomienda realizar una prueba de esfuerzo cardiopulmonar y si el consumo máximo de oxígeno es <10 mL/kg/min remitir a cirugía torácica para resección.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43153, 14002, '4. Se debe realizar una prueba de esfuerzo cardiopulmonar y si el consumo máximo de oxígeno es <10 mL/kg/min el manejo terapéutico más seguro es por medio de radioterapia estereotáxica fraccionada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43154, 14003, '1. T1N1M0.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43155, 14003, '2. T1N0M0.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43156, 14003, '3. T1N0M1.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43157, 14003, '4. T2N0M0.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43158, 14004, '1. Es una gammagrafía ósea normal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43159, 14004, '2. No está indicada la gammagrafía ósea en el estudio de extensión, ya que el sarcoma de Ewing no desarrolla metástasis óseas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43160, 14004, '3. Existe afectación ósea metastásica diseminada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43161, 14004, '4. El único hallazgo anormal es el acúmulo patológico del radiotrazador en el tumor costal conocido.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43162, 14005, '1. Atelectasia de lóbulo inferior izquierdo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43163, 14005, '2. Derrame pleural subpulmonar izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43164, 14005, '3. Hernia de Bochdalek o defecto diafragmático posterior izquierdo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43165, 14005, '4. Hiperinsuflación pulmonar derecha por bronquiectasias e impactos mucosos basales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43166, 14006, '1. Infiltración por adenocarcinoma.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43167, 14006, '2. Inflamación aguda con abscesificación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43168, 14006, '3. Inflamación granulomatosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43170, 14007, '1. Neoplasia pulmonar con metástasis ganglionares ipsilaterales.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43171, 14007, '2. Neoplasia pulmonar avanzada con metástasis extratorácicas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43172, 14007, '3. Hamartomas pulmonares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43173, 14007, '4. Tuberculosis pulmonar y ganglionar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43174, 14008, '1. Está contraindicada en quimio-resistencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43175, 14008, '2. Solo se emplea en el síndrome de vena cava superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43176, 14008, '3. Es más eficaz después de la quimioterapia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43177, 14008, '4. Se recomienda de forma simultánea con los dos primeros ciclos de quimioterapia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43178, 14009, '1. Cáncer de célula no pequeña estadio I.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43179, 14009, '2. Nódulo pulmonar solitario.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43180, 14009, '3. Cáncer de célula no pequeña estadio II.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43181, 14009, '4. Cáncer de célula pequeña.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43182, 14010, '1. Quimioterapia neoadyuvante con quimiorradioterapia combinada, seguida de cirugía.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43183, 14010, '2. Quimioterapia neoadyuvante sin cirugía, seguida de radioterapia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43184, 14010, '3. Cirugía seguida de quimiorradioterapia combinada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43185, 14010, '4. Radioterapia sin quimioterapia, seguida de cirugía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43186, 14011, '1. Bronquio principal derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43187, 14011, '2. Bronquio principal izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43188, 14011, '3. Bronquio lobar medio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43189, 14011, '4. Bronquio intermediario.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43190, 14012, '1. Se observa una consolidación alveolar en el lóbulo superior derecho. El diagnóstico más probable es una neumonía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43191, 14012, '2. La imagen radiológica corresponde a una lesión extrapulmonar, puede tratarse de una masa pleural o de una masa de la pared torácica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43192, 14012, '3. Hay un ensanchamiento mediastínico que se extiende a la región superior del hemitórax derecho, por lo que la principal sospecha es que se trate de un linfoma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43193, 14012, '4. El paciente tiene una atelectasia del lóbulo superior derecho, la primera sospecha diagnóstica es un carcinoma broncogénico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43194, 14013, '1. Resección quirúrgica seguida de quimioterapia adyuvante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43195, 14013, '2. Cirugía más radioterapia postoperatoria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43196, 14013, '3. Quimioterapia neoadyuvante seguida de cirugía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43197, 14013, '4. Quimiorradioterapia combinada seguida de cirugía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43198, 14014, '1. Son especialmente frecuentes en pacientes de raza caucásica y excepcionales en población asiática.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43199, 14014, '2. Se localizan mayoritariamente en los exones 19 y 21 del gen.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43200, 14014, '3. Son más frecuentes en adenocarcinomas, en no fumadores y en el sexo femenino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43201, 14014, '4. En pacientes con estadios avanzados, el empleo de inhibidores de la tirosina kinasa (gefitinib o erlotinib), se ha mostrado superior a la quimioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43202, 14015, '1. Tumoración de tejidos blandos de la pared torácica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43203, 14015, '2. Consolidación alveolar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43204, 14015, '3. Atelectasia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43205, 14015, '4. Derrame pleural.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43206, 14016, '1. Al tratarse de una masa anterior no dolorosa, se debe considerar un tumor benigno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43207, 14016, '2. Como primera medida debe descartarse un tumor condroide dado que son los más frecuentes en esta localización.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43208, 14016, '3. No está indicada la realización de una biopsia por el peligro de diseminación local del tumor.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43209, 14016, '4. Es preferible mantener una actitud conservadora, evaluando la evolución y posible crecimiento de la tumoración.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43210, 14017, '1. Neoplasia pulmonar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43211, 14017, '2. Sarcoidosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43212, 14017, '3. Silicosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43213, 14017, '4. Tuberculosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43214, 14018, '1. Quimioterapia previa neumonectomía derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43215, 14018, '2. Cirugía y radioterapia posterior de todas las cadenas ganglionares afectas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43216, 14018, '3. Neumonectomía derecha y quimioterapia posterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43217, 14018, '4. Quimioterapia y radioterapia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43218, 14018, '5. Radioterapia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43219, 14019, '1. Tumor de Pancoast.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43220, 14019, '2. Tumor de mediastino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43221, 14019, '3. Mesotelioma pleural localizado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43222, 14019, '4. Tumor bronquioloalveolar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43223, 14019, '5. Cáncer microcítico de pulmón con metástasis cerebrales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43224, 14020, '1. Adenocarcinoma gástrico', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43225, 14020, '2. Epidermoide esofágico', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43226, 14020, '3. Timoma mediastínico', false, 3);
