INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43228, 14020, '5. Mesotelioma pleural', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43229, 14021, '1. Se emplea un sistema simplificado de estadificación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43230, 14021, '2. La mayoría de los casos se diagnostican en estadios avanzados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43231, 14021, '3. El derrame pericárdico corresponde a la enfermedad avanzada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43232, 14021, '4. La definición del estadio limitado o avanzado depende de que todo el tumor conocido pueda ser contenido en un campo tolerable de radioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43233, 14021, '5. Las adenopatías supraclaviculares contralaterales se consideran generalmente enfermedad avanzada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43234, 14022, '1. Derrame pleural izquierdo encapsulado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43235, 14022, '2. Tumoración de las partes blandas anteriores del tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43236, 14022, '3. Colapso de lóbulo superior izquierdo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43237, 14022, '4. Masa mediastínica anterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43238, 14022, '5. Elevación de la cúpula diafragmática izquierda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43239, 14023, '1. Carcinoma broncogénico central.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43240, 14023, '2. Parálisis frénica izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43241, 14023, '3. Absceso de pared torácica anterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43242, 14023, '4. Mesotelioma pleural izquierdo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43243, 14023, '5. Linfoma mediastínico anterior.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43244, 14024, '1. Estadio I.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43245, 14024, '2. Estadio IIA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43249, 14025, '1. Es obligado hacer la determinación de la mutación del receptor del factor de crecimiento epidérmico (EGFR).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43250, 14025, '2. Gefitinib de entrada es el tratamiento estándar sin determinación de EGFR.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43251, 14025, '3. Tiene un tratamiento estándar basado en camptotecinas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43252, 14025, '4. Cualquier tipo de quimioterapia estándar es válido.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43253, 14025, '5. No hay ningún factor predictivo para esta enfermedad.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43254, 14026, '1. Una consolidación pulmonar en lóbulo superior derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43255, 14026, '2. Una tumoración broncopulmonar central, con adenopatías.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43256, 14026, '3. Un derrame pleural encapsulado cisural.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43257, 14026, '4. Una masa mediastínica anterior.', false, 4);
