INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43260, 14027, '2. Un timoma invasivo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43261, 14027, '3. Un carcinoma indiferenciado de células pequeñas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43262, 14027, '4. Una neumonía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43263, 14027, '5. Un mesotelioma pleural.', false, 5);
