INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43265, 14028, '2. Determinación de anticuerpos anti-Hu en suero.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43266, 14028, '3. Tomografía computarizada (cerebro, tórax y abdomen).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43267, 14028, '4. Gammagrafía pulmonar de ventilación-perfusión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43268, 14028, '5. Fibrobroncoscopia', true, 5);
