INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43289, 14033, '1. Realizar una mediastinoscopia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43290, 14033, '2. Debe contraindicarse la intervención quirúrgica con intención curativa por la edad avanzada del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43291, 14033, '3. Se debe llevar a cabo un test de consumo de oxígeno, dada la limitación respiratoria que presenta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43292, 14033, '4. Debe indicarse la resección quirúrgica (lobectomía del lóbulo inferior del pulmón derecho) de forma directa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43293, 14033, '5. Debe realizarse una punción transtorácica', false, 5);
