INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43295, 14034, '2. Infiltrado alveolar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43296, 14034, '3. Bronquiectasias.', false, 3);
