INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43304, 14036, '1. Broncoscopia.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43305, 14036, '2. Toracocentesis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43306, 14036, '3. Mediastinoscopia.', false, 3);
