INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43308, 14036, '5. Cultivo de esputos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43309, 14037, '1. No es una urgencia oncológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43310, 14037, '2. Los datos clínicos no suelen ser expresivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43311, 14037, '3. La radiografía simple de tórax no permite sospecharlo en la mayoría de las ocasiones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43312, 14037, '4. El 85% de los casos se deben a la existencia de un cáncer de pulmón.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43313, 14037, '5. No responde al tratamiento con radioterapia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43314, 14038, '1. Se trata de la progresión normal de la neumonía y lo único que debemos hacer es esperar a que responda al tratamiento antibiótico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43315, 14038, '2. Podría tratarse de un mesotelioma que pasara desapercibido en la radiografía inicial de urgencias.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43316, 14038, '3. Probablemente se trate de un derrame metaneumonico que debe responder al tratamiento antibiótico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43317, 14038, '4. Dados los antecedentes de tabaquismo del paciente el infiltrado inicialmente interpretado como una neumonía podría tratarse de una neoplasia de pulmón y esta nueva lesión de una metástasis pleural que deberíamos puncionar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43318, 14038, '5. Puede tratarse de una neumonía complicada con un derrame, el líquido debería ser analizado por si es tributario de la colocación de un drenaje pleural.', false, 5);
