INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43320, 14039, '2. Adenocarcinoma metastásico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43321, 14039, '3. Carcinoma de células gigantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43322, 14039, '4. Carcinoma microcítico con Síndrome de secreción inadecuada de ADH (SIADH).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43323, 14039, '5. Tumor carcinoide con metástasis hepáticas.', false, 5);
