INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43328, 14040, '5. Esófago distal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43329, 14041, '1. Língula.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43330, 14041, '2. Lóbulo superior derecho.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43331, 14041, '3. Lóbulo medio.', true, 3);
