INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43333, 14041, '5. Hilio pulmonar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43334, 14042, '1. Indicación de tratamiento quirúrgico sin más estudios previos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43335, 14042, '2. Administración directa de un tratamiento oncológico neoadyuvante', false, 2);
