INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43348, 14044, '5. Solicitar radiografía simple de tórax.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43349, 14045, '1. El paciente presenta un carcinoma broncogénico no microcítico estadio IV (T4N0M0), por lo que no es resecable. Se debe tratar con quimioterapia y radioterapia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43350, 14045, '2. El paciente presenta un carcinoma broncogénico no microcítico estadio clínico IIIB (T4N0M0). La realización de una ecoendoscopia esofágica que determine el grado de afectación de la pared del esófago sería útil para plantear una posible extirpación, aunque se debe empezar con quimioterapia y radioterapia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43351, 14045, '3. El paciente presenta un carcinoma broncogénico no microcítico estadio clínico IIIB (T4N0M0). Se debe operar, extirpando todo el pulmón y la totalidad del esófago.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43352, 14045, '4. El paciente presenta un carcinoma broncogénico no microcítico estadio clínico IV (T4N0M0). La realización de una ecoendoscopia esofágica que determine el grado de afectación de la pared del esófago sería útil para plantear una posible extirpación, aunque se debe empezar con quimioterapia y radioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43353, 14045, '5. El paciente presenta un carcinoma broncogénico no microcítico estadio clínico IIIB (T4N0M0), por lo que en ningún caso es resecable. Se debe administrar tratamiento paliativo con quimioterapia.', false, 5);
