INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43375, 14051, '1. Medidas higiénico-dietéticas y control evolutivo.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43376, 14051, '2. Uvulopalatofaringoplastia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43377, 14051, '3. CPAP(Presión Positiva Continua en la Vía Aérea) nasal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43378, 14051, '4. Ventilación mecánica no invasiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43379, 14051, '5. Oxigenoterapia nocturna.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43380, 14052, '1. Que el paciente no tiene un síndrome de apnea obstructiva del sueño.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43381, 14052, '2. La capacidad vital no se debe medir nunca en decúbito supino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43382, 14052, '3. Que el paciente no tiene un síndrome hepatopulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43383, 14052, '4. Que el paciente no tiene enfisema clínicamente relevante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43384, 14052, '5. Que el paciente no tiene una debilidad clínicamente relevante de los músculos inspiratorios.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43385, 14053, '1. Se trata de un roncador simple que no precisa tratamiento.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43386, 14053, '2. Se trata de un síndrome de apnea del sueño subsidiario de tratamiento con CPAPnasal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43387, 14053, '3. Se trata de un síndrome del sueño subsidiario de dieta hipocalórica y dormir en decúbito lateral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43388, 14053, '4. Se trata de un síndrome de apneas centrales secundarias a la insuficiencia cardiaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43389, 14053, '5. Los resultados de polisomnografía no son compatibles con la historia clínica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43390, 14054, '1. Las apneas e hipopneas nocturna desaparecen cuando se utiliza la CPAP nasal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43391, 14054, '2. La somnolencia y el cansancio diurno experimentarán una mejoría.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43392, 14054, '3. Se producirá un aumento del FEV1.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43393, 14054, '4. La oxigenación durante el sueño mejorará.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43394, 14054, '5. La frecuencia de los despertares breves y los cambios de fase de sueño disminuirán.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43395, 14055, '1. Drenaje cerrado con un tubo de tórax con instilación de fibrinolíticos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43396, 14055, '2. Toracocentesis repetidas para extraer todo el derrame posible.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43397, 14055, '3. Decorticación quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43398, 14055, '4. Ampliación de la cobertura antibiótica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43399, 14056, '1. La presencia de derrame pleural en paciente con exposición conocida a asbesto indica mesotelioma maligno.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43400, 14056, '2. Las opacidades lineales irregulares en bases pulmonares son los signos radiográficos característicos de asbestosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43401, 14056, '3. El cáncer pulmonar es la tumoración más frecuente relacionada con la exposición al asbesto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43402, 14056, '4. Las placas pleurales indican que hubo tan sólo exposición, pero no afectación pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43403, 14057, '1. Aneurisma aórtico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43404, 14057, '2. Pericarditis aguda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43405, 14057, '3. Neumonía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43406, 14057, '4. Hernia hiatal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43407, 14058, '1. Soplo tubárico y crepitantes en base derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43408, 14058, '2. Disminución del murmullo vesicular en la base derecha, disminución de las vibraciones vocales y matidez a la percusión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43409, 14058, '3. Disminución/abolición de las vibraciones vocales y timpanismo en la percusión en hemitorax derecho.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43410, 14058, '4. Roncus y sibilancias dispersas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43411, 14059, '1. La tomografía por emisión de positrones permite llegar al diagnóstico específico si se observa un gran hipermetabolismo a nivel pleural.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43412, 14059, '2. El diagnóstico más probable es el de carcinoma broncogénico, por lo que deberá realizarse, en primer lugar, una fibrobroncoscopia diagnóstica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43413, 14059, '3. La primera maniobra diagnóstica debe ser una toracocentesis. En caso de que no se consiga un diagnóstico etiológico, debe plantearse una toracoscopia diagnóstica para toma de una biopsia pleural.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43414, 14059, '4. Al tratarse de un derrame pleural atípico, debe descartarse una causa infecciosa, por lo que deberá realizase una toracocentesis con análisis bioquímico y cultivo para indicar un posible drenaje pleural.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43415, 14060, '1. Derrame pleural tipo trasudado, por tanto es necesario tratar la causa subyacente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43416, 14060, '2. Derrame pleural tipo exudado, probablemente secundario a insuficiencia cardíaca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43417, 14060, '3. Derrame pleural tipo exudado del que se debe investigar la causa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43418, 14060, '4. Los valores medidos no son creíbles y se requiere la toma de una nueva muestra. Pregunta', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43419, 14061, '1. Instaurar ventilación mecánica no invasiva y solicitar transfusión sanguínea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43420, 14061, '2. Analgesia, oxigenoterapia, solicitar transfusión sanguínea e indicar una intervención quirúrgica urgente.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43421, 14061, '3. Intubación orotraqueal, solicitar transfusión sanguínea y observación para, en caso de empeoramiento, indicar la intervención quirúrgica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43422, 14061, '4. Intubación orotraqueal y realización de una TC urgente para valoración exacta de las lesiones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43423, 14062, '1. Realizar una TC torácica de alta resolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43424, 14062, '2. Repetir la radiografía añadiendo una proyección lateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43425, 14062, '3. Realizar fibrinolisis urgente con 100 mg de tenecteplasa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43426, 14062, '4. Colocar un drenaje torácico en la cavidad pleural derecha.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43427, 14063, '1. Insuficiencia cardiaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43428, 14063, '2. Síndrome de Meigs.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43429, 14063, '3. Quilotórax.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43430, 14063, '4. Tuberculosis pleural.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43431, 14064, '1. Se puede establecer el diagnóstico de empiema pleural si se realiza una toracocentesis y el pH del líquido pleural es de 7,4.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43432, 14064, '2. El diagnóstico de empiema pleural solo queda confirmado si se halla un microorganismo en el cultivo de líquido pleural.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43433, 14064, '3. Debe sospecharse un empiema pleural si el paciente presenta persistencia de fiebre y leucocitosis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43434, 14064, '4. La presencia de un derrame pleural es suficiente para establecer el diagnóstico de empiema pleural y colocar un drenaje pleural derecho.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43435, 14065, '1. Taponamiento cardíaco traumático.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43436, 14065, '2. Neumotórax a tensión derecho.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43437, 14065, '3. Hemotórax masivo derecho.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43438, 14065, '4. Contusión pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43439, 14066, '1. Hemotórax espontáneo tardío.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43440, 14066, '2. Mesotelioma pleural.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43441, 14066, '3. Atelectasia pasiva crónica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43442, 14066, '4. Metástasis pulmonares de origen desconocido.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43443, 14067, '1. Piel - tejido subcutáneo - músculo dorsal ancho - musculatura intercostal-pleura visceral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43444, 14067, '2. Piel - tejido subcutáneo - músculo serrato lateral - musculatura intercostal - pleura parietal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43445, 14067, '3. Piel - tejido subcutáneo - musculatura pectoral - musculatura intercostal - pleura parietal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43446, 14067, '4. Piel - tejido subcutáneo - músculo infraespinoso - musculatura intercostal - pleura parietal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43447, 14068, '1. Debe realizarse una intubación orotraqueal e iniciar ventilación mecánica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43448, 14068, '2. Debe realizarse una traqueotomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43449, 14068, '3. Debe colocarse el paciente en decúbito prono para evitar otros tratamientos más invasivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43450, 14068, '4. Debe realizarse una fijación costal quirúrgica urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43451, 14069, '1. Colocación de una derivación pleuroperitoneal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43452, 14069, '2. Ligadura del conducto torácico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43453, 14069, '3. Inserción de un tubo de pleurostomía y administración de octeótrido.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43454, 14069, '4. Toracotomía con catéter e inserción de un agente esclerosante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43455, 14070, '1. Neumotórax derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43456, 14070, '2. Atelectasia obstructiva derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43457, 14070, '3. Condensación pulmonar derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43458, 14070, '4. Derrame pleural derecho.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43459, 14071, '1. Atelectasia. Fisioterapia respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43460, 14071, '2. Neumotórax. Drenaje torácico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43461, 14071, '3. Atelectasia. Broncoscopia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43462, 14071, '4. Neumotórax. Videotoracoscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43533, 14087, '3. Atelectasia redonda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43463, 14072, '1. Murmullo vesicular normal - vibraciones vocales normales-percusión mate.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43464, 14072, '2. Murmullo vesicular disminuido - vibraciones vocales aumentadas-percusión mate.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43465, 14072, '3. Estertores - vibraciones vocales aumentadas- percusión mate.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43466, 14072, '4. Murmullo vesicular disminuido - vibraciones vocales disminuidas-percusión mate.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43467, 14073, '1. Anticuerpos frente a receptor de acetilcolina.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43468, 14073, '2. Anticuerpos frente a canales de calcio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43469, 14073, '3. Anticuerpos antisintetasa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43470, 14073, '4. TSH y anticuerpos antitiroideos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43471, 14074, '1. Neumotórax espontáneo primario derecho del 50% en paciente de 30 años con saturación basal de 89% y dolor sobre hemitórax derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43472, 14074, '2. Hombre de 59 años de edad con semiología radiológica de velamiento de todo el hemitórax izquierdo con desplazamiento mediastínico contralateral, hipotensión de 70/40 mm de Hg y frecuencia cardiaca de 120 latidos por minuto, tras accidente de tráfico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43473, 14074, '3. Paciente de 67 años con adenocarcinoma pulmonar de tercio distal de bronquio principal derecho con extensión sobre bronquio intermediario con obstrucción completa de lóbulo inferior derecho y lóbulo medio que presenta disnea a grandes esfuerzos y semiología radiológica de velamiento del tercio inferior del hemitórax derecho con desplazamiento ipsilateral mediastínico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43474, 14074, '4. Paciente fumador de 45 años con neumonía neumocócica de lóbulo superior izquierdo e hipofonesis basal izquierda en la auscultación. Radiológicamente derrame pleural ipsilateral que ocupa tercio inferior del hemitórax izquierdo y toracocentesis diagnóstica con pH del líquido pleural de 6,7.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43475, 14075, '1. Biopsia pleural con aguja.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43476, 14075, '2. Tomografía por emisión de positrones (PET).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43477, 14075, '3. Cultivo de micobacterias en sangre.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43478, 14075, '4. Determinación de lisozima en líquido pleural.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43479, 14076, '1. Realizar una videotoracoscopia diagnóstica y terapéutica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43480, 14076, '2. Realizar una toracocentesis diagnóstica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43481, 14076, '3. Cambiar el antibiótico utilizado hasta el momento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43482, 14076, '4. Colocar un drenaje pleural de forma urgente.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43483, 14077, '1. Tumor broncogénico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43484, 14077, '2. Hernia de Bochdalek.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43485, 14077, '3. Absceso pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43486, 14077, '4. Neumopericardio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43487, 14078, '1. Tumores del mediastino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43488, 14078, '2. Traumatismo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43489, 14078, '3. Hipertrigliceridemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43490, 14078, '4. Linfoma', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43491, 14079, '1. Derrame pleural loculado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43492, 14079, '2. Neumotórax mínimo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43493, 14079, '3. Hemotórax.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43494, 14079, '4. Atelectasia pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43495, 14079, '5. Pericarditis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43496, 14080, '1. Derrame pleural.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43497, 14080, '2. Neumonía lobar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43498, 14080, '3. Bronquitis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43499, 14080, '4. Tuberculosis pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43500, 14080, '5. Neumotórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43501, 14081, '1. Debe ampliarse el estudio del líquido con recuento celular, glucosa, pH, ADA, colesterol y cultivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43502, 14081, '2. Biopsia pleural ciega.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43503, 14081, '3. Videotoracoscopia diagnóstica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43504, 14081, '4. Antibioterapia empírica por sospecha de derrame paraneumónico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43505, 14081, '5. Continuar el tratamiento de su hepatopatía.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43506, 14082, '1. Se trata de una gran hemorragia pulmonar por lo que el paciente debe ser intervenido de urgencia mediante toracotomía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43507, 14082, '2. Al tratarse de una hemorragia intratorácica, es de esperar una hemostasia espontánea por lo que no está indicada ninguna medida terapéutica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43508, 14082, '3. Está indicado un drenaje de la cavidad pleural con un catéter de grueso calibre y la monitorización del paciente.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43509, 14082, '4. La simple punción-evacuadora con aguja es el tratamiento de elección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43510, 14082, '5. Se trata más probablemente de un quilotórax por lo que debe establecerse un tratamiento con restricción de triglicéridos de cadena pesada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43511, 14083, '1. Derrame pleural izquierdo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43512, 14083, '2. Coartación aórtica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43513, 14083, '3. Disección aórtica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43514, 14083, '4. Neumotórax.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43515, 14083, '5. Neumonía izquierda.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43516, 14084, '1. Puncionar el hemitórax derecho para recoger muestras de líquido pleural.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43517, 14084, '2. Dar de alta al enfermo tras haber cumplido un ciclo de antibióticos y tras mejoría de la consolidación pulmonar izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43518, 14084, '3. Iniciar tratamiento con furosemida ya que el paciente está haciendo un edema agudo de pulmón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43519, 14084, '4. Colocar tubo intratorácico conectado a drenaje con sello de agua.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43520, 14084, '5. Ingresar al paciente a cirugía vascular porque lo más probable es que tenga un aneurisma aórtico y requiera de cirugía de urgencia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43521, 14085, '1. La evolución es normal, debe mantenerse tratamiento hasta completar los 10 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43522, 14085, '2. Se considera un fracaso terapéutico y debe modificar el tratamiento antibiótico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43523, 14085, '3. Realizar toracocentesis para descartar empiema.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43524, 14085, '4. Asociar corticoides a dosis de 0.5 mg/Kg/día al tratamiento antibiótico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43525, 14085, '5. Realizar broncoscopia con biopsia, aspiración y lavado broncoalveolar.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43526, 14086, '1. Derrame paraneumónico complicado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43527, 14086, '2. Tromboembolismo pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43528, 14086, '3. Insuficiencia cardiaca congestiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43529, 14086, '4. Tuberculosis pleural.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43530, 14086, '5. Quilotórax.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43531, 14087, '1. Mesotelioma pleural.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43532, 14087, '2. Adenopatías mediastínicas calcificadas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43534, 14087, '4. Carcinoma broncogénico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43535, 14087, '5. Placas pleurales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43536, 14088, '1. Recidiva', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43537, 14088, '2. Fugas aéreas mantenidas en sistema de drenaje más de 72 h.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43538, 14088, '3. Falta de reexpansión pulmonar tras tratamiento con tubo de drenaje permeable y aspiración', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43539, 14088, '4. Neumotórax bilateral simultáneo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43540, 14088, '5. Neumotórax de gran tamaño.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43541, 14089, '1. Tomografía computarizada de tórax.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43542, 14089, '2. Toracotomía urgente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43543, 14089, '3. Observación clínica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43544, 14089, '4. Radiología simple de tórax y según hallazgos colocación de drenaje pleural.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43545, 14089, '5. Ingreso en unidad de cuidados intensivos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43546, 14090, '1. Iniciar tratamiento antibiótico empírico y esperar los resultados del cultivo del líquido pleural para colocar un tubo de drenaje torácico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43547, 14090, '2. Colocar un drenaje pleural, instilar fibrinolíticos intrapleurales e iniciar tratamiento antibiótico empírico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43548, 14090, '3. Iniciar tratamiento antibiótico empírico y repetir la toracentesis al cabo de 24 horas para valorar la actitud a seguir en función de la evolución de los parámetros bioquímicos del líquido pleural.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43549, 14090, '4. Colocar un tubo de drenaje torácico e iniciar tratamiento antibiótico empírico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43550, 14090, '5. Efectuar una broncoscopia para toma de muestras microbiológicas, colocar un tubo de drenaje torácico e iniciar tratamiento antibiótico empírico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43551, 14091, '1. Relación proteínas en líquido pleural/proteínas en suero menor de 0,5.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43552, 14091, '2. Presencia de bacilos ácido-alcohol resistentes en el frotis directo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43553, 14091, '3. Abundantes células mesoteliales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43554, 14091, '4. Recuento de leucocitos inferior a 100 celular/ml.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43555, 14091, '5. Niveles de adenosíndeaminasa (ADA) mayor - 9 - de 45 UI/litro.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43556, 14092, '1. La anatomía del conducto torácico es prácticamente constante por lo que el tratamiento habitual consiste en el cierre quirúrgico de la fuga.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43557, 14092, '2. Las causas más frecuentes son las neoplásicas y los traumatismos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43558, 14092, '3. Es la causa más frecuente de derrame pleural en el neonato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43559, 14092, '4. Uno de los criterios diagnósticos más fiables es el índice Colesterol/Triglicéridos < 1 en el líquido pleural.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43560, 14092, '5. Aunque su efectividad es escasa, entre las medidas terapéuticas utilizadas se encuentra la administración de una dieta pobre en grasas y con suplementos de triglicéridos de cadena media.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43561, 14093, '1. Hipoventilación alveolar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43562, 14093, '2. Trastornos de la difusión alveolocapilar de oxígeno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43563, 14093, '3. Cortocircuito intrapulmonar de derecha a izquierda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43564, 14093, '4. Desequilibrio en la relación ventilación/ perfusión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43565, 14094, '1. Insuficiencia respiratoria global con acidosis respiratoria.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43566, 14094, '2. Insuficiencia respiratoria global con acidosis metabólica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43567, 14094, '3. Insuficiencia respiratoria parcial con acidosis metabólica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43568, 14094, '4. Insuficiencia respiratoria parcial con alcalosis respiratoria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43569, 14095, '1. La causa más frecuente es infecciosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43570, 14095, '2. Durante los primeros siete días de evolución se produce normalmente la fase proliferativa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43571, 14095, '3. Se caracteriza por un aumento de la distensibilidad del pulmón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43572, 14095, '4. La relación entre la presión parcial de oxígeno y la fracción inspirada de oxígeno es superior a 300.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43573, 14096, '1. El edema de pulmón se debe a una elevación de la presión capilar pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43574, 14096, '2. El edema de pulmón se debe a una lesión de la membrana alveolocapilar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43575, 14096, '3. La lesión pulmonar se debe a una presión pleural muy negativa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43576, 14096, '4. La lesión pulmonar se debe fundamentalmente a una broncoaspiración.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43577, 14097, '1. La inestabilidad de la pared torácica por las fracturas múltiples.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43578, 14097, '2. La infección respiratoria por aspiración.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43579, 14097, '3. La alteración del intercambio gaseoso por la contusión pulmonar.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43580, 14097, '4. La hipovolemia postraumática.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43581, 14098, '1. En pacientes con espacio muerto aumentado, la PCO2 en el aire espirado medida al final de la espiración siempre es mayor que la PACO2 (PCO2 alveolar).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43582, 14098, '2. La relación normal entre espacio muerto fisiológico y volumen corriente es de aproximadamente un tercio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43583, 14098, '3. La PAO2 (PO2 alveolar) debería ser siempre más alta que la PaO2 (PO2 arterial).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43584, 14098, '4. El porcentaje de oxihemoglobina, metahemoglobina y carboxihemoglobina nunca debe superar el 100%.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43585, 14099, '1. Ajustar el volumen tidal > 10 mL/kg de peso real.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43586, 14099, '2. Evitar una presión meseta en la vía aérea > 30 cm H20.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43587, 14099, '3. Utilizar la menor fracción inspiratoria de oxígeno (FiO2) posible para mantener una SatO2 = 90%.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43588, 14099, '4. Ajustar la PEEPpara mantener la permeabilidad alveolar al tiempo que se previene la distensión excesiva y el cierre/reapertura.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43589, 14100, '1. Hiperventilación marcada y acidosis metabólica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43590, 14100, '2. Alcalosis respiratoria crónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43591, 14100, '3. Alcalosis respiratoria y acidosis respiratoria.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43592, 14100, '4. Hiperventilación y alcalosis respiratoria aguda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43593, 14101, '1. Es debido a una alteración de la membrana capilar pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43594, 14101, '2. Radiológicamente se objetivan opacidades bilaterales no explicadas por derrame pleural, atelectasia o nódulos pulmonares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43595, 14101, '3. Es necesario que exista una presión de oclusión de la arteria pulmonar (POAP) > 18 mmHg.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43596, 14101, '4. El cociente Pa02/FiO2 debe ser menor o igual a 200 mmHg.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43597, 14102, '1. El paciente presenta una acidosis mixta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43598, 14102, '2. Debe descartarse la posibilidad de intoxicación por metanol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43599, 14102, '3. Se trata de una acidosis metabólica por pérdida de bicarbonato. Hay que descartar diarreas o pérdidas renales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43600, 14102, '4. Dada la disminución del bicarbonato, es ineludible su reposición inmediata con el objetivo de alcanzar, en la primera hora, sus valores plasmáticos normales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43601, 14103, '"1. La frecuencia respiratoria y el volumen ""tidal"" o corriente los determina el médico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43602, 14103, '2. El paciente recibe asistencia ventilatoria sólo cuando el ventilador detecta un esfuerzo inspiratorio.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43603, 14103, '3. La complicación más frecuente de este modo ventilatorio es el barotrauma.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43604, 14103, '4. Es el modo más frecuente utilizado al inicio de la ventilación mecánica porque asegura el volumen minuto en los pacientes que no respiran espontáneamente."', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43605, 14104, '1. Enfermedad pulmonar obstructiva crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43606, 14104, '2. Fibrosis pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43607, 14104, '3. Tromboembolismo pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43608, 14104, '4. Enfermedad neuromuscular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43609, 14105, '1. Cortocircuito.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43610, 14105, '2. Hipoventilación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43611, 14105, '3. Baja presión O2 inspirado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43612, 14105, '4. Enfermedad neuromuscular.', false, 4);
