INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43662, 14116, '1. Una capacidad vital, en decúbito supino, normal excluye debilidad muscular clínicamente significativa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43663, 14116, '2. El defecto típico es reducción en la capacidad pulmonar total y la capacidad vital forzada con aumento del volumen residual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43664, 14116, '3. La constante de difusión (KCO) puede estar aumentada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43665, 14116, '4. La habilidad de toser requiere una fuerza muscular suficiente y es crucial para prevenir infecciones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43666, 14116, '5. En caso de fallo agudo debemos tratar conservadoramente al paciente hasta que la gasometría muestre hipercarbia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43667, 14117, '1. Hiperpermeabilidad alveolocapilar, infiltrados pulmonares difusos e insuficiencia respiratoria aguda.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43668, 14117, '2. Insuficiencia respiratoria crónica agudizada, aumento de la distensibilidad pulmonar y edema agudo de pulmón hemodinámico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43669, 14117, '3. Hipercapnia, infiltrados pulmonares difusos e insuficiencia cardiaca izquierda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43670, 14117, '4. Hipopermeabilidad alveolocapilar, edema agudo de pulmón cardiogénico y aumento de la presión de enclavamiento capilar pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43671, 14117, '5. Aumento de la presión de enclavamiento capilar pulmonar, anuria y aumento de la distensibilidad pulmonar.', false, 5);
