INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43677, 14119, '2. Iniciar tratamiento con antibióticos de amplio espectro y corticoides a dosis altas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43678, 14119, '3. Monitorización ambulatoria con seguimiento telefónico y tratamiento sintomático.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43679, 14119, '4. Ingreso hospitalario para tratamiento con remdesivir y dexametasona.', true, 4);
