INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43687, 14121, '4. Neumonía por Pneumocystis jirovecii.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43688, 14122, '1. Rifampicina, isoniacida, pirazinamida y etambutol durante 18 meses.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43689, 14122, '2. Rifampicina, pirazinamida, etambutol y levofloxacino durante 6 meses.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43690, 14122, '3. Rifampicina, bedaquilina y proteonamida durante 12 meses.', false, 3);
