INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43692, 14123, '1. Puntuación de 0 puntos y sería tributario de alta y tratamiento ambulatorio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43693, 14123, '2. Puntuación de 1 punto y sería tributario de alta y tratamiento ambulatorio dependiendo de criterio del médico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43694, 14123, '3. Puntuación de 2 puntos y puede requerir ingreso hospitalario dependiendo del criterio del médico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43695, 14123, '4. Puntuación de 3 puntos y requiere ingreso hospitalario.', false, 4);
