INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43716, 14129, '1. Neumonía adquirida en la comunidad. Se debe solicitar antigenuria de neumococo y pautar cobertura antibiótica de amplio espectro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43717, 14129, '2. Derrame pleural a estudio. Se debe realizar una cobertura antibiótica y controles radiológicos seriados.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43718, 14129, '3. Neumonía adquirida en la comunidad y derrame paraneumónico izquierdo. Se debe realizar cobertura antibiótica y esperar a los resultados del cultivo del líquido pleural para valorar la colocación de un drenaje pleural.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43719, 14129, '4. Neumonía adquirida en la comunidad y empiema pleural paraneumónico izquierdo. Se debe realizar cobertura antibiótica, solicitar antigenuria de neumococo y colocar un drenaje pleural izquierdo urgente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43720, 14130, '1. Es preciso analizar muestras de esputo inducido para descartar tuberculosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43721, 14130, '2. Se debe iniciar un tratamiento empírico con metronidazol.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43722, 14130, '3. Si en el esputo no se aísla un patógeno específico se presupone la presencia de gérmenes anaerobios.', false, 3);
