INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43770, 14141, '1. El paciente puede ser dado de alta con trata- miento antibiótico y realizar una radiografía de control en un mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43771, 14141, '2. Se debe realizar un estudio de tomografía computarizada (TC) torácica ante la sospecha de neoplasia pulmonar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43772, 14141, '3. El paciente puede ser bacilífero y se debe realizar un análisis del esputo.', true, 3);
