INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43793, 14146, '1. La atención primaria es el entorno más favorable para detectar el consumo de tabaco, proporcionar consejo breve, facilitar la deshabituación tabáquica y promover estrategias de abandono.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43794, 14146, '2. La detección y el tratamiento de la dependencia del tabaco se considera una intervención con coste-efectividad favorable, sin repercusión en términos de coste por año de vida ganado.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43795, 14146, '3. En la ayuda para dejar de fumar, la evidencia avala tanto las estrategias no farmacológicas (intervención breve o apoyo motivacional) como las estrategias farmacológicas, siendo la combinación de ambas lo más efectivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43796, 14146, '4. Los fumadores que no desean intentar el abandono del tabaco pueden carecer de la información adecuada sobre sus efectos nocivos, tener creencias erróneas o estar desmoralizados por haber tenido recaídas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43797, 14147, '1. La principal causa de muerte relacionada con el tabaco son las neoplasias malignas.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43798, 14147, '2. En promedio, uno de cada tres fumadores morirá de forma prematura como consecuencia del tabaco.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43799, 14147, '3. El tabaco aumenta el riesgo de cáncer de vejiga.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43800, 14147, '4. Los que suspenden el tabaquismo tienen una tasa de mortalidad por cáncer de pulmón casi del 50% menor a los 10 años que los sujetos que continúan el consumo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43801, 14148, '1. En la espiración forzada se puede generar trasvase de sangre de la circulación pulmonar a la circulación sistémica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43802, 14148, '2. Cuando disminuye la concentración de oxígeno en los alvéolos, los vasos adyacentes se dilatan.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43803, 14148, '3. El ejercicio aumenta el flujo sanguíneo en todas las zonas pulmonares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43804, 14148, '4. El aumento del gasto cardiaco durante el ejercicio intenso es asumido normalmente sin grandes aumentos en la presión arterial pulmonar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43805, 14149, '1. La ventilación alveolar es mayor en áreas pulmonares superiores.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43806, 14149, '2. El flujo capilar es menor en áreas pulmonares superiores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43807, 14149, '3. La ventilación alveolar es ligeramente menor que el flujo capilar en áreas pulmonares inferiores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43808, 14149, '4. La ventilación alveolar es mayor que el flujo capilar en áreas pulmonares superiores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43809, 14150, '1. Disminución de los iones hidrógeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43810, 14150, '2. Disminución del CO2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43811, 14150, '3. Aumento de la temperatura.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43812, 14150, '4. Disminución del 2,3-bis-fosfoglicerato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43813, 14151, '1. Bronquiectasias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43814, 14151, '2. Fibrosis pulmonar idiopática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43815, 14151, '3. Obesidad mórbida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43816, 14151, '4. Esclerosis lateral amiotrófica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43817, 14152, '1. Retirar la SNG y volverla a introducir', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43818, 14152, '2. Conectar una jeringa a la sonda e insuflar 10-20 cc de aire mientras escucho ruidos en el estómago con el fonendoscopio.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43819, 14152, '3. Iniciar la nutrición enteral ya que la SNG está en posición correcta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43820, 14152, '4. Progresar la SNG cuatro centímetros más.', false, 4);
