INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43826, 14154, '2. Coartación de aorta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43827, 14154, '3. Neoplasia pulmonar.', false, 3);
