INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43831, 14155, '3. Dilatación aórtica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43832, 14155, '4. Atelectasia lobar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43833, 14155, '5. Crecimiento de cavidades derechas.', false, 5);
