INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43835, 14156, '2. Arteria torácica interna derecha.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43836, 14156, '3. Arteria subescapular derecha.', false, 3);
