INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43840, 14157, '2. Estridor – obstrucción bronquiolar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43841, 14157, '3. Crepitantes gruesos – bronquitis aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43842, 14157, '4. Una respiración superficial con difícil audición de los ruidos respiratorios – enfermedad neuromuscular.', false, 4);
