INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43844, 14158, '1. Alteración de los flujos mesoespiratorios forzados sin afectación del volumen espiratorio forzado en un segundo (FEV1) y de la capacidad vital forzada (FVC).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43845, 14158, '2. Disminución importante del FEV1/FVC.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43846, 14158, '3. Disminución de la difusión para el monóxido de carbono (DLCO) relacionada con el volumen alveolar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43847, 14158, '4. Disminución de la FVC con empeoramiento del resultado obtenido en decúbito supino respecto a la sedestación.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43848, 14158, '5. Mejoría de la alteración de la capacidad pulmonar total (TLC) tras ejercicio moderado.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43849, 14159, '1. Nódulos de Heberden', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43850, 14159, '2. Artropatía psoriásica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43851, 14159, '3. Acropaquias', true, 3);
