INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43855, 14160, '2. Ecocardiograma', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43856, 14160, '3. Rx de manos', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43857, 14160, '4. Rx simple de tórax', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43858, 14160, '5. Hemograma y bioquímica rutinaria', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43859, 14161, '1. Los beta-2 adrenérgicos carecen de efectos estimulantes cardiacos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43860, 14161, '2. Son eficaces por vía oral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43861, 14161, '3. Consiguen relajación de la musculatura lisa de vías aéreas de pequeño y gran calibre.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43862, 14161, '4. Tienen efectos antiinflamatorios bronquiales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43863, 14161, '5. Su potencia como broncodilatadores es similar a la de la aminofilina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43864, 14162, '1. Aumenta la tensión superficial de la superficie del interior alveolar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43865, 14162, '2. Reduce el esfuerzo para distender los pulmones.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43866, 14162, '3. Su secreción en el feto comienza en el sex-to/séptimo mes del embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43867, 14162, '4. Su déficit puede ser responsable de atelectasias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43868, 14162, '5. Contiene fosfolípidos y proteínas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43869, 14163, '1. Rx PA y Lat del tórax en inspiración.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43870, 14163, '2. Rx PA y Lat del tórax en espiración.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43871, 14163, '3. Rx en decúbito supino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43872, 14163, '4. Rx oblicuas de ambos pulmones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43873, 14163, '5. Rx en proyección lordótica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43874, 14164, '1. El tabaquismo, la incisión toracotomía y el dolor contribuyen en la hipoventilación y atelectasias postoperatoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43875, 14164, '2. Toleran mejor esta cirugía los pacientes con enfermedad pulmonar obstructiva que aquellos que presentan trastornos restrictivos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43876, 14164, '3. Si el FEV1 (volumen espirado forzado en un segundo) postoperatorio predecible es menor o igual que 800cc, el riesgo de padecer complicaciones pulmonares es muy elevado y contraindica la cirugía de resección pulmonar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43877, 14164, '4. Es de vital importancia en el devenir del postoperatorio la fisioterapia respiratoria pre y postoperatoria, así como la deambulación precoz.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43878, 14164, '5. La prueba de esfuerzo cardiopulmonar no ayuda a definir la función pulmonar postoperatoria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43879, 14165, '1. Displasia fibrosa.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43880, 14165, '2. Granuloma eosinófilo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43881, 14165, '3. Defecto cortical benigno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43882, 14165, '4. Encondroma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43883, 14165, '5. Tumor desmoide.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43884, 14166, '1. La capacidad vital es la capacidad pulmonar total.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43885, 14166, '2. El volumen residual es la capacidad funcional residual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43886, 14166, '3. El FEF25-75 se mide en litros/segundo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43887, 14166, '4. Mediante la espirometría podemos medir la capacidad vital, la capacidad pulmonar total y el volumen residual.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43888, 14166, '5. El volumen de ventilación pulmonar en reposo (“tidal volume”) incluye el volumen de reserva inspiratoria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43889, 14167, '1. Es la causa más frecuente de síndrome de Sjögren secundario y cursa con queratoconjuntivitis seca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43890, 14167, '2. La manifestación cardiaca más frecuente es la pericarditis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43891, 14167, '3. La pleuritis se caracteriza por un derrame pleural con características de exudado y típicamente con glucosa muy baja.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43892, 14167, '4. La manifestación hematológica más frecuente es la leucopenia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43893, 14168, '1. Pleuritis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43894, 14168, '2. Nódulos subcutáneos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43895, 14168, '3. Glomerulonefritis proliferativa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43896, 14168, '4. Enfermedad pulmonar intersticial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43897, 14169, '1. Evitar cambios frecuentes del tratamiento y evitar combinaciones de fármacos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43898, 14169, '2. Evitar tratamientos innecesarios en pacientes que a pesar de tener síntomas, pueden mantener una actividad diaria aceptable.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43899, 14169, '3. El tratamiento debe ser temprano e intensivo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43900, 14169, '4. Debe aplicarse en todos los pacientes el mismo protocolo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43901, 14170, '1. Uveítis anterior.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43902, 14170, '2. Subluxación atloaxoidea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43903, 14170, '3. Enfermedad pulmonar intersticial difusa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43904, 14170, '4. Mononeuritis múltiple.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43905, 14171, '1. Rigidez en las manos de predominio matutino de más de una hora de duración.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43906, 14171, '2. Nódulos subcutáneos en las superficies de roce de codos, rodillas y dedos de las manos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43907, 14171, '3. Astenia, anorexia y febrícula.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43908, 14171, '4. Dolor lumbar de ritmo inflamatorio.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43909, 14172, '1. Solicitaría pruebas serológicas para la hepatitis B y C, parvovirus humano B19, virus de Epstein-Barr y prueba para el virus de la inmunodeficiencia humana, dado que la causa más probable son las enfermedades infecciosas, especialmente las infecciones víricas agudas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43910, 14172, '2. Aunque se trata de un diagnóstico de exclusión, solicitaría una ferritina sérica por la posibilidad de que se trate de una enfermedad de Still del adulto.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43911, 14172, '3. Solicitaría un estudio inmunológico que incluyera anticuerpos antinucleares, factor reumatoide, anticuerpos antipéptidos cíclicos citrulinados y ANCAs para confirmar la sospecha de una enfermedad reumática sistémica como la artritis reumatoide o lupus eritematoso sistémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43912, 14172, '4. Solicitaría un estudio genético dado que lo más probable es que se trate de una enfermedad autoinflamatoria tipo fiebre mediterránea familiar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43913, 14173, '1. Etanercept es un anticuerpo monoclonal quimérico contra el TNF.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43914, 14173, '2. Abatacept impide la maduración de linfocitos B a células plasmáticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43915, 14173, '3. Anakinra es un antagonista recombinante de los receptores de IL-6.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43916, 14173, '4. Adalimumab es un anticuerpo contra el TNF completamente humano.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43917, 14174, '1. Gota tofácea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43918, 14174, '2. Artrosis erosiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43919, 14174, '3. Artritis reumatoide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43920, 14174, '4. Artropatía por pirofosfato.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43921, 14174, '5. Polimialgia reumática.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43922, 14175, '1. Solo permitiría valorar la afectación tendinosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43923, 14175, '2. No tiene ninguna utilidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43924, 14175, '3. Detecta la sinovitis pero no las erosiones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43925, 14175, '4. No detecta ni la sinovitis ni las erosiones.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43926, 14175, '5. Detecta tanto la sinovitis como las erosiones.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43927, 14176, '1. Síndrome cardio-renal tipo 2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43928, 14176, '2. Amiloidosis AA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43929, 14176, '3. Miocarditis de células gigantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43930, 14176, '4. Toxicidad por infliximab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43931, 14176, '5. Glomerulonefritis membranosa asociada a AR.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43932, 14177, '1. Es fundamental el diagnóstico precoz, un tratamiento intensivo y un control estrecho de la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43933, 14177, '2. El metotrexato es el fármaco de primera elección para controlar la actividad de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43934, 14177, '3. El factor reumatoide es típico de la enfermedad y es un criterio obligado para el diagnóstico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43935, 14177, '4. La especificidad de los anticuerpos antipéptidos citrulinados es muy elevada y tienen valor pronóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43936, 14177, '5. Los fármacos biológicos, como los anti TNF, han revolucionado el tratamiento.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43937, 14178, '1. Comienzan a detectarse en sangre en el debut de la Artritis Reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43938, 14178, '2. Son igual de específicos, para Artritis Reumatoide, que el Factor Reumatoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43939, 14178, '3. Se asocian a un peor pronóstico de la Artritis Reumatoide.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43940, 14178, '4. Son menos sensibles que el factor reumatoide.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43941, 14178, '5. Su presencia se asocia al HLA-DR2.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43942, 14179, '1. No se pueden emplear en diabéticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43943, 14179, '2. No se puede utilizar en combinación con Metotrexato.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43944, 14179, '3. No se puede utilizar en combinación con corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43945, 14179, '4. Hay riesgo de reactivar una tuberculosis latente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43946, 14179, '5. La presencia de una enfermedad desmielinizante no contraindica su uso.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43947, 14180, '1. Suspender el tratamiento pautado por la falta de respuesta e iniciar prednisona a dosis altas para el control de los síntomas exclusivamente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43948, 14180, '2. Mantener la actitud terapéutica tomada dado que sólo llevamos 6 meses y habría que esperar un mínimo de 9 meses para valorar respuesta terapéutica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43949, 14180, '3. Si no existe contraindicación médica, valorar asociar al tratamiento un anti-TNF alfa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43950, 14180, '4. Iniciar lo antes posible un segundo fármaco modificador de la enfermedad dado que no se podría iniciar tratamiento con terapia biológica sólo tras metotrexate.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43951, 14180, '5. Valorar iniciar tratamiento con terapia anti-CD20 asociada al metotrexate.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43952, 14181, '1. Más del 95% de los pacientes con artritis reumatoide tiene en su suero niveles elevados de factor reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43953, 14181, '2. Las erosiones articulares en las articulaciones de las manos y pies en esta enfermedad comienzan a aparecer después de 5 años de evolución.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43954, 14181, '3. El tratamiento estándar en esta paciente debe incluir fármacos modificadores de la enfermedad, de preferencia metotrexato.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43955, 14181, '4. La mortalidad por enfermedad cardiovascular en estos pacientes está disminuida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43956, 14181, '5. La mortalidad por cánceres sólidos y linfomas en estos pacientes está disminuida.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43957, 14182, '1. Biopsia rectal.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43958, 14182, '2. Ecografía renovesical.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43959, 14182, '3. Pielografía intravenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43960, 14182, '4. Renograma isotópico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43961, 14182, '5. Eco-Doppler renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43962, 14183, '1. La fibrosis pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43963, 14183, '2. Una alta incidencia de sinoviosarcomas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43964, 14183, '3. Una alta tasa de caídas con traumatismos craneoencefálicos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43965, 14183, '4. La presencia prematura de enfermedad cardiovascular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43966, 14183, '5. La alta incidencia de suicidios.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43967, 14184, '1. Porque la Artritis Idiopática Juvenil se asocia con mucha frecuencia a alteraciones congénitas retinianas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43968, 14184, '2. Porque la Artritis Idiopática Juvenil influye en el desarrollo de defectos refractivos miópicos severos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43969, 14184, '3. Porque la Artritis Idiopática Juvenil se asocia con frecuencia a uveítis anterior crónica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43970, 14184, '4. Porque los niños con Artritis Idiopática Juvenil deben ser revisados con la misma frecuencia que un niño con otro tipo de enfermedad infantil.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43971, 14184, '5. Porque la Artritis Idiopática Juvenil se asocia a subluxación del cristalino.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43972, 14185, '1. La determinación de los anticuerpos antipéptido cíclico citrulinado (Anti-CCP) tiene valor en el diagnóstico de la artritis reumatoide de inicio.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43973, 14185, '2. La mayoría de las veces, la enfermedad intersticial pulmonar es asintomática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43974, 14185, '3. Un rasgo característico de la afectación articular periférica es la presencia de un patrón de afectación radial (participación de diversas articulaciones de un mismo dedo, con preservación de las de los otros dedos de manos o pies).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43975, 14185, '4. Los FAMEs (fármacos modificadores de la enfermedad) tradicionales se asocian con beneficios terapéuticos importantes: mejoran los signos y síntomas y retardan la evolución radiológica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43976, 14185, '5. La rigidez matutina de larga duración es el síntoma de comienzo más frecuente en la artritis reumatoide, precediendo a la artritis en semanas o incluso meses.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43977, 14186, '1. La afectación de la columna lumbar es más frecuente que la cervical.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43978, 14186, '2. La afectación de las articulaciones interfalángicas distales es más frecuente que las proximales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43979, 14186, '3. La artritis reumatoide es más frecuente en los hombres en áreas rurales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43980, 14186, '4. Es una poliartritis de más de 6 semanas de duración.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43981, 14186, '5. La artritis reumatoide del adulto se asocia con un aumento de la frecuencia de uveitis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43982, 14187, '1. Hipertrofia vellosa de la sinovial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43983, 14187, '2. Focos de necrosis caseiforme.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43984, 14187, '3. Hiperplasia del lecho que bordea los sinoviocitos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43985, 14187, '4. Infiltración linfoplasmocitaria.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43986, 14187, '5. Neo-angiogénesis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43987, 14188, '1. La artritis reumatoide y la enfermedad de Crohn pueden tratarse con anticuerpos monoclonales anti-TNF alfa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43988, 14188, '2. Los pacientes con esclerosis múltiple mejoran notablemente con la administración de gamma interferón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43989, 14188, '3. La plasmaféresis es útil en el tratamiento del síndrome de Guillain-Barré.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43990, 14188, '4. Los anticuerpos monoclonales anti-CD3 son muy útiles en el tratamiento del rechazo crónico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43991, 14188, '5. La rapamicina bloquea a la calcineurina uniéndose a FKBP12 en el citoplasma celular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43992, 14189, '1. La artritis reumatoide es una enfermedad benigna por lo que debe iniciarse tratamiento rehabilitador, deben administrarse de forma secuencial e intermitente diferentes antiinflamatorios no esteroideos y reevaluar al paciente pasado un año.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43993, 14189, '2. No puede descartarse el desarrollo de un lupus eritematoso sistémico por lo que ceben administrarse corticoides y antipalúdicos y realizar controles periódicos de hemograma, anticuerpos anti-ADN, orina y sedimento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43994, 14189, '3. La artritis reumatoide es una enfermedad grave y debe tratarse inmediatamente con dosis bajas de corticoides, metotrexate o leflunomida. En caso de no obtenerse la remisión de la enfermedad debe realizarse un tratamiento combinado o iniciar la administración de agentes inhibidores de TNF-alfa.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43995, 14189, '4. La artritis reumatoide es una enfermedad grave y debe tratarse inmediatamente con dosis bajas de corticoides, metotrexate o leflunomida. En caso de no obtenerse la remisión de la enfermedad deben administrarse dosis altas de corticoides y tratamiento sintomático del dolor.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43996, 14189, '5. La paciente presenta una forma simétrica de espondiloartritis, probablemente una psoriasis por la detección de factor reumatoide, y basta con administrar antiinflamatorios no esteroideos. En caso de no obtenerse respuesta puede precisar anti-TNF-alfa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43997, 14190, '1. La atrofia muscular puede ser evidente a las pocas semanas del inicio de la artritis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43998, 14190, '2. Los nódulos reumatoides suelen aparecer en más del 80% de los pacientes con artritis reumatoide activa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (43999, 14190, '3. Cuando existe derrame pleural, el líquido obtenido por toracocentesis contiene niveles bajos de glucosa incluso en ausencia de infección.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44000, 14190, '4. La pericarditis puede ser asintomática y se asocia con frecuencia a la aparición de derrame pleural.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44001, 14190, '5. Entre el 15 y 20% de los pacientes experimentan un síndrome de Sjögren con la consiguiente queratoconjuntivitis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44002, 14191, '1. Metotrexate subcutáneo semanal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44003, 14191, '2. Corticoides orales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44004, 14191, '3. Fisioterapia y antiinflamatorios no esteroides (AINEs).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44005, 14191, '4. Terapia biológica con anti-TNF.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44006, 14192, '1. Artritis reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44007, 14192, '2. Lupus eritematoso sistémico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44008, 14192, '3. Artritis psoriásica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44009, 14192, '4. Artrosis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44010, 14193, '1. Artritis reactiva.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44011, 14193, '2. Artritis psoriásica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44012, 14193, '3. Artritis enteropática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44013, 14193, '4. Espondilitis anquilosante.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44014, 14194, '1. Cuadratura de los cuerpos vertebrales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44015, 14194, '2. Calcificación del ligamento vertebral común anterior.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44016, 14194, '3. Sacroileítis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44017, 14194, '4. Cifosis dorsal.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44018, 14195, '1. Espondilitis anquilosante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44019, 14195, '2. Hiperostosis vertebral anquilosante.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44020, 14195, '3. Enfermedad de Paget.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44021, 14195, '4. Artropatía psoriásica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44022, 14196, '1. Resonancia magnética de sacroiliacas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44023, 14196, '2. HLA-B27.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44024, 14196, '3. Radiografía de sacroiliacas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44025, 14196, '4. Velocidad de sedimentación globular.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44026, 14197, '1. Por edad y sexo, es probable que se trate de gota e iniciaría tratamiento con alopurinol y colchicina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44027, 14197, '2. Preguntaré por antecedentes familiares de psoriasis y solicitaría HLA-B27, es probable que sufra un tipo de espondiloartritis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44028, 14197, '3. El tipo de dolor en raquis orienta el diagnóstico a hernia discal. Derivo al paciente a Neurocirugía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44029, 14197, '4. Iniciaría tratamiento con metotrexato que es eficaz para el dolor de raquis y la inflamación de dedos de pies.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44030, 14198, '1. Infección por VIH.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44031, 14198, '2. Sífilis secundaria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44032, 14198, '3. Síndrome de Reiter.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44033, 14198, '4. Eritema multiforme.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44034, 14199, '1. Dada la edad del paciente, lo más probable es que padezca lumbalgia inespecífica y una tendinitis en los pies. Si persisten las diarreas realizaría estudio digestivo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44035, 14199, '2. Realizaría estudio digestivo para descartar patología tumoral. El dolor lumbar puede ser debido a patología visceral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44036, 14199, '3. El cuadro clínico es muy sugestivo de espondiloartritis. Habría que descartar enfermedad inflamatoria intestinal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44037, 14199, '4. Solicitaría RNM lumbar para descartar hernia discal y si persiste diarrea, estudio digestivo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44038, 14200, '1. Se debe iniciar tratamiento con cloxacilina y ceftriaxona en espera del resultado del cultivo del líquido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44039, 14200, '2. Es aconsejable realizar artrocentesis diarias para aliviar los síntomas y evitar la destrucción articular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44040, 14200, '3. Si el cultivo es negativo, es probable que se trate de una artritis reactiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44041, 14200, '4. La negatividad de la tinción de Gram descarta que se trate de una artritis séptica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44042, 14201, '1. Se trata de una espondiloartropatía, iniciaría tratamiento con metotrexato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44043, 14201, '2. Inmovilizar la rodilla con un vendaje durante 15 días y dar antiinflamatorios no esteroideos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44044, 14201, '3. Practicar una artrocentesis para realizar cultivo, análisis de microcristales y recuento celular del líquido sinovial.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44045, 14201, '4. Realizar una artroscopia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44046, 14201, '5. Se trata de una artritis gotosa, iniciaría tratamiento con alopurinol.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44047, 14202, '1. Fractura de Looser - Osteomalacia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44048, 14202, '2. Sacroileítis bilateral - Espondilitis anquilosante.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44049, 14202, '3. Coexistencia de lesiones líticas y blásticas - Enfermedad de Paget.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44050, 14202, '4. Lesiones blásticas - Adenocarcinoma prostático con metástasis óseas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44051, 14202, '5. Osteoesclerosis -Linfoma.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44052, 14203, '1. Indometacina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44053, 14203, '2. Etoricoxib.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44054, 14203, '3. Corticoides sistémicos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44055, 14203, '4. Fisioterapia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44056, 14203, '5. Adalimumab.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44057, 14204, '1. Enfermedad de Behçet.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44058, 14204, '2. Síndrome de artritis reactiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44059, 14204, '3. Síndrome de Sweet.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44060, 14204, '4. Déficit de vitamina A.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44061, 14204, '5. Infección por Gonococo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44062, 14205, '1. La movilidad espinal rara vez está comprometida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44063, 14205, '2. No existe sacroileítis radiográfica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44064, 14205, '3. Hay predominio en mujeres.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44065, 14205, '4. Es excepcional que afecte a la columna cervical.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44066, 14205, '5. El curso es agudo e invalidante.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44067, 14206, '1. Espondilitis anquilopoyética.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44068, 14206, '2. Artrosis de raquis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44069, 14206, '3. Hiperostosis anquilosante vertebral de Forestier-Rotes', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44070, 14206, '4. Melorreostosis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44071, 14206, '5. Mastocitosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44072, 14207, '1. La presencia de artritis en más de un territorio articular sugiere el diagnóstico de Artritis Reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44073, 14207, '2. La presencia de artritis en más de un territorio articular excluye la presencia de una artritis infecciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44074, 14207, '3. La presencia de artritis en más de un territorio articular, asociada a fiebre y presencia de afectación cutánea nos orienta hacia una enfermedad sistémica, como el Lupus Eritematoso Sistémico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44075, 14207, '4. La presencia de artritis de rodilla y tobillo y la afectación que presenta en los dedos de los pies, y la fiebre son sugerentes de Infección por Gonococo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44076, 14207, '5. La fiebre y la presencia de artritis de rodilla y tobillo, y la afectación que presenta en los dedos de los pies, son sugerentes de una Artritis Reactiva.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44077, 14208, '1. Realizar hemocultivos, cultivo de líquido articular e iniciar tratamiento antibiótico IV. En caso de que los cultivos sean negativos completar tratamiento antibiótico de 10 días y ver evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44078, 14208, '2. Realizar hemocultivos, cultivo de líquido articular e iniciar tratamiento antibiótico i.v. y antiinflamatorio v.o. En caso de que los cultivos sean negativos, suspender antibióticos y ver evolución.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44079, 14208, '3. Realizar hemocultivos, cultivo de líquido articular e iniciar tratamiento antibiótico i.v. y corticoides a altas dosis (1 mg/kg de peso). En caso de que los cultivos sean negativos, suspender antibióticos y ver evolución.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44354, 14268, '4. Osteonecrosis del maxilar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44080, 14208, '4. Iniciar de inmediato tratamiento con corticoides a altas dosis (1 mg/kg de peso) y Metotrexato (15 mg v.o. en dosis única semanal).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44081, 14208, '5. Iniciar de inmediato tratamiento con antiinflamatorios y Metotrexato (15 mg v.o. en dosis única semanal).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44082, 14209, '1. Anticuerpos Antinucleares y estudio del Complemento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44083, 14209, '2. Factor Reumatoide y Anticuerpos anti-péptido citrulinado.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44084, 14209, '3. Determinación del HLA-B27.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44085, 14209, '4. Serología de Salmonella, Shigella y Yersinia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44086, 14209, '5. Determinación de Antígeno del Gonococo en uretra.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44087, 14210, '1. La nefropatía IgA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44088, 14210, '2. La afectación pulmonar intersticial de campos superiores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44089, 14210, '3. La uveítis anterior aguda.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44090, 14210, '4. La uveítis posterior con coriorretinitis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44091, 14210, '5. La amiloidosis secundaria.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44092, 14211, '1. La inflamación ocular (uveitis, conjuntivitis).', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44093, 14211, '2. La leucopenia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44094, 14211, '3. La hipertensión arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44095, 14211, '4. La presencia de afectación gástrica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44096, 14211, '5. La afectación renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44097, 14212, '1. La positividad del antígeno HLA-B27 hará seguro el diagnóstico de espondilitis anquilosante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44098, 14212, '2. Los corticoides orales serán una parte importante del tratamiento en este paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44099, 14212, '3. Una radiografía anteroposterior de pelvis y de columna lumbar aportará poco en este caso.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44100, 14212, '4. La sulfasalazina será una parte importante del tratamiento en este paciente.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44101, 14212, '5. La uveítis posterior es relativamente frecuente en el curso evolutivo de estos pacientes.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44102, 14213, '1. Inmovilización de la rodilla con rodillera de descarga rotuliana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44103, 14213, '2. Pérdida de peso y ejercicio físico supervisado para fortalecer el cuádriceps.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44104, 14213, '3. Infiltración intraarticular de corticoides.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44105, 14213, '4. Tratamiento farmacológico con tramadol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44106, 14214, '1. Artritis reumatoide', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44107, 14214, '2. Artritis psoriásica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44108, 14214, '3. Artritis gotosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44109, 14214, '4. Artrosis.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44110, 14215, '1. Hago el diagnóstico de coxartrosis y envío al traumatólogo para colocar una prótesis de cadera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44111, 14215, '2. Inicio tratamiento con opioides débiles que han demostrado evidencia en detener la progresión de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44112, 14215, '3. Instauro tratamiento con paracetamol, explico que la evolución es muy variable y la indicación quirúrgica depende de la funcionalidad y control del dolor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44113, 14215, '4. Por las características radiológicas descritas, necesito una RMN de cadera antes de tomar una decisión terapéutica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44114, 14216, '1. Hay una estrecha correlación entre los hallazgos radiológicos y la sintomatología de los pacientes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44115, 14216, '2. La afectación sintomática de la cadera es mucho más frecuente que la afectación de la rodilla.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44116, 14216, '3. La obesidad no se ha demostrado que sea un factor de riesgo para su desarrollo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44117, 14216, '4. La presencia de una velocidad de sedimentación elevada apoya fuertemente el diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44118, 14216, '5. La rigidez matutina habitualmente dura menos de 30 minutos', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44119, 14217, '1. La artrosis de articulaciones interfalángicas distales predomina en mujeres.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44120, 14217, '2. La artrosis de articulaciones interfalángicas distales tiene una clara historia familiar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44121, 14217, '3. Las dos artropatías que afectan con más frecuencia las articulaciones interfalángicas distales son: la artrosis y la artritis psoriásica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44122, 14217, '4. La artritis reumatoide debe incluirse en el diagnóstico diferencial de este caso.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44123, 14217, '5. La artrosis de articulaciones interfalángicas distales puede ocasionar desviaciones laterales de los dedos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44124, 14218, '1. Antiinflamatorios no esteroideos (AINE) orales con protección gástrica con ranitidina durante 7 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44125, 14218, '2. Inhibidores de la enzima ciclooxigenasa (Cox 2) durante 7 días.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44126, 14218, '3. Paracetamol 1 g cada 8 horas durante 7 días.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44127, 14218, '4. Vendaje de la rodilla más AINE orales durante 7 días.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44128, 14218, '5. Administrar una dosis intramuscular de corticoides depot', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44129, 14219, '1. Porfiria aguda intermitente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44130, 14219, '2. Alcaptonuria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44131, 14219, '3. Osteoartritis séptica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44132, 14219, '4. Artritis reumatoide.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44133, 14220, '1. Realizar artrocentesis y enviar el líquido sinovial al laboratorio para evaluar presencia de cristales y gérmenes.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44134, 14220, '2. Empezar tratamiento con colchicina porque está sufriendo un episodio de gota.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44135, 14220, '3. Empezar tratamiento con un AINE y alopurinol para tratar el episodio de gota y la hiperuricemia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44136, 14220, '4. Empezar tratamiento con un AINE, alopurinol y un antibiótico para tratar el episodio de gota, la hiperuricemia y la probable infección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44137, 14221, '1. El tratamiento hipouricemiante debe iniciarse durante el ataque de gota, tan pronto como sea posible.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44138, 14221, '2. El fármaco de elección es el alopurinol comenzando con dosis bajas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44139, 14221, '3. Como norma general, la hiperuricemia asintomática no debe ser tratada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44140, 14221, '4. Alrededor del 50 % de los casos se manifiestan como monoartritis inflamatoria aguda de la primera articulación metatarsofalángica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44141, 14222, '1. Tratamiento con febuxostat.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44142, 14222, '2. Tratamiento con indometacina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44143, 14222, '3. Tratamiento con benzbromarona.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44144, 14222, '4. Tratamiento con ejercicio, dieta estricta baja en purinas y colchicina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44145, 14223, '1. Diclofenaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44146, 14223, '2. Alopurinol.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44149, 14224, '1. El tratamiento inicial consistirá en antiinflamatorios no esteroideos, así como la aspiración del líquido sinovial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44150, 14224, '2. Es conveniente la realización de cultivo del líquido sinovial para descartar sinovitis infecciosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44151, 14224, '3. Una vez pasado el brote agudo habrá que instaurar tratamiento con alopurinol para disminuir la incidencia de nuevos brotes de artritis en el futuro.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44152, 14224, '4. El diagnóstico más probable es una artritis aguda por depósito de cristales de pirofosfato cálcico (pseudogota).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44153, 14225, '1. El ácido acetilsalicílico a dosis inferiores a 1g diario.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44154, 14225, '2. La hidroclorotiacida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44155, 14225, '3. La ciclosporina A.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44156, 14225, '4. El etambutol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44157, 14225, '5. Los estrógenos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44158, 14226, '1. El tratamiento es el empleo de alopurinol a dosis mínimas de 800 mg diarios por lo que se debe incrementar de forma precoz la dosis que empleaba el paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44159, 14226, '2. Durante la fase aguda el tratamiento son los AINE, que se pueden asociar a colchicina.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44160, 14226, '3. Dada la gravedad de las lesiones se debe emplear la colchicina intravenosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44161, 14226, '4. Si el líquido sinovial presenta un recuento celular superior a 3000 cel /μl se debe iniciar tratamiento con antibioterapia parenteral con cobertura frente a Staphylococcus Aureus y Streptococcus spp y mantenerla al menos 6 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44162, 14226, '5. En esta enfermedad los esteroides sistémicos o intraarticulares no han demostrado su eficacia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44163, 14227, '1. Es necesario realizar tomografía axial computarizada abdominal para descartar pancreatitis crónica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44164, 14227, '2. Realizaría análisis del líquido sinovial de una articulación afecta.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44165, 14227, '3. Trataría las crisis agudas con alopurinol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44166, 14227, '4. El diagnóstico más probable es una artritis reactiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44167, 14227, '5. Está indicado iniciar tratamiento con metotrexato.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44168, 14228, '1. Hidroclorotiazida.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44169, 14228, '2. Amlodipino.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44170, 14228, '3. Losartán.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44171, 14228, '4. Enalaprilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44172, 14228, '5. Diltiazem.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44173, 14229, '1. Suspender alopurinol e iniciar tratamiento con colchicina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44174, 14229, '2. Suspender alopurinol y comenzar con AINE.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44175, 14229, '3. Añadir un AINE hasta que la artritis remita.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44176, 14229, '4. Aumentar la dosis de alopurinol a 300 mg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44177, 14229, '5. Sustituir el alopurinol por un uricosúrico.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44178, 14230, '1. Su empleo es de segunda elección, cuando han fracasado los uricosúricos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44179, 14230, '2. Su empleo por tiempo prolongado es prácticamente obligado porque existen tofos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44180, 14230, '3. Su introducción debe demorarse hasta que se haya resuelto al ataque actual con antiinflamatorios o con colchicina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44181, 14230, '4. Su introducción debe ser gradual hasta una dosis que consiga una uricemia inferior a 6 mg/dL.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44182, 14230, '5. En los primeros meses de tratamiento se aconseja asociar dosis bajar de colchicina para prevenir nuevos ataques.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44183, 14231, '1. La colchicina es muy útil, reduciendo el número y la intensidad de los ataques en pacientes tratados o no con fármacos hipouricemiantes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44184, 14231, '2. La disminución del aclaramiento renal de ácido úrico es la causa más común de hiperuricemia y gota.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44185, 14231, '3. La identificación de cristales de urato monosódico en líquido sinovial permite un diagnóstico preciso de la enfermedad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44186, 14231, '4. El inicio del tratamiento hipouricemiante ha de comenzarse en el brote agudo asociado a AINEs.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44187, 14231, '5. La práctica de radiografías en las articulaciones con ataques de gota es útil si se desea descartar otras entidades detectables radiológicamente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44188, 14232, '1. Pueden ser producidas por cualquiera de los siguientes cristales: urato monosódico, pirofosfato cálcico, hidroxiapatita cálcica y oxalato cálcico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44189, 14232, '2. El depósito de cristales puede producir cuadros clínicos similares a la artritis reumatoide o la espondilitis anquilosante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44190, 14232, '3. Los cuadros clínicos producidos son específicos para cada uno de los tipos de cristales depositados.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44191, 14232, '4. Para hacer el diagnóstico es imprescindible el estudio del líquido sinovial con microscopio de luz polarizada para identificar el tipo de cristales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44192, 14232, '5. El líquido sinovial suele ser de tipo inflamatorio, aunque en ocasiones existen cristales en ausencia de inflamación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44193, 14233, '1. A pesar de su gran eficacia, la colchicina produce efectos secundarios en el 80% de los pacientes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44194, 14233, '2. Las inyecciones intraarticulares de glucocorticoides pueden ser útiles.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44195, 14233, '3. Los antiinflamatorios no esteroideos (AINE) deben mantenerse hasta 3 o 4 días después de la desaparición de todos los signos inflamatorios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44196, 14233, '4. Si existe hiperuricemia asociada, debe iniciar- se tratamiento con alopurinol sin esperar a la resolución del episodio agudo, para prevenir así futuros ataques de gota.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44197, 14233, '5. Una alternativa a la colchicina y los AINE es emplear glucocorticoides a dosis bajas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44198, 14234, '1. A diferencia de lo objetivado en el paciente, la alteración de la ENMG más característica es una neuropatía de fibra fina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44199, 14234, '2. Una biopsia de músculo no permitiría demostrar histológicamente la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44200, 14234, '3. A pesar de la sospecha diagnóstica, no cumple criterios clasificatorios de la enfermedad, por lo que no es posible diagnosticarle.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44201, 14234, '4. Existen pacientes que cumplen los criterios clasificatorios de la enfermedad que presentan mutaciones con pérdida de función en el gen CECR1 que codifica la adenosina desaminasa 2.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44202, 14235, '1. Síndrome de Muckle-Wells (síndrome periódico asociado a criopirina).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44203, 14235, '2. Fiebre mediterránea familiar.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44204, 14235, '3. Síndrome de Blau (granulomatosis artrocutaneouveal).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44355, 14268, '5. Tetania.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44205, 14235, '4. Síndrome periódico asociado al receptor del factor de necrosis tumoral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44206, 14236, '1. La gran mayoría de los pacientes presentan fiebre alta de forma brusca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44207, 14236, '2. Los episodios inflamatorios son breves y recurrentes, con intervalos asintomáticos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44208, 14236, '3. Las manifestaciones digestivas son poco frecuentes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44209, 14236, '4. Pueden presentar dolor torácico por pleuritis y/o pericarditis estéril.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44210, 14237, '1. Tricrómico de Masson.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44211, 14237, '2. Rojo Congo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44212, 14237, '3. Ácido peryódico de Schiff (PAS).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44213, 14237, '4. Metenamina de plata.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44214, 14238, '1. Síndrome cardio-renal tipo 2.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44215, 14238, '2. Amiloidosis AA.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44216, 14238, '3. Miocarditis de células gigantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44217, 14238, '4. Toxicidad por infliximab.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44218, 14238, '5. Glomerulonefritis membranosa asociada a AR.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44219, 14239, '1. Una tomografía axial computarizada (TAC) de abdomen.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44220, 14239, '2. Un estudio genético.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44221, 14239, '3. Unos anticuerpos antinucleares.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44222, 14239, '4. Una resonancia magnética nuclear (RMN) de rodilla.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44223, 14239, '5. Una velocidad de sedimentación globular (VSG).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44224, 14240, '1. Absceso odontógeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44225, 14240, '2. Osteonecrosis por bifosfonatos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44226, 14240, '3. Osteorradionecrosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44227, 14240, '4. Raíz dental incluida.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44228, 14240, '5. Metástasis de carcinoma de mama.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44229, 14241, '1. Biopsia de grasa abdominal y aspirado de medula ósea.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44230, 14241, '2. Determinación de microalbuminuria y hemoglobina glicosilada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44231, 14241, '3. Determinación de vitamina B12 plasmática y folato eritrocitario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44232, 14241, '4. Serología para el VIH (virus de la inmunodeficiencia humana).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44233, 14241, '5. Biopsia renal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44234, 14242, '1. La biopsia renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44235, 14242, '2. La biopsia hepática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44236, 14242, '3. La biopsia cutánea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44237, 14242, '4. La punción aspirativa de grasa abdominal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44238, 14242, '5. La determinación de amiloide circulante.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44239, 14243, '1. Anomalías en el flujo vascular por factores genéticos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44240, 14243, '2. Oclusión intravascular por émbolos (lípidos, nitrógeno, hematíes anómalos).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44241, 14243, '3. Dehiscencia de la íntima arterial de los vasos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44242, 14243, '4. Compresión extravascular a consecuencia de un acúmulo graso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44243, 14244, '1. No es candidato a tratamiento osteoprotector por edad y presencia de demencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44244, 14244, '2. No se deben iniciar bifosfonatos si presenta hipocalcemia.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44245, 14244, '3. Debe suplementarse con calcio aunque sus valores sean normales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44246, 14244, '4. Debe permanecer encamado seis semanas tras la intervención quirúrgica para mejorar la consolidación de la fractura', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44247, 14245, '1. Solicitar de forma urgente radiografías de columna dorsal y lumbar y pautar tratamiento analgésico para el dolor.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44248, 14245, '2. Solicitar una RM de columna dorsal y lumbar y pautar tratamiento analgésico y reposo para el dolor.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44249, 14245, '3. Pautar tratamiento analgésico y empezar tratamiento antirreabsortivo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44250, 14245, '4. Solicitar una densitometria, pautar tratamiento analgésico y empezar con tratamiento antireabsortivo, calcio y vitamina D.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44251, 14246, '1. Osteoporosis.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44252, 14246, '2. Déficit visual.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44253, 14246, '3. Artrosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44254, 14246, '4. Polifarmacia.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44255, 14247, '1. La baja adherencia al tratamiento se asocia a un incremento del riesgo de fractura.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44256, 14247, '2. Los marcadores de remodelado óseo pueden ser útiles para monitorizar de forma precoz la respuesta al tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44257, 14247, '3. La vitamina D en monoterapia es eficaz en la reducción de dichas fracturas en personas mayores no institucionalizadas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44258, 14247, '4. El aumento de calcio dietético o tomar suplementos de calcio de forma aislada no protegen frente a la aparición de fracturas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44259, 14248, '1. Zolendronato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44260, 14248, '2. Denosumab.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44261, 14248, '3. Alendronato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44262, 14248, '4. Teriparatida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44263, 14249, '1. Puede relacionarse con la administración de bifosfonatos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44264, 14249, '2. Se asocia en la mayoría de los casos con radioterapia previa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44265, 14249, '3. El tratamiento de elección es la mandibulectomía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44266, 14249, '4. Es una forma de atrofia mandibular del desarrollo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44267, 14250, '1. La prueba es normal, suspender calcio y vitamina D.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44268, 14250, '2. Mantener tratamiento con calcio y vitamina D.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44269, 14250, '3. Recomendar añadir fármacos antirresortivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44270, 14250, '4. Iniciar tratamiento con teriparatide', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44271, 14251, '1. Osteomielitis aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44272, 14251, '2. Artrosis de cadera.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44273, 14251, '3. Necrosis avascular de la cabeza femoral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44274, 14251, '4. Osteosarcoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44275, 14252, '1. Lesión ósea mandibular secundaria a radioterapia (osteorradionecrosis).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44276, 14252, '2. Necrosis ósea vascular mandibular secundaria a vasculopatía diabética, tabaquismo y osteoporosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44277, 14252, '3. Carcinoma epidermoide verrucoso-ulcerado.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44278, 14252, '4. Osteonecrosis mandibular secundaria a tratamiento con denosumab', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44279, 14253, '1. De acuerdo con los datos obtenidos en la densitometría ósea, se define osteoporosis cuando T score (comparación con población joven sana de la misma raza y sexo) es > 3,5.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44356, 14269, '1. Aneurisma abdominal con erosión vertebral acompañante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44280, 14253, '2. La medida de T score es útil para el diagnóstico de osteoporosis en mujeres jóvenes. En mujeres postmenopáusicas se utiliza el Z score.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44281, 14253, '3. Está indicado administrar fármacos específicos para el tratamiento de osteoporosis en mujeres menopaúsicas con diagnóstico de osteopenia (densitometría) y aplastamiento vertebral sea o no sintomático.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44282, 14253, '4. La acción de los bisfosfonatos utilizados en el tratamiento de la osteoporosis es activar la acción de los osteoblastos para la formación de hueso.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44283, 14254, '1. Solicitaría un mapa óseo incluyendo cráneo y parrilla costal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44284, 14254, '2. Solicitaría una determinación de fosfatasa alcalina ósea.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44285, 14254, '3. Iniciaría terapia hormonal estrogénica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44286, 14254, '4. Los bifosfonatos endovenosos como pamidronato y zoledronato son una opción eficaz en este problema.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44287, 14255, '1. No es necesario iniciar un tratamiento anti-rreabsortivo por edad y ausencia de otros factores de riesgo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44288, 14255, '2. Recomendaría orientar su dieta a fortalecer el consumo de productos ricos en calcio y fósforo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44289, 14255, '3. Debe iniciar tratamiento con un agente anti-rreabsortivo asociado a suplementos de calcio y vitamina D.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44290, 14255, '4. No debe instaurarse ningún tratamiento farmacológico hasta disponer de los resultados de una densitometría ósea lumbar y femoral.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44291, 14256, '1. Si la dosis de prednisona recibida por el paciente, es inferior a 15 mg al día, durante un tiempo inferior a 6 meses, no es un problema realmente y no se debe tomar ninguna medida preventiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44292, 14256, '2. Las tiazidas han demostrado disminuir el riesgo de fracturas, tanto de cadera, como de columna vertebral, en pacientes tratados con glucocorticoides. Por eso, su uso debe recomendarse en estos pacientes como medida preventiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44293, 14256, '3. Se recomienda realizar una densitometría ósea después del primer año de tratamiento con glucocorticoides, puesto que antes no se produce pérdida de masa ósea.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44294, 14256, '4. Todos los pacientes en tratamiento con glucocorticoides deben recibir un aporte adecuado de calcio y vitamina D, que puede proceder de la dieta o de suplementos farmacológicos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44295, 14256, '5. La pérdida de masa ósea se observa, sobre todo, en cadera, por eso la densitometría de columna vertebral no tiene ninguna utilidad en su valoración.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44296, 14257, '1. Solicitar DXA y esperar al resultado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44297, 14257, '2. Valorar riesgo absoluto de fractura mediante el cuestionario FRAX sin DMO y tratar sólo si es alto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44298, 14257, '3. Iniciar tratamiento con Bisfosfonatos y vitamina D (800 UI/día).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44299, 14257, '4. Administrar suplemento de calcio (1g) y vitamina D (800 UI/día).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44300, 14257, '5. Valorar si tiene osteopenia en las radiografías y tratar si está presente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44301, 14258, '1. Osteoporosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44302, 14258, '2. Enfermedad de Paget.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44303, 14258, '3. Osteitis fibrosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44304, 14258, '4. Metástasis de cáncer de próstata.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44305, 14258, '5. Osteomalacia.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44306, 14259, '1. El tratamiento con corticosteroides invalida rápidamente el resultado de la biopsia de la arteria temporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44307, 14259, '2. Si se sospecha, en caso de síntomas visuales o si la biopsia se va a retrasar, se debe iniciar de inmediato el tratamiento con corticosteroides.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44308, 14259, '3. La ausencia de cambios inflamatorios en el segmento de arteria temporal biopsiado descarta el diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44309, 14259, '4. Es suficiente con mantener el tratamiento con corticosteroides durante dos o tres meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44310, 14259, '5. Si durante la reducción progresiva de los corticosteroides sube lo más mínimo la velocidad de sedimentación globular, debe subirse la dosis, aunque el paciente esté asintomático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44311, 14260, '1. Atorvastatina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44312, 14260, '2. Warfarina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44313, 14260, '3. Furosemida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44314, 14260, '4. Hidroclorotiazida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44315, 14260, '5. Levotiroxina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44316, 14261, '1. Estrógenos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44317, 14261, '2. Calcio y Vitamina D.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44318, 14261, '3. Bifosfonatos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44319, 14261, '4. Actividad física.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44320, 14261, '5. Calcitonina.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44321, 14262, '1. Bifosfonatos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44322, 14262, '2. Terramicina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44323, 14262, '3. Cisplatino.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44324, 14262, '4. Calcio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44325, 14262, '5. Corticoides.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44326, 14263, '1. Cráneo con lesiones líticas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44327, 14263, '2. Craneoestenosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44328, 14263, '3. Cráneo con alteraciones en sal y pimienta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44329, 14263, '4. Cráneo con ensanchamiento destructivo de la silla turca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44330, 14263, '5. Cráneo con cambios líticos y escleróticos.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44331, 14264, '1. Hiperparatiroidismo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44332, 14264, '2. Acromegalia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44333, 14264, '3. Enfermedad de Paget.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44334, 14264, '4. Mieloma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44335, 14264, '5. Hipervitaminosis D.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44336, 14265, '1. Osteoporosis idiopática del varón.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44337, 14265, '2. Síndrome de Marfan.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44338, 14265, '3. Osteomalacia.', false, 3);
