INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44361, 14270, '1. Tiene una prevalencia en la población general de entre un 5 y un 10 %.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44362, 14270, '2. La edad más frecuente de aparición es por encima de los 50 años.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44363, 14270, '3. Existen múltiples fármacos aprobados para su tratamiento.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44364, 14270, '4. La fatiga es un síntoma muy común, por encima del 70 % de los pacientes.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44365, 14271, '1. Su diagnóstico es esencialmente clínico, pues no hay alteraciones de laboratorio características.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44366, 14271, '2. Distribución simétrica de los puntos dolorosos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44367, 14271, '3. Presencia de síntomas como parestesias, alteraciones del sueño y rigidez.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44368, 14271, '4. Buena respuesta al tratamiento con glucocorticoides.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44369, 14272, '1. Educación del paciente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44370, 14272, '2. Actividad física aeróbica, adaptada a las capacidades del paciente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44371, 14272, '3. Amitriptilina a bajas dosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44372, 14272, '4. Mórficos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44373, 14272, '5. Analgésicos.', false, 5);
