INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44375, 14273, '2. Proteínas en orina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44376, 14273, '3. NT-proBNP.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44377, 14273, '4. Test de Coombs', false, 4);
