INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44379, 14274, '2. Vitaminas antioxidantes a dosis altas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44380, 14274, '3. Intentar la gestación mediante diagnóstico genético preimplantacional.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44381, 14274, '4. Tratamiento según cribado de preeclampsia de primer trimestre con aspirina a dosis bajas si alto riesgo.', false, 4);
