INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44394, 14278, '1. La fertilidad no se ve afectada.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44395, 14278, '2. Durante la gestación los brotes suelen ser más frecuentes y graves.', false, 2);
