INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44402, 14280, '1. Los anti-Sm no son específicos de esta patología.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44403, 14280, '2. Los anticuerpos anticentrómero se detectan en el 90 % de los casos.', false, 2);
