INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44533, 14309, '4. Solicitar una TC torácica de alta resolución', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44534, 14310, '1. Dermatomiositis asociada al autoanticuerpo anti-TIF1-gamma (transcription intermediary factor 1-gamma).', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44535, 14310, '2. Miopatía inflamatoria idiopática asociada al autoanticuerpo anti-FHL-1 (Four and a half LIM domains 1).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44536, 14310, '3. Dermatomiositis asociada al autoanticuerpo anti-MDA-5 (melanoma differentiation associated gen 5).', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44537, 14310, '4. Miopatía miofibrilar asociada al anticuerpo anti-desmina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44538, 14311, '1. Lupus cutáneo subagudo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44539, 14311, '2. Porfiria cutánea tarda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44540, 14311, '3. Dermatomiositis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44541, 14311, '4. Artropatía psoriásica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44542, 14312, '1. Análisis inmunológico: Ac. anti-cN1A positivos. Biopsia: infiltrado inflamatorio perivascular y presencia de vacuolas ribeteadas. Diagnóstico: miositis con cuerpos de inclusión.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44543, 14312, '2. Análisis inmunológico: Ac. anti-TIF-1 gamma positivos. Biopsia: infiltrado inflamatorio perivascular y células en anillo. Diagnóstico: dermatomiositis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44544, 14312, '3. Análisis inmunológico: Ac. anti-mitocondriales positivos. Biopsia: necrosis coagulativa y regeneración de fibras musculares con escaso infiltrado inflamatorio. Diagnóstico: distrofia muscular congénita de Ullrich.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44545, 14312, '4. Análisis inmunológico: Ac. anti-HMG-CoA reductasa positivos. Biopsia: necrosis coagulativa y regeneración de fibras musculares con escaso infiltrado inflamatorio. Diagnóstico: miopatía necrosante inmunomediada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44546, 14313, '1. Infiltrado inflamatorio perimisial, ragged-red fibers (fibras rojo-rotas) y atrofia perifascicular: Dermatomiositis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44547, 14313, '2. Infiltrado inflamatorio endomisial y vacuolas ribeteadas: Miositis con cuerpos de inclusión.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44548, 14313, '3. Necrosis coagulativa, inclusiones lipídicas y regeneración de fibras musculares: Miopatía necrosante autoinmune.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44549, 14313, '4. Atrofia de fibras tipo II, infiltrado inflamatorio endomisial y regeneración de fibras musculares: Distrofia miotónica de Steinert.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44550, 14314, '1. Vasculitis tipo panarteritis nudosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44551, 14314, '2. Lupus eritematoso sistémico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44552, 14314, '3. Dermatomiositis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44553, 14314, '4. Miositis con cuerpos de inclusión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44554, 14314, '5. Sarcoidosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44555, 14315, '1. TC toracoabdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44556, 14315, '2. Exploración ginecológica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44557, 14315, '3. Autoanticuerpos que incluyan ANA y antisintetasa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44558, 14315, '4. Electromiografía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44559, 14315, '5. Arteriografía de las arterias renales.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44560, 14316, '1. Determinación de aldolasa sérica', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44561, 14316, '2. Electroencefalograma', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44562, 14316, '3. Biopsia de tejido celular subcutáneo', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44563, 14316, '4. Determinación de anticuerpos anti músculo liso', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44564, 14316, '5. Estudio genético de sus descendientes', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44565, 14317, '1. Los datos confirman la existencia de una afectación postsináptica de la transmisión neuromuscular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44566, 14317, '2. Los datos establecen el diagnóstico de una Distrofia Miotónica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44567, 14317, '3. Si en la biopsia muscular se encuentran datos de inflamación puede establecerse el diagnóstico de Polimiositis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44568, 14317, '4. Los datos del electromiograma muestran un patrón de afectación neurógeno crónico que excluye cualquier tipo de miopatía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44569, 14317, '5. Los datos confirman la existencia de una polineuropatía desmielinizante inflamatoria crónica.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44570, 14318, '1. La vasculitis sistémica que se sospecha con mayor probabilidad es una vasculitis de gran vaso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44571, 14318, '2. En el análisis, la normalidad de la velocidad de sedimentación globular apoya el diagnóstico de esta vasculitis.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44572, 14318, '3. Es frecuente observar afectación de la pared arterial de la aorta y sus ramas principales mediante pruebas de imagen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44573, 14318, '4. Una biopsia de la arteria temporal que muestre un infiltrado inflamatorio en la pared arterial confirmaría el diagnóstico de arteritis de células gigantes.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44574, 14319, '1. El hallazgo de HLA B*51 confirma el diagnóstico de sospecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44575, 14319, '2. Las úlceras bucales dejan cicatriz en la mayoría de los casos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44576, 14319, '3. Debe instaurar tratamiento precoz e intensivo con glucocorticoides sistémicos e inmunosupresión con azatioprina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44577, 14319, '4. La adición al tratamiento de anticuerpos monoclonales anti TNF alfa o ciclosporina no mejora el control de la uveítis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44578, 14320, '1. Glomerulonefritis pauciinmune.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44579, 14320, '2. Nefritis tubulointersticial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44580, 14320, '3. Síndrome de Goodpasture.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44581, 14320, '4. Nefropatía IgA.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44582, 14321, '1. Algunos pacientes presentan estenosis arteriales establecidas que se detectan de forma casual en una fase inactiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44583, 14321, '2. Sus manifestaciones vasculares periféricas son soplos vasculares, disminución de pulsos y claudicación de extremidades en más de la mitad de los pacientes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44584, 14321, '3. La VSG normal descartaría el diagnóstico de sospecha.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44585, 14321, '4. Un estudio angiográfico con resonancia magnética es de gran utilidad en su diagnóstico, ya que proporciona información de la luz vascular y de la afectación inflamatoria de la pared de la aorta y sus ramas principales', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44586, 14322, '1. Glomerulonefritis postinfecciosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44587, 14322, '2. Vasculitis pauciinmunitaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44588, 14322, '3. Nefropatía IgA.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44589, 14322, '4. Síndrome de Goodpasture.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44590, 14323, '1. Granulomatosis eosinofílica con poliangitis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44591, 14323, '2. Poliangitis microscópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44592, 14323, '3. Granulomatosis con poliangitis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44593, 14323, '4. Poliarteritis nudosa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44594, 14324, '1. Debe administrarse rituximab, puesto que los glucocorticoides han quedado relegados a un tratamiento de segunda línea debido a sus efectos secundarios.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44595, 14324, '2. El tocilizumab se ha mostrado eficaz en reducir las recidivas y la dosis acumulada de prednisona en más del 50 % de los pacientes.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44596, 14324, '3. En presencia de clínica isquémica, y para no empeorar el riesgo vascular del paciente, se debe evitar el uso de glucocorticoides a dosis superiores a 30 mg/día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44597, 14324, '4. Junto con bolos de glucocorticoides de 1 g/día, el infliximab debe utilizarse como fármaco de primera línea para la inducción a la remisión.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44598, 14325, '1. Predomina en el sexo femenino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44599, 14325, '2. La presencia de reactantes de fase aguda determina el pronóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44600, 14325, '3. La evolución de las lesiones depende fundamentalmente de la supresión del hábito tabáquico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44601, 14325, '4. Se caracteriza por ser una trombosis inflamatoria segmentaria, ateromatosa, que afecta a arterias y venas de mediano y pequeño calibre.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44602, 14326, '"1. Una ecografía-Doppler de las arterias renales para el diagnóstico de una arteritis de Takayasu.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44603, 14326, '2. Un biopsia cutánea tipo ""punch"" (sacabocados) para el diagnóstico de una poliarteritis nudosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44604, 14326, '3. La detección de crioglobulinas circulantes para el diagnóstico de una vasculitis crioglobulinémica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44605, 14326, '4. Una biopsia renal para el diagnóstico de una vasculitis por IgA."', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44606, 14327, '450. 000/mm3. La creatinina es de 1,7 mg/dL. Una tira reactiva urinaria muestra 510 leucocitos, 5-10 hematíes y proteínas +. Se muestra la radiografía de tórax póstero-anterior. Indique cuál de las siguientes determinaciones analíticas solicitaría para confirmar el diagnóstico:', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44607, 14327, '1. Anticuerpos anti-proteinasa 3.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44608, 14327, '2. Enzima convertidor de la angiotensina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44609, 14327, '3. Galactomanano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44610, 14327, '4. Anticuerpos anti-membrana basal glomerular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44611, 14328, '1. Se presenta fundamentalmente en personas de raza blanca y mayores de 50 años.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44612, 14328, '2. Aproximadamente una cuarta parte de los pacientes desarrollan aneurisma o dilatación de la aorta torácica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44613, 14328, '3. La pérdida de visión unilateral o bilateral es una de las complicaciones más graves.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44614, 14328, '4. La máxima incidencia se da entre la sexta y la séptima década de la vida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44615, 14329, '1. La presencia de eosinofilia periférica intensa (> 1.000 células/L) es una característica de la enfermedad.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44616, 14329, '2. Sin tratamiento, más del 80 % de los pacientes presentan una evolución favorable con resolución del cuadro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44617, 14329, '3. El rituximab ha demostrado ser efectivo para la inducción de la remisión de las formas generalizadas con afectación renal.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44618, 14329, '4. En torno al 90 % de los pacientes que tienen afectación renal muestran positividad de anticuerpos anticitoplasma del neutrófilo con especificidad frente a mieloperoxidasa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44619, 14330, '1. Enfermedad por Ig G4.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44620, 14330, '2. Enfermedad de Takayasu.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44621, 14330, '3. Arteritis de la arteria temporal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44622, 14330, '4. Tromboangeitis obliterante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44623, 14331, '1. Prednisona y ciclosporina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44624, 14331, '2. Prednisona y azatioprina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44625, 14331, '3. Prednisona y micofenolato de mofetilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44626, 14331, '4. Prednisona y ciclofosfamida.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44627, 14332, '1. Lupus eritematoso sistémico con afectación renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44628, 14332, '2. Vasculitis tipo EGPA (granulomatosis eosinofílica con poliangeitis o síndrome de ChurgStrauss).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44629, 14332, '3. Púrpura de Schönlein-Henoch.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44630, 14332, '4. Granulomatosis con poliangeitis (enfermedad de Wegener).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44631, 14333, '1. Sarcoidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44632, 14333, '2. Dermatomiositis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44633, 14333, '3. Síndrome de Behçet.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44634, 14333, '4. Lupus eritematoso sistémico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44635, 14334, '1. Prednisona 10 mg diarios v.o.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44636, 14334, '2. Metilprednisolona 1 g i.v. diario durante tres días.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44637, 14334, '3. Ciclofosfamida i.v. 1 g/m2.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44638, 14334, '4. Infliximab i.v. 3 mg/Kg.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44639, 14335, '1. Punción lumbar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44640, 14335, '2. Proteína C Reactiva.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44641, 14335, '3. Angio Resonancia Magnética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44642, 14335, '4. Ecografía carotidea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44643, 14336, '1. Iniciar tratamiento con corticoides.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44644, 14336, '2. Iniciar tratamiento con ciclofosfamida.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44645, 14336, '3. Iniciar tratamiento con micofenolato de mofetilo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44646, 14336, '4. Vigilancia expectante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44647, 14337, '1. Hemosiderosis pulmonar idiopática.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44648, 14337, '2. Síndrome de Goopasture.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44649, 14337, '3. Lupus eritematoso sistémico con afectación renal severa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44650, 14337, '4. Poliarteritis nodosa clásica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44651, 14337, '5. Poliarteritis microscópica.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44652, 14338, '1. Etanercept.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44653, 14338, '2. Ciclofosfamida endovenosa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44654, 14338, '3. AINE.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44655, 14338, '4. Metotrexate.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44656, 14338, '5. Rituximab.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44657, 14339, '1. El tratamiento con corticosteroides invalida rápidamente el resultado de la biopsia de la arteria temporal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44658, 14339, '2. Si se sospecha, en caso de síntomas visuales o si la biopsia se va a retrasar, se debe iniciar de inmediato el tratamiento con corticosteroides.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44659, 14339, '3. La ausencia de cambios inflamatorios en el segmento de arteria temporal biopsiado descarta el diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44660, 14339, '4. Es suficiente con mantener el tratamiento con corticosteroides durante dos o tres meses.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44661, 14339, '5. Si durante la reducción progresiva de los corticosteroides sube lo más mínimo la velocidad de sedimentación globular, debe subirse la dosis, aunque el paciente esté asintomático.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44662, 14340, '1. Artritis de rodillas y tobillos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44663, 14340, '2. Hematuria.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44664, 14340, '3. Plaquetopenia.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44665, 14340, '4. Sangre oculta en heces.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44666, 14340, '5. Edema escrotal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44667, 14341, '1. En el tratamiento inicial puede elegirse entre esteroides o inmunosupresores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44668, 14341, '2. La principal complicación es la amaurosis por afectación neurítica isquémica.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44669, 14341, '3. La elevación de la creatinkinasa es típica cuando existe polimialgia asociada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44670, 14341, '4. La biopsia de la arteria temporal tiene que resultar positiva para iniciar el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44671, 14341, '5. La arteritis de Takayasu es clínicamente similar pero la histología es muy diferente.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44672, 14342, '1. Se debe asegurar una ingesta adecuada de calcio y vitamina D debido al riesgo de osteoporosis esteroideas en los pacientes con edad avanzada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44673, 14342, '2. El tratamiento de elección es 60 mg de prednisona al día durante una semana y bajar a un ritmo de 10 mgs por semana y suspender.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44674, 14342, '3. En algunos pacientes la utilización de fármacos como el metotrexate o la azatioprina pueda ayudar a reducir las necesidades de esteroides para el control de los síntomas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44675, 14342, '4. La mayor parte de los síntomas desaparecen a las 48-72h de comenzar el tratamiento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44676, 14342, '5. Las dosis de esteroides deben ser incrementadas en el caso de una reactivación de los síntomas y no por elevaciones de la velocidad de sedimentación.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44677, 14343, '1. Lesiones gomosas abiertas al exterior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44678, 14343, '2. Lesiones papulovesiculosas sobre una base eritematosa.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44679, 14343, '3. Lesiones queratósicas que tienen base vesiculosa.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44680, 14343, '4. Lesiones liquenificadas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44681, 14343, '5. Se trata de lesiones verrugosas que son indicio de una evolución prolongada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44682, 14344, '1. Investigación microbiológica de una de las lesiones, mediante frotis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44683, 14344, '2. Mantoux y placa de tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44684, 14344, '3. Determinación de crioglobulinas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44685, 14344, '4. Serología luética.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44686, 14344, '5. Extirpación y estudio histopatológico de una adenopatía.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44687, 14345, '1. Nefropatía IgA.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44688, 14345, '2. Síndrome de Schönlein Henoch.', true, 2);
