INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44696, 14346, '5. Curva de la glucemia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44697, 14347, '1. Solicitar una ecografía doppler de arterias temporales', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44698, 14347, '2. Iniciar tratamiento con prednisona 60 mg al día y aspirina 100 mg al día', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44699, 14347, '3. Iniciar tratamiento con prednisona 10 mg al día', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44700, 14347, '4. Solicitar una biopsia de arteria temporal', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44701, 14347, '5. Solicitar una resonancia nuclear magnética cerebral', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44702, 14348, '1. Prednisona 20 mg cada día.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44703, 14348, '2. Prednisona 40-60 mg cada día.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44704, 14348, '3. Prednisona 40-60 mg cada día y ciclofosfamida.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44705, 14348, '4. Prednisona 40-60 mg cada día, Calcio y Vitamina D y bisfosfonatos.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44706, 14348, '5. Ciclofosfamida oral.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44707, 14349, '1. Infecciosa por bacilos Gram negativos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44708, 14349, '2. Isquémica por obstrucción proximal de los vasos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44709, 14349, '3. Inmunológica por depósitos de inmunocomplejos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44710, 14349, '4. Metabólica con depósitos de proteínas glicosiladas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44711, 14349, '5. Reacción inflamatoria a cuerpo extraño.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44712, 14350, '1. Poliarteritis Nodosa clásica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44713, 14350, '2. Granulomatosis alérgica de Churg-Strauss.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44714, 14350, '3. Granulomatosis de Wegener.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44715, 14350, '4. Arteritis de Takayasu.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44716, 14350, '5. Artritis Reumatoide.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44717, 14351, '1. Hemoglobina.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44718, 14351, '2. Recuento de leucocitos.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44719, 14351, '3. Hierro sérico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44720, 14351, '4. Alfa 2 globulinas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44721, 14351, '5. Velocidad de sedimentación globular.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44722, 14352, '1. Complemento sérico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44723, 14352, '2. Arteriografía abdominal', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44724, 14352, '3. Determinación de anticuerpos anticitoplasma del neutrófilo (ANCA).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44725, 14352, '4. Endoscopia digestiva alta.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44726, 14352, '5. Medida del flujo lagrimal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44727, 14353, '1. Puede aparecer una diferencia mayor de 10 mm Hg al medir la tensión arterial entre ambos brazos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44728, 14353, '2. El estudio complementario fundamental para el diagnóstico es la arteriografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44729, 14353, '3. Aunque es más frecuente en las razas orientales y en ciertos países de Sudamérica, se han descrito casos en todas las razas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44730, 14353, '4. El tratamiento inicial recomendado consiste en la administración de prednisona a dosis de 1 mg/kg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44731, 14353, '5. La afectación de las arterias coronarias es extremadamente frecuente.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44732, 14354, '1. En esta situación los hemocultivos ofrecen escasa rentabilidad diagnóstica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44733, 14354, '2. El test de rosa de Bengala puede resultar de gran utilidad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44734, 14354, '3. En la radiografía simple de rodilla lo esperable es encontrar únicamente aumento de panes blandas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44735, 14354, '4. Una buena aproximación terapéutica puede ser la asociación de doxiciclina (100 mg/12 horas vía oral) durante 45 días y estreptomicina (1 g/día intramuscular)', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44736, 14355, '1. Bacteriana.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44737, 14355, '2. Autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44738, 14355, '3. Microcristalina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44739, 14355, '4. Viral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44740, 14356, '1. Es un brote de artritis reumatoide insuficientemente controlado. Debe aumentarse la dosis de prednisona o asociar un antiinflamatorio vigilando la función renal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44741, 14356, '2. La leucocitosis y el tratamiento reciente con corticoides sugieren osteonecrosis aséptica de la cabeza femoral. Debe aumentarse la analgesia y asegurar descarga con bastones o encamamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44742, 14356, '3. Requiere ingreso hospitalario por sospecha de artritis infecciosa aguda de la cadera. Debe iniciarse antibioterapia de forma precoz.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44743, 14356, '4. Se trata de una artritis gotosa aguda de la cadera. Debe asociarse alopurinol y aumentar la analgesia si precisa, recurriendo a opioides mayores.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44744, 14357, '1. Practicar infiltración intrarticular con triamcinolona de la articulación afecta.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44745, 14357, '2. Iniciar tratamiento ambulatorio con amoxicilina más ácido clavulánico y valorar la respuesta en una semana.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44746, 14357, '3. Indicar ingreso y tratamiento antibiótico parenteral inmediato hasta resultado del cultivo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44747, 14357, '4. Tratamiento con corticoides a dosis bajas y alopurinol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44748, 14358, '1. Se debe iniciar tratamiento con cloxacilina y ceftriaxona en espera del resultado del cultivo del líquido.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44749, 14358, '2. Es aconsejable realizar artrocentesis diarias para aliviar los síntomas y evitar la destrucción articular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44750, 14358, '3. Si el cultivo es negativo, es probable que se trate de una artritis reactiva.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44751, 14358, '4. La negatividad de la tinción de Gram descarta que se trate de una artritis séptica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44752, 14359, '1. Estreptococo viridans.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44753, 14359, '2. Estafilococo aureus.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44754, 14359, '3. Neisseria gonorrhoeae.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44755, 14359, '4. Estreptococo pneumoniae.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44756, 14360, '1. Artritis reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44757, 14360, '2. Síndrome de Reiter.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44758, 14360, '3. Gota úrica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44759, 14360, '4. Artritis gonocócica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44760, 14360, '5. Vasculitis de Cogan.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44761, 14361, '1. Artritis por microcristales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44762, 14361, '2. Artritis reactiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44763, 14361, '3. Artritis infecciosa bacteriana.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44764, 14361, '4. Artritis infecciosa por mycobacterias.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44765, 14361, '5. Artritis reumatoide.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44766, 14362, '1. Antibioterapia empírica IV con cobertura para S. aureus, y específica cuando se disponga de cultivo y antibiograma.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44767, 14362, '2. Análisis bioquímico del líquido obtenido, y cultivo del mismo. Si los resultados confirman el diagnóstico de artritis séptica, realizar el drenaje quirúrgico y la antibioterapia específica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44768, 14362, '3. Realización de punción articular guiada por ecografía para desbridamiento y antibioterapia local intrarticular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44769, 14362, '4. Artrocentesis de repetición hasta lograr la reducción de los síntomas inflamatorios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44770, 14362, '5. Drenaje quirúrgico urgente, y antibioterapia IV empírica hasta disponer de antibiograma.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44771, 14363, '1. Lupus eritematoso sistemico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44772, 14363, '2. Artritis Reumatoide.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44773, 14363, '3. Artritis por Parvovirus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44774, 14363, '4. Artritis Reactiva.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44775, 14363, '5. Espondiloartropatia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44776, 14364, '1. La elevación de la proteína C reactiva confirma el diagnostico.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44777, 14364, '2. La radiografía simple no es necesaria ya que en fases iniciales no muestra alteraciones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44778, 14364, '3. La ecografía es poco sensible para detectar la presencia de líquido articular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44779, 14364, '4. La resonancia magnética es la prueba de elección para el despistaje de infección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44780, 14364, '5. La punción articular tiene valor diagnóstico y en algunos casos terapéutico.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44781, 14365, '1. Pielonefritis aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44782, 14365, '2. Un nuevo episodio de sepsis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44783, 14365, '3. Osteomielitis vertebral con absceso epidural.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44784, 14365, '4. Obstrucción de la vía urinaria con infección.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44785, 14365, '5. Proceso infeccioso retroperitoneal.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44786, 14366, '1. Cultivo del líquido sinovial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44787, 14366, '2. Cultivo de sangre.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44788, 14366, '3. Cultivo de endocervix.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44789, 14366, '4. Biopsia cutánea.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44790, 14366, '5. Determinación de auto anticuerpos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44791, 14367, '1. La forma más común de afectación vertebral es la diseminación por contigüidad de un foco parameníngeo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44792, 14367, '2. El agente causal más frecuente es Escherichia Coli.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44793, 14367, '3. La resonancia magnética es el procedimiento diagnóstico de elección.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44794, 14367, '4. La evolución sólo con tratamiento médico es generalmente desfavorable.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44795, 14367, '5. La duración recomendable del tratamiento antibiótico es de 4 semanas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44796, 14368, '1. Viscosidad alta, leucocitosis <2000/μL de predominio polimorfonuclear, cristales de pirofosfato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44797, 14368, '2. Viscosidad alta, leucocitosis <2000/μL de predominio polimorfonuclear, cristales de ácido úrico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44798, 14368, '3. Viscosidad baja, leucocitosis >50000/μL de predominio polimorfonuclear, ausencia de cristales.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44799, 14368, '4. Viscosidad baja, linfocitosis, ausencia de cristales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44800, 14368, '5. Viscosidad alta, leucocitosis >50000/μL de predominio polimorfonuclear, ausencia de cristales.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44801, 14369, '1. Trombosis arterial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44802, 14369, '2. Proliferación de la íntima arterial sin datos de vasculitis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44803, 14369, '3. Fibrosis estoriforme.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44804, 14369, '4. Infiltrado perivascular de polimorfonucleares', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44805, 14370, '1. Sarcoidosis.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44806, 14370, '2. Fibrosis pulmonar idiopática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44807, 14370, '3. Neumonitis por hipersensibilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44808, 14370, '4. Proteinosis alveolar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44809, 14371, '1. Penfigoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44810, 14371, '2. Policondritis recidivante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44811, 14371, '3. Sarcoidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44812, 14371, '4. Pénfigo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44813, 14372, '1. La disminución de interleuquina 6 se relaciona con fragilidad y demencia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44814, 14372, '2. Disminuye el número de linfocitos T.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44815, 14372, '3. Disminuye el factor de necrosis tumoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44816, 14372, '4. Disminuye la producción de autoanticuerpos por los linfocitos B', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44817, 14373, '1. Fiebre y adenopatías.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44818, 14373, '2. Anticuerpos anti-La y anti-Ro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44819, 14373, '3. Esplenomegalia y pancitopenia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44820, 14373, '4. Hipocomplementemia y crioglobulinemia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44821, 14374, '1. Conjuntivitis alérgica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44822, 14374, '2. Epiescleritis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44823, 14374, '3. Pinguécula.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44824, 14374, '4. Queratoconjuntivitis seca.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44825, 14375, '1. Poliartritis de grandes y pequeñas articulaciones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44826, 14375, '2. Fenómeno de Raynaud.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44827, 14375, '3. Hepatoesplenomegalia.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44828, 14375, '4. Crioglobulinemia.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44829, 14376, '1. Artritis reumatoide, iniciaría tratamiento con metotrexato.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44830, 14376, '2. Fibromialgia, iniciaría tratamiento con duloxetina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44831, 14376, '3. Polimialgia reumática, iniciaría tratamiento con corticoides.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44832, 14376, '4. Espondilitis anquilosante, iniciaría tratamiento con antiinflamatorios no esteroideos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44833, 14377, '1. El cartílago articular hialino está formado fundamentalmente por colágeno', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44834, 14377, '2. Los proteoglicanos de la matriz extracelular del cartílago hialino son macromoléculas formadas por proteínas y glicosaminoglicanos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44835, 14377, '3. El condrocito vive en un medio acidótico e hipóxico y emplea la glucólisis anaerobia para producir energía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44836, 14377, '4. Los sinoviocitos tipo A son similares a macrófagos, son fagocíticos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44837, 14377, '5. Una entesis es la región donde un tendón, ligamento o cápsula articular se une directa o indirectamente al hueso', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44838, 14378, '1. Diabetes Mellitus.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44839, 14378, '2. Lepra.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44840, 14378, '3. Amiloidosis.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44841, 14378, '4. Osteoartropatía hipertrófica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44842, 14378, '5. Siringomielia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44843, 14379, '1. Los anticuerpos antinucleares son útiles en el proceso diagnóstico, pero no tienen ningún papel en el seguimiento posterior de estas enfermedades.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44844, 14379, '2. En ausencia de clínica, la presencia de anticuerpos anticardiolipina no son diagnósticos de un síndrome antifosfolipídico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44845, 14379, '3. La ausencia o resultado negativo en el estudio de los anticuerpos antinucleares permite descartar la presencia de un Lupus.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44846, 14379, '4. La determinación periódica de los anticuerpos anti-DNA y de los niveles del complemento, son útiles en el seguimiento de la actividad clínica del lupus.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44847, 14379, '5. La presencia de anticuerpos anti-Ro no es diagnóstico de Síndrome de Sjögren Primario, pues pueden observarse también en otras enfermedades sistémicas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44848, 14380, '1. Artrocentesis, examen del líquido sinovial con microscopio de luz polarizada y test de Gram urgente.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44849, 14380, '2. Tratamiento con antibióticos intraarticulares.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44850, 14380, '3. Estudio inmunológico, incluyendo factor reumatoide.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44851, 14380, '4. Lavado articular y tratamiento con antibióticos intravenosos.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44852, 14380, '5. Artrocentesis e infiltración con corticosteroides de acción prolongada.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44853, 14381, '1. AngioTC helicoidal con contraste.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44854, 14381, '2. Gammagrafía pulmonar de perfusión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44855, 14381, '3. Radiografía de tórax.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44856, 14381, '4. Ecocardiografía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44857, 14382, '1. Fractura-luxación de Monteggia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44858, 14382, '2. Fractura de la cabeza radial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44859, 14382, '3. Epifisiolisis distal del radio.', true, 3);
