INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44982, 14410, '1. Actitud expectante, ya que se trata de un hueso sin carga, lo que reduce el riesgo de fractura.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (44983, 14410, '2. Aplicación de mórficos a dosis altas para controlar el dolor que le permitan realizar fisioterapia para recuperar la función.', false, 2);
