INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45400, 14505, '1. Rotura en asa de cubo del menisco interno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45032, 14422, '1. Los músculos que forman el manguito de los rotadores son el subescapular, el supraespinoso, el infraespinoso y el redondo mayor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45033, 14422, '2. Los tendones de los músculos del manguito refuerzan la cápsula fibrosa de la articulación escápulo-humeral.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45034, 14422, '3. El músculo infraespinoso rota el brazo en dirección interna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45035, 14422, '4. El músculo supraespinoso ayuda a la aducción (aproximación) del brazo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45036, 14423, '1. Iniciar tratamiento con AINE, solicitar una ecografía y derivar a rehabilitación', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45037, 14423, '2. Derivar a un cirujano especialista para hacer una artroscopia de hombro.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45038, 14423, '3. Si hay limitación pasiva del balance articular, con la sospecha de capsulitis adhesiva, derivar a rehabilitación urgente para movilizaciones pasivas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45039, 14423, '4. Se sospecha una lesión del manguito de los rotadores (supraespinoso con bursitis subacromial), por lo que hay que potenciar la musculatura descoaptante del hombro.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45040, 14424, '1. Prótesis anatómica de hombro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45041, 14424, '2. Infiltración del resto de manguito con células mesenquimales.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45042, 14424, '3. Reparación artroscópica del manguito rotador mediante anclajes en doble hilera.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45043, 14424, '4. Prótesis invertida de hombro.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45044, 14425, '1. Capsulitis adhesiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45045, 14425, '2. Lesión del labrum', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45046, 14425, '3. Bursitis subacromial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45047, 14425, '4. Tendinitis cálcica.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45048, 14426, '1. Inestabilidad de hombro asociada a laxitud.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45049, 14426, '2. Rotura del manguito de los rotadores del hombro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45050, 14426, '3. Capsulitis adhesiva de hombro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45051, 14426, '4. Tendinitis calcificante del tendón supraespinoso del hombro.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45052, 14427, '1. Una tumoración maligna localizada en la epífisis proximal de húmero.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45053, 14427, '2. Una artritis séptica de hombro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45054, 14427, '3. Una capsulitis adhesiva.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45055, 14427, '4. Un proceso degenerativo artrósico acromioclavicular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45056, 14428, '1. Clavo trocantérico largo acerrojado proximal y distal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45057, 14428, '2. Rehabilitación intensiva inmediata sin inmovilización.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45058, 14428, '3. Inmovilización con yeso braquial colgante de Caldwell.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45059, 14428, '4. Artroplastia glenohumeral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45060, 14429, '1. Tendinopatía del redondo mayor.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45061, 14429, '2. Capsulitis adhesiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45062, 14429, '3. Neuropatía del nervio supraescapular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45063, 14429, '4. Lesión del nervio axilar.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45064, 14430, '1. Una lesión del nervio radial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45065, 14430, '2. Una lesión del nervio axilar (circunflejo).', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45066, 14430, '3. Una lesión del nervio musculocutáneo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45067, 14430, '4. Una rotura de los ligamentos escapulohumerales.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45068, 14431, '1. Antecedentes de fractura del tercio medio de la clavícula contralateral.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45069, 14431, '2. Lesión neurovascular que persiste tras la reducción cerrada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45070, 14431, '3. Hombro flotante, con fractura de clavícula asociada a fractura de escápula (cuello).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45071, 14431, '4. Fracturas abiertas que requieren limpieza y desbridamiento del foco.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45072, 14432, '1. Fractura aislada de troquíter mínimamente desplazada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45073, 14432, '2. Luxación glenohumeral posterior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45074, 14432, '3. Fractura-luxación de extremo proximal de húmero.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45075, 14432, '4. Luxación anterior glenohumeral asociada a fractura de troquíter.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45076, 14432, '5. Fractura-luxación de extremo proximal de húmero con necrosis.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45077, 14433, '1. Reducción cerrada y fijación del troquíter si permanece desplazado.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45078, 14433, '2. Inmovilización durante 3 semanas, y fisioterapia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45079, 14433, '3. Artroplastia parcial de hombro.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45080, 14433, '4. Enclavado intramedular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45081, 14433, '5. Artroplastia total de hombro.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45082, 14434, '1. Vendaje de yeso.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45083, 14434, '2. No precisa tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45084, 14434, '3. Férula de abducción.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45085, 14434, '4. Reducción y osteosintesis con agujas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45086, 14434, '5. Vendaje en 8.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45087, 14435, '1. Realizar una arteriografía de la arteria humeral.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45088, 14435, '2. Reducir y fijar la fractura en quirófano y observar la respuesta vascular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45089, 14435, '3. Proceder a la exploración quirúrgica de la arteria humeral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45090, 14435, '4. Hacer una ecografía Doppler de la arteria radial a nivel de la muñeca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45091, 14436, '1. Se desencadenan por un mecanismo de valgo forzado del codo en la caída.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45092, 14436, '2. Están asociadas hasta en un 50 % de los casos con una luxación postero-lateral del codo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45093, 14436, '3. Pueden presentar asociada una neurapraxia del nervio cubital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45094, 14436, '4. Es más frecuente en niños de edades entre 4 y 6 años.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45095, 14437, '1. Fractura luxación de húmero proximal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45096, 14437, '2. Luxación de codo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45097, 14437, '3. Fractura diafisaria de húmero asociada a fractura doble de antebrazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45098, 14437, '4. Fractura diafisaria de húmero con lesión del nervio radial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45099, 14438, '1. Fractura en tallo verde de radio y cúbito.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45100, 14438, '2. Esguince de muñeca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45101, 14438, '3. Fractura aislada de radio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45102, 14438, '4. Fractura espiroidea larga de cúbito aislada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45103, 14439, '1. Está inervada por el nervio mediano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45104, 14439, '2. Tiene como función la supinación del antebrazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45105, 14439, '3. Participa en la estabilidad de la articulación radiocubital distal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45180, 14455, '4. La rotura del extensor largo del pulgar no es una complicación de estas fracturas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45106, 14439, '4. Tiene su origen en el cuarto distal de la cara anterior del cúbito y su inserción en el cuarto distal de la cara anterior del radio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45107, 14440, '1. Neuritis nervio cubital.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45108, 14440, '2. Osificación heterotópica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45109, 14440, '3. Molestias derivadas del material de síntesis implantado.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45110, 14440, '4. Limitación de la flexión del codo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45111, 14441, '1. Fractura de troquíter en húmero izquierdo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45112, 14441, '2. Fractura diafisaria de húmero izquierdo con lesión del nervio radial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45113, 14441, '3. Fractura supraintercondílea de paleta humeral con lesión del nervio mediano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45114, 14441, '4. Fractura de cuello anatómico de húmero con lesión del nervio radial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45115, 14441, '5. Fractura de epitróclea desplazada con lesión del nervio cubital.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45116, 14442, '1. Nervio musculocutáneo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45117, 14442, '2. Nervio radial.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45118, 14442, '3. Nervio cubital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45119, 14442, '4. Nervio mediano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45120, 14442, '5. Nervio circunflejo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45121, 14443, '1. Paciente politraumatizado.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45122, 14443, '2. Fractura patológica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45123, 14443, '3. Lesión asociada de la arteria braquial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45124, 14443, '4. Angulación en el foco de fractura de 10 grados.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45125, 14443, '5. Lesión asociada ipsilateral del cúbito y radio (codo flotante).', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45126, 14444, '1. Mediano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45127, 14444, '2. Axial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45128, 14444, '3. Cubital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45129, 14444, '4. Radial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45130, 14444, '5. Safeno.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45131, 14445, '1. Fractura de cúbito y radio con luxación de cabeza radial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45132, 14445, '2. Fractura-luxación de la cabeza radial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45133, 14445, '3. Fractura del olécranon y luxación de cabeza radial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45134, 14445, '4. Fractura supracondílea del codo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45135, 14445, '5. Fractura-epifisiolisis de epitróclea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45136, 14446, '1. Lesión arteria humeral y nervio mediano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45137, 14446, '2. Lesión nervio cubital.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45138, 14446, '3. Lesión nervio radial.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45139, 14446, '4. Lesión nervio mediano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45140, 14446, '5. Lesión nervios radial y mediano.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45141, 14447, '1. Una radiografía de codo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45142, 14447, '2. Retirar la escayola.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45143, 14447, '3. Una analítica con iones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45144, 14447, '4. Administrar un analgésico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45145, 14447, '5. Sujetar el brazo con una charpa.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45146, 14448, '1. Síndrome de dolor regional complejo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45147, 14448, '2. Síndrome compartimental local.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45148, 14448, '3. Rotura tendinosa de extensores.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45149, 14448, '4. Desplazamiento secundario de la fractura.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45150, 14449, '1. Reducción cerrada y yeso antebraquial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45151, 14449, '2. Artroplastia total de muñeca.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45152, 14449, '3. Osteosíntesis con placas dorsal y volar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45153, 14449, '4. No inmovilizar, rehabilitación inmediata.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45154, 14450, '1. Suele cursar con una necrosis del fragmento distal de la fractura.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45155, 14450, '2. Puede cursar de manera asintomática.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45156, 14450, '3. A largo plazo suele provocar una artrosis radiocarpiana.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45157, 14450, '4. En estadios iniciales el tratamiento de elección es la fijación de la fractura y aporte de injerto óseo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45158, 14451, '1. Dado que se trata de una fractura extrarticular, se considera una fractura estable. Se mantendrá la inmovilización durante 2 semanas y a partir de entonces se iniciará programa de ejercicios activos de flexoextensión y pronosupinación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45159, 14451, '2. Dado que la reducción lograda es óptima, se recomienda control radiológico a los 10-15 días y en caso de no observarse desplazamiento secundario de la fractura, se mantendrá la inmovilización un total de 6 semanas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45160, 14451, '3. La fractura de estiloides cubital determina la existencia de una inestabilidad radiocubital distal, que exige su reparación quirúrgica en un segundo tiempo. En el mismo acto quirúrgico se debe realizar la osteosíntesis del radio con placa atornillada.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45161, 14451, '4. Dada la osteoporosis de la paciente, la probabilidad de desplazamiento de la fractura es muy elevada. El tratamiento más recomendable es quirúrgico de entrada, con colocación de fijador externo asociado a fijación interna con placa atornillada.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45162, 14452, '1. Un tiempo máximo de 2 semanas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45163, 14452, '2. Un tiempo máximo de 6 semanas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45164, 14452, '3. Un tiempo máximo de 10 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45165, 14452, '4. Un tiempo máximo de 14 semanas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45166, 14452, '5. Un tiempo máximo de 18 semanas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45167, 14453, '1. No efectuar ningún tratamiento.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45168, 14453, '2. Realizar una tomografía axial computarizada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45169, 14453, '3. Inmovilizar la muñeca con un yeso de escafoides y repetir la radiografía a las dos semanas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45170, 14453, '4. Realizar tratamiento médico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45171, 14453, '5. Pedir una gammagrafía ósea.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45172, 14454, '1. Mantener el yeso, AINE y remitir al paciente a consultas externas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45173, 14454, '2. Observación prolongada (al menos 48 horas) del paciente con la extremidad elevada, instándole a mover activamente los dedos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45174, 14454, '3. Abrir el yeso y prescribir antiinflamatorios y diuréticos como tratamiento para su domicilio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45175, 14454, '4. Abrir el yeso, AINE y remitir a consultas externas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45176, 14454, '5. Abrir el yeso, observación del paciente y estimular la movilidad activa, y si no mejora rápidamente fasciotomía urgente.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45177, 14455, '1. Más frecuente en hombres.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45178, 14455, '2. La mayoría se producen como consecuencia de una caída con la muñeca en flexión.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45179, 14455, '3. La mayoría responden favorablemente al tratamiento conservador.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45181, 14455, '5. El tratamiento quirúrgico está contraindicado.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45182, 14456, '1. Mantener el yeso, administrar antiinflamatorios y remitir a la paciente a consultas externas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45183, 14456, '2. Mantener el yeso, elevar la mano, ingresar a la paciente en observación instándole a mover activamente los dedos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45184, 14456, '3. Abrir el yeso, antiinflamatorios y diuréticos, estimular la movilidad activa, y si no mejora rápidamente osteosíntesis de la fractura.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45185, 14456, '4. Abrir el yeso, administrar antiinflamatorios y remitir a la paciente a consultas externa.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45186, 14456, '5. Abrir el yeso, antiinflamatorios y diuréticos, estimular la movilidad activa, y si no mejora rápidamente fasciotomía urgente.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45187, 14457, '1. Epicondilopatía medial.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45188, 14457, '2. Epicondilopatía lateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45189, 14457, '3. Síndrome compartimental crónico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45190, 14457, '4. Neuropatía cubital por atrapamiento en canal epitrócleo-olecraniano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45191, 14458, '1. Síndrome del túnel carpiano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45192, 14458, '2. Hernia discal cervical C3-C4.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45193, 14458, '3. Compresión cubital epitroclear.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45194, 14458, '4. Tendinitis de De Quervain.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45195, 14459, '1. Es más frecuente en varones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45196, 14459, '2. Cursa con hipoestesia en el pulpejo de los dedos segundo a quinto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45197, 14459, '3. Los síntomas se exacerban durante la noche.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45198, 14459, '4. Se acompaña de atrofia de la musculatura de la eminencia hipotenar.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45199, 14460, '1. Afecta con mayor frecuencia a los dedos anular y meñique.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45200, 14460, '2. El tratamiento conservador con fisioterapia es poco eficaz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45201, 14460, '3. Es un engrosamiento y retracción de la aponeurosis palmar.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45202, 14460, '4. Es más frecuente en trabajadores manuales.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45203, 14461, '1. Si la exploración neurológica muestra adormecimiento de los dedos primero a tercero pensaremos en afectación del nervio cubital a nivel epitroclear.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45204, 14461, '2. Si la exploración neurológica muestra adormecimiento de los dedos primero a tercero pensaremos en afectación del nervio mediano a nivel del canal del carpo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45205, 14461, '3. Para realizar el diagnóstico no es preciso realizar una electromiografía, dado que la exploración física presenta muy buenos coeficientes de probabilidad.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45206, 14461, '4. El tratamiento de la afectación del nervio cubital a nivel epitroclear o del nervio mediano a nivel carpiano es la intervención quirúrgica, dado que el tratamiento conservador no mejora la sintomatología.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45207, 14462, '1. Tendón del flexor cubital del carpo', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45208, 14462, '2. Tendón del abductor largo del pulgar', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45209, 14462, '3. Tendón del flexor profundo de los dedos', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45210, 14462, '4. Tendón del flexor radial del carpo', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45211, 14462, '5. Tendón del palmar largo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45212, 14463, '1. Compresión proximal nervio cubital.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45213, 14463, '2. Síndrome canal carpiano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45214, 14463, '3. Sección nervio cubital.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45215, 14463, '4. Atrapamiento nervio mediano y cubital a nivel de la muñeca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45216, 14463, '5. Compresión del nervio radial.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45217, 14464, '1. Serie de 3 infiltraciones con corticoide y anestésico local.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45218, 14464, '2. Antiinflamatorios, codera con dispositivo de presión, aplicación de calor local.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45219, 14464, '3. Resonancia magnética.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45220, 14464, '4. Inmovilización con yeso braquial.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45221, 14464, '5. Indicación quirúrgica inmediata.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45222, 14465, '1. Distrofia simpático refleja.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45223, 14465, '2. Artrosis postraumática del carpo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45224, 14465, '3. Ruptura del tendón extensor del 2 y 3 dedo de la mano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45225, 14465, '4. Síndrome del túnel del carpo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45226, 14465, '5. Radiculalgia C5-C6.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45227, 14466, '1. N. mediano y flexor profundo de 4º dedo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45228, 14466, '2. N. mediano y flexor superficial de 4º dedo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45229, 14466, '3. N. cubital y flexor superficial de 4º dedo.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45230, 14466, '4. N. radial y flexor superficial de 4º dedo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45231, 14466, '5. N. radial y flexor profundo de 4º dedo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45232, 14467, '1. Fractura pertrocantérea de fémur izquierdo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45233, 14467, '2. Fractura subcapital de fémur izquierdo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45234, 14467, '3. Luxación anterior de cadera, con fractura de pared anterior de acetábulo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45235, 14467, '4. Luxación posterior de cadera, con fractura de pared posterior de acetábulo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45236, 14468, '1. Hemiartroplastia de cadera.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45237, 14468, '2. Fijación con clavo trocantérico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45238, 14468, '3. Fijación con tornillos canulados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45239, 14468, '4. Conservador: vida cama-sillón.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45240, 14469, '1. La baja adherencia al tratamiento se asocia a un incremento del riesgo de fractura.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45241, 14469, '2. Los marcadores de remodelado óseo pueden ser útiles para monitorizar de forma precoz la respuesta al tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45242, 14469, '3. La vitamina D en monoterapia es eficaz en la reducción de dichas fracturas en personas mayores no institucionalizadas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45243, 14469, '4. El aumento de calcio dietético o tomar suplementos de calcio de forma aislada no protegen frente a la aparición de fracturas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45244, 14470, '1. Clavo trocantérico en mesa ortopédica.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45245, 14470, '2. Prótesis parcial bipolar de cadera.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45246, 14470, '3. Osteosíntesis con tornillos canulados.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45247, 14470, '4. No cirugía, vida cama-sillón precoz.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45248, 14471, '1. El miembro inferior se encuentra en flexión, rotación externa y abducción.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45249, 14471, '2. Hay que realizar una reducción de urgencia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45250, 14471, '3. Una de sus complicaciones posibles es la necrosis de la cabeza femoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45251, 14471, '4. Una vez reducida, son infrecuentes las recidivas.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45252, 14472, '1. Ingreso para ecografía transtorácica, valoración por Cardiología y después reducción cerrada y fijación con tornilloplaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45253, 14472, '2. Ingreso para valoración por Nefrología y Cardiología, y después decidirá Traumatología si usa una artroplastia o un clavo trocantérico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45254, 14472, '3. Ingreso en Medicina Interna/Geriatría, estabilización progresiva de las comorbilidades, tratamiento ortopédico conservador.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45255, 14472, '4. Reducción cerrada y fijación de la fractura antes de 48 horas, sedestación muy precoz, manejo ortogeriátrico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45256, 14473, '1. Realizar ecografía abdominal en el box de Urgencias.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45257, 14473, '2. Solicitar tomografía computa-rizada de tórax.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45258, 14473, '3. Solicitar angiografía pélvica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45259, 14473, '4. Solicitar tomografía computarizada de abdomen y pelvis.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45260, 14473, '5. Ingresar inmediatamente al paciente en la unidad de cuidados intensivos.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45261, 14474, '1. Luxación traumática posterior de la cadera.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45262, 14474, '2. Fractura desplazada del cuello femoral del anciano.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45263, 14474, '3. Fractura trocantérea del anciano.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45264, 14474, '4. Fractura de cotilo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45265, 14474, '5. Fractura subtrocantérea', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45266, 14475, '1. Fractura subtrocantérea de fémur.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45267, 14475, '2. Fractura subcapital de fémur.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45268, 14475, '3. Luxación coxofemoral anterior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45269, 14475, '4. Luxación coxofemoral posterior.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45270, 14475, '5. Fractura pertrocantérea de fémur.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45271, 14476, '1. Tracción transesquelética durante 3 semanas y descarga del miembro hasta el tercer mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45272, 14476, '2. Reducción cerrada y osteosíntesis.', true, 2);
