INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45274, 14476, '4. Artroplastia total de cadera.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45275, 14476, '5. Reducción abierta e inmovilización con yeso pelvipédico durante seis semanas.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45276, 14477, '1. Artritis séptica de cadera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45277, 14477, '2. Lesión de arteria femoral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45278, 14477, '3. Necrosis avascular de la cabeza femoral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45279, 14477, '4. Pinzamiento femoroacetabular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45280, 14477, '5. Neuroapraxia de nervio femorocutáneo.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45281, 14478, '1. Retrasar la cirugía hasta que haya desaparecido el cuadro confusional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45282, 14478, '2. Retrasar la cirugía y realizar un ecocardiograma.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45283, 14478, '3. Retrasar la cirugía hasta un buen control de la tensión arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45284, 14478, '4. Iniciar un betabloqueante y realizar la cirugía.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45285, 14478, '5. Realizar osteosíntesis cerrada, evitado en todo caso la implantación de prótesis.', false, 5);
