INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45287, 14479, '2. Reducción y osteosíntesis con tornillo-clavo deslizante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45288, 14479, '3. Reducción y osteosíntesis con tornillos canulados.', true, 3);
