INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45292, 14480, '2. Osteonecrosis multifocal.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45293, 14480, '3. Epifisiolisis bilateral de cadera.', false, 3);
