INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45296, 14481, '2. Oclusión intravascular por émbolos (lípidos, nitrógeno, hematíes anómalos).', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45297, 14481, '3. Dehiscencia de la íntima arterial de los vasos.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45298, 14481, '4. Compresión extravascular a consecuencia de un acúmulo graso.', false, 4);
