INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45302, 14482, '4. Síndrome del piramidal.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45303, 14483, '1. Observación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45304, 14483, '2. Descompresión central de la cadera con o sin terapia celular complementaria.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45305, 14483, '3. Osteotomía de rotación del extremo proximal del fémur.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45306, 14483, '4. Prótesis total de cadera.', false, 4);
