INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45308, 14484, '2. Artrosis de cadera.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45309, 14484, '3. Necrosis avascular de la cabeza femoral.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45310, 14484, '4. Osteosarcoma.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45311, 14485, '1. Indicar un estudio gammagráfico para descartar la presencia de lesiones similares en otras grandes articulaciones.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45312, 14485, '2. Realizar un estudio de extensión y despistaje de lesión primaria, pues se trata de una metástasis ósea en la cadera izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45313, 14485, '3. Realizar el diagnóstico probable de necrosis avascular de la cadera izquierda e indicar un estudio con RM de ambas caderas.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45314, 14485, '4. Realizar el diagnóstico de osteoporosis transitoria de cadera izquierda, indicar 2 meses de descarga y repetir el estudio radiológico en ese momento.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45315, 14486, '1. Hago el diagnóstico de coxartrosis y envío al traumatólogo para colocar una prótesis de cadera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45316, 14486, '2. Inicio tratamiento con opioides débiles que han demostrado evidencia en detener la progresión de la enfermedad.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45317, 14486, '3. Instauro tratamiento con paracetamol, explico que la evolución es muy variable y la indicación quirúrgica depende de la funcionalidad y control del dolor.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45318, 14486, '4. Por las características radiológicas descritas, necesito una RMN de cadera antes de tomar una decisión terapéutica', false, 4);
