INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45322, 14487, '4. Forage descompresivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45323, 14487, '5. Reparación del labrum y microfracturas de la zona de la lesión mediante artroscopia.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45324, 14488, '1. Artritis reumatoide.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45325, 14488, '2. Artritis postraumática.', false, 2);
