INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45328, 14488, '5. Trocanteritis del trocanter mayor del fémur.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45329, 14489, '1. La relación hombre mujer es ligeramente superior en el hombre 2:1.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45330, 14489, '2. Puede cursar con brotes de inflamación con dolor nocturno.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45331, 14489, '3. La velocidad de sedimentación globular es inferior a 20 mm/h.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45332, 14489, '4. Puede presentar pinzamiento articular asimétrico en cualquier zona de la articulación.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45333, 14489, '5. El control del sobrepeso y la utilización de un bastón resulta útil para mejorar el dolor.', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45334, 14490, '1. Osteoporosis transitoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45335, 14490, '2. Coxartrosis.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45336, 14490, '3. Fractura por estrés del cuello femoral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45337, 14490, '4. Espondilitis anquilosante con afectación monoarticular.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45338, 14490, '5. Necrosis isquémica de la cabeza femoral.', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45339, 14491, '1. Radiografía de cadera.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45340, 14491, '2. Ecografía de cadera.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45341, 14491, '3. RM de ambas caderas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45342, 14491, '4. Artrografía de cadera.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45343, 14492, '1. Fractura de cadera como consecuencia de la caída sufrida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45344, 14492, '2. Epifisiolisis traumática de cadera izquierda.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45345, 14492, '3. Artritis séptica de cadera izquierda.', false, 3);
