INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45349, 14493, '3. Artritis séptica de cadera.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45350, 14493, '4. Se necesita realizar una artrocentesis para establecer el diagnóstico.', false, 4);
