INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45361, 14496, '1. Se aconseja la realización de una radiografía de caderas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45362, 14496, '2. En la sinovitis transitoria el comienzo suele ser agudo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45363, 14496, '3. En la enfermedad de Legg-Calvé-Perthes el pronóstico es peor cuanto menor es la edad de comienzo.', true, 3);
