INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45683, 14568, '1. Suspender ambos antiagregantes plaquetarios 7 días antes de la operación, por el riesgo de hemorragia durante la intervención.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45684, 14568, '2. Sustituir la doble antiagregación 7 días antes de la intervención, por heparina de bajo peso molecular, a una dosis de 0,5 mg por Kg de peso cada 12 horas, administrando la última dosis 12 horas antes de la intervención quirúrgica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45685, 14568, '3. Suspender el clopidogrel 7 días antes de la operación y mantener el ácido acetil salicílico hasta el día de la intervención, para prevenir la obstrucción de los “stents” coronarios sin aumentar en exceso el riesgo de hemorragia intraoperatoria.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45686, 14568, '4. Mantener los dos antiagregantes plaquetarios 7 días antes de la intervención, dado que existe un riesgo muy elevado de obstrucción de los “stents” coronarios.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45687, 14568, '5. Suspender el ácido acetil salicílico, mantener el clopidogrel hasta la intervención y complementar con heparina de bajo peso molecular hasta 12 horas antes de la misma', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45688, 14569, '1. Isquemia crítica de miembro inferior derecho.', false, 1);
