INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45692, 14569, '5. Radiculopatía', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45698, 14571, '1. En cuanto al colesterol LDL, el objetivo terapéutico depende del riesgo cardiovascular global.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45699, 14571, '2. Los pacientes diabéticos tipo 2 deben considerarse de alto riesgo cardiovascular y el objetivo en cuanto a colesterol LDL debe ser <100 mg/dL.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45700, 14571, '3. No hay evidencia suficiente de que niveles bajos de colesterol HDL supongan un factor de riesgo cardiovascular.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45701, 14571, '4. Lo importante en el riesgo asociado a hipertensión arterial es que mejora cuando se reduce la presión arterial independientemente del tipo de fármaco utilizado.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45702, 14571, '5. La existencia de enfermedad coronaria en la familia es un factor de riesgo para el paciente', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45703, 14572, '1. Análisis de las curvas de flujo por velocimetría doppler.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45704, 14572, '2. Medición segmentaria de presiones.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45705, 14572, '3. Valoración del índice tobillo-brazo o índice de Yao.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45706, 14572, '4. Pletismografía a nivel distal de las extremidades', false, 4);
