INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45712, 14574, '2. Enfermedad de Takayasu.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45713, 14574, '3. Arteritis de la arteria temporal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45714, 14574, '4. Tromboangeitis obliterante.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45715, 14575, '1. Es un cuadro clínico que comprende la triada claudicación plantar, impotencia coeundi y ausencia de pulsos distales.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45716, 14575, '2. Es consecuencia de una oclusión fémoropoplítea bilateral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45717, 14575, '3. Los pulsos femorales están ausentes.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45718, 14575, '4. La arteriografía es la primera prueba diagnóstica a realizar', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45719, 14576, '1. Índice tobillo brazo.', true, 1);
