INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45723, 14577, '1. Predomina en el sexo femenino.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45724, 14577, '2. La presencia de reactantes de fase aguda determina el pronóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45725, 14577, '3. La evolución de las lesiones depende fundamentalmente de la supresión del hábito tabáquico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45726, 14577, '4. Se caracteriza por ser una trombosis inflamatoria segmentaria, ateromatosa, que afecta a arterias y venas de mediano y pequeño calibre', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45727, 14578, '1. Viscosidad de la sangre.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45728, 14578, '2. Velocidad del flujo sanguíneo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45729, 14578, '3. Diámetro del vaso sanguíneo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45730, 14578, '4. Densidad de la sangre', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45731, 14579, '1. Algunos pacientes presentan estenosis arteriales establecidas que se detectan de forma casual en una fase inactiva.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45732, 14579, '2. Sus manifestaciones vasculares periféricas son soplos vasculares, disminución de pulsos y claudicación de extremidades en más de la mitad de los pacientes.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45733, 14579, '3. La VSG normal descartaría el diagnóstico de sospecha.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45734, 14579, '4. Un estudio angiográfico con resonancia magnética es de gran utilidad en su diagnóstico, ya que proporciona información de la luz vascular y de la afectación inflamatoria de la pared de la aorta y sus ramas principales', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45735, 14580, '1. Se obtiene calculando la relación entre la presión diastólica en el tobillo y la presión diastólica braquial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45736, 14580, '2. Se considera normal si se obtienen valores entre 1 y 1,5.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45737, 14580, '3. Tiene una sensibilidad del 95 % y una especificidad del 60 % para el diagnóstico de enfermedad arterial periférica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45738, 14580, '4. Se considera un indicador por sí mismo de enfermedad arteriosclerótica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45739, 14581, '1. Solicitar una TC torácica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45740, 14581, '2. Valoración de tratamiento quirúrgico por cirugía vascular.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45741, 14581, '3. Determinación de ANA y anti-centrómero.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45742, 14581, '4. Tratamiento vasodilatador con prostaglandinas intravenosas', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45743, 14582, '1. La presencia de foco embolígeno y pulsos distales en la extremidad contralateral hace sospechar una trombosis arterial.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45744, 14582, '2. Si el paciente tiene antecedentes de claudicación y la clínica es de inicio brusco sospecharemos embolia arterial en primer lugar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45745, 14582, '3. Si la extremidad contralateral tiene todos los pulsos presentes y la clínica se inicia de forma lenta, sospecharemos una trombosis arterial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45746, 14582, '4. Si la clínica se inicia de forma brusca en un paciente con foco embolígeno sospecharemos una embolia arterial.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45747, 14582, '5. Si el paciente es portador de una derivación arterial previa sospecharemos de embolia arterial', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45748, 14583, '1. La causa más probable es de origen embolígeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45749, 14583, '2. La parálisis es un signo de aparición tardía que indica que el tratamiento revascularizador debe realizarse lo antes posible.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45750, 14583, '3. El tratamiento consiste en embolectomía arterial femoral con sonda de Fogarty.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45751, 14583, '4. En caso de parálisis rígida con anestesia profunda y ausencia de señal Doppler está indicada una arteriografía urgente', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45752, 14584, '1. Desestimar la cirugía de revascularización, por el tiempo prolongado de isquemia.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45753, 14584, '2. Aplicar calor y avisar al cirujano vascular de guardia.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45754, 14584, '3. Tratamiento quirúrgico urgente mediante tromboembolectomía.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45755, 14584, '4. Tratamiento médico urgente con prostaglandinas intravenosas', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45756, 14585, '1. Trombosis arterial recurrente.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45757, 14585, '2. Síndrome de reperfusión.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45758, 14585, '3. Necrosis muscular.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45759, 14585, '4. Neuropatía isquémica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45760, 14586, '1. La trombosis arterial se da frecuentemente en pacientes con arritmia cardíaca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45761, 14586, '2. Los pacientes con una embolia arterial refieren de forma habitual clínica de claudicación previa.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45762, 14586, '3. La embolia se trata habitualmente mediante anticoagulación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45763, 14586, '4. En la angiografía de un paciente con trombosis arterial se objetiva mayor desarrollo de circulación colateral', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45764, 14587, '1. Etosuximida.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45765, 14587, '2. Vigabatrina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45766, 14587, '3. Gabapentina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45767, 14587, '4. Levetiracetam', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45768, 14588, '1. Puede aparecer una diferencia mayor de 10 mm Hg al medir la tensión arterial entre ambos brazos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45769, 14588, '2. El estudio complementario fundamental para el diagnóstico es la arteriografía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45770, 14588, '3. Aunque es más frecuente en las razas orientales y en ciertos países de Sudamérica, se han descrito casos en todas las razas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45771, 14588, '4. El tratamiento inicial recomendado consiste en la administración de prednisona a dosis de 1 mg/kg/día.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45772, 14588, '5. La afectación de las arterias coronarias es extremadamente frecuente', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45773, 14589, '1. Acenocumarol, ajustándolo a la dosis que consiga un INR de 2.5.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45774, 14589, '2. Ácido acetilsalicílico: 300 mg al día.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45775, 14589, '3. Clopidogrel: 75 mg al día.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45776, 14589, '4. Angioplastia transluminal percutánea carotídea izquierda.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45777, 14589, '5. Endarterectomía carotídea izquierda', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45778, 14590, '1. Arteria carótida común.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45779, 14590, '2. Arteria carótida interna.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45780, 14590, '3. Arteria cerebral media.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45781, 14590, '4. Arteria cerebral anterior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45782, 14590, '5. Arteria comunicante posterior', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45783, 14591, '1. Estenosis del 50% de la luz de la arteria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45784, 14591, '2. Estenosis del 30% de la luz.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45785, 14591, '3. Estenosis del 90% de la luz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45786, 14591, '4. Estenosis del 70% de la luz.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45787, 14591, '5. Estenosis del 10% de la luz', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45788, 14592, '1. Disección de la arteria carótida interna izquierda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45789, 14592, '2. Trombosis de la arteria cerebelosa anteroinferior derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45790, 14592, '3. Trombosis de la arteria cerebelosa posteroinferior derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45791, 14592, '4. Trombosis de la arteria vertebral izquierda.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45792, 14592, '5. Trombosis de la arteria cerebelosa anteroinferior izquierda', false, 5);
