INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45794, 14593, '2. Accidente cerebrovascular agudo de territorio posterior', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45795, 14593, '3. Síndrome coronario agudo', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45796, 14593, '4. Shock hipovolémico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45797, 14593, '5. Edema agudo de pulmón secundario a flutter auricular', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45798, 14594, '1. 1', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45799, 14594, '2. 2', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45800, 14594, '3. 3', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45801, 14594, '4. 4', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45802, 14595, '1. 1.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45803, 14595, '2. 2.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45804, 14595, '3. 3.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45805, 14595, '4. 4', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45806, 14596, '1. Arteria lingual.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45807, 14596, '2. Arteria facial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45808, 14596, '3. Arteria oftálmica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45809, 14596, '4. Arteria temporal superficial', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45810, 14597, '1. Una causa probable es una embolia arterioarterial por desprendimiento de una placa carotídea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45811, 14597, '2. El ecografía-doppler de troncos supraaórticos es poco útil para el diagnóstico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45812, 14597, '3. Es necesario realizar una TC craneal para evaluar la repercusión sobre el parénquima cerebral.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45813, 14597, '4. El tratamiento quirúrgico está indicado si las pruebas de imagen revelan una estenosis carotídea >70%', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45814, 14598, '1. Aneurisma abdominal con erosión vertebral acompañante.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45815, 14598, '2. Estenosis de canal lumbar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45816, 14598, '3. Hernia de disco aguda.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45817, 14598, '4. Osteoporosis con aplastamiento vertebral.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45818, 14598, '5. Enfermedad de Paget', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45819, 14599, '1. Resección del aneurisma e injerto quirúrgico convencional.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45820, 14599, '2. Inducción de la trombosis del saco y bypass axilo-bifemoral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45821, 14599, '3. Tratamiento endovascular con implantación de endoprótesis.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45822, 14599, '4. Vigilancia del crecimiento aneurismático.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45823, 14599, '5. Cirugía por vía laparoscópica', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45824, 14600, '1. Tronco arterial celíaco.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45825, 14600, '2. Arteria sacra media.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45826, 14600, '3. Arteria diafragmática superior.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45827, 14600, '4. Arteria renal derecha.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45828, 14600, '5. Arteria gonadal derecha', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45829, 14601, '1. Ilíaca externa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45830, 14601, '2. Mesentérica inferior.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45831, 14601, '3. Ilíaca interna.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45832, 14601, '4. Mesentérica superior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45833, 14601, '5. Gastroepiploica inferior', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45834, 14602, '1. Absceso de psoas izquierdo. Realizaría tratamiento sintomático y lo mantendría en observación a la espera de analíticas y otras pruebas complementarias.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45835, 14602, '2. Aneurisma de aorta abdominal roto. Es una emergencia y la primera opción es tratamiento quirúrgico o endovascular.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45836, 14602, '3. Completaría el estudio con una ecografía abdominal para realizar el diagnóstico diferencial entre absceso de psoas y aneurisma de aorta abdominal roto.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45837, 14602, '4. Tumoración hipervascular del psoas. Realizaría resonancia magnética para una mejor caracterización', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45838, 14603, '1. Hernia complicada de pared abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45839, 14603, '2. Seroma post-quirúrgico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45840, 14603, '3. Absceso en la vaina del recto anterior izquierdo del abdomen.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45841, 14603, '4. Hematoma en la vaina del recto anterior izquierdo del abdomen', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45842, 14604, '1. Está indicada su reparación quirúrgica cuando el diámetro aneurismático supera los 5-5,5 cm de diámetro.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45843, 14604, '2. Suelen ser asintomáticos y de diagnóstico casual en el transcurso de pruebas de imagen hechas por otros motivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45844, 14604, '3. La complicación más frecuente es la trombosis aneurismática.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45845, 14604, '4. En caso de rotura está indicado el tratamiento quirúrgico urgente mediante cirugía abierta o endovascular', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45846, 14605, '1. Isquemia mesentérica aguda', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45847, 14605, '2. Isquemia mesentérica crónica', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45848, 14605, '3. Isquemia mesentéricas no oclusiva', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45849, 14605, '4. Colitis isquémica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45850, 14606, '1. Los aneurismas no disecantes asintomáticos tienen una probabilidad de rotura a los 5 años menor del 5 por ciento.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45851, 14606, '2. Las mujeres presentan aneurismas en edad superior a los hombres.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45852, 14606, '3. La mayor edad se asocia a un mayor riesgo de rotura.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45853, 14606, '4. Pueden producir disfonía.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45854, 14606, '5. El tamaño mayor se asocia a mayor posibilidad de rotura', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45855, 14607, '1. Tomografía computarizada.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45856, 14607, '2. Ecocardiografía transesofágica.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45857, 14607, '3. Ecocardiografía transtorácica.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45858, 14607, '4. Resonancia magnética.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45859, 14607, '5. Aortografía', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45860, 14608, '1. Actualmente, en nuestro medio, el diagnóstico de esta patología se establece rutinariamente mediante arteriografía percutánea.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45861, 14608, '2. La tomografía computarizada no es una buena técnica de imagen para su diagnóstico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45862, 14608, '3. Las técnicas ecocardiográficas no suelen aportar datos de interés en el diagnóstico y estudio de estas entidades nosológicas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45863, 14608, '4. Se considera disección o hematoma intramural aórtico tipo A de Stanford cuando está afectada la aorta ascendente sea cual fuese el lugar de origen de la lesión o su extensión.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45864, 14608, '5. La indicación quirúrgica de una disección aórtica es independiente de la afectación de la aorta ascendente', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45865, 14609, '1. La sustitución de la aorta aneurismática por un injerto está indicada cuando el diámetro de la aorta ascendente es mayor de 4,5 cm.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45866, 14609, '2. En pacientes con diagnóstico de enfermedad de Marfan o válvula aórtica bicúspide, se considerará el tratamiento quirúrgico cuando la aorta tenga entre 4 y 5 cm de diámetro.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45867, 14609, '3. Se considera necesario intervenir sobre la aorta torácica descendente aneurismática si su diámetro es superior a 6 cm.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45868, 14609, '4. Se recomienda sustituir la aorta aneurismática cuando, en un periodo de 1 año, se observa un incremento del diámetro del aneurisma de más de 1 cm', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45869, 14610, '1. Trombosis mural aórtica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45870, 14610, '2. Hematoma intramural aórtico.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45871, 14610, '3. Disección aórtica tipo B.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45872, 14610, '4. Úlcera penetrante aórtica.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45873, 14611, '1. Disección de aorta.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45874, 14611, '2. Rotura de aorta.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45875, 14611, '3. Hematoma intramural de aorta.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45876, 14611, '4. Úlcera aórtica arteriosclerosa penetrante', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45877, 14612, '1. Cuando se sospechan por palpación de un pulso poplíteo amplio la ecografía es la prueba diagnóstica de elección.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45878, 14612, '2. El riesgo de rotura aneurismática es alto.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45879, 14612, '3. El edema por compresión de la vena poplítea es la manifestación más frecuente.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45880, 14612, '4. Son más frecuentes en mujeres que en varones en una proporción 2:1', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45881, 14613, '1. Embolia pulmonar.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45882, 14613, '2. Traumatismo torácico con afectación de la aorta y el corazón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45883, 14613, '3. Necrosis quística de la media y síndrome de Marfan.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45884, 14613, '4. Síndrome dislipémico familiar con grave aterosclerosis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45885, 14614, '1. Está indicado el tratamiento con estatinas para estabilizar el trombo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45886, 14614, '2. Es necesaria la realización de una aortografía diagnóstica urgente.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45887, 14614, '3. En la cirugía se sustituye el segmento aneurismático por una prótesis tubular con reimplante de los troncos supraaórticos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45888, 14614, '4. Está indicado el implante de una endoprótesis torácica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45893, 14616, '1. Vena subclavia derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45894, 14616, '2. Vena yugular derecha.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45895, 14616, '3. Vena cava superior.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45896, 14616, '4. Vena basílica derecha.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45897, 14616, '5. Tronco braquiocefálico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45903, 14618, '1. La causa más frecuente es un émbolo cardiógeno.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45904, 14618, '2. La embolia suele ser distal al origen de la arteria mesentérica superior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45905, 14618, '3. La trombosis venosa es de difícil diagnóstico precoz.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45906, 14618, '4. La isquemia no oclusiva tiene el mejor pronóstico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45907, 14618, '5. La cirugía precoz ofrece la mejor oportunidad de tratamiento eficaz', false, 5);
