INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45931, 14624, '1. Anatómicamente se forma por detrás del cuello del páncreas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45932, 14624, '2. Al igual que muchas otras venas del organismo, sus paredes tienen válvulas.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45933, 14624, '3. En el hilio hepático suele estar detrás de la arteria hepática.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45934, 14624, '4. Su bifurcación presenta menos variantes anatómicas que los conductos biliares', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45935, 14625, '1. Perforación de ulcus gástrico o duodenal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45936, 14625, '2. Íleo biliar.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45937, 14625, '3. Neoplasia obstructiva de sigma con perforación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45938, 14625, '4. Isquemia mesentérica', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45939, 14626, '1. Ecografía urgente como test de cribado inicial, si es normal no son necesarios más estudios radiológicos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45940, 14626, '2. Radiografía de abdomen en bipedestación o decúbito lateral izquierdo para valorar presencia de gas ectópico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45941, 14626, '3. TC abdominopélvico con contraste intravenoso con protocolo de angio-TC por sospecha de isquemia mesentérica.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45942, 14626, '4. Arteriografía para descartar oclusión aguda de arteria mesentérica', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45943, 14627, '1. La exploración física revela frecuentemente signos de malnutrición y un soplo abdominal.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45944, 14627, '2. El tratamiento consiste en tromboembolectomía con sonda de Fogarty.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45945, 14627, '3. La ecografía Doppler (duplex) es una exploración no invasiva útil para el diagnóstico.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45946, 14627, '4. La angioplastia con stent de los troncos viscerales es una opción terapéutica con una tasa de éxito del 80 %', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45947, 14628, '1. La división del ligamento de Treitz.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45948, 14628, '2. La duodenoyeyunostomía.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45949, 14628, '3. El cambio de la posición del duodeno.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45950, 14628, '4. El bypass de la arteria mesentérica superior', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45951, 14629, '1. Lesión arteria humeral y nervio mediano.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45952, 14629, '2. Lesión nervio cubital.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45953, 14629, '3. Lesión nervio radial.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45954, 14629, '4. Lesión nervio mediano.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45955, 14629, '5. Lesión nervios radial y mediano', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45956, 14630, '1. El sangrado es probable que sea debido a la sección de la arteria cubital localizada en el margen lateral de la muñeca.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45957, 14630, '2. El sangrado es secundario a la sección accidental de la arteria humeral.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45958, 14630, '3. Posiblemente la sección de la arteria radial es la causante del sangrado pulsátil.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45959, 14630, '4. La vena cefálica, medial al tendón del músculo palmar mayor debe ser la causante del san grado. 5. La vena basílica es la estructura vascular más frecuentemente seccionada ante un paciente con esta sintomatología', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45960, 14631, '1. Arteria carótida primitiva derecha.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45961, 14631, '2. Arteria torácica interna derecha.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45962, 14631, '3. Arteria subescapular derecha.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45963, 14631, '4. Arteria tiroidea superior derecha.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45964, 14631, '5. Arteria tímica superior derecha', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45965, 14632, '1. Cuando afecta al cayado de la safena interna puede ligarse éste por debajo del trombo y evitarse así la anticoagulación.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45966, 14632, '2. La anticoagulación es obligatoria cuando se practica la extirpación del sistema superficial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45967, 14632, '3. El tratamiento quirúrgico de las varices de miembros inferiores requiere el ingreso hospitalario de los pacientes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45968, 14632, '4. El edema y las úlceras son complicaciones poco frecuentes de las varices.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45969, 14632, '5. No es bueno administrar antiinflamatorios tópicos en las varices superficiales', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45970, 14633, '1. Eco-doppler venoso de miembros inferiores.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45971, 14633, '2. Angiorresonancia de miembros inferiores.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45972, 14633, '3. Arteriografía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45973, 14633, '4. Indice tobillo-brazo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45974, 14633, '5. AngioTC', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45975, 14634, '1. Realización de actividad física con elevación del miembro superior derecho.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45976, 14634, '2. Terapia física con fisioterapia descongestiva.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45977, 14634, '3. Diuréticos para reducir edema.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45978, 14634, '4. Liposucción', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45979, 14635, '1. 1 mes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45980, 14635, '2. 2 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45981, 14635, '3. 6 meses.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45982, 14635, '4. 2 años.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45983, 14635, '5. Toda la vida', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45984, 14636, '1. Infección respiratoria.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45985, 14636, '2. Infarto de miocardio con Síndrome de Dressler.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45986, 14636, '3. Taponamiento cardíaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45987, 14636, '4. Tromboembolismo pulmonar masivo.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45988, 14636, '5. Dehiscencia de sutura con distress respiratorio', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45989, 14637, '1. En pacientes con TVP confirmada objetiva mente, recomendamos tratamiento agudo con heparina de bajo peso subcutánea o heparina no fraccionada.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45990, 14637, '2. Para pacientes con elevada sospecha clínica de trombosis, se recomienda tratamiento anticoagulante mientras se espera el resultado de las pruebas diagnósticas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45991, 14637, '3. El tratamiento con heparina se dice debe controlarse realizando TPT (tiempo parcial de tromboplastina).', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45992, 14637, '4. Se recomienda iniciar la administración de anticoagulantes orales junto con heparina en el primer día del tratamiento, e interrumpir la administración de heparina cuando el INR sea estable y superior a 2.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45993, 14637, '5. En los pacientes tratados con heparina de bajo peso es necesario hacer mediciones sistemática cas de la actividad antiXa con el fin de ajustar la dosis', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45994, 14638, '1. Vena cava superior.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45995, 14638, '2. Vena cava inferior.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45996, 14638, '3. Seno coronario.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45997, 14638, '4. Vena pulmonar derecha.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45998, 14638, '5. Venas cardiacas anteriores', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (45999, 14639, '1. En los pacientes sintomáticos, el edema y dolor son frecuentes.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46000, 14639, '2. El signo de Homanns es inespecífico.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46001, 14639, '3. La elevación en sangre del dímero-D es específico.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46002, 14639, '4. Puede confundirse con la rotura de un quiste poplíteo.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46003, 14639, '5. La dilatación de las venas superficiales puede ser otro signo de trombosis venosa', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46004, 14640, '1. Suele manifestarse a edades más precoces.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46005, 14640, '2. Suele ser causa de enfermedad tromboembólica recidivante.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46006, 14640, '3. Debe sospecharse en caso de antecedentes familiares positivos.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46007, 14640, '4. Es indicación de heparina no fraccionada.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46008, 14640, '5. Puede requerir tratamientos más prolongados', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46009, 14641, '1. Safena interna.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46010, 14641, '2. Femoral superficial.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46011, 14641, '3. Femoral común.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46012, 14641, '4. Ilíaca.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46013, 14641, '5. Peronea', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46014, 14642, '1. No es una urgencia oncológica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46015, 14642, '2. Los datos clínicos no suelen ser expresivos.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46016, 14642, '3. La radiografía simple de tórax no permite sospecharlo en la mayoría de las ocasiones.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46017, 14642, '4. El 85% de los casos se deben a la existencia de un cáncer de pulmón.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46018, 14642, '5. No responde al tratamiento con radioterapia', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46019, 14643, '1. Se debe realizar un estudio complejo para llegar a un diagnóstico inicial, pudiendo descartarse de entrada la existencia de embolia de pulmón dado que se realizó tratamiento profiláctico con heparina tras la cirugía.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46020, 14643, '2. Aunque la probabilidad clínica de embolia de pulmón es baja debe realizarse una TAC de arterias pulmonares para descartarla, antes de iniciarse ningún tratamiento.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46021, 14643, '3. Debe realizarse la determinación dímero D y si es positiva iniciarse tratamiento con heparina.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46022, 14643, '4. La probabilidad clínica de embolia de pulmón es alta debiendo iniciarse tratamiento con heparina y después realizar con una TAC de arterias pulmonares para confirmar el diagnóstico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46023, 14643, '5. El paciente probablemente padece una embolia de pulmón y debe iniciar tratamiento fibrinolítico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46024, 14644, '1. Los cumarínicos tienen pocas interacciones farmacológicas.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46025, 14644, '2. El tratamiento de la trombocitopenia inducida por heparina consiste en la disminución de la dosis de heparina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46026, 14644, '3. Los cumarínicos son seguros durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46027, 14644, '4. El test más utilizado para el control de la heparina no fraccionada es el TTPA (tiempo de tromboplastina parcial activada).', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46028, 14644, '5. El fondaparinux es un nuevo anticoagulante de administración oral', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46029, 14645, '1. Heparina de bajo peso molecular solapada con dicumarínicos al menos los 5 primeros días, hasta obtener INR entre 2 y 3. Después, dicumarínicos solos.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46030, 14645, '2. Sólo heparina de bajo peso molecular mientras dure el embarazo, pasando a dicumarínicos tras el parto si es preciso prolongar el tratamiento.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46031, 14645, '3. Sólo dicumarínicos desde el principio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46032, 14645, '4. Fibrinolisis con activador tisular del plasminógeno (tPA).', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46033, 14645, '5. Los anticoagulantes están contraindicados en el embarazo. Sólo medias de compresión fuerte', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46034, 14646, '1. Angiotensina II.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46035, 14646, '2. Prostaciclina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46036, 14646, '3. Glucosaminoclucano de heparín-sulfato.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46037, 14646, '4. Trombomodulina.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46038, 14646, '5. Óxido nítrico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46039, 14647, '1. Insuficiencia renal aguda.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46040, 14647, '2. Anemia hemolítica autoinmune.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46041, 14647, '3. Trombosis venas suprahepáticas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46042, 14647, '4. Síndrome leucoeritroblástico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46043, 14647, '5. Plaquetopenia', true, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46044, 14648, '1. Dado que la gestación es un estado protrombótico, existiría alto riesgo de tromboembolia venosa por lo que se debe desaconsejar el embarazo.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46045, 14648, '2. Se debe realizar tratamiento con heparina de bajo peso molecular a dosis profilácticas en el puerperio inmediato siendo opcional realizar igual tratamiento durante el embarazo.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46046, 14648, '3. El Factor V Leiden en heterocigosis es una trombofilia de bajo riesgo y no hay necesidad de ningún tratamiento en el embarazo y puerperio.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46047, 14648, '4. Se debe aconsejar aspirina a bajas dosis durante todo el embarazo y puerperio.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46048, 14648, '5. Debe realizar tratamiento con fármacos antivitamina K (Acenocumarol) durante el embarazo', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46049, 14649, '1. Pautar morfina, furosemida y dopamina y vigilar evolución.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46050, 14649, '2. Se debe solicitar determinación de dímero D para confirmar o descartar el diagnóstico de embolia de pulmón.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46051, 14649, '3. Hay alta sospecha de embolia de pulmón y se debe inicar tratamiento con heparina de bajo peso molecular sin realizar más estudios.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46052, 14649, '4. Existe alta sospecha de embolia de pulmón masiva y se debe realizar angioTC para confirmarla y valorar tratamiento fibrinolítico.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46053, 14649, '5. Se debe solicitar determinación de NTproBNP y Troponinas y conocer el resultado antes de realizar un nuevo procedimiento diagnóstico', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46054, 14650, '1. Dímero D.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46055, 14650, '2. Resonancia magnética.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46056, 14650, '3. Flebografía.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46057, 14650, '4. Ecografía doppler venosa.', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46058, 14650, '5. TAC helicoidal', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46059, 14651, '1. Dabigatran.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46060, 14651, '2. Apixaban.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46061, 14651, '3. Ribaroxaban.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46062, 14651, '4. Acenocumarol.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46063, 14651, '5. Clopidogrel', false, 5);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46064, 14652, '1. Se trata de la resistencia del factor V a la acción de la proteína S.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46065, 14652, '2. Es un trastorno adquirido que se asocia a la presencia de anticuerpos anticardiolipina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46066, 14652, '3. Su presencia ocasiona una prolongación del tiempo de tromboplastina parcial.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46067, 14652, '4. Junto con la mutación de la protrombina constituye la predisposición trombótica de base genética más frecuente en nuestro medio', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46068, 14653, '1. Plexos venosos de los músculos sóleos.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46069, 14653, '2. Sector femoral en el muslo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46070, 14653, '3. Sector iliaco.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46071, 14653, '4. Vena cava inferior', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46072, 14654, '1. Debe aconsejarse tratamiento profiláctico con heparina de bajo peso molecular durante el embarazo y hasta 6 semanas posparto.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46073, 14654, '2. Debe aconsejarse tratamiento profiláctico con aspirina durante todo el embarazo.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46074, 14654, '3. Debe aconsejarse realizar profilaxis con acenocumarol durante todo el embarazo.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46075, 14654, '4. Dado que el estudio de trombofilia fue negativo solo se precisa realizar profilaxis de trombosis venosa con medias compresivas para miembros inferiores', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46076, 14655, '1. Ingreso hospitalario y tratamiento antibiótico por vía intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46077, 14655, '2. Biopsia de la zona mamelonada.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46078, 14655, '3. Realizar curas con pomadas enzimáticas desbridantes.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46079, 14655, '4. Cobertura de la úlcera con injerto de piel', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46080, 14656, '1. Heparina sódica en perfusión intravenosa.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46081, 14656, '2. Tromboendarectomía.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46082, 14656, '3. Fibrinolisis sistémica con rt - P A (alteplase) 100 mg intravenoso.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46083, 14656, '4. Filtro en vena cava inferior.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46084, 14657, '1. Dada la potencial gravedad de la enfermedad tromboembólica venosa y tratándose de una paciente joven hay que asegurarse que no tiene nada mediante la realización de un ecodoppler.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46085, 14657, '2. La paciente tiene una probabilidad previa baja en base a la historia y los hallazgos en la exploración, por lo que lo más adecuado es realizar un a determinación de dímeros D, que, de ser negativos, descartarían la presencia de una trombosis venosa sin requerir pruebas adicionales.', true, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46086, 14657, '3. Al no estar inmovilizada la probabilidad clínica de presentar una trombosis es muy baja, así que no requiere estudios adicionales.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46087, 14657, '4. En todos los pacientes en los que se sospeche una trombosis venosa aguda hay que realizar de forma urgente una determinación de dímeros-D para el diagnóstico.', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46088, 14658, '1. Solicitar angioTC de arterias pulmonares por sospecha de tromboembolismo pulmonar.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46089, 14658, '2. Iniciar tratamiento antibiótico por sospecha de neumonía sin signos de complicación y control radiológico en 4-6 semanas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46090, 14658, '3. Derivarle a consulta especializada por sospecha radiológica de carcinoma de pulmón.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46091, 14658, '4. Solicitar radiografía en decúbito lateral derecho por sospecha de derrame pleural encapsulado previo a toracocentesis', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46092, 14659, '1. Hipopotasemia extrema.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46093, 14659, '2. Trastornos gastrointestinales con diarrea abundante y deshidratación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46094, 14659, '3. Alcalosis metabólica por toxicidad tubular renal.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46095, 14659, '4. Trombopenia grave acompañada de fenómenos trombóticos venosos o arteriales', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46096, 14660, '1. El eco-Doppler color es de gran valor como primera prueba diagnóstica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46097, 14660, '2. Debe realizarse una radiografía simple de tórax para detectar anomalías óseas.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46098, 14660, '3. La angio-TC permite el diagnóstico de confirmación.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46099, 14660, '4. Debe realizarse una flebografía para confirmar la presencia de trombosis venosa axilosubclavia', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46100, 14661, '1. Heparina de bajo peso molecular.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46101, 14661, '2. Rivaroxaban.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46102, 14661, '3. Acenocumarol.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46103, 14661, '4. Filtro de vena cava inferior', true, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46104, 14662, '1. Púrpura trombótica trombocitopénica.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46105, 14662, '2. Coagulación intravascular diseminada.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46106, 14662, '3. Trombopenia inducida por heparina.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46107, 14662, '4. Síndrome hemolítico urémico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46108, 14663, '1. Dímero D.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46109, 14663, '2. Proteínas en orina.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46110, 14663, '3. NT-proBNP.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46111, 14663, '4. Test de Coombs', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46112, 14664, '1. La paciente presenta una linfangitis, que se tratará mediante pauta de amoxicilinaclavulánico durante 10 días.', false, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46113, 14664, '2. La paciente tiene un lipedema, que se tratará con actividad física de bajo impacto con el objetivo de mejorar la circulación.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46114, 14664, '3. La paciente presenta un linfedema, que se tratará mediante prenda de presoterapia a medida y drenaje linfático manual.', true, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46115, 14664, '4. La paciente presenta una sospecha de trombosis venosa profunda en la extremidad, por lo que solicitaremos un estudio de imagen con doppler vascular para confirmar el diagnóstico', false, 4);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46116, 14665, '1. Tras la sospecha clínica, el diagnóstico suele realizarse mediante ecografía doppler.', true, 1);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46117, 14665, '2. Los pacientes con factores de riesgo o trombosis venosas de repetición suelen precisar anticoagulación durante 12 meses.', false, 2);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46118, 14665, '3. Por norma general, la anticoagulación se suele mantener durante 3 semanas.', false, 3);
INSERT INTO public.respuestas OVERRIDING SYSTEM VALUE VALUES (46119, 14665, '4. La tas de recidiva es del 60%', false, 4);
